# ---------------------------------------------------------------- subprocess

# Two scripts whose module name doesn't follow the s/-/_/ pattern of the
# console-script name in pyproject.toml. Everything else uses the default
# `taxjson-foo-bar` → `taxjson_foo_bar` mapping.
_MODULE_OVERRIDES = {
    "taxjson-to-base-curr": "to_base_curr",
    "taxjson-fill-crypto": "fill_crypto_prices",
}


def _cmd(name: str) -> List[str]:
    """Build the invocation for one of the taxjson sub-tools. Runs the
    module `taxjson.bin.<module>` so the wrapper works whether or not
    the console scripts are on PATH; built by lib/dispatch.py
    python_module_argv, never a plain `python -m` that imports a
    planted json.py from the folder it runs in (backlog TJ-0632).
    dispatch.run_cmd runs it in process."""
    from taxjson.lib.dispatch import python_module_argv
    module = _MODULE_OVERRIDES.get(name, name.replace("-", "_"))
    return python_module_argv(f"taxjson.bin.{module}")


def _self_cmd(root: Path, *args: str) -> List[str]:
    """`tjs -C ROOT ARGS` as a tool command for dispatch.run_cmd (a
    command relaying another one's --json: instalments and amt the
    estimate, close-year the carryover ledger, watch harvest)."""
    return _cmd("taxjson-run") + ["-C", str(root), *args]


def run_to_file(cmd: List[str], out_path: Path, *, capture_diag: bool = True,
                interactive: bool = False) -> None:
    """Run a sub-tool, writing stdout to out_path.

    stderr is normally captured, never echoed live — the console stays
    clean. When capture_diag is set, stderr is persisted to an
    `<out_path>.diag` sidecar that the .sum report's DIAGNOSTICS section
    folds in. On a non-zero exit the stderr is surfaced so a real failure
    isn't hidden behind the wrapper's own traceback.

    stdin is /dev/null for every stage so a sub-tool can never block the
    pipeline waiting on input it will never get.

    `interactive=True` is for the one stage that legitimately prompts —
    taxjson-corp-actions' election questions. It lets stderr (the prompt)
    and stdin (your answer) pass through to the terminal while stdout still
    goes to the file. At a non-TTY (CI/cron) the tool falls back to its own
    'needs an election' error, which surfaces here as a normal failure.
    """
    from taxjson.lib.dispatch import run_cmd
    out_path.parent.mkdir(parents=True, exist_ok=True)
    if out_path.is_dir():
        # one line, not an IsADirectoryError at the rename (A2-0795)
        _die_input(_work_path_problem(out_path))
    # Write to a .part sidecar and rename into place only on success. A failed
    # (or Ctrl-C'd, e.g. at the corp-actions election prompt) stage must never
    # leave a truncated output file: its fresh mtime would make needs_rebuild
    # treat the corrupt file as valid and feed it to downstream stages. On
    # failure the previous good output (if any) survives with its old mtime,
    # so the next run correctly rebuilds the stage.
    # The .part is created fresh (never through a symlink planted at its
    # name) and the rename replaces a symlink at out_path instead of
    # writing through it (lib/safe_write; security review M1).
    from taxjson.lib.safe_write import atomic_open
    if interactive:
        # The prompt owns stderr, so no fresh .diag is captured —
        # but a STALE one from a prior non-interactive run of this
        # stage would keep polluting the .sum DIAGNOSTICS banner
        # until hand-deleted from work/ (KNOWN_ISSUES). Clear it.
        out_path.with_name(out_path.name + ".diag").unlink(
            missing_ok=True)
        with atomic_open(out_path, binary=True) as f:
            result = run_cmd(cmd, stdout=f,      # stderr+stdin keep TTY
                             interactive=True)
            if result.returncode != 0:
                raise subprocess.CalledProcessError(result.returncode, cmd)
        return
    from taxjson.lib.cli_diag import NO_SPACE_FIX, is_no_space, no_space_text
    try:
        with atomic_open(out_path) as f:
            result = run_cmd(cmd, stdout=f)
            stderr_text = result.stderr or ""
            if capture_diag:
                diag_path = out_path.with_name(out_path.name + ".diag")
                # (a directory in its place: one line, A2-0795)
                if stderr_text:
                    _write_work_stamp(diag_path, stderr_text)
                else:
                    _drop_work_file(diag_path)
            if result.returncode != 0:
                if stderr_text:
                    _echo_stage_stderr(_stage_text_shown(stderr_text, cmd,
                                                         out_path))
                err = subprocess.CalledProcessError(result.returncode, cmd,
                                                    stderr=stderr_text)
                err.out_path = out_path
                raise err
    except OSError as e:
        if not is_no_space(e):
            raise
        # The stage's output could not be finished (flushed, synced,
        # renamed into place): a full disk. Said naming the work/ file,
        # then the run's "stopped at <stage> for account <acct>" line —
        # it was a bare "[Errno 28] ..." with no file or stage (backlog
        # TJ-0106). The previous output is kept (lib/safe_write).
        what = no_space_text(e, _work_shown(out_path))
        _say("error", what, NO_SPACE_FIX[:1].upper() + NO_SPACE_FIX[1:]
             + ".", prog=_PROG)
        raise subprocess.CalledProcessError(
            2, cmd, stderr=f"{_PROG}: error: {what}") from None


def _work_shown(out_path: Path) -> str:
    """A stage's output file as the run's messages name it: work/<name>
    (the stages write into the project's work/ folder)."""
    p = Path(out_path)
    return f"{p.parent.name}/{p.name}" if p.parent.name else str(p)


def _stage_text_shown(text: str, cmd, out_path: Optional[Path] = None
                      ) -> str:
    """A failed stage's captured stderr as the console shows it: each
    input file the stage was given (inputs/<account>/<file>, passed by
    its absolute path) named as the run names inputs — the absolute
    path pushed the headline under a bare "Error:" (backlog TJ-0123);
    a write to its stdout a full disk refused names the work/ file the
    run redirects it to, `out_path` (TJ-0106). The .diag keeps the
    captured bytes."""
    if not text:
        return text
    for a in (str(c) for c in (cmd or [])):
        p = Path(a)
        if (p.is_absolute() and len(p.parts) > 3
                and p.parent.parent.name == "inputs" and a in text):
            text = text.replace(a, f"inputs/{p.parent.name}/{p.name}")
    if out_path is not None:
        text = text.replace("cannot write the output: ",
                            f"cannot write {_work_shown(out_path)}: ")
    return text


# Matches the per-file count lines `taxjson-brokerage` prints to
# stderr (e.g. `  margin_2025.csv: 142 tax objects`). Used by
# stage_account to echo the counts into the wrapper's console output
# so a keen eye can spot a 0-object parse of a non-empty file before
# downstream stages silently propagate the empty data.
_PARSE_COUNT_RE = re.compile(r'^\s+.+: \d+ tax objects\b')
# taxjson-brokerage's zero-row warning (captured in the parse .diag).
_ZERO_TX_RE = re.compile(r'^warning: (.+?) parsed to 0 transactions\b')


def _load_holdings_summary(toml_path: Path) -> Dict[str, Tuple[float, float]]:
    """Parse a holdings.toml into `{symbol: (qty, total_cost)}`. Used
    by `print_holdings_diff` to compare snapshots. Returns an empty
    dict for missing files or when no TOML reader is available."""
    if tomllib is None or not toml_path.exists():
        return {}
    try:
        with toml_path.open('rb') as f:
            doc = tomllib.load(f)
    except (tomllib.TOMLDecodeError, OSError, UnicodeDecodeError):
        return {}
    # A damaged snapshot (it is the previous run's own report, used
    # only for the 'what moved' lines) reads as none: `holding = "x"`
    # or a quantity "abc" tracebacked `run` (re-audit A2-0792).
    rows = doc.get('holding', [])
    if not isinstance(rows, list):
        return {}
    out: Dict[str, Tuple[float, float]] = {}
    for h in rows:
        if not isinstance(h, dict):
            continue
        sym = h.get('symbol')
        if not sym or not isinstance(sym, str):
            continue
        if h.get('asset_type') == 'crypto' and '.' in sym:
            # A coin by its bare name: the venue suffix (BTC.KR, backlog
            # TJ-0418) is not a move, nor is its arrival in the file.
            sym = sym.rsplit('.', 1)[0]
        try:
            out[sym] = (
                float(h.get('quantity', 0.0)),
                float(h.get('total_cost', 0.0)),
            )
        except (TypeError, ValueError):
            continue
    return out


# Alias: tests and older callers import `_fmt_qty` from here.
from taxjson.lib.report_model import fmt_qty6 as _fmt_qty  # noqa: E402


def maybe_print_holdings_diff(prev_path: Path, curr_path: Path,
                              account: str = "") -> None:
    """Print the holdings diff if a baseline snapshot exists; silent
    otherwise (so first runs don't emit a confusing "all positions are
    new" block). Encapsulated so the first-run-silent rule is testable
    in isolation from `stage_account`."""
    if not prev_path.exists():
        return
    print_holdings_diff(
        _load_holdings_summary(prev_path),
        _load_holdings_summary(curr_path),
        account=account,
    )


def write_holdings_toml(name: str, export_cmd: List[str], cache: Path,
                        reports_dir: Path) -> None:
    """reports/<name>_holdings.toml from `export_cmd` (a taxjson-export
    --holdings-toml command), then the quantities that moved since the
    last run's file."""
    holdings_toml = reports_dir / f"{name}_holdings.toml"
    # Snapshot the existing holdings.toml so the post-export diff
    # has a baseline. First-run / no-prior-snapshot cases produce
    # no diff (correct behaviour — there's nothing to compare to).
    prev_holdings = cache / f"{name}_holdings_prev.toml"
    if holdings_toml.exists():
        # (a fresh file: never written through a symlink at the
        # snapshot's name — security review M1)
        from taxjson.lib.safe_write import write_atomic
        write_atomic(prev_holdings, holdings_toml.read_bytes())
    elif prev_holdings.exists():
        # Stale snapshot from a prior run whose output was wiped;
        # discard so we don't diff against an out-of-date baseline.
        prev_holdings.unlink()
    run_to_file(export_cmd, holdings_toml, capture_diag=False)
    _wrote(holdings_toml, reports_dir.parent, "holdings")
    # Surface quantity changes vs the prior run so the user can
    # sanity-check trades at a glance (e.g. "I didn't expect SAMPLG
    # to move — did I import the wrong file?"). Silent on the
    # first run (no baseline) and silent when nothing changed.
    maybe_print_holdings_diff(prev_holdings, holdings_toml, name)


def fill_moved_holdings(names: Iterable[str],
                        outputs: Dict[str, Dict[str, Any]], cache: Path,
                        reports_dir: Path) -> None:
    """After the passes across accounts: write reports/<name>_holdings.toml
    again for each account in them whose file has a holding with no cost
    in its own books (`cost_unknown = true`: units moved in from another
    of your accounts), with the figure the passes have for it
    (work/<name>_gains_wash.json, `tjs list`'s; taxjson-export
    --blended-gains, backlog TJ-0598). stage_account wrote the file and
    said its changes since the last run; this changes no quantity."""
    for name in names:
        cmd = (outputs.get(name) or {}).get("holdings_cmd")
        holdings = reports_dir / f"{name}_holdings.toml"
        wash = cache / f"{name}_gains_wash.json"
        if not cmd or not wash.is_file() or not holdings.is_file():
            continue
        try:
            if "cost_unknown = true" not in holdings.read_text(
                    encoding="utf-8"):
                continue
        except (OSError, UnicodeDecodeError):
            continue
        try:
            run_to_file(list(cmd) + ["--blended-gains", str(wash)],
                        holdings, capture_diag=False)
        except subprocess.CalledProcessError:
            # The file stage_account wrote stays (cost_unknown).
            _say("warning", f"{name}: the holdings file keeps units moved "
                 f"in from another of your accounts at an unknown cost "
                 f"(work/{wash.name} could not be read for theirs)",
                 prog=_PROG)


def print_holdings_diff(prev: Dict[str, Tuple[float, float]],
                         curr: Dict[str, Tuple[float, float]],
                         account: str = "") -> None:
    """Emit a one-line-per-changed-symbol summary so the user can
    sanity-check what moved since the last run. Quiet when nothing
    changed (no news is good news; the standard `→ holdings.toml`
    print already confirms the file was written). The run's default
    console says it in ONE line naming the symbols (`account` first),
    the line per symbol with --details (backlog TJ-0177)."""
    all_syms = set(prev) | set(curr)
    changes: List[str] = []
    moved: List[str] = []
    qty_eps = 1e-9
    for sym in sorted(all_syms):
        p_qty, _ = prev.get(sym, (0.0, 0.0))
        c_qty, _ = curr.get(sym, (0.0, 0.0))
        if abs(p_qty - c_qty) < qty_eps:
            continue
        moved.append(sym)
        if abs(p_qty) < qty_eps and abs(c_qty) > qty_eps:
            changes.append(f"    + {sym}: {_fmt_qty(c_qty)} (new position)")
        elif abs(c_qty) < qty_eps and abs(p_qty) > qty_eps:
            changes.append(f"    - {sym}: was {_fmt_qty(p_qty)} (closed)")
        else:
            delta = c_qty - p_qty
            sign = '+' if delta > 0 else ''
            changes.append(
                f"    ~ {sym}: {_fmt_qty(p_qty)} → {_fmt_qty(c_qty)} "
                f"({sign}{_fmt_qty(delta)})"
            )
    if changes:
        from taxjson.lib.out import width as _w
        if _run_concise():
            # One line: the count and the first symbols.
            from taxjson.lib.out import show
            _DETAILS_HIDDEN[0] = True
            show([f"Info: {account + ': ' if account else ''}"
                  f"{_count_noun(len(moved), 'holding')} changed since the "
                  f"last run ("
                  + ", ".join(moved[:3])
                  + (f" +{len(moved) - 3} more" if len(moved) > 3 else "")
                  + ")"], sys.stdout)
            return
        if _w(sys.stdout) > 0:
            # The run's console: a message and its flush-left
            # continuation lines (docs/output-style.md, The run's
            # console).
            from taxjson.lib.out import show
            show([f"Info: holdings changed since the last run "
                  f"({len(changes)}):"]
                 + [line.strip() for line in changes], sys.stdout)
            return
        print(f"  holdings changes vs prior run ({len(changes)}):")
        for line in changes:
            print(line)


def _console_names(files) -> Callable[[str], str]:
    """A function giving a captured line back its real file names for
    the console: the .diag masks account-number-like parts of names
    (shown_name), the person's own terminal names each file as it is on
    disk. A masked name two of `files` share stays masked."""
    from taxjson.lib.brokerages.base import shown_name
    from taxjson.lib.out import one_line
    real: Dict[str, set] = {}
    for p in files or ():
        # Control characters escaped (one_line): a name holding a
        # newline stays one console line.
        real.setdefault(shown_name(p), set()).add(one_line(Path(p).name))
    pairs = sorted(((m, next(iter(r))) for m, r in real.items()
                    if len(r) == 1 and next(iter(r)) != m),
                   key=lambda mr: -len(mr[0]))
    if not pairs:
        return lambda line: line
    rx = re.compile("|".join(
        r"(?<![\w*])" + re.escape(m) + r"(?![\w*])" for m, _r in pairs))
    table = dict(pairs)
    return lambda line: rx.sub(lambda mm: table[mm.group(0)], line)


def echo_parse_stats(out_path: Path, files=None) -> None:
    """Re-emit per-file transaction counts and parse warnings from the
    parser's stderr (captured to `<out_path>.diag` by `run_to_file`)
    onto the wrapper's stdout. Visibility is the safety net that
    would have caught the cycle-4 Webull `_find_header` regression
    instantly instead of needing an empty cache file to surface the
    silent zero-tx output. `files`: the parsed inputs — the console
    names them as they are on disk (the .diag keeps them masked)."""
    diag_path = out_path.with_name(out_path.name + ".diag")
    if not diag_path.exists():
        return
    _real = _console_names(files)
    echoing = False
    for line in diag_path.read_text(errors="replace").splitlines():
        line = _real(line)
        if (echoing and line[:1] in (" ", "\t") and line.strip()
                and not _PARSE_COUNT_RE.match(line)):
            # An echoed warning's indented continuation (the GLOBAL line
            # under a ticker-change hint, re-audit A2-0613).
            _echo_captured(line)
            continue
        echoing = line.startswith((UNBOOKED_PREFIX, ATTENTION_PREFIX))
        if _PARSE_COUNT_RE.match(line):
            # Shown to a person: `Info: <file>: N tax objects`
            # (stage_msg.reword). Captured: the parser's own line, its
            # leading indent kept. (A file name's control characters
            # are shown escaped.)
            from taxjson.lib.out import shown, width as _w
            if _w(sys.stdout) > 0:
                _echo_captured(line)
            else:
                print(shown(line))
        elif line.startswith("warning: ") and " parsed to 0 transactions" in line:
            # Indent the warning to match per-file count nesting.
            _echo_captured(line)
        elif line.startswith(UNBOOKED_PREFIX):
            # Input rows the parser knows are real events but could not
            # book (e.g. Kraken ledger trades with no trades-export
            # fill): the tax numbers are missing them. Console, always.
            _echo_captured(line)
        elif line.startswith(ATTENTION_PREFIX):
            # Statement coverage / identity the numbers silently depend
            # on (an IB statement ending before year end, no Cash Report
            # to reconcile against). Console, always.
            _echo_captured(line)
        elif line.startswith(_codes_note_head()):
            # Questrade internal codes booked under the tickers the
            # project's other exports name (lib/symbol_codes): one note
            # per account, in place of the per-code ATTENTION lines.
            _echo_captured(line)


def _echo_tt_totals(account: str, tt: Path, out_path: Path,
                    strict: bool = False) -> None:
    """The .tt lines whose total is not qty x price +/- fee
    (lib/tt_totals, read from the .tt stage's .diag): one `Warning:`
    each on the console, naming file:line, the written total and the
    formula's; `--strict` stops on them. The file is named as the
    run's step line names it (masked: brokerages.base.shown_name), and
    the line is quoted as written (an ACQUIRED line, not the BUYSELL it
    expands to: third pre-release review, finding 9)."""
    from taxjson.lib.brokerages.base import shown_name
    from taxjson.lib.tt_totals import read_diag, source_line
    found = read_diag(out_path)
    if not found:
        return
    shown = shown_name(tt)
    for m in found:
        line_no = m.where.rsplit(":", 1)[-1]
        head, details = m.message(f"inputs/{account}/{shown}:{line_no}",
                                  source_line(tt, m.where))
        _say_once(("tt-total", account, m.where), "warning", head,
                  *details, prog=_PROG)
    if strict:
        _die(f"--strict: {account}: inputs/{account}/{shown} has "
             f"{len(found)} line(s) whose total is not qty x price +/- "
             f"fee (warning above) — aborting",
             "Fix the total, or make the line agree with it (the "
             "warning above says how).")


# convert-tt's warning for a bare symbol on an equity account's .tt line
# (taxjson_convert_tt._warn_bare_equity_symbol), as its .diag keeps it.
_TT_BARE_RE = re.compile(r"^warning: (?P<where>\S+:\d+): symbol (?P<sym>\S+) "
                         r"has no market suffix")


def _echo_tt_bare_symbols(account: str, tt_jsons: List[Path],
                          parsed: List[Path]) -> None:
    """A .tt line whose symbol has no market suffix (AAPL) while the
    account's broker rows hold the suffixed listing (AAPL.US) opens a
    separate pool: the broker's sale of AAPL.US then goes short. The
    convert-tt warning reached only the .sum; the console gets one line
    naming file:line and the listing the books hold. Read from the
    persisted .diag on every run, cached or not."""
    import json as _json
    bare = []
    for out in tt_jsons:
        for line in _diag_lines(out):
            m = _TT_BARE_RE.match(line)
            if m:
                bare.append((m["where"], m["sym"].upper()))
    if not bare:
        return
    held: Dict[str, set] = {}
    for p in parsed:
        try:
            rows = _json.loads(p.read_text(encoding="utf-8")).get(
                "transactions") or []
        except (OSError, ValueError, AttributeError):
            continue
        for t in rows:
            sym = str((t or {}).get("symbol") or "").upper()
            if "." in sym:
                held.setdefault(sym.split(".", 1)[0], set()).add(sym)
    for where, sym in bare:
        listings = sorted(held.get(sym, ()))
        if not listings:
            continue
        _say_once(("tt-bare", account, where), "warning",
                  f"inputs/{account}/{where}: {sym} has no market suffix: "
                  f"a pool of its own, apart from {' / '.join(listings)} "
                  f"in the books", prog=_PROG)


def _codes_note_head() -> str:
    from taxjson.lib.symbol_codes import NOTE_HEAD
    return NOTE_HEAD


def _echo_stage_stderr(text: str) -> None:
    """A captured stage's stderr shown on the console (a failed stage, a
    report tool's notes), each long line wrapped for the person at
    display time (lib/stage_msg.console_lines); the captured text
    itself is unchanged. A message this run already showed (another
    engine pass said it: the per-account gains, the blended pass with
    the sheltered context) is not shown again (_echo_captured once)."""
    _ECHO_SKIP[0] = False
    for line in text.splitlines():
        _echo_captured(line, indent="", file=sys.stderr, once=True)
    _ECHO_SKIP[0] = False


# A position short in the books, as an engine pass says it (lib/pipeline
# ATTENTION_SHORT): its symbol and account key the message, whichever
# pass and wording (a registered account's short is said by its own
# gains stage and again by a taxable pass that reads it as context).
_SHORT_KEY_RE = re.compile(r"(?:[\w./-]+: )?warning: ATTENTION: short: "
                           r"(?P<sym>\S+) \((?P<acct>[^()]+)\)")
# The continuation lines of a message _echo_captured left out.
_ECHO_SKIP = [False]


def _echo_key(line: str) -> Tuple[str, ...]:
    """The run-wide key of a captured message line (_SHOWN_THIS_RUN): a
    short position by (symbol, account), any other by its text without
    the program name."""
    m = _SHORT_KEY_RE.match(line)
    if m:
        return ("short", m["sym"], m["acct"])
    from taxjson.lib.pipeline import TRANSFER_WINDOW_HEAD
    if TRANSFER_WINDOW_HEAD in line:
        # The run's one transfer-window warning (_say_transfer_windows)
        # gathers every pass's items: one key for all of them.
        return ("xferwin",)
    from taxjson.lib.out import relabel
    return ("echo", relabel(line.strip(), source=False))


def _echo_captured(line: str, indent: str = "  ", file=None,
                   source: bool = True, once: bool = False) -> None:
    """Show one captured stage line (a .diag's ATTENTION / UNBOOKED line
    or its continuation) on the run's console, wrapped for the person:
    the marker first line keeps its prefix, the rest is an indented
    headline + detail (lib/stage_msg.console_lines). The .diag and the
    .sum DIAGNOSTICS keep the one line. `source=False`: the run's own
    line (its program name is not shown). Shown to a person, the run's
    console rule applies whatever `indent` and `source` say: the label
    at column 0, continuations flush-left, one blank line after a
    message of more than one line, no stage program name
    (docs/output-style.md, The run's console)."""
    from taxjson.lib.stage_msg import console_lines, is_continuation
    from taxjson.lib.out import show, width as _w
    file = sys.stdout if file is None else file
    if once:
        # An engine message is shown once per run (owner request): the
        # gains stage, the raw-holdings pass, the blended pass and a
        # failed stage's echo all say the same lines. A continuation
        # follows its message's fate. The captured .diag / .sum keep
        # every pass's lines.
        if line[:1] in (" ", "\t") and not _PARSE_COUNT_RE.match(line):
            if _ECHO_SKIP[0]:
                return
        elif line.strip():
            key = _echo_key(line)
            if key in _SHOWN_THIS_RUN:
                _ECHO_SKIP[0] = True
                return
            _SHOWN_THIS_RUN.add(key)
            _ECHO_SKIP[0] = False
    if _w(file) > 0:
        indent, source = "", False
    if _run_concise(file):
        # One line per message (Essentials first): the continuation
        # lines and the detail wait for `tjs run --details` — an
        # error keeps its detail (the fix).
        from taxjson.lib.out import relabel as _relabel
        if is_continuation(line):
            if _ECHO_LAST_ERROR[0]:
                show(console_lines(line, indent, stream=file,
                                   source=source), file, cont=True)
            else:
                _DETAILS_HIDDEN[0] = True
            return
        _ECHO_LAST_ERROR[0] = _relabel(line.strip()).startswith("Error:")
        if _ECHO_LAST_ERROR[0]:
            show(console_lines(line, indent, stream=file, source=source),
                 file)
            return
        lines = console_lines(line, indent, stream=file, source=source,
                              concise=True)
        full = console_lines(line, indent, stream=file, source=source)
        if lines != full:
            _DETAILS_HIDDEN[0] = True
        if lines:
            show(lines, file)
        return
    show(console_lines(line, indent, stream=file, source=source), file,
         cont=is_continuation(line))


def _out_wrap(text: str, indent: str = "", hang: Optional[str] = None,
              file=None) -> List[str]:
    """lib/out.wrap for the run console (stdout by default)."""
    from taxjson.lib.out import wrap
    return wrap(text, indent=indent, hang=hang,
                stream=sys.stdout if file is None else file)


def _split_msg(text: str) -> Tuple[str, ...]:
    """A one-string message as (headline, detail) — split at its first
    clause break (lib/stage_msg.split_message) — or (text,)."""
    from taxjson.lib.stage_msg import split_message
    head, rest = split_message(str(text))
    return (head, rest) if rest else (head,)


def _out_relpath(path: Path, root: Path) -> str:
    from taxjson.lib.out import relpath
    return relpath(path, root)


def _console_line_buffered() -> None:
    """stdout and stderr flushed at every line end. Read through a pipe
    (`tjs run 2>&1 | tee log`) a block-buffered stdout came out in
    chunks while stderr came out at once: a warning landed in the middle
    of an earlier stdout line, or before the step it belongs to."""
    import io as _io
    for st in (sys.stdout, sys.stderr):
        try:
            st.flush()
            st.reconfigure(line_buffering=True)
        except (AttributeError, ValueError, OSError,
                _io.UnsupportedOperation):
            pass


def _step(text: str, file=None) -> None:
    """`==> <text>`: a step the run is doing, on its console
    (docs/output-style.md, The run's console: short, plain, one verb
    form — the table there lists every step)."""
    from taxjson.lib.out import show, width, wrap
    file = sys.stdout if file is None else file
    # Shown to a person, a wrapped step continues flush-left (a blank
    # line after it, lib/out.show); captured, two spaces in.
    show(wrap("==> " + text, None, "", "  " if width(file) <= 0 else "",
              stream=file), file)


def _wrote(path: Path, root: Path, what: str = "summary") -> None:
    """`==> Writing summary reports/margin.sum`: a file the run writes,
    named relative to the project."""
    from taxjson.lib.out import relpath
    shown = relpath(path, root)
    _step(f"Writing {what} {shown}{'/' if path.is_dir() else ''}")


def _run_concise(file=None) -> bool:
    """True on `tjs run`'s console shown to a person without
    --details: each message is one line (docs/output-style.md,
    Essentials first); captured output (width 0) keeps every byte."""
    from taxjson.lib.out import width as _w
    return (_current_cmd() == "run" and not _CURRENT_DETAILS
            and _w(sys.stdout if file is None else file) > 0)


# Set when the run's console left a message's detail out (_run_concise):
# the closing lines then name `tjs run --details`.
_DETAILS_HIDDEN = [False]
# The last message _echo_captured showed was an error (its continuation
# lines are shown whole).
_ECHO_LAST_ERROR = [False]


def _say(kind: str, text: str, *details: str, prog: Optional[str] = None,
         indent: str = "", file=None, short: Optional[str] = None,
         cmd: Optional[str] = None) -> None:
    """A run-console message in the house style: `[<prog>: ]<kind>:
    <headline>` and indented `details` (stderr by default). kind: note |
    warning | attention | error. `indent` nests the captured form
    (width 0) only: shown to a person the label starts the line, its
    continuations are flush-left and a message of more than one line is
    followed by one blank line (The run's console). On the run's
    console without --details (_run_concise) a note or warning is one
    line: `short` when given, else its headline and the command its
    detail names, or `cmd` (lib/stage_msg.concise_line); an error keeps
    its detail (the fix)."""
    from taxjson.lib.stage_msg import concise_line, message_lines
    from taxjson.lib.out import label, show, width as _w
    file = sys.stderr if file is None else file
    if _w(file) > 0:
        indent = ""
    if kind != "error" and _run_concise(file):
        lab = label("warning" if kind == "attention" else kind,
                    stream=file)
        w = _w(file)
        if kind == "attention":
            from taxjson.lib.out import shown_topic
            text = shown_topic(text)
        from taxjson.lib.stage_msg import shorten_commands
        one = shorten_commands(f"{lab}{short}" if short else
                               concise_line(f"{lab}{text}", details, w,
                                            cmd=cmd), w)
        if details or short or len(one) < len(lab) + len(text):
            _DETAILS_HIDDEN[0] = True
        # One line, cut at the width; the third of a kind folded.
        from taxjson.lib.out import concise_show
        concise_show(one, file)
        return
    show(message_lines(kind, text, details, prog=prog, indent=indent,
                       stream=file), file)


# Parser warning prefix for rows that are known tax events the parser
# could NOT book. `tjs run` echoes these to the console and, under
# --strict, refuses to publish (R1-104).
UNBOOKED_PREFIX = "warning: UNBOOKED:"
# Parser warning prefix for input COVERAGE / identity problems (lib/
# brokerages/ib_extractor.ATTENTION_PREFIX): echoed to the console.
ATTENTION_PREFIX = "warning: ATTENTION:"


def echo_attention_lines(out_path: Path, prefix: str = "",
                         exclude: Optional[str] = None,
                         once: bool = False) -> None:
    """Print the ATTENTION lines of a stage's persisted .diag (only
    those whose text starts with `prefix`, none starting with `exclude`)
    on the console. `once`: an engine pass's line — shown once per run
    whichever pass says it (_echo_captured)."""
    diag_path = out_path.with_name(out_path.name + ".diag")
    try:
        lines = diag_path.read_text(errors="replace").splitlines()
    except OSError:
        return
    echoing = False
    for line in lines:
        if echoing and line[:1] in (" ", "\t") and line.strip():
            _echo_captured(line, once=once)
            continue
        echoing = (line.startswith(ATTENTION_PREFIX + " " + prefix)
                   and not (exclude and line.startswith(
                       ATTENTION_PREFIX + " " + exclude)))
        if echoing:
            _echo_captured(line, once=once)


def _diag_lines(out_path: Path) -> List[str]:
    """The lines of a stage's persisted .diag ([] when none)."""
    try:
        return out_path.with_name(out_path.name + ".diag").read_text(
            errors="replace").splitlines()
    except OSError:
        return []


def _attention_short_lines(out_path: Path) -> List[str]:
    """The `ATTENTION: short:` lines of a gains stage's persisted .diag
    (lib/pipeline.ATTENTION_SHORT)."""
    from taxjson.lib.pipeline import ATTENTION_SHORT
    diag_path = out_path.with_name(out_path.name + ".diag")
    try:
        lines = diag_path.read_text(errors="replace").splitlines()
    except OSError:
        return []
    return [ln for ln in lines if ln.startswith(ATTENTION_SHORT)]


def unbooked_lines(out_path: Path) -> List[str]:
    diag_path = out_path.with_name(out_path.name + ".diag")
    if not diag_path.exists():
        return []
    return [ln for ln in diag_path.read_text(errors="replace").splitlines()
            if ln.startswith(UNBOOKED_PREFIX)]


def attention_lines(out_path: Path) -> List[str]:
    """A stage's captured `warning: ATTENTION:` lines (its .diag)."""
    diag_path = out_path.with_name(out_path.name + ".diag")
    if not diag_path.exists():
        return []
    return [ln for ln in diag_path.read_text(errors="replace").splitlines()
            if ln.startswith(ATTENTION_PREFIX)]


_DIAG_MARKER_RE = re.compile(
    # `warning: …` (parser-layer, bare) or GNU-style `<prog>: warning: …`
    # (bin CLIs per AUDIT-2026-07-ui §1C1, e.g. `taxjson-fill-crypto: warning:`).
    # `validation:` — merge2 --validate's report header ("validation: N
    # error(s) …" + indented TX lines); FUZZ #M found hard ERRORs living
    # only in the raw .diag because this regex dropped the header.
    r"^(?:[\w./-]+:\s+)?(?:ok|warning|note|error|validation):",
    re.IGNORECASE)


# Sidecars written by the cross-account passes AFTER <acct>.sum: the
# blended pass's per-account mirror and the single-account crypto wash
# pass's stderr. They belong to <acct>_wash.sum only — read into the
# baseline <acct>.sum they were one run stale (R1-259).
_POST_PASS_DIAG_SUFFIXES = ("_blend.diag", "_cryptoblend.diag",
                            "_gains_wash.json.diag")
_DIAG_DATE_RE = re.compile(r"\b(\d{4})-(\d{2})-(\d{2})\b")
# An account's file as the messages name it: inputs/<account>/<file>
# (the .tt line locations, lib/dated_events._where; the parsers' and the
# run's own messages), or a path ending so (a stage given the absolute
# path of an input file).
_DIAG_INPUTS_RE = re.compile(r"(?<![\w.-])inputs/([^/\s`'\"]+)/")


def _diag_block_account(block: List[str], names: List[str]
                        ) -> Optional[str]:
    """The one account (of `names`) whose files a diagnostics block
    (marker line and continuations) names by their inputs/<account>/
    path, or None: none, or files of two accounts (a blend-wide
    message). Backlog TJ-0252."""
    found = {m.group(1) for ln in block
             for m in _DIAG_INPUTS_RE.finditer(ln)} & set(names)
    return next(iter(found)) if len(found) == 1 else None


def collect_diagnostics(cache: Path, account: str, *,
                        post_pass: bool = True,
                        blended: bool = False) -> str:
    """Concatenate persisted stderr diagnostics across an account's
    pipeline stages, keeping ok/warning/note/error lines — bare or
    prog-prefixed (`taxjson-fill-crypto: warning: …`) — plus their
    indented continuation lines. post_pass=False leaves out the
    cross-account passes' sidecars (_POST_PASS_DIAG_SUFFIXES).
    blended=True (the filing-basis <acct>_wash.sum of an account the
    blended s.47 pass covers) leaves out the isolated per-account gains
    pass's <acct>_gains.json.diag: the blend re-ran the engine over the
    same rows (its mirror <acct>_blend.diag carries what it said), and
    the per-account pool's notes — a s.40(3) deemed gain on a return
    of capital beyond the account's own ACB or on its empty pool — are
    not what the blended books booked (A2-0654, A2-1117).

    The engine runs over the whole history, so a year's banner used to
    ask for action on events of a LATER year (declare 2026 transfer
    legs in the 2025 report, S038-05). A note whose dates all fall
    after the tax year's 30-day superficial-loss tail is listed last,
    under its own heading."""
    out: List[str] = []
    # Sibling-prefix guard (mirrors cmd_fees_sum): the glob for account
    # 'margin' also matches 'margin_us_*.diag', so account margin's
    # DIAGNOSTICS banner absorbed the other account's errors and sent
    # the user auditing the wrong book. cache is always <root>/work, so
    # the config is one level up; on any load problem fall back to the
    # unfiltered glob (a false extra line beats a crash here).
    siblings: List[str] = []
    names: List[str] = []
    year: Optional[int] = None
    try:
        _cfg = load_config(cache.parent)
        accounts_cfg = (_cfg.get("accounts") or {})
        names = [str(a) for a in accounts_cfg]
        siblings = [a for a in accounts_cfg
                    if a != account and a.startswith(f"{account}_")]
        _y = (_cfg.get("settings") or {}).get("year")
        year = _y if isinstance(_y, int) else None
    except (Exception, SystemExit):
        pass
    blocks: List[List[str]] = []
    for diag in sorted(cache.glob(f"{account}_*.diag")):
        if any(diag.name.startswith(f"{s}_") for s in siblings):
            continue
        if not post_pass and diag.name.endswith(_POST_PASS_DIAG_SUFFIXES):
            continue
        if blended and diag.name == f"{account}_gains.json.diag":
            continue
        start = len(blocks)
        kept_prev = False
        for line in diag.read_text(errors="replace").splitlines():
            is_marker = bool(_DIAG_MARKER_RE.match(line.strip()))
            is_cont = kept_prev and line[:1].isspace() and bool(line.strip())
            if is_marker:
                blocks.append([line.rstrip()])
                kept_prev = True
            elif is_cont:
                blocks[-1].append(line.rstrip())
            else:
                kept_prev = False
        if diag.name in (f"{account}_blend.diag",
                         f"{account}_cryptoblend.diag"):
            # The blended pass's mirror is the whole blend's stderr,
            # copied into every blended account's banner: a message
            # about another account's file names that account in front
            # (backlog TJ-0252). Nothing is dropped; a blend-wide one,
            # or one about this account's own files, stays as it is.
            for b in blocks[start:]:
                who = _diag_block_account(b, names)
                if who is not None and who != account:
                    b[0] = f"[{who}] {b[0]}"
    # The gains stage and the blend stage both persist the engine's
    # stderr, so every engine line reached a _wash.sum twice (audit
    # R1-181): a block (marker line + continuations) already kept is
    # not repeated.
    seen: set = set()
    _uniq: List[List[str]] = []
    for b in blocks:
        key = "\n".join(b)
        if key in seen:
            continue
        seen.add(key)
        _uniq.append(b)
    blocks = _uniq
    later: List[List[str]] = []
    if year is not None:
        # Past the year's end AND its 30-day window (a January rebuy
        # still denies a December loss).
        cutoff = f"{year + 1}-01-30"
        now: List[List[str]] = []
        for b in blocks:
            dates = ["-".join(m) for ln in b
                     for m in _DIAG_DATE_RE.findall(ln)]
            # Errors stay where they are, whatever their dates.
            is_err = re.search(r"\b(?:error|validation):", b[0], re.I)
            (later if dates and not is_err and min(dates) > cutoff
             else now).append(b)
        blocks = now
    for b in blocks:
        out.extend(b)
    if later:
        out.append(f"-- notes about events after {year} (they do not "
                   f"affect the {year} figures; act on them in that "
                   f"year's project):")
        for b in later:
            out.extend(b)
    return "\n".join(out)


def run_capture(cmd: List[str]) -> bytes:
    from taxjson.lib.dispatch import run_cmd
    result = run_cmd(cmd, capture_output=True)
    if result.stderr:
        _echo_stage_stderr(result.stderr)
    if result.returncode != 0:
        raise subprocess.CalledProcessError(result.returncode, cmd,
                                            stderr=result.stderr)
    return (result.stdout or "").encode("utf-8")


def _exec_tool(cmd: List[str], cwd: Optional[str] = None) -> None:
    """Wrapper-command tail: run the tool (in-process, streaming live)
    and exit with its return code — replaces the historical
    `_exec_tool(cmd)`."""
    from taxjson.lib.dispatch import run_cmd
    raise SystemExit(run_cmd(cmd, cwd=cwd).returncode)


_CONFIG_PATH: Optional[Path] = None
_PACKAGE_MTIME_CACHED: Optional[float] = None


# Files in the package that are not code or data the code reads: byte
# caches, hidden files (.gitignore, .DS_Store, editor swap files),
# documentation and editor / merge leftovers.
_PKG_SKIP_SUFFIXES = (".pyc", ".pyo", ".md", ".rst", "~", ".swp", ".swo",
                      ".orig", ".rej", ".bak")


def _package_files(pkg_root: Path) -> List[Path]:
    """Every file of the installed taxjson package that decides what a
    run computes: the `.py` sources AND the shipped data they read
    (data/markets.toml — venues, index-option roots, stablecoins — and
    any other toml / json / csv / txt shipped beside the code), sorted.
    A market-data-only update left `run --fast` serving output built
    from the old data (GitHub issue #10)."""
    out = []
    for p in pkg_root.rglob("*"):
        rel = p.relative_to(pkg_root).parts
        if any(part.startswith(".") or part == "__pycache__"
               for part in rel):
            continue
        if p.name.endswith(_PKG_SKIP_SUFFIXES) or not p.is_file():
            continue
        out.append(p)
    return sorted(out)


def _package_mtime() -> float:
    """Maximum mtime across every file of the installed taxjson package
    that decides a result (`_package_files`: the `.py` sources and the
    shipped data). Used as an implicit dependency for every cached stage
    so that an upgrade / edit to any engine, parser, wrapper module or
    market-data file invalidates the cache (which only `run --fast`
    consults — the default run rebuilds everything).

    Without this, a code fix (e.g. a parser regression repair) would
    let `--fast` silently reuse pre-fix cached output until the user
    remembered to drop the flag or touch `taxjson.toml`. That was the
    failure mode that hid the cycle-4 Webull `_find_header` regression
    (back when the cache was the default).

    Result is process-cached because the package files don't change
    underneath us mid-run.
    """
    global _PACKAGE_MTIME_CACHED
    if _PACKAGE_MTIME_CACHED is not None:
        return _PACKAGE_MTIME_CACHED
    import taxjson
    pkg_root = Path(taxjson.__file__).parent
    latest = 0.0
    for p in _package_files(pkg_root):
        try:
            latest = max(latest, p.stat().st_mtime)
        except OSError:
            continue
    _PACKAGE_MTIME_CACHED = latest
    return latest


def _package_fingerprint() -> str:
    """A CONTENT fingerprint of the installed taxjson package's .py
    sources and shipped data (`_package_files`; relative path + bytes).
    The mtime key above misses a code change whose files keep an older
    mtime (cp -p, rsync -a, tar x, touch -r) and a deleted module, so
    `run --fast` served output from the old code (S039-03); `run`
    compares this with the stamp the last complete run left in work/
    and rebuilds everything on a mismatch."""
    import taxjson
    pkg_root = Path(taxjson.__file__).parent
    h = hashlib.sha256()
    for p in _package_files(pkg_root):
        try:
            data = p.read_bytes()
        except OSError:
            continue
        h.update(p.relative_to(pkg_root).as_posix().encode() + b"\0")
        h.update(hashlib.sha256(data).digest())
    return h.hexdigest()


_CODE_STAMP = ".code_fingerprint"


def _read_work_stamp(path: Path) -> Optional[str]:
    """A work/ bookkeeping file's text (sources list, input fingerprint,
    code stamp, map markers), or None when it is missing or cannot be
    read: an unreadable stamp means 'changed' and is rewritten. A
    non-UTF-8 byte in one was a UnicodeDecodeError traceback that even
    a full `tjs run` — the documented recovery — could not get past
    (re-audit A2-0795, A2-1429)."""
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _work_path_problem(path: Path) -> str:
    return (f"{path} is a directory, not a work file — work/ holds only "
            f"files `tjs run` rebuilds: delete it and re-run.")


def _write_work_stamp(path: Path, text: str) -> None:
    """Write a work/ bookkeeping file atomically; a directory (or an
    unwritable path) in its place is one line naming it (A2-1433)."""
    from taxjson.lib.cli_diag import OutputWriteError
    if path.is_dir():
        _die_input(_work_path_problem(path))
    try:
        write_text_atomic(path, text)
    except OutputWriteError as e:
        _die_input(f"{e} — work/ holds only files `tjs run` "
                   f"rebuilds: fix or delete it and re-run.")


def _drop_work_file(path: Path) -> None:
    """Remove a work/ bookkeeping file if present; a directory in its
    place is one line naming it, not an IsADirectoryError (A2-1433)."""
    if path.is_dir() and not path.is_symlink():
        _die_input(_work_path_problem(path))
    try:
        path.unlink(missing_ok=True)
    except OSError as e:
        _die_input(f"cannot remove {path}: {e.strerror or e} — delete it "
                   f"and re-run.")


def timeline_beside(gains_json: Path) -> Path:
    """The engine's cost timeline the run writes with a gains file
    (taxjson-gains --cost-timeline; lib/cost_timeline, backlog TJ-0417),
    read by `tjs list --date`: `.<gains file's stem>.timeline.json`
    beside it — dot-prefixed, so no account glob (`<account>_*.json`) or
    gains glob (`*_gains*.json`) finds it."""
    stem = gains_json.name.lstrip(".")
    if stem.endswith(".json"):
        stem = stem[:-len(".json")]
    return gains_json.with_name(f".{stem}.timeline.json")


def needs_rebuild(out: Path, *inputs: Path) -> bool:
    """Mtime-based rebuild check — consulted only by `run --fast` (the
    default run passes force=True everywhere). Cached output is stale
    when:
      - it doesn't exist, or
      - any declared input is newer than it, or
      - `taxjson.toml` is newer than it (implicit dep via _CONFIG_PATH), or
      - any `.py` or shipped data file (data/markets.toml) in the
        installed taxjson package is newer than it (implicit dep via
        `_package_mtime()`).

    The config-file dependency catches edits to year / country /
    tax_date / base_currency. The package-source dependency catches
    engine and parser fixes (an upgrade — re-running the installer — or
    a `git pull` in editable mode bumps file mtimes and invalidates the
    cache).
    Together they make `--fast` safe to reach for: when the cache
    returns a result, it's a result computed by the CURRENT code
    against the CURRENT config and inputs.
    """
    if not out.exists():
        return True
    out_mtime = out.stat().st_mtime
    for inp in inputs:
        if inp.exists() and inp.stat().st_mtime > out_mtime:
            return True
    if _CONFIG_PATH is not None and _CONFIG_PATH.exists():
        if _CONFIG_PATH.stat().st_mtime > out_mtime:
            return True
    if _package_mtime() > out_mtime:
        return True
    return False


# ---------------------------------------------------------------- config

def _project_above(root: Path, levels: int = 4) -> Optional[Path]:
    """The project a folder inside one belongs to: the nearest folder
    above `root` (up to `levels`) holding a taxjson.toml, or the latest
    year folder of the nearest one holding year folders (in the shared
    inputs/ of a multi-year project). None when there is none."""
    try:
        here = Path(root).resolve()
    except (OSError, RuntimeError):
        return None
    for up in list(here.parents)[:levels]:
        if _PL.has_config(up):
            return up
        years = _PL.year_dirs(up)
        if years:
            return years[-1][1]
    return None


def _no_project_message(root: Path, cmd: str = "") -> Tuple[str, str]:
    """(headline, fix) for a command run where there is no project:
    the folder has no taxjson.toml. The fix names the project above it
    when there is one (`cd` there or -C), else how to start one — never
    "run `tjs run` first", which fails the same way (workflow audit
    2026-10-22, item 15)."""
    import os as _os
    head = f"no taxjson.toml in {root} — not a taxjson project"
    above = _project_above(root)
    if above is not None:
        try:
            where = _os.path.relpath(str(above))
        except ValueError:
            where = str(above)
        if len(where) > len(str(above)):
            where = str(above)
        # Commands to paste: a path with a space is one argument
        # (backlog TJ-0571).
        import shlex as _shlex
        arg = _shlex.quote(where)
        run = f"`{_PROG} -C {arg} {cmd}`" if cmd else \
            f"`{_PROG} -C {arg} ...`"
        return head, f"The project is in {where}: `cd {arg}`, or {run}."
    return head, (f"`{_PROG} init --country canada|usa` creates one "
                  f"(docs/getting-started.md); to use one you have, "
                  f"`cd` into its folder or name it with -C DIR.")


def _use_project_ticker_map(root: Path) -> None:
    """Point lib/markets at the project's ticker.map. It extends the
    shipped market lists (STABLE, SPLITSHARE, INDEXOPT, SECFUT, EVENING,
    MULT, VENUE): every command and stage of this project reads the same one;
    an empty value means the project has none (a stray outer setting
    never applies). A view that soft-reads the config calls it too: its
    MULT lines size an assignment (backlog TJ-0789)."""
    from taxjson.lib.markets import ENV_TICKER_MAP
    _tm = _PL.ticker_map_path(root)
    import os as _os
    _os.environ[ENV_TICKER_MAP] = (str(_tm.resolve()) if _tm.is_file()
                                   else "")


def load_config(root: Path) -> Dict[str, Any]:
    """The project's taxjson.toml, parsed and checked: every command's
    reader. It refuses what no command may run on (a bad account name or
    type, a setting of the other country, a folder setting leaving the
    folder that holds the project — lib/project_layout) and points the
    stages at the project's ticker.map."""
    if tomllib is None:
        _die("TOML support requires Python 3.11+ or `pip install tomli`")
    path = root / "taxjson.toml"
    if not path.exists():
        _die(*_no_project_message(root, _current_cmd()))
    # First: a project made for a newer taxjson is refused before any
    # other check reads it with this version's rules (lib/requires).
    _refuse_newer_config(path)
    _refuse_unreadable_project_inputs(root)
    text = _read_config_text(path)
    try:
        cfg = tomllib.loads(text)
        # Account names build filesystem paths (inputs/<name>,
        # work/<name>_*) and sub-tool argv (--account <name>): a
        # "../x" name wrote artifacts OUTSIDE the project and a
        # "-x" name was parsed as a flag (2026-09 security audit).
        # Checked HERE, not in validate_config, because every
        # command (not just `run`) derives paths from the names.
        for _n in (cfg.get("accounts") or {}):
            if not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_.-]*",
                                str(_n)):
                from taxjson.lib.config_check import invalid_account_name
                _die(invalid_account_name(_n))
            if str(_n).upper() == "COMBINED":
                # reports/wash_radar_COMBINED.* is the cross-account
                # radar: an account of that name had its own radar
                # replaced by it (S038-10).
                _die(f"[accounts.{_n}]: the name COMBINED is "
                     f"reserved for the cross-account wash radar — "
                     f"rename the account (and its inputs/{_n}/ "
                     f"folder).")
    except Exception as e:
        _die(_toml_problem(path, e), _TOML_FIX)
    _refuse_outside_dir_links(root, cfg.get("accounts") or {})
    _refuse_bad_account_types(cfg)
    _normalize_settings(cfg)
    _refuse_folder_settings(root, cfg)
    _use_project_ticker_map(root)
    import os as _os
    # The project itself, for the stages whose input files may sit in a
    # folder shared by every year (`inputs_dir`): the IB parse reads the
    # project's .tt RENAME lines and ticker.map from it, never from the
    # folder above the inputs (lib/project_layout.project_of_input).
    _os.environ[_PL.ENV_PROJECT_ROOT] = str(Path(root).resolve())
    return cfg


def _refuse_newer_config(path: Path, where: str = "this project"
                         ) -> Optional[Dict[str, Any]]:
    """Exit 2 when taxjson.toml at `path` records a requires_taxjson
    newer than this taxjson (or one that is not ">=X.Y.Z"):
    lib/requires. The parsed file; None when it cannot be read or
    parsed (left to the reader, which says why)."""
    from taxjson.lib import requires as _REQ
    try:
        cfg = tomllib.loads(path.read_bytes().decode("utf-8-sig"))
    except Exception:                                   # noqa: BLE001
        return None
    why = _REQ.problem(cfg.get("settings"), where)
    if why:
        _die_input(why)
    return cfg


def _refuse_newer_projects(args: argparse.Namespace) -> None:
    """Every command, before anything else: the project in -C (and, for
    the commands that work on the folder holding the years, or from a
    folder with no taxjson.toml, every year folder beside it) must not
    need a newer taxjson (lib/requires)."""
    if args.cmd in ("help", "tax-logic") + _RELEASE_CMDS:
        return
    root = Path((getattr(args, "path", None) if args.cmd == "init"
                 else None) or args.dir)
    if not root.is_dir():
        return
    own = root / _PL.CONFIG
    cfg = _refuse_newer_config(own) if own.is_file() else None
    if cfg is not None and args.cmd not in ("run", "init"):
        # A key this taxjson does not read is ignored: said, one line
        # each (`run` says it with its other config warnings).
        for _msg in _unknown_setting_warnings(cfg):
            _warn_config_once(_msg)
    if own.is_file() and args.cmd not in _YEARS_ROOT_CMDS | {"align"}:
        return
    top = _PL.multi_root(root)
    if top is None:
        return
    for y, d in _PL.year_dirs(top):
        if d.resolve() != root.resolve():
            _refuse_newer_config(d / _PL.CONFIG, f"{y}/")


def _refuse_folder_settings(root: Path, cfg: Dict[str, Any]) -> None:
    """[settings] inputs_dir / holdings_dir / exports_dir that leave the
    folder holding the project, and a year folder holding another
    year's project (lib/project_layout.setting_problems)."""
    probs = _PL.setting_problems(root, cfg.get("settings") or {})
    if probs:
        _die(probs[0] if len(probs) == 1 else
             "taxjson.toml:\n  " + "\n  ".join(probs))


def _read_config_text(path: Path) -> str:
    """taxjson.toml's text for tomllib. A directory or unreadable file
    tracebacked from every command (S040-03); a leading UTF-8 BOM (what
    Notepad saves) failed as "Invalid statement (at line 1, column 1)"
    with no hint (S038-04) — it is dropped, as TOML allows no BOM."""
    try:
        raw = path.read_bytes()
    except OSError as e:
        _die(f"cannot read {path}: {e.strerror or e}")
    if raw.startswith(b"\xef\xbb\xbf"):
        raw = raw[3:]
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as e:
        from taxjson.lib.cli_diag import not_utf8_headline
        _die(not_utf8_headline(_config_shown(path), e)
             + " — it is not valid TOML",
             "Save it as UTF-8 in your editor.")


# The fix under "taxjson.toml is not valid TOML: ..." (the parser names
# the line and column).
_TOML_FIX = ("Correct that line in taxjson.toml (docs/settings.md lists "
             "every key), then run the command again.")


def _toml_problem(path: Path, exc: BaseException) -> str:
    """`taxjson.toml:28: not valid TOML: <the parser's reason> (column
    42)` — the line first, so the headline stays one line."""
    text = str(exc)
    m = re.search(r"\s*\(at line (\d+), column (\d+)\)\s*$", text)
    if m:
        return (f"{_config_shown(path)}:{m[1]}: not valid TOML: "
                f"{text[:m.start()]} (column {m[2]})")
    return f"{_config_shown(path)} is not valid TOML: {text}"


def _config_shown(path: Path) -> str:
    """A taxjson.toml as a message names it: relative to the folder the
    command was run in when it is inside it (`taxjson.toml`,
    `2025/taxjson.toml`), else as given. The absolute path pushed the
    headline under a bare "Error:" (backlog TJ-0123)."""
    from taxjson.lib.out import relpath
    return relpath(path, Path.cwd())


# Commands that never date a crypto row: a crypto project without
# [settings] local_timezone still runs them (`tjs format` shows the
# key to add; `migrate` moves old files).
_ZONE_FREE_CMDS = ("format", "format-map", "migrate", "init", "help")


def _normalize_settings(cfg: Dict[str, Any]) -> None:
    """Canonical `country` (canada|usa) and a checked `tax_date` for
    EVERY config reader, not only `run`'s validate_config: check-filed,
    audit and close-year passed the raw strings to the gains engine,
    whose argparse refused "Canada"/"CA"/"Settle" — the filed-year
    drift guard went silently off and the checklist called the crash
    drift (S031-21, S031-24). A missing country, a setting or table the
    country does not own, and a base currency that is not the
    country's are refused here, for every command."""
    from taxjson.lib.config_check import settings_problems
    problems = settings_problems(cfg)
    if problems:
        # The country, its ownership of every setting (partition audit
        # R1/R2: a missing country was Canada everywhere but `run`; a
        # Canada-only key was silently ignored or honoured in a US
        # project) and the base currency: lib/config_check.
        _die(problems[0] if len(problems) == 1 else
             "taxjson.toml:\n  " + "\n  ".join(problems))
    settings = cfg["settings"]
    # The zone crypto UTC stamps are dated in (the parsers and
    # crypto-sends read TAXJSON_LOCAL_TZ): the project's setting wins
    # over the environment, so every command and stage of this project
    # dates a crypto row the same way (partition INPUTS-09); the
    # variable applies only OUTSIDE a project (re-audit A2-0165). There
    # is no default zone (CA-DATE-12 / US-DATE-11): a project with a
    # crypto account and no setting stops here, naming the key — one
    # user's zone silently dated everyone's midnight fills. `tjs
    # format` / `migrate` do not come through here.
    import os as _os
    from taxjson.lib.brokerages._crypto_common import (
        ENV_LOCAL_TZ, missing_timezone_message, timezone_typo_note)
    _tz = settings.get("local_timezone")
    if not _tz and _current_cmd() in _ZONE_FREE_CMDS:
        pass                # they only read or rewrite the config text
    elif not _tz:
        _crypto = sorted(str(n) for n, a in
                         (cfg.get("accounts") or {}).items()
                         if isinstance(a, dict) and a.get("crypto") is True)
        if _crypto:
            _die(f"[accounts.{_crypto[0]}] is a crypto account"
                 + (f" (and {len(_crypto) - 1} more)" if len(_crypto) > 1
                    else "")
                 + " but [settings] has no local_timezone"
                 # A misspelled key: this stops before the unknown-key
                 # warning that names it (backlog TJ-0034).
                 + timezone_typo_note(settings) + " — "
                 + missing_timezone_message("project")
                 # The scaffold has a crypto account whether or not the
                 # user holds any coins (new-user study).
                 + f" If you have no crypto, delete the "
                   f"[accounts.{_crypto[0]}] section from taxjson.toml "
                   f"instead.")
        # No crypto account: an outer TAXJSON_LOCAL_TZ still never dates
        # this project's rows (a crypto file in another account is
        # refused by its parser with the same message).
        _os.environ.pop(ENV_LOCAL_TZ, None)
    else:
        _os.environ[ENV_LOCAL_TZ] = _tz
    srcs = settings.get("source_currencies")
    if isinstance(srcs, list) and all(isinstance(c, str) for c in srcs):
        settings["source_currencies"] = [c.strip().upper() for c in srcs]
    # year: a typo'd 2204 / 1850 / 0 built empty books and every filing
    # total read 0 with exit 0; `true` failed minutes later inside the
    # gains stage (R1-256). Same plausible range `tjs init` enforces.
    year = settings.get("year")
    if year is not None:
        if isinstance(year, bool) or not isinstance(year, int):
            _die(f"[settings] year must be an integer tax year, "
                 f"got {year!r}")
        _max_year = date_cls.today().year + 1
        if not 1900 <= year <= _max_year:
            _die(f"[settings] year = {year} is not a plausible tax year "
                 f"(expected 1900..{_max_year})")


# Top-level tables taxjson.toml may carry. Anything else is ignored —
# which is why a misspelled [estimates] / [Estimate] / [instalment]
# silently fell back to 0 other income or no instalment schedule
# (R1-216, R1-257).
# The key lists live in lib/config_check (shared with the template).
from taxjson.lib.config_check import (  # noqa: E402
    TOP_LEVEL_TABLES as _TOP_LEVEL_TABLES,
    INSTALMENTS_KEYS as _INSTALMENTS_KEYS,
    ESTIMATE_KEYS as _ESTIMATE_KEYS,
    ACCOUNT_KEYS as _ACCOUNT_KEYS)


def _did_you_mean(key: str, valid) -> str:
    import difflib
    close = difflib.get_close_matches(str(key).lower(), list(valid), n=1)
    return f" (did you mean {close[0]!r}?)" if close else ""


def _config_table_warnings(cfg: Dict[str, Any]) -> List[str]:
    """Unknown top-level tables/keys and unknown [estimate] /
    [instalments] keys. Shared by `run` (validate_config) and by the
    commands that READ those tables (estimate, sum, instalments), which
    used to use 0 for a misspelled key with no word (S038-13)."""
    out: List[str] = []
    for key in cfg:
        if key in _TOP_LEVEL_TABLES:
            continue
        if key == "fetch" and isinstance(cfg[key], dict):
            out.append("the retired [fetch.<account>] tables are "
                       "ignored — `tjs fetch` reads `brokerage` + "
                       "`account` / `query_id` under [accounts.<name>]")
            continue
        what = ("table" if isinstance(cfg[key], dict) else "key")
        out.append(f"unknown top-level {what} "
                   f"{'[' + key + ']' if what == 'table' else repr(key)} "
                   f"is ignored{_did_you_mean(key, _TOP_LEVEL_TABLES)}")
    for table, allowed in (("instalments", _INSTALMENTS_KEYS),
                           ("estimate", _ESTIMATE_KEYS)):
        tbl = cfg.get(table)
        if not isinstance(tbl, dict):
            continue
        for key in tbl:
            if key not in allowed:
                out.append(f"unknown [{table}] key {key!r} is "
                           f"ignored{_did_you_mean(key, allowed)}")
    return out


_CONFIG_WARNED: set = set()


def _unknown_setting_warnings(cfg: Dict[str, Any]) -> List[str]:
    """One warning per [settings] key this taxjson does not read."""
    settings = cfg.get("settings")
    if not isinstance(settings, dict):
        return []
    return [f"unknown [settings] key {key!r} is ignored"
            f"{_did_you_mean(key, _SETTINGS_KEYS)}"
            for key in settings if key not in _SETTINGS_KEYS]


def _warn_config_once(msg: str) -> None:
    """`tjs <cmd>: warning: taxjson.toml: <msg>` on stderr, once per
    process."""
    if msg in _CONFIG_WARNED:
        return
    _CONFIG_WARNED.add(msg)
    emit_line(f"{_cmd_prog()}: warning: taxjson.toml: {msg}",
              file=sys.stderr)


def _warn_config_tables(root: Path) -> None:
    """Print _config_table_warnings once per process (estimate reads
    [estimate] twice; instalments reads both tables)."""
    for msg in _config_table_warnings(_soft_config(root)):
        if msg in _CONFIG_WARNED:
            continue
        _CONFIG_WARNED.add(msg)
        _cmd = _current_cmd()
        _pfx = f"tjs {_cmd}" if _cmd else "tjs"
        emit_line(f"{_pfx}: warning: taxjson.toml: {msg}", file=sys.stderr)


def _nonneg_money(value: Any, what: str) -> float:
    """A config money figure: a finite, non-negative number (a TOML
    boolean is refused — float(True) is 1.0). Dies naming `what`."""
    import math as _math
    # A TOML number only: float() also read the string "5_000" as 5000
    # and "nan" as nan (S043-05).
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        _die(f"{what} must be a number, got {value!r}")
    try:
        f = float(value)
    except (TypeError, ValueError):
        _die(f"{what} must be a number, got {value!r}")
    if not _math.isfinite(f) or f < 0:
        _die(f"{what} must be a non-negative finite number (enter it as "
             f"a positive amount), got {value!r}")
    return f


def _refuse_bad_account_types(cfg: Dict[str, Any]) -> None:
    """Die on an [accounts.*] entry whose `type` is missing or not
    exactly taxable/sheltered. Applied by EVERY config reader
    (load_config, _soft_config), not only `run`'s validate_config: the
    filing commands partition on an exact string match, so a type
    edited after the run ("Taxable") silently dropped the account from
    estimate, sum, form-export and the close-year lock (R1-268). Silent
    on a valid config."""
    from taxjson.lib.config_check import account_type_problems
    problems = account_type_problems(cfg)
    if problems:
        _die(problems[0] if len(problems) == 1
             else "\n  ".join(["invalid account types:"] + problems))


# The command currently executing (set by main's dispatch loop) so
# shared helpers' errors can say WHICH command in a chain failed.
_CURRENT_CMD = ""
# --details on the command currently executing (docs/output-style.md,
# Essentials first): shared helpers print a warning's detail lines only
# then; the default view shows its headline.
_CURRENT_DETAILS = False


class _CappedHelpFormatter(argparse.HelpFormatter):
    """Help wrapped at the house width (lib/out.width, docs/output-
    style.md): argparse wraps to the FULL terminal width, so on a wide
    monitor the option descriptions sprawl into hard-to-scan lines; the
    house width caps it at 160 columns on a terminal (120 piped) and
    still shrinks with a narrow terminal (TAXJSON_WIDTH=N sets it; 0
    keeps the piped house width)."""

    def __init__(self, prog, **kw):
        from taxjson.lib.out import WIDTH, width
        w = width()
        # A help page is always for a person: unwrapped (width 0) it
        # would be one line per option, so it keeps the house width.
        kw.setdefault("width", w if w > 0 else WIDTH)
        super().__init__(prog, **kw)


# The help page lists the subcommands by what they are for, not as one
# flat list of 55+ names (owner request). Every registered subcommand
# sits in exactly one group (tests/test_cli_polish.py); the README's
