# A LEAPS position: a LONG option BUY placed with more than
# `[settings] leaps_months` calendar months left to expiry (default 9,
# the market convention; a views-only setting — no tax figure uses it).
# The contract set is identified over FULL history (not the viewing
# window), so a sale, assignment, or expiry inside the window still
# shows even when the qualifying buy happened before it.
LEAPS_MONTHS_DEFAULT = 9


def _leaps_months(root: Path) -> int:
    """The project's LEAPS cut-off in months ([settings] leaps_months)."""
    cfg = load_config(root) if _PL.has_config(root) else {}
    v = (cfg.get("settings") or {}).get("leaps_months")
    return int(v) if v is not None else LEAPS_MONTHS_DEFAULT


def _leaps_rule(root: Path) -> str:
    """The definition the LEAPS views print."""
    return f"long option buys placed >{_leaps_months(root)} months to expiry"


def _add_months(iso_date: str, months: int) -> str:
    """ISO date `months` calendar months later, clamping the day into the
    target month (Jan 31 + 1mo -> Feb 28/29)."""
    import calendar
    from datetime import date as _date
    y, m, d = (int(x) for x in iso_date.split("-"))
    m += months
    y, m = y + (m - 1) // 12, (m - 1) % 12 + 1
    return _date(y, m, min(d, calendar.monthrange(y, m)[1])).isoformat()


def _gains_artifact_scope(files, period_token,
                          root: Optional[Path] = None
                          ) -> Tuple[Set[str], bool]:
    """(the tax years the gains files hold, whether the requested
    window lies inside them). The canonical <acct>_gains[_wash].json
    artifacts contain ONLY the config tax year's dispositions, but the
    PERIOD grammar accepts any window — `winners all` / `ccd-sum 2024`
    printed definite-looking answers silently missing every
    out-of-year row (2026-09 audit); _window_gains_files reads the
    full-history books for such a window. [settings] year differing
    from the books' year dies here (S048-14)."""
    tok = str(period_token or "").strip().lower()
    years = set()
    for p in (files or {}).values():
        try:
            y = str((_read_work_doc(p).get("summary") or {})
                    .get("year") or "")
        except (OSError, ValueError):
            continue
        if y and y != "all":
            years.add(y)
    if not years:
        return years, True
    if (tok in _TAX_YEAR_TOKENS or tok == "") and root is not None:
        # The default / tax_year window IS [settings].year: artifacts
        # built for another year cannot answer it, and "No realized
        # dispositions in tax year 2025" from a 2026 build is a false
        # statement, not an empty result (audit S048-14).
        cfg_year = str(_soft_settings(root).get("year") or "")
        if cfg_year and cfg_year not in years:
            _die(f"work/ holds the gains of tax year "
                 f"{', '.join(sorted(years))} but [settings] year is "
                 f"{cfg_year}",
                 f"Run `tjs run` to rebuild for {cfg_year} (or pass "
                 f"the year the books cover).")
    in_scope = (tok in _TAX_YEAR_TOKENS or tok == ""
                or (tok.isdigit() and tok in years))
    return years, in_scope


def _warn_gains_artifact_scope(files, period_token,
                               root: Optional[Path] = None) -> None:
    """The warning for a window outside the tax-year gains files when
    no full-history file can be built (_window_gains_files)."""
    years, in_scope = _gains_artifact_scope(files, period_token, root)
    if not in_scope:
        _view_msg("warning", f"the computed gains cover tax year "
                  f"{', '.join(sorted(years))} only — rows outside it are "
                  f"NOT in this report",
                  f"The requested window '{period_token}' may exceed that; "
                  f"`tjs gains` reads the full-history native books.")


_GAINS_ALL_SUFFIX = "_gains_all.json"


def _gains_all_file(root: Path, cache: Path, account: str,
                    settings: Dict[str, Any]) -> Optional[Path]:
    """work/<account>_gains_all.json: every disposition the account's
    books hold, from the SAME consolidated base-currency book the tax
    year's gains are computed from (<account>_base.json: ticker.map's
    TOBASE pooling, per-transaction FX) through the gains engine with
    no --year and the flags stage_account's gains stage passes, so the
    rows inside the tax year equal the filing file's. Built on demand
    for a windowed view whose window reaches outside the tax year
    (_window_gains_files), rebuilt when the base book, the config, the
    locks or the engine are newer. An account the run's cross-account
    pass blended with others is computed with them (_gains_all_blend):
    its cost pooled across them as the tax year's (TJ-0677). The
    engine's superficial-loss / wash-sale denials are in it, across
    those taxable accounts; a registered account's purchase is checked
    for the tax year only. None without a base book."""
    base_json = cache / f"{account}_base.json"
    if not base_json.is_file():
        return None
    out = cache / f"{account}{_GAINS_ALL_SUFFIX}"
    acfg = (_soft_config(root).get("accounts") or {}).get(account) or {}
    country = _country(settings)
    is_crypto = bool(acfg.get("crypto", False))
    is_taxable = acfg.get("type", "sheltered") == "taxable"
    if is_taxable:
        from taxjson.lib.report_model import wash_blend
        blend = wash_blend(cache, account)
        if blend is not None:
            return _gains_all_blend(root, cache, account, blend[0],
                                    blend[1], settings)
    cmd = _cmd("taxjson-gains") + ["--country", country,
                                  "--tax-date", _tax_date(settings)]
    cmd += _wash_flags(is_taxable, is_crypto, country)
    cmd += option_timing_flags(settings)
    cmd += income_dating_flags(settings)
    cmd += _locked_year_flags(root, settings)
    cmd += _loss_override_flags(cache)
    if is_crypto:
        cmd.append("--spot-crypto")
    from taxjson.lib.loss_overrides import state_path as _lo_state
    deps = [base_json, root / "taxjson.toml", _lo_state(cache)]
    deps += _lock_files(root, settings)
    mh = _missing_history_arg(root)
    if mh is not None:
        cmd += ["--incomplete-history", str(mh)]
        deps.append(mh)
    cmd.append(str(base_json))
    if needs_rebuild(out, *deps):
        run_to_file(cmd, out, capture_diag=False)
    return out


def _gains_all_blend(root: Path, cache: Path, account: str, tag: str,
                     members: List[str], settings: Dict[str, Any]
                     ) -> Optional[Path]:
    """work/<account>_gains_all.json for an account of the run's
    cross-account pass (report_model.wash_blend: `tag`, `members`): ONE
    gains run with no --year over the members' merged base books, with
    the flags stage_blended_wash_pass passes (but no registered-account
    book), split back per account. Built per account alone, an account's
    full history lost the cost pooled with the others' purchases (ITA
    s. 47), so `stats all` gave a sale another gain than the tax year
    (backlog TJ-0677). None when a member has no base book."""
    acfgs = _soft_config(root).get("accounts") or {}
    # taxjson.toml order, as the run's blended pass merges them
    # (CA-DATE-14 / US-DATE-13).
    names = ([n for n in acfgs if n in members]
             + [n for n in members if n not in acfgs])
    bases = [cache / f"{n}_base.json" for n in names]
    if not all(b.is_file() for b in bases):
        return None
    country = _country(settings)
    _us = country in ("us", "usa")
    combined_base = cache / f".{tag}_all_base.json"
    combined = cache / f".{tag}{_GAINS_ALL_SUFFIX}"
    cmd = _cmd("taxjson-gains") + ["--taxable", "--country", country,
                                  "--tax-date", _tax_date(settings)]
    if _us:
        cmd.append("--per-account-basis")
        if tag != "blend":
            # A US crypto blend: lots carried between the accounts, no
            # wash-sale rule (stage_blended_wash_pass no_wash).
            cmd += ["--no-wash", "--spot-crypto"]
    cmd += option_timing_flags(settings)
    cmd += income_dating_flags(settings)
    cmd += _locked_year_flags(root, settings)
    cmd += _loss_override_flags(cache)
    from taxjson.lib.loss_overrides import state_path as _lo_state
    deps = bases + [root / "taxjson.toml", _lo_state(cache)]
    deps += _lock_files(root, settings)
    mh = _missing_history_arg(root)
    if mh is not None:
        cmd += ["--incomplete-history", str(mh)]
        deps.append(mh)
    cmd.append(str(combined_base))
    if needs_rebuild(combined, *deps):
        _check_books_before_merge(bases)
        run_to_file(_cmd("taxjson-merge") + [str(b) for b in bases],
                    combined_base)
        run_to_file(cmd, combined, capture_diag=False)
    for n, b in zip(names, bases):
        out = cache / f"{n}{_GAINS_ALL_SUFFIX}"
        if needs_rebuild(out, combined, b):
            run_to_file(_cmd("taxjson-split-gains") + [
                str(combined), "--account", n, "--base", str(b)],
                out, capture_diag=False)
    return cache / f"{account}{_GAINS_ALL_SUFFIX}"


def _window_gains_files(root: Path, cache: Path, account: Optional[str],
                        args: argparse.Namespace
                        ) -> Tuple[Dict[str, Path], bool]:
    """The gains files a windowed view (stats, win-rates, winners,
    losers, ccd-sum, leaps, leaps-sum) reads: the tax year's filing
    files (resolve_gains_files: wash-adjusted when the cross-account
    pass ran) for a window inside the tax year; for one reaching
    outside it (`all`, `2y`, another year, --all-history) each
    account's full-history file (_gains_all_file), said in a note.
    Second element: whether the full-history files were read. An
    account with no base book to build from keeps its tax-year file,
    with the old warning."""
    from taxjson.lib.report_model import resolve_gains_files
    resolved = resolve_gains_files(cache, account or None)
    tok = _period_token(args)
    years, in_scope = _gains_artifact_scope(resolved, tok, root)
    if in_scope or not resolved:
        return resolved, False
    settings = _soft_settings(root)
    out: Dict[str, Path] = {}
    for acct in resolved:
        p = _gains_all_file(root, cache, acct, settings)
        if p is None:
            _warn_gains_artifact_scope(resolved, tok, root)
            return resolved, False
        out[acct] = p
    _view_msg("note", f"the window reaches outside tax year "
              f"{', '.join(sorted(years))}: read from the full-history "
              f"books",
              "Consolidated, in the base currency and across your "
              "taxable accounts as the tax year's gains are; "
              "superficial-loss / wash-sale denials among the taxable "
              "accounts only (a registered account's purchase is "
              "checked for the tax year). A view, not a filing figure.")
    return out, True


def _leaps_scope_guard(root: Path, account: Optional[str],
                       args) -> Dict[str, Path]:
    """leaps/leaps-sum read the same year-scoped gains artifacts as
    ccd-sum and winners, so they resolve them the same way: the
    full-history files for a window outside the tax year (`leaps-sum
    all` labelled 'all history' while holding one year, audit
    S048-11). The files _leaps_closed reads."""
    files, _all_history = _window_gains_files(root, root / "work", account,
                                              args)
    return files


def _leaps_contracts(root: Path, account: Optional[str],
                     label: str) -> Dict[str, float]:
    """{option_symbol: full-history net open qty} for contracts with at
    least one qualifying LEAPS entry buy in the native books. Membership
    (`sym in result`) identifies the contract set; the value gives the
    TRUE still-open quantity regardless of any viewing window."""
    from taxjson.lib.core import is_option_symbol, parse_option_expiry
    months = _leaps_months(root)
    cache = root / "work"
    if account:
        accounts = [account]
    else:
        accounts = _discover_tx_accounts(cache)
    from taxjson.lib.report_model import resolve_gains_files
    if not any(_native_tx_file(cache, a) is not None for a in accounts) \
            and not resolve_gains_files(cache, account or None):
        # "No LEAPS contracts found" (exit 0) before any run read as a
        # verdict about the books (2026-09 CLI audit B22).
        _die_input("no gains files in work/"
                   + (f" for account {account!r}" if account else "")
                   + " — run `tjs run` first",
                   "LEAPS come from the built books.")
    # An account with option gains but no native book: its LEAPS
    # entries are unknowable, and the report silently left them out with rc 0
    # (audit A2-0117; S040-00 covered an unreadable book only).
    _no_native = sorted(
        a for a, gf in resolve_gains_files(cache, account or None).items()
        if _native_tx_file(cache, a) is None
        and any(is_option_symbol(str(t.get("symbol") or ""))
                for t in (_load_json_or_die(gf).get("transactions")
                          or []) if isinstance(t, dict)))
    if _no_native:
        _die(f"no native transaction file (work/<account>_raw.json) for "
             f"account(s) {', '.join(_no_native)}, which have gains",
             "Rerun `tjs run` (this report would otherwise leave "
             "their LEAPS out).")
    leaps: set = set()
    qty_by_symbol: Dict[str, float] = {}
    # The native books carry the broker's listing (pre-TOBASE: SAMPMN...US)
    # while the gains files carry the ticker.map spelling (SAMPMN...TO);
    # without the rename a genuine LEAPS never matched a gains row and
    # vanished from both views (R1-237).
    _renames: Dict[str, str] = {}
    _tm = _PL.ticker_map_path(root)
    if _tm.exists():
        # Read as `run` reads it: an unreadable map stops the report —
        # treated as empty, a TOBASE-renamed LEAPS vanished with rc 0
        # (audit A2-0329, A2-1126).
        try:
            from taxjson.bin.taxjson_ticker_map import (load_map_file,
                                                        merge_renames)
            _renames = merge_renames(load_map_file(_tm), True)
        except Exception as e:                          # noqa: BLE001
            _die(f"could not read ticker.map: {e}",
                 "Fix it (`tjs run` refuses it too); the LEAPS report "
                 "would otherwise miss the renamed contracts.")
    from taxjson.bin.taxjson_ticker_map import map_symbol as _map_sym
    from taxjson.lib.corporate_timeline import dedupe_split_events

    def _is_opt_split(tx) -> bool:
        return (isinstance(tx, dict) and tx.get("action") == "SPLIT"
                and is_option_symbol(str(tx.get("symbol") or "")))
    _native_rows: Dict[str, Optional[list]] = {}

    def _rows_of(a: str) -> Optional[list]:
        if a not in _native_rows:
            nf = _native_tx_file(cache, a)
            _native_rows[a] = (None if nf is None else
                               [t for t in (_load_json_or_die(nf)
                                            .get("transactions") or [])
                                if isinstance(t, dict)])
        return _native_rows[a]
    # A split or rename of a series is the security's: one account of a
    # Canadian project's blended taxable pool reports it, and the gains
    # carry it into the others' contracts. Each account replays its
    # pool's option splits (one event reported twice is one), so an
    # account filter no longer loses the renamed LEAPS (backlog
    # TJ-0907).
    pool_of = _split_pool_of(root)
    _pool_splits: Dict[str, list] = {}
    _pools = {pool_of(a) for a in accounts}
    for _a in sorted(set(_discover_tx_accounts(cache)) | set(accounts)):
        if pool_of(_a) not in _pools:
            continue                 # (another pool's book is not read)
        _pool_splits.setdefault(pool_of(_a), []).extend(
            t for t in (_rows_of(_a) or []) if _is_opt_split(t))
    for acct in accounts:
        own = _rows_of(acct)
        if own is None:
            continue
        # Per-ACCOUNT running balance, rows in date order: the old
        # single cross-account dict, iterated in account-name order,
        # made "buy against a short = buy-to-close" depend on the
        # ALPHABETICAL position of the account holding the short —
        # renaming an account changed the LEAPS report (2026-09
        # audit). The open quantity too: a split applies to each
        # account's own contracts.
        acct_bal: Dict[str, float] = {}
        acct_qty: Dict[str, float] = {}
        # A contract held before the data (a .tt OPENING cost=unknown
        # line) is the position its first sale closes, as the gains
        # stage and option-yield read it: without it the sale read as
        # a write and a later real entry as its buy-back (backlog
        # TJ-0777).
        rows = sorted([t for t in own if not _is_opt_split(t)]
                      + dedupe_split_events(
                          _pool_splits.get(pool_of(acct), []))
                      + _option_openings(root, own, native=True),
                      key=lambda t: (str(t.get("date") or ""),
                                     0 if t.get("action") == "OPENING_BALANCE"
                                     else 1,
                                     str(t.get("time") or ""),
                                     0 if t.get("action") == "SPLIT" else 1))
        for tx in rows:
            if tx.get("action") == "SPLIT":
                # A rename-SPLIT of a contract (an OCC adjustment) carries
                # its lots — and its LEAPS entry — to the new symbol, as
                # the engine carries them; the renamed LEAPS vanished
                # from leaps/leaps-sum (S040-02).
                _old = tx.get("symbol") or ""
                _new = str(tx.get("symbol_new") or "").strip()
                if (is_option_symbol(_old) and _new
                        and _new.upper() != _old.upper()):
                    _r = float(tx.get("quantity") or 1.0) or 1.0
                    acct_bal[_new] = (acct_bal.get(_new, 0.0)
                                      + acct_bal.pop(_old, 0.0) * _r)
                    _mo = _map_sym(_old, _renames) if _renames else _old
                    _mn = _map_sym(_new, _renames) if _renames else _new
                    acct_qty[_mn] = (acct_qty.get(_mn, 0.0)
                                     + acct_qty.pop(_mo, 0.0) * _r)
                    if _mo in leaps:
                        leaps.add(_mn)
                continue
            if tx.get("action") not in ("BUYSELL", "ASSIGN",
                                        "OPENING_BALANCE"):
                continue
            sym = tx.get("symbol") or ""
            if not is_option_symbol(sym):
                continue
            qty = float(tx.get("quantity") or 0.0)
            prev_bal = acct_bal.get(sym, 0.0)
            acct_bal[sym] = prev_bal + qty
            msym = _map_sym(sym, _renames) if _renames else sym
            acct_qty[msym] = acct_qty.get(msym, 0.0) + qty
            if msym in leaps or tx.get("action") != "BUYSELL" or qty <= 0:
                continue                       # entry must be a LONG buy
            if prev_bal < -1e-9:
                # A BUY against THIS ACCOUNT'S short position is a
                # buy-to-CLOSE (covered-call exit), not a LEAPS entry —
                # it was double-counting the same gain in both ccd-sum
                # and leaps-sum (FUZZ #L). Only the closing portion is
                # excluded: a buy that covers AND opens long can still
                # qualify via its opening remainder.
                if qty <= -prev_bal + 1e-9:
                    continue
            expiry = parse_option_expiry(sym)
            d = tx.get("date") or ""
            if not expiry or not _ISO_DATE_RE.match(d):
                continue
            if expiry > _add_months(d, months):
                leaps.add(msym)
        for s, q in acct_qty.items():
            qty_by_symbol[s] = qty_by_symbol.get(s, 0.0) + q
    return {sym: qty_by_symbol.get(sym, 0.0) for sym in leaps}


def cmd_leaps(args: argparse.Namespace) -> None:             # `leaps` view
    """Closed LEAPS positions over the window: one row per engine
    disposition of a qualifying contract (long option buy placed more
    than [settings] leaps_months to expiry), with lot-matched
    base-currency gains."""
    root = Path(args.dir).resolve()
    keep, scope, account = _view_window(args, root)
    _files = _leaps_scope_guard(root, account, args)
    leaps = _leaps_contracts(root, account, "leaps")
    if not leaps:
        if getattr(args, "json", False):
            _json_out(_leaps_empty_doc(root, account))
            return
        print(f"No LEAPS contracts found ({_leaps_rule(root)}).")
        return
    entries, found, basis = _leaps_closed(root, account, leaps, keep,
                                          _files)
    if not found:
        _die_input("no gains files in work/ — run `tjs run` first",
                   "Closed positions come from the gains engine.")
    if not entries:
        if getattr(args, "json", False):
            _json_out(_leaps_empty_doc(root, account, basis))
            return
        print(f"No closed LEAPS positions in {scope}.")
        return
    base_cur = _base_currency(root)

    money = fmt_money               # shared report-layer formatter

    entries.sort(key=lambda ae: (ae[1].get("date") or "",
                                 ae[1].get("symbol") or ""))
    _split = _scope_split(root, [(a, e.get("gain")) for a, e in entries])
    if getattr(args, "json", False):
        _json_out({"rows": [dict(e, account=acct) for acct, e in entries],
                   "total_gain": round(sum(float(e.get("gain") or 0)
                                           for _a, e in entries), 2),
                   "taxable_gain": _split["taxable"],
                   "sheltered_gain": _split["sheltered"],
                   "currency": base_cur, "basis": basis})
        return
    out_lines = ["DATE CONTRACT QTY PROCEEDS COST GAIN DAYS_HELD"]
    total = 0.0
    for _acct, e in entries:
        gain = float(e.get("gain") or 0.0)
        total += gain
        out_lines.append(" ".join([
            e.get("date") or "?", str(e.get("symbol") or "?"),
            f"{abs(float(e.get('qty') or 0.0)):g}",
            money(float(e.get("proceeds") or 0.0)),
            money(float(e.get("cost") or 0.0)),
            money(gain), str(int(e.get("days_held") or 0))]))
    _vprint(f"CLOSED LEAPS POSITIONS — {scope} ({base_cur}; "
            f"{_leaps_rule(root)})")
    print()
    # Too wide (a long contract symbol): DAYS_HELD goes first.
    _print_report_table(out_lines, fit=True, drop=(6,), key=(0, 1))
    print(f"\nTOTAL REALIZED GAIN: {money(total)} {base_cur}")
    _print_scope_split(_split, base_cur, root)
    _vprint(f"Allowed amounts, lot-matched, basis: {basis}; a partial "
            f"close as realized; open contracts not shown.")


def _scope_split(root: Path, pairs) -> Dict[str, float]:
    """{'taxable': x, 'sheltered': y} over (account, gain) pairs, by
    the config's account types (an unknown account counts as taxable,
    the side that must never be understated). The cross-account views
    added registered-account P&L into one headline total with no
    account column (R1-182)."""
    _acfg = _soft_config(root).get("accounts") or {}
    out = {"taxable": 0.0, "sheltered": 0.0}
    for acct, gain in pairs:
        scope = ("sheltered" if (_acfg.get(acct) or {}).get("type")
                 == "sheltered" else "taxable")
        out[scope] += float(gain or 0.0)
    return {k: round(v, 2) for k, v in out.items()}


def _print_scope_split(split: Dict[str, float], base_cur: str,
                       root: Optional[Path] = None) -> None:
    if abs(split.get("sheltered", 0.0)) < 0.005:
        return
    from taxjson.lib.out import kv_lines
    money = fmt_money
    # An IRA is not "registered" (a Canadian term; audit A2-1324).
    _kind = ("retirement (IRA)" if root is not None
             and _country(_soft_settings(root)) == "usa" else "registered")
    for ln in kv_lines([
            ("TAXABLE accounts", f"{money(split['taxable'])} {base_cur}"),
            ("SHELTERED accounts", f"{money(split['sheltered'])} "
             f"{base_cur} ({_kind} — not taxable events; the return uses "
             f"the taxable figure)")], indent="  "):
        print(ln)


def _leaps_empty_doc(root: Path, account: Optional[str],
                     basis: Optional[str] = None) -> Dict[str, Any]:
    """Empty-state leaps JSON with the SAME key set as the populated
    document — machine consumers keying on `basis` broke only on the
    empty case; the taxable / sheltered totals were missing from it
    (backlog TJ-0541)."""
    if basis is None:
        from taxjson.lib.report_model import (gains_basis_label,
                                              resolve_gains_files)
        resolved = resolve_gains_files(root / "work", account or None)
        basis = gains_basis_label(resolved) if resolved else "pre-wash"
    return {"rows": [], "total_gain": 0.0, "taxable_gain": 0.0,
            "sheltered_gain": 0.0,
            "currency": _base_currency(root), "basis": basis}


def _leaps_closed(root: Path, account: Optional[str], leaps,
                  keep, files: Optional[Dict[str, Path]] = None
                  ) -> Tuple[list, bool, str]:
    """[(account, gains_entry)] for in-window dispositions of LEAPS
    contracts, from the wash-adjusted gains files (falling back to the
    plain gains files) — the lot-matched, superficial-loss-adjusted,
    BASE-currency numbers a return reports. Tainted (unknown-cost)
    dispositions are excluded, mirroring every filing-facing consumer.
    Second element: whether any gains file was found at all; third the
    resolved files' basis label ("wash-adjusted" only when the wash
    files actually exist — the resolver silently falls back to the
    pre-wash gains, and the printed claim must follow it)."""
    from taxjson.lib.report_model import (gains_basis_label,
                                          resolve_gains_files)
    cache = root / "work"
    entries: list = []
    found = False
    resolved = (files if files is not None
                else resolve_gains_files(cache, account or None))
    basis = gains_basis_label(resolved)
    tainted = 0
    for acct, path in resolved.items():
        data = _load_json_or_die(path)
        found = True
        _settle = _settle_basis(root, data)
        # Unknown-cost LEAPS closes routed to manual reporting (or
        # flagged in-line) vanished with no word, and the view said
        # "No closed LEAPS positions" (S040-06): count them.
        for e in data.get("manual_reporting_required") or []:
            d = _gains_row_date(e, keep, _settle)
            if ((e.get("symbol") or "") in leaps
                    and _ISO_DATE_RE.match(d) and keep(d)):
                tainted += 1
        for e in data.get("transactions", []):
            sym = e.get("symbol") or ""
            if sym not in leaps:
                continue
            if e.get("action") in ("DIVIDEND", "DIVIDEND_IN_LIEU"):
                continue
            if (e.get("tainted") and "gain" in e
                    and e.get("direction") != "SHORT"
                    and not e.get("grant")):
                d = _gains_row_date(e, keep, _settle)
                if _ISO_DATE_RE.match(d) and keep(d):
                    tainted += 1
                continue
            if "gain" not in e or "qty" not in e or e.get("tainted"):
                continue
            # LONG dispositions only: the write (grant record) and the
            # buy-back of a contract that qualified through a long entry
            # are covered-call legs — counted in ccd-sum, and counted a
            # second time here (R1-172).
            if e.get("direction") == "SHORT" or e.get("grant"):
                continue
            d = _gains_row_date(e, keep, _settle)
            if not _ISO_DATE_RE.match(d) or not keep(d):
                continue
            entries.append((acct, e))
    if tainted:
        _view_msg("warning", f"{tainted} LEAPS disposition(s) in this "
                  f"window have an unknown cost and need MANUAL reporting",
                  "No purchase in your files; not shown here (see "
                  "`tjs sum`).")
    return entries, found, basis


def cmd_leaps_sum(args: argparse.Namespace) -> None:
    """Realized-gain summary for closed LEAPS positions over a window
    (default: the tax year): per contract — quantity closed, proceeds,
    cost, gain, expiry — plus the total. A contract qualifies via its
    FULL-history entry buy (>leaps_months to expiry), so in-window exits of
    older entries are included."""
    from taxjson.lib.core import parse_option_expiry, parse_option_underlying
    root = Path(args.dir).resolve()
    # `leaps-sum margin` → the lone positional is an account, not a window.
    keep, scope, account = _view_window(args, root)
    _files = _leaps_scope_guard(root, account, args)
    leaps = _leaps_contracts(root, account, "leaps-sum")
    if not leaps:
        if getattr(args, "json", False):
            _json_out(_leaps_empty_doc(root, account))
            return
        print(f"No LEAPS contracts found ({_leaps_rule(root)}).")
        return
    entries, found, basis = _leaps_closed(root, account, leaps, keep,
                                          _files)
    if not found:
        _die_input("no gains files in work/ — run `tjs run` first",
                   "Gains come from the engine.")
    if not entries:
        if getattr(args, "json", False):
            _json_out(_leaps_empty_doc(root, account, basis))
            return
        print(f"No closed LEAPS positions in {scope}.")
        return
    base_cur = _base_currency(root)

    money = fmt_money               # shared report-layer formatter

    _split = _scope_split(root, [(a, e.get("gain")) for a, e in entries])
    agg: Dict[str, Dict[str, float]] = {}
    for _acct, e in entries:
        sym = str(e.get("symbol") or "?")
        rec = agg.setdefault(sym, {"qty": 0.0, "proceeds": 0.0,
                                   "cost": 0.0, "gain": 0.0})
        rec["qty"] += abs(float(e.get("qty") or 0.0))
        rec["proceeds"] += float(e.get("proceeds") or 0.0)
        rec["cost"] += float(e.get("cost") or 0.0)
        rec["gain"] += float(e.get("gain") or 0.0)
    out_lines = ["CONTRACT EXPIRY QTY_CLOSED PROCEEDS COST GAIN"]
    total = 0.0
    def sort_key(item):
        sym, _rec = item
        return (parse_option_underlying(sym) or sym,
                parse_option_expiry(sym) or "", sym)

    if getattr(args, "json", False):
        _json_out({"rows": [dict(rec, contract=sym,
                                 expiry=parse_option_expiry(sym))
                            for sym, rec in sorted(agg.items(),
                                                   key=sort_key)],
                   "total_gain": _foot(r2["gain"]
                                       for r2 in agg.values()),
                   "taxable_gain": _split["taxable"],
                   "sheltered_gain": _split["sheltered"],
                   "currency": base_cur, "basis": basis})
        return
    for sym, rec in sorted(agg.items(), key=sort_key):
        total += round(rec["gain"], 2)
        out_lines.append(" ".join([
            sym, parse_option_expiry(sym) or "?", f"{rec['qty']:g}",
            money(rec["proceeds"]), money(rec["cost"]),
            money(rec["gain"])]))
    _vprint(f"LEAPS REALIZED GAINS — {scope} ({base_cur}; "
            f"{_leaps_rule(root)})")
    _vprint(f"Allowed amounts, lot-matched, basis: {basis}; closed "
            f"portions only, no mark-to-market on open contracts.")
    # Too wide (a long contract symbol): the expiry goes first (the
    # contract symbol carries it).
    _print_report_table(out_lines, fit=True, drop=(1,))
    print(f"\nTOTAL REALIZED GAIN: {money(total)} {base_cur}")
    _print_scope_split(_split, base_cur, root)


def _earlier_grant_expiries(root: Path, cache: Path, acct: str,
                            data: Dict[str, Any], keep: Callable[[str], bool],
                            all_history: bool, splits: list
                            ) -> List[Tuple[Dict[str, Any], float, int]]:
    """[(write's gains row, contracts expired, closing records to add)]
    of the grant-timing writes in an earlier year's books whose expiry
    falls in the window `keep` of a view that reads one tax year's gains
    (`data`): that file holds neither the write nor a record of its
    expiry, so the close was counted in no single-year view (backlog
    TJ-1086). A write that file's own pass counts already is its one
    record: only the contracts are added (TJ-1308). Read from the
    full-history file, built on demand: only when the account's book
    holds a sold option of an earlier year expiring in the tax year or
    after it, in a project on grant timing."""
    import json as _json
    from taxjson.lib.core import is_option_symbol, parse_option_expiry
    from taxjson.lib.report_model import grant_write_expiries
    year = str((data.get("summary") or {}).get("year") or "")
    settings = _soft_settings(root)
    if (all_history or not re.fullmatch(r"\d{4}", year)
            or _country(settings) == "usa"
            or str(settings.get("option_premium_timing", "grant")).strip()
            .lower() != "grant"):
        return []
    start = f"{year}-01-01"
    bpath = cache / f"{acct}_base.json"
    if not bpath.is_file():
        return []
    try:
        base = _read_work_doc(bpath).get("transactions") or []
    except (OSError, ValueError):
        return []
    if not any(isinstance(t, dict)
               and t.get("action") == "BUYSELL"
               and float(t.get("quantity") or 0.0) < 0
               and str(t.get("date") or "") < start
               and is_option_symbol(str(t.get("symbol") or ""))
               and str(parse_option_expiry(str(t.get("symbol"))) or "") >= start
               for t in base):
        return []
    path = _gains_all_file(root, cache, acct, settings)
    if path is None:
        return []
    try:
        doc = _json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []
    if not isinstance(doc, dict):
        return []

    def row_key(t: Dict[str, Any]) -> Tuple[str, str, str]:
        return (str(t.get("id") or ""), str(t.get("date") or ""),
                str(t.get("symbol") or ""))
    own_txs = data.get("transactions") or []
    own = {row_key(t) for t in own_txs
           if isinstance(t, dict) and t.get("grant")}
    # What the year's own pass counts of its writes: the two passes pair
    # a buy-back with different writes when a series was written in both
    # years, so a write of the year can have expired in the full history
    # alone (backlog TJ-1256).
    own_counted = {
        row_key(own_txs[i]): q
        for i, (q, _e) in grant_write_expiries(
            own_txs, data.get("inventory") or [], year, splits).items()}
    txs = doc.get("transactions") or []
    out: List[Tuple[Dict[str, Any], float, int]] = []
    for i, (q, exp) in grant_write_expiries(
            txs, doc.get("inventory") or [], None, splits).items():
        t = txs[i]
        if not (t.get("grant") and not t.get("tainted")
                and _ISO_DATE_RE.match(exp) and keep(exp)):
            continue
        k = row_key(t)
        counted = own_counted.get(k, 0.0) if k in own else 0.0
        q -= counted
        if q > 1e-9:
            out.append((t, q, 0 if counted > 1e-9 else 1))
    return out


def cmd_ccd_sum(args: argparse.Namespace) -> None:
    """Covered-call (SHORT call) realized-gain summary over a window
    (default: the tax year): per underlying — contracts closed, premium
    collected (proceeds), buyback cost, gain — plus the total. Same
    canonical wash-adjusted gains basis as `leaps-sum`; the windowed
    query twin of the pipeline's cross-account `reports/ccd.rpt`."""
    from taxjson.lib.core import is_option_symbol, parse_option_right
    from taxjson.lib.report_model import gains_basis_label
    root = Path(args.dir).resolve()
    cache = root / "work"
    keep, scope, account = _view_window(args, root)
    resolved, _all_history = _window_gains_files(root, cache, account,
                                                 args)
    if resolved and not account:
        _warn_accounts_without_books(root, resolved, "ccd-sum",
                                     "gains file")
    if not resolved:
        if account:
            _die_input(f"no gains for account {account!r} in work/ — run "
                       f"`tjs run` first, or check the name")
        _die_input("no gains files in work/ — run `tjs run` first")
    basis = gains_basis_label(resolved)

    agg: Dict[str, Dict[str, float]] = {}
    _ccd_pairs: List[Tuple[str, float]] = []
    tainted_skipped = 0
    from taxjson.lib.ticker_map import class_share_aliases, underlying_of
    _docs = [(_a, _load_json_or_die(_f)) for _a, _f in resolved.items()]
    # The class share is found among every listing the accounts hold or
    # traded (inventory and native books), not only the year's sales: a
    # A class-share call written on held, unsold SAMPLD.B.TO shares was headed
    # SAMPLD.TO while the holdings TOML said SAMPLD.B.TO (audit A2-1115).
    _alias_syms = [t.get("symbol") for _a, _d in _docs
                   for t in (_d.get("transactions", []) or [])
                   + (_d.get("inventory", []) or [])
                   if isinstance(t, dict)]
    for _a in resolved:
        _nf = _native_tx_file(cache, _a)
        if _nf is not None:
            _alias_syms += [t.get("symbol") for t in
                            (_load_json_or_die(_nf).get("transactions")
                             or []) if isinstance(t, dict)]
    _aliases = class_share_aliases(_alias_syms)
    from taxjson.lib.report_model import grant_write_expiries
    _osplits = _option_split_rows(root, cache, [a for a, _d in _docs])
    for acct, data in _docs:
        # A write in an earlier year's books that expired in the window
        # counts its close here, with no premium (backlog TJ-1086).
        for t, _q, _rec in _earlier_grant_expiries(root, cache, acct, data,
                                                   keep, _all_history,
                                                   _osplits.get(acct, [])):
            sym = str(t.get("symbol") or "")
            if parse_option_right(sym) != "C" \
                    or t.get("direction") != "SHORT":
                continue
            rec = agg.setdefault(underlying_of(sym, _aliases),
                                 {"contracts": 0, "qty": 0.0,
                                  "proceeds": 0.0, "cost": 0.0, "gain": 0.0})
            rec["contracts"] += _rec
            rec["qty"] += _q
        # An expired grant-timing write has no closing record: the
        # WRITE stands for its close (A2-0693), dated at the expiry
        # (backlog TJ-0778), through the series' renames (TJ-0903).
        _gclose = grant_write_expiries(
            data.get("transactions") or [], data.get("inventory") or [],
            (data.get("summary") or {}).get("year"),
            _osplits.get(acct, []))
        _settle = _settle_basis(root, data)
        # Routed unknown-cost rows (manual_reporting_required) are
        # tainted too — counted, never silent (audit S040-15 sibling).
        for t in data.get("manual_reporting_required") or []:
            sym = str(t.get("symbol") or "")
            d = _gains_row_date(t, keep, _settle)
            if (is_option_symbol(sym) and parse_option_right(sym) == "C"
                    and _ISO_DATE_RE.match(d) and keep(d)):
                tainted_skipped += 1
        for _ti, t in enumerate(data.get("transactions", [])):
            sym = str(t.get("symbol") or "")
            if not is_option_symbol(sym):
                continue
            if parse_option_right(sym) != "C":
                continue
            d = _gains_row_date(t, keep, _settle)
            in_window = bool(_ISO_DATE_RE.match(d) and keep(d))
            # A grant-timing write that expired: its premium is the
            # write's (its date), its close the expiry's — an expiry in
            # the window counts there even when the write is before it
            # (backlog TJ-0778).
            _exp = _gclose[_ti][1] if (t.get("grant")
                                       and _ti in _gclose) else ""
            expired_in = bool(_exp and _ISO_DATE_RE.match(_exp)
                              and keep(_exp))
            if not in_window and not expired_in:
                continue
            if t.get("tainted"):
                # Unknown-cost rows are excluded by every filing-
                # facing consumer; counting them here fabricated
                # premium totals (REVIEW #2 sibling).
                if in_window:
                    tainted_skipped += 1
                continue
            # SHORT (sold-to-open) legs only — covered-call premium.
            # Older gains files carry no `direction`; infer it the way
            # taxjson-ccd-gains does: a short's gain is cost-vs-proceeds
            # inverted.
            cost = float(t.get("cost", 0) or 0)
            proceeds = float(t.get("proceeds", 0) or 0)
            gain = float(t.get("gain", 0) or 0)
            direction = t.get("direction")
            inferred = direction is None
            if inferred:
                # Older gains files: shorts satisfy gain == cost -
                # proceeds (fields carry the legs swapped) — same
                # heuristic taxjson-ccd-gains uses. A BREAK-EVEN row
                # satisfies both orientations; classify it LONG
                # (excluded) rather than fabricate a covered-call
                # close with invented premium/buyback totals (2026-09
                # audit).
                direction = ("SHORT"
                             if abs(gain - (cost - proceeds)) < 0.01
                             and abs(gain) >= 0.01
                             else "LONG")
            if direction != "SHORT":
                continue
            # PREMIUM/BUYBACK must satisfy gain = premium - buyback.
            # Rows with an explicit direction use the engines' signed
            # cash-flow convention (FUZZ #E: now identical in BOTH
            # engines): cost = -premium, proceeds = -buyback, so
            # gain == proceeds - cost holds direction-free. Legacy
            # inferred-short rows carry the legs swapped and positive.
            premium, buyback = ((cost, proceeds) if inferred
                                else (-cost, -proceeds))
            und = underlying_of(sym, _aliases)
            rec = agg.setdefault(und, {"contracts": 0, "qty": 0.0,
                                       "proceeds": 0.0, "cost": 0.0,
                                       "gain": 0.0})
            # A grant-timing record recognises the premium at the
            # WRITE (s.49(1)); it is not a close. CLOSES/QTY count the
            # closing records only (audit S028-07).
            if not t.get("grant"):
                rec["contracts"] += 1
                rec["qty"] += abs(float(t.get("qty") or 0.0))
            elif expired_in:
                rec["contracts"] += 1
                rec["qty"] += _gclose[_ti][0]
            if not in_window:
                continue
            _ccd_pairs.append((acct, gain))
            rec["proceeds"] += premium
            rec["cost"] += buyback
            rec["gain"] += gain

    base_cur = _base_currency(root)
    if tainted_skipped:
        _view_msg("warning", f"skipped {tainted_skipped} disposition(s) "
                  f"with an unknown cost",
                  "No purchase in your files; form-export, carryover and "
                  "leaps leave them out too.")
    if getattr(args, "json", False):
        _json_out({"rows": [dict(rec, underlying=und,
                                 contracts=int(rec["contracts"]))
                            for und, rec in sorted(agg.items())],
                   "total_gain": _foot(r["gain"] for r in agg.values()),
                   "taxable_gain": _scope_split(root, _ccd_pairs)[
                       "taxable"],
                   "sheltered_gain": _scope_split(root, _ccd_pairs)[
                       "sheltered"],
                   "tainted_skipped": tainted_skipped,
                   "currency": base_cur, "scope": scope,
                   "basis": basis})
        return
    if not agg:
        print(f"No covered-call (short call) closes in {scope}.")
        return

    money = fmt_money
    out_lines = ["UNDERLYING CLOSES QTY PREMIUM BUYBACK GAIN"]
    total = 0.0
    for und, rec in sorted(agg.items()):
        total += round(rec["gain"], 2)
        out_lines.append(" ".join([
            und, str(int(rec["contracts"])), f"{rec['qty']:g}",
            money(rec["proceeds"]), money(rec["cost"]),
            money(rec["gain"])]))
    _vprint(f"COVERED-CALL GAINS — {scope} ({base_cur}, basis: {basis})")
    _vprint("Short call legs only, allowed amounts. PREMIUM = proceeds of "
            "the sold calls; BUYBACK = cost to close (0 at expiry); "
            "CLOSES = closing records. An assignment's share gain is in "
            "the stock's rows.")
    _print_report_table(out_lines, fit=True, drop=(2, 1))
    print(f"\nTOTAL COVERED-CALL GAIN: {money(total)} {base_cur}")
    _print_scope_split(_scope_split(root, _ccd_pairs), base_cur, root)


def cmd_winners(args: argparse.Namespace) -> None:
    """`tjs winners [PERIOD] [ACCOUNT] [--top N]`: the biggest
    realized WINNERS over a window (default: the tax year), positive
    gains only, best first (`losers` is the other side)."""
    _ranked_view(args, "winners")


def cmd_losers(args: argparse.Namespace) -> None:
    """`tjs losers [PERIOD] [ACCOUNT] [--top N]`: the biggest
    realized LOSERS over a window (default: the tax year), negative
    gains only, worst first (`winners` is the other side)."""
    _ranked_view(args, "losers")


def _ranked_view(args: argparse.Namespace, side: str) -> None:
    """winners / losers: per-ticker realized gains over a window,
    canonical wash-preferred basis, option contracts grouped under
    their underlying, ranked; the text shows one side's top N (winners:
    gains above zero, best first; losers: below zero, worst first) and
    its taxable / sheltered split. --json carries every ticker ranked
    from that side, as `winners --json` always did, with the side's own
    totals beside the overall ones."""
    from taxjson.lib.report_model import gains_basis_label
    losers = side == "losers"
    top = getattr(args, "top", None)
    if top is None:
        top = 10
    elif top < 1:
        # 0 was silently rewritten to the default and negatives
        # clamped to 1 — the header then advertised a number the user
        # never asked for (REVIEW #44). A usage error: exit 2, as
        # every command's, said before any file is read (backlog
        # TJ-0157, TJ-0241).
        _die_input(f"--top must be >= 1, got {top}")
    root = Path(args.dir).resolve()
    cache = root / "work"
    keep, scope, account = _view_window(args, root)
    resolved, _all_history = _window_gains_files(root, cache, account,
                                                 args)
    if resolved and not account:
        _warn_accounts_without_books(root, resolved, side, "gains file")
    if not resolved:
        _die_input("no gains files in work/ — run `tjs run` first")
    basis = gains_basis_label(resolved)
    _INCOME = {"DIVIDEND", "DIVIDEND_IN_LIEU", "TAX", "INTEREST",
               "FEE", "DISALLOW", "ADJUST"}
    agg: Dict[str, Dict[str, Any]] = {}
    tainted_skipped = 0
    groups = _account_group_of(root)
    grp_gain = {"taxable": 0.0, "sheltered": 0.0}
    shel_accts = set()
    from taxjson.lib.ticker_map import class_share_aliases, underlying_of
    _docs = [(_a, _load_json_or_die(_f)) for _a, _f in resolved.items()]
    # Held shares (inventory) too: a covered call's class share is
    # often only held (re-audit A2-0715).
    _aliases = class_share_aliases(
        t.get("symbol") for _a, _d in _docs
        for t in (_d.get("transactions", []) or [])
        + (_d.get("inventory", []) or []) if isinstance(t, dict))
    from taxjson.lib.report_model import grant_write_expiries
    # (through the series' renames, as ccd-sum: backlog TJ-0903)
    _osplits = _option_split_rows(root, cache, [a for a, _d in _docs])

    def _ticker_rec(und: str) -> Dict[str, Any]:
        return agg.setdefault(und, {"closes": 0, "proceeds": 0.0,
                                    "cost": 0.0, "gain": 0.0,
                                    "denied": 0.0,
                                    "_grp": {"taxable": 0.0,
                                             "sheltered": 0.0},
                                    "_shel": set()})
    for _acct, data in _docs:
        _gclose = grant_write_expiries(
            data.get("transactions") or [], data.get("inventory") or [],
            (data.get("summary") or {}).get("year"),
            _osplits.get(_acct, []))
        # A write in an earlier year's books that expired in the window:
        # its close, no gain (backlog TJ-1086, TJ-1112).
        for t, _q, _rec in _earlier_grant_expiries(root, cache, _acct, data,
                                                   keep, _all_history,
                                                   _osplits.get(_acct, [])):
            _ticker_rec(underlying_of(str(t.get("symbol") or "?"),
                                      _aliases))["closes"] += _rec
        _settle = _settle_basis(root, data)
        # Pipeline files ROUTE unknown-cost rows out of transactions[]
        # into manual_reporting_required: count them too, or the
        # "nothing is silent" warning never fired on real books (audit
        # S040-15).
        for t in data.get("manual_reporting_required") or []:
            d = _gains_row_date(t, keep, _settle)
            if _ISO_DATE_RE.match(d) and keep(d):
                tainted_skipped += 1
        for _ti, t in enumerate(data.get("transactions", [])):
            if t.get("action") in _INCOME:
                continue
            d = _gains_row_date(t, keep, _settle)
            in_window = bool(_ISO_DATE_RE.match(d) and keep(d))
            # An expired grant-timing write's gain is the write's (its
            # date), its close the expiry's, as ccd-sum counts it
            # (backlog TJ-0778, TJ-1112).
            _exp = (_gclose[_ti][1] if t.get("grant") and _ti in _gclose
                    else "")
            expired_in = bool(_exp and _ISO_DATE_RE.match(_exp)
                              and keep(_exp))
            if not in_window:
                if expired_in and not t.get("tainted"):
                    _ticker_rec(underlying_of(str(t.get("symbol") or "?"),
                                              _aliases))["closes"] += 1
                continue
            if t.get("tainted"):
                # A missing-history OPENING_BALANCE basis fabricates gains — a
                # $0-cost row was ranked the portfolio's #2 winner and
                # made the total irreconcilable with form-export
                # (REVIEW #2). Excluded like every filing-facing
                # consumer, and COUNTED so nothing is silent.
                tainted_skipped += 1
                continue
            sym = str(t.get("symbol") or "?")
            und = underlying_of(sym, _aliases)
            rec = _ticker_rec(und)
            # A WRITE is not a close — unless it expired in the window,
            # when it is the only record of that close (A2-0693).
            if not t.get("grant") or expired_in:
                rec["closes"] += 1
            # Real-world orientation, as ccd-sum and form-export show
            # it: a SHORT row carries the engine's signed legs (cost =
            # -premium, proceeds = -buyback), so the columns read
            # negative and swapped (S040-14).
            if t.get("direction") == "SHORT":
                rec["proceeds"] -= float(t.get("cost") or 0.0)
                rec["cost"] -= float(t.get("proceeds") or 0.0)
            else:
                rec["proceeds"] += float(t.get("proceeds") or 0.0)
                rec["cost"] += float(t.get("cost") or 0.0)
            rec["gain"] += float(t.get("gain") or 0.0)
            # The loss the superficial-loss / wash-sale rule denied:
            # GAIN = PROCEEDS - COST + DENIED, so the row adds up
            # (backlog TJ-0120).
            rec["denied"] += float(t.get("disallowed_amount") or 0.0)
            _g = groups.get(_acct)
            if _g:
                grp_gain[_g] += float(t.get("gain") or 0.0)
                rec["_grp"][_g] += float(t.get("gain") or 0.0)
                if _g == "sheltered":
                    shel_accts.add(_acct)
                    rec["_shel"].add(_acct)
    ranked = sorted(agg.items(), key=lambda kv: (kv[1]["gain"]
                                                 if losers
                                                 else -kv[1]["gain"]))
    # One side: a winner gained, a loser lost (a ticker that nets to
    # zero is neither).
    side_rows = [(t, r) for t, r in ranked
                 if (round(r["gain"], 2) < 0 if losers
                     else round(r["gain"], 2) > 0)]
    side_grp = {"taxable": 0.0, "sheltered": 0.0}
    side_shel = set()
    for _t, r in side_rows:
        for g in side_grp:
            side_grp[g] += r["_grp"][g]
        side_shel |= r["_shel"]
    base_cur = _base_currency(root)
    if tainted_skipped:
        _view_msg("warning", f"skipped {tainted_skipped} disposition(s) "
                  f"with an unknown cost",
                  "No purchase in your files; form-export, carryover and "
                  "leaps leave them out too.")
    if getattr(args, "json", False):
        _json_out({"rows": [dict({k: v for k, v in rec.items()
                                  if not k.startswith("_")}, ticker=t,
                                 closes=int(rec["closes"]))
                            for t, rec in ranked],
                   "total_gain": _foot(r["gain"] for _t, r in ranked),
                   "total_gain_taxable": round(grp_gain["taxable"], 2),
                   "total_gain_sheltered": round(grp_gain["sheltered"], 2),
                   "sheltered_included": sorted(shel_accts),
                   "side": side,
                   "side_tickers": [t for t, _r in side_rows],
                   "side_total_gain": _foot(r["gain"]
                                            for _t, r in side_rows),
                   "side_total_gain_taxable": round(side_grp["taxable"],
                                                    2),
                   "side_total_gain_sheltered": round(
                       side_grp["sheltered"], 2),
                   "tainted_skipped": tainted_skipped,
                   "currency": base_cur, "scope": scope,
                   "basis": basis})
        return
    # One account asked for: the title and the side's total name it,
    # as the TOTAL REALIZED GAIN line does (backlog TJ-0260).
    where = f"account {account}" if account else ""
    if not ranked:
        print(f"No realized dispositions in {scope}"
              + (f" ({where})" if where else "") + ".")
        return
    word = "losers" if losers else "winners"
    other = "winners" if losers else "losers"
    money = fmt_money
    if not side_rows:
        print(f"No realized {word} in {scope} ("
              + (f"{where}, " if where else "")
              + f"basis: {basis}); the other side: tjs {other}.")
        return
    head = side_rows[:top]
    # A DENIED column only when a shown row has a denial: without one,
    # PROCEEDS - COST is the GAIN already (backlog TJ-0120).
    with_denied = any(round(rec["denied"], 2) for _t, rec in head)
    out_lines = ["TICKER CLOSES PROCEEDS COST "
                 + ("DENIED GAIN" if with_denied else "GAIN")]
    for t, rec in head:
        out_lines.append(" ".join([t, str(int(rec["closes"])),
                                   money(rec["proceeds"]),
                                   money(rec["cost"])]
                                  + ([money(rec["denied"])]
                                     if with_denied else [])
                                  + [money(rec["gain"])]))
    _vprint(f"{word.upper()} — {scope} ({base_cur}, "
            + (f"{where}, " if where else "")
            + f"{'worst' if losers else 'top'} {top})")
    _rule = ("" if not with_denied
             else "wash-sale" if _country(_soft_settings(root)) == "usa"
             else "superficial-loss")
    _vprint(f"Realized dispositions, allowed amounts, basis: {basis}; an "
            f"option under its underlying; dividends and PIL: tjs divs-sum."
            + (f" GAIN = PROCEEDS − COST + DENIED (the loss the {_rule} "
               f"rule denied)." if with_denied else ""))
    _print_report_table(out_lines, fit=True,
                        drop=(4, 2, 3) if with_denied else (2, 3))
    side_total = _foot(r["gain"] for _t, r in side_rows)
    total = _foot(r["gain"] for _t, r in ranked)
    print()
    if side_shel:
        # A registered account's gains are not taxable events; the
        # headline alone overstated a Schedule 3 gain several-fold
        # (audit S040-13). Same split and note `sum` prints.
        _vprint(f"TAXABLE: {money(side_grp['taxable'])} {base_cur}   "
                f"SHELTERED ({', '.join(sorted(side_shel))} — not "
                f"taxable events): {money(side_grp['sheltered'])} "
                f"{base_cur}")
    shown = (f"{len(head)} of {len(side_rows)} shown"
             if len(head) < len(side_rows)
             else "1 shown" if len(head) == 1
             else f"all {len(head)} shown")
    from taxjson.lib.out import kv_lines as _kvl
    for ln in _kvl([(f"{word.upper()} TOTAL",
                     f"{money(side_total)} {base_cur} ({shown}"
                     + (f", {account}" if account else "") + ")"),
                    ("TOTAL REALIZED GAIN",
                     f"{money(total)} {base_cur} ({len(ranked)} ticker(s), "
                     f"{account or 'all accounts'}; the {other}: "
                     f"tjs {other})")]):
        print(ln)


def cmd_stats(args: argparse.Namespace) -> None:
    """`tjs stats [YEAR] [ACCOUNT] [--all-history] [--json]`: win/lose
    statistics on closed trades per asset class (lib/trade_stats) —
    economic P/L in the base currency before any superficial-loss /
    wash-sale denial, the denied total on its own line. A view, never a
    filing number."""
    from taxjson.lib import trade_stats
    root = Path(args.dir).resolve()
    if args.all_history:
        if args.period and _is_period(args.period):
            _die_input("give a YEAR or --all-history, not both")
        if args.period and args.account is None:
            args.account, args.period = args.period, None
        args.period = "all"
    settings = _soft_settings(root)
    country = _country(settings)
    usa = country == "usa"
    inp = _closed_trade_inputs(args, root, "stats")
    keep, scope, account = inp["keep"], inp["scope"], inp["account"]
    groups, resolved = inp["groups"], inp["resolved"]
    res = trade_stats.compute(inp["gains"], inp["books"], keep,
                              inp["date_of"], inp["crypto"],
                              inp["in_books"], pools=inp["pools"],
                              timelines=inp["timelines"],
                              split_at_open=inp["split_at_open"],
                              fifo_books=inp["fifo_books"],
                              cover_docs=inp["cover_docs"],
                              fifo_timelines=inp["fifo_timelines"],
                              history_docs=inp["history_docs"],
                              cover_history_docs=inp["cover_history_docs"])
    base = _base_currency(root)
    sheltered = bool(account) and groups.get(account) == "sheltered"
    rule = "wash-sale" if usa else "superficial-loss"
    if getattr(args, "json", False):
        _json_out(dict(res, scope=scope, currency=base,
                       accounts=sorted(resolved),
                       sheltered=sheltered,
                       basis=f"economic P/L before any {rule} denial",
                       option_premium_timing=(
                           None if usa else
                           settings.get("option_premium_timing")
                           or "grant")))
        return
    money = fmt_money

    def _m(v):
        return "-" if v is None else money(v)

    def _row(label, st):
        wr = ("-" if st["win_rate"] is None
              else f"{st['win_rate'] * 100:.1f}%")
        pf = ("-" if st["profit_factor"] is None
              else f"{st['profit_factor']:.2f}")
        return [label, str(st["trades"]), str(st["wins"]),
                str(st["losses"]), wr, money(st["net_pl"]),
                _m(st["avg_win"]), _m(st["avg_loss"]),
                _m(st["largest_win"]), _m(st["largest_loss"]), pf]
    kind = ("retirement (IRA)" if usa else "registered")
    who = (f"account {account}" + (f" — {kind}, not taxable events"
                                   if sheltered else "")
           if account else _accounts_phrase(sorted(resolved)))
    from taxjson.lib.out import Doc
    doc = Doc(f"CLOSED-TRADE STATISTICS — {scope} ({base}; {who})")
    _det = _details(args)
    doc.para(f"Economic P/L in {base} before any {rule} denial, not a "
             f"filing number.")
    if _det:
        doc.blank()
    else:
        # The legend, before the table (docs/output-style.md).
        doc.para("WIN_RATE = wins / trades; PROFIT_FACTOR = gross wins / "
                 "gross losses.")
    # Too wide: the largest win/loss go first, then the averages (the
    # --json output keeps them all).
    doc.table(["CLASS", "TRADES", "WINS", "LOSSES", "WIN_RATE", "NET_P/L",
               "AVG_WIN", "AVG_LOSS", "LARGEST_WIN", "LARGEST_LOSS",
               "PROFIT_FACTOR"],
              [_row(cls, res["classes"][cls])
               for cls, _desc in trade_stats.CLASSES],
              foot=[_row("TOTAL", res["total"])], drop=(8, 9, 6, 7))
    doc.blank()
    doc.para(f"Denied by the {rule} rule (NOT subtracted above): "
             f"{money(res['denied_total'])} {base} over "
             f"{res['denied_count']} disposition(s).")
    # A move in kind (a registered account's withdrawal in kind) is no
    # trade: its P/L apart (backlog TJ-0629).
    _mv = res["moved_in_kind"]
    if _mv["count"]:
        doc.para(f"Moved in kind, not trades (NOT in the table): "
                 f"{money(_mv['net_pl'])} {base} of P/L over "
                 f"{_mv['count']} move(s), at the value they moved at.")
    if not _det:
        if res["tainted_skipped"]:
            doc.para(f"{res['tainted_skipped']} disposition(s) with an "
                     f"unknown cost are not counted — tjs "
                     f"find-missing-history")
        from taxjson.lib.out import details_hint as _dh
        doc.para(_dh("tjs stats --details", "how the trades are counted"))
        doc.print()
        return
    doc.section("How the trades are counted")
    doc.items([
        "WIN_RATE = wins / trades (a break-even trade is neither); "
        "PROFIT_FACTOR = gross wins / gross losses.",
        "One trade per closing disposition (a partial close is its own "
        "trade).",
        "A written option is one trade from write to close, whatever the "
        "premium timing: the premium minus the buy-back, or the premium "
        "kept at expiry or assignment."])
    if res["assigned_written_options"]:
        doc.item(f"{res['assigned_written_options']} assigned written "
                 f"option close(s): the premium counts on the option row "
                 f"and is taken out of the shares' P/L (the tax rules "
                 f"fold it into the shares' proceeds or cost).")
    if res["exercised_long_options"]:
        doc.item(f"{res['exercised_long_options']} exercised long "
                 f"option(s) are not trades: their cost carried into the "
                 f"shares.")
    if _mv["count"]:
        doc.item(f"{_mv['count']} move(s) in kind (a registered "
                 f"account's withdrawal in kind) are not trades: the "
                 f"books count each as a sale at its value, so the shares "
                 f"left keep their cost, but nothing was sold. Their P/L "
                 f"is the line under the table.")
    if res["tainted_skipped"]:
        doc.item(f"{res['tainted_skipped']} disposition(s) with an "
                 f"unknown cost (no purchase in your files) are not "
                 f"counted.")
    doc.print()


def _is_period(s: Optional[str]) -> bool:
    """True if `s` is a period token (30d/6w/3m/1y/mtd/ytd/all/YYYY/tax_year)."""
    s = (s or "").strip().lower()
    return (s in ("all", "max", "mtd", "ytd") or s in _TAX_YEAR_TOKENS
            or _YEAR_TOKEN_RE.fullmatch(s) is not None
            or re.fullmatch(r"\d+\s*[dwmy]", s) is not None)


_AMBIGUOUS_WARNED: Set[str] = set()


def _warn_period_or_account(tok: str) -> None:
    """Say, once, that a lone positional naming both a period and a
    configured account (an account called `2025` or `1y`) was read as
    the period: every account, not that one (backlog TJ-0909)."""
    if tok in _AMBIGUOUS_WARNED:
        return
    _AMBIGUOUS_WARNED.add(tok)
    _view_msg("warning", f"'{tok}' is both a period and an account name: "
              f"read as the period (every account)",
              f"For the account, give a period before it: `tjs "
              f"{_current_cmd() or 'stats'} all {tok}` (or "
              f"`tax_year {tok}`).")


def _view_positionals(items, accounts_cfg, *,
                      all_history: bool = False
                      ) -> Tuple[Optional[str], Optional[str], List[str]]:
    """(period, account, the rest upper-cased) of the free-order
    positionals of `win-rates` / `option-yield` (`QQQ 1y margin`, any
    order). An exact configured account name is an account even when
    it starts with a digit (`123abc`: it was refused as an invalid
    period, backlog TJ-0909); one that is also a period (`2025`) is the
    account when a period is given beside it (or --all-history), the
    period when an account is, the first of two such tokens the period,
    and alone the period, said in a warning. A digit-leading token with
    a dot is a listing (`1234.HK`: refused as an invalid period, backlog
    TJ-0785), unless a number stands after the dot (`1.5y`, `2.5m`: read
    as a symbol, the window fell back to the tax year: backlog TJ-1085);
    any other digit-leading non-period is a malformed period."""
    period = account = None
    rest: List[str] = []
    both: List[str] = []
    for tok in (items or []):
        t = str(tok or "").strip()
        if not t:
            continue
        is_p, is_a = _is_period(t), t in accounts_cfg
        if is_p and is_a:
            both.append(t)
        elif period is None and is_p:
            period = t
        elif account is None and is_a:
            account = t
        elif (t[:1].isdigit() and not is_p
              and ("." not in t or re.fullmatch(r"\d+\.\d+[A-Za-z]*", t))):
            _tx_period_cutoff(t)                # sys.exits: invalid period
        else:
            rest.append(t.upper())
    for i, t in enumerate(both):
        if account is None and (period is not None or all_history):
            account = t
        elif period is None and account is not None:
            period = t
        elif period is None and account is None:
            period = t
            if i == len(both) - 1:
                _warn_period_or_account(t)
        else:
            rest.append(t.upper())
    return period, account, rest


def _period_token(args: argparse.Namespace) -> Optional[str]:
    """The PERIOD positional as _view_window resolves it: None when the
    lone positional was read as an account (`winners margin`) — passing
    the raw token warned that the window 'margin' may exceed the
    artifacts' year (S048-22)."""
    period, account = args.period, args.account
    if period and account is None and not _is_period(period):
        return None
    return period


def _lone_positional(root: Path, period: Optional[str],
                     account: Optional[str]
                     ) -> Tuple[Optional[str], Optional[str]]:
    """(period, account) of the `[PERIOD] [ACCOUNT]` positionals: a lone
    one is the account when it is no period token. An exact configured
    account name is the account even when it starts with a digit
    (`stats 123abc` was refused as an invalid period; backlog TJ-0909);
    one that is also a period (`2025`) stays the period, said once; any
    other digit-leading non-period is a malformed period (exit 2)."""
    if not period or account is not None:
        return period, account
    tok = str(period).strip()
    named = tok in (_soft_config(root).get("accounts") or {})
    if named and _is_period(tok):
        _warn_period_or_account(tok)
        return period, None
    if named:
        return None, tok
    if not _is_period(period):
        if tok[:1].isdigit():
            _tx_period_cutoff(period)                # sys.exits: invalid period
        return None, period
    return period, None


def _view_window(args: argparse.Namespace, root: Path):
    """Resolve the shared optional `(period, account)` positionals of the
    query commands (events/divs/roc/leaps/trades/gains and the -sum
    roll-ups) into `(keep, scope, account)`. The lone positional is read as
    an account when it isn't a period token (a digit-leading non-token is
    validated as a window so the error names the real problem); with no
    period the scope defaults to the config tax year, else all history."""
    period, account = _lone_positional(root, args.period, args.account)
    if period:
        keep, scope = _period_keep(period, root)         # incl. `tax_year`
    else:
        year = _soft_settings(root).get("year")
        if year:
            ys = str(year)
            keep, scope = _year_keep(ys), f"tax year {year}"
        else:
            keep, scope = (lambda d: True), "all history"
    return keep, scope, account


def _tx_fee(tx: dict) -> float:
    """Total fee on a transaction. Parsers split this across `fee` and
    `commission` (Questrade uses the latter); sum both."""
    return float(tx.get("fee") or 0.0) + float(tx.get("commission") or 0.0)


def _view_income_rules(root: Path):
    """The project's lib/income_dating rules for the income views. A
    project with no country, or whose settings the rules refuse, stops
    the view."""
    settings = _soft_settings(root)
    # No country (no taxjson.toml): the window, the account types and
    # the dating rules are all unknown — refuse, as `divs` / `roc` do,
    # instead of an 'all history' total with registered accounts folded
    # in (audit A2-1110).
    _country(settings)
    try:
        return _income_rules(settings)
    except ValueError as e:
        _die(str(e))


def _view_trust_units(root: Path, rules) -> frozenset:
    """The symbols every account's books show to be a Canadian trust's
    units (lib/income_dating.trust_units, over the whole history, not
    the view's window): a payment in lieu on one is ordinary income,
    as in the gains files (CA-INC-07; A2-1465)."""
    if rules is None:
        return frozenset()
    cache = root / "work"
    rows = []
    for acct in _discover_tx_accounts(cache):
        native = _native_tx_file(cache, acct)
        if native is None:
            continue
        try:
            data = _read_work_doc(native)
        except (OSError, ValueError):
            continue          # the view's own read names a bad file
        rows += [t for t in (data.get("transactions") or [])
                 if isinstance(t, dict) and t.get("action") == "DIVIDEND"]
    return rules.trust_units(rows)


def _warn_accounts_without_books(root: Path, have, label: str,
                                 what: str) -> None:
    """Warn naming each configured account that has inputs but no `what`
    in work/ (its stage failed): the all-accounts views discover
    accounts from work/, so such an account was simply absent — "No
    wash sales", "No dividends" — with rc 0 (S045-09)."""
    have = set(have)
    skipped = _accounts_skipped_for_no_inputs(root)
    missing = sorted(n for n in (_soft_config(root).get("accounts") or {})
                     if n not in have and n not in skipped
                     and _has_inputs(root, n))
    if missing:
        print(f"tjs {label}: warning: no {what} for account(s) "
              f"{', '.join(missing)} (the last `tjs run` did not "
              f"build it — did it fail?) — their rows are NOT in this "
              f"report.", file=sys.stderr)


def _collect_period_txs(args: argparse.Namespace, label: str, actions,
                        date_of=None, settle_trades: bool = False):
    """Read native per-account transactions over a window, for the period-aware
    summaries (`fees`/`divs-sum`/`trades-sum`). The lone positional is a period
    (30d/6w/…) when it looks like one, else an account name; with no period the
    scope defaults to the config tax year. Returns (rows, scope_label, bad,
    keep) — `keep(iso_date) -> bool` is the window predicate, for callers
    that must apply the SAME window to a second data source. `date_of`
    (row -> ISO date) picks the date a row is windowed on (the income
    views pass lib/income_dating's tax date); default: its `date`."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    # `X-sum margin` → the lone positional is an account, not a window
    # (see _view_window).
    keep, scope, account = _view_window(args, root)

    if account:
        accounts = [account]
        if _native_tx_file(cache, account) is None:
            _die_input(f"no native transaction file for account "
                       f"{account!r} in work/ — run `tjs run` first, "
                       f"or check the name")
    else:
        accounts = _discover_tx_accounts(cache)
        if not accounts:
            _die("no transaction files in work/ — run `tjs run` first")
        _warn_accounts_without_books(root, accounts, label,
                                     "transaction file")

    rows, bad = [], 0
    # settle_trades: a "tax year N" window over a settle-basis project
    # takes a trade by its SETTLEMENT date, as Schedule 3 does (a
    # Dec-31 sale settling in January is next year's) — S039-18.
    _settle = settle_trades and _settle_basis(root)
    for acct in accounts:
        native = _native_tx_file(cache, acct)
        if native is None:
            continue
        data = _load_json_or_die(native)
        for tx in data.get("transactions", []):
            if actions is not None and tx.get("action") not in actions:
                continue
            d = tx.get("date") or ""
            if not _ISO_DATE_RE.match(d):
                bad += 1
                continue
            if date_of:
                d = date_of(tx)
            elif _settle and tx.get("action") in _TRADE_ACTIONS:
                d = _gains_row_date(tx, keep, True)
            if not keep(d):
                continue
            rows.append((acct, tx))
    return rows, scope, bad, keep


# Native rows that are dispositions/acquisitions, windowed on the
# project's tax_date basis in a tax-year view.
_TRADE_ACTIONS = ("BUYSELL", "ASSIGN", "EXERCISE")


def _account_group_of(root: Path) -> Dict[str, str]:
    """{account: 'taxable'|'sheltered'} from taxjson.toml ({} without a
    config) — the split the roll-up views print so a registered account's
    income or gains never pass for taxable ones (audit S040-13, S041-04)."""
    out: Dict[str, str] = {}
    for name, a in ((_soft_config(root).get("accounts") or {}).items()):
        t = str((a or {}).get("type") or "").strip().lower()
        if t in ("taxable", "sheltered"):
            out[name] = t
    return out


def _double_roc_warnings(root: Path, accounts, keep, rules=None
                         ) -> List[str]:
    """One sentence per [[distributions]] entry that books the same ROC an
    ADJUST in the books already books (same account, symbol and date):
    the ACB is reduced twice (audit R1-163). Matched over ALL rows, not
    the window's: the broker row is windowed on its record date and the
    map row on its own date, so a pair straddling the year end never met
    (audit A2-0072). The map date may be either the pay date or the
    printed record date. Shared by roc-sum, `run` and the checklist's
    roc-entered step (A2-0361)."""
    cache = root / "work"
    if rules is None:
        rules = _view_income_rules(root)
    all_native: List[Tuple[str, dict]] = []
    for a in accounts:
        nf = _native_tx_file(cache, a)
        if nf is None:
            continue
        all_native += [(a, t) for t in
                       (_load_json_or_die(nf).get("transactions") or [])
                       if t.get("action") == "ADJUST"]
    all_dist = _dist_adjust_rows(cache, accounts, lambda _d: True)
    book_keys: Dict[Tuple[str, str, str], str] = {}
    for a, t in all_native:
        if float(t.get("net_amount") or 0.0) >= 0:
            continue
        w = rules.roc_date(t) if rules else str(t.get("date") or "")
        for d in (t.get("date"), t.get("record_date")):
            if d:
                book_keys[(a, str(t.get("symbol") or ""), str(d))] = w
    out = []
    for a, t in all_dist:
        md = str(t.get("date_settle") or t.get("date") or "")
        w = book_keys.get((a, str(t.get("symbol") or ""), md))
        if w is not None and (keep(md) or keep(w)):
            out.append(f"{t.get('symbol')} {md} ({a}) has an ADJUST in the "
                       f"books AND a [[distributions]] entry — the ACB is "
                       f"reduced twice if both are the same distribution.")
    return out


def _dist_adjust_rows(cache: Path, accounts, keep) -> List[Tuple[str, dict]]:
    """[[distributions]] ACB adjustments: `run` books them (type 'dist',
    id DIST-*) into <acct>_base.json only — the native books the
    transaction views read never see them, so `roc` / `roc-sum` said
    "No ACB adjustments" while the engine applied one (audit R1-163)."""
    out: List[Tuple[str, dict]] = []
    # Only a project with [[distributions]] has such rows; without them
    # a missing base book hides nothing.
    _has_map = bool(_soft_config(cache.parent).get("distributions"))
    missing: List[str] = []
    for acct in accounts:
        p = cache / f"{acct}_base.json"
        if not p.exists():
            if _has_map:
                missing.append(p.name)
            continue
        doc = _load_json_or_die(p)
        for t in (doc.get("transactions") if isinstance(doc, dict)
                  else doc) or []:
            # The map's rows only (id DIST-*): RBC's NOTIONAL
            # DISTRIBUTION row carries type 'dist' too, but it is a
            # native row the view already shows — counted twice, with
            # a false double-entry warning (audit A2-0116).
            if (t.get("action") == "ADJUST"
                    and (t.get("type") or "").lower() == "dist"
                    and str(t.get("id") or "").startswith("DIST-")):
                # The map's own date (the record date) is date_settle:
                # the trade-date stamp can sit a day earlier so a
                # trade-ordered engine reaches the record holder's lots
                # (audit A2-0071).
                d = t.get("date_settle") or t.get("date") or ""
                if _ISO_DATE_RE.match(d) and keep(d):
                    out.append((acct, t))
    if missing and not warned_missing_base_once(missing):
        # The map's adjustments live only in the base books: without
        # one they vanished from roc / roc-sum with rc 0 (A2-1128).
        emit_line(f"tjs: warning: taxjson.toml has [[distributions]] but "
                  f"{', '.join(missing)} is missing in {cache} (the last "
                  f"`tjs run` did not build it) — that account's map "
                  f"ACB adjustments are NOT in this report.", file=sys.stderr)
    return out


_WARNED_MISSING_BASE: set = set()


def warned_missing_base_once(names) -> bool:
    """True when this process already warned about these base books
    (roc-sum reads them twice: the window's rows and the double-entry
    check's)."""
    key = tuple(sorted(names))
    if key in _WARNED_MISSING_BASE:
        return True
    _WARNED_MISSING_BASE.add(key)
    return False


def _warn_dist_double_entry(root: Path, accounts, rules, keep,
                            label: str) -> None:
    """Print _double_roc_warnings for a view (roc-sum, roc; A2-1116)."""
    for w in _double_roc_warnings(root, accounts, keep, rules):
        _view_msg("warning", w)

def _load_json_or_die(path: Path) -> Any:
    """Read a work/ artifact a query view needs, or stop naming it. The
    views used to warn and skip the file, then print a partial report —
    a smaller total, a missing account, a clean report —
    with exit 0 (audit S045-01, S042-05). A file that cannot be read is
    an input: exit 2, never the 1 of a command's finding (backlog
    TJ-0596, docs/commands.md's exit codes)."""
    try:
        return _read_work_doc(path)
    except (OSError, ValueError) as e:
        _die_input(f"could not read {_work_read_why(path, e)} — rerun "
                   f"`tjs run` (this view would otherwise leave that "
                   f"file's rows out).")


def _work_read_why(path: Path, e: BaseException,
                   root: Optional[Path] = None) -> str:
    """`<file>: <reason>` for a work/ file its reader refused, the file
    said once and from the project (`work/margin_gains.json: not valid
    JSON (…)`): the reader's message names it by its absolute path, and
    `could not read work/x: /abs/…/work/x: …` said it twice
    (docs/output-style.md; backlog TJ-0596, TJ-0641)."""
    if root is not None:
        shown = _out_relpath(path, root)
    elif path.parent.name == "work":
        shown = _out_relpath(path, path.parent.parent)
    else:
        shown = str(path)
    why = str(e)
    return (why.replace(str(path), shown) if str(path) in why
            else f"{shown}: {why}")


def _read_work_doc(path: Path) -> Dict[str, Any]:
    """A work/ artifact as a JSON object whose row lists are lists of
    objects (lib/json_input.read_work_doc). Raises OSError/ValueError
    — the views' existing handlers — never an AttributeError or a
    UnicodeDecodeError traceback for a corrupt file (S042-18)."""
    from taxjson.lib.json_input import read_work_doc
    return read_work_doc(path)


def _warn_bad_dates(bad: int) -> None:
    if bad:
        _view_msg("warning", f"{bad} row(s) had a missing/unparseable "
                  f"date and were excluded from the window.")


def cmd_fees(args: argparse.Namespace) -> None:
    """Fees incurred over a window (default: the tax year) — one row per
    fee-bearing transaction plus a per-currency total. `PERIOD` is 30d/6w/3m/1y/
    all; omit it for the tax year. (For the by-brokerage roll-up, see
    `fees-sum`.)"""
    rows, scope, bad, _keep = _collect_period_txs(args, "fees", actions=None)

    money = fmt_money               # shared report-layer formatter

    out_lines = ["ACCOUNT DATE SYMBOL ACTION FEE CUR"]
    import math as _math
    parts: Dict[str, List[float]] = {}
    entries = []
    n_small = 0
    for acct, tx in rows:
        if tx.get("action") == "FEE":
            # Standalone fee rows (e.g. IB monthly/market-data fees) carry
            # the amount in net_amount: POSITIVE = charged, the convention
            # every parser (IB, Questrade, RBC, generic) and fx-cash use
            # (a rebate is negative and nets out). The old flip showed
            # every charge as a rebate (R1-124, R1-54, R1-269).
            fee = float(tx.get("net_amount") or 0.0)
        else:
            fee = _tx_fee(tx)
        if abs(fee) < 1e-9:
            continue
        cur = tx.get("currency") or "?"
        # Every fee is in the total, unrounded; one under half a cent
        # is only not listed (it would print as 0.00). Skipping it
        # before the sum made three 0.004 commissions "no fees"
        # (backlog TJ-0328).
        parts.setdefault(cur, []).append(fee)
        if abs(fee) < 0.005:
            n_small += 1
            continue
        entries.append((tx.get("date") or "", acct, tx, fee, cur))
    totals = {c: _math.fsum(v) for c, v in parts.items()}
    entries.sort(key=lambda e: (e[0], e[1]))
    if getattr(args, "json", False):
        _warn_bad_dates(bad)
        _json_out({"rows": [{"account": acct, "date": date,
                             "symbol": tx.get("symbol"),
                             "action": tx.get("action"),
                             "fee": round(fee, 2), "currency": cur}
                            for date, acct, tx, fee, cur in entries],
                   "totals": {c: round(v, 2) + 0.0
                              for c, v in totals.items()},
                   # The fees under half a cent: in `totals`, not in
                   # `rows` (backlog TJ-0328).
                   "unlisted_small_fees": n_small,
                   "scope": scope})
        return
    for date, acct, tx, fee, cur in entries:
        out_lines.append(" ".join([acct, date or "-",
                                    str(tx.get("symbol") or "-"),
                                    str(tx.get("action") or "-"),
                                    money(fee), cur]))
    _warn_bad_dates(bad)
    if not parts:
        print(f"No fees incurred in {scope}.")
        return
    _vprint(f"FEES — {scope}")
    _vprint("Trade commissions and fees, and the FEE rows; per-trade "
            "totals by broker: tjs fees-sum.")
    if entries:
        _print_report_table(out_lines, fit=True, drop=(3,), key=(0, 1, 2))
        print()
    tot = ", ".join(f"{money(v)} {c}" for c, v in sorted(totals.items()))
    n = len(entries) + n_small
    unlisted = (f" ({n_small} under half a cent, not listed)"
                if n_small else "")
    print(f"{n} fee(s){unlisted}; TOTAL FEES: {tot}")


def _foot(values) -> float:
    """A report total that FOOTS: the sum of the rows as printed
    (rounded to the cent), not the raw sum rounded once — the printed
    TOTAL differed from the column by cents (S037-11; `sum` already
    rounds per row)."""
    return round(sum(round(float(v or 0.0), 2) for v in values), 2)


def _foot_by_currency(pairs) -> Dict[str, float]:
    """{currency: _foot of that currency's row amounts}."""
    out: Dict[str, List[float]] = {}
    for cur, v in pairs:
        out.setdefault(cur, []).append(v)
    return {c: _foot(vs) for c, vs in out.items()}


def _box18_fractions(root: Path, rules=None
                     ) -> Optional[Dict[Tuple[str, str], float]]:
    """{(account, row id): share of the DIVIDEND row that is a T5 box 18
    capital-gains dividend} from the project's [[capital_gains_dividends]]
    (taxjson.toml; lib/cg_dividends; tax-logic CA-INC-06), or None
    without entries. Canada only: a US project's table is refused with
    the rest of the config (lib/country CONFIG_COUNTRY). Matched over
    EVERY year in the native books, on the dividend's tax date; an
    entry without an account covers the taxable accounts."""
    from taxjson.lib.cg_dividends import (CgDividendMapError, allocate,
                                          entries_from_config)
    try:
        entries = entries_from_config(_soft_config(root))
    except CgDividendMapError as e:
        _die(str(e))
    if entries is None:
        return None
    if rules is None:
        rules = _view_income_rules(root)
    date_of = (rules.income_date if rules is not None
               else (lambda t: str(t.get("date") or "")))
    cache = root / "work"
    rows: List[Tuple[str, dict]] = []
    for acct in _discover_tx_accounts(cache):
        native = _native_tx_file(cache, acct)
        if native is None:
            continue
        for t in _load_json_or_die(native).get("transactions", []):
            if t.get("action") == "DIVIDEND":
                rows.append((acct, t))
    groups = _account_group_of(root)
    taxable = ({a for a, g in groups.items() if g == "taxable"}
               if groups else None)
    try:
        return allocate(entries, rows, date_of=date_of,
                        default_accounts=taxable)
    except CgDividendMapError as e:
        _die(str(e))


def _staking_rows(args: argparse.Namespace):
    """Rewards and their acquisitions from the final base-currency books.

    Read one consolidated book per configured crypto account, never the
    per-broker parses alongside it. This preserves the run's dedup, prices
    and FX and excludes intermediate books and the combined sheltered book.
    """
    from datetime import date as _date
    from taxjson.lib.core import validate_staking_reward
    root = Path(args.dir).resolve()
    cfg = _soft_config(root)
    settings = cfg.get("settings") or {}
    country = _country(settings)
    currency = _base_currency(root)
    keep, scope, selected = _view_window(args, root)
    _require_books(root, selected)
    configured = cfg.get("accounts") or {}
    if selected:
        if selected not in configured:
            _die_input(f"unknown account {selected!r} — check taxjson.toml")
        accounts = [selected]
    else:
        accounts = sorted(n for n, a in configured.items()
                          if (a or {}).get("crypto") is True)
    rows = []
    tt_rewards = 0
    for acct in accounts:
        path = root / "work" / f"{acct}_base.json"
        if not path.is_file():
            if selected or _has_inputs(root, acct):
                _die_input(f"no base-currency book for {acct!r} — run "
                           "`tjs run` first; staking totals need its "
                           "saved prices and exchange rates")
            continue
        crypto = (configured.get(acct) or {}).get("crypto") is True
        for tx in _load_json_or_die(path).get("transactions", []):
            action = tx.get("action")
            if action not in {"DIVIDEND", "BUYSELL"}:
                continue
            if action == "DIVIDEND" and not (crypto or tx.get("staking_reward")):
                continue
            when = str(tx.get("date") or "")
            try:
                _date.fromisoformat(when)
            except ValueError:
                _die_input(f"{path.name}: invalid reward/acquisition date "
                           f"{when!r} — rerun `tjs run`")
            if not keep(when):
                continue
            if str(tx.get("currency") or "").strip().upper() != currency.upper():
                _die_input(f"{path.name}: {tx.get('symbol', '?')} on {when} "
                           f"is not in {currency} — rerun `tjs run` "
                           "before totalling staking")
            if action == "DIVIDEND":
                facts = tx.get("staking_reward") or {}
                if not isinstance(facts, dict):
                    _die_input(f"{path.name}: damaged staking evidence — "
                               "rerun `tjs run`")
                if facts:
                    try:
                        validate_staking_reward(facts, path.name)
                    except ValueError as exc:
                        _die_input(f"{exc} — rerun `tjs run`")
                broker = str(facts.get("broker") or "unknown")
                if args.symbol and str(tx.get("symbol") or "").casefold() != args.symbol.casefold():
                    continue
                if args.broker and broker.casefold() != args.broker.casefold():
                    if broker == "unknown":
                        # A .tt reward line never records an exchange, so
                        # no rerun gives it one: left out of another
                        # exchange's view, and counted. An export's reward
                        # without one is a book built before the evidence.
                        if not str(tx.get("source") or "").lower().endswith(".tt"):
                            _die_input(f"{path.name}: exchange is unknown for a reward "
                                       "in this window — rerun `tjs run` before "
                                       "filtering staking by exchange")
                        tt_rewards += 1
                    continue
            rows.append((acct, tx))
    if tt_rewards:
        _say("note", f"{tt_rewards} reward(s) in this window come from .tt "
             f"lines, which name no exchange: not in --broker {args.broker}",
             "`tjs staking --broker unknown` lists them.")
    return rows, scope, currency, country, settings


def _staking_view(args: argparse.Namespace, *, summary: bool) -> None:
    from taxjson.lib import out
    from taxjson.lib.staking_report import build_report, render
    rows, scope, currency, country, settings = _staking_rows(args)
    try:
        report = build_report(
            rows, currency=currency, scope=scope, country=country,
            account_groups=_account_group_of(Path(args.dir).resolve()),
            local_timezone=str(settings.get("local_timezone") or "unknown"))
    except ValueError as exc:
        _die_input(f"staking report: {exc}")
    if getattr(args, "json", False):
        _json_out(report)
    else:
        out.show(render(report, summary=summary,
                        details=getattr(args, "details", False)), file=sys.stdout)


def cmd_staking(args: argparse.Namespace) -> None:
    """One reward per row, with commissions and the recorded income."""
    _staking_view(args, summary=False)


def cmd_staking_sum(args: argparse.Namespace) -> None:
    """Reward totals by exchange and asset, with evidence coverage."""
    _staking_view(args, summary=True)


def cmd_divs_sum(args: argparse.Namespace) -> None:
    """Dividend summary over a window (default: the tax year): total received
    per ticker, plus a per-currency grand total. `PERIOD` is 30d/6w/3m/1y/all;
    omit it for the tax year."""
    # DIVIDEND rows, plus (Canada) a payment in lieu that ITA s.260
    # deems a dividend — a Canadian dealer's payment on a Canadian
    # corporation's share (not a trust's unit, CA-INC-07), on the
    # dealer's T5 box 24. Every other payment in lieu is ordinary
    # income, reported by `dil-sum` only (counting it
    # in both views put it in the slip tie-out, audit R1-272). Rows are
    # windowed on their tax date (lib/income_dating: a Canadian trust's
    # distribution by its record date).
    _rules = _view_income_rules(Path(args.dir).resolve())
    rows, scope, bad, _keep = _collect_period_txs(
        args, "divs-sum", actions={"DIVIDEND", "DIVIDEND_IN_LIEU"},
        date_of=_rules.income_date if _rules else None)
    _trusts = _view_trust_units(Path(args.dir).resolve(), _rules)
    rows = [(a, t) for a, t in rows
            if t.get("action") == "DIVIDEND"
            or (_rules is not None and _rules.pil_is_dividend(t, _trusts))]
    n_pil_div = sum(1 for _a, t in rows
                    if t.get("action") == "DIVIDEND_IN_LIEU")

    money = fmt_money               # shared report-layer formatter
    groups = _account_group_of(Path(args.dir).resolve())

    agg: Dict[Tuple[str, str], float] = {}
    totals: Dict[str, float] = {}
    by_group: Dict[str, Dict[str, float]] = {"taxable": {},
                                             "sheltered": {}}
    shel_accts = set()
    # A crypto account's DIVIDEND rows are staking rewards — other
    # income, never on a T5/T3 — so they are totalled apart instead of
    # blending into the dividend total unmarked (audit S031-04).
    _crypto_accts = {n for n, a in ((_soft_config(Path(args.dir).resolve())
                                     .get("accounts") or {}).items())
                     if (a or {}).get("crypto") is True}
    staking: Dict[str, float] = {}
    staking_taxable: Dict[str, float] = {}
    staking_accts = set()
    # T5 box 18 capital-gains dividends named in capital_gains_dividends
    # .map (Canada, tax-logic CA-INC-06): a capital gain, not a
    # dividend — shown apart and left out of the dividend totals.
    _box18 = _box18_fractions(Path(args.dir).resolve(), _rules)
    cg_agg: Dict[Tuple[str, str], float] = {}
    cg_by_group: Dict[str, Dict[str, float]] = {"taxable": {},
                                                "sheltered": {}}
    for acct, tx in rows:
        cur = tx.get("currency") or "?"
        # Signed: reversal rows (negative) net against the original posting.
        amt = (float(tx.get("gross_amount") or 0.0)
               or float(tx.get("net_amount") or 0.0))
        _f = (_box18 or {}).get((acct, str(tx.get("id")))) \
            if tx.get("action") == "DIVIDEND" else None
        if _f:
            _cg = amt * _f
            amt -= _cg
            _k = (str(tx.get("symbol") or "?"), cur)
            cg_agg[_k] = cg_agg.get(_k, 0.0) + _cg
            _g = groups.get(acct)
            if _g:
                cg_by_group[_g][cur] = cg_by_group[_g].get(cur, 0.0) + _cg
        key = (str(tx.get("symbol") or "?"), cur)
        agg[key] = agg.get(key, 0.0) + amt
        totals[cur] = totals.get(cur, 0.0) + amt
        if acct in _crypto_accts:
            staking[cur] = staking.get(cur, 0.0) + amt
            staking_accts.add(acct)
            if groups.get(acct) == "taxable":
                staking_taxable[cur] = staking_taxable.get(cur, 0.0) + amt
        g = groups.get(acct)
        if g:
            by_group[g][cur] = by_group[g].get(cur, 0.0) + amt
            if g == "sheltered":
                shel_accts.add(acct)
    _warn_bad_dates(bad)
    totals = _foot_by_currency((cur, amt) for (_s, cur), amt in agg.items())
    # The figure the T5/T3 slips add up to: taxable accounts' dividends
    # WITHOUT crypto staking (other income, never on a slip) — the
    # "compare with slips" line counted staking in (S048-24).
    slips = {c: v - staking_taxable.get(c, 0.0)
             for c, v in by_group["taxable"].items()}
    cg_totals = _foot_by_currency((cur, a) for (_s, cur), a
                                  in cg_agg.items())
    cg_doc = None
    if _box18 is not None:
        cg_doc = {"rows": [{"symbol": sym, "currency": cur,
                            "amount": round(a, 2)}
                           for (sym, cur), a in sorted(cg_agg.items())],
                  "totals": {c: round(v, 2) for c, v in cg_totals.items()},
                  "totals_taxable": {c: round(v, 2) for c, v
                                     in cg_by_group["taxable"].items()},
                  "totals_sheltered": {c: round(v, 2) for c, v
                                       in cg_by_group["sheltered"].items()},
                  "line": "17400"}
    if getattr(args, "json", False):
        _json_out({"rows": [{"symbol": sym, "currency": cur,
                             "dividend": round(amt, 2)}
                            for (sym, cur), amt in sorted(agg.items())],
                   "capital_gains_dividends": cg_doc,
                   "totals": {c: round(v, 2) for c, v in totals.items()},
                   "totals_taxable": {c: round(v, 2) for c, v
                                      in by_group["taxable"].items()},
                   "totals_sheltered": {c: round(v, 2) for c, v
                                        in by_group["sheltered"].items()},
                   "totals_slips": {c: round(v, 2) for c, v
                                    in slips.items()},
                   "sheltered_included": sorted(shel_accts),
                   "crypto_staking": {c: round(v, 2) for c, v
                                      in staking.items()},
                   "payments_in_lieu_as_dividends": n_pil_div,
                   "scope": scope})
        return
    if not agg and not cg_agg:
        print(f"No dividends in {scope}.")
        return
    out_lines = ["SYMBOL CUR DIVIDEND"]
    for (sym, cur), amt in sorted(agg.items()):
        out_lines.append(" ".join([sym, cur, money(amt)]))
    _vprint(f"DIVIDENDS — {scope}")
    if n_pil_div:
        _vprint(f"DIVIDEND rows and {n_pil_div} payment(s) in lieu deemed "
                f"dividends by ITA s.260; other payments in lieu are in "
                f"`dil-sum`.")
    else:
        _vprint("DIVIDEND rows; payments in lieu are in `dil-sum`.")
    print()
    _print_report_table(out_lines, fit=True)

    def _tot(d):
        return ", ".join(f"{money(v)} {c}" for c, v in sorted(d.items()))
    print()
    # The slips a dividend ties to: T5/T3 in Canada, Form 1099-DIV in the
    # US (audit A2-0741, A2-1354).
    _usa_v = _country(_soft_settings(Path(args.dir).resolve())) == "usa"
    _slips_w = "Form 1099-DIV" if _usa_v else "T5/T3 slips"
    from taxjson.lib.out import kv_lines as _kvl
    _figs = []
    if shel_accts or staking_taxable:
        # Registered accounts get no T5/T3 and their dividends are not
        # income: the slip tie-out figure is the TAXABLE line (audit
        # S041-04), without crypto staking (S048-24).
        _figs.append((f"TAXABLE ({_slips_w})", _tot(slips) or "0.00"))
        if shel_accts:
            _figs.append((f"SHELTERED ({', '.join(sorted(shel_accts))}, "
                          f"not taxable)", _tot(by_group['sheltered'])))
        _figs.append(("TOTAL DIVIDEND (all accounts)", _tot(totals)))
    else:
        _figs.append(("TOTAL DIVIDEND", _tot(totals)))
    if staking_accts:
        _figs.append((f"  of which staking rewards ("
                      f"{', '.join(sorted(staking_accts))}, other income, "
                      f"no {'1099-DIV' if _usa_v else 'slip'})",
                      _tot(staking)))
    for ln in _kvl(_figs):
        print(ln)
    if cg_agg:
        print()
        _vprint("CAPITAL-GAINS DIVIDENDS — T5 box 18, line 17400")
        _vprint("A capital gain at 50% inclusion, not a dividend; named in "
                "[[capital_gains_dividends]], NOT in the totals above.")
        print()
        _print_report_table(["SYMBOL CUR AMOUNT"] + [
            " ".join([sym, cur, money(a)])
            for (sym, cur), a in sorted(cg_agg.items())], fit=True)
        print()
        if cg_by_group["sheltered"]:
            _vprint(f"TAXABLE: {_tot(cg_by_group['taxable']) or '0.00'}; "
                    f"SHELTERED: {_tot(cg_by_group['sheltered'])}",
                    hang="  ")
        _vprint(f"TOTAL CAPITAL-GAINS DIVIDENDS: {_tot(cg_totals)}",
                hang="  ")


def cmd_div_estimate(args: argparse.Namespace) -> None:
    """`tjs div-estimate [PERIOD] [ACCOUNT] [--months N] [--date D]`:
    upcoming dividends projected from each held position's own dividend
    history in the books (lib/div_estimate; CA-PLAN-06 / US-PLAN-07).
    The history is the native books (work/<acct>_raw.json, what
    divs-sum reads), the shares held now each account's native
    holdings (work/<acct>_raw_gains.json inventory, one row per
    listing), the base-currency rate the books' latest (work/
    to_base.csv). Crypto accounts are left out (staking is not a
    dividend). Planning numbers only."""
    from taxjson.lib import div_estimate as DE
    from taxjson.lib.core import is_option_symbol
    from taxjson.lib.price_chain import latest_rate, load_fx_history
    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = _soft_settings(root)
    rules = _view_income_rules(root)        # refuses a project w/o country
    period, account = args.period, args.account
    if period and account is None and DE.parse_window(period) is None:
        account, period = period, None
    months = 12
    if period:
        months = DE.parse_window(period)
        if months is None:
            _die_input(f"{period!r} is not a forward window",
                       "Give Nd, Nw, Nm or Ny (6m, 1y), or --months N.")
        # The same limits as --months (a 100000y window reached a
        # date past year 9999 and a traceback; '0m' was one month:
        # backlog TJ-0039).
        if months < 1:
            _die_input(f"{period!r} is a zero-length window",
                       "Give a window of 1 to 120 months (1m to 10y), "
                       "as --months takes.")
        if months > 120:
            _die_input(f"{period!r} is longer than 120 months",
                       "Give a window up to 10y (120m).")
    if args.months is not None:
        if period:
            _die_input("give a PERIOD or --months, not both")
        if args.months < 1 or args.months > 120:
            _die_input("--months must be between 1 and 120")
        months = args.months
    if args.date:
        from taxjson.lib.dates import as_of_date_problem
        _bad = as_of_date_problem(args.date)
        if _bad:
            _die_input(_bad)
    as_of = args.date or date_cls.today().isoformat()
    accounts_cfg = (_soft_config(root).get("accounts") or {})
    if account and account not in accounts_cfg:
        _die_input(f"no [accounts.{account}] in taxjson.toml",
                   "Check the name.")
    if not cache.is_dir():
        _die("no work/ — run `tjs run` first.")
    groups = _account_group_of(root)
    rows: List[Tuple[str, Dict[str, Any]]] = []
    positions: List[Dict[str, Any]] = []
    missing: List[str] = []
    # A payer's history is read from every account (one schedule per
    # listing); the account filter picks the positions estimated.
    for n in sorted(accounts_cfg):
        acfg = accounts_cfg.get(n) or {}
        if acfg.get("crypto"):
            continue
        native = _native_tx_file(cache, n)
        inv = cache / f"{n}_raw_gains.json"
        if native is not None:
            data = _load_json_or_die(native)
            ntx = [t for t in (data.get("transactions") or [])
                   if isinstance(t, dict)]
            rows += [(n, t) for t in ntx]
            # Units held before the data (a .tt OPENING cost=unknown
            # line), opened as the gains stage opens them: a dividend
            # row is read against the position the books hold, not a
            # short made of a sale of those units (2026-10-25 audit
            # planning-us#4).
            rows += [(n, t) for t in _tt_openings(root, ntx, native=True)
                     if str(t.get("account") or n) == n]
        if account and n != account:
            continue
        if native is None or not inv.exists():
            if _has_inputs(root, n):
                missing.append(n)
            continue
        for h in (_load_json_or_die(inv).get("inventory") or []):
            sym = str((h or {}).get("symbol") or "").strip()
            qty = float((h or {}).get("qty") or 0.0)
            if (not sym or qty <= 1e-9 or sym.startswith("CASH.")
                    or is_option_symbol(sym.upper())):
                continue
            positions.append({"account": n, "group": groups.get(n, ""),
                              "symbol": sym, "qty": qty})
    if missing:
        _view_msg("warning", f"no native books for {', '.join(missing)} "
                  f"(work/<account>_raw.json, _raw_gains.json): not "
                  f"estimated",
                  "Run `tjs run`; a raw holdings view skipped for "
                  "mixed currencies leaves an account out too.")
    if not rows and not positions and not missing:
        _die("no books in work/ — run `tjs run` first.")
    base = _base_currency(root)
    hist = load_fx_history(cache / "to_base.csv", base)

    def _fx(cur: str):
        r, _d = latest_rate(hist, cur, as_of)
        return r

    def _fx_on(cur: str, on: str):
        # A pay date's rate (a withholding posted in another currency
        # than its dividend: backlog TJ-0548).
        r, _d = latest_rate(hist, cur, on)
        return r
    try:
        year = int(str(settings.get("year") or as_of[:4]))
    except ValueError:
        year = int(as_of[:4])
    # The whole horizon (the window, and the January after the tax
    # year) must stay in the calendar: `--date 9999-09-01 --months 120`
    # reached year 10009 and a traceback (2026-10 audit A30).
    _bad = DE.horizon_problem(as_of, months, year)
    if _bad:
        _die_input(_bad, "Give an earlier --date or a shorter window.")
    pays = DE.payments(rows, as_of=as_of)
    # A dividend paid while the books put the account short: counted,
    # but a short is charged a dividend, not paid one, so a trade is
    # likely missing (backlog TJ-0073). One warning per account and
    # security.
    for (_a, _s), _ds in sorted(pays.short_paid.items()):
        _view_msg("warning",
                  (f"{_a}: {_s} dividend paid on {_ds[0]}" if len(_ds) == 1
                   else f"{_a}: {len(_ds)} {_s} dividends paid from "
                   f"{_ds[0]}") + " while the books show it short",
                  "A short position is charged a dividend, not paid "
                  "one: the books likely miss a purchase or a transfer "
                  "in before it. The estimate counts the payment as "
                  "income.",
                  "Find the missing trade: `tjs find-missing-history`.")
    doc = DE.estimate(positions, pays, as_of=as_of,
                      months=months, tax_year=year, base=base, fx=_fx,
                      income_date=rules.income_date if rules else None,
                      fx_on=_fx_on)
    if getattr(args, "json", False):
        _json_out(doc)
        return
    DE.render(doc, _details(args), country=_country(settings)).print()

def _names_phrase(names: List[str]) -> str:
    """`a, b, c` up to three names, else `N accounts` (a step line
    naming every account wraps)."""
    return ", ".join(names) if len(names) <= 3 else f"{len(names)} accounts"


def _accounts_phrase(names: List[str]) -> str:
    """`taxable accounts: a, b` up to three names, else `4 taxable
    accounts` (a title that names every account wraps)."""
    if len(names) <= 3:
        return f"taxable accounts: {', '.join(names)}"
    return f"{len(names)} taxable accounts"


def _option_openings(root: Path, rows: List[Dict[str, Any]],
                     native: bool = False) -> List[Dict[str, Any]]:
    """The missing-history openings (`OPENING <date> <SYMBOL> <qty>
    cost=unknown` .tt lines) of the option contracts in `rows` (one
    account's book), as the OPENING_BALANCE rows the gains stage
    synthesizes in memory — the books on disk never carry them, so the
    option views read a long contract bought before the data and sold
    to close as a write (2026-10 audit #59; option-boundary's S044-09).
    `native`: the rows are the native books (symbols mapped by GLOBAL
    renames only). [] without such lines."""
    return _tt_openings(root, rows, native=native, options_only=True)


def _tt_openings(root: Path, rows: List[Dict[str, Any]], *,
                 native: bool = False,
                 options_only: bool = False) -> List[Dict[str, Any]]:
    """The missing-history openings of `rows` (one account's book), as
    the OPENING_BALANCE rows the gains stage synthesizes in memory:
    every symbol's, or the option contracts' alone (`options_only`,
    `_option_openings`). A view that reads a position from the books on
    disk reads a sale of units bought before the data as a short
    without them (div-estimate's long or short test: 2026-10-25 audit
    planning-us#4). `native`: the rows are the native books (symbols
    mapped by GLOBAL renames only). [] without such lines."""
    mh = _missing_history_arg(root)
    if mh is None or not rows:
        return []
    from taxjson.lib.core import TaxTransaction, is_option_symbol
    from taxjson.lib.missing_history import (load_missing_history,
                                             synthesize_openings)
    try:
        pairs = load_missing_history(mh, native=native)
    except (OSError, ValueError) as e:
        _die("the .tt OPENING cost=unknown lines cannot be read", str(e))
    fixed = getattr(pairs, "fixed", None) or {}
    if options_only \
            and not any(is_option_symbol(str(sym)) for sym, _a in fixed) \
            and not any(is_option_symbol(str(sym)) for sym, _a in pairs):
        return []
    if not fixed and not pairs:
        return []
    fields = TaxTransaction.__dataclass_fields__
    txs = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        try:
            txs.append(TaxTransaction(**{k: v for k, v in r.items()
                                         if k in fields}))
        except TypeError:
            continue
    try:
        out, _log = synthesize_openings(txs, pairs, flag_stale=False)
    except ValueError as e:
        _die("the .tt OPENING cost=unknown lines cannot be applied", str(e))
    import dataclasses as _dc
    return [_dc.asdict(t) for t in out
            if t.action == "OPENING_BALANCE"
            and (not options_only or is_option_symbol(str(t.symbol or "")))]


def _closed_trade_inputs(args: argparse.Namespace, root: Path,
                         label: str) -> Dict[str, Any]:
    """What `stats` and `win-rates` read (lib/trade_stats): the window
    and account of the positionals, each account's gains document and
    base-currency book (taxable accounts by default; a sheltered one
    only when named), the row-dating closure and the span the written
    options keep to (a year project's gains files hold one tax year)."""
    from taxjson.lib.crypto_sends import crypto_accounts
    cache = root / "work"
    keep, scope, account = _view_window(args, root)
    groups = _account_group_of(root)
    resolved, all_history = _window_gains_files(root, cache, account,
                                                args)
    if not account:
        # Taxable accounts by default; a sheltered one only when named.
        resolved = {a: f for a, f in resolved.items()
                    if groups.get(a) != "sheltered"}
        if resolved:
            _warn_accounts_without_books(
                root, list(resolved) + [a for a, g in groups.items()
                                        if g == "sheltered"],
                label, "gains file")
    if not resolved:
        what = (f"account {account!r}" if account else "a taxable account")
        _die(f"no books for {what} in work/ — run `tjs run` first")
    books: Dict[str, list] = {}
    base_rows: Dict[str, list] = {}
    gains: Dict[str, Dict[str, Any]] = {}
    for acct, path in resolved.items():
        gains[acct] = _load_json_or_die(path)
        bpath = cache / f"{acct}_base.json"
        if not bpath.is_file():
            _die(f"no base-currency book for account {acct!r} "
                 f"(work/{bpath.name})", "Run `tjs run` first.")
        base_rows[acct] = list(_load_json_or_die(bpath).get("transactions")
                               or [])
        books[acct] = base_rows[acct] + _option_openings(root,
                                                         base_rows[acct])
    settle = _settle_basis(root, next(iter(gains.values())))
    # The gains files of a year project hold that tax year only; the
    # written options (rebuilt from the whole-history base book) keep
    # to the same span.
    _years = {str((d.get("summary") or {}).get("year") or "")
              for d in gains.values()}
    _by = next(iter(_years)) if len(_years) == 1 else ""
    in_books = None
    if re.fullmatch(r"\d{4}", _by):
        def in_books(r, _y=_by):
            d = (r.get("date_settle") if settle else None) or r.get("date")
            return str(d or "").startswith(_y)
    crypto = crypto_accounts(_soft_config(root))
    pools = _acb_pools(root, cache, gains, groups, crypto, base_rows)
    fifo = None
    if pools is None:
        # The US lots, the stocks' missing-history openings with them: a
        # lot of unknown cost a sale takes first (backlog TJ-1097).
        books = {a: rows + _tt_openings(root, rows)
                 for a, rows in base_rows.items()}
        fifo = _fifo_books(root, cache, groups, crypto, base_rows)
    # An assignment's contract size: the project's MULT lines first, as
    # the engine sizes it (TJ-0789).
    _use_project_ticker_map(root)
    from taxjson.lib.country import engine_sort_profile
    country = _country(_soft_settings(root))
    return {"keep": keep, "scope": scope, "account": account,
            "groups": groups, "resolved": resolved, "gains": gains,
            "books": books, "settle": settle, "in_books": in_books,
            "date_of": lambda r: _gains_row_date(r, keep, settle),
            "crypto": crypto, "pools": pools,
            "timelines": _acb_pool_timelines(cache, pools, gains),
            "cover_docs": _pool_cover_docs(root, cache, pools, gains,
                                           all_history),
            # The written options' replay orders a split as the
            # country's engine does (backlog TJ-0697).
            "split_at_open": engine_sort_profile(country) == "ca_main",
            "fifo_books": fifo,
            "fifo_timelines": _fifo_timelines(cache, fifo, books, gains),
            "history_docs": _fifo_history_docs(root, cache, fifo, books,
                                               _by, all_history),
            "cover_history_docs": _pool_history_cover_docs(
                root, cache, pools, _by, all_history)}


def _fifo_books(root: Path, cache: Path, groups: Dict[str, str],
                crypto: Iterable[str], base_rows: Dict[str, list]
                ) -> Dict[str, list]:
    """{account: base-currency book rows} of every taxable account of a
    US project (FIFO lots per account, US-BASIS-01), whether shown or
    not: a move between two of your own accounts carries its lots, and
    an assigned put's premium with them, into the other (lib/trade_stats
    share_credits; backlog TJ-0788)."""
    crypto = set(crypto)
    out: Dict[str, list] = {}
    for acct, g in sorted(groups.items()):
        if g != "taxable" or acct in crypto:
            continue
        rows = base_rows.get(acct)
        if rows is None:
            bpath = cache / f"{acct}_base.json"
            if not bpath.is_file():
                continue
            rows = list(_load_json_or_die(bpath).get("transactions") or [])
        out[acct] = rows + _tt_openings(root, rows)
    return out


def _fifo_timelines(cache: Path, fifo: Optional[Dict[str, list]],
                    books: Dict[str, list],
                    gains: Dict[str, Dict[str, Any]]
                    ) -> Optional[Dict[str, Optional[Dict[str, Any]]]]:
    """{account: the engine's cost timeline} of a US project's lots
    (`_acb_pool_timelines`, one account at a time): what
    lib/trade_stats.share_credits reads a spin-off's part of the basis
    from (backlog TJ-1095). None in a Canadian project."""
    if fifo is None:
        return None
    accts = sorted(set(fifo) | set(books))
    tls = _acb_pool_timelines(cache, [{a: []} for a in accts], gains) or []
    return dict(zip(accts, tls))


def _fifo_history_docs(root: Path, cache: Path,
                       fifo: Optional[Dict[str, list]],
                       books: Dict[str, list], year: str,
                       all_history: bool) -> Dict[str, Dict[str, Any]]:
    """{account: full-history gains document} of a US year view whose
    taxable accounts hold an assigned option (in any of them: a move
    carries its lots to another): each account with a return of capital
    of an earlier year, or of the view's span in an account not shown.
    The year's gains rows shown do not hold its deemed gain, which took
    the premium in the lots' cost (backlog TJ-1133, TJ-1221, TJ-1255).
    Only those: the file is built on demand (_gains_all_file). An
    account whose file cannot be read is left out."""
    import json as _json
    from taxjson.lib.core import is_option_symbol
    out: Dict[str, Dict[str, Any]] = {}
    if fifo is None or all_history or not re.fullmatch(r"\d{4}", year):
        return out
    start, after = f"{year}-01-01", f"{int(year) + 1}-01-01"
    settings = _soft_settings(root)
    joint = dict(fifo)
    joint.update(books)
    if not any(isinstance(r, dict) and r.get("action") == "ASSIGN"
               and is_option_symbol(str(r.get("symbol") or ""))
               for rows in joint.values() for r in rows):
        return out
    for acct, rows in sorted(joint.items()):
        rows = [r for r in rows if isinstance(r, dict)]
        until = after if acct not in books else start
        if not any(r.get("action") == "ADJUST"
                   and str(r.get("date") or "") < until
                   and float(r.get("net_amount") or 0.0) < 0
                   for r in rows):
            continue
        path = _gains_all_file(root, cache, acct, settings)
        if path is None:
            continue
        try:
            doc = _json.loads(Path(path).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(doc, dict):
            out[acct] = doc
    return out


def _pool_history_cover_docs(root: Path, cache: Path,
                             pools: Optional[List[Dict[str, list]]],
                             year: str, all_history: bool
                             ) -> Dict[str, Dict[str, Any]]:
    """{account: full-history gains document} of the accounts of a
    Canadian year view's pools with an option assigned before the year,
    in a pool whose shares went short before it (what a put's delivery
    can have covered): lib/trade_stats.closed_trades reads
    those covers, which the year's files do not hold, so the delivery
    is not read as shares into the pool (backlog TJ-1222). The file is
    built on demand (_gains_all_file). An account whose file cannot be
    read is left out."""
    import json as _json
    from taxjson.lib.core import is_option_symbol
    out: Dict[str, Dict[str, Any]] = {}
    if not pools or all_history or not re.fullmatch(r"\d{4}", year):
        return out
    start = f"{year}-01-01"
    settings = _soft_settings(root)
    for pool in pools:
        early = {a: [r for r in rows if isinstance(r, dict)
                     and str(r.get("date") or "") < start]
                 for a, rows in pool.items()}
        moved = sorted((r for rows in early.values() for r in rows
                        if r.get("action") in ("BUYSELL", "ASSIGN",
                                               "OPENING_BALANCE", "TRANSFER")
                        and not is_option_symbol(str(r.get("symbol") or ""))),
                       key=lambda r: (str(r.get("date") or ""),
                                      str(r.get("time") or "")))
        net: Dict[str, float] = {}
        went_short = False
        for r in moved:
            sym = str(r.get("symbol") or "")
            net[sym] = net.get(sym, 0.0) + float(r.get("quantity") or 0.0)
            went_short = went_short or net[sym] < -1e-6
        if not went_short:
            continue
        for acct, rows in sorted(early.items()):
            if acct in out or not any(
                    r.get("action") == "ASSIGN"
                    and is_option_symbol(str(r.get("symbol") or ""))
                    for r in rows):
                continue
            path = _gains_all_file(root, cache, acct, settings)
            if path is None:
                continue
            try:
                doc = _json.loads(Path(path).read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            if isinstance(doc, dict):
                out[acct] = doc
    return out


def _acb_pool_timelines(cache: Path, pools: Optional[List[Dict[str, list]]],
                        gains: Dict[str, Dict[str, Any]]
                        ) -> Optional[List[Optional[Dict[str, Any]]]]:
    """Each of `_acb_pools`' pools' engine cost timeline (lib/cost_timeline,
    `timeline_beside` the gains pass that walked it: the blended pass's
    for the blended accounts, else the account's own), None where there
    is none or it cannot be read: lib/trade_stats.pooled_put_credits
    reads a spin-off's part of the ACB from it (backlog TJ-0894)."""
    import json as _json
    if pools is None:
        return None
    out: List[Optional[Dict[str, Any]]] = []
    for pool in pools:
        acct = next(iter(pool), "")
        doc = gains.get(acct)
        wash = cache / f"{acct}_gains_wash.json"
        if doc is None and wash.is_file():
            try:
                doc = _json.loads(wash.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                doc = None
        split = isinstance(doc, dict) and bool(
            (doc.get("metadata") or {}).get("split_from"))
        tl = None
        for g in ([cache / ".blend_gains_wash.json"] if split
                  else [wash, cache / f"{acct}_gains.json"]):
            try:
                tl = _json.loads(timeline_beside(g).read_text(
                    encoding="utf-8"))
            except (OSError, ValueError):
                continue
            break
        out.append(tl if isinstance(tl, dict) else None)
    return out


def _pool_cover_docs(root: Path, cache: Path,
                     pools: Optional[List[Dict[str, list]]],
                     gains: Dict[str, Dict[str, Any]],
                     all_history: bool) -> Dict[str, Dict[str, Any]]:
    """{account: gains document} of the accounts of `_acb_pools`' pools
    that the view does not show (a view of one account), the same kind
    of file as the shown ones (the tax year's, else the full-history
    one): lib/trade_stats.closed_trades reads their short covers, so a
    put's shares that covered another account's short keep their
    premium out of the shown account's sales (backlog TJ-0994). An
    account whose file cannot be read is left out."""
    import json as _json
    from taxjson.lib.report_model import resolve_gains_files
    missing = sorted({a for pool in (pools or []) for a in pool}
                     - set(gains))
    if not missing:
        return {}
    files = resolve_gains_files(cache, None)
    settings = _soft_settings(root) if all_history else {}
    out: Dict[str, Dict[str, Any]] = {}
    for acct in missing:
        path = (_gains_all_file(root, cache, acct, settings)
                if all_history else files.get(acct))
        if path is None:
            continue
        try:
            doc = _json.loads(Path(path).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(doc, dict):
            out[acct] = doc
    return out


def _gains_blended(cache: Path, acct: str) -> bool:
    """Whether the account's tax-year gains came from the blended
    taxable pass (its wash file's metadata says `blended`)."""
    import json as _json
    wash = cache / f"{acct}_gains_wash.json"
    if not wash.is_file():
        return False
    try:
        doc = _json.loads(wash.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    return bool(isinstance(doc, dict)
                and (doc.get("metadata") or {}).get("blended"))


def _split_pool_of(root: Path) -> Callable[[str], str]:
    """account -> the pool its corporate events are shared in, for the
    option views that replay the native books per account: in a
    Canadian project the taxable equity accounts the run blended are
    one pool (ITA s.47, CA-CORP-12: a split or rename of a series that
    one of them reports is the security's, and the gains carry it into
    the others' contracts), every other account a pool of its own. A
    split posted in one account left the others' contracts in the old
    series (backlog TJ-0907). A US project, or books without a
    taxjson.toml country: each account its own."""
    settings = _soft_settings(root)
    if not settings.get("country") or _country(settings) == "usa":
        return lambda a: a
    from taxjson.lib.crypto_sends import crypto_accounts
    cache = root / "work"
    crypto = set(crypto_accounts(_soft_config(root)))
    members = {a for a, g in _account_group_of(root).items()
               if g == "taxable" and a not in crypto
               and _gains_blended(cache, a)}
    return lambda a: "\0blended" if a in members else a


def _option_split_rows(root: Path, cache: Path,
                       accounts: Iterable[str]) -> Dict[str, list]:
    """{account: the SPLIT rows of option series its gains rows went
    through}: the base books' (the gains' own symbols) of every account
    of its split pool (_split_pool_of), one event once — what
    report_model.grant_write_expiries follows a renamed write through
    (backlog TJ-0903)."""
    from taxjson.lib.core import is_option_symbol
    from taxjson.lib.corporate_timeline import dedupe_split_events
    pool_of = _split_pool_of(root)
    by_pool: Dict[str, list] = {}
    accounts = list(accounts)
    pools = {pool_of(a) for a in accounts}
    for a in sorted(set(_discover_tx_accounts(cache)) | set(accounts)):
        if pool_of(a) not in pools:
            continue
        bpath = cache / f"{a}_base.json"
        if not bpath.is_file():
            continue
        try:
            rows = _read_work_doc(bpath).get("transactions") or []
        except (OSError, ValueError):
            continue
        by_pool.setdefault(pool_of(a), []).extend(
            t for t in rows if isinstance(t, dict)
            and t.get("action") == "SPLIT"
            and is_option_symbol(str(t.get("symbol") or "")))
    return {a: dedupe_split_events(by_pool.get(pool_of(a), []))
            for a in accounts}


def _acb_pools(root: Path, cache: Path, gains: Dict[str, Dict[str, Any]],
               groups: Dict[str, str], crypto: Iterable[str],
               base_rows: Dict[str, list]
               ) -> Optional[List[Dict[str, list]]]:
    """A Canadian project's average-cost pools for `stats` / `win-rates`
    (lib/trade_stats.closed_trades `pools`), each {account: base book
    with its missing-history openings}: the taxable equity accounts the
    run blended (ITA s.47: one cost per security across them; their
    gains files say `blended`), every one of them whether shown or not,
    and each other account read a pool of its own. An assigned put's
    premium is drawn by the pool's sales as the gains rows' cost holds
    it (backlog TJ-0546). None in a US project (FIFO per account)."""
    import json as _json
    if _country(_soft_settings(root)) == "usa":
        return None
    crypto = set(crypto)

    def book(acct: str) -> Optional[list]:
        rows = base_rows.get(acct)
        if rows is None:
            bpath = cache / f"{acct}_base.json"
            if not bpath.is_file():
                return None
            rows = list(_load_json_or_die(bpath).get("transactions") or [])
        return rows + _tt_openings(root, rows)

    def blended(acct: str) -> bool:
        doc = gains.get(acct)
        if doc is None:
            wash = cache / f"{acct}_gains_wash.json"
            if not wash.is_file():
                return False
            try:
                doc = _json.loads(wash.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                return False
        return bool(isinstance(doc, dict)
                    and (doc.get("metadata") or {}).get("blended"))
    members = [a for a, g in sorted(groups.items())
               if g == "taxable" and a not in crypto and blended(a)]
    pools: List[Dict[str, list]] = []
    blend = {a: rows for a in members
             if (rows := book(a)) is not None}
    if blend:
        pools.append(blend)
    for acct in gains:
        if acct in blend or acct in crypto:
            continue
        rows = book(acct)
        if rows is not None:
            pools.append({acct: rows})
    return pools


def cmd_win_rates(args: argparse.Namespace) -> None:
    """`tjs win-rates [SYMBOL...] [PERIOD] [ACCOUNT] [--by
    symbol|account|month|class] [--all-history] [--json]`: the win
    rate of every closed trade in the window, grouped per share
    listing (an option under its underlying) by default, else per
    account, month of the close or asset class (lib/trade_stats
    closed_trades + group) — economic P/L in the base currency before
    any superficial-loss / wash-sale denial, as `stats` counts it. A
    view, never a filing number."""
    from taxjson.lib import trade_stats
    from taxjson.lib.option_yield import underlying_matches
    root = Path(args.dir).resolve()
    settings = _soft_settings(root)
    usa = _country(settings) == "usa"
    accounts_cfg = (_soft_config(root).get("accounts") or {})
    # The positionals: a period token, an account name, the rest are
    # symbols (`win-rates QQQ 1y margin`), in any order.
    period, account, syms = _view_positionals(
        args.items, accounts_cfg, all_history=bool(args.all_history))
    if args.all_history:
        if period:
            _die_input("give a PERIOD or --all-history, not both")
        period = "all"
    args.period, args.account = period, account
    inp = _closed_trade_inputs(args, root, "win-rates")

    def _sym_ok(sym: str) -> bool:
        # An option under its underlying, as the rows are grouped; the
        # denied and unknown-cost tallies take the same filter (backlog
        # TJ-0025).
        return (underlying_matches(trade_stats._underlying(sym), syms)
                or sym.upper() in syms)
    res = trade_stats.closed_trades(inp["gains"], inp["books"], inp["keep"],
                                    inp["date_of"], inp["crypto"],
                                    inp["in_books"],
                                    symbol_ok=_sym_ok if syms else None,
                                    pools=inp["pools"],
                                    timelines=inp["timelines"],
                                    split_at_open=inp["split_at_open"],
                                    fifo_books=inp["fifo_books"],
                                    cover_docs=inp["cover_docs"],
                                    fifo_timelines=inp["fifo_timelines"],
                                    history_docs=inp["history_docs"],
                                    cover_history_docs=inp[
                                        "cover_history_docs"])
    trades = res["trades"]
    unmatched: List[str] = []
    if syms:
        for w in syms:
            if not any(underlying_matches(t["underlying"], [w])
                       or t["symbol"].upper() == w for t in trades):
                unmatched.append(w)
    g = trade_stats.group(trades, args.by)
    base = _base_currency(root)
    scope, account = inp["scope"], inp["account"]
    sheltered = bool(account) and inp["groups"].get(account) == "sheltered"
    rule = "wash-sale" if usa else "superficial-loss"
    doc = dict(g, scope=scope, currency=base,
               accounts=sorted(inp["resolved"]), sheltered=sheltered,
               symbols=syms, unmatched_symbols=unmatched,
               basis=f"economic P/L before any {rule} denial",
               denied_total=res["denied_total"],
               denied_count=res["denied_count"],
               tainted_skipped=res["tainted_skipped"],
               # Not trades (TJ-0629): apart.
               moved_in_kind={k: res["moved_in_kind"][k]
                              for k in ("count", "net_pl")})
    if getattr(args, "json", False):
        _json_out(doc)
        return
    money = fmt_money

    def _m(v):
        return "-" if v is None else money(v)

    def _row(label, st, classes=None):
        wr = ("-" if st["win_rate"] is None
              else f"{st['win_rate'] * 100:.1f}%")
        pf = ("-" if st["profit_factor"] is None
              else f"{st['profit_factor']:.2f}")
        row = [label, str(st["trades"]), str(st["wins"]),
               str(st["losses"]), wr, money(st["net_pl"]),
               _m(st["avg_win"]), _m(st["avg_loss"]), pf]
        if args.by != "class":
            row.append(", ".join(f"{k} {n}" for k, n in
                                 (classes or {}).items()) or "-")
        return row
    kind = ("retirement (IRA)" if usa else "registered")
    who = (f"account {account}" + (f" — {kind}, not taxable events"
                                   if sheltered else "")
           if account else _accounts_phrase(sorted(inp["resolved"])))
    head = {"symbol": "TICKER", "account": "ACCOUNT", "month": "MONTH",
            "class": "CLASS"}[args.by]
    from taxjson.lib.out import Doc, act, details_hint
    d = Doc(f"WIN RATES — {scope} ({base}; {who}), by {head.lower()}")
    d.para(f"Economic P/L in {base} before any {rule} denial, not a "
           f"filing number. WIN_RATE = wins / trades; PROFIT_FACTOR = "
           f"gross wins / gross losses"
           + ("; an option under its underlying."
              if args.by == "symbol" else "."))
    headers = [head, "TRADES", "WINS", "LOSSES", "WIN_RATE", "NET_P/L",
               "AVG_WIN", "AVG_LOSS", "PROFIT_FACTOR"]
    aligns = ["<", ">", ">", ">", ">", ">", ">", ">", ">"]
    drop = (6, 7, 8)
    if args.by != "class":
        headers.append("CLASSES")
        aligns.append("<")
        drop = (9, 6, 7, 8)
    if g["rows"]:
        d.table(headers,
                [_row(r["key"], r, r.get("classes")) for r in g["rows"]],
                foot=[_row("TOTAL", g["total"], None)], aligns=aligns,
                drop=drop)
    else:
        d.para("No closed trade in the window.")
    d.blank()
    d.para(f"Denied by the {rule} rule (NOT subtracted above): "
           f"{money(res['denied_total'])} {base} over "
           f"{res['denied_count']} disposition(s).")
    _mv = res["moved_in_kind"]
    if _mv["count"]:
        d.para(f"Moved in kind, not trades (NOT in the table): "
               f"{money(_mv['net_pl'])} {base} of P/L over "
               f"{_mv['count']} move(s), at the value they moved at.")
    acts = []
    if res["tainted_skipped"]:
        acts.append(act(f"{res['tainted_skipped']} disposition(s) with an "
                        f"unknown cost are not counted",
                        "tjs find-missing-history"))
    for w in unmatched:
        acts.append(act(f"{w}: no closed trade on it in the window",
                        "tjs trades"))
    if acts:
        d.blank()
        for a in acts:
            d.item(a[len(_out_act_prefix()):], bullet=_out_act_prefix())
    d.para(details_hint("tjs stats", "the same trades per asset class"))
    d.print()


def _out_act_prefix() -> str:
    from taxjson.lib import out as _out
    return _out.ACT


def cmd_option_yield(args: argparse.Namespace) -> None:
    """`tjs option-yield [UNDERLYING...] [PERIOD] [ACCOUNT] [--json]`:
    how the option trades on an underlying did over a window — premiums
    in and out, the profit or loss of the contracts closed in it and
    how they closed, what is still open, and the yield on the strike
    notional at risk, time-weighted and annualized (lib/option_yield;
    CA-PLAN-07 / US-PLAN-08). The contracts are matched per account and
    series from the native books (work/<acct>_raw.json), every account
    read so a contract opened before the window still closes in it.
    Planning numbers only."""
    from taxjson.lib import markets
    from taxjson.lib import option_yield as OY
    from taxjson.lib.core import is_option_symbol, parse_option_underlying
    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = _soft_settings(root)
    from taxjson.lib.country import engine_sort_profile
    # (refuses a project w/o country)
    split_at_open = engine_sort_profile(_country(settings)) == "ca_main"
    # A contract's size: the project's MULT lines first (`_size`; they
    # were never read here: backlog TJ-0789).
    _use_project_ticker_map(root)
    accounts_cfg = (_soft_config(root).get("accounts") or {})
    # The positionals: a period token, an account name, the rest are
    # underlyings (`option-yield QQQ 1y margin`), in any order.
    period, account, unds = _view_positionals(args.items, accounts_cfg)
    args.period, args.account = period, account
    keep, scope, account = _view_window(args, root)
    if not cache.is_dir():
        _die("no work/ — run `tjs run` first.")
    accounts = ([account] if account else _discover_tx_accounts(cache))
    if account and _native_tx_file(cache, account) is None:
        _die_input(f"no native transaction file for account {account!r} "
                   f"in work/ — run `tjs run` first, or check the name")
    if not accounts:
        _die("no transaction files in work/ — run `tjs run` first")
    if not account:
        _warn_accounts_without_books(root, accounts, "option-yield",
                                     "transaction file")
    rows: List[Tuple[str, Dict[str, Any]]] = []
    first = ""
    # Every account's rows: the contracts are matched per account, and
    # an account filter keeps only that account's contracts.
    for n in _discover_tx_accounts(cache):
        if (accounts_cfg.get(n) or {}).get("crypto"):
            continue
        native = _native_tx_file(cache, n)
        if native is None:
            continue
        _ntx = [t for t in (_load_json_or_die(native).get("transactions")
                            or []) if isinstance(t, dict)]
        for t in _ntx:
            d = str(t.get("date") or "")
            if _ISO_DATE_RE.match(d) and (not first or d < first):
                first = d
            rows.append((n, t))
        # A contract held before the data (a .tt OPENING cost=unknown
        # line): its opening, as the gains stage adds it (audit #59).
        rows += [(n, t) for t in _option_openings(root, _ntx, native=True)]
    today = date_cls.today().isoformat()
    ty = getattr(keep, "tax_year", None)
    if ty:
        start, end = f"{ty}-01-01", f"{ty}-12-31"
    elif period and period.strip().lower() in ("all", "max"):
        start, end = (first or today), today
    elif period:
        start, end = _tx_period_cutoff(period).isoformat(), today
    else:
        start, end = (first or today), today
    # A tax year that has not begun holds nothing yet: its own (empty)
    # window, not today's (the start moved back to today and reported
    # this year's closes under next year's label: backlog TJ-0784).
    future = start > today
    if not future:
        end = min(end, today)
    if start > end:
        start = end

    def _size(t: Dict[str, Any]) -> float:
        sym = str(t.get("symbol") or "").upper()
        ovr = markets.option_contract_size(
            sym, parse_option_underlying(sym) or "")
        return float(ovr) if ovr else OY.default_size(t)

    def _mult_line(sym: str) -> Optional[float]:
        return markets.option_contract_size(
            sym, parse_option_underlying(sym) or "")
    # The books as of the window's end: a later split or rename does
    # not rewrite the window's counts (audit R10).
    # A split takes effect as the country's engine orders it (TJ-0697).
    lots = [] if future else OY.contracts(rows, size_of=_size,
                                          stated_size=_mult_line, through=end,
                                          pool_of=_split_pool_of(root),
                                          split_at_open=split_at_open)
    if future:
        _view_msg("note", f"{scope} has not begun: no contract of the "
                  f"books is in it yet")
    # The underlying's shares held now, per account and the currency of
    # their cost (the native holdings, as div-estimate reads them): the
    # yield's capital, where it is in the options' currency. A CAD cost
    # was added to a USD option's capital as USD (backlog TJ-0543).
    shares: Dict[Tuple[str, str, str], Tuple[float, float]] = {}
    # Holdings whose cost is not all known (an opening cost=unknown):
    # no yield on their partial cost (backlog TJ-0774).
    unknown_shares: Set[Tuple[str, str, str]] = set()
    for n in _discover_tx_accounts(cache):
        if (accounts_cfg.get(n) or {}).get("crypto"):
            continue
        inv = cache / f"{n}_raw_gains.json"
        if not inv.exists():
            continue
        for h in (_load_json_or_die(inv).get("inventory") or []):
            sym = str((h or {}).get("symbol") or "").strip().upper()
            qty = float((h or {}).get("qty") or 0.0)
            if (not sym or qty <= 1e-9 or sym.startswith("CASH.")
                    or is_option_symbol(sym)):
                continue
            hcur = str((h or {}).get("currency") or "").strip().upper()
            q0, c0 = shares.get((n, sym, hcur), (0.0, 0.0))
            shares[(n, sym, hcur)] = (
                q0 + qty, c0 + float((h or {}).get("total_cost") or 0.0))
            if (h or {}).get("unknown_cost"):
                unknown_shares.add((n, sym, hcur))
    # A class share's option root (SYNB for SYN.B.TO) is that share
    # line, as the engines read it (core.class_root_aliases): its
    # shares were not found, so not counted as the capital (backlog
    # TJ-0910).
    from taxjson.lib.core import class_root_aliases
    aliases = class_root_aliases(
        [str(t.get("symbol") or "") for _n, t in rows]
        + [k[1] for k in shares])
    doc = OY.analyze(lots, start=start, end=end, scope=scope,
                     underlyings=unds,
                     accounts=([account] if account else None),
                     groups=_account_group_of(root), shares=shares,
                     unknown_shares=unknown_shares, aliases=aliases)
    if getattr(args, "json", False):
        _json_out(doc)
        return
    # (A message on stderr owes its own blank line: lib/out
    # settling_streams. An unconditional one here was an empty stderr
    # line before every report — workflow audit 2026-10.)
    OY.render(doc).print()

def cmd_dil_sum(args: argparse.Namespace) -> None:
    """Payment-in-lieu summary over a window (default: the tax year):
    DIVIDEND_IN_LIEU rows only — payments received while shares were lent
    out (or short) over the ex-date. Split out from `divs-sum` because
    the tax treatment differs: a payment in lieu is ordinary income (no
    CA gross-up/credit; no US qualified rate) — except, in a Canada
    project, a Canadian dealer's payment on a Canadian issuer's share,
    which ITA s.260 deems a dividend (shown as such, and counted in
    `divs-sum`)."""
    _rules = _view_income_rules(Path(args.dir).resolve())
    rows, scope, bad, _keep = _collect_period_txs(
        args, "dil-sum", actions={"DIVIDEND_IN_LIEU"},
        date_of=_rules.income_date if _rules else None)
    _trusts = _view_trust_units(Path(args.dir).resolve(), _rules)

    money = fmt_money               # shared report-layer formatter

    # Treatment per row (lib/income_dating): Canada — a Canadian
    # dealer's payment on a Canadian issuer's share is a taxable
    # dividend (ITA s.260; T5 box 24, counted in `divs-sum`); every
    # other payment in lieu is ordinary income (US: non-qualified).
    agg: Dict[Tuple[str, str, str], Dict[str, float]] = {}
    totals: Dict[str, float] = {}
    by_treat: Dict[str, Dict[str, float]] = {"dividend": {}, "ordinary": {}}
    # The part of dividend compensation in a cover's cost: no payment
    # in lieu at all, as in `sum` (§263(h); backlog TJ-1066).
    _cap_share = _capitalized_pil_shares(Path(args.dir).resolve() / "work")
    capitalized: Dict[str, float] = {}
    # A registered account's payment in lieu is not income at all: it
    # is its own line, never "ordinary income" (S041-09).
    groups = _account_group_of(Path(args.dir).resolve())
    sheltered: Dict[str, float] = {}
    shel_accts = set()
    for acct, tx in rows:
        cur = tx.get("currency") or "?"
        # Signed: reversal rows (negative) net against the original posting.
        amt = (float(tx.get("gross_amount") or 0.0)
               or float(tx.get("net_amount") or 0.0))
        treat = ("dividend" if _rules is not None
                 and _rules.pil_is_dividend(tx, _trusts) else "ordinary")
        _cap = amt * _cap_share.get((acct, str(tx.get("id"))), 0.0)
        if _cap:
            amt -= _cap
            capitalized[cur] = capitalized.get(cur, 0.0) + _cap
            _crec = agg.setdefault((str(tx.get("symbol") or "?"), cur,
                                    "capitalized"),
                                   {"amount": 0.0, "rows": 0})
            _crec["amount"] += _cap
            _crec["rows"] += 1
            if abs(amt) < 0.005:
                continue
        key = (str(tx.get("symbol") or "?"), cur, treat)
        rec = agg.setdefault(key, {"amount": 0.0, "rows": 0})
        rec["amount"] += amt
        rec["rows"] += 1
        totals[cur] = totals.get(cur, 0.0) + amt
        if groups.get(acct) == "sheltered":
            sheltered[cur] = sheltered.get(cur, 0.0) + amt
            shel_accts.add(acct)
            continue
        by_treat[treat][cur] = by_treat[treat].get(cur, 0.0) + amt
    _warn_bad_dates(bad)
    if getattr(args, "json", False):
        _json_out({"rows": [{"symbol": sym, "currency": cur,
                             "in_lieu": round(rec["amount"], 2),
                             "rows": int(rec["rows"]),
                             "treatment": treat}
                            for (sym, cur, treat), rec
                            in sorted(agg.items())],
                   "totals": {c: round(v, 2) for c, v in totals.items()},
                   "totals_ordinary": {c: round(v, 2) for c, v
                                       in by_treat["ordinary"].items()},
                   "totals_dividend": {c: round(v, 2) for c, v
                                       in by_treat["dividend"].items()},
                   "totals_sheltered": {c: round(v, 2) for c, v
                                        in sheltered.items()},
                   "totals_capitalized": {c: round(v, 2) for c, v
                                          in capitalized.items()},
                   "sheltered_included": sorted(shel_accts),
                   "scope": scope})
        return
    if not agg:
        print(f"No dividends in lieu in {scope}.")
        return
    out_lines = ["SYMBOL CUR IN_LIEU ROWS TREATMENT"]
    for (sym, cur, treat), rec in sorted(agg.items()):
        out_lines.append(" ".join([
            sym, cur, money(rec["amount"]), str(int(rec["rows"])),
            {"dividend": "dividend(s.260)",
             "capitalized": "capitalized(§263(h))"}.get(treat, "ordinary")]))
    _vprint(f"DIVIDENDS IN LIEU — {scope}")
    if by_treat["dividend"]:
        _vprint("Payments in lieu are ordinary income, except a Canadian "
                "dealer's payment on a Canadian issuer's share: a taxable "
                "dividend under ITA s.260, on the T5 and in `divs-sum`; "
                "the slip is authoritative.")
    else:
        _vprint("Payments in lieu are ordinary income: no dividend "
                "gross-up/credit or qualified rate.")
    if capitalized:
        _vprint("Capitalized: dividend compensation paid on a short sale "
                "closed within 45 days is the cover's cost (§263(h)), not "
                "a payment in lieu; `tjs sum` and the total below leave "
                "it out.")
    print()
    _print_report_table(out_lines, fit=True, drop=(3,))

    def _tot(d):
        return ", ".join(f"{money(v)} {c}" for c, v in sorted(d.items()))
    if by_treat["dividend"] or shel_accts:
        print()
        _vprint(f"ORDINARY INCOME: {_tot(by_treat['ordinary']) or '0.00'}",
                hang="  ")
    if by_treat["dividend"]:
        _vprint(f"DEEMED DIVIDENDS (s.260, in divs-sum): "
                f"{_tot(by_treat['dividend'])}", hang="  ")
    if shel_accts:
        _vprint(f"SHELTERED ({', '.join(sorted(shel_accts))} — not taxable "
                f"income): {_tot(sheltered)}", hang="  ")
    if capitalized:
        print()
        _vprint(f"{_CAPITALIZED_LBL} {_tot(capitalized)}", hang="  ")
    print()
    _vprint(f"TOTAL DIVIDEND IN LIEU"
            + (" (all accounts)" if shel_accts else "")
            + f": {_tot(totals) or '0.00'}", hang="  ")


def cmd_roc_sum(args: argparse.Namespace) -> None:
    """Return-of-capital summary over a window (default: the tax year):
    per ticker, the capital returned (= ACB reduced) with broker-classified
    vs manual row counts, plus per-currency totals. Reads ADJUST rows —
    broker-classified ROC carries type='roc'; a manual row is a .tt line
    (e.g. a T3 box 42 entry, `type=roc` or not: backlog TJ-0427) or a
    typeless ADJUST. An ADJUST that is no return of capital
    (a reinvested distribution, a spin-off's cost allocation:
    income_dating.is_return_of_capital) is listed apart, outside the
    totals compared with T3 box 42 (2026-10-23 audit #5, #11)."""
    from taxjson.lib.income_dating import is_return_of_capital
    # A Canadian trust's ROC counts in the year it became payable (its
    # record date, lib/income_dating — the year of T3 box 42).
    _rules = _view_income_rules(Path(args.dir).resolve())
    rows, scope, bad, _keep = _collect_period_txs(
        args, "roc-sum", actions={"ADJUST"},
        date_of=_rules.roc_date if _rules else None)
    _root = Path(args.dir).resolve()
    _accts = sorted({a for a, _t in rows}
                    | set(_discover_tx_accounts(_root / "work")))
    _acct_arg = _view_window(args, _root)[2]
    if _acct_arg:
        _accts = [_acct_arg]
    dist_rows = _dist_adjust_rows(_root / "work", _accts, _keep)
    _warn_dist_double_entry(_root, _accts, _rules, _keep, "roc-sum")
    rows = list(rows) + dist_rows

    money = fmt_money               # shared report-layer formatter

    agg: Dict[Tuple[str, str], Dict[str, float]] = {}
    totals: Dict[str, float] = {}
    # Registered accounts have no ACB to track and get no T3: the total
    # a user ties to T3 box 42 is the TAXABLE one (S041-10), the same
    # scope as the checklist's roc-entered step.
    groups = _account_group_of(_root)
    by_group: Dict[str, Dict[str, float]] = {"taxable": {},
                                             "sheltered": {}}
    shel_accts = set()
    other: List[Dict[str, Any]] = []
    for acct, tx in rows:
        cur = tx.get("currency") or "?"
        if not is_return_of_capital(tx):
            _dist = str(tx.get("id") or "").startswith("DIST-")
            other.append({"account": acct,
                          "symbol": str(tx.get("symbol") or "?"),
                          "currency": cur,
                          "date": str((tx.get("date_settle") if _dist
                                       else None)
                                      or tx.get("date") or "")[:10],
                          "acb_change": float(tx.get("net_amount") or 0.0),
                          "kind": _adjust_kind(tx)})
            continue
        _g = groups.get(acct)
        if _g:
            _r = -float(tx.get("net_amount") or 0.0)
            by_group[_g][cur] = by_group[_g].get(cur, 0.0) + _r
            if _g == "sheltered":
                shel_accts.add(acct)
        # ADJUST net_amount is the ACB delta (negative = reduction).
        # Present as capital RETURNED, so a normal ROC posting is
        # positive; negative values are reversals / manual ACB increases.
        returned = -float(tx.get("net_amount") or 0.0)
        key = (str(tx.get("symbol") or "?"), cur)
        rec = agg.setdefault(key, {"returned": 0.0, "roc_rows": 0,
                                   "manual_rows": 0, "dist_rows": 0})
        rec["returned"] += returned
        _typ = (tx.get("type") or "").lower()
        if _typ == "dist" and str(tx.get("id") or "").startswith("DIST-"):
            rec["dist_rows"] += 1
        elif str(tx.get("source") or "").lower().endswith(".tt"):
            # A line typed into a .tt file (a T3's box 42, the line
            # slip-audit suggests), `type=roc` or not: manual, never the
            # broker's (backlog TJ-0427).
            rec["manual_rows"] += 1
        elif _typ in ("roc", "dist"):
            # Broker-classified: a ROC, or RBC's notional distribution
            # (type 'dist' in the native book, not a map row — A2-0116).
            rec["roc_rows"] += 1
        else:
            rec["manual_rows"] += 1
        totals[cur] = totals.get(cur, 0.0) + returned
    _warn_bad_dates(bad)
    if getattr(args, "json", False):
        _json_out({"rows": [{"symbol": sym, "currency": cur,
                             "capital_returned": round(rec["returned"], 2),
                             "roc_rows": int(rec["roc_rows"]),
                             "manual_rows": int(rec["manual_rows"]),
                             "dist_rows": int(rec["dist_rows"])}
                            for (sym, cur), rec in sorted(agg.items())],
                   "totals": {c: round(v, 2) for c, v in totals.items()},
                   "totals_taxable": {c: round(v, 2) for c, v
                                      in by_group["taxable"].items()},
                   "totals_sheltered": {c: round(v, 2) for c, v
                                        in by_group["sheltered"].items()},
                   "sheltered_included": sorted(shel_accts),
                   "other_adjustments": [
                       dict(o, acb_change=round(o["acb_change"], 2))
                       for o in other],
                   "scope": scope})
        return
    # Each country's own slip and cost word (A2-0735): a US fund's
    # nondividend distribution is 1099-DIV box 3 and reduces basis.
    _us = _country(_soft_settings(_root)) == "usa"
    _cw = "basis" if _us else "ACB"
    _slip = "1099-DIV box 3" if _us else "T3 box 42"
    if not agg and not other:
        print(f"No {_cw} adjustments in {scope}.")
        return
    if not agg:
        print(f"No return of capital in {scope}.")
        _roc_sum_other(other, _cw, _slip)
        return
    out_lines = ["SYMBOL CUR CAPITAL_RETURNED ROC_ROWS MANUAL_ROWS "
                 "MAP_ROWS"]
    for (sym, cur), rec in sorted(agg.items()):
        out_lines.append(" ".join([sym, cur, money(rec["returned"]),
                                   str(rec["roc_rows"]),
                                   str(rec["manual_rows"]),
                                   str(rec["dist_rows"])]))
    _vprint(f"RETURN OF CAPITAL / {_cw.upper()} ADJUSTMENTS — {scope}")
    print()
    _print_report_table(out_lines, fit=True, drop=(5, 4, 3))
    def _tot(d):
        return ", ".join(f"{money(v)} {c}" for c, v in sorted(d.items()))
    print()
    if shel_accts:
        _vprint(f"TAXABLE (compare with {_slip}): "
                f"{_tot(by_group['taxable']) or '0.00'}", hang="  ")
        _vprint(f"SHELTERED ({', '.join(sorted(shel_accts))} — no {_cw} "
                f"to track, no {'1099-DIV' if _us else 'T3'}): "
                f"{_tot(by_group['sheltered'])}", hang="  ")
        _vprint(f"TOTAL CAPITAL RETURNED (all accounts): {_tot(totals)}",
                hang="  ")
    else:
        _vprint(f"TOTAL CAPITAL RETURNED ({_cw} reduced): {_tot(totals)}",
                hang="  ")
    _roc_sum_other(other, _cw, _slip)
    print()
    for item in (f"Positive = {_cw} reduced (capital returned). Negative "
                 f"rows are reversals or manual {_cw} increases (MAP_ROWS: "
                 f"[[distributions]] return-of-capital entries).",
                 f"Enter fund ROC from your {_slip} as .tt ADJUST lines OR "
                 f"as [[distributions]] in taxjson.toml, never both — see "
                 f"docs/tax-rules.md, \"Return of capital\"."):
        _vprint(item, indent="- ", hang="  ")


def _adjust_kind(tx: Dict[str, Any]) -> str:
    """What an ADJUST that is no return of capital is, in a few words
    (roc-sum's OTHER table)."""
    typ = str(tx.get("type") or "").lower()
    up = float(tx.get("net_amount") or 0.0) > 0
    if typ == "dist":
        if str(tx.get("id") or "").startswith("DIST-"):
            return ("reinvested distribution ([[distributions]])" if up
                    else "[[distributions]] entry")
        return "notional distribution" if up else "distribution"
    if tx.get("corp_event_id") or typ == "spinoff_355":
        el = str(tx.get("corp_election") or "")
        return (f"spin-off cost allocation ({el})" if el
                else "spin-off cost allocation")
    if str(tx.get("id") or "").startswith(("WASH_", "HANDOFF_WASH_")):
        return "deferred loss"
    return typ or "adjustment"


def _roc_sum_other(other: List[Dict[str, Any]], cw: str,
                   slip: str) -> None:
    """roc-sum: the ADJUST rows that are no return of capital — a
    reinvested or notional distribution raises the cost, a spin-off
    moves part of it to the new shares — each with its kind, outside
    the totals compared with the slip."""
    if not other:
        return
    from taxjson.lib.out import fit_table
    print()
    _vprint(f"OTHER {cw.upper()} ADJUSTMENTS (not a return of capital, not "
            f"in {slip}; + = {cw} raised)", hang="  ")
    print()
    body = [[o["symbol"], o["currency"], o["date"],
             f"{o['acb_change']:+,.2f}", o["kind"]]
            for o in sorted(other, key=lambda o: (o["symbol"], o["date"]))]
    for ln in fit_table(["SYMBOL", "CUR", "DATE", f"{cw.upper()}_CHANGE",
                         "KIND"], body, drop=(2,)):
        print(ln)


def cmd_trades_sum(args: argparse.Namespace) -> None:
    """Trade summary over a window (default: the tax year): per ticker, the
    buy/sell counts, value bought/sold, and fees, plus per-currency totals.
    `PERIOD` is 30d/6w/3m/1y/all; omit it for the tax year."""
    rows, scope, bad, _keep = _collect_period_txs(
        args, "trades-sum", actions={"BUYSELL", "ASSIGN"},
        settle_trades=True)

    money = fmt_money               # shared report-layer formatter

    agg: Dict[Tuple[str, str], Dict[str, float]] = {}
    tot_bought: Dict[str, float] = {}
    tot_sold: Dict[str, float] = {}
    tot_fees: Dict[str, float] = {}
    # The SOLD total pooled registered accounts with no word: it is not
    # the T5008 figure, which covers taxable accounts only (S041-12).
    groups = _account_group_of(Path(args.dir).resolve())
    tax_sold: Dict[str, float] = {}
    shel_accts = set()
    for acct, tx in rows:
        cur = tx.get("currency") or "?"
        q = float(tx.get("quantity") or 0.0)
        amt = _trade_total(tx)          # sells signed (S039-11)
        fee = _tx_fee(tx)
        if groups.get(acct) == "sheltered":
            shel_accts.add(acct)
        elif q < 0:
            tax_sold[cur] = tax_sold.get(cur, 0.0) + amt
        d = agg.setdefault((str(tx.get("symbol") or "?"), cur),
                           {"buys": 0, "sells": 0, "bought": 0.0, "sold": 0.0,
                            "fees": 0.0})
        if q > 0:
            d["buys"] += 1
            d["bought"] += amt
            tot_bought[cur] = tot_bought.get(cur, 0.0) + amt
        elif q < 0:
            d["sells"] += 1
            d["sold"] += amt
            tot_sold[cur] = tot_sold.get(cur, 0.0) + amt
        d["fees"] += fee
        tot_fees[cur] = tot_fees.get(cur, 0.0) + fee
    _warn_bad_dates(bad)
    for _tot_d, _k in ((tot_bought, "bought"), (tot_sold, "sold"),
                       (tot_fees, "fees")):
        _tot_d.clear()
        _tot_d.update(_foot_by_currency((cur, d[_k]) for (_s, cur), d
                                        in agg.items()))
    if getattr(args, "json", False):
        _json_out({"rows": [dict(d, symbol=sym, currency=cur,
                                 buys=int(d["buys"]), sells=int(d["sells"]))
                            for (sym, cur), d in sorted(agg.items())],
                   "totals": {c: {"bought": round(tot_bought.get(c, 0.0), 2),
                                  "sold": round(tot_sold.get(c, 0.0), 2),
                                  "fees": round(tot_fees.get(c, 0.0), 2)}
                              for c in sorted(set(tot_bought) | set(tot_sold)
                                              | set(tot_fees))},
                   "sold_taxable": {c: round(v, 2)
                                    for c, v in tax_sold.items()},
                   "sheltered_included": sorted(shel_accts),
                   "scope": scope})
        return
    if not agg:
        print(f"No trades in {scope}.")
        return
    out_lines = ["SYMBOL CUR BUYS SELLS BOUGHT SOLD FEES"]
    for (sym, cur), d in sorted(agg.items()):
        out_lines.append(" ".join([
            sym, cur, str(int(d["buys"])), str(int(d["sells"])),
            money(d["bought"]), money(d["sold"]), money(d["fees"])]))
    _vprint(f"TRADES — {scope}")
    print()
    _print_report_table(out_lines, fit=True, drop=(6, 2, 3))
    curs = sorted(set(tot_bought) | set(tot_sold) | set(tot_fees))
    print()
    for c in curs:
        _vprint(f"TOTAL {c}: bought {money(tot_bought.get(c, 0.0))}, "
                f"sold {money(tot_sold.get(c, 0.0))}, "
                f"fees {money(tot_fees.get(c, 0.0))}", hang="  ")
    if shel_accts:
        # A US project's sheltered accounts are IRAs (A2-0735).
        from taxjson.lib.country import CountryError, settings_country
        try:
            _usa_t = settings_country(_soft_settings(
                Path(args.dir).resolve())) == "usa"
        except CountryError:
            _usa_t = False
        _kind = "retirement (IRA)" if _usa_t else "registered"
        _vprint(f"SOLD IN TAXABLE ACCOUNTS: "
                + (", ".join(f"{money(v)} {c}" for c, v
                             in sorted(tax_sold.items())) or "0.00")
                + f"  (the totals include the {_kind} "
                f"{', '.join(sorted(shel_accts))})", hang="  ")


def _real_world_legs(t: dict) -> Tuple[float, float]:
    """(proceeds, cost) as a person reads them: a SHORT row carries the
    engine's signed legs (cost = -premium/-short proceeds, proceeds =
    -buy-back/-cover), so its columns read negative and swapped. The
    views show what ccd-sum, winners and form-export show — proceeds
    = what the short brought in, cost = what closing it cost (S048-10,
    S040-14)."""
    proceeds = float(t.get("proceeds") or 0.0)
    cost = float(t.get("cost") or 0.0)
    if t.get("direction") == "SHORT":
        return -cost + 0.0, -proceeds + 0.0
    return proceeds, cost


def _gain_display_line(g: dict) -> str:
    """A realized-gain (disposition) row for `tjs gains`: money columns
    (proceeds/cost/gain) to 2 decimals, quantity keeps significant digits.
    A short row's legs are shown the real-world way (_real_world_legs)."""
    money = fmt_money               # shared report-layer formatter

    def sig(x):
        s = f"{float(x or 0):.8f}".rstrip("0").rstrip(".")
        return "0" if s in ("", "-", "-0") else s

    days = g.get("days_held")
    _p, _c = _real_world_legs(g)
    return " ".join([
        g.get("date", ""), g.get("symbol", ""), sig(g.get("qty")),
        g.get("currency") or "?", money(_p),
        money(_c), money(g.get("gain")),
        "" if days is None else str(days),
    ])


def cmd_gains(args: argparse.Namespace) -> None:
    """Realized gains in NATIVE terms (pre-TOBASE consolidation, pre-currency-
    to-base) — read from the pipeline's `<account>_raw_gains.json`."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    keep, _scope, account = _view_window(args, root)
    suffix = "_raw_gains.json"

    # Income rows carry an action; dispositions are everything else. Excluding
    # the known income actions (rather than requiring action is None) keeps
    # working if the engine ever tags dispositions with an action.
    _INCOME = {"DIVIDEND", "DIVIDEND_IN_LIEU", "TAX", "INTEREST", "FEE",
               "DISALLOW", "ADJUST"}
    sym_filter = _instrument_filter(args)

    if account:
        accounts = [account]
        if not (cache / f"{account}{suffix}").exists():
            if (cache / f"{account}_base.json").exists():
                _die(f"no native gains for account {account!r}",
                     "Crypto accounts have none, and an equity account's "
                     "native books are skipped after a cross-currency "
                     "rollover rename (see the run's 'raw holdings "
                     "skipped' line) — rerunning will not create them; "
                     "its converted gains are in `tjs sum`.")
            _die_input(f"no native gains for account {account!r} in work/",
                       "Crypto has none; else run `tjs run`, or check the "
                       "name.")
    else:
        accounts = sorted(p.name[: -len(suffix)]
                          for p in cache.glob(f"*{suffix}")
                          if not p.name.startswith("."))
        # A configured equity account with converted books but no native
        # gains had its raw stage skipped (a cross-currency rollover
        # rename): say so, or the view silently omits the whole account
        # while `sum` counts it (2026-09 audit S037-23).
        _noted = []
        for _n, _c in sorted((_soft_config(root).get("accounts")
                              or {}).items()):
            if (isinstance(_c, dict) and _c.get("crypto")
                    and _n not in accounts
                    and (cache / f"{_n}_base.json").exists()):
                _noted.append(_n)
                # The all-accounts view left the crypto account out
                # with no word while `sum` counted it (R1-274).
                _view_msg("note", f"crypto account {_n!r} is not shown "
                          f"(crypto has no native-currency gains)",
                          "Its gains are in `tjs sum` / `tjs "
                          "winners`.")
            elif (isinstance(_c, dict) and not _c.get("crypto")
                    and _n not in accounts
                    and (cache / f"{_n}_base.json").exists()):
                _noted.append(_n)
                _view_msg("note", f"account {_n!r} has no native gains",
                          "The last run skipped its native books (see its "
                          "'raw holdings skipped' line); its converted "
                          "gains are in `tjs sum` / `tjs "
                          "winners`.")
        if not accounts and not _noted:
            _die_input("no native gains files in work/ — run `tjs run` "
                       "first")
        # S045-09 twin (audit A2-1182): accounts with books are named by
        # the notes above; one with inputs but no books at all is not.
        _warn_accounts_without_books(
            root, set(accounts) | {
                n for n in (_soft_config(root).get("accounts") or {})
                if (cache / f"{n}_base.json").exists()},
            "gains", "books")
        if not accounts:
            # Every account with books was named above (crypto only, or
            # native books skipped): nothing to show, and no run to ask
            # for — a run cannot make them (backlog TJ-0130).
            return

    rows = []
    bad_dates = 0
    manual = 0
    for acct in accounts:
        f = cache / f"{acct}{suffix}"
        if not f.exists():
            _view_msg("note", f"no native gains for account {acct!r} "
                      f"(crypto has only base-converted gains); skipping "
                      f"it.")
            continue
        data = _load_json_or_die(f)
        _settle = _settle_basis(root, data)
        # Missing-history sales (bought before the data) are routed out of
        # the gains, as in `sum`: count them so the view says so (audit
        # A2-0305).
        for g in data.get("manual_reporting_required") or []:
            if sym_filter is not None and not sym_filter(g.get("symbol") or ""):
                continue
            d = _gains_row_date(g, keep, _settle)
            if _ISO_DATE_RE.match(d) and keep(d):
                manual += 1
        for g in data.get("transactions", []):
            if g.get("action") in _INCOME:
                continue
            if sym_filter is not None and not sym_filter(g.get("symbol") or ""):
                continue
            d = _gains_row_date(g, keep, _settle)
            if not _ISO_DATE_RE.match(d):
                bad_dates += 1
                continue
            if keep(d):
                rows.append((d, acct, g))

    if bad_dates:
        _view_msg("warning", f"{bad_dates} gain row(s) had a "
                  f"missing/unparseable date and were excluded.")
    if manual:
        _view_msg("note", f"{manual} sale(s) with unknown cost are not "
                  f"shown",
                  "Shares bought before the data (.tt OPENING cost=unknown): "
                  "their basis is unknown; `tjs form-export` lists "
                  "them for manual reporting.")
    rows.sort(key=lambda r: (r[0], r[1]))
    if getattr(args, "json", False):
        jt: Dict[str, float] = {}
        for _d, _acct, g in rows:
            cur = g.get("currency") or "?"
            jt[cur] = jt.get(cur, 0.0) + float(g.get("gain") or 0.0)
        _json_out({"rows": [dict(g, account=acct) for _d, acct, g in rows],
                   "totals": jt})
        return
    if not rows:
        print("(no realized gains in this window)")
        return
    prefix = len(accounts) != 1

    _vprint("REALIZED GAINS — native currency, per account, pre-wash")
    _vprint("Before the base-currency conversion; the filing figures: "
            "tjs sum.")
    header = (["ACCT"] if prefix else []) + \
        ["DATE", "SYMBOL", "QTY", "CUR", "PROCEEDS", "COST", "GAIN", "DAYS"]
    out_lines = [" ".join(header)]
    totals: Dict[str, float] = {}
    for _d, acct, g in rows:
        line = _gain_display_line(g)
        out_lines.append(f"{acct} {line}" if prefix else line)
        cur = g.get("currency") or "?"
        totals[cur] = totals.get(cur, 0.0) + float(g.get("gain") or 0.0)

    # Too wide: DAYS, then the proceeds and the cost go first.
    _o = 1 if prefix else 0
    _print_report_table(out_lines, fit=True,
                        drop=(7 + _o, 4 + _o, 5 + _o),
                        key=(0, 1, 2) if prefix else (0, 1))
    print()
    _vprint("TOTAL GAIN: " + ", ".join(
        f"{v:,.2f} {c}" for c, v in sorted(totals.items())), hang="  ")


# One per-country plan table (lib/country.PLAN_COUNTRY): the HSA, LIF,
# RDSP ... its missing_history twin knew were missing, and the other
# country's plans were accepted silently (audit A2-0739, A2-1272,
# A2-1332).
from taxjson.lib.country import PLAN_COUNTRY as _PLAN_COUNTRY
from taxjson.lib.country import plan_kinds as _plan_kinds
_PLAN_NAMES = tuple(k for k in _PLAN_COUNTRY
                    if k not in ("taxable", "sheltered"))
_PLAN_KINDS = tuple(_PLAN_COUNTRY)


def _ptype_conflict(acfg: Dict[str, Any]) -> bool:
    """A registered plan on a taxable account, or plan = "taxable" on a
    sheltered one (audit A2-1332): tips read the plan and skipped
    the account's checks."""
    plan = str(acfg.get("plan") or "").strip().lower()
    typ = acfg.get("type")
    if plan in ("", "sheltered"):
        return plan == "sheltered" and typ == "taxable"
    if plan == "taxable":
        return typ == "sheltered"
    return plan in _PLAN_NAMES and typ == "taxable"


def _account_plan(name: str, acfg: Dict[str, Any],
                  country: Optional[str] = None) -> str:
    """Registered-plan kind for the tips checks: explicit `plan = "tfsa"` in
    taxjson.toml wins (an unknown value is ignored — validate_config
    warns); else inferred from a plan word that is a whole TOKEN of the
    account NAME (the init scaffold names folders tfsa/rrsp/...; `rrsp2`
    and `my-tfsa` count, `admiral` and `spiral` no longer read as an IRA
    and silently skipped the US-LISTING check, R1-243); else the type."""
    # Only the project country's plans count, and a taxable account is
    # taxable whatever its plan says (tips skipped one with plan =
    # "401k"; validate_config warns on the contradiction, the other
    # country's plan is refused — audit A2-0739, A2-1332).
    kinds = _plan_kinds(country) if country else list(_PLAN_KINDS)
    if acfg.get("type") == "taxable":
        return "taxable"
    explicit = str(acfg.get("plan") or "").strip().lower()
    if explicit in kinds:
        return explicit
    low = name.lower()
    for p in _PLAN_NAMES:
        if p in kinds and re.search(
                rf"(?<![a-z]){re.escape(p)}(?![a-z])", low):
            return p
    return "sheltered"


# Boilerplate an exchange appends to a listing's name that carries no
# issuer identity — dropped before comparing names across listings.
_ISSUER_NOISE = frozenset(
    "INC INCORPORATED CORP CORPORATION LTD LIMITED CO COMPANY PLC LP "
    "THE NEW CLASS CL A B C COM COMMON ORDINARY SHARES SHS STOCK "
    "SUBORDINATE VOTING NON RESTRICTED SV MV NPV ADR ADS UNITS UNIT "
    "TRUST FUND ETF INDEX INCOME REIT DEPOSITARY RECEIPT".split())


def _norm_issuer_name(name: str) -> str:
    """Issuer name reduced to its identity tokens, order kept:
    'B2Gold Corp.' -> 'B2GOLD', 'The Toronto-Dominion Bank' ->
    'TORONTO DOMINION BANK'. Empty when nothing survives."""
    import re as _re
    tokens = _re.sub(r"[^A-Za-z0-9 ]", " ", name.upper()).split()
    return " ".join(t for t in tokens if t not in _ISSUER_NOISE)


def _is_cdr_name(name: str) -> bool:
    """Exchange name says Canadian Depositary Receipt — a fractional,
    CAD-hedged receipt over a US share, NOT a listing equivalent (the
    receipt ratio floats with the hedge, so no static TOBASE ratio can
    ever be right)."""
    up = f" {name.upper()} "
    return (" CDR " in up or "(CDR)" in up.replace("( ", "(")
            or "CANADIAN DEPOSITARY" in up or "CAD HEDGED" in up
            or "CAD-HEDGED" in up)


def _issuer_names_match(a: str, b: str) -> bool:
    """Same issuer? Both names normalized; equal, or one a prefix of
    the other with the longer adding at most ONE token ('AGNICO
    EAGLE' vs 'AGNICO EAGLE MINES' matches; 'BROOKFIELD CORPORATION'
    vs 'BROOKFIELD RENEWABLE PARTNERS' does not). KNOWN LIMIT: a
    distinct issuer differing by exactly one meaningful token
    ('...ASSET MANAGEMENT' vs '...ASSET MANAGEMENT REINSURANCE' after
    noise-stripping) still matches — a MAP-BAD? finding says VERIFY,
    so false negatives are cheaper than false alarms."""
    na, nb = _norm_issuer_name(a), _norm_issuer_name(b)
    if not na or not nb:
        return True          # no evidence — do not accuse the map
    if na == nb:
        return True
    ta, tb = na.split(), nb.split()
    short, long_ = (ta, tb) if len(ta) <= len(tb) else (tb, ta)
    # Multi-token prefix ('AGNICO EAGLE' vs 'AGNICO EAGLE MINES'):
    # same issuer — but only when the longer name adds at most ONE
    # token. Issuer FAMILIES extend a shared prefix by several
    # ('BROOKFIELD ASSET MANAGEMENT' vs 'BROOKFIELD ASSET MANAGEMENT
    # REINSURANCE PARTNERS' are different companies — round-five
    # audit finding 7).
    return (len(short) >= 2 and len(long_) - len(short) <= 1
            and long_[:len(short)] == short)


def cmd_tips(args: argparse.Namespace) -> None:
    """`tjs tips`: advice for next year — where you hold what costs
    tax it need not. It changes no number of this year. Canada checks
    today:

      US-LISTING   a cross-listed CANADIAN issuer (a ticker.map join, or
                   a same-root Canadian listing the exports do not show
                   apart — "verify" unless the names agree) held via its
                   US line in a taxable account or TFSA while receiving
                   dividends — USD dividend conversion drag, and brokers
                   can misclassify the payment; the .TO line gives clean
                   eligible-dividend treatment.
      TFSA-US-DIV  a US-domiciled dividend payer inside a TFSA — the 15%
                   US withholding is unrecoverable there (an RRSP is
                   treaty-exempt; a taxable account can claim the FTC).
                   The domicile is a ticker.map T1135 line, the ISIN's
                   country or tobase.map's, never the listing alone; a
                   US-listed payer with none is flagged as a condition
                   (backlog TJ-0562).

    With --online (Yahoo Finance; candidates to verify, not verdicts):
    MAP-GAP? — a .TO twin of a US-listed dividend payer the map doesn't
    know, and held listings clustered by issuer name to catch
    DIFFERENT-root dual listings (SAMPLQ.US/SAMPLP.TO); MAP-BAD? — a
    defined map pair whose two sides name different issuers; CDR-PAIR —
    a .TO line whose exchange name says CDR (Canadian Depositary Receipt
    — SAMPLR.TO over SAMPLR.US): the SAME issuer but NOT a listing
    equivalent (fractional, CAD-hedged, floating ratio) — never map it;
    nothing to do: look-alike listings are never joined.

    The map's own hygiene is `tjs ticker-map --suggest`: a loss on
    one listing with the other bought in its window (lib/
    xlist_loss_radar), a same-root listing pair the map does not answer
    (MAP-GAP, lib/map_hygiene.map_gaps) and the rules no symbol reaches
    (lib/map_hygiene.unused_rules).

    Exit 0 with or without tips (advice never fails a command); 2 when
    the project cannot be read (no holdings reports, a damaged report or
    book, an account left unread)."""
    import json
    from taxjson.lib import map_hygiene as _MH
    root = Path(args.dir).resolve()
    cache = root / "work"
    reports = root / "reports"
    cfg = load_config(root)
    settings = cfg.get("settings", {})
    country = _country(settings)
    accounts = cfg.get("accounts", {}) or {}
    if not accounts:
        _die_input("no accounts in taxjson.toml.")

    # Per-listing positions (holdings.toml is built PRE-TOBASE, so the
    # US/TO line actually held is visible — the gains inventory is
    # already consolidated and would hide it).
    holdings: Dict[str, list] = {}
    # Accounts tips cannot read (no holdings report / raw book): "no
    # tips" over them was a false all-clear (re-audit A2-0404).
    _skipped_no_inputs = _accounts_skipped_for_no_inputs(root)
    unscanned: Dict[str, str] = {}
    for name in accounts:
        if (accounts.get(name) or {}).get("crypto"):
            # Coins have no listings to compare: a crypto account's
            # holdings report is not a cross-listing sighting.
            continue
        f = reports / f"{name}_holdings.toml"
        if not f.exists() or tomllib is None:
            if (tomllib is not None and name not in _skipped_no_inputs
                    and _has_inputs(root, name)):
                unscanned[name] = f"reports/{f.name}"
            continue
        try:
            _hl = (tomllib.loads(f.read_text(encoding="utf-8"))
                   .get("holding", []))
            # `holding = "x"` or a quantity "abc" was an AttributeError
            # / ValueError traceback further down (re-audit A2-0792).
            if not isinstance(_hl, list) \
                    or any(not isinstance(h, dict) for h in _hl):
                raise ValueError("`holding` is not a list of [[holding]] "
                                 "tables")
            for h in _hl:
                float(h.get("quantity", 0) or 0)
            holdings[name] = _hl
        except Exception as e:
            # A warning, then a clean report and exit 0 turned an
            # unreadable report into a false all-clear: the findings on
            # that account's positions vanished (S049-10).
            _die_input(f"could not read reports/{f.name}: {e}",
                       "Re-run `tjs run` to rebuild it (tips would "
                       "otherwise leave that account's positions out).")
    _equity_accts = [n for n, c in accounts.items()
                     if not (c or {}).get("crypto")]
    if not holdings and _equity_accts:
        # A clean report (exit 0) over books it read nothing of was a
        # false all-clear (2026-09 CLI audit B22).
        if set(_equity_accts) <= _accounts_skipped_for_no_inputs(root):
            _die_input("no account has any input yet — nothing to check.",
                       "Drop broker CSVs into inputs/<account>/ and "
                       "`tjs run`.")
        _die_input("no holdings reports in reports/ — nothing was checked",
                   "Run `tjs run` first (tips read the per-listing "
                   "positions).")

    # Dividend payers, per raw (pre-consolidation) symbol.
    div_syms: set = set()
    isin_country: Dict[str, set] = {}
    for name in accounts:
        f = cache / f"{name}_raw.json"
        if not f.exists():
            if (name not in _skipped_no_inputs
                    and not (accounts.get(name) or {}).get("crypto")
                    and _has_inputs(root, name)):
                unscanned.setdefault(name, f"work/{f.name}")
            continue
        # A truncated raw book turned a real finding into a clean report
        # with exit 0 (audit S042-05).
        try:
            data = _read_work_doc(f)
        except (OSError, ValueError) as e:
            _die_input(f"could not read {f}: {e}",
                       "Re-run `tjs run` (tips would otherwise leave "
                       "that file's rows out).")
        for t in data.get("transactions", []):
            if t.get("action") in ("DIVIDEND", "DIVIDEND_IN_LIEU"):
                _ds = str(t.get("symbol") or "").upper()
                # A dividend-in-lieu PAID (a short's charge, negative)
                # is an expense, not a dividend received (backlog
                # TJ-0914).
                try:
                    _amt = (float(t.get("gross_amount") or 0)
                            or float(t.get("net_amount") or 0))
                except (TypeError, ValueError):
                    _amt = 0.0
                if not (t.get("action") == "DIVIDEND_IN_LIEU"
                        and _amt < 0):
                    div_syms.add(_ds)
                # The issuer's country the export's ISIN gives (IB):
                # domicile evidence beyond the listing (backlog TJ-0562).
                _ic = str(t.get("issuer_country") or "").upper()
                if _ic:
                    isin_country.setdefault(_ds, set()).add(_ic)

    # ticker.map consolidations (GLOBAL + TOBASE + JOURNAL) and the
    # user's declared-distinct pairs (CDRs etc. — see DISTINCT).
    renames: Dict[str, str] = {}
    glob_renames: Dict[str, str] = {}
    distinct_pairs: set = set()
    map_file = _PL.ticker_map_path(root)
    if map_file.exists():
        try:
            from taxjson.bin.taxjson_ticker_map import (load_map_file,
                                                        merge_renames)
            _tmap = load_map_file(map_file)
            renames = merge_renames(_tmap, to_base=True)
            glob_renames = merge_renames(_tmap, to_base=False)
            distinct_pairs = {frozenset(s.upper() for s in pair)
                              for pair in _tmap.distinct}
        except Exception as e:
            from taxjson.lib.out import warn as _warn
            _warn(f"could not read ticker.map: {e}", prog="tjs tips")
    renames_u = {k.upper(): v.upper() for k, v in renames.items()}

    # The issuer's domicile, never the listing alone (a US listing of a
    # Canadian issuer is no US dividend payer: backlog TJ-0562): the
    # project's declaration (a ticker.map `T1135 SYMBOL COUNTRY` line),
    # else the export's ISIN country, else tobase.map's (the interlisted
    # master's domicile of an issuer it books under its US listing).
    t1135_dom: Dict[str, str] = {}
    master_dom: Dict[str, str] = {}
    if map_file.exists():
        try:
            from taxjson.lib.ticker_map import read_side_rules
            t1135_dom = {str(k).upper(): str(v).upper() for k, v
                         in read_side_rules(map_file).t1135.items()}
        except Exception:                                  # noqa: BLE001
            t1135_dom = {}      # (run refuses the map, naming the line)
        try:
            from taxjson.lib.tobase_map import t1135_countries
            master_dom = {str(k).upper(): str(v).upper() for k, v
                          in t1135_countries(map_file).items()}
        except Exception:                                  # noqa: BLE001
            master_dom = {}

    def _domicile(sym_u: str) -> Optional[str]:
        """"USA", another country ("CAN": Canada, or a T1135 line's
        not-foreign word), or None when nothing in the project says."""
        for s in dict.fromkeys((sym_u, renames_u.get(sym_u, sym_u))):
            v = t1135_dom.get(s)
            if v:
                return "CAN" if v == "CA" else v
        ic = isin_country.get(sym_u) or set()
        if len(ic) == 1:
            c = next(iter(ic))
            return {"US": "USA", "CA": "CAN"}.get(c, c)
        for s in dict.fromkeys((sym_u, renames_u.get(sym_u, sym_u))):
            if master_dom.get(s):
                return master_dom[s]
        return None

    def _declared_distinct(a: str, b: str) -> bool:
        return frozenset((a.upper(), b.upper())) in distinct_pairs

    # Every (root, suffix) sighting across holdings + dividend history +
    # the map itself — the cross-listing evidence base (an option is a
    # sighting of its underlying, S042-04).
    # (The map's own lines only: a tobase.map pair is not a sighting,
    # lib/map_hygiene.own_renames.)
    own_u = _MH.own_renames(map_file) if map_file.is_file() else {}
    seen_suffixes = _MH.sightings(
        [str(h.get("symbol") or "") for rows in holdings.values()
         for h in rows] + sorted(div_syms) + list(own_u)
        + list(own_u.values()))

    from taxjson.lib.markets import canadian_suffixes as _ca_sufs
    _CA_SUFS = tuple(sorted(_ca_sufs()))

    # The listings' security names in the parsed exports: the only
    # identity evidence beyond a map ruling (read once, when a pair
    # first needs it).
    _xl: Dict[str, Any] = {}

    def _verdict(a: str, b: str) -> Tuple[str, str]:
        if "names" not in _xl:
            _xl["names"], _xl["shown"] = _MH.listing_names(
                cache, _equity_accts,
                {k.upper(): v.upper() for k, v in glob_renames.items()})
        if "receipts" not in _xl:
            # A CDR and its US share (the interlisted master, Canada).
            from taxjson.lib.tobase_map import receipt_pairs
            _xl["receipts"] = receipt_pairs(country == "canada")
        return _MH.pair_verdict(a.upper(), b.upper(), _xl["names"],
                                  _xl["shown"], _xl["receipts"])

    def _ca_twins(rt: str, sym_u: str) -> List[str]:
        # ticker.map (GLOBAL/TOBASE onto a Canadian listing) is the
        # identity ruling; without one, a sighting of the same root on
        # ANY Canadian venue (.TO, .V, .CN, .NE, .VN — not only the TSX)
        # is a candidate (MAP-GAP asks for the ruling too) — unless the
        # exports show the two apart (map_hygiene.pair_verdict: the Canadian
        # line is a receipt, or the names name different companies) or
        # a DISTINCT line rules it: "hold it instead" would then be
        # wrong advice (audit S042-06, S049-09).
        tgt = renames_u.get(sym_u, "")
        if _MH.symbol_root(tgt)[1] in _CA_SUFS:
            return [] if _declared_distinct(sym_u, tgt) else [tgt]
        return [f"{rt}.{s}" for s in sorted(seen_suffixes.get(rt) or ())
                if s in _CA_SUFS
                and not _declared_distinct(sym_u, f"{rt}.{s}")
                and _verdict(sym_u, f"{rt}.{s}")[0] not in _MH.APART]

    def _twins_proved(rt: str, sym_u: str) -> bool:
        # A map ruling, or equal names for every twin named.
        tgt = renames_u.get(sym_u, "")
        if _MH.symbol_root(tgt)[1] in _CA_SUFS:
            return True
        return all(_verdict(sym_u, c)[0] == "same"
                   for c in _ca_twins(rt, sym_u))

    def _has_ca_twin(rt: str, sym_u: str) -> bool:
        return bool(_ca_twins(rt, sym_u))

    findings = []                     # (check, account, symbol, message)
    if country == "canada":
        for name, acfg in accounts.items():
            plan = _account_plan(name, acfg, country)
            if plan not in ("taxable", "tfsa"):
                continue              # RRSP/LIRA: treaty-exempt, no check
            for h in holdings.get(name, []):
                sym = str(h.get("symbol") or "")
                if float(h.get("quantity", 0) or 0) <= 0:
                    # A short position pays the dividend (in lieu); it
                    # receives none: both checks are about dividends
                    # received (backlog TJ-0914).
                    continue
                rt, suf = _MH.symbol_root(sym)
                if suf != "US":
                    continue
                sym_u = sym.upper()
                # The US line itself must pay: borrowing the .TO line's
                # dividends through the bare root flagged a US holding
                # that pays nothing (audit S049-09).
                pays = sym_u in div_syms
                if not pays:
                    continue
                # An issuer the project records as domiciled outside
                # Canada is no Canadian issuer, Canadian line or not: its
                # dividends are foreign wherever it trades, and the
                # twin branch called a declared US issuer Canadian and
                # hid TFSA-US-DIV (backlog TJ-0913).
                dom = _domicile(sym_u)
                if dom in (None, "CAN") and _has_ca_twin(rt, sym_u):
                    _ca = " or ".join(_ca_twins(rt, sym_u))
                    _chk = ("" if _twins_proved(rt, sym_u) else
                            f" (verify {_ca} is the same security first: "
                            f"only the letters match — `tjs "
                            f"ticker-map --suggest` lists the pair)")
                    findings.append((
                        "US-LISTING", name, sym,
                        f"Canadian issuer held via its US listing in a "
                        f"{plan} account while paying dividends — hold "
                        f"{_ca} instead for clean eligible-dividend "
                        f"treatment (and no USD conversion drag){_chk}."))
                elif plan == "tfsa":
                    # US withholding follows the issuer's domicile, not
                    # its listing: a payer the project says is domiciled
                    # elsewhere is not flagged; one it says nothing of
                    # is flagged as a condition (backlog TJ-0562).
                    if dom == "USA":
                        findings.append((
                            "TFSA-US-DIV", name, sym,
                            "US dividend payer inside a TFSA: the 15% US "
                            "withholding is unrecoverable here. Prefer the "
                            "RRSP (treaty-exempt) or a taxable account "
                            "(foreign tax credit claimable)."))
                    elif dom is None:
                        findings.append((
                            "TFSA-US-DIV", name, sym,
                            f"US-listed dividend payer inside a TFSA: if "
                            f"its issuer is US-domiciled, the 15% US "
                            f"withholding is unrecoverable here; prefer "
                            f"the RRSP (treaty-exempt) or a taxable "
                            f"account (foreign tax credit claimable). The "
                            f"listing alone does not say: a ticker.map "
                            f"`T1135 {sym} COUNTRY` line records the "
                            f"issuer's country."))

    from taxjson.lib.offline import offline_enabled as _offline
    if getattr(args, "online", False) and _offline():
        # The documented kill switch covers this probe too: it sends
        # every held and dividend ticker to Yahoo (S042-12, S048-00).
        note("tjs tips", "TAXJSON_OFFLINE is set — the --online "
             "Yahoo Finance probe is skipped",
             details=["MAP-GAP?/MAP-BAD?/CDR-PAIR are not checked; the "
                      "offline checks below still ran."])
    elif getattr(args, "online", False):
        try:
            import yfinance as yf
        except ImportError:
            from taxjson.lib.out import warn as _warn
            _warn("--online needs yfinance (pip install -e '.[fx]'); "
                  "skipping the probe.", prog="tjs tips")
        else:
            # The book symbol (ZZQ.US, ZZQ.B.TO) is not Yahoo's spelling:
            # every probe goes through the project's QUOTE lines, else
            # the one converter the price chain uses (lib/price_chain).
            # A raw `ZZQ.US` lookup came back empty for every US symbol,
            # so MAP-BAD? could never be raised.
            from taxjson.lib.price_chain import load_yf_map, yf_symbol_for
            try:
                _quote = load_yf_map([str(root)])
            except Exception:
                _quote = {}

            def _yf(sym: str) -> Optional[str]:
                s = str(sym or "").upper()
                if s in _quote:
                    return _quote[s][0]
                return yf_symbol_for(s)

            def _issuer_names(sym: str) -> Tuple[str, str]:
                """(longName, shortName) — BOTH matter: for a CDR the
                longName is the clean issuer ('Abbott Laboratories')
                and only the shortName carries the receipt marker
                ('ABBOTT LABS CDR (CAD HEDGED)'). Falls back to the
                chart metadata when the info endpoint is throttled.
                `sym` is the book symbol; Yahoo is asked for its
                spelling (_yf)."""
                ln = sn = ""
                sym = _yf(sym)
                if not sym:
                    return ln, sn
                try:
                    info = yf.Ticker(sym).info or {}
                    ln = str(info.get("longName") or "")
                    sn = str(info.get("shortName") or "")
                except Exception:
                    pass
                if not (ln or sn):
                    try:
                        t = yf.Ticker(sym)
                        t.history(period="5d", timeout=5)
                        md = t.history_metadata or {}
                        ln = str(md.get("longName") or "")
                        sn = str(md.get("shortName") or "")
                    except Exception:
                        pass
                return ln, sn

            probed = []
            for sym in sorted(div_syms):
                rt, suf = _MH.symbol_root(sym)
                if (suf != "US" or _has_ca_twin(rt, sym.upper())
                        or _declared_distinct(f"{rt}.US", f"{rt}.TO")):
                    continue
                # The exports already name the two differently (a CDR,
                # another issuer): nothing to verify. A pair the books
                # cannot compare stays a candidate TO VERIFY.
                if _verdict(f"{rt}.US", f"{rt}.TO")[0] in _MH.APART:
                    continue
                _twin = _yf(f"{rt}.TO")
                if not _twin:
                    continue
                try:
                    hist = yf.Ticker(_twin).history(period="5d",
                                                    timeout=5)
                    if hist is not None and not hist.empty:
                        probed.append(rt)
                except Exception:
                    continue
            for rt in probed:
                # A .TO line that exists is very often the CDR, not a
                # cross-listing — check what the exchange calls it
                # before suggesting a merge that would be wrong. An
                # unheld CDR twin is silently skipped (nothing in the
                # books to rule on); a HELD one is surfaced as
                # CDR-PAIR by the issuer-name clustering below.
                _tl, _ts = _issuer_names(f"{rt}.TO")
                if _is_cdr_name(_tl) or _is_cdr_name(_ts):
                    continue
                findings.append((
                    "MAP-GAP?", "-", f"{rt}.US",
                    f"{rt}.TO trades on the TSX — VERIFY whether it is "
                    f"the same issuer; if so, add "
                    f"`TOBASE {rt}.US {rt}.TO` to ticker.map."))

            # Issuer-name evidence — the only way to catch
            # DIFFERENT-root dual listings (SAMPLQ.US/SAMPLP.TO) and typo'd
            # map pairs, which same-root scanning can never see.

            held_syms = {str(h.get("symbol") or "").upper()
                         for rows in holdings.values() for h in rows}
            held_syms = {s for s in held_syms
                         if _MH.symbol_root(s)[1]
                         in _CA_SUFS + ("US",)}
            _NAME_CAP = 80
            # The held listings and the map partners OF THEM — never
            # every tobase.map pair: the master's 3,800 lines spent the
            # cap on AAB.TO..AFE.TO and the holdings were never probed
            # (2026-10 workflow audit).
            _probe_list = sorted(
                held_syms
                | {renames_u[s] for s in held_syms if s in renames_u}
                | {k for k, v in renames_u.items() if v in held_syms})
            if len(_probe_list) > _NAME_CAP:
                note("tjs tips",
                     f"probing issuer names for the first {_NAME_CAP} "
                     f"of {len(_probe_list)} held listings",
                     details=["Alphabetical; the remainder are NOT "
                              "probed — every run scans the same "
                              "window."])
                _probe_list = _probe_list[:_NAME_CAP]
            # yfinance logs every miss as a raw line of its own: the
            # findings below say what matters.
            import logging as _lg
            _lg.getLogger("yfinance").setLevel(_lg.CRITICAL)
            _pairs = {s: _issuer_names(s) for s in _probe_list}
            names = {s: (ln or sn) for s, (ln, sn) in _pairs.items()}
            is_cdr = {s: _is_cdr_name(ln) or _is_cdr_name(sn)
                      for s, (ln, sn) in _pairs.items()}

            # MAP-VERIFY: each defined pair must name ONE issuer — a
            # typo'd pair silently merges two companies' ACB pools.
            # A CDR paired with anything is wrong even when the issuer
            # matches: the receipt ratio floats, so no consolidation
            # ratio exists.
            for old_, new in sorted(renames_u.items()):
                na, nb = names.get(old_, ""), names.get(new, "")
                if (na and nb
                        and is_cdr.get(old_, False)
                        != is_cdr.get(new, False)):
                    findings.append((
                        "MAP-BAD?", "-", f"{old_}->{new}",
                        f"ticker.map pairs a CDR with its underlying "
                        f"({na!r} vs {nb!r}) — a CDR is a fractional "
                        f"CAD-hedged receipt whose ratio floats; "
                        f"remove the entry (look-alike listings are "
                        f"never joined: no DISTINCT line is needed)."))
                elif na and nb and not _issuer_names_match(na, nb):
                    findings.append((
                        "MAP-BAD?", "-", f"{old_}->{new}",
                        f"ticker.map pairs these, but the exchanges "
                        f"name them {na!r} vs {nb!r} — VERIFY: a "
                        f"wrong pair merges two companies' ACB "
                        f"pools."))

            # MAP-GAP (different roots): held listings whose issuer
            # names match across a US and a Canadian line with no map
            # entry connecting them.
            _by_name: Dict[str, set] = {}
            for s, n in names.items():
                if s in held_syms and n:
                    _by_name.setdefault(_norm_issuer_name(n),
                                        set()).add(s)
            for key, syms in sorted(_by_name.items()):
                if not key or len(syms) < 2:
                    continue
                # sorted: `syms` is a set, and its iteration order
                # numbered the findings differently on every run (S042-13).
                us = [s for s in sorted(syms)
                      if _MH.symbol_root(s)[1] == "US"]
                ca = [s for s in sorted(syms)
                      if _MH.symbol_root(s)[1] in _CA_SUFS]
                for u in us:
                    for c in ca:
                        if (u in renames_u or c in renames_u
                                or renames_u.get(u) == c
                                or renames_u.get(c) == u
                                or _declared_distinct(u, c)):
                            continue
                        if is_cdr.get(c) or is_cdr.get(u):
                            # Same issuer, but one side is a CDR —
                            # NOT a mappable listing pair. Suggest
                            # recording the ruling, not a TOBASE.
                            findings.append((
                                "CDR-PAIR", "-", f"{u}/{c}",
                                f"{names.get(c) or names.get(u)!r} "
                                f"is a CDR over {u} — a fractional "
                                f"CAD-hedged receipt, not a listing "
                                f"equivalent; nothing to do: "
                                f"look-alike listings are never "
                                f"joined."))
                            continue
                        findings.append((
                            "MAP-GAP?", "-", f"{u}/{c}",
                            f"both held and both named "
                            f"{names[u]!r} — looks like one issuer's "
                            f"two listings with no ticker.map entry; "
                            f"VERIFY and add `TOBASE {u} {c}` if "
                            f"so."))

    if getattr(args, "json", False):
        # schema 2: the unused-rule notes and cross-listing loss
        # findings are `tjs ticker-map --suggest`'s now.
        print(json.dumps({"schema_version": 2, "findings": [
            {"check": c, "account": a, "symbol": sy, "message": m}
            for c, a, sy, m in findings],
            "unscanned": [{"account": n, "missing": w}
                          for n, w in sorted(unscanned.items())]},
            indent=2, sort_keys=True))
        raise SystemExit(2 if unscanned else 0)

    from taxjson.lib import out
    doc = out.Doc(f"TIPS — tax-efficiency advice for next year, {country}"
                  f"{', online map probe' if getattr(args, 'online', False) else ''}")
    if unscanned:
        out.warn("not read (no "
                 + "; ".join(f"{n}: {w}"
                             for n, w in sorted(unscanned.items()))
                 + ")", prog="tjs tips",
                 details=["Re-run `tjs run` to rebuild them."])
    if not findings:
        doc.blank()
        if unscanned:
            doc.para(f"No tips for the accounts read — "
                     f"{', '.join(sorted(unscanned))} could not be read "
                     f"(see above).")
            doc.print()
            raise SystemExit(2)
        doc.line("No tips — nothing to change in where you hold what.")
        doc.print()
        return
    doc.section("TIPS")
    doc.table(["CHECK", "ACCOUNT", "SYMBOL"],
              [[c, a, sy] for c, a, sy, _m in findings])
    doc.blank()
    for i, (c, a, sy, m) in enumerate(findings, 1):
        where = f" [{a}]" if a != "-" else ""
        doc.item(f"{c}{where} {sy}: {m}", bullet=f"{i}. ")
    doc.blank()
    doc.line(f"{len(findings)} tip(s) for next year — none changes a "
             f"number of this year.")
    doc.print()
    if unscanned:
        raise SystemExit(2)


def _issuer_facts(cache: Path, acct: str) -> Dict[str, Any]:
    """The issuer's country of each income row of an account's base book
    that carries one (an IB CA/US ISIN): {"by_id": {row id: Canadian
    issuer?}, "by_symbol": {symbol: [(date, Canadian issuer?), ...] in
    date order}}. The estimate splits Canadian (eligible) from foreign
    dividends with the SAME test the engine uses for a s.260 payment in
    lieu, income_dating.is_canadian_issuer, not the listing suffix alone
    (A2-0319, A2-0662), row by row: one flag per symbol, the last row's
    in all history, classified every payment of the symbol by it, an
    earlier year's too (backlog TJ-0726). A symbol with no such row is
    not in by_symbol: the caller falls back to its listing."""
    from taxjson.lib.income_dating import is_canadian_issuer
    by_id: Dict[str, bool] = {}
    by_sym: Dict[str, List[Tuple[str, bool]]] = {}
    try:
        data = _read_work_doc(cache / f"{acct}_base.json")
    except (OSError, ValueError):
        return {"by_id": by_id, "by_symbol": by_sym}
    for t in data.get("transactions", []) or []:
        if not isinstance(t, dict) or not t.get("issuer_country"):
            continue
        if t.get("action") not in ("DIVIDEND", "DIVIDEND_IN_LIEU"):
            continue
        sym = str(t.get("symbol") or "")
        if not sym:
            continue
        ca = is_canadian_issuer(t)
        if t.get("id"):
            by_id[str(t["id"])] = ca
        by_sym.setdefault(sym, []).append((str(t.get("date") or ""), ca))
    for v in by_sym.values():
        v.sort(key=lambda x: x[0])
    return {"by_id": by_id, "by_symbol": by_sym}


def _issuer_fact_at(facts: List[Tuple[str, bool]], date: str) -> bool:
    """The symbol's issuer fact in force on `date`: the latest row's on
    or before it, else the earliest (a later row never reclassifies an
    earlier payment; backlog TJ-0726)."""
    pick = facts[0][1]
    for d, ca in facts:
        if d and date and d > date:
            break
        pick = ca
    return pick


def _issuer_split(rows, issuer: Optional[Dict[str, Any]]
                  ) -> Dict[Tuple[str, str], List[float]]:
    """{(symbol, currency): [Canadian, foreign]} dividends of the gains
    rows `rows` whose symbol has issuer facts (`_issuer_facts`), each
    row classified by its own base row's issuer country, a row without
    one by the symbol's fact on its date (backlog TJ-0726)."""
    out: Dict[Tuple[str, str], List[float]] = {}
    by_id = (issuer or {}).get("by_id") or {}
    by_sym = (issuer or {}).get("by_symbol") or {}
    if not by_sym:
        return out
    for t in rows or []:
        if not isinstance(t, dict) or t.get("action") not in (
                "DIVIDEND", "DIVIDEND_IN_LIEU"):
            continue
        sym = str(t.get("symbol") or "")
        if sym not in by_sym:
            continue
        ca = by_id.get(str(t.get("id") or ""))
        if ca is None:
            ca = _issuer_fact_at(by_sym[sym], str(t.get("date") or ""))
        cell = out.setdefault((sym, t.get("currency") or "?"), [0.0, 0.0])
        cell[0 if ca else 1] += float(t.get("dividend", 0) or 0)
    return out


def _section_1256_gain(files: Dict[str, Path], accounts, year,
                       settings: Dict[str, Any]) -> Tuple[float, float]:
    """US only: (the year's realized P/L of §1256 contracts — futures,
    futures options, broad-based index options, lib/futures.
    section_1256_kind — in the taxable accounts' gains files, the part
    of it the engine termed long-term). The estimate takes the P/L out
    of the term the engine gave it (a long-term part out of the
    long-term gains, the rest out of the short-term ones, where a gain
    with no term goes) and splits it as Form 6781 does, 40% short-term
    and 60% long-term (US-FUT-03; backlog TJ-0466, A2-1124)."""
    docs = []
    for acct in sorted(accounts):
        p = files.get(acct)
        if p is None:
            continue
        try:
            docs.append(_read_work_doc(p))
        except (OSError, ValueError):
            continue                # the account loop already refused it
    return _section_1256_of_docs(docs, year, settings)


def _section_1256_of_docs(docs, year, settings: Dict[str, Any]
                          ) -> Tuple[float, float]:
    """`_section_1256_gain` over gains documents already read (plot-tax
    passes each month's slice, so its months split the §1256 P/L as the
    year's estimate does)."""
    from taxjson.lib.futures import section_1256_kind
    key = ("date" if _tax_date_basis(settings) == "trade"
           else "date_settle")
    ystr = str(year or "")
    total = long_term = 0.0
    for data in docs:
        for t in data.get("transactions", []) or []:
            if not isinstance(t, dict) or t.get("action", "BUYSELL") in (
                    "DIVIDEND", "DIVIDEND_IN_LIEU"):
                continue
            d = str(t.get(key) or t.get("date") or "")
            if ystr and not d.startswith(ystr):
                continue
            if section_1256_kind(str(t.get("symbol") or "")):
                total += float(t.get("gain") or 0.0)
                if t.get("term") == "LONG_TERM":
                    long_term += float(t.get("gain") or 0.0)
    return total, long_term


def _box18_into_estimate(root: Path, est: Dict[str, float], accounts,
                         year, foreign_by_acct: Dict[str, float],
                         foreign_by_security: Optional[
                             Dict[str, Dict[str, float]]] = None) -> None:
    """Move the tax year's T5 box 18 capital-gains dividends named in
    [[capital_gains_dividends]] out of the estimate's dividends and into
    `est["cg_div"]` (taxed as capital gains by estimate_canada). Base-
    currency amounts from each taxable account's base book (the native
    row's id is the base row's id); a foreign one out of its security's
    dividends in `foreign_by_security` too. No map: nothing changes."""
    fr = _box18_fractions(root)
    est.setdefault("cg_div", 0.0)
    if not fr:
        return
    from taxjson.lib.cg_dividends import row_amount
    rules = _view_income_rules(root)
    ystr = str(year or "")
    cache = root / "work"
    # Each bucket's mapped amounts are netted first and taken out once:
    # floored row by row, a 100 dividend and its -60 reversal took
    # max(0, 40 - 100) = 0, then 0 + 60 = 60 of phantom dividends
    # (backlog TJ-1020).
    ca_cg = foreign_cg = 0.0
    acct_cg: Dict[str, float] = {}
    sec_cg: Dict[Tuple[str, str], float] = {}
    for acct in sorted(accounts):
        p = cache / f"{acct}_base.json"
        try:
            data = _read_work_doc(p)
        except (OSError, ValueError) as e:
            # Named once, from the project; exit 2 (backlog TJ-0641).
            _die_input(f"could not read {_work_read_why(p, e, root)}",
                       "It holds the capital-gains dividends "
                       "[[capital_gains_dividends]] names. Re-run "
                       "`tjs run` to rebuild it.")
        for t in data.get("transactions", []):
            f = fr.get((acct, str(t.get("id"))))
            if not f or t.get("action") != "DIVIDEND":
                continue
            d = rules.income_date(t) if rules is not None \
                else str(t.get("date") or "")
            if ystr and not str(d).startswith(ystr):
                continue
            cg = row_amount(t) * f
            from taxjson.lib.income_dating import is_canadian_issuer
            # The issuer test the dividend split uses (A2-0319).
            if is_canadian_issuer(t):
                ca_cg += cg
            else:
                foreign_cg += cg
                acct_cg[acct] = acct_cg.get(acct, 0.0) + cg
                sym = str(t.get("symbol") or "")
                sec_cg[(acct, sym)] = sec_cg.get((acct, sym), 0.0) + cg
            est["cg_div"] += cg
    if ca_cg:
        est["div_ca"] = max(0.0, est["div_ca"] - ca_cg)
    if foreign_cg:
        est["div_foreign"] = max(0.0, est["div_foreign"] - foreign_cg)
    for acct, cg in acct_cg.items():
        foreign_by_acct[acct] = max(0.0, foreign_by_acct.get(acct, 0.0)
                                    - cg)
    for (acct, sym), cg in sec_cg.items():
        by = (foreign_by_security or {}).get(acct)
        if by is not None and sym in by:
            by[sym] = max(0.0, by[sym] - cg)


def _fold_estimate_income(res: Dict[str, Any], acct: str,
                          est: Dict[str, float],
                          foreign_by_acct: Dict[str, float], *,
                          crypto: bool,
                          issuer: Optional[Dict[str, Any]] = None,
                          rows=None,
                          foreign_by_security: Optional[
                              Dict[str, Dict[str, float]]] = None
                          ) -> None:
    """Add one taxable account's `summarize_gains` aggregates to the
    estimator's inputs: realized gains (and their ST/LT split), its
    dividends as Canadian (eligible), foreign (`foreign_by_acct` too,
    for the FTC, and `foreign_by_security` {account: {symbol: amount}}
    when given: the 15% limit is each security's, backlog TJ-0638) or,
    in a crypto account, staking rewards (ordinary
    income, nothing withheld — not foreign dividends with an assumed
    15% FTC), and the payments in lieu. `sum` / `estimate` and
    `plot-tax` feed the estimator through this one path. `issuer`:
    `_issuer_facts` of the account; `rows`: the gains rows `res`
    summarizes, whose dividends are then classified row by row (each
    by its own issuer country, backlog TJ-0726)."""
    from taxjson.lib.income_dating import is_canadian_listing
    by_sym = (issuer or {}).get("by_symbol") or {}
    split = _issuer_split(rows, issuer) if rows is not None else {}
    for ticker, cur_map in res.get("ticker_stats", {}).items():
        # The issuer's ISIN country when the books carry it, else the
        # listing (A2-0319, A2-0662); with no rows to split, the
        # symbol's latest fact.
        is_ca_listed = (by_sym[ticker][-1][1] if ticker in by_sym
                        else is_canadian_listing(ticker))

        def _foreign(amount: float) -> None:
            est["div_foreign"] += amount
            foreign_by_acct[acct] = foreign_by_acct.get(acct, 0.0) + amount
            if foreign_by_security is not None:
                by = foreign_by_security.setdefault(acct, {})
                by[ticker] = by.get(ticker, 0.0) + amount
        for cur, s in cur_map.items():
            est["realized"] += (float(s.get("cap", 0) or 0)
                                + float(s.get("opt", 0) or 0))
            est["st"] += float(s.get("st_gain", 0) or 0)
            est["lt"] += float(s.get("lt_gain", 0) or 0)
            d = float(s.get("div", 0) or 0)
            cell = split.get((ticker, cur))
            if crypto:
                est["staking"] += d
            elif cell is not None and abs(cell[0] + cell[1] - d) <= 0.005:
                # Row by row: each payment by its own issuer's country.
                est["div_ca"] += cell[0]
                if cell[1]:
                    _foreign(cell[1])
            elif is_ca_listed:
                est["div_ca"] += d
            else:
                _foreign(d)
            _p = float(s.get("pil", 0) or 0)
            est["pil"] += _p
            # Compensation paid on a short (US: no deduction under the
            # standard deduction, US-INC-04; TJ-0728), row by row: one
            # netted against a payment received is still paid (TJ-1060),
            # a reversal of one received nets. A security's net below
            # zero counts whole, as on gains files of an older run.
            _paid = max(float(s.get("pil_paid", 0) or 0), -_p)
            if _paid > 0:
                est["pil_paid"] = est.get("pil_paid", 0.0) + _paid


def cmd_plot_tax(args: argparse.Namespace) -> None:
    """`tjs plot-tax [--other-income AMT] [--other-losses AMT]
    [--deductions AMT] [--carrying-charges AMT] [--long-term-losses
    AMT] [--province P] [--json]`: the tax the year's investment income
    generated month by month as an ASCII chart against the year's
    estimate (lib/tax_plot; CA-PLAN-08 / US-PLAN-09). The estimator
    `estimate` uses runs once per month on the taxable accounts' gains
    and income dated up to the month's end (the same inputs, the same
    code path); a month's tax is that run less the month before's.
    Planning numbers only."""
    from taxjson.bin.taxjson_sum_gains import summarize_gains
    from taxjson.lib import tax_plot as TP
    from taxjson.lib.report_model import resolve_gains_files
    root = Path(args.dir).resolve()
    cache = root / "work"
    cfg = load_config(root) if _PL.has_config(root) else {}
    if not cfg:
        _die("the tax estimate needs taxjson.toml",
             "It reads the country and the account types from it.")
    settings = cfg.get("settings") or {}
    country = _country(settings)
    year = settings.get("year")
    if year is None:
        _die("no `year` under [settings] in taxjson.toml",
             "The chart is the project's tax year, month by month.")
    year = int(year)
    prov = None
    if country == "canada":
        from taxjson.lib import tax_estimate as _te
        prov = (getattr(args, "province", None)
                or str(settings.get("province", "") or "")).strip()
        _te.apply_vintage(year)
        if not prov:
            _die("the canada estimate needs a province",
                 "Pass --province ON|BC|AB or set `province` under "
                 "[settings] in taxjson.toml.")
        if prov.upper() not in _te.CA_PROVINCES:
            _die(f"unsupported province {prov!r} for the estimate",
                 f"Supported: {', '.join(sorted(_te.CA_PROVINCES))}.")
    taxable = {n for n, c in (cfg.get("accounts") or {}).items()
               if c.get("type") == "taxable"}
    files = {a: p for a, p in resolve_gains_files(cache, None).items()
             if a in taxable}
    if not files:
        _die_input("no gains files for a taxable account in work/",
                   "Run `tjs run` first.")
    _warn_artifact_year(files, year)
    _warn_run_state(root, cfg)
    oi, ol = _estimate_inputs(root, args)
    ded, cc = _estimate_deductions(root, args)
    ltl = _estimate_lt_losses(root, args)
    ol, ltl, amt_in, carry_src = _carry_inputs(root, args, cfg, ol, ltl)
    carry_src["other_income_value"] = oi
    docs: Dict[str, Dict[str, Any]] = {}
    for acct, p in files.items():
        try:
            docs[acct] = _read_work_doc(p)
        except (OSError, ValueError) as e:
            # Named once, from the project; exit 2 (backlog TJ-0641).
            _die_input(f"could not read {_work_read_why(p, e, root)}",
                       "A taxable account's gains cannot be left out. "
                       "Re-run `tjs run` to rebuild it.")
    settle = _settle_basis(root, next(iter(docs.values())))
    keep = _year_keep(str(year))

    def date_of(t):
        return _gains_row_date(t, keep, settle)
    issuer = {a: _issuer_facts(cache, a) for a in docs}
    crypto = {n for n, c in (cfg.get("accounts") or {}).items()
              if c.get("crypto")}

    def inputs(through: Optional[str]):
        est = dict(realized=0.0, st=0.0, lt=0.0, div_ca=0.0,
                   div_foreign=0.0, pil=0.0, staking=0.0)
        fba: Dict[str, float] = {}
        fbs: Dict[str, Dict[str, float]] = {}
        slices = []
        for a, doc in docs.items():
            sl = TP.slice_doc(doc, date_of, through) if through else doc
            slices.append(sl)
            _fold_estimate_income(summarize_gains(sl), a, est, fba,
                                  crypto=a in crypto,
                                  issuer=issuer[a],
                                  rows=sl.get("transactions") or [],
                                  foreign_by_security=fbs)
        if country in ("us", "usa"):
            # Each month splits the §1256 P/L it holds 40/60, as the
            # year's estimate does (US-FUT-03; backlog TJ-0466).
            est["s1256"], est["s1256_lt"] = _section_1256_of_docs(
                slices, year, settings)
        return est, fba, fbs

    def run(est, withheld):
        return _tax_estimate_result(
            cfg, est, other_income=oi, other_losses=ol, province=prov,
            deductions=ded, carrying_charges=cc, lt_losses=ltl,
            amt_carryover=amt_in, carry_sources=carry_src,
            **withheld)
    # The year as `estimate` computes it: the T5 box 18 capital-gains
    # dividends are dated to the year (the US §1256 split is each
    # month's own, in inputs()).
    est, fba, fbs = inputs(None)
    _box18_into_estimate(root, est, set(docs), year, fba, fbs)
    # The foreign tax withheld, as `estimate` reads it (the base books'
    # TAX rows; the 15% assumption only for an account with none in
    # the year): with no such argument every month and the year ran on
    # the assumption (backlog TJ-0299). A month's run credits what was
    # recorded by its end. The US estimate takes no such credit. A
    # spin-off's deemed dividend takes no assumed withholding (backlog
    # TJ-0422). Each security's withholding counts up to 15% of its own
    # dividends (backlog TJ-0638).
    wh_noncash: Dict[str, List[Tuple]] = {}
    wh_rows = (_withholding_rows(cache, set(docs), year, fba, wh_noncash)
               if country == "canada" else None)

    def withheld(fb, fs, through=None) -> Dict[str, Any]:
        if wh_rows is None:
            return {}
        kw = _withholding_kwargs(_withholding_split(
            wh_rows, fb, through, wh_noncash))
        kw["withholding_by_security"] = _withholding_by_security(
            wh_rows, fs, through, wh_noncash)
        return kw
    points = []
    for m in TP.months_of_year(year):
        end = TP.month_end(m)
        m_est, m_fba, m_fbs = inputs(end)
        r = run(m_est, withheld(m_fba, m_fbs, end))
        points.append({"month": m, "cum_tax": r["estimated_tax"],
                       "cum_income": r["investment_income"]})
    ry = run(est, withheld(fba, fbs))
    base = _base_currency(root)
    label = (f"canada/{prov.upper()}" if country == "canada" else "usa")
    # The sales with an unknown cost, counted as `estimate` counts them
    # (summarize_gains): routed to manual reporting, out of every
    # figure, or in-line in raw engine output (backlog TJ-0783).
    n_routed = sum(len(d.get("manual_reporting_required") or [])
                   for d in docs.values())
    n_inline = sum(1 for d in docs.values()
                   for t in d.get("transactions") or []
                   if isinstance(t, dict) and t.get("tainted")
                   and "gain" in t)
    doc = TP.build(points, year=year, base=base,
                   year_estimate=ry["estimated_tax"],
                   year_income=ry["investment_income"], label=label,
                   accounts=docs, with_amt=ry.get("estimated_tax_with_amt"),
                   other_income=oi, unknown_cost_routed=n_routed,
                   unknown_cost_included=n_inline)
    if getattr(args, "json", False):
        if n_routed:
            from taxjson.lib import out as _out
            _out.warn(f"{n_routed} disposition(s) with an unknown cost "
                      f"(no purchase in your files) were routed to manual "
                      f"reporting — these figures EXCLUDE them",
                      prog="tjs plot-tax",
                      details=["`tjs form-export` lists them in its "
                               "MANUAL REPORTING section; report them by "
                               "hand."])
        _json_out(doc)
        return
    from taxjson.lib import out as _out
    TP.render(doc, _out.width(sys.stdout)).print()


def _report_aggregate_usable(gains: Any) -> bool:
    """Is a work/<acct>_report.json `gains` object the complete
    summarize_gains aggregate `sum` reads (its ticker_stats and
    total_fees objects)? A truncated or hand-edited one (`{}`) passed
    the fast path as "no gains" and put REALIZED 0.00 beside a nonzero
    FOR THE RETURN total in the same `sum --json` (2026-10-24 audit
    D07); `sum` recomputes from the gains file instead."""
    return (isinstance(gains, dict)
            and isinstance(gains.get("ticker_stats"), dict)
            and isinstance(gains.get("total_fees"), dict))


def cmd_summary(args: argparse.Namespace) -> None:
    """One-row-per-account realized-gains summary (base currency) on the
    filing basis: wash-adjusted gains where the pipeline built the
    cross-account pass (matching `reports/<account>_wash.sum`, carryover,
    t1135 and form-export), plain gains otherwise. The banner names the
    basis. Reuses `summarize_gains` so the aggregation itself matches
    `reports/<account>.sum`."""
    from taxjson.bin.taxjson_sum_gains import summarize_gains
    from taxjson.lib import out as _out
    from taxjson.lib.report_model import (gains_basis_label,
                                          resolve_gains_files)
    root = Path(args.dir).resolve()
    cache = root / "work"
    # Canonical per-account gains, wash-adjusted where the pipeline built
    # the cross-account pass — the same basis carryover/t1135/form-export
    # report, so this summary can't disagree with the filing commands.
    files = resolve_gains_files(cache, getattr(args, "account", None)
                                or None)
    if not files:
        if getattr(args, "account", None):
            _die_input(f"no gains for account {args.account!r} in work/",
                       "Run `tjs run` first, or check the account "
                       "name.")
        if not _PL.has_config(root):
            _die(*_no_project_message(root, _current_cmd()))
        _die_input("no gains files in work/", "Run `tjs run` first.")
    basis = gains_basis_label(files)

    money = fmt_money               # shared report-layer formatter

    # --other-income/--other-losses turn on the marginal tax estimate,
    # which needs the config (country/account types) and only counts
    # TAXABLE accounts' income.
    want_estimate = (getattr(args, "other_income", None) is not None
                     or getattr(args, "other_losses", None) is not None
                     or getattr(args, "deductions", None) is not None
                     or getattr(args, "carrying_charges", None) is not None
                     or getattr(args, "long_term_losses", None) is not None
                     or getattr(args, "estimate", False))
    _oi, _ol = _estimate_inputs(root, args)
    _ded, _cc = _estimate_deductions(root, args)
    _ltl = _estimate_lt_losses(root, args)
    _foreign_by_acct: Dict[str, float] = {}
    # Each security's foreign dividends too: the 15% limit on its
    # withholding is its own (backlog TJ-0638).
    _foreign_by_sec: Dict[str, Dict[str, float]] = {}
    cfg = load_config(root) if _PL.has_config(root) else {}
    _amt_in: Optional[Dict[int, float]] = None
    _carry_src: Dict[str, Any] = {}
    if want_estimate and cfg:
        _ol, _ltl, _amt_in, _carry_src = _carry_inputs(root, args, cfg,
                                                       _ol, _ltl)
        _carry_src["other_income_value"] = _oi
    taxable_accounts = {n for n, c in cfg.get("accounts", {}).items()
                        if c.get("type") == "taxable"}
    est = dict(realized=0.0, st=0.0, lt=0.0, div_ca=0.0,
               div_foreign=0.0, pil=0.0, staking=0.0)
    if want_estimate and not cfg:
        _die("the tax estimate needs taxjson.toml",
             "It reads the country and the account types from it.")
    _prog = f"tjs {_current_cmd() or 'sum'}"
    if getattr(args, "province", None) and not want_estimate:
        _out.warn("--province is ignored without the tax estimate",
                  prog=_prog,
                  details=["Add --other-income or --other-losses, or use "
                           "`tjs estimate`."])
    if want_estimate:
        # --other-income/--other-losses were checked by _estimate_inputs
        # above (one guard, A2-1123).
        _settings0 = cfg.get("settings") or {}
        if _country(_settings0) == "canada" \
                and not getattr(args, "federal_only", False):
            # Validate the province BEFORE printing anything: a missing
            # or unsupported one used to fail only after the whole sum
            # table had scrolled past (2026-09 CLI audit B20).
            from taxjson.lib import tax_estimate as _te
            _prov = (getattr(args, "province", None)
                     or str(_settings0.get("province", "") or "")).strip()
            _te.apply_vintage(_settings0.get("year"))
            if not _prov:
                _die("the canada estimate needs a province",
                     "Pass --province ON|BC|AB or set `province` under "
                     "[settings] in taxjson.toml.")
            if _prov.upper() not in _te.CA_PROVINCES:
                _die(f"unsupported province {_prov!r} for the estimate",
                     f"Supported: "
                     f"{', '.join(sorted(_te.CA_PROVINCES))}.")
    _run_state: List[str] = []
    if cfg:
        _warn_artifact_year(files, (cfg.get("settings") or {}).get("year"))
        _run_state = _warn_run_state(root, cfg)

    # NON-OPT: every non-option disposition (shares, units, futures,
    # crypto) — it was headed STOCK and read as Schedule 3 line 4
    # (audit R1-211, S051-01).
    header = ["ACCOUNT", "NON-OPT", "OPTION", "REALIZED", "DIVIDEND", "PIL",
              "FEES", "TOTAL"]
    acct_types = {n: str(c.get("type") or "")
                  for n, c in cfg.get("accounts", {}).items()}
    acct_rows: List[Dict[str, Any]] = []
    tainted_included = 0
    tainted_routed = 0
    year = None
    for acct, p in files.items():
        # Prefer the machine twin the pipeline wrote (work/<acct>_report.json)
        # when it is at least as fresh as the gains file — same aggregates,
        # no recompute. Falls back to summarize_gains for older projects.
        res = None
        data = None
        report_p = p.with_name(f"{acct}_report.json")
        if report_p.exists() and report_p.stat().st_mtime >= p.stat().st_mtime:
            # Freshness alone is not enough: after `run --account X` the
            # report is freshly rebuilt from PRE-wash gains (the wash
            # pass is skipped under --account) while resolve_gains_files
            # still returns the older _gains_wash.json — serving it
            # would print pre-wash aggregates under a "wash-adjusted"
            # banner. Require the recorded basis to match the resolved
            # file; reports without one (older projects) fall through to
            # reading the gains file itself.
            p_basis = ("wash-adjusted" if p.name.endswith("_gains_wash.json")
                       else "pre-wash")
            try:
                rep = _read_work_doc(report_p)
                if (rep.get("schema_version") == 1 and "gains" in rep
                        and rep.get("basis") == p_basis
                        and _report_aggregate_usable(rep.get("gains"))):
                    res = rep["gains"]
                    year = year or rep.get("year")
                elif (rep.get("schema_version") == 1 and "gains" in rep
                        and rep.get("basis") == p_basis):
                    # The twin is there but its aggregate is not the
                    # one the run writes (damaged, truncated, edited):
                    # served, it put REALIZED 0.00 beside the FOR THE
                    # RETURN total computed from the gains file (D07).
                    # The gains file is read instead, and said.
                    _out.warn(f"{_out.relpath(report_p, root)} holds no "
                              f"usable gains aggregate — {acct}'s row is "
                              f"recomputed from {p.name}", prog=_prog,
                              details=["A full `tjs run` rewrites "
                                       "the report file."])
                elif (rep.get("basis") and rep.get("basis") != p_basis):
                    # The account was rebuilt on a DIFFERENT basis than
                    # the resolved gains file (run --account skips the
                    # wash pass). We fall back to the older wash file
                    # for label consistency — but say so, or the
                    # staleness is invisible.
                    _brief1 = _brief(sys.stderr)
                    _out.note(f"{acct}: serving the previous {p_basis} "
                              f"numbers"
                              + (" — run a full `tjs run`" if _brief1
                                 else ""),
                              prog=_prog,
                              details=[] if _brief1 else [
                                  f"The latest per-account rebuild is "
                                  f"{rep.get('basis')} only. Run a full "
                                  f"`tjs run` to refresh the "
                                  f"wash-adjusted aggregates."])
            except (OSError, ValueError):
                res = None
        if res is None:
            try:
                data = _read_work_doc(p)
            except (OSError, ValueError) as e:
                # The file named once, work/<file> (its absolute path
                # came second, in the reader's message), and exit 2: an
                # input that cannot be read, not the 1 of a finding
                # (docs/commands.md, Exit codes; backlog TJ-0641).
                _why = _work_read_why(p, e, root)
                if acct in taxable_accounts:
                    # A taxable account's books left out of the filing
                    # block, the estimate and instalments with rc 0
                    # (R1-277, S004-09): refuse instead.
                    _die_input(f"could not read {_why}",
                               "A taxable account's gains cannot be left "
                               "out of the totals. Re-run `tjs run` "
                               "to rebuild it.")
                if acct in acct_types:
                    # A configured sheltered account dropped out of the
                    # SHELTERED / ALL ACCOUNTS tables with rc 0 and a
                    # stderr line, changing their totals (A2-1119).
                    _die_input(f"could not read {_why}",
                               f"Account {acct!r} "
                               f"({acct_types[acct] or 'untyped'}) would "
                               f"be left out of the account tables and "
                               f"the ALL ACCOUNTS total. Re-run `tjs "
                               f"run` to rebuild it.")
                _out.warn(f"could not read {_why}", prog=_prog)
                continue
            year = year or (data.get("summary") or {}).get("year")
            res = summarize_gains(data)
        cap = opt = div = pil = 0.0
        for cur_map in res.get("ticker_stats", {}).values():
            for s in cur_map.values():
                cap += float(s.get("cap", 0) or 0)
                opt += float(s.get("opt", 0) or 0)
                div += float(s.get("div", 0) or 0)
                pil += float(s.get("pil", 0) or 0)
        if acct in taxable_accounts:
            _issuer = (_issuer_facts(cache, acct) if want_estimate
                       else {})
            _rows = None
            if _issuer.get("by_symbol"):
                # Each dividend by its own issuer's country (backlog
                # TJ-0726): the gains rows the aggregate summarizes.
                if data is None:
                    try:
                        data = _read_work_doc(p)
                    except (OSError, ValueError):
                        data = None
                _rows = ((data or {}).get("transactions") or []
                         if data is not None else None)
            _fold_estimate_income(
                res, acct, est, _foreign_by_acct,
                crypto=bool((cfg.get("accounts", {}).get(acct)
                             or {}).get("crypto")),
                issuer=_issuer, rows=_rows,
                foreign_by_security=_foreign_by_sec)
        fees = sum(float(v) for v in (res.get("total_fees") or {}).values())
        tainted_included += int(res.get("tainted_count") or 0)
        tainted_routed += int(res.get("tainted_routed") or 0)
        # Every row foots as printed (S042-21): REALIZED is the engine's
        # gain rounded once (what the .sum and the checklist compare),
        # NON-OPT is rounded on its own, and OPTION is the cent
        # difference — rounding the three separately left rows whose
        # NON-OPT + OPTION missed REALIZED by a cent. TOTAL adds the
        # displayed REALIZED, DIVIDEND and PIL: a payment in lieu is
        # income like the .sum's GRAND TOTAL counts it (S042-22).
        _stock_r = round(cap, 2)
        _real_r = round(cap + opt, 2)
        _div_r, _pil_r = round(div, 2), round(pil, 2)
        acct_rows.append({"account": acct, "stock": _stock_r,
                          "option": round(_real_r - _stock_r, 2) + 0.0,
                          "realized": _real_r,
                          "dividend": _div_r,
                          "pil": _pil_r, "fees": round(fees, 2),
                          "total": round(_real_r + _div_r + _pil_r, 2),
                          "type": acct_types.get(acct, "")})
        if (cfg.get("accounts", {}).get(acct) or {}).get("crypto"):
            # Its DIVIDEND column is staking rewards (S023-11).
            acct_rows[-1]["dividend_is_staking"] = True
    if want_estimate and cfg:
        # T5 box 18 capital-gains dividends ([[capital_gains_dividends]],
        # tax-logic CA-INC-06): out of the dividends, into the gains.
        _box18_into_estimate(root, est, set(files) & taxable_accounts,
                             year or (cfg.get("settings") or {}).get("year"),
                             _foreign_by_acct, _foreign_by_sec)
        if _country(cfg.get("settings") or {}) in ("us", "usa"):
            est["s1256"], est["s1256_lt"] = _section_1256_gain(
                files, set(files) & taxable_accounts,
                year or (cfg.get("settings") or {}).get("year"),
                cfg.get("settings") or {})

    def _sum_rows(rows: List[Dict[str, Any]]) -> Dict[str, float]:
        # Summed from the DISPLAYED (2dp-rounded) per-account figures,
        # so every table's total row exactly equals the sum of the
        # rows above it.
        s = {k: round(sum(r[k] for r in rows), 2)
             for k in ("stock", "option", "realized", "dividend",
                       "pil", "fees", "total")}
        return s

    def _table_lines(rows: List[Dict[str, Any]],
                     total_label: str) -> List[str]:
        lines = [" ".join(header)]
        for r in rows:
            lines.append(" ".join(
                [r["account"], money(r["stock"]), money(r["option"]),
                 money(r["realized"]), money(r["dividend"]),
                 money(r["pil"]), money(r["fees"]), money(r["total"])]))
        s = _sum_rows(rows)
        lines.append(" ".join(
            [total_label, money(s["stock"]), money(s["option"]),
             money(s["realized"]), money(s["dividend"]), money(s["pil"]),
             money(s["fees"]), money(s["total"])]))
        return lines

    # Group by configured account type. Grouped tables only appear
    # when there is genuinely more than one group — a single-type
    # project (or one with no taxjson.toml types) keeps the plain
    # one-table layout.
    group_defs = [
        ("TAXABLE", [r for r in acct_rows if r["type"] == "taxable"]),
        ("SHELTERED", [r for r in acct_rows if r["type"] == "sheltered"]),
        ("UNTYPED", [r for r in acct_rows
                     if r["type"] not in ("taxable", "sheltered")]),
    ]
    group_defs = [(g, rows) for g, rows in group_defs if rows]
    grouped = len(acct_rows) > 1 and len(group_defs) > 1

    # What the return's capital-gains entry asks for: taxable accounts
    # only, on form-export's convention, so these can never disagree with
    # the export. Canada: one row per Schedule 3 line (shares 13199/13200,
    # options & other properties 15199/15300, crypto-assets 15200/15301).
    # USA: Form 8949's own part totals — (d) proceeds, (e) cost, (g)
    # adjustment, (h) gain.
    from taxjson.bin.taxjson_form_export import (filing_6781,
                                                 filing_lines,
                                                 filing_parts_8949,
                                                 filing_totals,
                                                 load_dispositions,
                                                 mark_crypto,
                                                 year_not_ended_text)
    _settings = cfg.get("settings") or {}
    _fyear = year or _settings.get("year")
    _is_us = _country(_settings) \
        in ("us", "usa")
    # The date the gains files were scoped on — an explicit tax_date
    # that differs from the country default dropped a year-end sale
    # from FOR THE RETURN (R1-200).
    _date_key = ("date" if _tax_date_basis(_settings) == "trade"
                 else "date_settle")
    filing_rows: List[Dict[str, Any]] = []
    _filing_ents: List[Dict[str, Any]] = []
    for acct, p in files.items():
        if acct not in taxable_accounts:
            continue
        try:
            _ents, _ = load_dispositions([p], _fyear, _date_key)
        except (OSError, ValueError) as e:
            # Named once, exit 2 (backlog TJ-0641).
            _die_input(f"{acct}: could not read dispositions from "
                       f"{_work_read_why(p, e, root)}",
                       "Re-run `tjs run` to rebuild it (the FOR THE "
                       "RETURN block cannot leave a taxable account out).")
        if ((cfg.get("accounts") or {}).get(acct) or {}).get("crypto"):
            _ents = mark_crypto(_ents)
        _filing_ents += _ents
        if _is_us:
            try:
                _parts = filing_parts_8949(_ents, _fyear)
            except SystemExit as e:
                # Dropping the account (and, below, every account's
                # Part I/II lines) printed RETURN 0.00 next to a nonzero
                # realized total with rc 0, where form-export fails and
                # the Canada branch dies (A2-1120).
                _die(f"{acct}: {e}",
                     "Re-run `tjs run` to rebuild it (the FOR THE "
                     "RETURN block cannot leave a taxable account out).")
            filing_rows.append({"account": acct, **{
                k: round(sum(x[k] for x in _parts), 2)
                for k in ("proceeds", "cost", "adjustment", "gain")},
                "dispositions": len(_ents)})
        else:
            filing_rows.append({"account": acct,
                                **filing_totals(_ents, _fyear,
                                                _date_key)})
    filing_line_rows: List[Dict[str, Any]] = []
    _filing_6781: Optional[Dict[str, Any]] = None
    if _is_us:
        try:
            filing_line_rows = filing_parts_8949(_filing_ents,
                                                 _fyear)
            # §1256 contracts stay off Form 8949 (Form 6781 by hand,
            # US-FUT-02 / US-OPT-04; A2-0324): shown beside the block.
            _filing_6781 = filing_6781(_filing_ents)
        except SystemExit:
            filing_line_rows = []           # warned per account above
        _fkeys = ("proceeds", "cost", "adjustment", "gain")
    else:
        filing_line_rows = filing_lines(_filing_ents, _fyear, _date_key)
        _fkeys = ("proceeds", "acb", "outlays", "gain", "denied")
    filing_total = {k: round(sum(r[k] for r in filing_line_rows), 2)
                    for k in _fkeys}
    # The part of the denial that no replacement's basis/ACB ever
    # recovers: Canada, a registered-account (or affiliated)
    # acquisition (s.40(2)(g)(i)); USA, a repurchase in an IRA (US-
    # WASH-11). The footer said every denied amount moves to the
    # replacement (S043-02, S048-04; the US twin A2-0647).
    from taxjson.lib.futures import section_1256_kind as _s1256k
    _ents_8949 = ([e for e in _filing_ents
                   if not _s1256k(str(e.get("symbol") or ""))]
                  if _is_us else _filing_ents)
    filing_total["permanently_denied"] = round(sum(
        float(e.get("permanently_disallowed") or 0.0)
        for e in _ents_8949), 2)
    if not _is_us:
        # An in-kind contribution's loss, nil by s.40(2)(g)(iv) — its own
        # figure, never in DENIED (CA-INKIND-03).
        filing_total["denied_contribution"] = round(sum(
            float(e.get("denied_contribution") or 0.0)
            for e in _ents_8949), 2)
    if _filing_6781 is not None:
        filing_total["section_1256_gain"] = _filing_6781["gain"]
    # The RETURN row sums the per-row cents, as filed; the gains files,
    # wash-sales and audit total the unrounded engine values — a few
    # cents apart on a large year (R1-166). Shown, not hidden. (US: the
    # §1256 contracts are not on the RETURN row, so not in this either.)
    _engine_gain = round(sum(float(e.get("gain") or 0.0)
                             for e in _ents_8949), 2)
    _round_gap = (round(filing_total.get("gain", 0.0) - _engine_gain, 2)
                  if filing_line_rows else 0.0)
    if want_estimate and not _is_us and filing_line_rows:
        # Canada: the estimate taxes the gain the user files — the
        # RETURN row's per-row cents — not the unrounded engine total
        # summed from the account tables, a cent or so off the RETURN
        # row it printed under.
        est["realized"] = filing_total["gain"]
    # The DENIED column (US: the code-W adjustment) has the same per-row
    # rounding gap; R1-166's headline mismatch was a denied total, and
    # form-export already names it (A2-0912).
    _denied_key = "adjustment" if _is_us else "denied"
    _engine_denied = round(sum(
        float(e.get("disallowed_amount") or 0.0) for e in _ents_8949
        # Form 8949 adds back only a positive disallowance (code W).
        if not _is_us or float(e.get("disallowed_amount") or 0.0) > 1e-9),
        2)
    _denied_gap = (round(filing_total.get(_denied_key, 0.0)
                         - _engine_denied, 2)
                   if filing_line_rows else 0.0)
    _denied_label = "adjustment (g)" if _is_us else "denied"
    # FX on foreign cash (s.39(1.1)) is reported on line 15300 too
    # (T4037) but lives outside the engine's dispositions. The default
    # ledger (v1) is NOT RELIABLE and its figure is never shown as
    # reportable (CA-FX-07); the opt-in v2 says what it computed or why
    # it refused (_fx_cash_status).
    _fx_note: Optional[Dict[str, Any]] = None
    _fx_err = ""
    # Essentials first (docs/output-style.md): shown to a person without
    # --details, each warning below is one `! ` line after the tables
    # (`_acts`); with --details, under --json, or captured (width 0) it
    # is the full stderr message it always was.
    _full_msgs = (_details(args) or bool(getattr(args, "json", False))
                  or _out.width(sys.stderr) == 0)
    _acts: List[str] = []
    if filing_rows and not _is_us:
        import contextlib as _ctx
        import io as _io
        _fx_buf = _io.StringIO()
        try:
            with _ctx.redirect_stderr(_fx_buf):
                _fx_note = _fx_cash_status(root, cache)
            _fx_note = dict(_fx_note, line="15300")
        except SystemExit as e:
            # The ledger refused (an unreadable or missing native tx
            # file): say so instead of a silent pointer (S005-04).
            _fx_note, _fx_err = None, str(e.code or "")
        except Exception as e:                      # noqa: BLE001
            _fx_note, _fx_err = None, f"{type(e).__name__}: {e}"
        _fx_warn = [ln for ln in _fx_buf.getvalue().splitlines()
                    if "warning" in ln.lower()]
        if (_fx_err or _fx_warn) and not _full_msgs:
            _acts.append(_out.act(
                "FX-on-cash (line 15300) estimate "
                + ("omitted" if _fx_err else "built with warnings"),
                "tjs fx-cash"))
        elif _fx_err or _fx_warn:
            _out.warn("FX-on-cash (line 15300) estimate "
                      + ("omitted" if _fx_err else
                         "built with warnings"), prog=_prog,
                      details=([_fx_err] if _fx_err else
                               [ln.strip() for ln in _fx_warn]))
    # Base currency is just a label here — soft-read, no hard config
    # dependency (the command works from the work/ gains files).
    base = _base_currency(root)
    # The engine's conservation check (a cost or quantity the books lost
    # track of) reached only each account's .sum DIAGNOSTICS: said here
    # too, and carried in --json's readiness (2026-10 critique).
    from taxjson.lib import readiness as _RD
    _conservation = _RD.conservation_lines(files.values())
    if _conservation and not _full_msgs:
        _acts.append(_out.act(
            f"{_count_noun(len(_conservation), 'conservation problem')} in "
            f"the books: a cost or quantity the totals do not account for",
            "tjs audit"))
    elif _conservation:
        _out.warn(f"{_count_noun(len(_conservation), 'conservation problem')}"
                  f" in the books: a cost or quantity the totals do not "
                  f"account for", prog=_prog, details=_conservation)
    # An assignment's premium no stock leg took is in no gain of a
    # taxable account: the filing totals leave it out (backlog TJ-0824).
    _unconsumed = _RD.unconsumed_premium_lines(
        p for a, p in files.items() if a in taxable_accounts)
    _unc_head = ("option-assignment premium in no gain: an assignment's "
                 "stock leg is not in the books")
    if _unconsumed and not _full_msgs:
        _acts.append(_out.act(_unc_head, "tjs audit"))
    elif _unconsumed:
        _out.warn(_unc_head, prog=_prog, details=_unconsumed)
    # Dividend compensation on a short still inside its 45 days: the
    # year's income moves if it is covered in time (backlog TJ-1065).
    _unsettled_comp = _RD.unsettled_compensation_lines(
        p for a, p in files.items() if a in taxable_accounts)
    _usc_head = (f"{_count_noun(len(_unsettled_comp), 'dividend compensation payment')}"
                 f" on a short still inside its 45 days: not settled")
    if _unsettled_comp and not _full_msgs:
        _acts.append(_out.act(_usc_head, "tjs sum --details"))
    elif _unsettled_comp:
        _out.warn(_usc_head, prog=_prog, details=_unsettled_comp)
    if tainted_included and not _full_msgs:
        _acts.append(_out.act(
            f"totals include {_count_noun(tainted_included, 'sale')} with an "
            f"unknown cost; the filing totals leave them out",
            "tjs form-export"))
    elif tainted_included:
        # In-line tainted rows (raw engine output): counted in totals.
        _out.warn(f"totals include {tainted_included} disposition(s) "
                  f"with an unknown cost (no purchase in your files)",
                  prog=_prog,
                  details=["form-export and carryover exclude them, so "
                           "the filing totals will differ."])
    if tainted_routed and not _full_msgs:
        _acts.append(_out.act(
            f"{_count_noun(tainted_routed, 'sale')} with an unknown cost NOT "
            f"in these totals: report them by hand", "tjs form-export"))
    elif tainted_routed:
        # Pipeline files: tainted rows were STRIPPED to the
        # manual_reporting_required section — totals exclude them, and
        # without this line `sum` gave no signal at all (round-five
        # audit finding: the warning was dead code for pipeline
        # files).
        _out.warn(f"{tainted_routed} disposition(s) with an unknown cost "
                  f"(no purchase in your files) were routed to manual "
                  f"reporting — these totals EXCLUDE them", prog=_prog,
                  details=["`tjs form-export` lists them in its MANUAL "
                           "REPORTING section; report them by hand."])
    # Sales with no purchase in the files that no .tt OPENING
    # cost=unknown line covers: the engine books them as an open short, so their gain is
    # simply not in these totals — and nothing above said so for a
    # Questrade / RBC / Webull sale (new-user study).
    # Only the sales the gains files lack are out of the totals
    # (first_run.engine_booking): one the engine closed as a short sale
    # within the year, or sold from a purchase it reads first, is in
    # them.
    _no_purchase = _uncovered_sales(root, cfg,
                                    getattr(args, "account", None) or None)
    _uncovered = [{k: v for k, v in r.items() if k != "booked"}
                  for r in _no_purchase if r.get("booked") == "open"]
    _in_totals = [r for r in _no_purchase if r.get("booked") != "open"]
    _covers = [r for r in _in_totals if r.get("booked") == "short_cover"]
    if _covers and not _full_msgs:
        # (Short enough to name a symbol within 100 columns: "with no
        # purchase in your files ... a later purchase closed" passed
        # them with one name, backlog TJ-0229.)
        _acts.append(_out.act_list(
            f"{_count_noun(len(_covers), 'sale')} with no purchase booked "
            f"as shorts covered later",
            [r["symbol"] for r in _covers], "tjs find-missing-history"))
    elif _covers:
        _shown_c = ", ".join(f"{r['symbol']} ({r['account']})"
                             for r in _covers[:4]) \
            + (f" +{len(_covers) - 4} more" if len(_covers) > 4 else "")
        _out.warn(f"{len(_covers)} position(s) sold in "
                  f"{(cfg.get('settings') or {}).get('year')} with no "
                  f"purchase in your files were booked as short sales "
                  f"closed by a later purchase: their gain is in these "
                  f"totals at that purchase's cost", prog=_prog,
                  details=[f"No .tt OPENING cost=unknown line: {_shown_c}.",
                           "If you held the shares before your files "
                           "start, `tjs find-missing-history` lists "
                           "them and the fixes (docs/getting-started.md, "
                           "step 5)."])
    if _uncovered and not _full_msgs:
        _acts.append(_out.act_list(
            f"{_count_noun(len(_uncovered), 'sale')} with no purchase NOT in "
            f"these totals", [r["symbol"] for r in _uncovered],
            "tjs find-missing-history"))
    elif _uncovered:
        _shown = ", ".join(f"{r['symbol']} ({r['account']})"
                           for r in _uncovered[:4]) \
            + (f" +{len(_uncovered) - 4} more" if len(_uncovered) > 4
               else "")
        _out.warn(f"{len(_uncovered)} position(s) sold in "
                  f"{(cfg.get('settings') or {}).get('year')} with no "
                  f"purchase in your files: their gain is NOT in these "
                  f"totals", prog=_prog,
                  details=[f"No .tt OPENING cost=unknown line: {_shown}.",
                           "`tjs find-missing-history` lists them and "
                           "the fixes (docs/getting-started.md, step 5)."])
    # An in-kind move to or from a registered account the run could not
    # value is NOT booked: a contribution's deemed sale (or a
    # withdrawal's purchase) is missing from the books, and only the
    # run's own warning said so (backlog TJ-0095).
    _ik_unbooked = [m for m in in_kind_unbooked(cache, _fyear)
                    if m.get("taxable") in files]
    _ik_head = (f"{_count_noun(len(_ik_unbooked), 'in-kind move')} with a "
                f"registered account NOT booked: NOT in these totals")
    if _ik_unbooked and not _full_msgs:
        _acts.append(_out.act_list(
            _ik_head, sorted({str(m.get("symbol")) for m in _ik_unbooked}),
            "tjs transfers"))
    elif _ik_unbooked:
        _ik_in = _PL.shown(_PL.inputs_dir(root), root)
        _out.warn(_ik_head, prog=_prog,
                  details=[in_kind_fix_line(m, base, _ik_in)
                           for m in _ik_unbooked]
                  + ["Then re-run `tjs run`; `tjs transfers` "
                     "lists every move (docs/tax-rules.md, In-kind "
                     "contributions and withdrawals)."])
    # Scope: unlike the filing commands (carryover/t1135/form-export,
    # taxable-only by law), this summary rolls up EVERY account — say so
    # when sheltered accounts contribute, or the totals look like filing
    # numbers they aren't.
    sheltered_included = []
    try:
        acct_cfg = (load_config(root).get("accounts", {})
                    if _PL.has_config(root) else {})
        sheltered_included = sorted(
            a for a in files
            if acct_cfg.get(a, {}).get("type") == "sheltered")
    except SystemExit:
        pass
    from taxjson.lib import loss_overrides as _LO
    _positions = _LO.positions(
        _LO.gather(files), year,
        "trade" if _date_key == "date" else "settle")
    if getattr(args, "json", False):
        doc: Dict[str, Any] = {
            "accounts": acct_rows,
            "tainted_included": tainted_included,
            "tainted_routed": tainted_routed,
            # The same counts under their plain name ("tainted" is the
            # engine's word for a disposition with an unknown cost; the
            # keys above stay for existing readers).
            "unknown_cost_included": tainted_included,
            "unknown_cost_routed": tainted_routed,
            # Sales with no purchase that no .tt OPENING cost=unknown
            # line covers and the gains files lack: not in the totals at all
            # (an open short).
            "no_purchase_uncovered": _uncovered,
            # Such sales the gains engine booked (a short sale a later
            # purchase of the year closed, or sold from a purchase it
            # reads first): in the totals.
            "no_purchase_in_totals": _in_totals,
            # Same row-sum path as the printed tables and subtotals, so
            # totals == Σ subtotals == Σ rows holds exactly for machine
            # consumers (the unrounded accumulation drifted by a cent).
            "totals": _sum_rows(acct_rows),
            "basis": basis, "year": year, "currency": base,
            "filing": {"accounts": filing_rows, "totals": filing_total,
                       ("parts_8949" if _is_us else "lines"):
                           filing_line_rows,
                       "fx_cash": _fx_note,
                       "engine_gain_unrounded": _engine_gain,
                       "engine_denied_unrounded": _engine_denied,
                       "date_basis": _date_key},
            "sheltered_included": sheltered_included,
            "run_state_problems": _run_state,
            # One record of whether the figures are complete (lib/
            # readiness): the keys above, and the engine's conservation
            # warnings, as `complete` and `issues`.
            "readiness": _RD.build(
                run_state=_run_state or (), unknown_cost=tainted_routed,
                no_purchase=len(_uncovered),
                conservation=_conservation,
                in_kind_unbooked=len(_ik_unbooked),
                unconsumed_premium=_unconsumed,
                unsettled_compensation=_unsettled_comp),
            "subtotals": {g.lower(): _sum_rows(rows)
                          for g, rows in group_defs}}
        if _positions:
            # The user's filing positions against the loss rule (.tt
            # ALLOWLOSS): in the totals above, listed so they are never
            # silent (CA-SL-18 / US-WASH-25).
            doc["filing_positions"] = _positions
        if want_estimate:
            doc["estimate"] = _tax_estimate_result(
                cfg, est,
                other_income=_oi, other_losses=_ol,
                deductions=_ded, carrying_charges=_cc, lt_losses=_ltl,
                amt_carryover=_amt_in, carry_sources=_carry_src,
                province=getattr(args, "province", None),
                federal_only=bool(getattr(args, "federal_only", False)),
                **_withholding_of_year(
                    cache, set(files) & taxable_accounts,
                    year or (cfg.get("settings") or {}).get("year"),
                    _foreign_by_acct, _foreign_by_sec))
            _iyear = year or (cfg.get("settings") or {}).get("year")
            _r = doc["estimate"]
            if not _is_us and "losses_unused" in _r:
                # The T1A carry-back the console prints (TJ-0084);
                # `losses_unused` stays the figure before it (backlog
                # TJ-0226).
                _back = _losses_carried_back(root, cfg, _iyear,
                                             _r["losses_unused"])
                _r["losses_carried_back"] = round(_back, 2) + 0.0
                _r["losses_carried_forward"] = round(
                    _r["losses_unused"] - _back, 2) + 0.0
            _idoc = _instalments_doc(
                root, doc["estimate"], _iyear,
                _instalment_config(root, _iyear))
            if _idoc:
                doc["instalments"] = _idoc
        _json_out(doc)
        return

    def _para(text: str, indent: str = "") -> None:
        for _ln in _out.wrap(text, None, indent, indent):
            print(_ln)

    def _item(text: str) -> None:
        for _ln in _out.wrap(text, None, "- ", "  "):
            print(_ln)

    def _rounding_legend() -> None:
        # The taxable accounts' SUBTOTAL adds the account rows (each
        # rounded once), the RETURN row each sale's cents: the legend
        # says so when they differ, where the reader compares them
        # (backlog TJ-0209; the US §1256 net is off the RETURN row).
        _sub = round(sum(r["realized"] for r in acct_rows
                         if r["account"] in taxable_accounts), 2)
        _ret = (float(filing_total.get("gain") or 0.0)
                + float((_filing_6781 or {}).get("gain") or 0.0))
        if filing_line_rows and abs(_sub - _ret) >= 0.005:
            # Not led by a row label: a line that starts "RETURN " or
            # "TOTAL" reads as that row to a script.
            _para(f"The {'SUBTOTAL' if grouped else 'TOTAL'} adds the "
                  f"account rows, RETURN each sale's cents: they can "
                  f"differ by a cent or two.")

    _det = _details(args)
    print(f"REALIZED-GAINS SUMMARY — {base}, tax year {year}, "
          f"basis: {basis}")
    # The legend, before the tables (docs/output-style.md, Essentials
    # first): what the columns mean, and a crypto row's DIVIDEND.
    _para("REALIZED = NON-OPT (shares, units, futures, crypto) + OPTION; "
          "TOTAL = REALIZED + DIVIDEND + PIL.")
    _stk = [r for r in acct_rows
            if r.get("dividend_is_staking") and abs(r["dividend"]) >= 0.005]
    if _stk:
        # The crypto rows' DIVIDEND is staking rewards: ordinary income
        # (no gross-up/credit, no withholding), as the estimate treats
        # it — not a figure for the dividend lines (S023-11).
        _para("DIVIDEND of " + ", ".join(r["account"] for r in _stk)
              + " is staking rewards: ordinary income, not dividends.")
    _filing = ("carryover and form-export" if _is_us
               else "carryover, t1135 and form-export")
    if sheltered_included and (_det or not grouped):
        _para(f"Totals include sheltered account(s) "
              f"{', '.join(sheltered_included)} — not taxable events; "
              f"{_filing} exclude them.")
    print()
    _tdrop = (6, 5)           # FEES, then PIL, when the width is short
    if grouped:
        for gname, rows in group_defs:
            print(f"{gname} ACCOUNTS"
                  + (" — not taxable" if gname == "SHELTERED" else ""))
            _print_report_table(_table_lines(rows, "SUBTOTAL"),
                                rule_before_last=True, fit=True,
                                drop=_tdrop)
            print()
        print("ALL ACCOUNTS"
              + (" — sheltered included" if sheltered_included else ""))
    _print_report_table(_table_lines(acct_rows, "TOTAL"),
                        rule_before_last=True, fit=True, drop=_tdrop)
    if _stk and _det:
        _para("DIVIDEND for crypto account(s) "
              + ", ".join(f"{r['account']} ({money(r['dividend'])})"
                          for r in _stk)
              + " is STAKING rewards — ordinary income, not dividends.")

    # After the data: the one-line act-on and must-not-miss lines
    # (`_acts`, `_tail`); --details adds the notes they leave out.
    _tail: List[str] = []
    if filing_rows:
        _names = ", ".join(r["account"] for r in filing_rows)
        _ynote = year_not_ended_text(_fyear)
        print()
        if _is_us:
            _para(f"FOR THE RETURN — taxable accounts ({_names}), {base} "
                  f"(Form 8949 → Schedule D, tax year {_fyear})")
            if _ynote:
                _para(_ynote if _det else
                      f"Tax year {_fyear} has not ended: these are "
                      f"YEAR-TO-DATE figures.")
            _para("(h) = (d) − (e) + (g), the allowed gain; (g) = the "
                  "code-W wash-sale loss disallowed, added back.")
            _rounding_legend()
            _body = [[f"{r['label']} → {r['schedule_d']}",
                      money(r["proceeds"]), money(r["cost"]),
                      money(r["adjustment"]), money(r["gain"])]
                     for r in filing_line_rows]
            _foot = [["RETURN", money(filing_total["proceeds"]),
                      money(filing_total["cost"]),
                      money(filing_total["adjustment"]),
                      money(filing_total["gain"])]]
            for _ln in _out.fit_table(
                    ["FORM 8949", "(d) PROCEEDS", "(e) COST",
                     "(g) ADJUSTMENT", "(h) GAIN"], _body,
                    aligns=["<", ">", ">", ">", ">"], foot=_foot):
                print(_ln)
            _permd = filing_total.get("permanently_denied") or 0.0
            if _filing_6781 and _filing_6781.get("dispositions"):
                _acts.append(_out.act(
                    f"{_count_noun(_filing_6781['dispositions'], '§1256 sale')}"
                    f", net {money(_filing_6781['gain'])}, not on Form "
                    f"8949: Form 6781 by hand", "tjs form-export"))
            if _det:
                print()     # the notes stand apart from the RETURN row
                _item("(d) − (e) + (g) = (h). Column (g) is the code-W "
                      "wash-sale loss disallowed and added back, so (h) "
                      "is the allowed gain; the disallowed loss moves to "
                      "the replacement shares' basis"
                      + (f", except {money(_permd)} from a repurchase in "
                         f"an IRA, which is lost for good — no basis "
                         f"addition (US-WASH-11)" if _permd > 0.005
                         else "") + ".")
                if _filing_6781 and _filing_6781.get("dispositions"):
                    _item(f"Not on Form 8949: "
                          f"{_filing_6781['dispositions']} §1256 contract "
                          f"disposition(s), net "
                          f"{money(_filing_6781['gain'])} — Form 6781 by "
                          f"hand (60/40; year-end marking not modelled, "
                          f"US-FUT-02 / US-OPT-04). `tjs form-export` "
                          f"lists them.")
                if abs(_round_gap) >= 0.005:
                    _item(f"Rows are rounded to the cent, as filed: the "
                          f"gains files' unrounded total gain is "
                          f"{money(_engine_gain)} ({_round_gap:+,.2f} on "
                          f"the RETURN row).")
                if abs(_denied_gap) >= 0.005:
                    _item(f"Rows are rounded to the cent, as filed: the "
                          f"gains files' unrounded total {_denied_label} "
                          f"is {money(_engine_denied)} "
                          f"({_denied_gap:+,.2f} on the RETURN row).")
                _item("Per-sale rows: `tjs form-export`.")
            _tail.append("More: tjs sum --details (notes); per sale: "
                         "tjs form-export")
        else:
            _para(f"FOR THE RETURN — taxable accounts ({_names}), {base} "
                  f"(Schedule 3, tax year {_fyear})")
            if _ynote:
                _para(_ynote if _det else
                      f"Tax year {_fyear} has not ended: these are "
                      f"YEAR-TO-DATE figures.")
            _body = [[f"Line {r['line']} {r['short']} "
                      f"({r['proceeds_code']}/{r['gain_code']})"
                      if r["line"] else
                      f"{r['short']} ({r['proceeds_code']}/"
                      f"{r['gain_code']})",
                      money(r["proceeds"]), money(r["acb"]),
                      money(r["outlays"]), money(r["gain"]),
                      money(r["denied"])] for r in filing_line_rows]
            _foot = [["RETURN", money(filing_total["proceeds"]),
                      money(filing_total["acb"]),
                      money(filing_total["outlays"]),
                      money(filing_total["gain"]),
                      money(filing_total["denied"])]]
            # Too wide: DENIED goes first (its total moves to the legend),
            # then one record per line.
            _s3 = _out.fit_table(
                ["SCHEDULE 3 LINE", "PROCEEDS", "COST(ACB)", "OUTLAYS",
                 "GAIN", "DENIED"], _body,
                aligns=["<", ">", ">", ">", ">", ">"], foot=_foot,
                drop=(5,))
            _den_shown = any("DENIED" in _ln for _ln in _s3[:1])
            _para("GAIN = PROCEEDS − COST(ACB) − OUTLAYS, the allowed "
                  "gain; "
                  + ("DENIED = superficial losses denied." if _den_shown
                     else f"superficial losses denied: "
                          f"{money(filing_total['denied'])}."))
            _rounding_legend()
            for _ln in _s3:
                print(_ln)
            _permd = filing_total.get("permanently_denied") or 0.0
            # FX on foreign cash (line 15300): never in the rows.
            if _fx_note is None:
                _acts.append(_out.act("FX on foreign cash (line 15300) is "
                                      "not in the rows", "tjs fx-cash"))
            elif (_fx_note.get("ledger") == "v2"
                    and _fx_note.get("status") == "computed"):
                _acts.append(_out.act(
                    f"FX on foreign cash (line 15300), not in the rows: "
                    f"reportable {money(_fx_note['reportable'])}",
                    "tjs fx-cash"))
            elif _fx_note.get("ledger") == "v2":
                _acts.append(_out.act("FX on foreign cash (line 15300): "
                                      "not computed, not in the rows",
                                      "tjs fx-cash"))
            elif _fx_note.get("active"):
                _acts.append(_out.act("FX on foreign cash (line 15300): "
                                      "not in the rows; its estimate is "
                                      "NOT RELIABLE", "tjs fx-cash"))
            if _det:
                print()     # the notes stand apart from the RETURN row
                # A short sale's opening commission is not on its
                # closing row: it stays netted (backlog TJ-0119).
                _item("PROCEEDS − COST(ACB) − OUTLAYS = GAIN, the allowed "
                      "gain. A short sale shows what it brought in, net "
                      "of its opening commission, as PROCEEDS and the "
                      "cover as ACB; the commissions of other sales are "
                      "outlays, as on the form.")
                _item(f"Where a superficial loss was DENIED "
                      f"({money(filing_total['denied'])} in all) the ACB "
                      f"is REDUCED by it, so the gain stays the allowed "
                      f"one; a deferred denial is added to the ACB of the "
                      f"replacement property, but one caused by a "
                      f"registered-account acquisition is lost for good, "
                      f"and one caused by an affiliated person's "
                      f"acquisition is permanent for this return (that "
                      f"person adds it to their own ACB, s.53(1)(f)) — no "
                      f"ACB addition here"
                      + (f" ({money(_permd)} of the DENIED total)"
                         if _permd > 0.005 else "") + ".")
                _dcon = filing_total.get("denied_contribution") or 0.0
                if _dcon > 0.005:
                    _item(f"Denied: contribution to a registered plan — "
                          f"{money(_dcon)} of losses on in-kind "
                          f"contributions to an RRSP/TFSA/... are nil "
                          f"(s.40(2)(g)(iv)): the ACB shown is reduced by "
                          f"them, they are lost for good (no ACB addition "
                          f"anywhere) and they are not in DENIED.")
                if abs(_round_gap) >= 0.005:
                    _item(f"Rows are rounded to the cent, as filed: the "
                          f"gains files' unrounded total gain is "
                          f"{money(_engine_gain)} ({_round_gap:+,.2f} on "
                          f"the RETURN row).")
                if abs(_denied_gap) >= 0.005:
                    _item(f"Rows are rounded to the cent, as filed: the "
                          f"gains files' unrounded total {_denied_label} "
                          f"is {money(_engine_denied)} "
                          f"({_denied_gap:+,.2f} on the RETURN row).")
                if _fx_note is not None:
                    _item(_fx_sum_item(_fx_note, money))
                else:
                    _item("FX on foreign cash (s.39(1.1)) is not in the "
                          "rows above — T4037 puts it on line 15300; see "
                          "`tjs fx-cash`.")
                # Slip capital gains are part of line 19700 too (R1-44).
                _item("Capital gains on T3 (box 21) and T5/T5013 (box 18) "
                      "slips are not in the rows above — Schedule 3 lines "
                      "17600 and 17400, entered from the slips (the books "
                      "carry those distributions as dividends).")
                _item("Per-security rows: `tjs form-export`; per "
                      "account: `tjs sum --json`.")
            # Slip capital gains are part of line 19700 too (R1-44).
            _tail.append("Not in the rows: T3/T5 slip capital gains (lines "
                         "17600, 17400). More: tjs sum --details")

    if _positions:
        _rule = ("wash-sale rule (§1091)" if _is_us
                 else "superficial-loss rule (s.54)")
        _acts.append(_out.act(
            f"{_count_noun(len(_positions), 'loss', 'losses')} claimed "
            f"against the {_rule.split(' (')[0]} (.tt ALLOWLOSS)",
            "tjs sum --details"))
    if _positions and _det:
        print()
        # "the totals above include them" only of this year's sales: a
        # position on another year's sale shapes this year's ACB, not
        # its totals (pre-release review).
        _n_in = sum(1 for _fp in _positions if _fp["in_year"])
        _n_out = len(_positions) - _n_in
        _para(f"FILING POSITIONS — {len(_positions)} loss(es) claimed "
              f"against the {_rule} (.tt ALLOWLOSS lines)"
              + ("; the totals above include them" if not _n_out else
                 "; sales of another year: not in the totals above, "
                 "their effect on the " + ("basis" if _is_us else "ACB")
                 + " carries" if not _n_in else
                 f"; the totals above include the {_n_in} of this year, "
                 f"not the {_n_out} of another year"))
        for _fp in _positions:
            _item(f"{_fp['account']} {_fp['date']} {_fp['symbol']} "
                  f"{fmt_qty(_fp['qty'])} units: loss {money(_fp['loss'])} "
                  f"claimed; the rule would "
                  f"{'disallow' if _is_us else 'deny'} "
                  f"{money(_fp['would_disallow'])}"
                  + (f" ({money(_fp['would_permanent'])} for good)"
                     if _fp['would_permanent'] > 0.005 else "")
                  + f" — {_fp['why']}. Your reason: \"{_fp['reason']}\" "
                  f"({_fp['where']})"
                  + ("" if _fp["in_year"] else
                     " [a sale of another year: its effect on the "
                     + ("basis" if _is_us else "ACB") + " carries]"))
        _item("A filing position is yours, not the rule's test: be ready "
              "to support it (" + ("IRS" if _is_us else "CRA")
              + " guidance, a tax professional). Delete the line to apply "
              "the rule.")
    if not _det and (_acts or _tail):
        print()
        for _ln in _acts + _tail:
            print(_ln)

    if want_estimate:
        _print_tax_estimate(
            cfg, est, base,
            other_income=_oi, other_losses=_ol,
            deductions=_ded, carrying_charges=_cc, lt_losses=_ltl,
            amt_carryover=_amt_in, carry_sources=_carry_src,
            province=getattr(args, "province", None),
            verbose=getattr(args, "verbose", False),
            **_withholding_of_year(
                cache, set(files) & taxable_accounts,
                year or (cfg.get("settings") or {}).get("year"),
                _foreign_by_acct, _foreign_by_sec),
            root=root,
            year=year or (cfg.get("settings") or {}).get("year"))


def _instalment_config(root: Path,
                       year: Optional[int] = None) -> Dict[str, Any]:
    """Validated [instalments] table ({} when absent). Loud on bad
    input: these figures move money."""
    from taxjson.bin.taxjson_instalments import BASES
    _warn_config_tables(root)
    cfg = (_soft_config(root).get("instalments") or {})
    if not cfg:
        return {}
    out: Dict[str, Any] = {}
    basis = str(cfg.get("basis") or "current_year")
    if basis not in BASES:
        _die(f"[instalments] basis must be one of "
             f"{', '.join(BASES)}, got {basis!r}")
    out["basis"] = basis
    for key in ("prior_year_net_tax", "second_prior_net_tax",
                "withheld", "prescribed_rate"):
        v = cfg.get(key)
        if v is None:
            continue
        # Sign, finiteness and type, like paid[].amount: withheld = -5000
        # overstated net tax owing by 10,000, withheld = nan waived the
        # instalments, a negative rate zeroed the interest, and `true`
        # read as 1.0 — all at exit 0 (R1-217).
        out[key] = _nonneg_money(v, f"[instalments] {key}")
    # CRA resets the prescribed rate quarterly and charges each day at
    # the rate in force that day — so a dated schedule is accepted and
    # applied per day. A scalar prescribed_rate stays valid.
    if (cfg.get("prescribed_rate") is not None
            and cfg.get("prescribed_rates") is not None):
        _die("[instalments] set prescribed_rate OR prescribed_rates, "
             "not both — the dated schedule would silently win and "
             "the single rate be discarded.")
    if out.get("prescribed_rate", 0) >= 1.0:
        _die(f"[instalments] prescribed_rate is a DECIMAL fraction "
             f"(0.08 = 8%), got {out['prescribed_rate']} — that would "
             f"charge {out['prescribed_rate'] * 100:.0f}% a year.")
    if cfg.get("prescribed_rates") is not None:
        if not isinstance(cfg.get("prescribed_rates"), list):
            _die("[instalments] prescribed_rates must be a LIST of "
                 "{ from, rate } tables.")
        sched = []
        for i, row in enumerate(cfg.get("prescribed_rates") or [], 1):
            if not isinstance(row, dict):
                _die(f"[instalments] prescribed_rates[{i}] must be a "
                     f"table like {{ from = \"2026-07-01\", "
                     f"rate = 0.09 }}")
            try:
                # fromisoformat, not strptime: strptime ACCEPTS
                # unpadded "2026-9-01", which then sorts and compares
                # wrong as a string ("2026-9-01" > "2026-12-31"), so
                # the segment silently applied to the wrong window.
                frm = date_cls.fromisoformat(str(row["from"])).isoformat()
                r = _nonneg_money(row["rate"],
                                  f"[instalments] prescribed_rates[{i}]"
                                  f".rate")
                if r >= 1.0:
                    _die(f"[instalments] prescribed_rates[{i}].rate is "
                         f"a DECIMAL fraction (0.08 = 8%), got {r}.")
                sched.append({"from": frm, "rate": r})
            except (KeyError, TypeError, ValueError):
                _die(f"[instalments] prescribed_rates[{i}] needs a "
                     f"YYYY-MM-DD `from` and a numeric `rate`, got "
                     f"{row!r}")
        if not sched:
            _die("[instalments] prescribed_rates is empty — remove it "
                 "or give at least one { from, rate } entry.")
        out["prescribed_rates"] = sorted(sched,
                                         key=lambda x: x["from"])
    if basis == "prior_year" and "prior_year_net_tax" not in out:
        _die("[instalments] basis 'prior_year' needs "
             "prior_year_net_tax (last year's net tax owing).")
    if basis == "cra_reminder" and not (
            "prior_year_net_tax" in out
            and "second_prior_net_tax" in out):
        _die("[instalments] basis 'cra_reminder' needs both "
             "prior_year_net_tax and second_prior_net_tax (the two "
             "preceding years' net tax owing).")
    payments = []
    if cfg.get("paid") is not None and not isinstance(cfg.get("paid"),
                                                      list):
        _die("[instalments] paid must be a LIST of "
             "{ date, amount } tables.")
    for i, row in enumerate(cfg.get("paid") or [], 1):
        if not isinstance(row, dict):
            _die(f"[instalments] paid[{i}] must be a table like "
                 f"{{ date = \"2026-03-15\", amount = 15000 }}")
        d, a = row.get("date"), row.get("amount")
        try:
            # fromisoformat (see prescribed_rates): the downstream
            # walk parses with it, so an unpadded date accepted here
            # crashed later behind a misleading error.
            d = date_cls.fromisoformat(str(d)).isoformat()
            if isinstance(a, bool) or not isinstance(a, (int, float)):
                # A TOML number only: "5_000" read as 5000 (S043-05).
                raise TypeError("not a number")
            a = float(a)
            import math as _math
            if not _math.isfinite(a):
                raise ValueError("non-finite amount")
        except (TypeError, ValueError):
            _die(f"[instalments] paid[{i}] needs a YYYY-MM-DD `date` "
                 f"and a numeric `amount`, got {row!r}")
        if a < 0:
            _die(f"[instalments] paid[{i}] amount is negative "
                 f"({a}) — instalments are payments TO CRA; adjust "
                 f"the amount instead of recording a reversal.")
        if year:
            # Year-rollover trap: leaving LAST year's payments in the
            # table after bumping [settings] year made the schedule
            # read "met" with zero interest and fabricated credit
            # interest — silently the maximally wrong answer.
            # The balance's on-time day ends the year: April 30, or the
            # Monday after a weekend April 30 (backlog TJ-0915).
            from taxjson.bin.taxjson_instalments import \
                balance_payment_deadline
            lo, hi = (f"{year}-01-01",
                      balance_payment_deadline(int(year)).isoformat())
            # A prepayment made before January 1 counts only when the
            # row designates this year (`tax_year = YEAR`): an
            # undesignated prior-year date is the rollover trap above.
            # The interest model credits it from January 1 (A2-0648).
            _ty = row.get("tax_year")
            if _ty is not None and (isinstance(_ty, bool)
                                    or not isinstance(_ty, int)
                                    or _ty != int(year) or d >= lo):
                _die(f"[instalments] paid[{i}] tax_year = {_ty!r}: "
                     f"`tax_year` designates a payment made BEFORE "
                     f"January 1 as a prepayment of this project's "
                     f"{year} instalments — it must be {year}, on a "
                     f"row dated before {lo}.")
            if not (lo <= d <= hi) and _ty is None:
                _die(f"[instalments] paid[{i}] is dated {d}, outside "
                     f"tax year {year} ({lo}..{hi}). Instalments are "
                     f"per year — move it to that year's project or "
                     f"remove it"
                     + (f"; if it is a prepayment of the {year} "
                        f"instalments, add `tax_year = {year}` to the "
                        f"row (it earns credit from January 1)"
                        if d < lo else "") + ".")
        row_out = {"date": d, "amount": a}
        if row.get("note"):
            row_out["note"] = str(row["note"])
        payments.append(row_out)
    out["paid"] = sorted(payments, key=lambda p: p["date"])
    return out


def _net_tax_owing(r: Dict[str, Any], withheld: float) -> float:
    """Instalments are computed on NET TAX OWING — total tax for the
    year (not the incremental investment-income figure) minus amounts
    withheld at source, with any AMT top-up included and any minimum
    tax carryover recovered (s.120.2) taken off."""
    total = float((r.get("tax_with") or {}).get("total") or 0.0)
    total += float((r.get("amt") or {}).get("topup") or 0.0)
    total -= float(((r.get("amt") or {}).get("carryover") or {})
                   .get("recovered") or 0.0)
    return max(0.0, total - withheld)


def _instalments_doc(root: Path, r: Dict[str, Any], year,
                     icfg: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Build the instalment picture from an estimate result. None when
    the project declares no [instalments] table."""
    from taxjson.bin import taxjson_instalments as INST
    if not icfg or not year:
        return None
    # Canada-only regime: the US path (1040-ES) differs in dates,
    # safe harbours and penalty basis, and its estimate total omits
    # NIIT — so a US project must not receive a Canadian doc, not
    # even through `sum --estimate --json`.
    if _country(_soft_settings(root)) \
            not in ("canada", "ca"):
        return None
    net = _net_tax_owing(r, float(icfg.get("withheld") or 0.0))
    # None (no rate configured) -> CRA's published quarterly rates.
    rate = (icfg.get("prescribed_rates")
            if icfg.get("prescribed_rates")
            else icfg.get("prescribed_rate"))
    doc = INST.build(
        year=int(year), basis=icfg["basis"], current_net_tax=net,
        payments=icfg.get("paid") or [], annual_rate=rate,
        prior_net_tax=icfg.get("prior_year_net_tax"),
        second_prior_net_tax=icfg.get("second_prior_net_tax"))
    doc["rate_configured"] = bool(icfg.get("prescribed_rates")) or (
        icfg.get("prescribed_rate") is not None)
    return doc


def _relay_child_stderr(text: str) -> None:
    """Show a captured child's stderr (captured unwrapped, lib/dispatch)
    to the person: each message line wrapped at the house width with its
    continuation indented, each indented detail line wrapped under
    itself (docs/output-style.md: whoever shows captured text wraps
    it), the label first and the child named as the source
    (`Warning: tjs estimate: ...`, lib/out.labelled)."""
    from taxjson.lib.out import labelled, wrap
    for ln in (text or "").splitlines():
        if not ln.strip():
            continue
        if ln[:1].isspace() and not _CURRENT_DETAILS:
            # Essentials first (docs/output-style.md): a message's
            # detail lines with --details only; the headline always.
            continue
        ln = labelled(ln, sys.stderr, source=True)
        lead = ln[:len(ln) - len(ln.lstrip())]
        for w in wrap(ln.strip(), None, lead, lead or "  ",
                      stream=sys.stderr):
            print(w, file=sys.stderr)


def cmd_instalments(args: argparse.Namespace) -> None:
    """`tjs instalments`: the year's instalment schedule, what each
    date calls for, what has been paid, and the offset interest /
    s.163.1 penalty that follows from the gap. The current-year basis
    is driven by `tjs estimate` itself (AMT included), so the two
    commands can never disagree."""
    import json as _json
    from taxjson.bin import taxjson_instalments as INST
    from taxjson.lib.dispatch import run_cmd as _run
    root = Path(args.dir).resolve()
    icfg = _instalment_config(root, _soft_settings(root).get("year"))
    if not icfg:
        _die("no [instalments] section in taxjson.toml",
             "Add one with basis, withheld and paid (docs/settings.md, "
             "[instalments]).")
    settings = _soft_settings(root)
    year = settings.get("year")
    base = str(_base(settings))
    if _country(settings) \
            not in ("canada", "ca"):
        _die("instalments are modeled for canada only",
             "US estimated taxes use a different regime — see "
             "docs/limits.md.")
    _oi, _ol = _estimate_inputs(root, args)
    _ded, _cc = _estimate_deductions(root, args)
    _argv = _self_cmd(root, "estimate", "--json")
    if _oi:
        _argv += ["--other-income", repr(_oi)]
    if _ol:
        _argv += ["--other-losses", repr(_ol)]
    if _ded:
        _argv += ["--deductions", repr(_ded)]
    if _cc:
        _argv += ["--carrying-charges", repr(_cc)]
    res = _run(_argv, capture_output=True)
    if res.returncode != 0:
        # The estimate's exit 2 (a work/ file it cannot read, a usage
        # error) stays 2: 1 is a command's finding (backlog TJ-0641).
        (_die_input if res.returncode == 2 else _die)(
            "could not compute the estimate it builds on",
            _child_error(res.stderr))
    # The estimate's own warnings (an unreadable or stale-year gains
    # file, tainted sales EXCLUDED, a run that failed) are caveats on
    # every figure below: relay them, never swallow them (S005-05,
    # S007-04, S043-17, S047-22).
    if (res.stderr or "").strip():
        _relay_child_stderr(res.stderr)
    r = (_json.loads(res.stdout) or {}).get("estimate") or {}
    if not r:
        _die("the estimate produced no result",
             "Run `tjs run` first, and set [settings] province.")
    doc = _instalments_doc(root, r, year, icfg)
    if doc is None:
        _die("no `year` under [settings] in taxjson.toml",
             "The instalment schedule is per tax year.")
    # A year the built-in tables do not cover (a 2023 project on the
    # 2024 tables and the post-2024 AMT) must say so here too (S043-16).
    from taxjson.lib.tax_estimate import vintage_notes
    doc["vintage"] = r.get("vintage")
    doc["vintage_notes"] = (vintage_notes(year, str(r.get("vintage")))
                            if r.get("vintage") else [])
    # The verdict rests on TOTAL net tax owing. Unset other income and
    # withholding were read as 0 without a word, so an employee was
    # told "no instalments required" on the investment tax alone
    # (S041-00): name what was assumed.
    _est_cfg = _soft_config(root).get("estimate") or {}
    _assumed = []
    # `instalments` has no --other-income: the advice named one, and the
    # parser refused it (backlog TJ-0407). The toml key is the input.
    if (getattr(args, "other_income", None) is None
            and "other_income" not in _est_cfg):
        _assumed.append("other income (employment, pension, business) "
                        "is not set — assumed 0: set [estimate] "
                        "other_income in taxjson.toml")
    if "withheld" not in icfg:
        _assumed.append("tax withheld at source is not set — assumed 0: "
                        "set [instalments] withheld")
    doc["assumed_zero"] = _assumed
    # Not modelled at all (S043-15, S048-12): CPP/EI payable on
    # self-employment earnings is part of the instalment amount CRA
    # asks for (not of net tax owing or the $3,000 test), and the FX
    # result on foreign cash (line 15300) is outside the estimate.
    doc["not_modelled"] = [
        "CPP/EI payable on self-employment earnings (T1 lines 42100 / "
        "42120) — CRA adds it to the instalments due; add it yourself",
        "FX gains/losses on foreign cash (s.39(1.1), line 15300 — "
        "`tjs fx-cash`) and capital gains on T3/T5 slips are not in "
        "the estimate this schedule is built on"]
    if getattr(args, "json", False):
        _json_out(doc)
        return
    from taxjson.lib import out as _out
    if not _details(args):
        # Essentials first (docs/output-style.md): the explanations,
        # the assumptions and what is not modelled with --details.
        print(INST.render_brief(doc, base))
        if _assumed:
            print(_out.act("Assumed 0: " + ", ".join(
                a.split(" (")[0].split(" is ")[0] for a in _assumed),
                "tjs instalments --details"))
        if doc["vintage_notes"]:
            print(_out.act("Rate tables of another year used",
                           "tjs instalments --details"))
        print("Not modelled: self-employed CPP/EI, FX on cash, slip "
              "gains — tjs instalments --details")
        return
    print(INST.render(doc, base))

    def _items(texts) -> None:
        for _t in texts:
            for _ln in _out.wrap(_t, None, "  - ", "    "):
                print(_ln)

    if _assumed:
        print()
        print("  Assumed zero — the figures above cover the investment "
              "income only")
        _items(_n[:1].upper() + _n[1:] + "." for _n in _assumed)
    print()
    print("  Not modelled")
    _items(_n + "." for _n in doc["not_modelled"])
    if doc["vintage_notes"]:
        print()
        print("  Rate tables")
        _items(doc["vintage_notes"])


def cmd_estimate(args: argparse.Namespace) -> None:
    """`tjs estimate`: the realized-gains summary table followed by
    the tax ESTIMATE for the year's investment income — the same code
    path `sum` uses for its estimate block (the two can never
    disagree): tax(other income + investment income) minus
    tax(other income), on the filing (wash-adjusted) basis, FTC from
    the books' actual TAX rows. ESTIMATE ONLY — never filing
    numbers.

    Essentials first (docs/output-style.md): the default view is the
    estimate block alone (the gains table is `tjs sum`) with the
    summary's act-on `! ` lines; --details and --json keep the summary
    first."""
    args.estimate = True
    if getattr(args, "json", False) or _details(args):
        cmd_summary(args)
        return
    import contextlib as _ctx
    import io as _io
    import os as _os
    from taxjson.lib import out as _out
    buf = _io.StringIO()
    # The captured text keeps the width the person's stdout has.
    _old_w = _os.environ.get("TAXJSON_WIDTH")
    _os.environ["TAXJSON_WIDTH"] = str(_out.width(sys.stdout))
    try:
        with _ctx.redirect_stdout(buf):
            cmd_summary(args)
    except SystemExit:
        sys.stdout.write(buf.getvalue())
        raise
    finally:
        if _old_w is None:
            _os.environ.pop("TAXJSON_WIDTH", None)
        else:
            _os.environ["TAXJSON_WIDTH"] = _old_w
    text = buf.getvalue()
    at = text.find("TAX ESTIMATE —")
    head, block = (text[:at], text[at:]) if at >= 0 else ("", text)
    lines = block.rstrip("\n").split("\n")
    more = [ln for ln in lines if ln.startswith("More: ")]
    for ln in lines:
        if not ln.startswith("More: "):
            print(ln)
    # The act-on lines first, then the pointers to the long form.
    for ln in [x for x in head.split("\n") if x.startswith(_out.ACT)]:
        print(ln)
    for ln in more:
        print(ln.rstrip() + "; the return's lines: tjs sum")


def cmd_amt(args: argparse.Namespace) -> None:
    """`tjs amt [YEAR]`: the year's Canadian minimum tax line by
    line — regular tax, adjusted taxable income, exemption, rate,
    credits, whether it binds, the provincial AMT, the carryover
    created, the carryovers available by year of origin with their
    7-year limit, what is recovered and what carries forward. Every
    figure is the estimate's own (`tjs estimate --json`), so the
    two agree to the cent (tax-logic CA-AMT-01). A closed earlier
    year prints what its close-year lock recorded."""
    import json as _json
    from taxjson.lib import amt_report as AR
    from taxjson.lib import carryforward as CF
    from taxjson.lib.dispatch import run_cmd as _run
    root = Path(args.dir).resolve()
    settings = _soft_settings(root)
    if not settings:
        _die("no taxjson.toml here", "Run it in a project.")
    py = settings.get("year")
    year = args.year if args.year is not None else py
    if year is None:
        _die("no `year` under [settings] in taxjson.toml",
             "Pass YEAR.")
    if py is None or int(year) != int(py):
        from taxjson.bin import taxjson_filed
        try:
            lk = taxjson_filed.lock_for_year(root, settings, int(year))
        except taxjson_filed.PriorRecordError as e:
            _die(str(e))
        if lk is None:
            _die(f"this project's books are for {py}; {year} has no "
                 f"close-year lock here",
                 f"Neither filed/{year}.json nor [settings] "
                 f"prior_year_record. Run `tjs amt` in the {year} "
                 f"project.")
        try:
            # The one lock check, under this project's country: a US
            # lock is refused by name, not "records no minimum tax"
            # (2026-10-25 audit year-end#1).
            block = CF.lock_block(lk[0], _country(settings))
        except CF.CarryInputError as e:
            _die(str(e))
        mt = (block or {}).get("minimum_tax")
        label = taxjson_filed.lock_label(root, lk[0])
        if not isinstance(mt, dict):
            _die(f"{label} records no minimum tax",
                 f"It was closed before taxjson recorded carry-forwards, "
                 f"or with no province set. Run `tjs amt` in the "
                 f"{year} project, or re-close {year} there.")
        if getattr(args, "json", False):
            _json_out({"year": int(year), "recorded": True,
                       "lock": label, "minimum_tax": mt, "law": AR.LAW})
            return
        for ln in AR.render_recorded(int(year), label, mt):
            print(ln)
        return
    argv = _self_cmd(root, "estimate", "--json")
    for flag, attr in (("--other-income", "other_income"),
                       ("--other-losses", "other_losses"),
                       ("--deductions", "deductions"),
                       ("--carrying-charges", "carrying_charges"),
                       ("--province", "province")):
        v = getattr(args, attr, None)
        if v is not None:
            argv += [flag, str(v) if isinstance(v, str) else repr(v)]
    res = _run(argv, capture_output=True)
    if res.returncode != 0:
        # The estimate's exit 2 (a work/ file it cannot read, a usage
        # error) stays 2: 1 is a command's finding (backlog TJ-0641).
        (_die_input if res.returncode == 2 else _die)(
            "could not compute the estimate it builds on",
            _child_error(res.stderr))
    if (res.stderr or "").strip():
        _relay_child_stderr(res.stderr)
    r = (_json.loads(res.stdout) or {}).get("estimate") or {}
    if not r or not r.get("amt"):
        _die("the estimate produced no minimum tax result",
             "Run `tjs run` first, and set [settings] province.")
    doc = AR.build(r, int(year), str(_base(settings)))
    if getattr(args, "json", False):
        _json_out(doc)
        return
    for ln in AR.render(doc, details=_details(args)):
        print(ln)


def _wrap_note(text: str, indent: str = "  ") -> str:
    """Report prose wrapped to the house width (lib/out: 100, or the
    terminal's) — the AMT explanation and the assumptions footer ran off
    the edge on any terminal while every table beside them was capped."""
    from taxjson.lib.out import fill
    return fill(text, indent=indent)


def _trace_bracket_rows(brackets, ti_base: float, ti_with: float):
    """[(band label, base tax, with tax)] over every band either run
    reaches, band by band — the two-column body of the --verbose trace.
    A band's label ends where the higher of the two incomes stops in
    it: a band only the base run reaches (an investment loss moving the
    WITH run down a bracket) is listed with 0.00 in WITH, so each column
    adds up to its total (backlog TJ-0472)."""
    from taxjson.lib.tax_estimate import bracket_slices
    base = {lo: (hi, rate, tax) for lo, hi, rate, tax
            in bracket_slices(ti_base, brackets)}
    with_ = {lo: (hi, rate, tax) for lo, hi, rate, tax
             in bracket_slices(ti_with, brackets)}
    rows = []
    for lo in sorted(set(base) | set(with_)):
        hi = max(x[0] for x in (base.get(lo), with_.get(lo)) if x)
        rate = (with_.get(lo) or base[lo])[1]
        hi_s = "inf" if hi == float("inf") else f"{hi:,.0f}"
        rows.append((f"{lo:,.0f}-{hi_s} @ {rate * 100:.2f}%",
                     (base.get(lo) or (0, 0, 0.0))[2],
                     (with_.get(lo) or (0, 0, 0.0))[2]))
    return rows


def _print_trace_table(rows, money) -> None:
    for label, b, w in rows:
        print(f"    {label:<34}{money(b):>14}{money(w):>14}")


def _withholding_rows(cache: Path, taxable_accounts, year,
                      foreign_by_account=None,
                      noncash: Optional[Dict[str, List[Tuple]]] = None
                      ) -> Dict[str, Optional[List[Tuple]]]:
    """{account: [(date, net TAX amount, symbol)] of the tax year in its
    BASE book, or None when the book holds no TAX row in the year} — the
    withholding `_withholding_total` credits, each row with the security
    it was withheld on ("" when the row names none; backlog TJ-0638).
    The base books, not the
    gains files: the gains engine does not carry TAX rows through, so
    reading its output silently found nothing and the estimator always
    fell back to the flat 15% assumption. `noncash`, when given, is
    filled with {account: [(date, amount, symbol)]}: the year's taxable
    spin-off
    distributions (a deemed dividend paid in shares: no cash, so nothing
    withheld and no withholding to assume; backlog TJ-0422)."""
    from taxjson.lib.corp_actions import FMV_SPINOFF_ELECTIONS
    from taxjson.lib.income_dating import is_canadian_issuer
    from taxjson.lib.tax_estimate import CA_FOREIGN_WITHHOLDING
    ystr = str(year or "")
    foreign_by_account = foreign_by_account or {}
    out: Dict[str, Optional[List[Tuple]]] = {}
    # Sorted: callers pass a SET, whose order made the unrounded FTC
    # differ in its last digit from run to run (S043-20).
    for acct in sorted(taxable_accounts):
        p = Path(cache) / f"{acct}_base.json"
        try:
            data = _read_work_doc(p)
        except (OSError, ValueError) as e:
            # Skipping the account dropped its withholding AND its 15%
            # fallback while its foreign dividends were still taxed
            # (R1-223): fall back for it, and say so.
            if foreign_by_account.get(acct):
                emit_line(f"tjs: warning: could not read {p.name} "
                          f"({e}) — assuming {CA_FOREIGN_WITHHOLDING:.0%} "
                          f"withholding on {acct}'s foreign dividends; "
                          f"re-run `tjs run`.", file=sys.stderr)
            data = {}
        rows: List[Tuple] = []
        acct_seen = False
        for t in data.get("transactions", []):
            d = str(t.get("date") or "")
            if ystr and not d.startswith(ystr):
                continue
            sym = str(t.get("symbol") or "")
            # A foreign issuer's only, by the test the dividend split
            # uses (A2-0319): a Canadian one is not in the foreign
            # dividends the assumption applies to.
            if (noncash is not None and t.get("action") == "DIVIDEND"
                    and t.get("corp_election") in FMV_SPINOFF_ELECTIONS
                    and not is_canadian_issuer(t)):
                noncash.setdefault(acct, []).append(
                    (d, float(t.get("net_amount") or 0.0), sym))
            if t.get("action") != "TAX":
                continue
            acct_seen = True
            rows.append((d, float(t.get("net_amount") or 0.0), sym))
        out[acct] = rows if acct_seen else None
    return out


def _withholding_split(rows: Dict[str, Optional[List[Tuple]]],
                       foreign_by_account=None,
                       through: Optional[str] = None,
                       noncash: Optional[Dict[str, List[Tuple]]] = None
                       ) -> Tuple[Optional[float], float, float]:
    """(total, assumed, noncash) over `_withholding_rows`: `total` is
    the net TAX withheld (base currency; positive = withheld, refunds
    net) plus the 15% assumed for each account with no TAX row in the
    year, None when no account's book holds one (no data is not the
    same as no tax); `assumed` is the assumed part; `noncash` the
    spin-off deemed dividends of those accounts, which take no
    assumption (`_withholding_rows`' `noncash`; backlog TJ-0422). With
    `through` (ISO), the rows dated up to it only (`plot-tax`'s month:
    the credit a month's run takes is the withholding recorded by its
    end; backlog TJ-0299)."""
    # Only some parsers emit TAX rows (IB and RBC do; Questrade does
    # not), so an account with foreign dividends and no TAX rows must
    # fall back to the treaty ASSUMPTION for its own share — treating
    # one broker's withholding as the credit for the whole book
    # systematically under-credited. An account with TAX rows in the
    # year is credited what it recorded, never the assumption, before
    # its first one too.
    from taxjson.lib.tax_estimate import CA_FOREIGN_WITHHOLDING
    import math as _math
    foreign_by_account = foreign_by_account or {}
    noncash = noncash or {}
    seen = False
    # Summed exactly (S043-20).
    parts: List[float] = []
    assumed: List[float] = []
    shares: List[float] = []
    for acct in sorted(rows):
        acct_rows = rows[acct]
        if acct_rows is None:
            nc = _math.fsum(r[1] for r in noncash.get(acct) or ()
                            if through is None or r[0][:10] <= through)
            fd = float(foreign_by_account.get(acct) or 0.0)
            nc = min(max(0.0, nc), max(0.0, fd))
            shares.append(nc)
            assumed.append(CA_FOREIGN_WITHHOLDING * (fd - nc))
            continue
        seen = True
        parts.extend(r[1] for r in acct_rows
                     if through is None or r[0][:10] <= through)
    total = _math.fsum(parts + assumed)
    return (max(0.0, total) if seen else None, _math.fsum(assumed),
            _math.fsum(shares))


def _withholding_by_security(
        rows: Dict[str, Optional[List[Tuple]]],
        foreign_by_security: Dict[str, Dict[str, float]],
        through: Optional[str] = None,
        noncash: Optional[Dict[str, List[Tuple]]] = None
        ) -> List[Dict[str, Any]]:
    """`_withholding_split`'s withholding paired with each security's
    foreign dividends, the entries of tax_estimate.ca_withholding_limit,
    which counts each at most 15% of its security's own (ITA s.20(11),
    s.126(7); backlog TJ-0638; tax-logic CA-EST-FTC). A security's
    dividends (`foreign_by_security`: {account: {symbol: amount}}, a
    spin-off's deemed dividend in them) and TAX rows are summed across
    the taxable accounts; an account with no TAX row in the year adds
    the 15% assumed on each security's cash dividends (none on a
    deemed dividend). A TAX row that names no security, or one with no
    foreign dividend in the books, is its account's unpaired
    withholding: one entry per account, whose `dividends` are the
    account's foreign cash dividends of the securities none of its own
    TAX rows names, each up to the part of its security's dividends
    whose 15% the paired, the assumed and an earlier account's unpaired
    withholding leave (backlog TJ-0715). `through`: as
    `_withholding_split`'s."""
    from taxjson.lib.tax_estimate import CA_FOREIGN_WITHHOLDING
    import math as _math
    noncash = noncash or {}

    def _upto(rs):
        return [r for r in rs or ()
                if through is None or str(r[0])[:10] <= through]

    def _sym(r) -> str:
        return str(r[2]) if len(r) > 2 and r[2] else ""

    divs: Dict[str, List[float]] = {}
    for acct in sorted(foreign_by_security):
        for sym, v in foreign_by_security[acct].items():
            divs.setdefault(sym, []).append(float(v or 0.0))
    income = {s: _math.fsum(v) for s, v in divs.items()}

    def _cash(acct: str) -> Dict[str, float]:
        """{symbol: cash dividends} of an account: its foreign dividends
        less its spin-off deemed dividends; a deemed dividend booked
        under a symbol its dividends do not carry comes off the
        account's cash dividends pro rata (what `_withholding_split`
        takes off the account's)."""
        by = {s: max(0.0, float(v or 0.0))
              for s, v in (foreign_by_security.get(acct) or {}).items()}
        nc_by: Dict[str, List[float]] = {}
        for r in _upto(noncash.get(acct)):
            nc_by.setdefault(_sym(r), []).append(float(r[1]))
        cash: Dict[str, float] = {}
        left = 0.0
        for s, v in nc_by.items():
            n = max(0.0, _math.fsum(v))
            if s in by:
                cash[s] = max(0.0, by[s] - n)
                left += max(0.0, n - by[s])
            else:
                left += n
        for s, v in by.items():
            cash.setdefault(s, v)
        total = _math.fsum(cash.values())
        if left > 0 and total > 0:
            k = max(0.0, total - left) / total
            cash = {s: v * k for s, v in cash.items()}
        return cash

    withheld: Dict[str, List[float]] = {}
    assumed: Dict[str, List[float]] = {}
    unpaired: Dict[str, List[float]] = {}
    # The securities each account's own TAX rows name.
    named: Dict[str, set] = {}
    for acct in sorted(rows):
        acct_rows = rows[acct]
        if acct_rows is None:
            for s, c in _cash(acct).items():
                assumed.setdefault(s, []).append(CA_FOREIGN_WITHHOLDING * c)
            continue
        for r in _upto(acct_rows):
            s = _sym(r)
            if s and income.get(s, 0.0) > 0.005:
                withheld.setdefault(s, []).append(float(r[1]))
                named.setdefault(acct, set()).add(s)
            else:
                unpaired.setdefault(acct, []).append(float(r[1]))
    out: List[Dict[str, Any]] = [
        {"security": s, "dividends": income.get(s, 0.0),
         "withheld": _math.fsum(withheld.get(s) or ()),
         "assumed": _math.fsum(assumed.get(s) or ())}
        for s in sorted(set(income) | set(withheld) | set(assumed))]
    # Each security's dividends whose 15% room its paired (and assumed)
    # withholding leaves: an account's unpaired withholding may use it
    # on the account's own cash dividends of the securities none of ITS
    # TAX rows names. Excluding every security another account's TAX
    # rows named zeroed that room (backlog TJ-0715); the security's
    # 15% ceiling still holds across the accounts.
    left = {s: max(0.0, income.get(s, 0.0)
                   - (_math.fsum(withheld.get(s) or ())
                      + _math.fsum(assumed.get(s) or ()))
                   / CA_FOREIGN_WITHHOLDING)
            for s in income}
    for acct in sorted(unpaired):
        own = named.get(acct) or set()
        by = {s: min(c, left.get(s, 0.0))
              for s, c in _cash(acct).items() if s not in own}
        room = _math.fsum(by.values())
        w = _math.fsum(unpaired[acct])
        out.append({"security": "", "account": acct, "dividends": room,
                    "withheld": w, "assumed": 0.0})
        # The room this account's withholding takes, off each security
        # pro rata, so another account's cannot take it again.
        cap = CA_FOREIGN_WITHHOLDING * room
        k = min(1.0, max(0.0, w) / cap) if cap > 0 else 0.0
        for s, v in by.items():
            left[s] = max(0.0, left[s] - v * k)
    return out


def _withholding_total(rows: Dict[str, Optional[List[Tuple]]],
                       foreign_by_account=None,
                       through: Optional[str] = None,
                       noncash: Optional[Dict[str, List[Tuple]]] = None
                       ) -> Optional[float]:
    """The `total` of `_withholding_split`: the foreign tax withheld
    the estimate credits, None when no account has a TAX row."""
    return _withholding_split(rows, foreign_by_account, through,
                              noncash)[0]


def _withholding_kwargs(split: Tuple[Optional[float], float, float]
                        ) -> Dict[str, Any]:
    """`estimate_canada`'s withholding arguments from a
    `_withholding_split`: the total, its assumed part and the deemed
    dividends no withholding is assumed on (backlog TJ-0422)."""
    total, assumed, noncash = split
    return {"actual_withheld": total, "withheld_assumed": assumed,
            "foreign_div_noncash": noncash}


def _actual_withholding(cache: Path, taxable_accounts, year,
                        foreign_by_account=None) -> Optional[float]:
    """Net TAX withheld (base currency) across the taxable accounts'
    BASE books for the tax year (`_withholding_rows`,
    `_withholding_total`)."""
    return _withholding_of_year(cache, taxable_accounts, year,
                                foreign_by_account)["actual_withheld"]


def _withholding_of_year(cache: Path, taxable_accounts, year,
                         foreign_by_account=None,
                         foreign_by_security: Optional[
                             Dict[str, Dict[str, float]]] = None
                         ) -> Dict[str, Any]:
    """`_withholding_kwargs` for the tax year: the taxable accounts'
    BASE books' TAX rows, the 15% assumption for an account with none
    and its spin-off deemed dividends, which take none. With
    `foreign_by_security` ({account: {symbol: foreign dividends}}), the
    same withholding paired with each security's dividends as well
    (`withholding_by_security`: the 15% limit is each security's,
    backlog TJ-0638)."""
    nc: Dict[str, List[Tuple]] = {}
    rows = _withholding_rows(cache, taxable_accounts, year,
                             foreign_by_account, nc)
    kw = _withholding_kwargs(
        _withholding_split(rows, foreign_by_account, None, nc))
    if foreign_by_security is not None:
        kw["withholding_by_security"] = _withholding_by_security(
            rows, foreign_by_security, None, nc)
    return kw


def _tax_estimate_result(cfg: Dict[str, Any], est: Dict[str, float], *,
                         other_income: float, other_losses: float,
                         province: Optional[str],
                         actual_withheld: Optional[float] = None,
                         deductions: float = 0.0,
                         carrying_charges: float = 0.0,
                         lt_losses: float = 0.0,
                         amt_carryover: Optional[Dict[int, float]] = None,
                         carry_sources: Optional[Dict[str, Any]] = None,
                         federal_only: bool = False,
                         withheld_assumed: float = 0.0,
                         foreign_div_noncash: float = 0.0,
                         withholding_by_security=None
                         ) -> Dict[str, Any]:
    """Resolve country/province and run the estimator — shared by the
    text block and `sum --json` so the two can never disagree. For usa,
    un-termed gains are folded into ST (conservative) with a stderr
    note, and the ST input (post-fold, pre-loss) rides along as
    `st_input` for display. The withholding arguments are
    `_withholding_kwargs`' (Canada)."""
    from taxjson.lib.tax_estimate import estimate_canada, estimate_usa
    settings = cfg.get("settings", {})
    _est_year = settings.get("year")
    country = _country(settings)
    if country == "canada":
        prov = (province or str(settings.get("province", "") or "")).strip()
        if federal_only:
            # close-year with no supported province: the federal
            # carry-forwards, no province standing in (CA-CARRY-01).
            prov = None
        elif not prov:
            _die("the canada estimate needs a province",
                 "Pass --province ON|BC|AB or set `province` under "
                 "[settings] in taxjson.toml.")
        _cs = carry_sources or {}
        try:
            r = estimate_canada(realized=est["realized"],
                                   year=_est_year,
                                   eligible_div=est["div_ca"],
                                   foreign_div=est["div_foreign"],
                                   pil=est["pil"],
                                   other_income=other_income,
                                   other_losses=other_losses,
                                   province=prov,
                                   actual_withheld=actual_withheld,
                                   withheld_assumed=withheld_assumed,
                                   foreign_div_noncash=foreign_div_noncash,
                                   withholding_by_security=(
                                       withholding_by_security),
                                   staking=est.get("staking", 0.0),
                                   deductions=deductions,
                                   carrying_charges=carrying_charges,
                                   capital_gains_dividends=est.get(
                                       "cg_div", 0.0),
                                   amt_carryover=amt_carryover,
                                   amt_carryover_source=_cs.get(
                                       "amt_carryover"))
        except ValueError as e:
            _die(str(e))
        r["carry_sources"] = _carry_sources_doc(_cs)
        r["notes"] = list(_cs.get("notes") or []) + list(r.get("notes")
                                                         or [])
        return r
    if deductions or carrying_charges:
        _die("--deductions/--carrying-charges are modelled for the "
             "canada estimate only",
             "The US estimate is experimental and uses the standard "
             "deduction.")
    unterm = est["realized"] - est["st"] - est["lt"]
    st_in = est["st"]
    if abs(unterm) > 0.01:
        st_in += unterm
        from taxjson.lib.out import note as _onote
        _onote(f"{fmt_money(unterm)} of gains carry no ST/LT term — "
               f"treated as SHORT-TERM (conservative)",
               prog=f"tjs {_current_cmd() or 'sum'}",
               details=["Re-run `tjs run` to refresh."])
    # The year's own [carryover] claimed entry: the deduction its filed
    # return's taxable income absorbed, which the carryover after the
    # year (and close-year's lock) counts as used (backlog TJ-0464).
    from taxjson.lib.project_tables import claimed_losses
    try:
        _claimed = claimed_losses(cfg)[0].get(int(_est_year))
    except (TypeError, ValueError):
        _claimed = None
    # §1256 P/L leaves the term the engine gave it (a gain with no term
    # is in st_in) and comes back 40% short-term / 60% long-term, as
    # Form 6781 puts it on Schedule D (US-FUT-03; backlog TJ-0466).
    s1256 = float(est.get("s1256") or 0.0)
    s1256_lt = float(est.get("s1256_lt") or 0.0)
    # Dividend compensation paid on a short is no reduction of ordinary
    # income: deductible only as investment interest on Schedule A
    # (itemized), and the estimate takes the standard deduction; one on
    # a short covered within 45 days is already in the cover's cost
    # (§263(h); US-INC-04, backlog TJ-0728).
    _pil_paid = float(est.get("pil_paid") or 0.0)
    r = estimate_usa(st=st_in - (s1256 - s1256_lt),
                     lt=est["lt"] - s1256_lt, year=_est_year,
                     qualified_div=est["div_ca"] + est["div_foreign"],
                     pil=est["pil"] + _pil_paid + est.get("staking", 0.0),
                     other_income=other_income,
                     other_losses=other_losses,
                     lt_losses=lt_losses,
                     deduction_claimed=_claimed,
                     section_1256=s1256)
    if _claimed is not None:
        r["deduction_claimed"] = round(float(_claimed), 2)
    r["carryover_short_term"] = round(other_losses, 2)
    r["carryover_long_term"] = round(lt_losses, 2)
    r["carry_sources"] = _carry_sources_doc(carry_sources or {})
    r["notes"] = (list((carry_sources or {}).get("notes") or [])
                  + list(r.get("notes") or []))
    if abs(s1256) > 0.005:
        r.setdefault("notes", []).append(
            f"{fmt_money(s1256)} of §1256 P/L (futures, futures options, "
            f"broad-based index options such as SPX) is split 60/40 as "
            f"Form 6781 does, whatever the holding period: "
            f"{fmt_money(r['section_1256_short_term'])} short-term (40%) "
            f"and {fmt_money(r['section_1256_long_term'])} long-term "
            f"(60%). Not modelled: contracts still open at year end are "
            f"not marked to market, and a net §1256 loss is not carried "
            f"back (§1212(c)): both by hand on Form 6781.")
    if _pil_paid > 0.005:
        r["pil_paid_not_deducted"] = round(_pil_paid, 2)
        r.setdefault("notes", []).append(
            f"{fmt_money(_pil_paid)} of dividend compensation paid on "
            f"short sales is not subtracted from ordinary income: it is "
            f"deductible only as investment interest on Schedule A (Form "
            f"4952) when you itemize, and this estimate takes the "
            f"standard deduction (US-INC-04).")
    return r


def _carry_sources_doc(cs: Dict[str, Any]) -> Dict[str, Any]:
    """Where the estimate's carry-forward inputs came from (JSON)."""
    return {k: cs.get(k) for k in ("other_losses", "long_term_losses",
                                   "amt_carryover", "partial_lock")
            if k in cs}


def _print_tax_estimate(cfg: Dict[str, Any], est: Dict[str, float],
                        base_cur: str, *, other_income: float,
                        other_losses: float,
                        province: Optional[str],
                        deductions: float = 0.0,
                        carrying_charges: float = 0.0,
                        lt_losses: float = 0.0,
                        verbose: bool = False,
                        actual_withheld: Optional[float] = None,
                        root: Optional[Path] = None,
                        year: Optional[Any] = None,
                        amt_carryover: Optional[Dict[int, float]] = None,
                        carry_sources: Optional[Dict[str, Any]] = None,
                        withheld_assumed: float = 0.0,
                        foreign_div_noncash: float = 0.0,
                        withholding_by_security=None
                        ) -> None:
    """Marginal tax-estimate block under `tjs sum` — TAXABLE
    accounts only, incremental on top of --other-income. Assumptions
    are printed with the numbers; these are never filing figures.
    `verbose` appends the CALCULATION TRACE: every bracket slice,
    credit and surtax tier for the base and with-investments runs.
    Every printed rate is read from lib/tax_estimate's constants (the
    ones tax-logic states), never a literal."""
    from taxjson.lib import tax_estimate as _TE
    money = fmt_money
    r = _tax_estimate_result(cfg, est, other_income=other_income,
                             other_losses=other_losses, province=province,
                             actual_withheld=actual_withheld,
                             withheld_assumed=withheld_assumed,
                             foreign_div_noncash=foreign_div_noncash,
                             withholding_by_security=withholding_by_security,
                             deductions=deductions,
                             carrying_charges=carrying_charges,
                             lt_losses=lt_losses,
                             amt_carryover=amt_carryover,
                             carry_sources=carry_sources)
    # The result carries the vintage apply_vintage() actually selected
    # for the project year — never the import-time module default.
    RATE_VINTAGE = r.get("vintage", "?")
    from taxjson.lib import out as _out
    # Essentials first (docs/output-style.md): the figures and a legend;
    # the notes, the assumptions and the AMT explanation with --details
    # (the --verbose calculation trace is the most detailed view).
    details = _CURRENT_DETAILS or verbose
    # The default view's figure lines keep a column gap after the label
    # and its sub-headings start the line, so they read as a block of
    # figures (lib/out.classify); --details keeps the long layout.
    _g = " " if details else "  "
    _h = "  " if details else ""

    def _est_row(label: str, amt: float, note: str = "",
                 short: Optional[str] = None) -> None:
        # The default view takes the row's `short` note (one line).
        if not details and short is not None:
            note = short
        # `  label  amount  [note]`: a long note wraps under itself.
        head = f"  {label:<30}{money(amt):>14}"
        if not note:
            print(head)
            return
        for _ln in _out.wrap(note, None, head + "  ", " " * (len(head) + 2)):
            print(_ln)

    def _est_notes(indent: str) -> None:
        for _n in r.get("notes") or []:
            for _ln in _out.wrap(_n, None, indent + "- ", indent + "  "):
                print(_ln)

    def _assumes(text: str, indent: str = "  ") -> None:
        # "Assumes: a; b; c." as a list — split on the top-level "; "
        # only (a parenthesis may hold its own).
        body = text[len("Assumes:"):].strip() if text.startswith(
            "Assumes:") else text
        parts, depth, cur = [], 0, ""
        for i, ch in enumerate(body):
            depth += (ch == "(") - (ch == ")")
            if ch == ";" and depth == 0 and body[i + 1:i + 2] == " ":
                parts.append(cur.strip())
                cur = ""
                continue
            cur += ch
        parts.append(cur.strip().rstrip("."))
        if not details:
            return
        print(indent + "Assumes:")
        for _p in parts:
            if _p:
                for _ln in _out.wrap(_p, None, indent + "- ",
                                     indent + "  "):
                    print(_ln)

    def _est_tail(res: Dict[str, Any], yr, assumes: str) -> None:
        # The default view's closing lines: a rate-table mismatch to act
        # on, then the assumptions and notes behind --details.
        if year is not None and str(res.get("vintage")) != str(yr):
            print(_out.act(f"Tax year {yr} uses the {res.get('vintage')} "
                           f"rate tables", "tjs estimate --details"))
        # Carryovers read from a lock taken before its year ended are
        # provisional: one line, the note behind --details (issue #55).
        _pl = (res.get("carry_sources") or {}).get("partial_lock")
        if _pl:
            print(_out.act(f"Carryovers come from the {_pl} lock, taken "
                           f"before {_pl} ended: provisional",
                           "tjs estimate --details"))
        n = len(res.get("notes") or [])
        print()
        print(assumes)
        print(_out.details_hint("tjs estimate --details",
                                "assumptions" + (f", {n} note(s)"
                                                 if n else "")))

    print()
    if r["country"] == "canada":
        print(f"TAX ESTIMATE — canada/{r['province']}, rates vintage "
              f"{RATE_VINTAGE}")
        if not details:
            # The legend, directly above the rows it explains.
            print("ESTIMATE ONLY, not filing numbers: taxable accounts "
                  "only; [ ] says how an amount was built.")
        else:
            print("ESTIMATE ONLY, not filing numbers; taxable accounts "
                  "only.")
            print()
        _ftc_src = str(r.get("ftc_source") or "")
        # The foreign tax counted and, when the T2209 / T2036 limits
        # leave some of it uncredited, what the credits take (backlog
        # TJ-0367).
        _ftc_tax = float(r.get("foreign_tax_creditable",
                               r.get("ftc_assumed")) or 0.0)
        _ftc_cr = float(r.get("ftc_federal", _ftc_tax) or 0.0) + float(
            r.get("ftc_provincial") or 0.0)
        _ftc_part = (f"FTC {money(_ftc_cr)} of {money(_ftc_tax)}"
                     if _ftc_tax - _ftc_cr > 0.005
                     else f"FTC {money(_ftc_tax)}")
        _ftc_split = (f"; credited: federal {money(r['ftc_federal'])} "
                      f"(T2209), {r['province']} "
                      f"{money(r.get('ftc_provincial') or 0.0)} (T2036)"
                      if _ftc_tax - _ftc_cr > 0.005
                      or float(r.get("ftc_provincial") or 0.0) > 0.005
                      else "")
        # Which part of the foreign tax the TAX rows hold and which is
        # the 15% assumption: "from the TAX rows" named an assumed
        # credit actual (backlog TJ-0422).
        _pct15 = _TE.fmt_pct(_TE.CA_FOREIGN_WITHHOLDING)
        _basis = r.get("ftc_basis") or ("tax_rows"
                                        if _ftc_src.startswith("actual")
                                        else "assumed")
        if _basis == "tax_rows_and_assumed":
            _ftc_short = (f"[{_ftc_part}: TAX rows "
                          f"{money(r.get('foreign_tax_from_rows') or 0.0)}"
                          f" + assumed {_pct15} "
                          f"{money(r.get('foreign_tax_by_assumption') or 0.0)}]")
        elif _basis == "tax_rows":
            _ftc_short = f"[{_ftc_part}, from the TAX rows]"
        else:
            _ftc_short = (f"[{_ftc_part}, assumed {_pct15}"
                          + ("; none on spin-off shares"
                             if float(r.get("foreign_div_noncash") or 0.0)
                             > 0.005 else "") + "]")
        # The eligible dividends taxed: compensation paid on a short
        # above the dividends received is not negative income (backlog
        # TJ-0727).
        _elig = float(r.get("eligible_dividends", est["div_ca"]))
        _elig_x = float(r.get("eligible_compensation_excess") or 0.0)
        _elig_floor = (f"; net {money(-_elig_x)}: compensation paid "
                       f"above the dividends is not deducted"
                       if _elig_x > 0.005 else "")
        rows = [
            ("Other income", other_income, ""),
            ("Capital gains (taxable)", r["taxable_gain"],
             f"[{money(est['realized'])} realized"
             + (f" + {money(r['capital_gains_dividends'])} box 18"
                if r.get("capital_gains_dividends") else "")
             + f" - {money(r['losses_applied'])} other losses, "
               f"x{_TE.fmt_pct(_TE.CA_INCLUSION)}]"),
        ] + ([("Capital-gains dividends", r["capital_gains_dividends"],
               "[T5 box 18, line 17400: in the gains above, not "
               "grossed up]", "[T5 box 18: in the gains above]")]
             if r.get("capital_gains_dividends") else []) + [
            ("Eligible dividends (grossed)", r["grossed_eligible"],
             f"[{money(_elig)} x{_TE.CA_ELIGIBLE_GROSSUP:g}, "
             f"Canadian issuers, "
             f"trust distributions included{_elig_floor}]",
             f"[{money(_elig)} x{_TE.CA_ELIGIBLE_GROSSUP:g}"
             f"{_elig_floor}]"),
            ("Foreign dividends", est["div_foreign"],
             f"[{_ftc_part} — "
             f"{r.get('ftc_source') or 'assumed ' + _pct15}"
             f"{_ftc_split}]",
             _ftc_short),
            ("Payments in lieu", est["pil"], ""),
        ] + ([("Crypto staking (ordinary)", r["staking"],
               "[no withholding, no FTC]")]
             if r.get("staking") else []) \
          + ([("Deductions", -r["deductions"],
               "[lines 20700-23500, e.g. RRSP 20800; in full under AMT]",
               "[lines 20700-23500]")]
             if r.get("deductions") else []) \
          + ([("Carrying charges", -r["carrying_charges"],
               f"[line 22100; "
               f"{_TE.fmt_pct(_TE.CA_AMT_CARRYING_CHARGE_ALLOWANCE)} under "
               f"AMT]")]
             if r.get("carrying_charges") else [])
        for label, amt, note, *short in rows:
            _est_row(label, amt, note, *short)
        print()
        _est_row("Tax with investments", r['tax_with']['total'],
                 f"federal {money(r['tax_with']['federal'])} + "
                 f"{r['province']} {money(r['tax_with']['provincial'])}")
        _est_row("Tax on other income alone", r['tax_base']['total'], "")
        print(f"  => ESTIMATED TAX ON INVESTMENT INCOME: "
              f"{money(r['estimated_tax'])} {base_cur}"
              + (f"  ({r['avg_rate_pct']:.1f}% of "
                 f"{money(r['investment_income'])})"
                 if r["avg_rate_pct"] is not None else ""))
        if r["estimated_tax"] < -0.005 and not details:
            print("  (negative: a saving — the dividend tax credit "
                  "exceeds the tax on the grossed-up dividends)")
        elif r["estimated_tax"] < -0.005:
            # Signed (R1-47): eligible dividends at a low bracket earn
            # more credit than the tax on their grossed-up amount.
            print(_wrap_note(
                f"Negative = a saving: the investment income lowers the "
                f"tax on the other income by "
                f"{money(-r['estimated_tax'])} (the dividend tax credit "
                f"exceeds the tax on the grossed-up dividends)."))
        # The part of the year's loss [carryover] claimed carries back
        # (T1A) does not carry forward: close-year's lock and
        # `tjs carryover` take it out (backlog TJ-0084).
        _back = _losses_carried_back(root, cfg, year, r["losses_unused"])
        if _back > 0.005:
            print(f"  Unused capital losses:{_g}"
                  f"{money(r['losses_unused'] - _back)}{_g}(carry "
                  f"forward; {money(_back)} carried back: [carryover] "
                  f"claimed, T1A)")
        elif r["losses_unused"]:
            print(f"  Unused capital losses:{_g}{money(r['losses_unused'])}"
                  f"{_g}(carry forward)")
        _ls = (r.get("carry_sources") or {}).get("other_losses")
        if _ls and other_losses:
            print(f"  Net capital losses carried in:{_g}"
                  f"{money(other_losses)} — from {_ls}")
        elif not _ls and year:
            # No lock before the year carried one and none was entered:
            # the 0 is the default, said, and where the books' figure
            # is — as the US estimate says it (backlog TJ-0612).
            print(f"  Net capital losses carried in:{_g}{money(0.0)} — no "
                  f"close-year lock before {year} and none entered: see "
                  f"`tjs carryover`")
        amt = r.get("amt")
        if amt:
            print()
            print(f"{_h}AMT CHECK — post-2024 minimum tax "
                  f"({amt['rate'] * 100:.1f}% over "
                  f"{money(amt['exemption'])} exemption)")
            print(f"  {'Adjusted taxable income':<30}"
                  f"{money(amt['adjusted_income']):>14}")
            print(f"  {'Federal minimum tax':<30}"
                  f"{money(amt['minimum_fed']):>14}")
            print(f"  {'Federal regular tax':<30}"
                  f"{money(amt['regular_fed']):>14}")
            # The top-up the other income owes on its own is not the
            # investment income's (backlog TJ-0489): it comes off.
            _base_top = float(amt.get("base_topup") or 0.0)
            if amt["binding"]:
                print(f"  {'=> AMT TOP-UP':<30}"
                      f"{money(amt['topup']):>14}")
                # One row each: "federal / ON" as one figure overran
                # the amount column.
                print(f"  {'   federal':<30}"
                      f"{money(amt['excess_fed']):>14}")
                print(f"  {'   ' + str(r['province']):<30}"
                      f"{money(amt['provincial_amt']):>14}")
                # The provincial foreign tax credit of a minimum-tax
                # year (form T2036) less the regular one: part of the
                # top-up (backlog TJ-0591).
                _pfc = float(amt.get("provincial_ftc_change") or 0.0)
                if abs(_pfc) > 0.005:
                    print(f"  {'   ' + str(r['province']) + ' FTC (T2036)':<30}"
                          f"{money(_pfc):>14}  [credit "
                          f"{money(amt.get('provincial_ftc_min_tax', 0.0))}"
                          f" with AMT, "
                          f"{money(amt.get('provincial_ftc_regular', 0.0))}"
                          f" without]")
            else:
                print(f"  {'=> does not bind':<30}"
                      f"{money(amt['headroom']):>14}  [headroom]")
            if _base_top > 0.005:
                print(f"  {'Top-up on other income alone':<30}"
                      f"{money(-_base_top):>14}  [owed without the "
                      f"investments]")
            if amt["binding"] or _base_top > 0.005:
                # Named as the headline above and `amt` name it: the
                # investment income's tax, not the total tax (backlog
                # TJ-0436: "TOTAL WITH AMT" under the regular tax read
                # as the return's total).
                print(f"  => ESTIMATED TAX ON INVESTMENT INCOME WITH AMT: "
                      f"{money(r['estimated_tax'] + amt.get('topup_attributed', amt['topup']))} "
                      f"{base_cur}")
            if amt["binding"]:
                if details:
                    print(_wrap_note(
                        f"AMT binds because capital gains enter at 100% "
                        f"(vs {_TE.fmt_pct(_TE.CA_INCLUSION)}) and the "
                        f"dividend tax credit is denied. "
                        # The carryover is s.120.2(3)'s additional tax,
                        # not always the excess (backlog TJ-0626).
                        f"The carryover it creates "
                        f"({money(amt['carryforward'])}: the additional "
                        f"tax of s.120.2(3), T691 Part 7 line 14) "
                        f"is creditable against REGULAR tax for 7 years, "
                        f"but recovery needs a future year where regular "
                        f"tax exceeds the minimum — gains-heavy, "
                        f"salary-light years keep hitting AMT instead."))
            else:
                if details:
                    print(_wrap_note(
                        f"AMT recomputes with capital gains at 100% (vs "
                        f"{_TE.fmt_pct(_TE.CA_INCLUSION)}) and the dividend "
                        f"tax credit denied; on "
                        "these numbers regular tax still exceeds the "
                        "minimum, so no top-up is owed."))
            _cy = amt.get("carryover") or {}
            if _cy.get("entered") or _cy.get("created", 0.0) > 0.005:
                print(f"{_h}MINIMUM TAX CARRYOVER (s.120.2; line 40427)"
                      + (f" — from {_cy['source']}"
                         if _cy.get("source") else ""))
                if _cy.get("entered"):
                    print(f"  {'Available from prior years':<30}"
                          f"{money(_cy.get('available', 0.0)):>14}")
                    # The provincial share apart from the surtax it
                    # saves (backlog TJ-0016).
                    _sur = float(_cy.get("recovered_provincial_surtax")
                                 or 0.0)
                    _share = _cy.get("recovered_provincial_credit",
                                     _cy.get("recovered_provincial", 0.0))
                    # The nominal line 40427 credit, less the foreign tax
                    # credit the lower tax limits (backlog TJ-0653).
                    _red = float(_cy.get("recovered_credits_reduced")
                                 or 0.0)
                    print(f"  {'Recovered this year':<30}"
                          f"{money(_cy.get('recovered', 0.0)):>14}"
                          f"  [federal "
                          f"{money(_cy.get('recovered_federal', 0.0))}"
                          f" + {r['province']} {money(_share)}"
                          + (f" + {r['province']} surtax {money(_sur)}"
                             if abs(_sur) > 0.005 else "")
                          + (f" - foreign tax credit it limits "
                             f"{money(_red)}" if abs(_red) > 0.005
                             else "") + "]")
                    if details and abs(_cy.get("attributed", 0.0)
                                       - _cy.get("recovered", 0.0)) > 0.005:
                        print(_wrap_note(
                            f"The other income alone would recover "
                            f"{money(_cy.get('base_recovered', 0.0))}, so "
                            f"the investment income changes this year's "
                            f"recovery by "
                            f"{money(_cy.get('attributed', 0.0))} — the "
                            f"part counted in the figure below (what is "
                            f"not recovered stays carried forward)."))
                    if abs(_cy.get("attributed", 0.0)) > 0.005:
                        print(f"  => ESTIMATED TAX ON INVESTMENT INCOME "
                              f"WITH AMT AND CARRYOVER: "
                              f"{money(r['estimated_tax_with_amt'])} "
                              f"{base_cur}")
                print(f"  {'Carried forward':<30}"
                      f"{money(_cy.get('closing', 0.0)):>14}  "
                      f"[`tjs amt` for the detail]")
        if verbose:
            from taxjson.lib.tax_estimate import (CA_FED_BPA,
                                                  CA_FED_BRACKETS,
                                                  CA_PROVINCES)
            tw, tb = r["trace_with"], r["trace_base"]
            provt = CA_PROVINCES[r["province"]]
            print(f"\n  CALCULATION TRACE — BASE (other income only) "
                  f"vs WITH investments")
            print(_out.fill(
                  f"Taxable income: BASE {money(tb['ti'])} | WITH "
                  f"{money(tw['ti'])} = "
                  f"{money(other_income + est['pil'] + r.get('staking', 0.0) - r.get('deductions', 0.0) - r.get('carrying_charges', 0.0))}"
                  f" ordinary (after deductions) + {money(r['taxable_gain'])} taxable gains"
                  f" + {money(r['grossed_eligible'])} grossed dividends"
                  f" + {money(est['div_foreign'])} foreign",
                  None, "  ", "    "))
            print(f"  {'FEDERAL':<36}{'BASE':>14}{'WITH':>14}")
            _print_trace_table(
                _trace_bracket_rows(CA_FED_BRACKETS, tb["ti"], tw["ti"]),
                money)
            _print_trace_table([
                (f"BPA credit ({CA_FED_BPA:,.0f} max @ "
                 f"{CA_FED_BRACKETS[0][1] * 100:g}%)",
                 -tb["fed_bpa"], -tw["fed_bpa"]),
                (f"DTC {_TE.fmt_pct(_TE.CA_FED_DTC_ELIGIBLE)} x "
                 f"{money(r['grossed_eligible'])}",
                 -tb["fed_dtc"], -tw["fed_dtc"]),
                # The credit's source, as the summary line says: the
                # actual TAX rows capped at 15%, or the 15% assumption
                # (a fixed "15% x" label contradicted it, R1-224).
                # The federal credit stops at the T2209 limit
                # (backlog TJ-0367): the row says so, with the tax.
                (f"FTC T2209 limit, tax {money(tw['foreign_tax'])}"
                 if tw.get("foreign_tax", tw["fed_ftc"])
                 - tw["fed_ftc"] > 0.005
                 # Rows and the assumption both: the row says so
                 # (backlog TJ-0422); the assumption alone is on the
                 # dividends less a spin-off's deemed one.
                 else (f"FTC TAX rows, max {_pct15} x "
                       + money(est['div_foreign'])
                       if _basis == "tax_rows"
                       else f"FTC rows+assumed, max {_pct15} x "
                       + money(est['div_foreign'])
                       if _basis == "tax_rows_and_assumed"
                       else f"FTC {_pct15} x "
                       + money(est['div_foreign']
                               - float(r.get("foreign_div_noncash")
                                       or 0.0))),
                 -tb["fed_ftc"], -tw["fed_ftc"]),
                ("= FEDERAL", r["tax_base"]["federal"],
                 r["tax_with"]["federal"]),
            ], money)
            print(f"  {r['province']}")
            _print_trace_table(
                _trace_bracket_rows(provt["brackets"], tb["ti"],
                                    tw["ti"]), money)
            _print_trace_table(
                [(f"BPA credit ({provt['bpa']:,.0f} @ "
                  f"{provt['brackets'][0][1] * 100:.2f}%)",
                  -tb["prov_bpa"], -tw["prov_bpa"]),
                 ("= basic tax", tb["prov_basic"], tw["prov_basic"])]
                + [(f"surtax {rate * 100:.0f}% of basic over {thr:,.0f}",
                    ab, aw)
                   for (thr, rate, ab), (_t2, _r2, aw)
                   in zip(tb["surtax_parts"], tw["surtax_parts"])]
                + [(f"DTC {provt['dtc_eligible'] * 100:.2f}% x "
                    f"{money(r['grossed_eligible'])}",
                    -tb["prov_dtc"], -tw["prov_dtc"])]
                + ([("FTC not used federally (T2036)",
                     -tb.get("prov_ftc", 0.0), -tw.get("prov_ftc", 0.0))]
                   if tw.get("prov_ftc", 0.0) > 0.005 else [])
                + ([("Ontario Health Premium", tb["prov_ohp"],
                     tw["prov_ohp"])] if provt.get("health_premium")
                   else [])
                + [(f"= {r['province']}", r["tax_base"]["provincial"],
                    r["tax_with"]["provincial"])], money)
            _print_trace_table(
                [("TOTAL", r["tax_base"]["total"],
                  r["tax_with"]["total"])], money)
            print(f"    => WITH - BASE = {money(r['estimated_tax'])} "
                  f"estimated tax on investment income"
                  + (" (negative: a saving)"
                     if r["estimated_tax"] < -0.005 else ""))
        if root is not None:
            _icfg = _instalment_config(root, year)
            _idoc = _instalments_doc(root, r, year, _icfg)
            if _idoc and _idoc["required_at_all"]:
                print()
                print(f"{_h}INSTALMENTS — {_idoc['basis'].replace('_', '-')} "
                      f"option (Mar/Jun/Sep/Dec 15)")
                print(f"  {'Required this year':<30}"
                      f"{money(_idoc['required_total']):>14}")
                print(f"  {'Paid to date':<30}"
                      f"{money(_idoc['paid_total']):>14}")
                print(f"  {'Net instalment interest':<30}"
                      f"{money(_idoc['net_interest']):>14}"
                      + (f"  [+ penalty "
                         f"{money(_idoc['penalty'])}]"
                         if _idoc["penalty"] > 0.005 else ""))
                if _idoc["remaining_dates"]:
                    print(f"  {'=> next due ' + _idoc['remaining_dates'][0]:<30}"
                          f"{money(_idoc['per_remaining_date'] or 0.0):>14}"
                          f"  [tjs instalments]")
                else:
                    from taxjson.bin.taxjson_instalments import \
                        balance_due_label
                    # The instalments still behind, not the balance
                    # owed at filing: the year's tax less what was paid
                    # is more than this (backlog TJ-0146).
                    print(f"  {'=> instalments behind':<30}"
                          f"{money(_idoc['shortfall']):>14}"
                          f"  [due with the balance "
                          f"{balance_due_label()}; tjs instalments]")
        if details:
            print()
            _est_notes("  ")
            _assumes(r["assumptions"])
        else:
            # The trust gross-up is stated on the default view too
            # (owner decision A2-0828, CA-EST-TRUST).
            _est_tail(r, year, "Assumes Canadian dividends (trusts' too) "
                      "eligible; no interest, FX on cash or slip gains")
    else:
        st_in, lt_in = r["st_input"], r["lt_input"]
        print(f"TAX ESTIMATE — usa (single, standard deduction), rates "
              f"vintage {RATE_VINTAGE}")
        if not details:
            print("ESTIMATE ONLY, not filing numbers: taxable accounts "
                  "only; [ ] says how an amount was built.")
        else:
            print("ESTIMATE ONLY, not filing numbers; taxable accounts "
                  "only.")
            print()
        rows = [
            ("Other income", other_income, ""),
            ("Short-term gains (net)", r["st_net"],
             f"[{money(st_in)} before carryovers; short-term "
             f"carryover {money(r.get('carryover_short_term', 0.0))}]",
             f"[{money(st_in)} less carryover "
             f"{money(r.get('carryover_short_term', 0.0))}]"),
            ("Long-term gains (net)", r["lt_net"],
             f"[{money(lt_in)} before carryovers; long-term "
             f"carryover {money(r.get('carryover_long_term', 0.0))}]",
             f"[{money(lt_in)} less carryover "
             f"{money(r.get('carryover_long_term', 0.0))}]"),
            ("Qualified dividends",
             est["div_ca"] + est["div_foreign"], ""),
            ("Payments in lieu", est["pil"], "[ordinary]"),
        ] + ([("Crypto staking", est["staking"], "[ordinary]")]
             if est.get("staking") else [])
        for label, amt, note, *short in rows:
            _est_row(label, amt, note, *short)
        print()
        print(f"  Tax with investments:{_g}{money(r['tax_with']['total'])}"
              f" + NIIT {money(r['niit'])}")
        print(f"  Tax on other income alone:{_g}"
              f"{money(r['tax_base']['total'])}")
        print(f"  => ESTIMATED TAX ON INVESTMENT INCOME: "
              f"{money(r['estimated_tax'])} {base_cur}"
              + (f"  ({r['avg_rate_pct']:.1f}% of "
                 f"{money(r['investment_income'])})"
                 if r["avg_rate_pct"] is not None else ""))
        if r["ordinary_offset"]:
            print(f"  Ordinary income offset by losses:{_g}"
                  f"{money(r['ordinary_offset'])}{_g}(max "
                  f"{_TE.US_ORDINARY_LOSS_CAP:,.0f})")
        if r["losses_unused"]:
            print(f"  Unused capital losses:{_g}{money(r['losses_unused'])}"
                  f"{_g}(carry forward"
                  + (f"; {money(r['offset_used_for_carryover'])} deducted: "
                     f"[carryover] claimed {year}"
                     if r.get("offset_used_from") == "claimed" else "")
                  + ")")
        _ls = (r.get("carry_sources") or {}).get("other_losses")
        if _ls and (other_losses or lt_losses):
            print(f"  Capital loss carryovers in:{_g}short-term "
                  f"{money(other_losses)}, long-term {money(lt_losses)}"
                  f" — from {_ls}")
        elif not _ls and year:
            # No lock before the year carried one and none was entered:
            # the 0 is the default, said, and where the books' figure is
            # (backlog TJ-0470).
            print(f"  Capital loss carryovers in:{_g}{money(0.0)} — no "
                  f"close-year lock before {year} and none entered: "
                  f"see `tjs carryover`")
        if verbose:
            from taxjson.lib.tax_estimate import (US_NIIT_MAGI_THRESHOLD,
                                                  US_ORD_BRACKETS,
                                                  US_STD_DEDUCTION,
                                                  stacked_slices)
            tw, tb = r["trace_with"], r["trace_base"]
            print(f"\n  CALCULATION TRACE — BASE (other income only) "
                  f"vs WITH investments")
            print(f"  Ordinary taxable: BASE {money(tb['ord_taxable'])} "
                  f"({money(other_income)} - "
                  f"{money(US_STD_DEDUCTION)} std deduction) | WITH "
                  f"{money(tw['ord_taxable'])}")
            print(f"  {'ORDINARY':<36}{'BASE':>14}{'WITH':>14}")
            _print_trace_table(
                _trace_bracket_rows(US_ORD_BRACKETS, tb["ord_taxable"],
                                    tw["ord_taxable"]), money)
            _print_trace_table(
                [("= ORDINARY", r["tax_base"]["ordinary"],
                  r["tax_with"]["ordinary"])], money)
            print(f"  PREFERENTIAL — {money(tw['pref_taxable'])} "
                  f"(LT + qualified) STACKED from "
                  f"{money(tw['ord_taxable'])}:")
            from taxjson.lib.tax_estimate import US_LTCG_BRACKETS
            for lo, hi, rate, tax in stacked_slices(
                    tw["ord_taxable"], tw["pref_taxable"],
                    US_LTCG_BRACKETS):
                hi_s = ("inf" if hi == float("inf") else f"{hi:,.0f}")
                print(f"    {f'{lo:,.0f}-{hi_s} @ {rate * 100:.0f}%':<34}"
                      f"{'':>14}{money(tax):>14}")
            if tw.get("ceiling"):
                # The worksheet's last lines (backlog TJ-0509): all of
                # the taxable income at the ordinary rates is less.
                print(_out.fill(
                      f"Ceiling (Pub 505 Worksheet 2-7 lines 39-40): "
                      f"{money(tw['ord_taxable'] + tw['pref_taxable'])} "
                      f"all at the ordinary rates is "
                      f"{money(tw['all_ordinary'])}, less than "
                      f"{money(r['tax_with']['ordinary'])} + "
                      f"{money(tw['pref_stacked'])} stacked: the tax is "
                      f"the ceiling", None, "  ", "    "))
                _print_trace_table(
                    [("= PREFERENTIAL", r["tax_base"]["preferential"],
                      r["tax_with"]["preferential"])], money)
            _niit = _TE.fmt_pct(_TE.US_NIIT_RATE)
            print(_out.fill(
                  f"NIIT: {_niit} x min(investment income, MAGI "
                  f"{money(r['magi'])} - "
                  f"{money(US_NIIT_MAGI_THRESHOLD)}) = "
                  f"{_niit} x {money(r['niit_base'])} = {money(r['niit'])}",
                  None, "  ", "    "))
            _print_trace_table(
                [("TOTAL (before NIIT)", r["tax_base"]["total"],
                  r["tax_with"]["total"])], money)
            print(f"    => WITH - BASE + NIIT = "
                  f"{money(r['estimated_tax'])} estimated tax on "
                  f"investment income")
        if not details:
            _est_tail(r, year, "Assumes single filer, standard deduction, "
                      "qualified dividends; no state tax, no §988 FX")
            return
        print()
        _est_notes("  ")
        _assumes("Assumes: single filer, standard deduction, all "
                 "dividends QUALIFIED, no foreign tax credit, no state "
                 "tax; §1256 contracts (futures, index options) split "
                 "60/40 long-/short-term (Form 6781), with no year-end "
                 "marking or loss carryback; interest income and the "
                 "§988 result on foreign currency (`tjs fx-cash`) "
                 "not included.")


def _sanity_items_from_config(accounts_cfg: Dict[str, Any],
                              root: Path, year: Optional[int] = None,
                              kinds: Optional[Dict[str, List[str]]] = None
                              ) -> Tuple[List[Tuple[List[str], List[str]]],
                                         List[str]]:
    """Paired `tjs sanity` items from each account's
    `holdings = [...]` (paths; `~` expanded, relative to the project),
    and for the other accounts the snapshots of the year's holdings/
    folder (lib/holdings_dir: by broker account id or file name).
    Accounts that list a common file — one broker export covering
    several taxjson accounts — merge into one `a+b=file` group, since
    a file may sit in only one group. An account whose file is missing
    is left out with a note rather than compared against a partial
    set. Returns (items, notes). `kinds`, when given, is filled with
    which notes are which: "accounts" — the accounts whose `holdings`
    setting was not checked; "info" — the notes that leave nothing
    unchecked (a holdings/ snapshot of an account whose own setting
    names its files; backlog TJ-0020), also in notes; "snapshots" — the
    holdings/ snapshots no account (or two) claims (TJ-0256); "unread" —
    what holdings/ holds that is not read, a file that is no positions
    file or a sub-folder (TJ-0424)."""
    notes: List[str] = []
    _unchecked: List[str] = []
    files_of: Dict[str, List[str]] = {}
    for name, acfg in (accounts_cfg or {}).items():
        raw = (acfg or {}).get("holdings")
        if not raw:
            continue
        if isinstance(raw, str):
            raw = [raw]
        if not isinstance(raw, (list, tuple)):
            notes.append(f"account {name}: `holdings` must be a path "
                         f"or a list of paths — not checked")
            _unchecked.append(name)
            continue
        paths: List[str] = []
        missing: List[str] = []
        for p in raw:
            pp = Path(str(p)).expanduser()
            if not pp.is_absolute():
                pp = root / pp
            (paths if pp.is_file() else missing).append(str(pp))
        if missing:
            # Masked like the file listing: holdings files are often
            # named after the broker account (S044-03).
            notes.append(f"account {name}: holdings file(s) missing — "
                         f"not checked: "
                         f"{', '.join(_mask_ids_in_path(Path(m).name) for m in missing)}")
            _unchecked.append(name)
            continue
        if paths:
            files_of[name] = paths
    from taxjson.lib import holdings_dir as _HD
    _hfolder, _hnote = _HD.folder_for(root, year)
    if _hnote:
        notes.append(_hnote)
    _info: List[str] = []
    _hnotes: List[str] = []
    if _hfolder is not None:
        _found, _hnotes = _HD.discover(_hfolder, accounts_cfg, root,
                                       info=_info)
        notes += _hnotes + _info
        for name, paths in _found.items():
            files_of.setdefault(name, []).extend(paths)
    # A file in holdings/ that is not read is named, never skipped with
    # "no holdings file" said beside it (backlog TJ-0424).
    _unread = _HD.unread_notes(_PL.holdings_folder(root), accounts_cfg,
                               root)
    notes += _unread
    # Union-find over accounts that share a file.
    parent = {n: n for n in files_of}

    def _find(n: str) -> str:
        while parent[n] != n:
            parent[n] = parent[parent[n]]
            n = parent[n]
        return n

    owner: Dict[str, str] = {}
    for n, paths in files_of.items():
        for p in paths:
            if p in owner:
                parent[_find(n)] = _find(owner[p])
            else:
                owner[p] = n
    groups: Dict[str, Tuple[List[str], List[str]]] = {}
    for n in files_of:
        accts, files = groups.setdefault(_find(n), ([], []))
        accts.append(n)
        for p in files_of[n]:
            if p not in files:
                files.append(p)
    # Structured (accounts, files) groups — never re-joined into the
    # `a+b=f1+f2` argument syntax, so a `+` or `=` inside a path is safe.
    items = sorted(((sorted(a), list(f)) for a, f in groups.values()),
                   key=lambda g: g[0])
    if kinds is not None:
        kinds["accounts"] = _unchecked
        kinds["info"] = _info
        kinds["snapshots"] = list(_hnotes)
        kinds["unread"] = list(_unread)
    return items, notes


def cmd_shares(args: argparse.Namespace) -> None:
    """`tjs shares [--options] [--taxable|--sheltered] [--json]`: the
    COMBINED quantity held of each symbol across all accounts — the
    canonical inventory (post ticker.map, base-currency, wash-adjusted
    where built), summed per symbol with a per-account breakdown. Shorts
    net against longs (the breakdown shows them). Option contracts are
    left out unless --options; positions netting to zero are dropped."""
    from taxjson.lib.core import is_option_symbol
    from taxjson.lib.report_model import (fmt_qty as qfmt,
                                          gains_basis_label,
                                          resolve_gains_files)
    from taxjson.lib.ticker_map import is_future_ticker
    root = Path(args.dir).resolve()
    cache = root / "work"
    files = resolve_gains_files(cache)
    if not files:
        _die_input("no gains files in work/ — run `tjs run` first")
    _warn_accounts_without_books(root, files, "shares", "gains file")
    basis = gains_basis_label(files)
    want = None
    if getattr(args, "taxable", False) or getattr(args, "sheltered", False):
        want = "taxable" if args.taxable else "sheltered"
        if not _PL.has_config(root):
            _die("--taxable/--sheltered need taxjson.toml (account "
                 "types).")
        types = {n: (a.get("type", "sheltered") if isinstance(a, dict)
                     else "sheltered")
                 for n, a in (load_config(root).get("accounts") or {}).items()}
        files = {n: f for n, f in files.items() if types.get(n) == want}
        if not files:
            _die(f"no {want} account with books in work/",
                 "Accounts and their types come from taxjson.toml; run "
                 "`tjs run` first.")
    by_sym: Dict[str, Dict[str, Any]] = {}
    year = None
    for acct, f in files.items():
        data = _load_json_or_die(f)
        year = year or (data.get("summary") or {}).get("year")
        for h in (data.get("inventory") or []):
            sym = str(h.get("symbol") or "")
            qty = float(h.get("qty", 0) or 0)
            if not sym or abs(qty) < 1e-12:
                continue
            if not getattr(args, "options", False) and is_option_symbol(sym):
                continue
            if is_future_ticker(sym) and not is_option_symbol(sym):
                # A futures contract is not a share: it was listed as
                # "1 share" with its notional as book cost (S044-04).
                # (Futures options follow --options.)
                continue
            e = by_sym.setdefault(sym, {"qty": 0.0, "cost": 0.0,
                                        "accounts": {},
                                        "unknown_cost": False})
            e["qty"] += qty
            e["cost"] += float(h.get("total_cost", 0) or 0)
            e["accounts"][acct] = e["accounts"].get(acct, 0.0) + qty
            # Units held before the data (an opening cost=unknown): the
            # cost is the known part only (backlog TJ-0774).
            e["unknown_cost"] = e["unknown_cost"] or bool(
                h.get("unknown_cost"))
    rows = [(sym, e) for sym, e in by_sym.items()
            if abs(e["qty"]) > 1e-9]
    if getattr(args, "sort", "symbol") == "qty":
        rows.sort(key=lambda r: (-abs(r[1]["qty"]), r[0]))
    else:
        rows.sort(key=lambda r: r[0])
    base = _base_currency(root)
    # The inventory is END OF DATA, not the tax year's Dec 31: the
    # header said "tax year 2025" over 2026 positions (S044-05, the
    # sibling of list's R1-282).
    horizon = _books_horizon(cache, list(files))
    if getattr(args, "json", False):
        _json_out({"basis": basis, "year": year, "as_of": horizon,
                   "currency": base,
                   "scope": want or "all",
                   "options_included": bool(getattr(args, "options",
                                                    False)),
                   "rows": [{"symbol": sym, "qty": round(e["qty"], 8),
                             "cost": round(e["cost"], 2),
                             "unknown_cost": e["unknown_cost"],
                             "accounts": {a: round(q, 8) for a, q in
                                          sorted(e["accounts"].items())}}
                            for sym, e in rows]})
        return
    from taxjson.lib.out import Doc
    scope = f" ({want} accounts)" if want else ""
    doc = Doc(f"SHARES HELD — combined across{scope} "
              f"{', '.join(sorted(files))}")
    doc.para("As of the books' latest data"
             + (f" ({horizon})" if horizon else "")
             + f", basis: {basis}, after ticker.map; no futures"
             + ("" if getattr(args, "options", False)
                else ", no option contracts")
             + f". COST = combined book cost in {base}.")
    if not rows:
        doc.para("No open positions.")
        doc.print()
        return
    # The per-account breakdown is one cell (it has spaces inside it).
    body = [[sym, qfmt(e["qty"]),
             fmt_money(e["cost"]) + ("+?" if e["unknown_cost"] else ""),
             ", ".join(f"{a} {qfmt(q)}"
                       for a, q in sorted(e["accounts"].items())
                       if abs(q) > 1e-12)]
            for sym, e in rows]
    doc.table(["SYMBOL", "SHARES", "COST", "ACCOUNTS"], body,
              aligns=["<", ">", ">", "<"])
    doc.blank().para(f"{len(rows)} symbol(s).")
    n_unk = sum(1 for _s, e in rows if e["unknown_cost"])
    if n_unk:
        from taxjson.lib.out import act as _act
        doc.item(_act(f"{n_unk} symbol(s) hold units of unknown cost (an "
                      f"opening cost=unknown): COST +? is the known part "
                      f"only", "tjs find-missing-history")[len(_out_act_prefix()):],
                 bullet=_out_act_prefix())
    doc.print()


def cmd_channels(args: argparse.Namespace) -> None:
    """`tjs channels [all] [--json] [--offline]`: where the release
    channels point (stable / beta in channels.json on main, latest = the
    newest release tag), what this machine's production copy runs, and
    the newest releases (lib/channels). Reads the development checkout
    when there is one, else the production copy's clone; one `git fetch`
    of that clone's own remote, skipped offline."""
    import json
    from taxjson.lib import channels as ch
    try:
        repo, kind = ch.source_checkout()
        st = ch.status(repo, fetch_remote=not args.offline,
                       limit=None if args.scope == "all"
                       else ch.DEFAULT_LIMIT, source_kind=kind)
    except ch.ChannelsError as e:
        _die_input(str(e))
    if args.json:
        print(json.dumps(st, indent=2))
    else:
        print(ch.render(st, _PROG))


def _release_dev_checkout(verb: str) -> Path:
    """The development checkout `promote` / `deploy` act from, or a clear
    refusal: they publish or install releases, which is the maintainer's
    machine's job (anywhere else, re-run the installer)."""
    from taxjson.lib import channels as ch
    try:
        dev = ch.dev_checkout()
    except ch.ChannelsError as e:
        _die_input(str(e))
    if dev is None or not (dev / "scripts" / "promote.sh").is_file():
        _die_input(
            f"`{verb}` is for the machine taxjson is developed on, and no "
            f"development checkout was found (set TAXJSON_DEV_DIR to it, or "
            f"run that checkout's own editable install). To update this "
            f"machine, re-run the installer: bash -c \"$(curl -fsSL "
            f"https://taxjson.com/install.sh)\"; `{_PROG} channels` shows "
            f"where the channels point.")
    return dev


def _run_script(argv: List[str], env: Optional[Dict[str, str]] = None
                ) -> None:
    """Run a release script on this terminal (promote asks before moving
    a channel backwards) and exit with its status."""
    r = subprocess.run(argv, env=env)
    if r.returncode:
        raise SystemExit(r.returncode)


def cmd_promote(args: argparse.Namespace) -> None:
    """`tjs promote [TAG] [stable|beta]`: point a channel at a
    release — scripts/promote.sh in the development checkout: it commits
    channels.json, lands it on main (scripts/land.sh) and pushes a
    fast-lane tag `channels-<UTC time>` on that commit, which asks the
    publisher to copy channels.json to the public repo. No new release
    tag, no rebuild (backlog TJ-0337). Without TAG: the release this
    machine's production copy runs."""
    from taxjson.lib import channels as ch
    dev = _release_dev_checkout("promote")
    tag, channel = args.tag, args.channel
    if tag in ch.CHANNELS and channel is None:
        tag, channel = None, tag            # `promote beta`
    channel = channel or "stable"
    if not tag:
        tag = ch.this_box().get("release")
        if not tag:
            _die_input(f"this machine's production copy "
                       f"({ch.prod_dir()}) is not on a release — say which: "
                       f"{_PROG} promote vX.Y.Z [stable|beta]")
        print(f"promoting what this machine runs: {tag}")
    _run_script(["bash", str(dev / "scripts" / "promote.sh"), tag, channel])


def cmd_deploy(args: argparse.Namespace) -> None:
    """`tjs deploy [TAG]`: put a release on this machine's production
    copy now — the newest tag, or TAG — through the installer's upgrade
    path (the development checkout's install.sh run against the
    production copy), then checks that the copy is at that tag and its
    `tjs --version` agrees (exit 1 when not). The remembered channel is left as it is; the
    installer never moves a channel backwards, so the copy stays on TAG
    until its channel passes it. No fetch flag is passed: the installer
    installs taxjson-fetch unless this machine opted out (remembered in
    ~/.config/taxjson/fetch) or TAXJSON_WITH_FETCH says otherwise."""
    import os
    from taxjson.lib import channels as ch
    dev = _release_dev_checkout("deploy")
    prod = ch.prod_dir()
    if not ch.is_checkout(prod):
        _die_input(f"no production copy at {prod} — install it first with "
                   f"the installer (bash -c \"$(curl -fsSL "
                   f"https://taxjson.com/install.sh)\"), or set "
                   f"TAXJSON_PROD_DIR")
    target = "latest"
    if args.tag:
        target = args.tag if args.tag.startswith("v") else f"v{args.tag}"
        if not ch.TAG_RE.match(target):
            _die_input(f"{args.tag!r} is not a release — give vX.Y.Z "
                       f"(or nothing, for the newest)")
    env = dict(os.environ, TAXJSON_DIR=str(prod),
               TAXJSON_REMEMBER_CHANNEL="0")
    _run_script(["bash", str(dev / "install.sh"), "--channel", target], env)
    # The installer said it worked; check what now runs is the release
    # (a pip install that silently kept an older build, a copy left on
    # another commit) — loudly, exit 1, never a quiet mismatch.
    want, got, problems = ch.check_deployed(prod, target)
    if problems:
        _die(f"deploy: the production copy does not run "
             f"{want or 'a release'}", *problems)
    print(f"deployed {want}: {prod} runs {got}")


def cmd_redact(args: argparse.Namespace) -> None:
    """`tjs redact FILE...`: strip account numbers and identity from
    broker exports (row shapes kept); with no FILE, copy the project's
    inputs/ to inputs_redact/, redacted — see taxjson_redact."""
    from taxjson.bin.taxjson_redact import main as redact_main
    argv: List[str] = [f"--dir={args.dir}"]
    if args.out:
        argv += ["--out", args.out]
    for a in args.also or []:
        argv += ["--also", a]
    if args.no_denylist:
        argv.append("--no-denylist")
    if args.force:
        argv.append("--force")
    if args.check:
        argv.append("--check")
    if _details(args):
        argv.append("--details")
    argv += ["--", *args.files]          # a file named `--check` stays a file
    raise SystemExit(redact_main(argv))


def _locked_grant_since(root: Path, settings: Dict[str, Any]
                        ) -> Optional[Tuple[int, str]]:
    """(since, lock label) from the most recent filed-year lock — the
    project's own or the one [settings] prior_year_record names — that
    records grant timing with an option_grant_since; None otherwise."""
    from taxjson.bin import taxjson_filed as _tfl
    try:
        locks = _tfl.project_locks(root, settings)
    except _tfl.PriorRecordError:
        return None
    for _y, p, _w in sorted(locks, key=lambda t: t[0], reverse=True):
        try:
            # The one lock check (read_lock): a damaged or other-country
            # lock is not the year to copy (backlog TJ-0069).
            ot = _tfl.read_lock(p, settings,
                                prior=_w != "local").get("option_timing")
        except ValueError:              # LockProblem; a bad country
            continue
        if not isinstance(ot, dict) or str(
                ot.get("option_premium_timing") or "").lower() != "grant":
            continue
        try:
            return int(ot.get("option_grant_since")), \
                _tfl.lock_label(root, p)
        except (TypeError, ValueError):
            continue
    return None


def _books_write_options(root: Path, accounts: Dict[str, Any]
                         ) -> Optional[bool]:
    """Whether a taxable equity account's books (work/<acct>_base.json)
    hold a written option (lib/option_boundary.write_lots): True /
    False, or None when no such book can be read."""
    import json as _json
    from taxjson.lib.core import TaxTransaction
    from taxjson.lib.option_boundary import write_lots
    fields = TaxTransaction.__dataclass_fields__
    seen = False
    for name, acfg in sorted((accounts or {}).items()):
        if not isinstance(acfg, dict) or acfg.get("type") != "taxable" \
                or acfg.get("crypto"):
            continue
        try:
            doc = _json.loads((Path(root) / "work" / f"{name}_base.json")
                              .read_text(encoding="utf-8"))
        except (OSError, ValueError, RecursionError):
            continue
        raw = doc.get("transactions") if isinstance(doc, dict) else doc
        txs = []
        for r in raw if isinstance(raw, list) else []:
            if isinstance(r, dict):
                try:
                    txs.append(TaxTransaction(
                        **{k: v for k, v in r.items() if k in fields}))
                except TypeError:
                    continue
        seen = True
        if write_lots(txs):
            return True
    return False if seen else None


def _grant_since_after_year(settings: Dict[str, Any]) -> Optional[str]:
    """One line when a Canadian project's option_grant_timing_since is
    later than its year: its written options are then taxed at the
    close, not when written — usually `year` lowered (filing an earlier
    year) with the key left as an earlier project wrote it."""
    if _country(settings) in ("us", "usa"):
        return None
    since, yr = settings.get("option_grant_timing_since"), \
        settings.get("year")
    if not (isinstance(since, int) and isinstance(yr, int)) \
            or isinstance(since, bool) or isinstance(yr, bool) \
            or since <= yr:
        return None
    if str(settings.get("option_premium_timing", "grant")).strip() \
            .lower() != "grant":
        return None
    return (f"option_grant_timing_since = {since} is after year = {yr}: "
            f"{yr}'s written options are taxed at the close (right only "
            f"if {yr} was filed that way)")


def _grant_since_warning(settings: Dict[str, Any],
                         root: Optional[Path] = None,
                         accounts: Optional[Dict[str, Any]] = None
                         ) -> Optional[str]:
    """The warning for a Canada project on grant timing with no explicit
    `option_grant_timing_since`: the default is the PROJECT year, which
    moves every year — consecutive default projects tax a year-straddling
    premium twice (2026-09 audit: +399 in 2025, +298 in 2026, for a 298
    economic gain). None when the key is set or does not apply — also
    when `accounts` (the [accounts] table) has no non-crypto taxable
    account: a crypto-only project writes no options (one gate for run,
    carryover and option-boundary, A2-1144)."""
    if _country(settings) in (
            "us", "usa"):
        return None
    if accounts is not None and not any(
            isinstance(_c, dict) and _c.get("type") == "taxable"
            and not _c.get("crypto") for _c in accounts.values()):
        return None
    if str(settings.get("option_premium_timing", "grant")).strip().lower() \
            != "grant":
        return None
    if settings.get("option_grant_timing_since") not in (None, ""):
        return None
    if root is not None and accounts is not None \
            and _books_write_options(root, accounts) is not True:
        # No written option in the books, or no taxable equity books at
        # all (the scaffold's empty margin account, skipped: a crypto-
        # only use, backlog TJ-0162): the default (the project year)
        # decides nothing (init leaves the key commented).
        return None
    yr = settings.get("year")
    if not isinstance(yr, int) or isinstance(yr, bool):
        # No year: the missing year is the real error (run and
        # option-boundary say so); never suggest "since = None"
        # (S044-06).
        return None
    # A filed-year lock that records an earlier `since` is the year to
    # copy: "e.g. <project year>" put last year's year-straddling
    # contracts back on close timing and taxed their premium twice
    # (A2-1142).
    locked = _locked_grant_since(root, settings) if root else None
    example = (f"{locked[0]}, the year {locked[1]} records"
               if locked else f"{yr}")
    return (f"[settings] option_grant_timing_since is not set, so grant "
            f"timing (ITA s.49(1)) starts at the project year ({yr}) — a "
            f"default that MOVES when you bump `year`: next year's project "
            f"would put this year's year-straddling written options back "
            f"on close timing and tax their premium a second time. Add "
            f"`option_grant_timing_since = <first year you file under "
            f"grant timing>` (e.g. {example}) to [settings] once and keep "
            f"it unchanged in every later year's project.")


def cmd_tax_logic(args: argparse.Namespace) -> None:
    """`tjs tax-logic`: a short statement of every rule taxjson
    applies for the project's country, with the project's settings
    filled in (lib/tax_logic). Works outside a project too (defaults)."""
    from taxjson.lib.country import CountryError
    from taxjson.lib.tax_logic import render, rule_sections, sections
    root = Path(args.dir).resolve()
    settings = dict((_soft_config(root).get("settings") or {}))
    if args.country:
        country = _normalize_country(args.country)
    elif settings:
        country = _country(settings)
    else:
        _die("no taxjson.toml here to read the country from — pass "
             "--country canada|usa (or -C DIR to a project)")
    try:
        if getattr(args, "json", False):
            _json_out({"country": country, "year": settings.get("year"),
                       "sections": [{"title": t, "rules": r}
                                    for t, r in sections(country, settings)],
                       "rule_ids": [
                           {"title": t, "rules": [
                               {"id": r.id, "text": r.text,
                                "continues": r.cont} for r in rs]}
                           for t, rs in rule_sections(country, settings)]})
            return
        print(render(country, settings, ids=getattr(args, "ids", False)))
    except (CountryError, ValueError) as e:
        # The same resolvers the engine uses refused a setting: the
        # text would otherwise describe a value `run` reads differently
        # (partition SPEC-12).
        _die(str(e))


def cmd_spinoffs(args: argparse.Namespace) -> None:
    """`tjs spinoffs`: every spin-off, its election, the value per
    share used and what was booked (lib/corp_views). Exit 1 when one
    needs attention (zero value, no election, ignored)."""
    from taxjson.lib.corp_views import ViewError, render_spinoffs, spinoffs
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    _require_books(root, args.account)
    try:
        doc = spinoffs(root, cfg, args.account)
    except ViewError as e:
        _die(str(e))
    if getattr(args, "json", False):
        _json_out(doc)
    else:
        for ln in render_spinoffs(doc):
            print(ln)
    if any(s["flags"] and not s["sheltered"] for s in doc["spinoffs"]):
        raise SystemExit(1)


def cmd_splits(args: argparse.Namespace) -> None:
    """`tjs splits`: every split, consolidation and rename in the
    books with holdings before and after, noting a split two sources
    report within a week (one event, applied once) and flagging the same
    ratio again further apart (applied twice), a no-op row and a
    fractional result (lib/corp_views). Exit 1 on a likely double
    application."""
    from taxjson.lib.corp_views import ViewError, render_splits, splits
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    _require_books(root, args.account)
    try:
        items = splits(root, cfg, args.account)
    except ViewError as e:
        _die(str(e))
    if getattr(args, "json", False):
        _json_out({"splits": items})
    else:
        for ln in render_splits(items):
            print(ln)
    if any("TWICE?" in s["flags"] for s in items):
        raise SystemExit(1)


def cmd_journals(args: argparse.Namespace) -> None:
    """`tjs journals`: every broker journal between two listings of
    one security, per account — its date, FROM -> TO, quantity, broker,
    how it was found and its state: joined (the map line that pools the
    two), suggested (the reason, and the `.tt` / ticker.map line that
    settles it) or refused (the reason, and the undo) — read from the
    last run's work/ (lib/journals). `--pending` lists only the pending
    journals (suggested, or refused with no ticker.map line behind it)
    and exits 1 when there is one."""
    from taxjson.lib.journals import JournalsError, render, report
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    want = (args.account or "").strip() or None
    if want and want not in (cfg.get("accounts") or {}):
        _die_input(f"no [accounts.{want}] in taxjson.toml — check the "
                   f"name.")
    try:
        doc = report(root, cfg, want, args.year)
    except JournalsError as e:
        _die(f"{e} — run `tjs run` first",
             "The journals are read from the last run's work/ folder.")
    if args.pending:
        doc = dict(doc, journals=[j for j in doc["journals"]
                                  if j["pending"]])
    if getattr(args, "json", False):
        _json_out(doc)
    else:
        for ln in render(doc, pending=args.pending):
            print(ln)
    if args.pending and doc["pending"]:
        raise SystemExit(1)


def cmd_renames(args: argparse.Namespace) -> None:
    """`tjs renames`: every ticker change in the books as a dated
    event (date, source, position and book cost carried), every trade in
    an old ticker after its rename with the .tt line that resolves it,
    the look-alike renames the exports show (suggested, with the `.tt`
    line `RENAME <date> OLD NEW` that books each) and the undated
    ticker.map renames (lib/renames), and each declared rename that
    books nothing. Exit 1 while a late trade is unresolved; with
    --pending, also while a suggestion is open or a declaration books
    nothing."""
    from taxjson.lib.renames import pending_renames, render, report
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    # No books is no check, as `splits` and `spinoffs` say: it read "no
    # renames, nothing pending" at exit 0 (backlog TJ-0319).
    _require_books(root, args.account)
    if not args.account:
        _warn_accounts_without_books(
            root, [n for n in (cfg.get("accounts") or {})
                   if (root / "work" / f"{n}_base.json").is_file()],
            "renames", "books")
    try:
        doc = report(root, cfg, args.account)
    except ValueError as e:
        _die(str(e))
    pending = getattr(args, "pending", False)
    if getattr(args, "json", False):
        if pending:
            # The events of the unresolved late trades: old symbol, new
            # symbol and date (backlog TJ-0687).
            doc = dict(doc, renames=pending_renames(doc),
                       late=[x for x in doc["late"]
                             if x["resolution"] == "unresolved"],
                       undated=[])
        _json_out(doc)
    else:
        for ln in render(doc, pending=pending):
            print(ln)
    if doc["unresolved"] or (pending and doc["pending"]):
        raise SystemExit(1)


def cmd_ticker_map(args: argparse.Namespace) -> None:
    """`tjs ticker-map --suggest [--write [--all]] [--json]`: every
    ticker.map line the last run suggested (lib/ticker_map_suggest),
    each with its reason; the listing pairs the map does not answer
    (MAP-GAP, "verify": TOBASE if one security, DISTINCT if two); the
    rules no symbol of the books reaches (lib/map_hygiene: "Unused
    rules, delete?", never written). --write appends the chosen lines
    to ticker.map (one by one on a terminal: y/n/q, and for a pair to
    verify t/d/s/q; --all: every evidence line, never a pair to
    verify), a comment line above each, never a line the map already
    answers, through safe_write with a backup of the old file."""
    from taxjson.lib import ticker_map_suggest as TS
    from taxjson.lib.out import Doc
    root = Path(args.dir).resolve()
    if not getattr(args, "suggest", False):
        _die_input("ticker-map: say what to do: --suggest lists the "
                   "ticker.map lines the last run suggested",
                   "`tjs ticker-map --suggest --write` appends them.")
    load_config(root)
    if not (root / "work").is_dir():
        _die("no work/ — run `tjs run` first",
             "The suggestions come from the run's messages.")
    offer, skipped = TS.pending(root)
    # The listing pairs the map does not answer (MAP-GAP): to verify,
    # asked on a terminal, never added by --all.
    verify, gap_unread = TS.verify(root, offer)
    # The rules no symbol of the books reaches (root-aware: an option's
    # underlying and a rename chain keep a rule live): listed to delete
    # by hand, never written (lib/map_hygiene).
    from taxjson.lib import map_hygiene as MH
    unused, unread = MH.unused_rules(root)
    # The user's own ticker.map lines tobase.map states identically
    # (Canada): listed ("delete?"); on a terminal --write asks for each
    # (keep is the default), --all never deletes one.
    tob_covered = _tobase_covered(root)
    interactive = (bool(getattr(args, "write", False)) and not args.all
                   and sys.stdin.isatty())
    as_json = bool(getattr(args, "json", False))
    if args.write and not interactive and not args.all and (offer or verify):
        # Nothing can be asked: a pair to verify is never written without
        # its answer, as an evidence line is never written unchosen
        # (exit 2 before any output, so a script reads no partial JSON).
        _die_input("ticker-map --write: not a terminal, so nothing can be "
                   "asked",
                   ("Add --all to append every suggestion the run's "
                    "evidence names (never a pair to verify), or run it "
                    "in a terminal to choose one by one."
                    if offer else
                    f"{len(verify)} listing pair(s) to verify — one "
                    f"security (TOBASE) or two (DISTINCT) — are asked only "
                    f"on a terminal: run it there, or write the line you "
                    f"choose into ticker.map by hand."))
    # Under --json every plain line goes to stderr: stdout is the JSON.
    out = sys.stderr if as_json else sys.stdout

    def say(text: str) -> None:
        print(text, file=out)

    def ask(prompt: str) -> str:
        if as_json:
            print(prompt, end="", file=sys.stderr, flush=True)
            return input()
        return input(prompt)

    if as_json:
        # `suggestions`: the lines the run's evidence names, safe to
        # append; `verify`: the pairs only you can answer (TOBASE or its
        # `alternative`) — apart, so a script appending every suggestion
        # never writes an unproven TOBASE.
        _json_out({"suggestions": [s.record() for s in offer],
                   "verify": [s.record() for s in verify],
                   "skipped": [dict(s.record(), why=w, by=(
                       "suggestion" if TS.covered_by_suggestion(w)
                       else "ticker.map")) for s, w in skipped],
                   "unused": [u.record() for u in unused],
                   "covered": [{"line": c.rule, "lineno": c.lineno,
                                "tobase": c.where} for c in tob_covered],
                   "unused_unread": list(unread),
                   "map_gap_unread": list(gap_unread)})
        if not args.write:
            return
    elif not args.write or not (offer or (verify and interactive)
                                or (tob_covered and interactive)):
        # Essentials first (docs/output-style.md): the lines; each one's
        # reason, the skipped ones and the advice behind --details.
        _det = _details(args)
        d = Doc(f"TICKER.MAP SUGGESTIONS — {len(offer)} from the last run"
                + (f", {len(verify)} to verify" if verify else ""))
        if offer:
            d.blank()
            if not _det:
                d.line("Lines for ticker.map, from the run's evidence (a "
                       "pair's reason under it; every reason: --details).")
            for s in offer:
                d.line(s.line + (("   (a template: edit, then add it by "
                                  "hand)" if _det else "   (template: edit "
                                  "it, add by hand)") if s.template else
                                 ("   (a .tt line: add it to a .tt file of "
                                  "the account)" if _det else
                                  "   (a .tt line)") if s.tt else ""))
                if _det or s.conditional or s.keyword in ("TOBASE",
                                                          "DISTINCT"):
                    # A pair joins (or parts) two listings' cost: its
                    # evidence stays in the default view.
                    d.para(s.reason, indent="  ")
        if verify:
            d.section(f"To verify: one security or two? ({len(verify)})")
            for s in verify:
                d.line(f"{s.line}   or   {s.alternative}")
                # (the evidence to choose by: kept in the default view)
                d.para(s.reason, indent="  ")
        if gap_unread:
            d.blank()
            d.para(f"The listing-pair check skipped what it could not "
                   f"read: {'; '.join(gap_unread)} — re-run `tjs "
                   f"run`.")
        # A suggestion another one covers is not answered by the map:
        # its own heading.
        covered = [x for x in skipped if TS.covered_by_suggestion(x[1])]
        answered = [x for x in skipped
                    if not TS.covered_by_suggestion(x[1])]
        _skip_lines = []
        for head, items in (("Already answered by ticker.map", answered),
                            ("Covered by another suggestion", covered)):
            if items and _det:
                d.section(f"{head} ({len(items)})")
                for s, why in items:
                    d.item(f"{s.line}: {why}", "  ")
            elif items:
                _skip_lines.append(f"{head} ({len(items)})")
        if _skip_lines:
            d.blank()
            d.line("; ".join(_skip_lines)
                   + " — tjs ticker-map --suggest --details")
        if unused:
            d.section(f"Unused rules, delete? ({len(unused)})")
            for u in unused:
                d.line(u.line)
                if _det:
                    d.para(u.reason, indent="  ")
        if tob_covered:
            d.section(f"Covered by tobase.map (delete?) "
                      f"({len(tob_covered)})")
            for c in tob_covered:
                d.item(f"{c.rule} (ticker.map:{c.lineno}): {c.where} "
                       f"states the same pair", "  ")
            if _det:
                d.para("Keeping them is harmless: your line holds even if "
                       "the interlisted master later retracts the pair. "
                       "`tjs ticker-map --suggest --write` on a "
                       "terminal asks for each (keep is the default).",
                       indent="  ")
        if unread:
            d.blank()
            d.para(MH.first_unread(unread))
        d.blank()
        if not _det:
            from taxjson.lib.out import act as _act
            if args.write and args.all and verify and not offer:
                d.line(_act("Nothing written: --all, never a pair to "
                            "verify; answer each",
                            "tjs ticker-map --suggest --write"))
            elif offer or verify:
                d.line(_act("Add only the lines right for your "
                            "securities, then `tjs run`",
                            "tjs ticker-map --suggest --write"))
            elif unused or tob_covered:
                d.line("Nothing to add; the lines above are harmless "
                       "(why: --details).")
            else:
                d.line("Nothing to add.")
            d.print()
            return
        d.para("Add a line only when it is right for your securities: "
               "`tjs ticker-map --suggest --write` asks for each one "
               "(a pair to verify: TOBASE, DISTINCT or skip; --all adds "
               "only the lines the run's evidence names, never a pair to "
               "verify), then re-run `tjs run`."
               if offer or verify else
               "Nothing to add; an unused rule is harmless — delete it by "
               "hand only if its symbol will not return." if unused else
               "Nothing to add; a line tobase.map covers is harmless."
               if tob_covered else "Nothing to add.")
        d.print()
        return
    chosen = []
    stopped = False
    for s in offer:
        if s.template:
            # A placeholder (<LISTING>, <words ...>) would rename rows to
            # a symbol that is not one: never written.
            say(f"Not added (a template — edit it, then add it by hand): "
                  f"{s.line}")
            continue
        if s.tt:
            # A dated event is a .tt line of an account (lib/dated_events),
            # never a ticker.map line.
            say(f"Not added (a .tt line — add it to a .tt file of the "
                  f"account): {s.line}")
            continue
        if interactive:
            say(s.line)
            for ln in _out_wrap(s.reason, indent="  ", hang="  "):
                say(ln)
            try:
                ans = ask("Add this line? [y/n/q] ").strip().lower()
            except EOFError:
                ans = "q"
            if ans.startswith("q"):
                stopped = True
                break
            if not ans.startswith("y"):
                continue
        chosen.append(s)
    for s in verify:
        if not interactive:
            # --all writes only what the evidence proves: a shared root
            # is a candidate, never proof (MAP-GAP).
            say(f"Not added (to verify — one security or two? `tjs "
                  f"ticker-map --suggest --write` on a terminal asks): "
                  f"{s.line} / {s.alternative}")
            continue
        if stopped:
            break
        say(f"{s.line}   or   {s.alternative}")
        for ln in _out_wrap(s.reason, indent="  ", hang="  "):
            say(ln)
        try:
            ans = ask("One security or two? [t]OBASE / [d]ISTINCT / "
                        "[s]kip / [q]uit ").strip().lower()
        except EOFError:
            ans = "q"
        if ans.startswith("q"):
            break
        # The comment above the line records the answer and what the
        # exports showed (the reason's first clause, without the lines).
        why = s.reason.split(" — ")[0]
        if ans.startswith("t"):
            chosen.append(TS.Suggestion(
                s.line, f"one security (your answer): {why}", s.source))
        elif ans.startswith("d"):
            chosen.append(TS.Suggestion(
                s.alternative, f"two securities (your answer): {why}",
                s.source))
    # The lines tobase.map covers: asked one by one on a terminal (keep
    # is the default); --all and a script never delete one.
    drop: List[int] = []
    if interactive and tob_covered and not stopped:
        say(f"{len(tob_covered)} ticker.map line(s) tobase.map states "
            f"identically (keeping one is harmless: it holds even if the "
            f"master later retracts the pair):")
        for c in tob_covered:
            try:
                ans = ask(f"{c.rule} (ticker.map:{c.lineno}; {c.where}): "
                          f"[k]eep / [d]elete / [q]uit? [k] "
                          ).strip().lower()
            except EOFError:
                ans = "q"
            if ans.startswith("q"):
                break
            if ans.startswith("d"):
                drop.append(c.lineno)
    if not chosen and not drop:
        say("Nothing added to ticker.map.")
        return
    tm = _PL.ticker_map_path(root)
    from taxjson.lib.cli_diag import read_text_utf8
    from taxjson.lib.safe_write import (OutsideLinkError, link_outside,
                                        write_user_file)
    _outside = link_outside(tm, root)
    if _outside is not None:
        _die_input(f"ticker-map --write: ticker.map is a symlink to "
                   f"{_outside}, outside the project — nothing was written",
                   "Add the lines to the file it points at, or replace the "
                   "link with a copy.")
    current = read_text_utf8(tm) if tm.is_file() else ""
    if drop:
        from taxjson.lib.tobase_map import without_lines
        current = without_lines(current, drop)
    text = TS.appended_text(current, chosen) if chosen else current
    # The new map must be one `tjs run` accepts (no contradiction).
    import tempfile as _tf
    with _tf.TemporaryDirectory() as _d:
        _probe = Path(_d) / "ticker.map"
        _probe.write_text(text, encoding="utf-8")
        from taxjson.bin.taxjson_ticker_map import map_file_problems
        _problems = map_file_problems(_probe)
    if _problems:
        _die("ticker-map --write: the lines would make ticker.map "
             "contradict itself — nothing was written",
             *[f"- {p}" for p in _problems])
    try:
        # The user-file guard migrate and format use: a link inside the
        # project stays a link (its target is replaced), the permission
        # bits are kept, the old text is kept as ticker.map.bak[N].
        bak = write_user_file(tm, text, root, suffix=".suggest.part")
    except OutsideLinkError as e:
        _die_input(f"ticker-map --write: {e}")
    except OSError as e:
        # Named from where the command was run, with the fix (backlog
        # TJ-0219).
        from taxjson.lib.cli_diag import cannot_write
        _h, _fix = cannot_write(_config_shown(tm), e, tm)
        _die_input(f"ticker-map --write: {_h}", *([_fix] if _fix else []),
                   "Nothing was written.")
    say((f"Added {len(chosen)} line(s) to ticker.map" if chosen else
         "ticker.map")
        + (f"; deleted {len(drop)} line(s) tobase.map covers" if drop
           else "")
        + (f" (the old file is {bak.name})" if bak else "")
        + ". Run `tjs run` to apply them.")


def _tobase_covered(root: Path) -> List[Any]:
    """The user's ticker.map lines the project's tobase.map states
    identically (lib/tobase_map.covered_lines): Canada only, [] without
    either file or when one cannot be read."""
    from taxjson.lib import tobase_map as TB
    tm = _PL.ticker_map_path(root)
    if not tm.is_file() or TB.project_country(root) != "canada":
        return []
    try:
        from taxjson.lib.cli_diag import read_text_utf8
        return TB.covered_lines(read_text_utf8(tm), TB.read_tobase(root))
    except (OSError, ValueError):
        return []


def _write_dated_events_state(root: Path, cfg: Dict[str, Any], cache: Path,
                              tmap: Any) -> List[Dict[str, Any]]:
    """work/dated_events.state (lib/dated_events): every declared journal
    with its status, and every rename event the books carry (each
    account's base rows) with its source and declarations, plus each
    declaration no account's books carried. Returns the rename records."""
    from taxjson.lib import dated_events as DE
    from taxjson.lib.renames import _book_rows
    decl = _DATED_THIS_RUN.get(cache.resolve())
    if decl is not None and decl.events:
        # Every event, the map's included, merged (resolve_renames).
        declared = list(decl.events)
    else:
        declared = list(getattr(tmap, "dated", ()) or ()) if tmap else []
        declared += list(decl.renames) if decl is not None else []
    try:
        rows = _book_rows(root, cfg)
    except ValueError:
        rows = []
    mapping: Dict[str, str] = {}
    if tmap is not None:
        from taxjson.bin.taxjson_ticker_map import merge_renames
        try:
            mapping = merge_renames(tmap, to_base=True)
        except ValueError:
            mapping = {}
    records = DE.rename_records(rows, declared, mapping)
    doc = DE.state_doc(decl.journals if decl is not None else (), records)
    import json
    text = json.dumps(doc, indent=2, sort_keys=True,
                      ensure_ascii=False) + "\n"
    path = cache / DE.STATE
    if _read_work_stamp(path) != text:
        _write_work_stamp(path, text)
    return records


def _warn_unused_renames(records: List[Dict[str, Any]], *,
                         strict: bool = False) -> None:
    """A declared rename no account's books carry (a typo of the symbol,
    a date after the last OLD row was sold, an account of the other kind):
    one Warning per declaration, naming its line (second pre-release
    review, 11); --strict stops, like the other unresolved rename items
    (third pre-release review, 7)."""
    unused = [r for r in records if r.get("status") == "unused"]
    for r in unused:
        where = ", ".join(r.get("where") or []) or "a declaration"
        _say_once(("rename-unused", where, r["old"], r["new"]), "warning",
                  f"{where}: RENAME {r['date']} {r['old']} {r['new']} books "
                  f"nothing",
                  f"No account's books hold {r['old']} before "
                  f"{r['date']} (in an account of the line's kind: "
                  f"securities or crypto) — check the symbols (a typo?) "
                  f"and the date, or delete the line. `tjs renames` "
                  f"lists it.", prog=_PROG)
    if unused and strict:
        _die(f"--strict: {len(unused)} declared rename(s) book nothing "
             f"— aborting",
             "See the warnings above and `tjs renames --pending`.")


def _check_renamed_late(root: Path, *, strict: bool) -> None:
    """A trade in a renamed ticker after its rename date that no
    declaration resolves (a .tt `RENAME <date> OLD NEW late=...` line, or
    a legacy ticker.map one: lib/renames, A2-0197): ATTENTION, and
    --strict stops."""
    from taxjson.lib.renames import unresolved_late
    try:
        rows = unresolved_late(root, load_config(root))
    except ValueError as e:
        _say("warning", *_split_msg(str(e)), indent="  ")
        return
    seen: Dict[Tuple[str, str], int] = {}
    for x in rows:
        k = (x["symbol"], x["rename_date"])
        seen[k] = seen.get(k, 0) + 1
    for (sym, d), n in sorted(seen.items()):
        new = next(x["renamed_to"] for x in rows
                   if (x["symbol"], x["rename_date"]) == (sym, d))
        _say("attention", f"{n} trade(s) in {sym} after its rename to "
             f"{new} on {d}",
             "Booked as a separate security until a .tt RENAME line says "
             "which it is (`late=fold` or `late=separate`; `tjs "
             "renames` prints the lines).", indent="  ")
    if rows and strict:
        _die(f"--strict: {len(rows)} trade(s) in a renamed ticker after "
             f"its rename are not declared — aborting",
             "See the warnings above and `tjs renames`.")


def cmd_check_dates(args: argparse.Namespace) -> None:
    """`tjs check-dates`: every trade and settlement date the parsers
    produced, checked against the trading calendar of what was traded
    (crypto 24/7, futures 23/5, US stocks with the overnight session,
    options and Canadian listings on exchange days) and the settlement
    rules (lib/check_dates). Exit 1 on an impossible date."""
    from taxjson.lib.check_dates import analyze, render
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    if not (root / "work").is_dir():
        _die("no work/ — run `tjs run` first")
    try:
        doc = analyze(root, cfg, account=args.account)
    except ValueError as e:
        # [settings] futures_settle refused as `run` refuses it (A2-0697).
        _die(str(e))
    if not doc["sources"]:
        _die("no parsed sources in work/ — run `tjs run` first")
    if not args.account:
        _warn_accounts_without_books(root, _discover_tx_accounts(root / "work"),
                                     "check-dates", "parsed source")
    if getattr(args, "json", False):
        _json_out(doc)
    else:
        for ln in render(doc, show_all=args.all, details=_details(args)):
            print(ln)
    if doc["errors"]:
        raise SystemExit(1)


def _tt_path_item(item: str) -> bool:
    """A `check-tt` item that names a file (a path ending in .tt, or
    with a folder in it, or an existing file), not an account."""
    return (item.lower().endswith(".tt") or "/" in item
            or Path(item).is_file())


def _tt_file(root: Path, item: str) -> Optional[Path]:
    """The file a `check-tt` FILE item names, or None: from the shell's
    folder, then from the project's (`-C DIR` does not change the
    shell's folder: _project_file), then a name check-tt itself prints
    (inputs/<account>/x.tt) in the project's inputs folder — in the
    default years layout that is ../inputs/ of the year folder. Before,
    only the shell's folder was looked in (backlog TJ-0033, TJ-0041)."""
    try:
        p = Path(item).expanduser()
        if p.is_file():
            return p
        q = _project_file(root, item)
        if q is not None:
            return q
        parts = Path(item).parts
        if not p.is_absolute() and len(parts) > 1 and parts[0] == "inputs":
            q = _PL.inputs_dir(root).joinpath(*parts[1:])
            if q.is_file():
                return q
    except (OSError, RuntimeError, ValueError):
        pass
    return None


def _check_tt_files_only(args: argparse.Namespace) -> bool:
    """`check-tt FILE.tt ...` needs no project: the files are named."""
    items = getattr(args, "items", None) or []
    return (args.cmd == "check-tt" and bool(items)
            and all(_tt_path_item(i) for i in items))


def _reads_no_project(args: argparse.Namespace) -> bool:
    """A command that reads no project, run in any folder: `check-tt
    FILE.tt ...` and `fetch --list` (the installed fetcher plugins; the
    installer runs it from the user's own folder — backlog TJ-0081)."""
    return _check_tt_files_only(args) or (
        args.cmd == "fetch" and bool(getattr(args, "list", False)))


def cmd_check_tt(args: argparse.Namespace) -> None:
    """`tjs check-tt [ACCOUNT | FILE.tt ...]`: every line of the .tt
    files read with the run's own parsers, every problem named with its
    file and line (lib/check_tt) — the run stops at the first. With no
    item, the project's accounts; an account name, its files; a path,
    that file (`--account` names the account it is read as). Exit 1 on
    a line the run would refuse; nothing is written."""
    from taxjson.lib import check_tt as CT
    root = Path(args.dir).resolve()
    items = list(args.items or [])
    paths = [i for i in items if _tt_path_item(i)]
    names = [i for i in items if i not in paths]
    files = []
    for i in paths:
        f = _tt_file(root, i)
        if f is None:
            _die_input(f"{i}: no such file",
                       "A relative FILE is looked for from the shell's "
                       "folder, then from the project's (`-C DIR`), and "
                       "a name check-tt prints (inputs/<account>/x.tt) "
                       "in the project's inputs folder.")
        files.append(f)
    if names or not paths:
        if not _os_path_lexists(root / _PL.CONFIG):
            _die(*_no_project_message(root, "check-tt"))
        cfg = load_config(root)
        accounts = cfg.get("accounts") or {}
        unknown = [n for n in names if n not in accounts]
        if unknown:
            _die_input(f"no account {unknown[0]!r} in taxjson.toml",
                       "The accounts: " + ", ".join(sorted(accounts))
                       + ". A file is named by its path (ending in .tt).")
        doc = CT.check_project(root, accounts, only=names or None)
    else:
        doc = {"files": [], "problems": [], "lines": 0, "rows": 0,
               "events": 0, "errors": 0, "warnings": 0}
    if paths:
        crypto = None
        if getattr(args, "crypto", False):
            crypto = True
        elif getattr(args, "equity", False):
            crypto = False
        more = CT.check_paths(files, account=getattr(args, "account", None),
                              crypto=crypto, shown=paths,
                              root=root if _PL.has_config(root) else None)
        for k in ("files", "problems"):
            doc[k] = doc[k] + more[k]
        for k in ("lines", "rows", "events", "errors", "warnings"):
            doc[k] += more[k]
    if getattr(args, "json", False):
        _json_out(doc)
    else:
        for ln in CT.render(doc):
            print(ln)
    if doc["errors"]:
        raise SystemExit(1)


def cmd_compare(args: argparse.Namespace) -> None:
    """`tjs compare [NAME] [--save NAME] [--delete NAME] [--list]`:
    reports/ against a snapshot of an earlier run (lib/compare): the
    run before (`prev`, rotated by every full run), a saved one, or
    the reports as filed (`filed`). Exit 1 when a report differs or an
    account figure moved."""
    from taxjson.lib import compare as _cmp
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    _json = getattr(args, "json", False)
    try:
        if args.save:
            doc = _cmp.save(root, cfg, args.save)
            if _json:
                _json_out({"saved": args.save, "taken": doc["taken"],
                           "reports": len(doc["reports"])})
            else:
                print(f"Saved {len(doc['reports'])} report file(s) as "
                      f"{args.save} (work/compare/{args.save}/); "
                      f"`tjs compare {args.save}` diffs against it.")
            return
        if args.delete:
            _cmp.delete(root, args.delete)
            if _json:
                _json_out({"deleted": args.delete})
            else:
                print(f"Deleted snapshot {args.delete}.")
            return
        if args.list:
            items = _cmp.list_snapshots(root, cfg)
            if _json:
                _json_out({"snapshots": items})
            else:
                for ln in _cmp.render_list(items):
                    print(ln)
            return
        if not (root / "reports").is_dir():
            _die_input("no reports/ — run `tjs run` first")
        doc = _cmp.compare(root, cfg, args.name or _cmp.PREV,
                           details=_details(args) or _json)
    except _cmp.CompareError as e:
        # A refusal (nothing to compare with) is exit 2; exit 1 is the
        # finding, a report that differs (cli_diag's convention).
        _die_input(str(e))
    if _json:
        _json_out(doc)
    else:
        for ln in _cmp.render(doc, details=_details(args)):
            print(ln)
    if doc["different"]:
        raise SystemExit(1)


def cmd_snapshot(args: argparse.Namespace) -> None:
    """`tjs snapshot`: the whole project copied to
    snapshot/<year>.<timestamp>/, laid out as it is, for `diff -r` and
    `tjs compare` (lib/compare.take_full)."""
    from taxjson.lib import compare as _cmp
    from taxjson.lib import out as _out
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    try:
        doc = _cmp.take_full(root, cfg)
    except _cmp.CompareError as e:
        _die_input(str(e))
    if doc["partial_accounts"]:
        _out.emit("warning", f"reports/ hold a `tjs run --account "
                  f"{', '.join(doc['partial_accounts'])}` over the last "
                  f"full run's; the snapshot records that")
    if doc["links_leaving"]:
        _out.emit("warning", "kept as links, what they lead to is not in "
                  "the snapshot: " + ", ".join(doc["links_leaving"]))
    if getattr(args, "json", False):
        _json_out(doc)
        return
    _mb = doc["bytes"] / (1024 * 1024)
    print(f"Saved snapshot {doc['name']}: {doc['files']} file(s), "
          f"{_mb:.1f} MB, in {doc['folder']}")
    for ln in _out.kv_lines([
            ("Compare", f"`tjs compare {doc['name']}`"),
            ("Diff", f"`diff -r reports {doc['reports_folder'].rstrip('/')}`")]):
        print(ln)


def cmd_edge_cases(args: argparse.Namespace) -> None:
    """`tjs edge-cases`: transactions whose treatment turns on a
    boundary — trades that settle in a different year than they trade,
    dispositions in the last/first days of a year, written options and
    expiries across Dec 31, income around New Year, crypto near midnight,
    superficial-loss windows that span the year end, and every taxable
    loss with an acquisition or sale within --margin days of the 30-day
    window's edge — each with where it lands and why (lib/edge_cases)."""
    from taxjson.lib.edge_cases import analyze, render_text
    if args.margin < 0:
        # A negative margin emptied the window-edge section at rc 0
        # (audit A2-1198); winners --top refuses < 1 the same way. A
        # usage error: exit 2, said before any file is read (backlog
        # TJ-0157, TJ-0241).
        _die_input(f"--margin must be >= 0, got {args.margin}")
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    if not (root / "work").is_dir():
        _die("no work/ directory — run `tjs run` first")
    _require_books(root, args.account)
    try:
        doc = analyze(root, cfg, margin=args.margin, account=args.account)
    except ValueError as e:
        # An unreadable work file, a damaged row (lib/json_input's row
        # funnel, A2-0330) or an invalid futures_settle: named, never a
        # silent "None." or a traceback (audit A2-1199, A2-0697).
        _die(str(e))
    if getattr(args, "json", False):
        _json_out(doc)
        return
    for line in render_text(doc, details=_details(args)):
        print(line)


def cmd_option_boundary(args: argparse.Namespace) -> None:
    """`tjs option-boundary [--json]`: every written option in the
    taxable accounts whose write and close straddle a tax-year boundary
    (or that is still open at the project year's end) — where each
    amount lands under the timing in force (ITA s.49), and whether a
    filed year needs a T1-ADJ. A `filed/<year>.json` lock is what turns
    "if that year was filed" into a fact; ATTENTION rows (a locked year
    kept on transition close timing, an expired contract with no
    expiry row) need action. Exit 1 when no taxable book exists (nothing
    was checked), 0 otherwise."""
    from taxjson.lib.core import TaxTransaction
    from taxjson.lib.option_boundary import reported_premiums, straddling
    from taxjson.lib.pipeline import option_timing_from_settings
    root = Path(args.dir).resolve()
    cache = root / "work"
    cfg = load_config(root)
    settings = cfg.get("settings", {})
    if not isinstance(settings.get("year"), int):
        # It went on with year 0 and printed "tax year 0" (S044-07).
        _die("[settings] year is required in taxjson.toml",
             "The review is per tax year.")
    from taxjson.lib import out as _out
    _prog = "tjs option-boundary"
    year = int(settings["year"])
    kw = option_timing_from_settings(settings)
    timing = kw.get("option_premium_timing", "close") if kw else "close"
    since = kw.get("option_grant_since") if kw else None
    _w = _grant_since_warning(settings, root, cfg.get("accounts") or {})
    if _w:
        _out.warn(_w, prog=_prog)
    filed_years = set()
    filed_timing: Dict[int, Dict[str, Any]] = {}
    filed_labels: Dict[int, str] = {}
    from taxjson.bin import taxjson_filed as _tfl
    # The project's own locks AND the one [settings] prior_year_record
    # names: in the per-year layout last year's lock lives in the
    # previous project, and "no filed-year locks ... No amended return
    # is required" was printed for a premium that lock put in no return
    # (A2-0036, A2-0335).
    try:
        _locks = _tfl.project_locks(root, settings)
    except _tfl.PriorRecordError as e:
        _die(str(e))
    # What each lock's return reported for the written options: a lock
    # re-closed without an assigned contract's premium is the amended
    # return, and asks for no T1-ADJ (backlog TJ-0085).
    filed_premiums: Dict[int, Any] = {}
    _docs: Dict[int, Dict[str, Any]] = {}
    for fy, f, _where in _locks:
        filed_years.add(fy)
        _lbl = _tfl.lock_label(root, f)
        filed_labels[fy] = _lbl
        try:
            # The one check every reader of a lock applies (read_lock):
            # a damaged lock, or one closed under the other country's
            # law, was read raw for its timing (backlog TJ-0069).
            _doc = _tfl.read_lock(f, settings, label=_lbl,
                                  prior=_where != "local")
        except _tfl.LockProblem as e:
            # The lock's recorded timing drives the advice below: an
            # unreadable lock silently read as "no timing recorded" and
            # the advice flipped to ATTENTION / since = <locked year>
            # (S044-08).
            _out.warn(f"cannot read {_lbl} as a close-year lock — its "
                      f"recorded option timing is unknown", prog=_prog,
                      details=[f"{e}", f"The advice for {fy} below assumes "
                               f"none was recorded; `tjs check-filed` "
                               f"checks the lock."])
            continue
        _docs[fy] = _doc
        _ot = _doc.get("option_timing")
        if isinstance(_ot, dict):
            filed_timing[fy] = _ot
        _rp = reported_premiums(_doc)
        if _rp is not None:
            filed_premiums[fy] = _rp
    # A lock taken before its year ended is a snapshot, not a filed
    # return (A2-1164): said beside the year.
    partial_locks: Dict[int, str] = {}
    from taxjson.bin.taxjson_filed import partial_year_note
    for fy, _doc in _docs.items():
        _pn = partial_year_note(_doc, fy)
        if _pn:
            partial_locks[fy] = _pn
    rows = []
    books = 0
    missing = []
    _mh_pairs = None
    _mh = _missing_history_arg(root)
    if _mh is not None:
        from taxjson.lib.missing_history import load_missing_history
        try:
            _mh_pairs = load_missing_history(_mh) or None
        except (OSError, ValueError) as e:
            _die("the .tt OPENING cost=unknown lines cannot be read",
                 str(e))
    # A crypto account writes no options (lib/option_boundary skips it
    # too), and one the run skipped for an empty inputs/ folder has no
    # books to make: "run `tjs run`" about either looped (workflow
    # audit 2026-10-22, item 12).
    _no_inputs = _accounts_skipped_for_no_inputs(root)
    empty = []
    for name, acfg in sorted((cfg.get("accounts") or {}).items()):
        if not isinstance(acfg, dict) or acfg.get("type", "sheltered") != "taxable" \
                or acfg.get("crypto"):
            continue
        base = cache / f"{name}_base.json"
        if not base.exists():
            if name in _no_inputs:
                empty.append(name)
                continue
            missing.append(name)
            _out.warn(f"no work/{base.name}", prog=_prog,
                      details=["Run `tjs run` first."])
            continue
        books += 1
        # A truncated, non-UTF-8 or wrong-shape book was a traceback
        # here (S042-18).
        doc = _load_json_or_die(base)
        if not isinstance(doc.get("transactions"), list):
            # An object without its rows ({"accounts": []}) iterated its
            # keys as rows: an AttributeError traceback (issue #53).
            _die_input(f'work/{base.name} has no "transactions" list — the '
                 f'books are damaged or from an interrupted run',
                 "Run `tjs run` to rebuild them.")
        txs = []
        for r in doc["transactions"]:
            try:
                txs.append(TaxTransaction(**{k: v for k, v in r.items()
                                             if k in TaxTransaction.__dataclass_fields__}))
            except TypeError:
                continue
        if _mh_pairs is not None:
            # The same missing-history openings the gains stage adds: a
            # LONG option bought before the data and sold to close read as a WRITE, with a
            # false checklist ATTENTION when it had expired (S044-09).
            from taxjson.lib.missing_history import synthesize_openings
            txs, _log = synthesize_openings(txs, _mh_pairs)
        for r in straddling(txs, year, timing, since, filed_years,
                            filed_timing=filed_timing,
                            tax_date=_tax_date_basis(settings),
                            filed_labels=filed_labels,
                            filed_premiums=filed_premiums):
            r["account"] = r["account"] or name
            rows.append(r)
    if not books:
        # Nothing was checked: printing the all-clear here let the
        # checklist mark the step done on a project that never ran.
        if empty and not missing:
            _f = ", ".join(f"{_PL.shown(_PL.inputs_dir(root), root)}/{n}"
                           for n in empty)
            _die(f"NOT CHECKED — {_f} {'is' if len(empty) == 1 else 'are'} "
                 f"empty, so the run made no books",
                 "Save the account's exports there, or delete its "
                 "[accounts.NAME] table from taxjson.toml if you do not "
                 "have it.")
        _die("NOT CHECKED — no taxable base files in work/",
             "Run `tjs run` first.")
    amend = [r for r in rows if r["action"].startswith("T1-ADJ")]
    attention = [r for r in rows if r.get("attention")]
    if getattr(args, "json", False):
        _json_out({"year": year, "timing": timing, "since": since,
                   "since_explicit": settings.get(
                       "option_grant_timing_since") not in (None, ""),
                   # The grant-timing warning above was given (the run's
                   # gate: a written option in the books) — what the
                   # checklist flags (audit 2026-10-22, item 10).
                   "since_warning": bool(_w),
                   "filed_years": sorted(filed_years),
                   "partial_locks": {str(k): v for k, v in
                                     sorted(partial_locks.items())},
                   "rows": rows,
                   "amend": len(amend), "attention": len(attention),
                   "missing_books": missing})
        return
    def _para(text: str, indent: str = "", hang: Optional[str] = None):
        for _ln in _out.wrap(text, None, indent,
                             indent if hang is None else hang):
            print(_ln)

    print(f"OPTION YEAR-BOUNDARY REVIEW — tax year {year}")
    # Essentials first (docs/output-style.md): --details adds each
    # contract's where and what-if.
    _det = _details(args)
    if not _det:
        _para(f"Premium timing: {timing}"
              + (f" (from {since})" if timing == "grant" and since else "")
              + "; filed-year locks: "
              + (", ".join(str(y) + (" (partial: taken before the year "
                                     "ended)" if y in partial_locks else "")
                           for y in sorted(filed_years))
                 if filed_years else "none") + ".")
    else:
        _para(f"Premium timing: {timing}"
          + (f" (contracts written from {since})"
             if timing == "grant" and since else "") + ".")
    if filed_years and _det:
        _para("Filed-year locks: " + ", ".join(
            str(y) + (" (partial: taken before the year ended)"
                      if y in partial_locks else "")
            for y in sorted(filed_years)) + ".")
    elif _det:
        _para("No filed-year locks (run `tjs close-year` after "
              "filing).")
    for _py in sorted(partial_locks):
        _para(_out.label("note", stream=sys.stdout) + partial_locks[_py],
              "", "  ")
    print()
    if not rows:
        _para("No written option straddles a year boundary and none is "
              "open at year end. Nothing to amend.")
        return
    out = ["ACCOUNT SYMBOL WRITTEN UNITS PREMIUM CLOSED KIND PAID"]
    for r in rows:
        # (`?`: the write is not in the books — a short opening balance
        # or a transfer in — so the premium is unknown)
        out.append(" ".join([r["account"], r["symbol"], r["written"], f"{r['units']:g}",
                             "?" if r["premium"] is None else fmt_money(r["premium"]),
                             r["closed"] or "-", r["close_kind"],
                             fmt_money(r["paid"]) if r["paid"] else "-"]))
    if not _det:
        print("KIND: how it closed (open: still open at year end); PAID: "
              "the cost to close it"
              + ("; PREMIUM ?: the write is not in the books."
                 if any(r["premium"] is None for r in rows) else "."))
    # Too wide: PAID, then UNITS go; then one record per contract.
    _print_report_table(out, fit=True, drop=(7, 3), key=(1, 0))
    print()
    if not _det:
        for r in rows:
            if str(r.get("action", "")).startswith("T1-ADJ"):
                print(_out.act(f"{r['symbol']} ({r['account']}): an "
                               f"amended return (T1-ADJ)",
                               "tjs option-boundary --details"))
            elif r.get("attention"):
                print(_out.act(f"{r['symbol']} ({r['account']}): review "
                               f"it", "tjs option-boundary --details"))
    for i, r in enumerate(rows if _det else [], 1):
        _lead = f"{i:>3}. "
        _hang = " " * len(_lead)
        _para(f"{r['symbol']} ({r['account']}, written {r['written']}): "
              f"{r['where']}", _lead, _hang)
        _para(f"=> {r['action']}", _hang, _hang + "   ")
    if _det:
        print()
    # (the default view said each as a `! ` line above)
    if attention and _det:
        _para(f"{len(attention)} item(s) need ATTENTION (review; a locked "
              f"year may need a T1-ADJ) — marked above.")
    if amend and _det:
        _para(f"{len(amend)} item(s) require an amended return (T1-ADJ) — "
              f"listed above with the year and amount.")
    if not amend and not attention:
        _para("No amended return is required by these contracts under the "
              "timing in force.")


def cmd_checklist(args: argparse.Namespace) -> None:
    """`tjs checklist`: every step from install to filing, in order
    (lib/checklist.items). `--run` checks each — a check runs the
    command that proves it (or reads the project's files) — and stores
    the verdicts in work/checklist_results.json (`-j N`: N slow checks
    at a time); without `--run` the stored verdicts are shown as they
    are, with a line saying when they were made and what changed since
    (nothing stored: the steps, unchecked). The view is the list, then
    the summary (the counts per section, one `!` line per step needing
    attention); `--section N[,N]` one or more sections of it. Manual marks for the
    items no command can prove (`--done ID [--force]`, `--undo ID`,
    ID the step's id or its number; stored in checklist.json at the
    project root, which you should commit) are applied as they are now.
    The last line names the next item and its command. `--walk` steps
    through the open items one at a time, checking each. Exit 1 while
    anything is open. Outside a project (no taxjson.toml) it prints the
    same list as a step-by-step guide, exit 0."""
    import json as _json
    from datetime import date as _date
    from taxjson.lib import checklist as cl

    root = Path(args.dir).resolve()
    if getattr(args, "skip", None):
        _named = ",".join(t.strip() for tok in args.skip
                          for t in str(tok).split(",") if t.strip())
        _die_input(f"--skip was replaced by --done --force: `tjs "
                   f"checklist --done {_named or 'ID'} --force`",
                   "It marks the step done over the last check's finding "
                   "(shown [f], the finding beside it). Nothing was "
                   "written.")
    section: List[str] = []
    if args.section:
        try:
            section = cl.resolve_sections(args.section)
        except KeyError as e:
            _die(f"unknown section {e.args[0]!r}",
                 "Sections: " + "; ".join(cl.section_label(sec)
                                          for sec in cl.SECTIONS)
                 + ". Several: `--section 6,7`.")
        if not section:
            _die("--section names no section")
        if args.only:
            _die("--section and --only: one or the other")
    if not _PL.has_config(root):
        used = [f for f, v in (("--done", args.done), ("--force", args.force),
                               ("--undo", args.undo), ("--reset", args.reset),
                               ("--walk", args.walk), ("--only", args.only),
                               ("--quick", args.quick), ("--show", args.show),
                               ("--note", args.note)) if v]
        if used:
            _die_input(f"{used[0]} needs a project: no taxjson.toml in "
                       f"{root}",
                       "Run `tjs checklist` in the project folder (or "
                       "`tjs -C DIR checklist`); here it prints the "
                       "steps.")
        if args.json:
            _json_out(cl.guide_json(section=section))
            return
        print(cl.render_guide(section=section))
        return
    cfg, cfg_error = _checklist_config(root)
    settings = cfg.get("settings") or {}
    year = settings.get("year")
    if not isinstance(year, int):
        _die("[settings] year is required in taxjson.toml")
    country = _country(settings)

    ids = cl.item_ids()
    if args.note and not args.done:
        _die("--note goes with --done (it is stored with the mark)")
    if args.force and not args.done:
        _die("--force goes with --done (it marks a step done over the "
             "check's finding)")

    def step_id(token: str) -> str:
        # A step by its id or its number in the list (`--done 18`).
        try:
            return cl.resolve_id(token)
        except KeyError:
            _die(f"unknown step {token!r}",
                 f"Step ids: {', '.join(ids)}; or the step's number, "
                 f"1-{len(ids)}.")
    def steps(flag: str, tokens) -> List[str]:
        # `--done a,b` and `--done a --done b` both name a and b.
        named = [step_id(t.strip()) for tok in (tokens or [])
                 for t in str(tok).split(",") if t.strip()]
        if tokens and not named:
            _die(f"{flag} names no step")
        return named
    # Every repeated --done/--undo is recorded (only the last one was,
    # silently — A2-1159); an unknown id stops before any is written.
    ctx = cl.Ctx(root=root, cfg=cfg, year=year, today=_date.today(),
                 run_sub=cl.default_run_sub(root), config_error=cfg_error)
    marks = ([(st, "done") for st in steps("--done", args.done)]
             + [(st, None) for st in steps("--undo", args.undo)])
    # The rest of the command line is checked first, so an error in it
    # writes no mark: `--done ID --run --only typo` recorded the mark
    # and then stopped on the typo (audit 2026-10-24 A15).
    only = steps("--only", [args.only]) if args.only else None
    scope = ""
    if section:
        only = cl.sections_ids(section)
        scope = cl.sections_label(section)
    elif only:
        scope = ", ".join(only)
    jobs = args.jobs if args.jobs is not None else cl.default_jobs()
    if jobs < 1:
        _die("-j takes a number of 1 or more (slow checks at a time)")
    if args.walk and not sys.stdin.isatty():
        _die("--walk needs a terminal",
             "Use `tjs checklist --run` for the report, "
             "--done to record steps.")
    # A plain --done over a kept finding would record a mark the list
    # never shows (a DONE mark never hides a finding): refused before
    # anything is written, naming --force; --force records a forced
    # mark where the check flags the step, a plain done elsewhere. A
    # question awaiting its answer is no such finding (the DONE mark
    # answers it) — decided by the kept verdict, not the step: a
    # question step's attention that asks nothing (fx-cash's NOT
    # RELIABLE) was never refused nor forced (audit 2026-10-25
    # first-project#1). This year's verdicts only (diff-tooling#2).
    kept = {st: cl.kept_verdict(ctx, st) for st, m in marks if m == "done"}
    findings = {st: cl.finding_over_done(r) for st, r in kept.items()}
    flagged = [st for st, v in findings.items() if v]
    if flagged and not args.force:
        st = flagged[0]
        _die(f"{st} is marked {findings[st]} by the last check — a done "
             f"mark would not show over it",
             f"Fix it (`tjs checklist --only {st}` says what), then "
             f"`--run --only {st}`; or accept it as it is: `tjs "
             f"checklist --done {st} --force` (shown [f], the finding "
             f"beside it).")
    marks = [(st, cl.MARK_FORCED if m == "done" and st in flagged else m)
             for st, m in marks]
    from taxjson.lib import out as _out
    recorded: List[Dict[str, Any]] = []
    for step, mark in marks:
        if step:
            # A question step's DONE mark answers the questions asked now
            # (their keys stored with it); a later one asks again.
            answers = (cl.question_answers(root, cfg, step,
                                           today=_date.today())
                       if mark == "done" and step in cl.QUESTION_STEPS
                       else None)
            try:
                changed = cl.set_override(root, year, step, mark,
                                          note=args.note or "",
                                          answers=answers)
            except KeyError:
                _die(f"unknown step {step!r}", f"Step ids: {', '.join(ids)}.")
            except cl.StateFileError as e:
                _die_state(e)
            verb = {"done": "marked done",
                    cl.MARK_FORCED: "marked done (forced)",
                    None: "mark removed"}[mark]
            if not changed:
                verb = "had no mark — nothing to undo"
            recorded.append({"step": step, "mark": mark or "undo",
                             "changed": changed, "note": args.note or "",
                             **({"answers": answers} if answers is not None
                                else {})})
            if not args.json:
                # The confirmation, no program name in front and its
                # later lines flush-left, wrapped at the width
                # (docs/output-style.md; backlog TJ-0174).
                lines = [f"{step} {verb}"
                         + (f" (recorded in {cl.STATE_FILE})." if changed
                            else ".")]
                if mark == cl.MARK_FORCED:
                    lines.append(f"The check still says {findings[step]}: "
                                 f"shown [f] with the finding beside it; "
                                 f"`--undo {step}` takes the mark back.")
                elif mark == "done" and args.force:
                    asked = kept.get(step)
                    # (a question's DONE mark is its answer: forced, it
                    # would accept every later question too)
                    lines.append(
                        f"(nothing to force: the done mark answers "
                        f"{step}'s question)"
                        if asked is not None and asked.question
                        and asked.status in cl.FINDING_STATUSES else
                        f"(nothing to force: the last check does not "
                        f"flag {step})")
                if answers:
                    lines.append(f"it answers: "
                                 + "; ".join(cl.key_text(step, k)
                                             for k in answers)
                                 + " — a new one asks again.")
                _out.show([w for ln in lines
                           for w in _out.wrap(ln, stream=sys.stdout)],
                          sys.stdout)
    if args.reset:
        try:
            existed = cl.reset_state(root)
        except cl.StateFileError as e:
            _die_state(e)
        recorded.append({"step": None, "mark": "reset", "changed": existed})
        if not args.json:
            print(f"{cl.STATE_FILE} removed." if existed
                  else f"No {cl.STATE_FILE} — nothing to reset.")
    if (args.done or args.undo or args.reset) and not args.walk \
            and not args.show and not args.run:
        if args.json:
            print(_json.dumps({"year": year, "state_file": cl.STATE_FILE,
                               "recorded": recorded}, indent=2))
        return

    from taxjson.lib.out import note as _note, warn as _warn
    if args.only and args.quick and args.run:
        _note("--only names one step; ignoring --quick.",
              prog="tjs checklist")
        args.quick = False

    if args.walk:
        try:
            _checklist_walk(ctx, cl, only, quick=args.quick, scope=scope)
        except cl.StateFileError as e:
            _die_state(e)
        return

    # The default view is the list (an open step's commands, the next
    # step's how and why) and then the summary; --all (or --details)
    # adds every item's how, commands and why; --only ID shows that item
    # in full; --section N one section.
    show_all = bool(args.all or _details(args) or args.only)
    quick = bool(args.quick and args.run)
    try:
        if args.run:
            results = cl.evaluate(ctx, only=only, quick=args.quick,
                                  progress=(cl.stderr_progress
                                            if show_all or args.json
                                            else cl.once_progress()),
                                  jobs=jobs)
            try:
                doc = cl.save_results(ctx, results)
            except OSError as e:
                # A read-only project, a full disk: the verdicts are
                # shown this once and not kept.
                _warn(f"the verdicts could not be stored in "
                      f"work/{cl.RESULTS_FILE} ({e.strerror or e}): "
                      f"shown now, not kept", prog="tjs checklist")
                info = cl.fresh_info()
            else:
                results, info = cl.load_results(ctx, only=only, doc=doc)
        else:
            if args.quick or args.jobs is not None:
                _note("--quick and -j go with --run; showing the stored "
                      "verdicts.", prog="tjs checklist")
            results, info = cl.load_results(ctx, only=only)
    except cl.StateFileError as e:
        _die_state(e)
    if args.json:
        print(_json.dumps(cl.to_json(results, year, country, info,
                                     root=root),
                          indent=2))
    else:
        print(cl.render(results, year, country, quick=quick,
                        show_all=show_all, root=root, info=info,
                        scope=scope,
                        whole=_checklist_whole(ctx, cl, only, results)))
    if not all(r.passed for r in results):
        sys.exit(1)


def _checklist_whole(ctx, cl, only, results) -> Optional[List[Any]]:
    """Every step's kept verdict, the scoped view's `results` over them,
    for a scoped view (`--section`, `--only`) with nothing left in it:
    its last line names the next step elsewhere (backlog TJ-0048). None
    for the whole list, or while the scope has something left."""
    if not only or not all(r.passed for r in results):
        return None
    try:
        rest, _info = cl.load_results(ctx)
    except (cl.StateFileError, OSError):
        return None
    mine = {r.id: r for r in results}
    return [mine.get(r.id, r) for r in rest]


def _checklist_config(root: Path) -> Tuple[Dict[str, Any], str]:
    """(taxjson.toml, "" or why every other command refuses it) for the
    checklist. A config the strict loader refuses — a crypto account and
    no local_timezone (what `init` writes on a UTC machine), an old map
    file `tjs migrate` moves — is the configure item's finding, not
    an error instead of the list: the TOML is
    read leniently and the checks that need the strict config are
    blocked. Only a file with no readable (or plausible) year, country
    or account names still stops here, with the loader's own message."""
    import contextlib
    import io
    from taxjson.lib.country import CountryError, settings_country
    buf = io.StringIO()
    try:
        with contextlib.redirect_stderr(buf):
            return load_config(root), ""
    except SystemExit as e:
        strict = e
        text = e.code if isinstance(e.code, str) else buf.getvalue()
    try:
        raw = (root / "taxjson.toml").read_bytes()
        cfg = tomllib.loads(raw.decode("utf-8-sig"))
        settings = cfg.get("settings")
        accounts = cfg.get("accounts") or {}
        year = settings.get("year") if isinstance(settings, dict) else None
        # The loader's plausible range (_normalize_settings): a typo'd
        # year still stops here, never a list for tax year 1850.
        # An account that is no table (`margin = 42`) died later on
        # a.get in the detectors (audit 2026-10-24 A16): the loader's
        # own message instead.
        ok = (isinstance(accounts, dict)
              and isinstance(year, int) and not isinstance(year, bool)
              and 1900 <= year <= date_cls.today().year + 1
              and all(re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_.-]*", str(n))
                      and str(n).upper() != "COMBINED"
                      and isinstance(a, dict) for n, a in accounts.items()))
        if ok:
            settings["country"] = settings_country(settings)
    except (OSError, UnicodeError, ValueError, TypeError, CountryError):
        ok = False
    if not ok:
        if not isinstance(strict.code, str) and buf.getvalue():
            sys.stderr.write(buf.getvalue())
        raise strict
    # A folder taxjson writes into that is a link leaving the project
    # is refused as every command refuses it (load_config), lenient
    # read or not: the checklist wrote work/checklist_results.json
    # through such a work/ link (audit 2026-10-24 A17).
    _refuse_outside_dir_links(root, accounts)
    # The loader's message without its `tjs checklist: error:`
    # headline prefix, on one line.
    msg = " ".join(re.sub(r"\x1b\[[0-9;]*m", "", text).split())
    msg = re.sub(r"^(?:Error:\s*|.*?: error:\s*)", "", msg, count=1)
    return cfg, msg or "taxjson.toml is refused by every other command"


def _walk_interrupted(sid: str, ctx) -> None:
    from taxjson.lib.out import error
    print(file=sys.stderr)
    error(f"interrupted at {sid} — it is not recorded",
          prog="tjs checklist",
          details=[f"The marks made so far are kept in "
                   f"{ctx.root / 'checklist.json'}."])
    sys.exit(1)


def _checklist_walk(ctx, cl, only, quick: bool = False,
                    scope: str = "") -> None:
    """Interactive pass over the open steps, one detector at a time: each
    step is shown as soon as its own check finishes (the whole list can
    take a minute on a big book), with why it matters and what was found,
    then the user's decision is recorded. Ends with the summary; exit 1
    while anything is still open (also after [q]uit)."""
    from taxjson.lib.out import kv_lines, wrap
    country = _country(ctx.settings)
    ids = [sid for sid in cl.item_ids() if not only or sid in only]
    keys = "[d]one  [f]orce done  [r]e-check  [n]ext  [q]uit  (Enter = next)"
    print("CHECKLIST WALK")
    print(f"For each open step: {keys}\n")
    seen = 0
    quit_early = False
    for sid in ids:
        r = cl.evaluate(ctx, only=[sid], quick=quick,
                        progress=cl.stderr_progress)[0]
        _walk_store(ctx, cl, r)
        if r.passed:
            for ln in wrap(f"{cl.SYMBOL[r.effective]} {sid}"
                           + (f": {r.detail}" if r.detail else "")
                           + (f" (marked {cl.mark_text(r.override)})"
                              if r.override else ""), None, "  ", "      "):
                print(ln)
            continue
        seen += 1
        _, section, title, cmd, why = cl.item_meta(sid, country)
        show = True
        while True:
            if show:
                print(f"\n{section.upper()} — {sid}")
                for ln in wrap(title, None, "  ", "  "):
                    print(ln)
                for ln in kv_lines([
                        ("why", why), ("proves", cmd),
                        ("found", f"{cl.SYMBOL[r.effective]} {r.detail}"
                         + (f" (marked {cl.mark_text(r.override)}"
                            + (f": {r.note}" if r.note else "") + ")"
                            if r.override else ""))], "  "):
                    print(ln)
            show = False
            try:
                ans = input("  > ").strip().lower()
            except EOFError:
                print()
                quit_early = True
                break
            except KeyboardInterrupt:
                _walk_interrupted(sid, ctx)
            if ans in ("d", "done", "f", "force"):
                # EOF or Ctrl-C at the note/reason prompt was a traceback
                # (re-audit A2-1394): this step is not recorded, the
                # marks made so far are kept.
                try:
                    note = input("  note (optional): " if ans[0] == "d"
                                 else "  reason (optional): ").strip()
                except (EOFError, KeyboardInterrupt):
                    _walk_interrupted(sid, ctx)
            if ans in ("q", "quit"):
                quit_early = True
                break
            if ans in ("d", "done"):
                if cl.finding_over_done(r):
                    # (as `--done` is refused: the mark would not show —
                    # a question step's finding that asks nothing too,
                    # audit 2026-10-25 first-project#1)
                    print(f"  {sid} is {r.status}: a done mark would not "
                          f"show over it — [f] accepts it as it is")
                    continue
                cl.set_override(
                    ctx.root, ctx.year, sid, "done", note=note,
                    answers=(cl.question_answers(ctx.root, ctx.cfg, sid,
                                                 today=ctx.today)
                             if sid in cl.QUESTION_STEPS else None))
                print(f"  recorded: {sid} done")
                break
            if ans in ("f", "force"):
                cl.set_override(ctx.root, ctx.year, sid, cl.MARK_FORCED,
                                note=note)
                print(f"  recorded: {sid} done (forced)")
                break
            if ans in ("r", "recheck", "re-check"):
                r = cl.evaluate(ctx, only=[sid], progress=cl.stderr_progress)[0]
                _walk_store(ctx, cl, r)
                if r.passed:
                    for ln in wrap(f"now: {cl.SYMBOL[r.effective]} "
                                   f"{r.detail}", None, "  ", "    "):
                        print(ln)
                    break
                show = True
                continue
            if ans in ("", "n", "next"):
                break
            print(f"  unknown key {ans!r} — {keys}")
        if quit_early:
            break
    print(f"\n{seen} open step(s) visited. Summary "
          f"(`tjs checklist --run` re-checks everything):\n")
    results, info = cl.load_results(ctx, only=only)
    print(cl.render_summary(results, ctx.year, country, root=ctx.root,
                            info=info, scope=scope,
                            whole=_checklist_whole(ctx, cl, only,
                                                   results)))
    if quit_early or not all(r.passed for r in results):
        # Open steps remain: the one quit on, the ones passed over, a
        # DONE mark that did not settle the step's finding — the exit
        # follows the verdicts as kept, like `--run`'s (audit
        # 2026-10-24 A18).
        sys.exit(1)


def _walk_store(ctx, cl, r) -> None:
    """A walked step's verdict goes to the store like a --run's; a store
    that cannot be written never stops the walk."""
    try:
        cl.save_results(ctx, [r])
    except OSError:
        pass


def _mask_ids_in_path(path: str) -> str:
    """`path` with every broker-account-like id in its FILE NAME masked
    to its first 2 characters + *** (U1234567 -> U1***, 53123456 ->
    53***): an IB U-number or a run of 5+ digits."""
    head, sep, name = str(path).rpartition("/")
    name = re.sub(r"(?<![A-Za-z0-9])(U\d{5,}|\d{5,})(?!\d)",
                  lambda m: m.group(1)[:2] + "***", name)
    return head + sep + name


def _sanity_note(text: str) -> None:
    """`tjs sanity: note: ...` on stderr, wrapped (lib/out)."""
    from taxjson.lib.out import note
    note(text, prog="tjs sanity")


def _project_file(root: Path, name: str) -> Optional[Path]:
    """`name`, a relative FILE argument that is not under the shell's
    folder, as the project's own file when it is one there (`-C DIR`
    does not change the shell's folder), else None."""
    try:
        q = Path(name).expanduser()
        if q.is_absolute():
            return None
        q = root / q
        return q if q.is_file() else None
    except (OSError, RuntimeError):
        return None


def cmd_sanity(args: argparse.Namespace) -> None:
    """`tjs sanity ITEM... [--tolerance N] [--json]`: LOOSE
    cross-check of open positions against externally produced holdings
    TOML files (a [[holding]] array of symbol/quantity tables).

    Two argument forms, freely mixed:

    * bare `ACCOUNT` / `FILE.toml` items — the AGGREGATE form: every
      bare account's positions are SUMMED into one book and compared
      against the SUM of every bare file. (Pairing was cumbersome for
      a quick check, and the pathological case — every total matching
      while positions sit in the wrong accounts — is rare.)
    * `ACCOUNT[+ACCOUNT...]=FILE[+FILE...]` — a PAIRED group: only
      those accounts against only those files. Many-to-many because a
      taxjson account can span several broker accounts (margin =
      IBKR + Webull → two exports) and one broker export can cover
      several taxjson accounts. Repeating a left-hand side
      (`margin=ibkr.toml margin=webull.toml`) merges into one group.

    Each group is compared independently; an account or file may sit
    in only one group. taxjson side: the canonical gains inventory
    (same basis as `tjs list` — wash-adjusted where built, post
    ticker.map). The files' symbols get the same GLOBAL+TOBASE renames,
    with options following their underlying's rename. Exit 1 on any
    discrepancy in any group.

    A FILE may also be a broker's own positions report
    (lib/positions_reports: an IB Activity Statement's Open Positions,
    an RBC Holdings Export). When a report is dated before the books'
    last row, the books' positions ON that day are compared (rebuilt
    from work/<acct>_base.json). After the quantities, the books' COST
    is compared with the report's where it states one, with a reason
    for each difference (lib/positions_check) — never a failing exit —
    and a dividend paid on a share count the books did not hold on its
    record date is listed (informational)."""
    import json
    from taxjson.lib.json_input import check_gains_parts
    from taxjson.lib.report_model import (gains_basis_label,
                                          resolve_gains_files)
    from taxjson.lib import positions_check as PC
    from taxjson.lib.brokerages.base import shown_name
    from taxjson.lib.positions_reports import (PositionsDateError,
                                               PositionsReportError,
                                               PositionsSnapshotError,
                                               read_positions, toml_as_of)
    root = Path(args.dir).resolve()
    cache = root / "work"
    tol = float(1e-4 if getattr(args, "tolerance", None) is None
                    else args.tolerance)
    cost_tol = float(1.0 if getattr(args, "cost_tolerance", None) is None
                     else args.cost_tolerance)
    if tomllib is None:
        _die("needs tomllib (py3.11+) or tomli")

    # ---- taxjson side ---------------------------------------------------
    resolved = resolve_gains_files(cache)
    if not resolved:
        # Books that are missing or cannot be read are an input this
        # check cannot read: exit 2, as docs/commands.md's exit-code
        # table says; 1 stays the verdict "positions differ" (backlog
        # TJ-0353).
        # Named from the project (docs/output-style.md; TJ-0631).
        _die_input("no gains files in work/ — run `tjs run` first.")
    basis = gains_basis_label(resolved)
    tax: Dict[str, Dict[str, float]] = {}
    unreadable: Dict[str, str] = {}
    from taxjson.lib.out import warn as _warn
    for acct, f in resolved.items():
        try:
            data = json.loads(f.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                raise ValueError("not a gains document")
            # `{}` is a damaged gains file, never an empty book that
            # compares clean (backlog TJ-0412).
            check_gains_parts(data, f)
        except (OSError, ValueError) as e:
            # Said once, below: the Error that refuses an account the
            # check takes in (_account), else a warning that it is left
            # out (_warn_left_out) — a warning by its absolute path
            # came first and the Error said it again (backlog TJ-0631).
            unreadable[acct] = f"work/{f.name}: {e}"
            continue
        book: Dict[str, float] = {}
        bad_qty = ""
        for h in (data.get("inventory") or []):
            sym = str(h.get("symbol") or "")
            _qraw = h.get("qty", 0)
            try:
                q = float(_qraw or 0)
            except (TypeError, ValueError):
                q = float("nan")
            if q != q or q in (float("inf"), float("-inf")):
                # A NaN quantity failed every comparison, so the
                # position vanished and the account's empty book
                # compared clean (audit 2026-10-24 B19). The books are
                # unreadable: an account they belong to is refused
                # below (_account), as a gains file that is not JSON is.
                bad_qty = (f"work/{f.name}: {sym or '?'}: inventory qty "
                           f"{_qraw!r} is not a finite number")
                break
            if sym and abs(q) > 1e-12:
                book[sym] = book.get(sym, 0.0) + q
        if bad_qty:
            unreadable[acct] = bad_qty
            continue
        tax[acct] = book

    # ---- classify the positionals into groups ------------------------------
    # A group is (accounts, files); bare items all land in one AGGREGATE
    # group, `A[+A]=F[+F]` items in a PAIRED group keyed by its accounts
    # so a repeated left-hand side merges. Each account/file belongs to
    # at most one group — a second placement is a usage error rather
    # than a silent double count.
    _declared_memo: List[Dict[str, Any]] = []

    def _declared() -> Dict[str, Any]:
        """taxjson.toml's accounts, read once. (A taxjson.toml that
        cannot be read stops here with its own Error, as the compare
        below would.)"""
        if not _declared_memo:
            _declared_memo.append(dict(
                (load_config(root) if _PL.has_config(root) else {})
                .get("accounts") or {}))
        return _declared_memo[0]

    def _account(name: str, ctx: str) -> str:
        if name in tax:
            return name
        if name in unreadable:
            # Its book exists but is corrupt: say so, not "not an
            # account" (R1-338 — that sent the user to the config).
            # The damaged file leads, not taxjson.toml (backlog TJ-0057).
            # Exit 2: an input that cannot be read (TJ-0353).
            _die_input(f"{unreadable[name]} — the books of {name!r} "
                       f"cannot be read: re-run `tjs run` to rebuild "
                       f"them.")
        if name in _declared():
            # An account of taxjson.toml with no books: it was refused
            # as "not an account" (backlog TJ-0639). No inputs, no
            # books, nothing to compare its holdings with — said, with
            # its inputs folder; with inputs, the run did not build
            # them. Exit 2: an input missing (docs/commands.md).
            _no_books(name, ctx)
        # A usage error, exit 2; 1 stays the verdict "positions differ"
        # (docs/commands.md, Exit codes; backlog TJ-0630).
        _die_input(f"{ctx}: {name!r} is not an account "
                   f"(have: {', '.join(sorted(tax))})")

    def _no_books(name: str, ctx: str) -> None:
        """Refuse account NAME of taxjson.toml, which has no gains file
        in work/ (exit 2), saying why: its run did not build them, or it
        has no inputs to build them from (backlog TJ-0639)."""
        if _has_inputs(root, name):
            _die_input(f"{ctx}: no gains file in work/ for account "
                       f"{name!r}, whose inputs are there — the last "
                       f"`tjs run` did not build them (did it "
                       f"fail?): fix and re-run `tjs run`.")
        _in = _PL.inputs_dir(root) / name
        _shown = _PL.shown(_in, root)
        _how = ("leave it out of the check" if ctx != "taxjson.toml"
                else "take out its "
                + ("`holdings` setting"
                   if (_declared().get(name) or {}).get("holdings")
                   else "snapshot in "
                   + _PL.shown(_PL.holdings_folder(root), root) + "/")
                + " until it has some")
        _die_input(f"{ctx}: account {name!r} has no inputs "
                   f"({_shown}/ "
                   + ("holds no export" if _in.is_dir() else "is missing")
                   + "): nothing to compare",
                   f"Its holdings are compared with the books `tjs "
                   f"run` builds from its exports. Save them in "
                   f"{_shown}/ and run `tjs run`, or {_how}.")

    def _warn_left_out() -> None:
        """Each account whose books cannot be read and that this check
        does not take in: one warning naming its work/ file. One it
        takes in never gets here: _account refuses it with an Error
        that says it all (backlog TJ-0631)."""
        for _a, _why in unreadable.items():
            _file, _, _reason = _why.partition(": ")
            _warn(f"could not read {_file} — {_a!r} is not in this check",
                  prog="tjs sanity",
                  details=[_reason, "Re-run `tjs run` to rebuild it."])

    def _resolved(name: str) -> Optional[Path]:
        """The file a holdings argument names, or None when it is not
        one: a symlink loop or an unreadable path is one clean line,
        never a traceback (audit A2-1392)."""
        try:
            p2 = Path(name).expanduser().resolve()
            if p2.is_file():
                return p2
            # The docs' `sanity ib=ib_positions.toml` run with -C from
            # another folder: the project's copy (workflow audit 2026-10).
            p3 = _project_file(root, name)
            return p3.resolve() if p3 is not None else None
        except (OSError, RuntimeError):
            return None

    def _file(name: str, ctx: str) -> Path:
        p2 = _resolved(name)
        if p2 is not None:
            return p2
        _die_input(f"{_mask_ids_in_path(ctx)}: "
                   f"{_mask_ids_in_path(name)!r} is not an existing "
                   f".toml file (or a symlink loop)",
                   "A relative FILE is looked for from the shell's folder, "
                   "then from the project's.")

    groups: Dict[Tuple[str, ...], Dict[str, Any]] = {}
    bare: Dict[str, Any] = {"accounts": [], "files": [], "paired": False}
    placed_accounts: Dict[str, str] = {}
    placed_files: Dict[Path, str] = {}

    def _place(group: Dict[str, Any], gname: str, acct: Optional[str],
               path: Optional[Path]) -> None:
        if acct is not None:
            owner = placed_accounts.get(acct)
            if owner is None:
                placed_accounts[acct] = gname
                group["accounts"].append(acct)
            elif owner == gname:
                # Summing a duplicate DOUBLED its positions and every
                # one showed as a 2x QTY_MISMATCH — while the header
                # printed the deduplicated list. Count once, say so.
                _sanity_note(f"account {acct!r} given more than once — "
                             f"counted once.")
            else:
                _die_input(f"account {acct!r} appears in "
                           f"more than one group ({owner} and {gname})")
        if path is not None:
            owner = placed_files.get(path)
            if owner is None:
                placed_files[path] = gname
                group["files"].append(path)
            elif owner == gname:
                _sanity_note(f"file {_mask_ids_in_path(path.name)} given "
                             f"more than once — counted once.")
            else:
                _die_input(f"file "
                           f"{_mask_ids_in_path(path.name)} appears in "
                           f"more than one group ({owner} and {gname})")

    items = list(args.items or [])
    config_groups: List[Tuple[List[str], List[str]]] = []
    config_notes: List[str] = []
    # Which notes are which (_sanity_items_from_config): the accounts
    # whose `holdings` setting was not checked, and the notes that leave
    # nothing unchecked.
    config_kinds: Dict[str, List[str]] = {}
    if not items:
        # No arguments: pairings come from taxjson.toml — each
        # account's `holdings = [...]`. Explicit arguments override
        # the config for that run.
        # Not swallowed: an unreadable taxjson.toml said "no account
        # declares `holdings`" and invited adding keys already there
        # (S049-08) — load_config names the TOML error instead.
        _scfg = load_config(root)
        _accts_cfg = _scfg.get("accounts") or {}
        # Every account of taxjson.toml is in this check: one whose books
        # cannot be read, or that has inputs and no books at all (its
        # run failed), is refused here — it dropped out of the coverage,
        # and "clean, complete" covered the others only (backlog
        # TJ-0307). Named, and refused, as when it is paired with a file
        # (_account).
        # (exit 2, an input that cannot be read: TJ-0353)
        _bad = [a for a in _accts_cfg if a in unreadable]
        if _bad:
            _die_input(f"{unreadable[_bad[0]]} — the books of {_bad[0]!r} "
                       f"cannot be read: re-run `tjs run` to rebuild "
                       f"them"
                       + (f" (also: {', '.join(_bad[1:])})"
                          if len(_bad) > 1 else "") + ".")
        _absent = [a for a in _accts_cfg if a not in resolved
                   and _has_inputs(root, a)]
        if _absent:
            _die_input(f"no gains file in work/ for account(s) "
                       f"{', '.join(_absent)}, whose inputs are there — "
                       f"the last `tjs run` did not build them (did it "
                       f"fail?): fix and re-run `tjs run`.")
        config_groups, config_notes = _sanity_items_from_config(
            _accts_cfg, root, (_scfg.get("settings") or {}).get("year"),
            kinds=config_kinds)
        if not config_groups:
            _warn_left_out()
            # A file holdings/ holds that is not read is named; alone it
            # leaves the accounts unchecked, as with no file (TJ-0424).
            _unread = list(config_kinds.get("unread") or ())
            for n in config_notes:
                _sanity_note(n)
            if [n for n in config_notes if n not in _unread]:
                # What the notes are about: an account's `holdings` paths
                # (fix the paths), or holdings/ snapshots no account
                # claims (claim them: no path is wrong; backlog TJ-0256).
                _n_paths = len(config_kinds.get("accounts") or ())
                _snaps = len(config_kinds.get("snapshots") or ())
                _hold = _PL.shown(_PL.holdings_folder(root), root)
                # Exit 2, not the verdict's 1: a named input missing or
                # one no account claims compared nothing; 1 stays
                # "positions differ" (docs/commands.md, Exit codes;
                # backlog TJ-0640, as TJ-0353 and TJ-0630 did).
                if _snaps and not _n_paths:
                    _die_input(f"none of the snapshots in {_hold}/ could "
                               f"be compared (see the notes above) — "
                               f"claim each for its account",
                               "Add the account's broker account id to "
                               "its [accounts.NAME] (`broker_accounts = "
                               "[\"...\"]`) and the same `broker_account` "
                               "to the file's [meta], name the file "
                               "NAME_holdings.toml, or list it in the "
                               "account's `holdings = [...]`.")
                _die_input("none of the `holdings` files "
                           "in taxjson.toml (or the holdings/ folder) "
                           "could be checked (see the notes above) — fix "
                           "the "
                           + ("paths." if not _snaps else
                              "paths, and claim each snapshot for its "
                              "account."))
            # Nothing to compare with is not an error: say which
            # accounts went unchecked, as when some have a file (the
            # checklist reads the UNCHECKED line; 2026-10 workflow
            # audit: docs/commands.md promised this, the command died).
            # Every account with open positions, a registered one too
            # (as the compare and the run count them); --json is a
            # document like the compare's (backlog TJ-0135).
            _unchk = sorted(a for a in tax if tax[a] and a in _accts_cfg)
            # The dividends paid on more shares than the books held: a
            # check of the books alone, run with no snapshot too (it was
            # skipped here: backlog TJ-0688). Informational, as below.
            _inc: List[Dict[str, Any]] = []
            for a in sorted(tax):
                if a in _accts_cfg:
                    _inc.extend(PC.income_share_mismatches(
                        PC.book_rows(cache, a), a, tol,
                        clock=_is_us(_soft_config(root))))
            if getattr(args, "json", False):
                _json_out({
                    "basis": basis, "accounts": [], "files": [],
                    "groups": [],
                    "cost": {"compared": 0, "matched": 0,
                             "not_compared": 0, "accounts_not_compared": [],
                             "tolerance": cost_tol, "rows": []},
                    "cost_differences": [], "income_share_mismatches": _inc,
                    "discrepancies": [], "uncovered_accounts": _unchk,
                    "accounts_not_checked": [], "notes": _unread,
                    "clean": True,
                    "complete": not _unchk and not _unread})
                return
            if _details(args) and _unchk:
                for a in _unchk:
                    print(f"  - account {a} not included "
                          f"({len(tax[a])} position(s) unchecked)")
                print()
            if _unchk:
                print(f"UNCHECKED: {len(_unchk)} account(s) with positions "
                      f"and no holdings file: " + ", ".join(_unchk[:3])
                      + (f" +{len(_unchk) - 3} more" if len(_unchk) > 3
                         else "")
                      + " — nothing to compare with")
            else:
                print("No account holds a position in the books, and no "
                      "holdings file — nothing to compare with.")
            print()
            _hold = _PL.holdings_folder(root)
            # README.txt only where it is: `init --single` makes no
            # holdings/ folder (TJ-0135).
            _how = ("; its README.txt says how"
                    if (_hold / "README.txt").is_file() else
                    ", named NAME_holdings.toml; the format: "
                    "docs/settings.md, Holdings TOML")
            for _ln in _out_wrap(
                    f"Put the broker's positions .toml in "
                    f"{_PL.shown(_hold, root)}/ (one per account{_how}; "
                    f"its RBC Holdings Export or IB statement, named "
                    f"NAME_holdings.csv, is read too), "
                    f"or pass one: `tjs sanity margin=positions.toml` "
                    f"(docs/commands.md, sanity)."):
                print(_ln)
            _sanity_print_extras([], [], [], 0, 0, _inc, True,
                                 brief=getattr(args, "brief_extras", False),
                                 concise=not _details(args))
            return
    for accts, paths in config_groups:
        key = tuple(accts)
        gname = "+".join(key)
        grp = groups.setdefault(key, {"accounts": [], "files": [],
                                      "paired": True})
        for n in key:
            _place(grp, gname, _account(n, "taxjson.toml"), None)
        for f in paths:
            _place(grp, gname, None, _file(f, "taxjson.toml"))
    for a in items:
        if "=" in a and not Path(a).expanduser().is_file():
            lhs, rhs = a.split("=", 1)
            names = [x for x in lhs.split("+") if x.strip()]
            paths = [x for x in rhs.split("+") if x.strip()]
            if not names or not paths:
                _die_input(f"{a!r}: paired form is "
                           f"ACCOUNT[+ACCOUNT...]=FILE[+FILE...]")
            key = tuple(sorted(dict.fromkeys(
                _account(n.strip(), a) for n in names)))
            gname = "+".join(key)
            grp = groups.setdefault(
                key, {"accounts": [], "files": [], "paired": True})
            for n in key:
                _place(grp, gname, n, None)
            for f in paths:
                _place(grp, gname, None, _file(f.strip(), a))
            continue
        if a in tax or a in unreadable or a in _declared():
            # An account whose books cannot be read, or that has none
            # (TJ-0639), is refused as such (_account), never as
            # "neither an account nor a file".
            _place(bare, "the aggregate group", _account(a, a), None)
            continue
        p2 = _resolved(a)
        if p2 is not None:
            _place(bare, "the aggregate group", None, p2)
            continue
        _die_input(f"{_mask_ids_in_path(a)!r} is neither "
                   f"an account "
                   f"(have: {', '.join(sorted(tax))}) nor an existing "
                   f".toml file")
    if bare["accounts"] or bare["files"]:
        if not (bare["accounts"] and bare["files"]):
            _die_input("the aggregate form needs at least "
                       "one ACCOUNT and one FILE.toml (free mix, e.g. "
                       "`tjs sanity margin rrsp margin.toml "
                       "rrsp.toml`), or pair them: "
                       "`margin=margin.toml+margin-2.toml`")
    ordered: List[Dict[str, Any]] = list(groups.values())
    if bare["accounts"]:
        ordered.append(bare)
    if not ordered:
        _die_input("nothing to check")
    _warn_left_out()

    # Same consolidation the canonical pipeline applied: GLOBAL+TOBASE
    # renames from the map the books were merged with — the run's
    # effective map (ticker.map plus the listings it joined by their
    # transfer journal, lib/cross_listings) when it wrote one, else
    # ticker.map; options follow their underlying.
    renames: Optional[Dict[str, str]] = None
    native_renames: Optional[Dict[str, str]] = None
    distinct: Set[frozenset] = set()
    map_symbol = None
    from taxjson.lib.cross_listings import EFFECTIVE_MAP as _EFF_MAP
    map_file = root / "work" / _EFF_MAP
    if not map_file.is_file():
        map_file = _PL.ticker_map_path(root)
    if map_file.exists():
        try:
            from taxjson.bin.taxjson_ticker_map import (load_map_file,
                                                        map_symbol,
                                                        merge_renames)
            _tmap = load_map_file(map_file)
            renames = merge_renames(_tmap, to_base=True)
            native_renames = merge_renames(_tmap, to_base=False)
            # The pairs ticker.map declares DISTINCT: two securities,
            # never one spelled two ways (_sanity_spellings).
            distinct = set(_tmap.distinct or ())
        except Exception as e:
            from taxjson.lib.out import warn as _warn
            _warn(f"ticker.map not applied ({e}) — cross-listed symbols "
                  f"may mismatch.", prog="tjs sanity")
            renames = None

    def _mapped(sym: str) -> str:
        if renames is not None and map_symbol is not None:
            return map_symbol(sym, renames)
        return sym

    def _native_mapped(sym: str) -> str:
        if native_renames is not None and map_symbol is not None:
            return map_symbol(sym, native_renames)
        return sym

    _OPT_RE = re.compile(r'^((?:F:)?[A-Z0-9.]+?)(\d{6}[CP]\d+)\.(\S+)$',
                         re.IGNORECASE)
    _VENUE_SFX_RE = re.compile(r'^([A-Za-z0-9]+)\.[A-Za-z]{2,3}$')

    def _ext_book(paths: List[Path]) -> Tuple[Dict[str, float],
                                              List[str],
                                              Dict[str, str]]:
        """(book, file labels, alt) — `alt` maps an option's symbol
        as the FILE spells it to the same contract keyed by the
        row's `underlying` root. Brokers and tools disagree on the
        option ROOT: IB names a Montréal contract on a class share ABC.B
        `ABC.B 17DEC27 30 C` (taxjson keys ABC.B271217C00030000.TO)
        while a positions export keys it by the exchange option
        root `ABC...` — same contract, and the export's `underlying
        = "ABC.B.TO"` field says so. The compare below falls back to
        the underlying spelling only when the file's spelling has no
        taxjson counterpart, so a real mismatch still shows."""
        book: Dict[str, float] = {}
        labels: List[str] = []
        alt: Dict[str, str] = {}
        for path in paths:
            if path.suffix.lower() != ".toml":
                # A broker's own positions report (CSV): read by
                # lib/positions_reports, one reader per broker export.
                try:
                    rep_ = read_positions(path)
                except PositionsReportError as e:
                    _die_input(str(e))
                reports_of[path] = rep_
                labels.append(", ".join(rep_.accounts) or path.stem)
                for r in rep_.rows:
                    if r.asset_type == "cash" or abs(r.quantity) <= 1e-12:
                        continue
                    tgt = _mapped(r.symbol)
                    book[tgt] = book.get(tgt, 0.0) + r.quantity
                continue
            # The same file through the positions reader, for its cost
            # columns (the quantity checks below stay the authority).
            try:
                reports_of[path] = read_positions(path)
            except (PositionsDateError, PositionsSnapshotError) as e:
                # An impossible date (an `acquired` of 2024-13-01) is
                # refused, as `tjs opening` refuses it: never a note.
                # So is a file that is not a whole snapshot: a
                # holdings_count that is not its number of tables, a
                # contract size that is no positive number. The quantities below
                # never check those, and a cut-short file compared "OK"
                # with the positions it lost unseen (audit 2026-10-25
                # brokers-inputs#1).
                _die_input(str(e))
            except PositionsReportError as e:
                reports_of[path] = None
                _unread_cost[path] = str(e)
            # A broker/position file re-saved with a BOM was refused
            # (re-audit A2-1409, A2-1453); unreadable is exit 2 (A2-0164).
            try:
                doc = tomllib.loads(path.read_text(encoding="utf-8-sig"))
            except Exception as e:
                _die_input(f"cannot parse {path}: {e}")
            meta = doc.get("meta") if isinstance(doc, dict) else None
            _toml_meta[path] = meta if isinstance(meta, dict) else {}
            # Its date picks the books it is compared with: an
            # impossible one (2025-02-30) is refused, never read as
            # "no date"; a cost the reader refused leaves the date.
            try:
                _toml_day[path] = toml_as_of(meta, shown_name(path))
            except PositionsReportError as e:
                _die_input(str(e))
            labels.append(str((meta or {}).get("account") or path.stem)
                          if isinstance(meta, (dict, type(None)))
                          else path.stem)
            holdings = doc.get("holding") if isinstance(doc, dict) else None
            from taxjson.lib.holdings_dir import empty_snapshot
            if holdings is None and empty_snapshot(doc):
                holdings = []       # the account holds nothing (#46)
            # A file it cannot read as a snapshot is an input that cannot
            # be read: exit 2, named from the project (docs/commands.md;
            # exit 1 stays "positions differ", backlog TJ-0643).
            _named = _mask_ids_in_path(_out_relpath(path, root))
            if not isinstance(holdings, list):
                _die_input(f"{_named} has no [[holding]] "
                           f"array (a holdings file has [[holding]] tables)")
            for h in holdings:
                if not isinstance(h, dict):
                    _die_input(f"{_named}: a [[holding]] "
                               f"entry is not a table")
                if (str(h.get("asset_type") or "")).lower() == "cash":
                    continue
                sym = str(h.get("symbol") or "").strip()
                _qraw = h.get("quantity")
                if _qraw is None or (isinstance(_qraw, str)
                                     and not _qraw.strip()):
                    # A missing or blank quantity read as 0 and the row
                    # vanished: sanity said OK and the checklist ticked
                    # the step (S044-18).
                    _die_input(f"{_named}: "
                               f"{sym or '?'}: a [[holding]] row has no "
                               f"quantity — fix the file (an unreadable "
                               f"row is never skipped).")
                try:
                    # A TOML boolean is not a quantity (`true` read as 1,
                    # re-audit A2-1230).
                    if isinstance(_qraw, bool):
                        raise TypeError("bool")
                    q = float(_qraw)
                except (TypeError, ValueError):
                    _die_input(f"{_named}: {sym or '?'}: "
                               f"quantity {h.get('quantity')!r} is not a "
                               f"number")
                if q != q or q in (float("inf"), float("-inf")):
                    _die_input(f"{_named}: {sym or '?'}: "
                               f"quantity is not finite")
                if not sym and abs(q) > 1e-12:
                    _cus = str(h.get("cusip") or h.get("isin")
                               or "").strip()
                    _die_input(f"{_named}: a [[holding]] "
                               f"row has quantity {q:g} but no symbol"
                               + (f" ({_cus})" if _cus else "")
                               + " — it cannot be compared; fix the file.")
                if not sym or abs(q) <= 1e-12:
                    continue
                if (str(h.get("asset_type") or "").lower() == "crypto"
                        and _VENUE_SFX_RE.match(sym)):
                    # A snapshot tool's venue suffix (e.g.
                    # `COIN.KR` for Kraken): taxjson keys crypto by the
                    # bare coin, so every coin showed twice, MISSING on
                    # each side (R1-113, R1-334).
                    sym = _VENUE_SFX_RE.match(sym).group(1)
                tgt = _mapped(sym)
                book[tgt] = book.get(tgt, 0.0) + q
                und = str(h.get("underlying") or "").strip()
                m = _OPT_RE.match(sym)
                if und and m and "." in und:
                    und_root, und_ext = _mapped(und).rsplit(".", 1)
                    via = f"{und_root}{m.group(2)}.{und_ext}"
                    if via != tgt:
                        alt[tgt] = via
        return book, labels, alt

    # ---- compare, per group ------------------------------------------------
    # Positions can NET to zero across accounts (or vs the files' sum);
    # only keep true residues.
    all_rows: List[Dict[str, Any]] = []
    reports_of: Dict[Path, Any] = {}
    # (a holdings TOML's [meta] table and date, and the reader's error
    # for one whose rows it refused: its cost is then not compared)
    _toml_meta: Dict[Path, Dict[str, Any]] = {}
    _toml_day: Dict[Path, str] = {}
    _unread_cost: Dict[Path, str] = {}
    base_rows: Dict[str, List[Dict[str, Any]]] = {}

    # (the year's holdings/ snapshots: dated by generated_at too —
    # lib/holdings_dir)
    _snap_dirs = {_PL.holdings_folder(root).resolve()}

    def _rows_of(acct: str) -> List[Dict[str, Any]]:
        if acct not in base_rows:
            # (with the missing-history openings the books hold:
            # units bought before the data — PC.book_rows). Books that
            # are there but cannot be read are not an empty history:
            # read as one, a dated snapshot was compared with the
            # latest books and certified (audit 2026-10-24 B18).
            try:
                base_rows[acct] = PC.book_rows(cache, acct, strict=True)
            except PC.BaseBookError as e:
                # (exit 2, an input that cannot be read: TJ-0353)
                _die_input(f"the books of {acct!r} cannot be read ({e}) — "
                           f"re-run `tjs run` to rebuild them")
        return base_rows[acct]

    def _file_day(_p: Path) -> str:
        """The day a file's positions are for ("" when it states none):
        a broker report's date; a holdings TOML's explicit [meta]
        as_of — a holdings/ snapshot's the day of its generated_at too
        (lib/holdings_dir)."""
        _rp = reports_of.get(_p)
        _day = _rp.as_of if _rp is not None else _toml_day.get(_p, "")
        if not _day:
            return ""
        if (_p.suffix.lower() == ".toml" and _p.parent not in _snap_dirs
                and not (_toml_meta.get(_p) or {}).get("as_of")):
            return ""
        return _day

    def _file_broker(_p: Path, accts: List[str]) -> str:
        """The broker account a file's positions are of, as the file
        states it ("" when it names none, or only a taxjson account's
        name): a holdings TOML's [meta] broker_account, else its
        account (as lib/holdings_dir claims it); a broker report's
        account keys."""
        if _p.suffix.lower() == ".toml":
            _meta = _toml_meta.get(_p) or {}
            for _k in ("broker_account", "account"):
                _v = str(_meta.get(_k) or "").strip()
                if _v and _v.lower() not in {a.lower() for a in accts}:
                    return re.sub(r"[^A-Za-z0-9]", "", _v).upper()
            return ""
        _rp = reports_of.get(_p)
        if _rp is None:
            return ""
        return "+".join(sorted({(r.account_key or r.account)
                                for r in _rp.rows
                                if r.account_key or r.account})
                        or _rp.accounts)

    # The project's country and account types (read once): the costs
    # need them, and the books' positions on a past day are replayed in
    # the engine's order (positions_on: the US engine takes a split by
    # its clock time). A config the quantity check never needed must not
    # stop it. With no country the costs are not compared (never a
    # silent Canada).
    try:
        _pcfg = (load_config(root) if _PL.has_config(root)
                 else {})
    except SystemExit:
        _pcfg = {}
    _cfg_accts = _pcfg.get("accounts") or {}
    _settings = _pcfg.get("settings") or {}
    try:
        _ctry = _country(_settings) if _settings else None
    except SystemExit:
        _ctry = None
    from taxjson.lib.country import CANADA as _CANADA, is_usa as _is_usa
    _clock = bool(_ctry) and _is_usa(_ctry)

    expanded: List[Dict[str, Any]] = []
    for grp in ordered:
        # Each file is read once. A group's files are summed — one
        # taxjson account across several broker accounts — unless they
        # are several snapshots of the SAME broker account(s) at
        # different dates: two observations of one position are never
        # a sum (a January 10 and a February 20 compared as 30 against
        # the current 20; audit 2026-10-24 B17). Those are compared one
        # date at a time, each against the books on its day.
        parsed = {_p: _ext_book([_p]) for _p in grp["files"]}
        days = {_p: _file_day(_p) for _p in grp["files"]}
        brokers = {_p: _file_broker(_p, grp["accounts"])
                   for _p in grp["files"]}
        _by_broker: Dict[str, Set[str]] = {}
        for _p in grp["files"]:
            if brokers[_p]:
                _by_broker.setdefault(brokers[_p], set()).add(days[_p])
        _repeated = sorted(b for b, ds in _by_broker.items() if len(ds) > 1)
        # A dated file beside an undated one: the undated one is read as
        # the latest books', so the two are of different days once the
        # books moved after the dated one — 10 on June 30 plus 5 now was
        # compared with the 15 of today and certified clean, without a
        # word (backlog TJ-0257).
        _dset = set(days.values())
        _end_g = (PC.last_day([r for a in grp["accounts"]
                               for r in _rows_of(a)])
                  if "" in _dset and len(_dset) > 1 else "")
        _undated_apart = bool(_end_g) and any(d and d < _end_g
                                              for d in _dset)
        units: List[List[Path]] = [list(grp["files"])]
        if _repeated:
            _udays = sorted({days[_p] for _p in grp["files"]})
            _at = {d: {brokers[_p] for _p in grp["files"] if days[_p] == d}
                   for d in _udays}
            _named = ", ".join(_mask_ids_in_path(_p.name)
                               for _p in grp["files"]
                               if brokers[_p] in _repeated)
            if ("" in _udays or any(s != set(_by_broker) for s in _at.values())):
                # Snapshots of one broker account at several dates
                # beside files that are not at each of those dates:
                # neither a sum nor a per-date compare is a complete
                # observation. A date with every broker account's
                # snapshot is one, checked in a run of its own: a
                # repeated ACCOUNT= merges into one group, so the
                # advice to pair each date in a group of its own could
                # not be followed (backlog TJ-0065).
                _acct = "+".join(grp["accounts"])
                _whole = [d for d in _udays
                          if d and _at[d] == set(_by_broker)]
                _one = ""
                if _whole:

                    def _rel(_p: Path) -> str:
                        try:
                            return str(_p.relative_to(root))
                        except ValueError:
                            return str(_p)
                    _one = (f" Or compare one date's files in a run of "
                            f"their own: `tjs sanity {_acct}="
                            + "+".join(_mask_ids_in_path(_rel(_p))
                                       for _p in grp["files"]
                                       if days[_p] == _whole[-1])
                            + f"` ({_whole[-1]}): a repeated `{_acct}=` "
                            f"merges into one group, so each date needs "
                            f"a run of its own.")
                _die(f"{_acct}: {_named} are snapshots "
                     f"of one broker account at different dates "
                     f"({', '.join(d or 'undated' for d in _udays)}), "
                     f"beside other files of the group",
                     "Their sum is no snapshot of one day, and the other "
                     "files are not at each of those dates. Keep one "
                     "snapshot per broker account (the year-end ones)."
                     + _one)
            units = [[_p for _p in grp["files"] if days[_p] == d]
                     for d in _udays]
            _sanity_note(f"{'+'.join(grp['accounts'])}: {len(units)} "
                         f"snapshots of the same broker account(s) "
                         f"({', '.join(_udays)}): each is compared with "
                         f"the books on its own day, never summed.")
        elif ((len({d for d in days.values() if d}) > 1 or _undated_apart)
              and any(not brokers[_p] for _p in grp["files"])):
            # Files of one group at different dates, not every one
            # naming its broker account: one broker account at two
            # dates (compared one date at a time) cannot be told from
            # two broker accounts of one taxjson account (summed), and
            # either guess gives a false verdict for the other — a sum
            # of two dates said MISSING_IN_TAXJSON for a correct pair
            # (audit 2026-10-25 first-project#2). Refused, naming the
            # files and the key that tells them apart.
            _unnamed = [_p for _p in grp["files"] if not brokers[_p]]
            _die_input(
                f"{'+'.join(grp['accounts'])}: "
                + ", ".join(f"{_mask_ids_in_path(_p.name)} "
                            f"({days[_p] or 'undated'})"
                            for _p in grp["files"])
                + f" are dated differently and "
                f"{'none' if len(_unnamed) == len(grp['files']) else 'not every one'}"
                f" names its broker account",
                "One broker account's snapshots at several dates are "
                "compared one date at a time; different broker accounts' "
                "are summed. Without each file's broker account the two "
                "cannot be told apart, and a sum of two dates is no "
                "snapshot."
                + (f" An undated file is read as of the books' last day "
                   f"({_end_g})." if _undated_apart else ""),
                "Add `broker_account = \"...\"` (the broker's account "
                "number) to the [meta] of "
                + ", ".join(_mask_ids_in_path(_p.name) for _p in _unnamed)
                + "; or keep one snapshot per broker account (the year-end "
                "one); or check one file at a time: `tjs sanity "
                "ACCOUNT=FILE`.")
        for _files in units:
            sub = grp if len(units) == 1 else dict(grp, files=_files)
            ext_book: Dict[str, float] = {}
            file_labels: List[str] = []
            alt: Dict[str, str] = {}
            for _p in _files:
                _b, _l, _a = parsed[_p]
                for sym, q in _b.items():
                    ext_book[sym] = ext_book.get(sym, 0.0) + q
                file_labels.extend(_l)
                alt.update(_a)
            tax_book: Dict[str, float] = {}
            for acct in sub["accounts"]:
                for sym, q in tax[acct].items():
                    tax_book[sym] = tax_book.get(sym, 0.0) + q
            # A broker report dated before the books' last row is
            # compared with the books' positions ON its date (rebuilt
            # from the account's rows); a holdings TOML only with an
            # explicit [meta] as_of. One date for the group, else the
            # latest books.
            sub["as_of"] = ""
            _dates = {days[_p] for _p in _files}
            _grows = [r for a in sub["accounts"] for r in _rows_of(a)]
            _books_end = PC.last_day(_grows)
            _one_day = (next(iter(_dates)) if len(_dates) == 1
                        and "" not in _dates else "")
            # (the files' one date, also when it is after the group's
            # own books end: the pooled cost may have moved since,
            # backlog TJ-0817)
            sub["file_day"] = _one_day
            if _one_day and _books_end and _one_day < _books_end:
                sub["as_of"] = _one_day
                tax_book = PC.positions_on(_grows, sub["as_of"],
                                           clock=_clock)
            elif (_one_day and _books_end and _one_day > _books_end
                  and any(_p.parent in _snap_dirs for _p in _files)):
                _sanity_note(f"{'+'.join(sub['accounts'])}: the snapshot "
                             f"is dated {_one_day}, after the books' "
                             f"last day {_books_end}: compared with the "
                             f"latest books.")
            elif _one_day and not _grows and not any(
                    (cache / f"{a}_base.json").exists()
                    for a in sub["accounts"]):
                # No rows to rebuild the day's positions from: said,
                # never a silent compare with the latest books.
                _sanity_note(f"{'+'.join(sub['accounts'])}: the file is "
                             f"dated {_one_day}, and the books' rows "
                             f"(work/<account>_base.json) are missing: "
                             f"compared with the latest books — "
                             f"`tjs run` writes them.")
            _ds = sorted(d for d in _dates if d)
            # (an undated file beside a dated one is of the books' last
            # day: two dates too, backlog TJ-0257)
            if ((len(_ds) > 1 or (_ds and "" in _dates)) and _books_end
                    and _ds[0] < _books_end):
                # Different broker accounts' snapshots at different
                # dates are summed (one taxjson account across brokers)
                # and compared with the latest books: the books cannot
                # say which broker account a later trade was in. Said
                # when the books moved after the earliest date, so a
                # difference there is read as one (backlog TJ-0066).
                _early = PC.positions_on(_grows, _ds[0], clock=_clock)
                _late = PC.positions_on(_grows, _books_end, clock=_clock)
                _moved = sorted(s for s in set(_early) | set(_late)
                                if abs(_early.get(s, 0.0)
                                       - _late.get(s, 0.0)) > tol)
                if _moved:
                    # (the point before the first clause break: the
                    # default view's one line, TJ-0160)
                    _sanity_note(
                        f"{'+'.join(sub['accounts'])}: "
                        f"{', '.join(_moved[:3])}"
                        + (f" +{len(_moved) - 3} more" if len(_moved) > 3
                           else "")
                        + f" changed after {_ds[0]}, the date of "
                        + ", ".join(_mask_ids_in_path(_p.name)
                                    for _p in _files if days[_p] == _ds[0])
                        + ": compared with the latest books — "
                        "snapshots of different broker accounts at "
                        "different dates ("
                        + ", ".join(f"{_mask_ids_in_path(_p.name)} "
                                    f"{days[_p] or 'undated'}"
                                    for _p in _files)
                        + ") are summed (the books cannot tell which "
                        "broker account a trade was in), so a difference "
                        "there may be that change; keep each broker "
                        "account's snapshot of one date (the year end).")
            via_underlying: List[Tuple[str, str]] = []
            for sym, via in alt.items():
                if sym in ext_book and sym not in tax_book \
                        and via in tax_book:
                    ext_book[via] = ext_book.get(via, 0.0) + ext_book.pop(sym)
                    via_underlying.append((sym, via))
            sub["via_underlying"] = via_underlying
            # An s.86.1 spin-off's fraction the books hold on the
            # snapshot's date until its cash in lieu is paid after it:
            # the broker shows the whole shares only (backlog TJ-0149).
            _await = (PC.fractions_awaiting_cash(_grows, sub["as_of"])
                      if sub["as_of"] else {})
            sub["awaiting_cash"] = []
            rows: List[Dict[str, Any]] = []
            for sym in sorted(set(tax_book) | set(ext_book)):
                tq = tax_book.get(sym, 0.0)
                eq = ext_book.get(sym, 0.0)
                if abs(tq - eq) <= tol:
                    continue
                _fr = _await.get(sym) or []
                _pend = sum(f["quantity"] for f in _fr)
                if _fr and abs(tq - _pend - eq) <= tol:
                    sub["awaiting_cash"].append(
                        {"symbol": sym, "taxjson_qty": tq,
                         "holdings_qty": eq, "fractions": _fr})
                    continue
                issue = ("MISSING_IN_TAXJSON" if abs(tq) <= tol
                         else "MISSING_IN_HOLDINGS" if abs(eq) <= tol
                         else "QTY_MISMATCH")
                rows.append({"symbol": sym, "issue": issue,
                             "taxjson_qty": tq, "holdings_qty": eq,
                             "accounts": sorted(sub["accounts"])})
            sub["rows"] = rows
            sub["labels"] = file_labels
            sub["positions"] = len(tax_book)
            all_rows.extend(rows)
            expanded.append(sub)
    ordered = expanded
    # ---- costs (never a failing exit; lib/positions_check) ----------------
    _base_cur = str(_settings.get("base_currency") or "").upper() or (
        _home_currency(_settings) if _ctry else "")
    _taxable = {a for a, c in _cfg_accts.items()
                if (c or {}).get("type") == "taxable"}
    _own_inv: Dict[str, Dict[str, Dict[str, Any]]] = {}
    _nat_inv: Dict[str, Dict[str, Dict[str, Any]]] = {}
    _fil_inv: Dict[str, Dict[str, Dict[str, Any]]] = {}
    for acct, f in resolved.items():
        _fil_inv[acct] = PC.load_inventory(f)
        _own_inv[acct] = PC.load_inventory(cache / f"{acct}_gains.json")
        _nat_inv[acct] = PC.load_inventory(cache / f"{acct}_raw_gains.json")
    cost_all: List[Dict[str, Any]] = []
    income_all: List[Dict[str, Any]] = []
    # Cost is compared for taxable accounts only: a registered account's
    # broker book cost is not a tax cost (an in-kind transfer in resets
    # it to the market value; none is reported) — Canada's RRSP/TFSA...
    # and the US IRA/401(k)/HSA alike (type = "sheltered"). Its
    # quantities are compared as every account's are.
    cost_skipped: List[str] = []
    for grp in ordered if _ctry else ():
        qty_bad = {r["symbol"] for r in grp["rows"]}
        ext_cost: Dict[str, Dict[str, Any]] = {}
        _shel = sorted(a for a in grp["accounts"]
                       if (_cfg_accts.get(a) or {}).get("type")
                       == "sheltered")
        if _shel:
            cost_skipped.extend(_shel)
        # An option the quantity check matched by its underlying (the
        # file's root spelling of the books' contract): its cost is the
        # books' contract's too (backlog TJ-0813).
        _via = dict(grp.get("via_underlying") or ())
        for _p in (grp["files"] if not _shel else ()):
            _rp = reports_of.get(_p)
            if _rp is None:
                continue
            for r in _rp.rows:
                if r.asset_type == "cash" or abs(r.quantity) <= 1e-12:
                    continue
                k = _mapped(r.symbol)
                _nk = _native_mapped(r.symbol)
                if k in _via:
                    k = _nk = _via[k]
                e = ext_cost.setdefault(k, {
                    "cost": 0.0, "currencies": set(), "kinds": set(),
                    "missing": False, "pos_cur": r.currency or "",
                    "native": _nk, "qty": 0.0})
                e["qty"] += r.quantity
                if r.cost is None or not r.cost_kind:
                    e["missing"] = True
                    continue
                e["cost"] += float(r.cost)
                e["currencies"].add((r.cost_currency or r.currency
                                     or "").upper())
                e["kinds"].add(r.cost_kind)
        _grows = [r for a in grp["accounts"] for r in _rows_of(a)]
        _after = (PC.touched_after(_grows, grp["as_of"])
                  if grp["as_of"] else set())
        # Canada: the filing cost is the s.47 average over every taxable
        # account, read from the LATEST books — another account's trade
        # after the report's date moved it, so it is not that day's
        # cost, even when this account's own books end before that date
        # (backlog TJ-0817). {symbol: the first such account}.
        _pool_after: Dict[str, str] = {}
        _fday = grp.get("as_of") or grp.get("file_day") or ""
        if _fday and _ctry == _CANADA:
            for _oa in sorted(_taxable - set(grp["accounts"])):
                for _s in PC.touched_after(PC.book_rows(cache, _oa),
                                           _fday):
                    # (in the books' spelling after ticker.map, as the
                    # report's symbols are compared)
                    _pool_after.setdefault(_mapped(_s), _oa)
        _roc = PC.roc_symbols(_grows)
        _spin = PC.spinoff_symbols(_grows)
        crow_list: List[Dict[str, Any]] = []
        for sym in sorted(ext_cost):
            e = ext_cost[sym]
            if sym in qty_bad or abs(e["qty"]) <= tol:
                continue
            base_row = {"symbol": sym, "accounts": sorted(grp["accounts"]),
                        "quantity": e["qty"]}
            if e["missing"] or len(e["currencies"]) != 1:
                cost_all.append(dict(base_row, status="n/a",
                                     note=("the report states no cost"
                                           if e["missing"] else
                                           "costs in several currencies")))
                continue
            if sym in _after:
                cost_all.append(dict(base_row, status="n/a",
                                     note=f"the books changed after the "
                                          f"report's date {grp['as_of']}"))
                continue
            if sym in _pool_after:
                cost_all.append(dict(base_row, status="n/a",
                                     note=f"the pooled ACB changed after "
                                          f"the report's date "
                                          f"{_fday} (account "
                                          f"{_pool_after[sym]} traded it)"))
                continue

            def _sum(inv, key):
                hit = [inv[a][key] for a in grp["accounts"]
                       if key in inv.get(a, {})]
                if not hit:
                    return None
                return {"total_cost": sum(h["total_cost"] for h in hit),
                        "deferred_wash": sum(h["deferred_wash"]
                                             for h in hit),
                        "currency": hit[0].get("currency") or "",
                        "qty": sum(h["qty"] for h in hit),
                        "unknown_cost": any(h.get("unknown_cost")
                                            for h in hit)}
            _own = _sum(_own_inv, sym)
            _pooled = any(sym in _fil_inv.get(a, {})
                          for a in _taxable - set(grp["accounts"]))
            res = PC.compare_cost(
                symbol=sym, broker_cost=e["cost"],
                cost_currency=next(iter(e["currencies"])),
                cost_kind=sorted(e["kinds"])[0],
                position_currency=e["pos_cur"], base=_base_cur,
                country=_ctry, filing=_sum(_fil_inv, sym),
                own=(_own or {}).get("total_cost"),
                native=_sum(_nat_inv, e["native"]),
                pooled=_pooled, roc=sym in _roc, tol_abs=cost_tol,
                tol_rel=0.001, short=e["qty"] < 0,
                spinoff=sym in _spin)
            cost_all.append(dict(base_row, **res))
        for a in grp["accounts"]:
            income_all.extend(PC.income_share_mismatches(_rows_of(a), a,
                                                         tol, clock=_clock))
    if cost_skipped:
        _sanity_note(f"cost not compared for registered accounts "
                     f"({', '.join(sorted(set(cost_skipped)))}): book cost "
                     f"there is not tax cost (quantities are compared).")
    for _p, _err in _unread_cost.items():
        # A malformed cost field: the quantities are still compared,
        # at the file's own date; the cost is not (never silently). The
        # point and its reason before the first clause break: the
        # default view's one line is the part before it, which was the
        # file and row alone (backlog TJ-0160).
        _where, _brk, _why = _err.rpartition("): ")
        _sanity_note(f"{_where}) cost is not compared: {_why} — its "
                     f"quantities are." if _brk else
                     f"{_err} — its cost is not compared (quantities "
                     f"are).")
    cost_diffs = [c for c in cost_all if c.get("status") == "differs"]
    cost_matched = sum(1 for c in cost_all if c.get("status") == "match")
    cost_na = sum(1 for c in cost_all if c.get("status") == "n/a")

    accounts = sorted(placed_accounts)
    files: List[Path] = [p2 for g in ordered for p2 in g["files"]]
    file_labels = [lbl for g in ordered for lbl in g["labels"]]
    uncovered = sorted(a for a in tax
                       if a not in placed_accounts and tax[a])
    # The notes that leave something unchecked: an account's `holdings`
    # setting that could not be read, a holdings/ snapshot no account
    # (or two) claims. A snapshot of an account whose own setting names
    # its files leaves nothing unchecked: that account is compared with
    # those (backlog TJ-0020).
    _info_notes = set(config_kinds.get("info") or ())
    open_notes = [n for n in config_notes if n not in _info_notes]
    cfg_unchecked = list(config_kinds.get("accounts") or ())

    if getattr(args, "json", False):
        _json_out({
            "basis": basis,
            "accounts": accounts,
            # The [meta] account label may be a broker account id:
            # masked like the text listing (S044-16).
            "files": [{"file": _mask_ids_in_path(str(p2)),
                       "file_account": _mask_ids_in_path(lbl)}
                      for p2, lbl in zip(files, file_labels)],
            "groups": [{"accounts": sorted(g["accounts"]),
                        "paired": g["paired"],
                        "files": [_mask_ids_in_path(str(p2))
                                  for p2 in g["files"]],
                        "matched_via_underlying": [
                            {"file_symbol": a, "taxjson_symbol": b}
                            for a, b in g["via_underlying"]],
                        "fractions_awaiting_cash_in_lieu":
                            g.get("awaiting_cash") or [],
                        "discrepancies": g["rows"],
                        "as_of": g["as_of"] or None,
                        "clean": not g["rows"]}
                       for g in ordered],
            # Costs and income share counts (lib/positions_check):
            # informational, never part of `clean` or the exit code.
            "cost": {"compared": cost_matched + len(cost_diffs),
                     "matched": cost_matched,
                     "not_compared": cost_na,
                     # (registered accounts: book cost is not tax cost)
                     "accounts_not_compared": sorted(set(cost_skipped)),
                     "tolerance": cost_tol,
                     "rows": cost_all},
            "cost_differences": cost_diffs,
            "income_share_mismatches": income_all,
            "discrepancies": all_rows,
            "uncovered_accounts": uncovered,
            # (the accounts whose `holdings` setting was not checked —
            # each named in notes — open positions or not)
            "accounts_not_checked": cfg_unchecked,
            "notes": config_notes,
            "clean": not all_rows,
            # False when an account's CONFIGURED holdings file could
            # not be read (R1-324), a holdings/ snapshot was not
            # compared, or — in the config form — an account with open
            # positions has no holdings file at all (S044-19): its
            # positions were never compared, so "clean" covers the
            # other groups only.
            "complete": not open_notes and not (uncovered
                                                and not items),
        })
        raise SystemExit(0 if not all_rows else 1)

    from taxjson.lib.out import kv_lines as _kv, wrap as _wrap
    from taxjson.lib.out import act as _act
    # Essentials first (docs/output-style.md): --details adds the
    # explanations, the cost/income tables and the not-compared list.
    _det = _details(args)
    for n in config_notes:
        _sanity_note(n)
    multi = len(ordered) > 1 or any(g["paired"] for g in ordered)
    _what = ("external holdings TOML"
             if all(p2.suffix.lower() == ".toml"
                    for g in ordered for p2 in g["files"])
             else "the broker's positions")
    for ln in _wrap(f"SANITY — taxjson positions (basis: {basis}) vs "
                    f"{_what} ({'paired' if multi else 'loose aggregate'} "
                    f"check)", None, "", "  "):
        print(ln)
    for grp in ordered:
        print()
        tag = ("paired" if grp["paired"] else "aggregate") if multi else ""
        pairs = [("accounts", f"{', '.join(sorted(grp['accounts']))}  "
                              f"({grp['positions']} combined position(s))"
                              + (f"  [{tag}]" if tag else ""))]
        if grp["as_of"]:
            pairs.append(("as of", f"{grp['as_of']} — the report's date; "
                                   f"the books' positions on that day "
                                   f"(rebuilt from "
                                   f"work/<account>_base.json)" if _det
                          else f"{grp['as_of']} (the report's date)"))
        # One line per file, PATH first: the label alone (the file's
        # meta.account, else its stem) didn't say which export was
        # actually read — a stale or wrong path is the first thing to
        # rule out when a group disagrees.
        for p2, lbl in zip(grp["files"], grp["labels"]):
            shown = str(p2)
            try:
                # Inside the project: relative to it (lib/out.relpath).
                shown = str(p2.resolve().relative_to(root))
            except (ValueError, OSError):
                try:
                    shown = "~/" + str(p2.relative_to(Path.home()))
                except ValueError:
                    pass
            # A holdings file named after the broker account put the
            # real account number on the console (R1-351): the file
            # name's ids are masked like the IB warning masks them.
            shown = _mask_ids_in_path(shown)
            extra = (f"  (account {_mask_ids_in_path(lbl)})"
                     if lbl not in p2.stem else "")
            pairs.append(("file", f"{shown}{extra}"))
        for a, b in grp["via_underlying"]:
            pairs.append(("option", f"{a} matched taxjson's {b} via its "
                                    f"underlying (same contract, "
                                    f"different option root)"))
        for _a in grp.get("awaiting_cash") or ():
            _f = _a["fractions"][0]
            _more = _a["taxjson_qty"] - _a["holdings_qty"]
            _what = ("a merger's fraction (received"
                     if _f.get("event") == "merger"
                     else "a spin-off's fraction (s.86.1, received")
            pairs.append(("fraction", f"{_a['symbol']}: {_more:g} more in "
                                      f"the books, {_what} {_f['received']}) "
                                      f"sold for its cash in lieu on "
                                      f"{_f['paid']}, after this date — "
                                      f"not a difference"))
        if multi:
            pairs.append(("result", f"{len(grp['rows'])} discrepancy(ies)"
                                    if grp["rows"] else "OK"))
        for ln in _kv(pairs, "  "):
            print(ln)
    if uncovered and _det:
        print()
        for a in uncovered:
            print(f"  - account {a} not included "
                  f"({len(tax[a])} position(s) unchecked)")
    elif uncovered and items:
        # (with no items the UNCHECKED line below names them)
        print()
        _unc = [f"{a} ({len(tax[a])})" for a in uncovered]
        print("Not compared (no holdings file given): "
              + ", ".join(_unc[:4])
              + (f" +{len(_unc) - 4} more" if len(_unc) > 4 else ""))
    print()
    if uncovered and not items:
        # The checklist's sanity step reads this line: "done" while
        # whole accounts were never tied was a false certificate
        # (S044-19).
        _named = list(uncovered)
        print(f"UNCHECKED: {len(uncovered)} account(s) with positions and "
              f"no holdings file: " + ", ".join(_named[:3])
              + (f" +{len(_named) - 3} more" if len(_named) > 3 else "")
              + ("" if _det else " — tjs sanity --details"))
    if open_notes:
        # A configured holdings file that could not be read drops its
        # whole account from the compare: never let that read as a
        # clean check (the checklist and run's auto-sanity key on this
        # line — 2026-09 audit R1-324). It counts what the notes say
        # (a holdings/ snapshot is not a path in taxjson.toml: backlog
        # TJ-0020).
        _nunread = len(config_kinds.get("unread") or ())
        _nsnap = len(open_notes) - len(cfg_unchecked) - _nunread
        _hshown = _PL.shown(_PL.holdings_folder(root), root)
        print("INCOMPLETE: " + "; ".join(
            ([f"{len(cfg_unchecked)} account(s) with `holdings` in "
              f"taxjson.toml not checked"] if cfg_unchecked else [])
            + ([f"{_nsnap} snapshot(s) in {_hshown}/ not compared"]
               if _nsnap > 0 else [])
            + ([f"{_nunread} file(s) in {_hshown}/ not read"]
               if _nunread else []))
              + " (the notes on stderr): fix "
              + ("them" if _nsnap > 0 or _nunread else "the paths")
              + ", then re-run")
    if not all_rows:
        print("OK: tickers and quantities agree"
              + (" in every checked group." if open_notes
                 else " in every group." if multi else "."))
    else:
        if (uncovered and not items) or open_notes:
            print()
        # The legend, before the table (Essentials first).
        print("ISSUE: MISSING_IN_HOLDINGS = not in the broker's file; "
              "MISSING_IN_TAXJSON = not in the books.")
        out_lines = [("ACCOUNTS SYMBOL ISSUE TAXJSON HOLDINGS DIFF"
                      if multi else
                      "SYMBOL ISSUE TAXJSON HOLDINGS DIFF")]
        for r in all_rows:
            # Both quantities at one precision (0.7552 beside 0.75
            # read as two scales).
            _dec = max(len((f"{v:g}".split(".") + [""])[1])
                       for v in (r["taxjson_qty"], r["holdings_qty"]))
            _dec = min(_dec, 8)
            cells = [r["symbol"], r["issue"],
                     f"{r['taxjson_qty']:.{_dec}f}",
                     f"{r['holdings_qty']:.{_dec}f}",
                     f"{r['taxjson_qty'] - r['holdings_qty']:+g}"]
            if multi:
                cells.insert(0, "+".join(r["accounts"]))
            out_lines.append(" ".join(cells))
        _print_report_table(out_lines, fit=True, key=(0, 1) if multi
                            else 0)
        _fewer = any(r["holdings_qty"] - r["taxjson_qty"] > 0
                     for r in all_rows)
        if not _det:
            print()
            # One `! ` line per kind of difference, each naming the fix
            # that works for it: find-missing-history sees a position
            # the books hold short, never one bought before the data or
            # typed under another spelling (backlog TJ-0423).
            for _text, _cmd in _sanity_pointers(root, all_rows,
                                                distinct=distinct):
                print(_act(_text, _cmd))
        else:
            print(f"\n{len(all_rows)} discrepancy(ies).")
        if _fewer and _det:
            # Fewer shares in the books than at the broker: on a first
            # project that is history the download does not reach
            # (new-user study), not a booking bug.
            for ln in _wrap(
                    "Fewer shares in taxjson than at the broker usually "
                    "means missing history: purchases from before your "
                    "download starts, or shares transferred in. See "
                    "`tjs find-missing-history`, `tjs transfers` "
                    "and docs/getting-started.md step 5. A trade after "
                    "your last export is the other usual cause."):
                print(ln)
    _sanity_print_extras(ordered, cost_all, cost_diffs, cost_matched,
                         cost_na, income_all, multi,
                         brief=getattr(args, "brief_extras", False),
                         concise=not _det)
    raise SystemExit(0 if not all_rows else 1)


# What `tjs opening` writes into a .tt line from a positions
# report's cells (security review M2): anything else is skipped, named.
_OPENING_SYMBOL_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:/+-]*\Z")
_OPENING_CURRENCY_RE = re.compile(r"[A-Z]{3}\Z")


def _opening_iso_day(v: str) -> bool:
    if not re.match(r"\d{4}-\d{2}-\d{2}\Z", v or ""):
        return False
    try:
        datetime.strptime(v, "%Y-%m-%d")
    except ValueError:
        return False
    return True


def _opening_padded_day(v: str) -> Optional[str]:
    """`2025-1-1` written as a .tt line takes it (2025-01-01); None when
    `v` is no real day in any spelling (2025-02-30, 1/1/2025)."""
    m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", (v or "").strip())
    if not m:
        return None
    day = f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}"
    return day if _opening_iso_day(day) else None


def _opening_lines(report, *, country: str, base_currency: str,
                   snapshot: str, mult: Optional[Dict[str, float]] = None):
    """(OPENING .tt lines, [skipped (symbol, reason)], [notes]) for one
    positions report's rows (lib/positions_reports). Long positions
    with a stated cost only: a short (a written option, a short sale)
    depends on its write; a row without a cost is never written at a
    market value (CA-OPEN-01). A US project needs each lot's own
    purchase date and a US-dollar cost (US-OPEN-01/02).

    An option whose contract size is not 100 (a mini) is written with
    it (`x<size>`) only when the project's ticker.map declares that size
    (`mult`: its MULT lines, {SYMBOL or root: size}): the exercise and
    assignment rows of the option carry no size of their own, and its
    premium is spread over the units each contract delivers. Without
    the line it is skipped, naming the line to add (backlog TJ-0963)."""
    from decimal import Decimal
    from taxjson.lib.core import is_option_symbol
    from taxjson.lib.positions_reports import COST_LOTS
    lines: List[str] = []
    skipped: List[Tuple[str, str]] = []
    notes: List[str] = []
    usa = country == "usa"
    lots_kind = False
    for r in sorted(report.rows, key=lambda x: (x.symbol, x.lot_date)):
        # Written raw into the .tt line: a newline or a space in the
        # symbol would book whatever follows as its own line (security
        # review M2). Named escaped in the skip list.
        safe_sym = bool(_OPENING_SYMBOL_RE.match(r.symbol or ""))
        sym = r.symbol if safe_sym else ascii(r.symbol)
        q = float(r.quantity or 0.0)
        if abs(q) < 1e-12:
            continue
        if r.asset_type in ("cash",):
            continue
        if q < 0:
            skipped.append((sym, "a short position (its premium or "
                                 "proceeds depend on the write: enter "
                                 "the write as a BUYSELL line)"))
            continue
        if r.asset_type == "future" \
                or (r.symbol or "").startswith(("F:", "/", "\\")):
            skipped.append((sym, "a futures contract (booked on its own "
                                 "basis: enter the opening trade as a "
                                 "BUYSELL line)"))
            continue
        # A holdings file's cost in the project's base currency at the
        # acquisition dates (taxjson-export's base_total_cost) is the
        # tax cost itself: kept as stated, never the native cost
        # converted again at the snapshot day's rate (backlog TJ-0990).
        base_known = (getattr(r, "base_cost", None) is not None
                      and str(getattr(r, "base_currency", "") or "")
                      .upper() == base_currency.upper())
        if not base_known and (r.cost is None or not r.cost_kind):
            skipped.append((sym, "the report states no cost for it (a "
                                 "market value is never a cost) — write "
                                 "its line by hand from a statement "
                                 "with book cost"))
            continue
        cost = float(r.base_cost if base_known else r.cost)
        if cost < 0:
            skipped.append((sym, f"a negative cost {cost:,.2f}"))
            continue
        cur = (base_currency.upper() if base_known
               else (r.cost_currency or r.currency or "").upper())
        if not cur:
            skipped.append((sym, "no currency for its cost"))
            continue
        if not _OPENING_CURRENCY_RE.match(cur):
            skipped.append((sym, f"its currency {ascii(cur)} is not a "
                                 f"3-letter code"))
            continue
        lot = r.lot_date or ""
        if lot and not _opening_iso_day(lot):
            skipped.append((sym, f"its lot date {ascii(lot)} is not a "
                                 f"YYYY-MM-DD date"))
            continue
        if usa:
            if not lot:
                skipped.append((sym, "no purchase date: a US opening is "
                                     "one line per lot with its own date "
                                     "(US-OPEN-01) — list the lots in a "
                                     "holdings TOML (`acquired = ...`) "
                                     "or write the lines by hand"))
                continue
            if cur != base_currency.upper():
                skipped.append((sym, f"its cost is in {cur}: a US lot's "
                                     f"basis is its {base_currency} cost "
                                     f"on its purchase date (US-OPEN-02)"))
                continue
        if lot and lot > snapshot:
            skipped.append((sym, f"its lot date {lot} is after the "
                                 f"snapshot date {snapshot}"))
            continue
        if not safe_sym:
            skipped.append((sym, "not a symbol a .tt line can carry "
                                 "(letters, digits and ._:/+- only)"))
            continue
        if r.cost_kind == COST_LOTS:
            lots_kind = True
        # The exact quantity, no exponent: a rounded one (8 significant
        # digits) would leave a residue at the closing sale.
        qtext = format(Decimal(repr(q)), "f")
        if "." in qtext:
            qtext = qtext.rstrip("0").rstrip(".")
        # An option's contract size other than 100 rides on the line
        # (`x<size>`, as a BUYSELL line's) once ticker.map declares it:
        # the units its exercise delivers, which spread its cost
        # (backlog TJ-0963).
        size = ""
        if is_option_symbol(sym) and r.multiplier \
                and float(r.multiplier) not in (0.0, 100.0):
            from taxjson.bin.taxjson_convert_tt import size_text
            from taxjson.lib.core import parse_option_underlying
            from taxjson.lib.markets import strip_listing_suffix
            m = float(r.multiplier)
            # The run's lookup (markets.option_contract_size): the
            # contract, the class share, the root, the underlying as
            # written (backlog TJ-1200).
            o_und = parse_option_underlying(sym) or ""
            o_share = strip_listing_suffix(o_und)
            said = next((float((mult or {})[k]) for k in (
                sym.upper(), o_share.upper(),
                o_und.split(".", 1)[0].upper(), o_und.upper())
                         if k and k in (mult or {})), None)
            if said is None or abs(said - m) > 1e-9:
                skipped.append((sym, f"a contract size of {size_text(m)} "
                                     f"(not 100): add `MULT "
                                     f"{o_share or sym} {size_text(m)}` to "
                                     f"ticker.map (each exercise or "
                                     f"assignment of it delivers "
                                     f"{size_text(m)} units a contract), "
                                     f"then run `tjs opening` again"))
                continue
            size = f" x{size_text(m)}"
        lines.append(f"OPENING {snapshot} {sym} {qtext} {cur} "
                     f"{cost:.2f}" + (f" {lot}" if lot else "") + size)
    if lots_kind and not usa:
        notes.append("the report's cost is the broker's LOT basis (each "
                     "lot at its own price, sales matched by the broker's "
                     "lot method); Canadian ACB is the average cost of "
                     "all identical shares (s.47). They differ when part "
                     "of a position was sold before the snapshot — check "
                     "those with `tjs sanity` once the books are "
                     "built.")
    return lines, skipped, notes


def cmd_opening(args: argparse.Namespace) -> None:
    """`tjs opening ACCOUNT FILE [--date D] [--dry-run] [--force]`:
    turn a broker's positions report (lib/positions_reports: an IB
    Activity Statement's Open Positions, an RBC Holdings Export, a
    `[[holding]]` TOML) into an opening balance —
    inputs/<ACCOUNT>/opening_<date>.tt with one OPENING line per long
    position (per lot with its date in a US project). The snapshot then
    replaces the account's earlier rows of those symbols
    (lib/opening; tax-logic CA-OPEN-01..03 / US-OPEN-01..03)."""
    from taxjson.lib.brokerages.base import shown_name
    from taxjson.lib.out import note as _note, warn as _warn, wrap as _wrap
    from taxjson.lib.positions_reports import (PositionsReportError,
                                               kind_label, read_positions)
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    settings = cfg.get("settings") or {}
    country = _country(settings)
    base = str(settings.get("base_currency") or "").upper() \
        or _home_currency(settings)
    accounts = cfg.get("accounts") or {}
    name = args.account
    if name not in accounts:
        _die(f"{name!r} is not an account in taxjson.toml",
             f"Accounts: {', '.join(sorted(accounts)) or '-'}.")
    if (accounts.get(name) or {}).get("crypto"):
        _die(f"account {name} is a crypto account",
             "An opening balance is for share accounts: enter the coins' "
             "purchases as BUYSELL lines.")
    path = Path(args.file).expanduser()
    if not path.is_file():
        path = _project_file(root, args.file) or path
    if not path.is_file():
        _die_input(f"{_mask_ids_in_path(str(path))} is not a file",
                   "A relative FILE is looked for from the shell's folder, "
                   "then from the project's.")
    try:
        report = read_positions(path)
    except PositionsReportError as e:
        _die_input(str(e))
    snapshot = args.date or report.as_of
    if not snapshot:
        _die(f"{shown_name(path)} does not say which day its positions "
             f"are for",
             "Pass --date YYYY-MM-DD (the statement's date).")
    if not _opening_iso_day(snapshot):
        # The padded form the .tt reader takes (taxjson-convert-tt
        # _check_date): strptime let `--date 2025-1-1` through, and
        # the opening_2025-1-1.tt written stopped the next run
        # (backlog TJ-0317).
        _padded = _opening_padded_day(snapshot)
        _die(f"{'--date' if args.date else shown_name(path) + ': the date'}"
             f" {snapshot!r} is not a YYYY-MM-DD date",
             (f"Write it {_padded}" if _padded else
              "Give the statement's day as YYYY-MM-DD (e.g. 2025-01-31)")
             + (" (--date)." if args.date else
                ", or pass --date YYYY-MM-DD."))
    if args.date and report.as_of and args.date != report.as_of:
        _note(f"the report is as of {report.as_of}; the opening is dated "
              f"{args.date} as given (--date).", prog="tjs opening")
    # Counted by each row's key of the whole account id: the masked
    # label (two characters + ***) is the same for two ids that share
    # their first two characters. A consolidated IB statement's rows
    # carry no one account's key (one position for all its accounts
    # combined).
    by_key: Dict[str, str] = {}
    for r in report.rows:
        k = r.account_key or r.account
        if k:
            by_key.setdefault(k, r.account)
    brokers = sorted(by_key.values())
    if len(brokers) > 1:
        alike = (" — ids that differ after the two characters shown"
                 if len(set(brokers)) < len(brokers) else "")
        _die(f"{shown_name(path)} lists {len(brokers)} broker accounts "
             f"({', '.join(brokers)}{alike})",
             "An opening is one taxjson account's: export each broker "
             "account's positions separately (or split the file).")
    # The contract sizes ticker.map declares (MULT lines): a mini
    # option's opening needs its own (backlog TJ-0963).
    _mult: Dict[str, float] = {}
    _tmp = _PL.ticker_map_path(root)
    if _tmp.is_file():
        from taxjson.lib.ticker_map import read_side_rules
        try:
            _mult = dict(read_side_rules(_tmp).mult)
        except Exception:                           # noqa: BLE001
            _mult = {}
    lines, skipped, notes = _opening_lines(report, country=country,
                                           base_currency=base,
                                           snapshot=snapshot, mult=_mult)
    acct_dir = _PL.inputs_dir(root) / name
    out = acct_dir / f"opening_{snapshot}.tt"
    # Another opening file of this account for the same symbols would
    # count them twice (two .tt files are two records — never deduped).
    from taxjson.bin.taxjson_convert_tt import strip_tt_comment, tt_lines
    # Compared as the books spell them: the merge stages map both
    # openings through the project's ticker.map (GLOBAL, TOBASE), where
    # same-day OPENING rows add up (lots) — an earlier OPENING of
    # SYN.A.TO under GLOBAL SYN.A.TO SYN.TO and a new SYN.TO snapshot
    # counted the shares twice (backlog TJ-0825, TJ-0814).
    _bmap: Dict[str, str] = {}
    try:
        from taxjson.lib.missing_history import declaration_maps
        _bmap = declaration_maps(root).base
    except Exception:                               # noqa: BLE001
        _bmap = {}      # a map the run refuses: the run names it

    def _booked(sym: str) -> str:
        sym = sym.upper()
        if not _bmap:
            return sym
        from taxjson.lib.missing_history import map_symbol_through
        try:
            return str(map_symbol_through(sym, _bmap)).upper()
        except Exception:                           # noqa: BLE001
            return sym
    syms = {_booked(ln.split()[2]) for ln in lines}
    clash = []
    # Every .tt the run reads (input_files: the suffix in any case — a
    # START.TT too).
    for f in input_files(acct_dir, ".tt"):
        if f.resolve() == out.resolve():
            continue
        try:
            text = f.read_text(encoding="utf-8-sig")
        except (OSError, UnicodeDecodeError):
            continue
        for ln in tt_lines(text):
            parts = strip_tt_comment(ln).split()
            if len(parts) >= 3 and parts[0] == "OPENING" \
                    and _booked(parts[2]) in syms:
                _was = parts[2].upper()
                _as = _booked(_was)
                clash.append((f.name, _was if _as == _was else
                              f"{_was} (the books' {_as})"))
    if clash:
        _die(f"{_PL.shown(acct_dir / clash[0][0], root)} already has "
             f"OPENING lines for "
             f"{', '.join(sorted({s for _f, s in clash})[:6])}",
             "One opening per symbol per account (the spellings "
             "ticker.map joins are one symbol): remove that file, or "
             "the lines, first.")
    header = [
        f"# Opening balance of account {name} on {snapshot} "
        f"(`tjs opening`).",
        # A control character of the file name or an account cell (a
        # newline) would end the comment and book the rest as a line
        # (security review L3).
        re.sub(r"[\x00-\x1f\x7f]", "?",
               f"# From: {_mask_ids_in_path(shown_name(path))} — "
               f"{kind_label(report.kind)}"
               + (f", accounts {', '.join(report.accounts)}"
                  if report.accounts else "") + "."),
        "# An OPENING line sets a position and its cost; it is not a "
        "purchase (tax-logic",
        "# CA-OPEN-01 / US-OPEN-01). The account's rows of these symbols "
        "dated on or",
        "# before the snapshot day are left out of the books "
        "(CA-OPEN-03 / US-OPEN-03).",
        "#       snapshot    symbol  qty  currency  total-cost  "
        "[lot-date]",
    ]
    text = "\n".join(header + lines) + "\n"
    # Each line read back as the run reads it, before anything is
    # written: a file the next run refuses is never published (TJ-0317).
    from taxjson.bin.taxjson_convert_tt import parse_tt_line
    for _i, _ln in enumerate(lines, len(header) + 1):
        try:
            parse_tt_line(_ln, name, source=f"{out.name}:{_i}")
        except ValueError as e:
            _die(f"an OPENING line would not read back: {e}",
                 "Nothing written: fix that position's row in the "
                 "report (or leave it out), then `tjs opening` "
                 "again.")
    if getattr(args, "dry_run", False):
        sys.stdout.write(text)
    elif not lines:
        pass
    else:
        if out.exists() and not args.force:
            _die(f"{_PL.shown(out, root)} exists",
                 f"Pass --force to replace it (the old file is kept as "
                 f"{out.name}.bak, or the next free .bakN).")
        acct_dir.mkdir(parents=True, exist_ok=True)
        # A .tt file is the user's: written as every user-file writer
        # writes one (lib/safe_write.write_user_file) — a read-only file
        # or a link leaving the project (the folder holding the year
        # folders, with shared inputs) is refused, a link inside it
        # keeps pointing at its target, which is replaced; the previous
        # contents are kept as the next free .bak/.bakN (security review
        # M1). It used to be replaced like a generated file: a read-only
        # file rewritten, a link replaced by a file (backlog TJ-0586).
        from taxjson.lib.cli_diag import cannot_write
        from taxjson.lib.safe_write import OutsideLinkError, write_user_file
        _shown_out = _PL.shown(out, root)
        try:
            bak = write_user_file(out, text, _PL.write_boundary(root))
        except OutsideLinkError as e:
            _die_input(str(e), "Nothing was written.")
        except OSError as e:
            _head, _fix = cannot_write(_shown_out, e, out)
            _die_input(_head, " ".join(x for x in (_fix, "Nothing was "
                                                         "written.") if x))
        if bak is not None:
            _note(f"kept the previous {out.name} as {bak.name}",
                  prog="tjs opening")
        _shared_inputs_note(root, out, "tjs opening")
    for n in report.notes + notes:
        _note(n, prog="tjs opening")
    for sym, why in skipped:
        _warn(f"skipped {sym}: {why}", prog="tjs opening")
    if not lines:
        _die(f"no position of {shown_name(path)} could be written (see "
             f"above) — nothing written")
    where = ("(dry run — nothing written)" if getattr(args, "dry_run",
                                                       False)
             else f"-> {_PL.shown(out, root)}")
    for ln in _wrap(f"{len(lines)} OPENING line(s) for account {name} as "
                    f"of {snapshot} {where}"
                    + (f"; {len(skipped)} position(s) skipped (see above)"
                       if skipped else "")):
        print(ln)
    if not getattr(args, "dry_run", False):
        for ln in _wrap("Next: `tjs run`, then `tjs "
                        "find-missing-history` and `tjs sanity` (it "
                        "compares quantities and costs)."):
            print(ln)


def _sanity_spellings(rows: List[Dict[str, Any]],
                      distinct: Iterable[frozenset] = ()
                      ) -> List[Tuple[Dict[str, Any], Dict[str, Any]]]:
    """(row, row) pairs of sanity differences that are one security
    spelled two ways: a symbol the books lack (MISSING_IN_TAXJSON) and
    one the holdings lack (MISSING_IN_HOLDINGS) of the same accounts,
    the same root before the exchange suffix (ZZB / ZZB.TO) and the same
    quantity — never a pair ticker.map declares DISTINCT (`distinct`:
    frozenset pairs, TickerMap.distinct): two securities, whose
    differences stay missing and extra holdings (backlog TJ-0836)."""
    def root_(s: str) -> str:
        return str(s or "").split(".", 1)[0].upper()
    apart = {frozenset(str(x).upper() for x in pair) for pair in distinct}
    out = []
    used: set = set()
    for a in rows:
        if a["issue"] != "MISSING_IN_TAXJSON":
            continue
        for b in rows:
            if (id(b) in used or b["issue"] != "MISSING_IN_HOLDINGS"
                    or b["accounts"] != a["accounts"]
                    or root_(b["symbol"]) != root_(a["symbol"])
                    or frozenset((str(a["symbol"]).upper(),
                                  str(b["symbol"]).upper())) in apart
                    or abs(b["taxjson_qty"] - a["holdings_qty"])
                    > 1e-6 * max(1.0, abs(a["holdings_qty"]))):
                continue
            used.add(id(b))
            out.append((a, b))
            break
    return out


def _sanity_pointers(root: Path, rows: List[Dict[str, Any]],
                     distinct: Iterable[frozenset] = ()
                     ) -> List[Tuple[str, str]]:
    """The `! ` lines closing `tjs sanity`'s table: (text, command)
    per kind of difference, each naming the fix that works for it
    (docs/getting-started.md, step 5b) — a symbol spelled two ways (the
    books' symbol, `tjs list`), shares transferred in with no cost
    (`tjs transfers`, from reports/run_summary.json), a position the
    books hold short (a sale with no purchase: `tjs find-missing-
    history`), one symbol more in one account and as many fewer in
    another (booked in the wrong account), fewer shares in the books and none short (bought before
    the data: an opening balance, `tjs opening`; find-missing-history
    sees nothing there and said "No missing-cost-basis issues found",
    backlog TJ-0423), more shares in the books (`tjs audit`)."""
    def names(rs: List[Dict[str, Any]]) -> str:
        syms = list(dict.fromkeys(r["symbol"] for r in rs))
        return ", ".join(syms[:2]) + (f" +{len(syms) - 2} more"
                                      if len(syms) > 2 else "")
    spelled = _sanity_spellings(rows, distinct)
    paired = {id(x) for pair in spelled for x in pair}
    no_cost: set = set()
    try:
        from taxjson.lib.first_run import SUMMARY_FILE
        import json as _json
        _doc = _json.loads((root / "reports" / SUMMARY_FILE)
                           .read_text(encoding="utf-8"))
        no_cost = {(str(i.get("symbol")), str(i.get("account")))
                   for i in _doc.get("transfer_in_no_cost") or []}
    except (OSError, ValueError, AttributeError, TypeError):
        pass
    # One symbol more in one account's books and as many fewer in
    # another's: booked in the wrong account (an export in the wrong
    # inputs/<account>/ folder), not missing history.
    moved: List[Dict[str, Any]] = []
    for a in rows:
        if id(a) in paired:
            continue
        for b in rows:
            if (b is a or id(b) in paired or b["symbol"] != a["symbol"]
                    or b["accounts"] == a["accounts"]):
                continue
            da = a["taxjson_qty"] - a["holdings_qty"]
            db = b["taxjson_qty"] - b["holdings_qty"]
            if da > 0 > db and abs(da + db) <= 1e-6 * max(1.0, da):
                paired |= {id(a), id(b)}
                moved += [a, b]
                break
    transfer, short, before, more = [], [], [], []
    for r in rows:
        if id(r) in paired:
            continue
        if r["holdings_qty"] - r["taxjson_qty"] <= 0:
            more.append(r)
        elif any((r["symbol"], a) in no_cost for a in r["accounts"]):
            transfer.append(r)
        elif r["taxjson_qty"] < 0:
            short.append(r)
        else:
            before.append(r)
    # (head, the symbols, tail, command): the symbols are left out of a
    # line that would pass the 100 columns of an `! ` line.
    kinds: List[Tuple[str, str, str, str]] = []
    if spelled:
        a, b = spelled[0]
        kinds.append((f"{len(spelled)} symbol spelling",
                      f"{a['symbol']} / {b['symbol']}"
                      + (f" +{len(spelled) - 1} more" if len(spelled) > 1
                         else ""),
                      ": use the books' symbol in the holdings file",
                      "tjs list"))
    if moved:
        kinds.append((f"{len(moved) // 2} booked in another account",
                      names(moved), ": check the export's folder",
                      "tjs audit SYMBOL"))
    if transfer:
        kinds.append((f"{len(transfer)} transferred in with no cost",
                      names(transfer), ", kept out of the books",
                      "tjs transfers"))
    if short:
        kinds.append((f"{len(short)} short in the books", names(short),
                      ": a sale with no purchase in your files",
                      "tjs find-missing-history"))
    if before:
        accts = sorted({a for r in before for a in r["accounts"]})
        kinds.append((f"{len(before)} with fewer shares",
                      names(before), ": bought before your data, step 5b",
                      f"tjs opening "
                      f"{accts[0] if len(accts) == 1 else 'ACCOUNT'} FILE"))
    if more:
        kinds.append((f"{len(more)} more in the books", names(more),
                      ": a trade after your last export, or a booking "
                      "problem", "tjs audit SYMBOL"))
    from taxjson.lib.out import act as _act_line
    out: List[Tuple[str, str]] = []
    for head, syms, tail, cmd in kinds:
        text = f"{head} ({syms}){tail}"
        if len(_act_line(text, cmd)) > 100:
            text = f"{head}{tail}"
        out.append((text, cmd))
    return out


def _sanity_print_extras(groups, cost_all, cost_diffs, cost_matched,
                         cost_na, income_all, multi,
                         brief: bool = False,
                         concise: bool = False) -> None:
    """The COST and INCOME sections of `tjs sanity` (after the
    quantity check, never changing its exit code). `brief` (the check
    `tjs run` ends with): one line each, the tables are
    `tjs sanity`'s."""
    from taxjson.lib.positions_check import REASON_TEXT
    from taxjson.lib.out import wrap as _wrap

    def _p(text: str, indent: str = "", hang: str = "  ") -> None:
        # Wrapped at the house width; captured (the checklist reads the
        # last line) it stays one line, as before.
        for ln in _wrap(text, None, indent, hang):
            print(ln)
    compared = cost_matched + len(cost_diffs)
    if brief:
        if cost_diffs:
            _p(f"COST: {len(cost_diffs)} of {compared} position(s) "
               f"differ from the reports' cost "
               f"({sum(1 for c in cost_diffs if c['reasons'] == ['unexplained'])}"
               f" unexplained) — `tjs sanity` lists them with "
               f"their reasons (informational).")
        if income_all:
            _p(f"INCOME: {len(income_all)} dividend row(s) state a "
               f"share count the books did not hold — `tjs "
               f"sanity` lists them.")
        return
    if concise:
        # The default view (Essentials first): one line each,
        # informational; --details has the tables and the reasons.
        if cost_diffs:
            print()
            print(f"COST: {len(cost_diffs)} of {compared} differ from the "
                  f"broker's book value (informational) — tjs sanity "
                  f"--details")
        if income_all:
            print()
            print(f"INCOME: {len(income_all)} dividend row(s) state shares "
                  f"the books did not hold — tjs sanity --details")
        return
    if compared or cost_na:
        print()
        _p(f"COST — books vs the reports' cost: {compared} compared, "
           f"{cost_matched} within tolerance, {len(cost_diffs)} "
           f"differ" + (f", {cost_na} not compared" if cost_na else "")
           + " (informational: a broker's book value is not your "
             "ACB/basis; never changes the exit code).")
    if cost_diffs:
        lines = [("ACCOUNTS " if multi else "")
                 + "SYMBOL QTY CUR BROKER BOOKS DIFF REASON"]
        for c in cost_diffs:
            cells = [c["symbol"], f"{c['quantity']:g}", c["cost_currency"]
                     or "-", f"{c['broker_cost']:,.2f}",
                     f"{c['books_cost']:,.2f}", f"{c['diff']:+,.2f}",
                     ",".join(c["reasons"])
                     + ("" if c.get("explained") or
                        c["reasons"] == ["unexplained"] else "?")]
            if multi:
                cells.insert(0, "+".join(c["accounts"]))
            lines.append(" ".join(x.replace(" ", "_") if i < len(cells) - 1
                                  else x for i, x in enumerate(cells)))
        print()
        _print_report_table(lines, fit=True, drop=(len(lines[0].split())
                                                    - 1,),
                            key=(0, 1) if multi else 0)
        print()
        used = sorted({r for c in cost_diffs for r in c["reasons"]})
        print("Reasons" + (" (a ? = a possible cause, not checked to "
                           "close the gap):"
                           if any(not c.get("explained")
                                  and c["reasons"] != ["unexplained"]
                                  for c in cost_diffs) else ":"))
        for r in used:
            _p(f"{r}: {REASON_TEXT.get(r, r)}", "  ", "    ")
        natives = sorted({c["basis"] for c in cost_diffs
                          if c.get("basis", "").startswith("native")})
        for b in natives:
            _p(f"BOOKS here is the {b}.", "  ", "    ")
    na = [c for c in cost_all if c.get("status") == "n/a"]
    if na:
        _p("Not compared: " + "; ".join(
            f"{c['symbol']} ({c.get('note') or 'n/a'})" for c in na[:8])
            + (f"; +{len(na) - 8} more" if len(na) > 8 else ""))
    if income_all:
        from taxjson.lib.positions_check import (
            INCOME_WINDOW_DAYS as _INCOME_WINDOW_DAYS)
        print()
        _p(f"INCOME ON SHARES THE BOOKS DO NOT HOLD — {len(income_all)} "
           f"dividend row(s) state more shares than the books held when "
           f"it was earned (on the record date; without one, at any "
           f"time in the {_INCOME_WINDOW_DAYS} days to the pay date) — "
           f"missing history or a missing trade is the usual cause; "
           f"informational:")
        lines = ["ACCOUNT SYMBOL PAID ON STATED BOOKS"]
        for m in income_all:
            lines.append(f"{m['account']} {m['symbol']} {m['date']} "
                         f"{m['on']}_({m['basis'].replace(' ', '_')}) "
                         f"{m['stated_shares']:g} {m['books_shares']:g}")
        # The old layout on purpose: the checklist's sanity step shows
        # the output's last line, which is this table's last row.
        _print_report_table(lines)


def _list_positional_date(args: argparse.Namespace) -> None:
    """`tjs list [ACCOUNT] [YYYY-MM-DD]`: a positional YYYY-MM-DD is
    the date (as --date), anything else the account — `list margin
    2026-04-28` and `list 2026-04-28` both work. Sets args.account and
    args.date; two dates, two accounts or a date that differs from
    --date stop with the usage."""
    given = [v for v in (getattr(args, "account", None),
                         getattr(args, "when", None)) if v]
    dates = [v for v in given if _ISO_DATE_RE.match(v)]
    accounts = [v for v in given if not _ISO_DATE_RE.match(v)]
    if len(dates) > 1 or len(accounts) > 1:
        _die(f"list takes one account and one date: got "
             f"{' '.join(given)}",
             "Usage: tjs list [ACCOUNT] [YYYY-MM-DD]")
    if dates:
        if getattr(args, "date", None) and args.date != dates[0]:
            _die(f"two dates: {dates[0]} and --date {args.date}",
                 "Give the date once.")
        args.date = dates[0]
    args.account = accounts[0] if accounts else None
    args.when = None


def _dated_inventory(cache: Path, acct: str, gains: Path, as_of: str,
                     acfg: Dict[str, Any], us: bool
                     ) -> Tuple[Dict[str, Any], str]:
    """`acct`'s positions at the end of `as_of` (the gains file's
    {"inventory", "summary"} shape) and the date basis they are on: the
    engine's own pools that day, from the cost timeline its canonical
    gains pass wrote (`gains`, the file plain `list` reads; timeline_beside,
    lib/cost_timeline; backlog TJ-0417). A blended pass's pools (Canada's
    s.47 pool across the taxable accounts) are apportioned by the
    account's own units that day, as taxjson-split-gains apportions them
    at the books' end; the US engine's lots are the account's own."""
    from types import SimpleNamespace
    from taxjson.lib import cost_timeline as CT
    from taxjson.lib.pipeline import declared_multipliers
    doc = _load_json_or_die(gains)
    split = bool((doc.get("metadata") or {}).get("split_from"))
    combined = (cache / (".cryptoblend_gains_wash.json" if acfg.get("crypto")
                         else ".blend_gains_wash.json")
                if split else gains)
    tl_path = timeline_beside(combined)
    if not tl_path.exists():
        _die(f"no cost timeline for {acct} (work/{tl_path.name})",
             "Run `tjs run`: it writes the positions per day with the "
             "gains.")
    tl = _load_json_or_die(tl_path)
    problem = CT.check(tl)
    if problem:
        # A damaged sidecar is an input that cannot be read: exit 2
        # (docs/commands.md's exit codes; backlog TJ-0684).
        _die_input(f"work/{tl_path.name}: {problem}",
                   "Run `tjs run` to rebuild it.")
    basis = str(tl.get("basis") or "settle")
    rows = CT.inventory_on(tl, as_of, eps=CT.us_eps if us else None)
    # A short beside a long, at its own proceeds (backlog TJ-1104).
    rows += CT.short_rows_on(tl, as_of)
    base_p = cache / f"{acct}_base.json"
    book = (list(_load_json_or_die(base_p).get("transactions") or [])
            if base_p.exists() else [])
    if split:
        from taxjson.bin.taxjson_split_gains import (
            _missing_history_openings, _position_starts, _split_inventory)
        from taxjson.lib.positions_check import (blended_pool_rows,
                                                 pool_splits,
                                                 without_pool_cut)
        _pool = blended_pool_rows(cache, acct)
        book = without_pool_cut(book, _pool, acct)
        book += _missing_history_openings(_load_json_or_die(combined), acct)
        # The splits another account of the pool reports: the engine
        # split this account's shares too (backlog TJ-0696).
        book += pool_splits(_pool, acct)
        dk = "date_settle" if basis == "settle" else "date"
        upto = [r for r in book
                if str(r.get(dk) or r.get("date") or "")[:10] <= as_of]
        inv = _split_inventory(rows, acct, book,
                               _position_starts(upto, basis), as_of, basis,
                               pool_rows=_pool)
    else:
        # The account's own pass: every pool in it is the account's (its
        # gains file's inventory, which plain `list` shows, has them all).
        inv = [dict(r, account=acct) for r in rows]
    # The declared contract sizes, as the run puts them on the inventory
    # (pipeline.annotate_inventory_multipliers).
    mults = declared_multipliers(
        [SimpleNamespace(symbol=str(t.get("symbol") or ""),
                         multiplier=t.get("multiplier") or 0.0)
         for t in book if isinstance(t, dict)])
    for r in inv:
        if mults.get(r.get("symbol")):
            r["multiplier"] = mults[r["symbol"]]
    return {"inventory": inv, "summary": doc.get("summary") or {}}, basis


def cmd_positions(args: argparse.Namespace) -> None:
    """List open positions per account, taken from each account's canonical
    gains file's `inventory` (wash-adjusted where built) — i.e. AFTER
    ticker.map consolidation (cross-listings merged) and base-currency
    conversion, so quantities and cost basis match the canonical pipeline.
    One row per (account, symbol); a base-currency book-cost TOTAL closes
    the table."""
    from taxjson.lib.report_model import (gains_basis_label,
                                          resolve_gains_files)
    root = Path(args.dir).resolve()
    cache = root / "work"
    _list_positional_date(args)
    # Canonical per-account gains (wash-adjusted where built — same basis
    # as every other query command); the raw/native derivatives keep
    # cross-listings separate and in native currency, which is the opposite
    # of what this view wants.
    as_of = getattr(args, "date", None)
    if as_of:
        # Positions AS OF a date: the engine's own pools that day, read
        # from the cost timeline each account's canonical gains pass (the
        # file plain `list` reads) wrote — the blended pass: Canada's s.47
        # ACB, the US engine's per-account FIFO lots, an own move's units
        # with the cost they brought (backlog TJ-0417; a recompute of
        # each account's books alone valued them at 0, TJ-0278 / TJ-0387,
        # and took a same-day sale before their arrival, TJ-0277).
        import re as _re
        if not _re.fullmatch(r"\d{4}-\d{2}-\d{2}", as_of):
            _die_input("--date expects YYYY-MM-DD")
        try:
            datetime.strptime(as_of, "%Y-%m-%d")
        except ValueError:
            # Shape-only validation let 2025-15-02 (swapped day/month)
            # through to the engine's string compare — wrong positions
            # at exit 0 with the bogus date in the banner (REVIEW #27).
            _die_input(f"--date {as_of} is not a real calendar date")
        settings = _soft_settings(root)
        # Accounts and their TYPES come from the config (a crypto
        # account's blended pass is the crypto one).
        accounts_cfg = (load_config(root).get("accounts", {})
                        if _PL.has_config(root) else {})
        if not accounts_cfg:
            _die("--date needs taxjson.toml (account names and types).")
        if args.account and args.account not in accounts_cfg:
            _die(f"no [accounts.{args.account}] in taxjson.toml")
        files = resolve_gains_files(cache, args.account or None)
        if not files:
            if args.account:
                _die_input(f"no gains for account {args.account!r} in "
                           f"work/ — run `tjs run` first")
            _die_input("no gains files in work/ — run `tjs run` first")
        from taxjson.lib.country import is_usa
        _us = is_usa(_country(settings))
        tmp_docs = {}
        _bases = set()
        for n, p in files.items():
            tmp_docs[n], _b = _dated_inventory(
                cache, n, p, as_of, accounts_cfg.get(n) or {}, _us)
            _bases.add(_b)
        _asof_basis = (next(iter(_bases)) if len(_bases) == 1
                       else _tax_date_basis(settings))
        _asof_word = ("settlement date" if _asof_basis == "settle"
                      else "trade date")
        basis = (f"{gains_basis_label(files)}, as of {as_of} by "
                 f"{_asof_word}")
    else:
        files = resolve_gains_files(cache, args.account or None)
        if not files:
            if args.account:
                _die_input(f"no gains for account {args.account!r} in "
                           f"work/ — run `tjs run` first, or check the "
                           f"name")
            _die_input("no gains files in work/ — run `tjs run` first")
        basis = gains_basis_label(files)

    money = fmt_money               # shared report-layer formatter
    from taxjson.lib.report_model import fmt_qty as qfmt
    from taxjson.lib.core import is_option_symbol as _is_opt_sym
    from taxjson.lib.ticker_map import is_future_ticker as _is_future_sym

    header = ["ACCOUNT", "SYMBOL", "QTY", "COST", "COST/SH",
              "DEFERRED", "SINCE"]
    out_rows: List[List[str]] = []
    json_rows: List[Dict[str, Any]] = []
    # A short that is a purchase missing from the files (a sale with
    # nothing to close), told apart from a real short — the pairs
    # find-missing-history reports (lib/missing_history.
    # missing_history_suspect).
    _suspects = _missing_history_suspects(root, cache)
    total_cost = 0.0
    total_deferred = 0.0
    n_pos = 0
    n_unknown = 0
    year = None
    for acct, p in files.items():
        if as_of:
            data = tmp_docs[acct]
        else:
            data = _load_json_or_die(p)
        year = year or (data.get("summary") or {}).get("year")
        inv = sorted((data.get("inventory") or []),
                     key=lambda r: str(r.get("symbol") or ""))
        for h in inv:
            qty = float(h.get("qty", 0) or 0)
            if qty == 0:                       # fully closed — not a position
                continue
            if getattr(args, "negative", False) and qty > 0:
                continue
            cost = float(h.get("total_cost", 0) or 0)
            # Signed division on purpose: shorts carry qty < 0 and
            # total_cost < 0 (proceeds credited), so COST/SH comes out
            # positive — same convention as the holdings export. An
            # equity option is 100 shares a contract: per SHARE, like
            # harvest and the holdings report (it was per contract,
            # 100x theirs — S045-03).
            _sym = str(h.get("symbol") or "")
            # A declared contract size (a futures option's CL 1000 —
            # S026-22) wins; an undeclared futures option stays per
            # contract.
            _mult = (float(h["multiplier"]) if _is_opt_sym(_sym)
                     and h.get("multiplier")
                     else 100.0 if _is_opt_sym(_sym)
                     and not _is_future_sym(_sym) else 1.0)
            cps = cost / (qty * _mult) if qty else 0.0
            deferred = float(h.get("deferred_wash", 0) or 0)
            suspect = qty < 0 and (_sym, acct) in _suspects
            # Units held before the data (an opening cost=unknown): the
            # cost is the known part only, said so (backlog TJ-0774).
            unk = bool(h.get("unknown_cost"))
            n_unknown += unk
            out_rows.append([
                acct, str(h.get("symbol") or "?"), qfmt(qty),
                money(cost) + ("+?" if unk else ""),
                money(cps) + ("+?" if unk else ""),
                money(deferred) if deferred > 0.005 else "-",
                str(h.get("position_start_date") or "-"),
                "missing history?" if suspect else "-"])
            json_rows.append({"account": acct,
                              "symbol": h.get("symbol"),
                              "qty": qty, "cost": round(cost, 2),
                              "cost_per_share": round(cps, 4),
                              "deferred_wash": round(deferred, 2),
                              "since": h.get("position_start_date"),
                              "last_acq_date": h.get("last_acq_date"),
                              "missing_history_suspect": suspect,
                              "unknown_cost": unk})
            total_cost += cost
            total_deferred += deferred
            n_pos += 1

    negative_only = getattr(args, "negative", False)

    # What the rows are AS OF: the --date, or the end of the books
    # (plain `list` is end-of-data, not the tax year's Dec 31 — its
    # header said "as of tax year 2025" over 2026 positions, R1-282).
    horizon = as_of or _books_horizon(cache, list(files))
    if getattr(args, "json", False):
        doc = {"rows": json_rows, "basis": basis, "year": year,
               "as_of": horizon,
               "currency": _base_currency(root),
               "totals": {"positions": n_pos,
                          "book_cost": round(total_cost, 2),
                          "deferred_wash": round(total_deferred, 2),
                          "unknown_cost_positions": n_unknown}}
        if negative_only:
            doc["filter"] = "negative"
        _json_out(doc)
        return

    if n_pos == 0:
        scope = f" for account {args.account!r}" if args.account else ""
        if negative_only:
            print(f"No negative positions{scope}.")
        else:
            print(f"No open positions{scope}.")
        return

    base = _base_currency(root)
    title = "NEGATIVE POSITIONS" if negative_only else "OPEN POSITIONS"
    when = (f"as of {as_of}" if as_of else
            f"as of the latest data in the books"
            + (f" ({horizon})" if horizon else ""))
    _vprint(f"{title} — {base}, {when}")
    _det = _details(args)
    if _det:
        _vprint(f"COST is book cost after ticker.map and the base-currency "
                f"conversion, basis: {basis}.")
        print()
    else:
        # The legend, before the table (docs/output-style.md).
        _vprint(f"COST: book cost in {base} after ticker.map, basis: "
                f"{basis}" + ("; DEFERRED: denied losses in it."
                              if total_deferred > 0.005 else "."))
    from taxjson.lib.out import fit_table as _fit_table
    n_sus = sum(1 for r in out_rows if r[7] != "-")

    def _table(rows, note=True):
        # Too wide: SINCE, then COST/SH, then DEFERRED go first. The
        # NOTE column only when a row carries one.
        cols = header + (["NOTE"] if n_sus and note else [])
        for ln in _fit_table(cols, [r[:len(cols)] for r in rows],
                             drop=(6, 4, 5), key=(0, 1)):
            print(ln)
    if negative_only and n_sus:
        # Two kinds of negative position: a real short (the broker marks
        # it, an option or a future sold to open) and a purchase missing
        # from the files.
        shorts = [r for r in out_rows if r[7] == "-"]
        if shorts:
            _vprint(f"Short positions ({len(shorts)}):")
            _table(shorts, note=False)
            print()
        _vprint(f"Missing history (a sale with no purchase in your files) "
                f"({n_sus}):")
        _table([r for r in out_rows if r[7] != "-"], note=False)
        print()
    if negative_only and n_sus and not _det:
        pass        # one `! ` line under the count (below)
    elif negative_only and n_sus:
        _vprint("Each is a sale your files show nothing to close for: a "
                "purchase before the data (or a transfer-in) is missing. "
                "Supply it (`tjs find-missing-history` lists the "
                "fixes), or record them all as openings with no cost so "
                "the shorts disappear: `tjs find-missing-history "
                "--write-missing-history --all-history` (their sales then "
                "leave the totals and are reported by hand; "
                "`--outside-year` records only the ones that do not touch "
                "the tax year).", hang="  ")
        print()
    else:
        _table(out_rows)
        print()
    _vprint(f"{n_pos} position(s), total book cost {money(total_cost)} "
            f"{base}" + (f", plus the unknown cost in {n_unknown} of "
                         f"them" if n_unknown else ""))
    if n_unknown:
        from taxjson.lib.out import act as _act_u
        print(_act_u(f"{n_unknown} position(s) hold units of unknown cost "
                     f"(an opening cost=unknown): COST +? is the known "
                     f"part only", "tjs find-missing-history"))
    if not _det:
        from taxjson.lib.out import act as _act
        if n_sus and not negative_only:
            print(_act(f"{n_sus} short position(s) with no purchase in "
                       f"your files (missing history?)",
                       "tjs list --negative"))
        elif n_sus:
            # Essentials first: the fixes are find-missing-history's.
            print(_act("supply each missing purchase, or record it as an "
                       "opening with no cost", "tjs find-missing-history"))
        if total_deferred > 0.005:
            _us_l = _country(_soft_settings(root)) == "usa"
            print(f"DEFERRED in the cost:  {money(total_deferred)} {base} "
                  + ("of disallowed wash-sale losses (§1091)" if _us_l
                     else "of denied superficial losses (s.54)"))
        from taxjson.lib.out import details_hint as _dh
        print(_dh("tjs list --details"))
        return
    if n_sus and not negative_only:
        _vprint(f"{n_sus} short position(s) marked `missing history?`: a "
                f"sale with no purchase in your files, not a real short — "
                f"`tjs list --negative` lists them apart.", hang="  ")
    if total_deferred > 0.005:
        _us_l = _country(_soft_settings(root)) == "usa"
        _vprint(f"DEFERRED: {money(total_deferred)} {base} of the book "
                f"cost is "
                + ("losses disallowed under the wash-sale rule (§1091), "
                   "added to these positions' basis"
                   if _us_l else
                   "denied superficial losses parked in these positions")
                + " (recovered when sold without a rebuy in the window).",
                hang="  ")


def _books_horizon(cache: Path, accounts: List[str]) -> Optional[str]:
    """Latest transaction date across these accounts' base books, on
    the project's date basis: a settle-basis book has already applied
    a Dec-31 trade's January settlement, so its horizon is that
    settlement date (audit A2-0698). A base book that exists but cannot
    be read is named on stderr instead of silently moving the date
    earlier (A2-0702)."""
    from taxjson.lib.country import (CountryError, resolve_tax_date,
                                     settings_country)
    try:
        _s = _soft_settings(cache.parent)
        settle = resolve_tax_date(settings_country(_s),
                                  _s.get("tax_date")) == "settle"
    except CountryError:
        settle = False        # no usable config: the trade date
    last = None
    for a in accounts:
        p = cache / f"{a}_base.json"
        try:
            doc = _read_work_doc(p)
            txs = doc.get("transactions", []) if isinstance(doc, dict) \
                else doc
            if not isinstance(txs, list):
                raise ValueError("no transactions list")
        except FileNotFoundError:
            continue
        except (OSError, ValueError, AttributeError) as e:
            emit_line(f"tjs: warning: work/{p.name} cannot be read "
                      f"({str(e)[:120]}) — the 'as of' date leaves account "
                      f"{a} out; re-run `tjs run`.", file=sys.stderr)
            continue
        for t in txs:
            if not isinstance(t, dict):
                continue
            d = str((t.get("date_settle") if settle else None)
                    or t.get("date") or "")[:10]
            if len(d) == 10 and (last is None or d > last):
                last = d
    return last


def _soft_config(root: Path) -> Dict[str, Any]:
    """Whole taxjson.toml (soft-read; {} when absent or unreadable). The
    single home for the query wrappers' config reads — they must work
    from work/ files without a hard config dependency."""
    cfg_path = root / "taxjson.toml"
    if cfg_path.is_symlink() and not cfg_path.exists():
        # Unreadable is not absent: a dangling taxjson.toml switched
        # fees / dil-sum / roc-sum from the tax year to all history at
        # exit 0 (re-audit A2-0144). (A directory reads as an error
        # below.)
        _die(f"cannot read {cfg_path}: it is a symlink whose target "
             f"does not exist (or loops) — fix or remove it.")
    if cfg_path.exists() and tomllib is not None:
        _refuse_unreadable_project_inputs(root)
        try:
            cfg = tomllib.loads(_read_config_text(cfg_path)) or {}
        except Exception as e:
            # Soft about a MISSING config only. An existing file that
            # does not parse is a user error to fix, not a reason to
            # guess: the {} fallback converted a USD-base project's fees
            # to CAD at an invented 1.35, dropped fees-sum's sibling
            # guard, and made the radar treat every registered book as
            # taxable (audit S049-00, S048-13).
            _die(_toml_problem(cfg_path, e), _TOML_FIX)
        # Soft about a MISSING or unreadable config, never about an
        # account the filing commands would silently drop (R1-268).
        _refuse_bad_account_types(cfg)
        _normalize_settings(cfg)
        _refuse_folder_settings(root, cfg)
        return cfg
    return {}


def _soft_settings(root: Path) -> Dict[str, Any]:
    """[settings] table from taxjson.toml (soft-read; {} when absent)."""
    return _soft_config(root).get("settings", {}) or {}


def _base_currency(root: Path) -> str:
    """Base currency label from taxjson.toml: [settings] base_currency,
    else the country's own currency (never a silent CAD for a US
    project)."""
    return _base(_soft_settings(root))


def cmd_wash_sales(args: argparse.Namespace) -> None:
    """Detail each superficial-loss (wash sale) that OCCURRED in the tax year —
    the losses the engine denied, which `<account>.sum` folds silently into the
    ticker totals. Reads the canonical per-account gains, preferring the
    cross-account `<account>_gains_wash.json` (which also catches registered-
    account repurchases) when the pipeline built it, else `<account>_gains.json`.
    One row per denied disposition + a denied total. With `--explain`, print the
    full ACB / superficial-loss calculation trace for each wash sale instead of
    the table."""
    root = Path(args.dir).resolve()
    cache = root / "work"

    if args.explain:
        if getattr(args, "json", False):
            # The trace is prose from taxjson-explain — silently
            # printing text under --json broke machine consumers.
            sys.exit(exit_text("tjs wash-sales: --explain has no JSON form; "
                               "drop --json (or drop --explain for the "
                               "machine-readable table)."))
        _explain_wash_sales(root, cache, args.account)
        return                                          # (raises SystemExit)

    from taxjson.lib.report_model import (gains_basis_label,
                                          resolve_gains_files)
    resolved = resolve_gains_files(cache, args.account or None)
    if not resolved:
        # work/ named from the project, and exit 2 for the input
        # missing, as sanity says it (backlog TJ-0642, TJ-0631).
        if args.account:
            _die_input(f"no gains for account {args.account!r} in work/ "
                       f"— run `tjs run` first, or check the name.")
        _die_input("no gains files in work/ — run `tjs run` first.")
    if not args.account:
        _warn_accounts_without_books(root, resolved, "wash-sales",
                                     "gains file")
    # The filing views' banners: per-account books after `run --account`
    # (no blended pass) and books built for another tax year printed
    # 'No wash sales' at rc 0 (re-audit A2-0400, A2-0405).
    # (The run-state banner: the dispatch loop, _RUN_STATE_BANNER_CMDS.)
    _cfg_ws = _soft_config(root)
    if _cfg_ws:
        _warn_artifact_year(resolved,
                            (_cfg_ws.get("settings") or {}).get("year"))
    files = list(resolved.items())

    money = fmt_money               # shared report-layer formatter
    from taxjson.lib.report_model import fmt_qty as qfmt

    header = ["ACCOUNT", "DATE", "SYMBOL", "QTY", "PROCEEDS", "COST",
              "GAIN", "DENIED", "ALLOWED"]
    rows = []
    year = None
    # Warn-only manual-check flags (CA-SL-14/15, US-WASH-14/15): they
    # deny nothing, so the table never showed them and the command said
    # "no losses were denied" over them (A2-0413).
    flags: Dict[str, str] = {}
    _usa = _country(_soft_settings(root)) == "usa"
    for acct, f in files:
        data = _load_json_or_die(f)
        year = year or (data.get("summary") or {}).get("year")
        for t in data.get("transactions", []):
            if t.get("is_wash_sale"):
                rows.append((t.get("date") or "", acct, t))
        for w in data.get("option_replacement_warnings") or []:
            if not isinstance(w, dict):
                continue
            try:
                from taxjson.lib.core import \
                    format_option_replacement_warning as _fmt_orw
                _txt = _fmt_orw(w, country="usa" if _usa else "canada")
            except (KeyError, TypeError, ValueError):
                _txt = (f"{w.get('loss_symbol')} loss on "
                        f"{w.get('loss_date')}: {w.get('option_symbol')} "
                        f"[{w.get('rule')}]")
            flags.setdefault(_txt, acct)
        # The engine's own manual checks: a loss with an unknown-cost
        # disposition in its window, or an unknown-cost loss with a
        # purchase in it. The books deny nothing for them, so the
        # command said "no losses were denied" and listed no flag
        # (backlog TJ-0551).
        from taxjson.lib.missing_history import loss_warning_text
        for w in data.get("superficial_loss_warnings") or []:
            if isinstance(w, dict):
                flags.setdefault(
                    f"{acct}: "
                    + loss_warning_text(w, "usa" if _usa else "canada"),
                    acct)
    rows.sort(key=lambda r: (r[0], r[1], str(r[2].get("symbol") or "")))

    from taxjson.lib.out import Doc
    from taxjson.lib.out import details_hint as _out_details_hint

    # The user's filing positions against the rule (.tt ALLOWLOSS): the
    # loss is allowed, so the table never shows it (CA-SL-18 /
    # US-WASH-25).
    from taxjson.lib import loss_overrides as _LO
    _lo_items = _LO.gather(dict(files))
    _lo_basis = ("trade" if (_soft_settings(root).get("tax_date")
                             or ("trade" if _usa else "settle")) == "trade"
                 else "settle")
    _positions = [p for p in _LO.positions(_lo_items, year, _lo_basis)
                  if p["in_year"]]

    _det = _details(args)
    _ws_cmd = "tjs wash-sales --details"

    def _flags_section(doc):
        if not _det:
            # Essentials first (docs/output-style.md): one act-on line
            # each; --details lists them.
            if _positions or flags:
                doc.blank()
            if _positions:
                doc.item(*_act_item(
                    f"FILING POSITIONS: {len(_positions)} loss(es) "
                    f"claimed against the rule (.tt ALLOWLOSS)", _ws_cmd))
            if flags:
                doc.item(*_act_item(
                    f"MANUAL CHECK: {len(flags)} warn-only flag(s) to "
                    f"decide by hand", _ws_cmd))
            return
        if _positions:
            doc.section(f"FILING POSITIONS — {len(_positions)} loss(es) "
                        f"claimed against the rule (.tt ALLOWLOSS)")
            doc.para("Allowed in the books although the rule would "
                     + ("disallow" if _usa else "deny")
                     + " them: your position, not the rule's test.")
            doc.items([ln for it in _lo_items
                       if it.get("status") == _LO.STATUS_APPLIED
                       and _LO.in_year(it, year, _lo_basis)
                       for ln in _LO.describe(it)])
        if not flags:
            return
        doc.section(f"MANUAL CHECK — {len(flags)} warn-only flag(s)")
        doc.para("The books deny nothing for them: decide each by hand.")
        doc.items(sorted(flags))

    # Deferred amounts still embedded in OPEN positions (across the
    # same canonical files): ties the historical denials to the present.
    embedded = 0.0
    for _acct, f in files:
        try:
            _d2 = _read_work_doc(f)
        except (OSError, ValueError):
            continue
        for h in _d2.get("inventory") or []:
            embedded += float(h.get("deferred_wash", 0) or 0)

    # The totals are the rows' cents added, as the table prints them and
    # the filed rows (sum's RETURN row) carry them; the engine's
    # unrounded total, a cent away over two rows, is a --details note
    # (backlog TJ-0428, as TJ-0209 did for sum).
    def _cents(key: str) -> float:
        return round(sum(round(float(t.get(key) or 0), 2)
                         for _d, _a, t in rows), 2)
    if getattr(args, "json", False):
        _json_out({"rows": [dict(t, account=acct)
                            for _d, acct, t in rows],
                   "totals": {"denied": _cents("disallowed_amount"),
                              # The engine's total rounded once: what
                              # close-year's lock records (A2-0867).
                              "denied_unrounded": round(sum(
                                  float(t.get("disallowed_amount") or 0)
                                  for _d, _a, t in rows), 2),
                              "permanently_denied":
                                  _cents("permanently_disallowed"),
                              "embedded_in_open": round(embedded, 2)},
                   "year": year, "currency": _base_currency(root),
                   "basis": gains_basis_label(resolved),
                   "manual_check_flags": sorted(flags),
                   **({"filing_positions": _positions}
                      if _positions else {})})
        return

    # The rule's own name: never "wash sale" in a Canadian project
    # (audit A2-0748, A2-1249, A2-1326, A2-1352, A2-1371, A2-1372).
    if not rows:
        scope = f" for account {args.account!r}" if args.account else ""
        # Each country's own term (A2-1366): a Canadian project has
        # superficial losses, not wash sales.
        doc = Doc(f"No {'wash sales' if _usa else 'superficial losses'}"
                  f"{scope} — no losses were denied.")
        _flags_section(doc)
        doc.print()
        return

    body = []
    total_denied = total_perm = 0.0
    for date, acct, t in rows:
        econ = float(t.get("raw_gain") or 0)        # true economic gain/loss
        denied = float(t.get("disallowed_amount") or 0)
        perm = float(t.get("permanently_disallowed") or 0)
        allowed = econ + denied                     # loss you can claim now
        _p, _c = _real_world_legs(t)                # S048-10
        body.append([
            acct, date or "-", str(t.get("symbol") or "?"),
            qfmt(float(t.get("qty") or 0)), money(_p),
            money(_c), money(econ), money(denied),
            money(allowed)])
        total_denied += denied
        total_perm += perm
    _engine_denied = total_denied
    total_denied = _cents("disallowed_amount")
    total_perm = _cents("permanently_disallowed")

    base = _base_currency(root)
    doc = Doc(f"{'WASH SALES' if _usa else 'SUPERFICIAL LOSSES'} — {base}, "
              f"tax year {year}, basis: {gains_basis_label(resolved)}")
    if _det:
        doc.para("Losses denied under "
                 + ("the wash-sale rule, §1091." if _usa
                    else "the superficial-loss rule, s.54."))
        doc.blank()
    else:
        # The legend, before the table (docs/output-style.md).
        doc.para("DENIED: the loss "
                 + ("the wash-sale rule (§1091) disallows" if _usa
                    else "the superficial-loss rule (s.54) denies")
                 + "; ALLOWED: the loss you claim.")
    # Too wide (a long option symbol): COST, then PROCEEDS, go first —
    # GAIN is their difference.
    doc.table(header, body, drop=(5, 4), key=(2, 1, 0))
    perm_note = (f" ({money(total_perm)} permanently denied)"
                 if total_perm > 0.005 else "")
    doc.blank()
    _figs = [("DENIED", f"{money(total_denied)} {base} over {len(rows)} "
                        f"{'wash sale(s)' if _usa else 'superficial loss(es)'}"
                        f"{perm_note}")]
    if embedded > 0.005:
        _figs.append(("DEFERRED", f"{money(embedded)} {base} in open "
                                  f"positions' cost — tjs list"))
    doc.kv(_figs)
    if not _det:
        _flags_section(doc)
        doc.para(_out_details_hint(
            _ws_cmd + " (what DENIED means); --explain: each denial's "
                      "trace", ""))
        doc.print()
        return
    doc.section("WHAT DENIED MEANS")
    if _usa:
        doc.item("DENIED is added to the cost basis of the repurchased "
                 "shares: you recover it on a later sale.")
        doc.item("A permanently-denied amount, from a repurchase in an "
                 "IRA, is lost for good.")
    else:
        doc.item("DENIED is added to the ACB of the substituted property "
                 "(s.53(1)(f)): you recover it on a later sale.")
        # An affiliated person's purchase: their own ACB, not "lost
        # for good" (S033-03 wording; re-audit A2-1233).
        doc.item("A permanently-denied amount is lost for good when the "
                 "repurchase is in a registered account; one bought by an "
                 "affiliated person is added to that person's own ACB "
                 "(s.53(1)(f)), not yours.")
    _gap = round(total_denied - _engine_denied, 2)
    if abs(_gap) >= 0.005:
        doc.item(f"Rows are rounded to the cent, as filed: the gains "
                 f"files' unrounded total denied is "
                 f"{money(_engine_denied)} ({_gap:+,.2f} on the DENIED "
                 f"total).")
    _flags_section(doc)
    doc.print()


def cmd_t1135(args: argparse.Namespace) -> None:
    """`tjs t1135`: CRA T1135 foreign-property helper over ALL taxable
    accounts (T1135 is a per-person form; registered accounts are excluded
    from specified foreign property by law, so sheltered accounts are never
    read). Feeds every taxable `<account>_base.json` (full history, base
    currency) plus the year-scoped gains files — preferring the wash-adjusted
    `<account>_gains_wash.json` so the GAIN(LOSS) column matches what
    Schedule 3 reports — into taxjson-t1135. Each account read needs its
    gains file (the income and gain columns): refused without it."""
    from taxjson.bin import taxjson_t1135
    from taxjson.lib.report_model import resolve_gains_files

    root = Path(args.dir).resolve()
    cache = root / "work"
    cfg = load_config(root)
    settings = cfg.get("settings", {})
    year = settings.get("year")
    if year is None:
        _die("no [settings] year in taxjson.toml")
    base_currency = str(_base(settings))
    if base_currency.upper() != "CAD":
        note("tjs t1135",
             f"base_currency is {base_currency} — T1135 amounts must be "
             f"reported in CAD; these figures are in {base_currency}.")

    taxable = [n for n, c in cfg.get("accounts", {}).items()
               if c.get("type") == "taxable"]
    if not taxable:
        _die("no taxable accounts in taxjson.toml",
             "T1135 applies to non-registered property only.")

    # All positionals first: argparse won't accept a second base file
    # after an interleaved --gains (the nargs="+" positional is consumed
    # greedily on first contact).
    base_argv: List[str] = []
    gains_argv: List[str] = []
    missing: List[str] = []
    no_gains: List[str] = []
    for name in taxable:          # taxjson.toml order (CA-DATE-14)
        base = cache / f"{name}_base.json"
        if not base.exists():
            missing.append(name)
            continue
        base_argv.append(str(base))
        gains = resolve_gains_files(cache, name).get(name)
        if gains is not None:
            gains_argv += ["--gains", str(gains)]
        else:
            no_gains.append(name)
    argv: List[str] = base_argv + gains_argv
    # A configured taxable account with inputs but no books made the
    # filing-threshold test read "not required" with rc 0 (S006-03).
    _require_taxable_books(root, cfg,
                           {n: 1 for n in taxable if n not in missing},
                           "base book")
    # The income and gain columns come from the gains files: an
    # account whose books were read without them showed 0 income and 0
    # gain, rc 0 and no word (backlog TJ-0306).
    if no_gains:
        _die(f"no gains file for taxable account(s) {', '.join(no_gains)} "
             f"in work/ — the T1135 income and gain(loss) columns come "
             f"from it",
             "Re-run `tjs run` to rebuild it; without it those "
             "accounts' income and gains would read 0.")
    missing = [n for n in missing
               if n not in _accounts_skipped_for_no_inputs(root)]
    if missing:
        from taxjson.lib.out import warn as _warn
        _warn(f"no base file for taxable account(s) {', '.join(missing)}",
              prog="tjs t1135",
              details=["Run `tjs run` first; the threshold test below "
                       "may be understated."])
    if not argv:
        _die("no taxable base files in work/", "Run `tjs run` first.")
    # The income/gain columns come from the year-scoped gains files: on
    # books built for another year they silently read 0 (S007-06,
    # S048-01).
    _warn_artifact_year(
        {Path(g).name.rsplit("_gains", 1)[0]: Path(g)
         for g in gains_argv[1::2]}, year)
    _warn_run_state(root, cfg)

    argv += ["--year", str(year), "--base-currency", base_currency,
             # S052-10: the gain join and the cost walk follow the
             # project's tax_date, like the gains files.
             "--tax-date", _tax_date_basis(settings)]
    # An account held with a custodian outside Canada: its Canadian
    # issuers' shares are T1135 property (tax-logic CA-RPT-02; backlog
    # TJ-0369). The config check has read the value.
    for name in taxable:
        cc = (cfg["accounts"][name] or {}).get("custodian_country")
        if cc is not None:
            argv += ["--custodian", f"{name}={cc}"]
    # The domicile overrides are ticker.map's T1135 lines (once
    # t1135.map). A dangling link (or a directory) is not "no map": the
    # overrides it holds change the filing verdict (A2-0355).
    t1135_map = _PL.ticker_map_path(root)
    if t1135_map.is_file():
        argv += ["--map", str(t1135_map)]
    elif t1135_map.is_symlink() or t1135_map.exists():
        _die(f"cannot read {t1135_map.name} (a broken link or not a "
             f"file)",
             "Fix or remove it; its T1135 country overrides change the "
             "verdict.")
    # The same missing-history openings the gains stage applies (R1-321):
    # without them a position bought before the data read as a short that
    # later real buys covered at zero cost.
    mh_file = _missing_history_arg(root)
    if mh_file is not None:
        argv += ["--incomplete-history", str(mh_file)]
    # The full-history superficial-loss pass (S008-07) sees what the
    # pipeline's wash pass sees: the registered accounts as context and
    # the project's written-option timing.
    sheltered_base = cache / "sheltered_base.json"
    if sheltered_base.exists():
        argv += ["--sheltered", str(sheltered_base)]
    argv += option_timing_flags(settings)
    # ...and its income dating: a listed corporation's ROC on its pay
    # date in that pass (audit A2-0339).
    argv += income_dating_flags(settings)
    # ...and the filing positions the books took (.tt ALLOWLOSS): no ACB
    # addition for them.
    argv += _loss_override_flags(cache)
    if args.json:
        argv.append("--json")
    if not _details(args) and not getattr(args, "json", False):
        # Essentials first (docs/output-style.md): the stage's default
        # view; --details prints its whole report.
        argv.append("--brief")
    # The cash an account holds outside Canada (a crypto account's, one
    # whose custodian is abroad) is foreign property at its cost: the
    # FX-on-cash ledger v2 gives it day by day (tax-logic CA-RPT-20;
    # backlog TJ-0454, TJ-0609).
    cash_doc = _t1135_cash_doc(root, cache, cfg, settings)
    if cash_doc is None:
        raise SystemExit(taxjson_t1135.main(argv))
    import json as _json
    import tempfile
    with tempfile.TemporaryDirectory(prefix="taxjson-t1135-") as td:
        cash_file = Path(td) / "cash.json"
        _write_atomic(cash_file, _json.dumps(cash_doc), encoding="utf-8")
        rc = taxjson_t1135.main(argv + ["--cash", str(cash_file)])
    raise SystemExit(rc)


def _t1135_cash_doc(root: Path, cache: Path, cfg: Dict[str, Any],
                    settings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """The cash rows of `tjs t1135` (lib/t1135_cash.cash_doc), None
    when no taxable account holds cash outside Canada (or the project
    is not Canadian). The FX-on-cash ledger v2 costs it; where it
    refuses or cannot run, the doc says so (an unknown cost, the total
    not settled) — never a stop: the securities' test still stands."""
    from taxjson.lib import t1135_cash as TC
    from taxjson.lib.country import is_canada
    if not is_canada(_country(settings)):
        return None
    counted = TC.counted_accounts(cfg.get("accounts") or {})
    if not counted:
        return None
    import contextlib
    import io
    ledger = None
    refusal = ""
    year = int(settings.get("year"))
    base = str(_base(settings)).upper()
    # The cash day by day on the dates the walk dates the securities
    # on: on trade dates a purchase's cash leaves as its shares come in
    # (backlog TJ-0627).
    basis = _tax_date_basis(settings)
    # The ledger's own notes are `tjs fx-cash`'s to say.
    with contextlib.redirect_stderr(io.StringIO()):
        try:
            ledger = _fx_cash_v2_doc(root, cache, holdings=True,
                                     holdings_basis=basis)[0]
        except SystemExit as e:
            refusal = str(e.code or "").strip()
        except (OSError, ValueError) as e:
            refusal = str(e)
    stable: List[str] = []
    if ledger is not None and ledger.get("stablecoins_as_cash"):
        from taxjson.lib.brokerages._crypto_common import USD_STABLECOINS
        stable = sorted(USD_STABLECOINS)
    refusal = refusal.split("\n", 1)[0]
    for p in ("tjs fx-cash: error: ", "tjs fx-cash: "):
        if refusal.startswith(p):
            refusal = refusal[len(p):]
    return TC.cash_doc(ledger, counted, year, base,
                       refusal=refusal and f"fx-cash v2: {refusal}",
                       stablecoins=stable, basis=basis)


def _box18_by_year(root: Path, accounts) -> Dict[int, float]:
    """{tax year: T5 box 18 capital-gains dividends} named in
    [[capital_gains_dividends]], in the base currency, dated as the
    estimate dates them (_box18_into_estimate). {} without the map."""
    fr = _box18_fractions(root)
    if not fr:
        return {}
    from taxjson.lib.cg_dividends import row_amount
    rules = _view_income_rules(root)
    out: Dict[int, float] = {}
    for acct in sorted(accounts):
        p = root / "work" / f"{acct}_base.json"
        if not p.exists():
            continue
        try:
            data = _read_work_doc(p)
        except (OSError, ValueError) as e:
            # Named once, from the project; exit 2, as the estimate's
            # _box18_into_estimate (backlog TJ-0641, TJ-0645).
            _die_input(f"could not read {_work_read_why(p, e, root)}",
                       "It holds the capital-gains dividends "
                       "[[capital_gains_dividends]] names. Re-run "
                       "`tjs run` to rebuild it.")
        for t in data.get("transactions", []):
            f = fr.get((acct, str(t.get("id"))))
            if not f or t.get("action") != "DIVIDEND":
                continue
            d = rules.income_date(t) if rules is not None \
                else str(t.get("date") or "")
            if len(str(d)) >= 4 and str(d)[:4].isdigit():
                y = int(str(d)[:4])
                out[y] = out.get(y, 0.0) + row_amount(t) * f
    return out


def cmd_carryover(args: argparse.Namespace) -> None:
    """`tjs carryover`: multi-year capital-loss carryforward/carryback
    ledger over all taxable accounts' full-history books. Passes the
    combined sheltered book for wash-window context and the project's
    .tt OPENING cost=unknown lines when present. taxjson.toml's [carryover] claimed
    (`claimed = { 2023 = 4000.00 }`) folds in what was actually claimed
    on filed returns."""
    from taxjson.bin import taxjson_carryover

    root = Path(args.dir).resolve()
    cache = root / "work"
    cfg = load_config(root)
    settings = cfg.get("settings", {})

    taxable = [n for n, c in cfg.get("accounts", {}).items()
               if c.get("type") == "taxable"]
    if not taxable:
        _die("no taxable accounts in taxjson.toml")
    _acct_cfg = cfg.get("accounts", {})
    base_argv: List[str] = []
    crypto_argv: List[str] = []
    missing: List[str] = []
    for name in taxable:          # taxjson.toml order (CA-DATE-14)
        base = cache / f"{name}_base.json"
        if not base.exists():
            missing.append(name)
        elif (_acct_cfg.get(name) or {}).get("crypto"):
            crypto_argv += ["--crypto", str(base)]
        else:
            base_argv.append(str(base))
    # An account the last run skipped for having no inputs has no books
    # to miss — the warning fired for the scaffold's empty `crypto`
    # account on every carryover (R1-264), unlike t1135 and the rest.
    missing = [n for n in missing
               if n not in _accounts_skipped_for_no_inputs(root)]
    if missing:
        from taxjson.lib.out import warn as _warn
        _warn(f"no base file for taxable account(s) {', '.join(missing)}",
              prog="tjs carryover",
              details=["Run `tjs run` first; those years' nets will "
                       "be incomplete."])
    if not base_argv and not crypto_argv:
        _die("no taxable base files in work/", "Run `tjs run` first.")
    # A crypto-only project passes its books as --crypto only: fed as
    # positional FILEs they lost the US no-wash pass (US-WASH-13; audit
    # A2-0146, A2-0411, A2-0412).

    argv = base_argv + crypto_argv + [
        "--country", _country(settings),
        "--base-currency", str(_base(settings)),
        # The same year attribution as run / close-year (R1-192).
        "--tax-date", _tax_date_basis(settings),
    ] + option_timing_flags(settings)       # same timing as the returns
    # ...and the same income dating: a listed corporation's ROC on its
    # pay date (audit A2-0123, A2-0339, A2-0341, A2-1141).
    argv += income_dating_flags(settings)
    argv += _loss_override_flags(cache)     # .tt ALLOWLOSS positions
    if settings.get("year") is not None:
        # Rows before the project year are flagged as possibly partial.
        argv += ["--project-year", str(int(settings["year"]))]
    sheltered_base = cache / "sheltered_base.json"
    if sheltered_base.exists():
        argv += ["--sheltered", str(sheltered_base)]
    mh_file = _missing_history_arg(root)
    if mh_file is not None:
        argv += ["--incomplete-history", str(mh_file)]
    # [carryover] claimed (taxjson.toml): the losses actually applied
    # on filed returns (checked with the rest of the config).
    from taxjson.lib.project_tables import claimed_losses
    for _y, _amt in sorted(claimed_losses(cfg)[0].items()):
        argv += ["--claimed-year", f"{_y}={_amt!r}"]
    argv.append("--claims-in-project")      # the notes name the toml
    # Each filed-year lock — this project's filed/<year>.json and the
    # prior_year_record lock of the per-year layout (A2-0338, A2-0121):
    # a year before the project year takes what the lock says was
    # filed; a later one is compared (S047-21, S048-20). An unreadable
    # lock is named, never skipped (A2-0336).
    from taxjson.bin import taxjson_filed
    try:
        _locks = taxjson_filed.project_locks(root, settings)
    except taxjson_filed.PriorRecordError as e:
        _die(str(e))
    for _yr, _lp, _where in _locks:
        argv += ["--filed-lock", f"{_yr}={_lp}"]
    # The prior_year_record lock deleted after its year was closed: named
    # as a lock that cannot be read (backlog TJ-0272).
    _mp = taxjson_filed.missing_prior_lock(root, settings)
    if _mp is not None and _mp[0] not in {y for y, _p, _w in _locks}:
        import os as _os
        argv += ["--filed-lock", f"{_mp[0]}={_os.path.normpath(_mp[1])}"]
    # T5 box 18 capital-gains dividends named in
    # [[capital_gains_dividends]] are capital gains of their year: the
    # estimate nets them, so the ledger does too (A2-0678).
    for _y, _amt in sorted(_box18_by_year(root, taxable).items()):
        argv += ["--slip-gains", f"{_y}={_amt!r}"]
    _ret = _project_return_row(root, cfg, taxable)
    if _ret is not None:
        # The project year's net as the return files it (backlog
        # TJ-0208): what close-year records and the estimate taxes.
        argv += ["--return-row",
                 f"{int(settings['year'])}={_ret['realized']!r}"]
    _w = _grant_since_warning(settings, root, cfg.get("accounts") or {})
    if _w:
        from taxjson.lib.out import warn as _warn
        _warn(_w, prog="tjs carryover")
    # Deferred / failed / validation-ERROR books drive the carryforward
    # balance too (S048-21).
    _warn_run_state(root, cfg)
    if args.json:
        argv.append("--json")
    if not _details(args) and not getattr(args, "json", False):
        # Essentials first (docs/output-style.md): the stage's default
        # view; --details prints its whole report.
        argv.append("--brief")
    raise SystemExit(taxjson_carryover.main(argv))


def _taxable_gains_argv(root: Path, cache: Path, *,
                        exclude_crypto: bool = False,
                        prog: str = "tjs",
                        required: bool = False) -> List[str]:
    """`--gains FILE` pairs for every taxable account, preferring the
    wash-adjusted `<account>_gains_wash.json` (the allowed numbers a return
    reports). Shared by the form-export and reconcile-slips wrappers.

    `exclude_crypto` drops `crypto = true` accounts (with a note): no
    exchange issues a T5008/1099-B, so feeding a crypto book to the slip
    reconciler made every one of its dispositions MISSING_FROM_SLIP and
    the command could never exit 0 (2026-09 audit)."""
    cfg = load_config(root)
    accounts_cfg = cfg.get("accounts", {})
    taxable = [n for n, c in accounts_cfg.items()
               if c.get("type") == "taxable"]
    if not taxable:
        _die("no taxable accounts in taxjson.toml")
    if exclude_crypto:
        crypto = sorted(n for n in taxable if accounts_cfg[n].get("crypto"))
        if crypto:
            note(prog, f"crypto account(s) {', '.join(crypto)} excluded "
                       f"(exchanges issue no slips)",
                 details=(["Exchanges issue no T5008/1099-B slips, so "
                           "there is nothing to reconcile them against."]
                          if _CURRENT_DETAILS else []))
            taxable = [n for n in taxable if n not in crypto]
        if not taxable:
            _die("every taxable account is crypto — nothing to reconcile",
                 "No slip data exists for crypto dispositions (exchanges "
                 "issue no T5008/1099-B).")
    from taxjson.lib.report_model import resolve_gains_files
    argv: List[str] = []
    _no_input = _accounts_skipped_for_no_inputs(root)
    have = {}
    for name in sorted(taxable):
        gains = resolve_gains_files(cache, name).get(name)
        if gains is not None:
            argv += ["--gains", str(gains)]
            have[name] = gains
        elif required and _has_inputs(root, name):
            pass                        # refused below, all at once
        elif name not in _no_input:
            from taxjson.lib.out import warn as _warn
            _warn(f"no gains file for taxable account {name!r}",
                  prog=prog, details=["Run `tjs run` first."])
    if required:
        # The Schedule 3 / 8949 export and the slip check must not be
        # partial: a failed account was a one-line warning with rc 0,
        # and the checklist certified the partial export (S045-21).
        _require_taxable_books(
            root, {"accounts": {n: accounts_cfg[n] for n in taxable}},
            have, "gains file")
    if not argv:
        _die("no taxable gains files in work/", "Run `tjs run` first.")
    return argv


def cmd_form_export(args: argparse.Namespace) -> None:
    """`tjs form-export`: render the year's gains as IRS Form 8949 or
    CRA Schedule 3 rows. Form defaults from the project country."""
    from taxjson.bin import taxjson_form_export

    root = Path(args.dir).resolve()
    cache = root / "work"
    _cfg = load_config(root)
    settings = _cfg.get("settings", {})
    country = _country(settings)
    form = args.form or ("8949" if country == "usa" else "schedule3")
    year = settings.get("year")
    _txf_only = [f for f, v in (("--out", getattr(args, "out", None)),
                                ("--box", getattr(args, "box", None)))
                 if v is not None]
    if form != "txf" and _txf_only:
        # Were silently ignored: `--out gains.txf` wrote nothing and
        # printed the table to stdout (2026-09 CLI audit B19).
        _die(f"{' and '.join(_txf_only)} only "
             f"{'applies' if len(_txf_only) == 1 else 'apply'} to --form txf "
             f"(this run renders {form})",
             f"Use --csv FILE to save the {form} rows.")

    gains_argv = _taxable_gains_argv(root, cache, required=True)
    # form-export takes gains files positionally.
    files = [gains_argv[i + 1] for i in range(0, len(gains_argv), 2)]
    _warn_artifact_year({Path(f).name.rsplit("_gains", 1)[0]: Path(f)
                         for f in files}, year)
    _state_probs = _warn_run_state(root, _cfg)
    # Crypto books go on Schedule 3's crypto-assets line: name them.
    from taxjson.lib.report_model import resolve_gains_files
    _crypto_files = []
    for _n, _c in sorted((_cfg.get("accounts") or {}).items()):
        if (_c or {}).get("type") == "taxable" and (_c or {}).get("crypto"):
            _g = resolve_gains_files(cache, _n).get(_n)
            if _g is not None:
                _crypto_files += ["--crypto", str(_g)]
    argv = files + _crypto_files + ["--form", form, "--country", country,
                    "--base-currency",
                    str(settings.get("base_currency", "")),
                    # R1-200: rows are picked by the date the gains
                    # files were scoped on, not the form's default.
                    "--date-basis", _tax_date_basis(settings)]
    if year is not None:
        argv += ["--year", str(year)]
    if args.csv:
        argv += ["--csv", args.csv]
    if args.json:
        argv.append("--json")
        for _p in _state_probs or ():
            argv += ["--run-state-problem", str(_p)]
    # What `tjs sum` counts as missing from the totals that the gains
    # files cannot tell: an in-kind move with a registered account the
    # run could not value, a sale with no purchase in the files — the
    # same readiness record, and a `! ` line each (backlog TJ-0251).
    _taxable = {n for n, c in (_cfg.get("accounts") or {}).items()
                if isinstance(c, dict) and c.get("type") == "taxable"}
    _ik = [m for m in in_kind_unbooked(cache, year)
           if m.get("taxable") in _taxable]
    _np = [r for r in _uncovered_sales(root, _cfg)
           if r.get("booked") == "open"]
    if _ik:
        argv += ["--in-kind-unbooked", str(len(_ik))]
    if _np:
        argv += ["--no-purchase", str(len(_np))]
    if not _details(args) and not getattr(args, "json", False):
        # Essentials first (docs/output-style.md): the stage's default
        # view; --details prints its whole report.
        argv.append("--brief")
    if form == "txf":
        argv += ["--box", args.box or "A"]
        if args.out:
            argv += ["--out", args.out]
    raise SystemExit(taxjson_form_export.main(argv))


def _radar_as_of(sidecar: Path) -> Optional[str]:
    """The day a wash-radar --json sidecar was computed as of
    (`as_of_date`, YYYY-MM-DD), None when it does not say or cannot be
    read (backlog TJ-1009)."""
    import json
    try:
        doc = json.loads(sidecar.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    d = doc.get("as_of_date") if isinstance(doc, dict) else None
    return d if isinstance(d, str) and re.fullmatch(
        r"\d{4}-\d{2}-\d{2}", d) else None


def cmd_harvest(args: argparse.Namespace) -> None:
    """`tjs harvest [SYMBOL]`: unrealized gain/(loss) per open
    position at current prices — "if I sold this today, is it a loss?" —
    over every taxable account's wash-adjusted books, harvestable losses
    first, each loss annotated with the wash radar's advisory. Prices
    resolve IBKR -> yfinance -> cache (work/.price_cache.json). Runs
    with cwd=project root so the root ticker.map QUOTE lines are found. Accounts
    with `crypto = true` are excluded unless --crypto is given (the
    price chain serves stock snapshots)."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = _soft_settings(root)
    cfg = load_config(root)
    accounts_cfg = cfg.get("accounts", {})
    # Crypto accounts are EXCLUDED by default: the price chain serves
    # stock snapshots, so crypto symbols just spray yfinance lookup
    # errors. `--crypto` opts them back in.
    include_crypto = getattr(args, "crypto", False)

    def _skip_crypto(acfg) -> bool:
        return bool(acfg.get("crypto", False)) and not include_crypto

    skipped = [n for n, c in sorted(accounts_cfg.items())
               if c.get("type") == "taxable" and _skip_crypto(c)]
    taxable = [n for n, c in sorted(accounts_cfg.items())
               if c.get("type") == "taxable" and not _skip_crypto(c)]
    if skipped:
        note("tjs harvest",
             f"crypto account(s) excluded: {', '.join(skipped)} "
             f"(pass --crypto to include them).")
    if not taxable:
        _die("no (non-crypto) taxable accounts",
             "Pass --crypto to harvest crypto accounts.")
    from taxjson.lib.report_model import resolve_gains_files
    files = []
    _no_input = _accounts_skipped_for_no_inputs(root)
    for name in taxable:
        gains = resolve_gains_files(cache, name).get(name)
        if gains is not None:
            files.append(str(gains))
        elif name not in _no_input:
            from taxjson.lib.out import warn as _warn
            _warn(f"no gains file for taxable account {name!r} — run "
                  f"`tjs run` first.", prog="tjs harvest")
    if not files:
        _die("no taxable gains files in work/",
             "Run `tjs run` first.")
    # Its rename rules decide which option contract is quoted: with a
    # malformed `GLOBAL OLD.TO NEW.TO` dropped, the books' NEW contract
    # was quoted for the OLD one held, a loss read as a gain (backlog
    # TJ-0352, audit TJ-0399). Refused as `tjs run` refuses it.
    _strict_ticker_map(
        root, "its rename rules decide which contract an option row is "
        "quoted as and its SIMILAR lines the wash caveats, so a "
        "valuation without the rule can price another contract "
        "(`tjs run` refuses this map too)")
    cmd = _cmd("taxjson-harvest") + files + [
        "--price-cache", str(cache / ".price_cache.json"),
        "--country", _country(settings),
        "--base-currency", str(_base(settings)),
    ]
    # --options was defined-but-never-forwarded: the wrapper (and the
    # GUI's include-options toggle, which calls through it) silently
    # ignored the flag (round-five audit finding 8).
    if getattr(args, "options", False):
        cmd.append("--options")
    # Crypto accounts are named to the tool, which decides by country
    # (US-PLAN-05: outside §1091 in a usa project; Canada unchanged).
    for name in taxable:
        if accounts_cfg.get(name, {}).get("crypto", False):
            cmd += ["--crypto-account", name]
    rates = cache / "to_base.csv"
    if rates.exists():
        cmd += ["--rates", str(rates)]
    per_acct_sidecars = []
    for f in files:
        acct = Path(f).name
        for suf in ("_gains_wash.json", "_gains.json"):
            if acct.endswith(suf):
                acct = acct[: -len(suf)]
                break
        sidecar = root / "reports" / f"wash_radar_{acct}.json"
        if sidecar.exists():
            per_acct_sidecars.append(sidecar)
    combined_sidecar = root / "reports" / "wash_radar_COMBINED.json"
    _fresh_refs = per_acct_sidecars or [Path(f) for f in files
                                        if Path(f).exists()]
    if combined_sidecar.exists() and all(
            combined_sidecar.stat().st_mtime >= s2.stat().st_mtime
            for s2 in _fresh_refs):
        # The cross-account radar (one run over every taxable base) —
        # a rebuy in a sibling taxable account is a trigger the
        # per-account sidecars can't see. Preferred only while FRESH:
        # a per-account sidecar rebuilt after it means the combined
        # view is stale and must not shadow it.
        radar_files = [combined_sidecar]
    else:
        radar_files = list(per_acct_sidecars)
    # A sidecar older than the books it describes — `run --account`
    # rebuilds an account's books (and sheltered_base.json) but skips
    # the cross reports — reported a registered-account buy's LOCKED
    # name as CLEAR / claimable now (2026-09 audit S038-09). Run the
    # radar live over the current books instead.
    # (is_file: a dangling *_base.json symlink was a FileNotFoundError
    # traceback, re-audit A2-1422)
    _books = [p for p in cache.glob("*_base.json")
              if not p.name.startswith(".") and p.is_file()]
    _newest_book = max((p.stat().st_mtime for p in _books), default=0.0)
    _old_books = bool(radar_files) and any(
        sc.stat().st_mtime < _newest_book for sc in radar_files)
    # A sidecar computed as of an EARLIER day is stale too, however new
    # its file: a registered account's purchase leaves the 30-day window
    # by the calendar alone, so the LOCKED units (at_risk_qty) a sale
    # today would lose shrink while the books stay as they are. harvest
    # counts the clear date down but took the units as timeless, and
    # said nothing was claimable now (backlog TJ-1009). The radar dates
    # its run by this computer's day, as here.
    _today_iso = datetime.now().strftime("%Y-%m-%d")
    _old_day = not _old_books and any(
        (_radar_as_of(sc) or _today_iso) < _today_iso
        for sc in radar_files)
    if _old_books or _old_day:
        if (not (cache / "sheltered_base.json").exists()
                and _sheltered_expected(root)):
            # A live radar without the registered accounts' books drops
            # their recent buys: a LOCKED loss read CLEAR, claimable now
            # (backlog TJ-1206). Refuse, as the checks do (TJ-0350).
            _die_input("no sheltered_base.json in work/: the registered "
                       "accounts' trades are missing from this harvest",
                       "A registered account's recent buy can deny a loss "
                       "for good, so the wash-radar reports cannot be "
                       "brought up to date without them. Run `tjs "
                       "run` first to rebuild it.")
        from taxjson.lib.dispatch import run_cmd as _run_live
        _live = cache / ".harvest_radar.json"
        _bases = _radar_taxable_bases(root, cache, "tjs harvest",
                                      empty_ok=True)
        _rcmd = _cmd("taxjson-wash-radar") + [
            "--taxable", *[str(b) for b in _bases],
            "--json-out", str(_live), "--account", "LIVE"]
        _rcmd += _radar_engine_args(_bases, root,
                                    _country(settings))
        if (cache / "sheltered_base.json").exists():
            _rcmd += ["--sheltered", str(cache / "sheltered_base.json")]
        _res = _run_live(_rcmd, capture_output=True)
        if _res.returncode == 0 and _live.exists():
            if _old_books:
                note("tjs harvest",
                     "the wash-radar reports are older than the books (a "
                     "single-account run?) — using a live radar",
                     details=["Run a full `tjs run` to refresh "
                              "reports/."])
            radar_files = [_live]
        else:
            from taxjson.lib.out import warn as _warn
            _warn("the wash-radar reports are "
                  + ("older than the books" if _old_books
                     else "of an earlier day")
                  + " and a live radar failed — the ADVISORY column is "
                  "left empty",
                  prog="tjs harvest",
                  details=["Losses count as 'no clear date'; run a full "
                           "`tjs run`."])
            radar_files = []
    for sidecar in radar_files:
        cmd += ["--radar", str(sidecar)]
    _tmap = _PL.ticker_map_path(root)
    if _tmap.exists():
        cmd += ["--ticker-map", str(_tmap)]
    # Sheltered accounts' inventories feed the SH_QTY / SH_ADD columns:
    # shares held sheltered and days since the sheltered side last
    # acquired (a sheltered add within the 30-day window makes a
    # harvested loss permanently denied). Crypto sheltered accounts
    # follow the same --crypto gate as taxable ones.
    for name in sorted(n for n, c in accounts_cfg.items()
                       if c.get("type") != "taxable"
                       and not _skip_crypto(c)):
        gains = resolve_gains_files(cache, name).get(name)
        if gains is not None:
            cmd += ["--sheltered", str(gains)]
    for sym in (args.symbol or []):
        cmd += ["--symbol", sym]
    if args.no_ibkr:
        cmd.append("--no-ibkr")
    if args.ibkr_port is not None:
        cmd += ["--ibkr-port", str(args.ibkr_port)]
    if args.json:
        cmd.append("--json")
    elif not _details(args):
        # Essentials first (docs/output-style.md): COLUMNS, NOTES and
        # the scope paragraph are the --details view.
        cmd.append("--brief")
    if args.verbose:
        cmd.append("--verbose")
    _exec_tool(cmd, cwd=str(root))


def _artifact_year_mismatch(files: Dict[str, Path],
                            config_year) -> Dict[str, str]:
    """{account: artifact_year} for each gains file whose recorded tax
    year (summary.year, written by the engine) differs from
    [settings].year. After a year bump without a rebuild, work/ still
    holds LAST year's books: close-year would lock them under the new
    year and sum/estimate/form-export would present them as the new
    year's figures (2026-09 CLI audit B2). Unreadable files and files
    without a recorded year are skipped (their own readers complain)."""
    out: Dict[str, str] = {}
    if config_year is None:
        return out
    for acct, pth in files.items():
        try:
            doc = _read_work_doc(Path(pth))
        except (OSError, ValueError):
            continue
        yr = ((doc.get("summary") or {}).get("year")
              if isinstance(doc, dict) else None)
        if yr is not None and str(yr) != str(config_year):
            out[acct] = str(yr)
    return out


def _warn_artifact_year(files: Dict[str, Path], config_year) -> None:
    """Loud stderr banner for _artifact_year_mismatch (report commands:
    they still print, but the numbers belong to another year)."""
    bad = _artifact_year_mismatch(files, config_year)
    if not bad:
        return
    got = ", ".join(f"{a} ({y})" for a, y in sorted(bad.items()))
    if _brief(sys.stderr):
        _say("warning", f"these figures are NOT {config_year}'s: work/ "
             f"was built for another year — run `tjs run`",
             prog=_cmd_prog())
        return
    _say("warning", f"[settings].year is {config_year} but the work/ "
         f"books were built for another tax year: {got}",
         f"These figures are NOT {config_year}'s — rebuild with `tjs "
         f"run` first.", prog=_cmd_prog())


def _count_noun(n: int, one: str, many: Optional[str] = None) -> str:
    """`1 sale`, `2 sales` (`many` for an irregular plural)."""
    return f"{n} {one if n == 1 else (many or one + 's')}"


def _brief(stream=None) -> bool:
    """A shared report-command warning shows only its headline: shown to
    a person (width > 0) without --details (docs/output-style.md,
    Essentials first). Captured (width 0) it keeps every detail line."""
    from taxjson.lib.out import width as _w
    return (not _CURRENT_DETAILS
            and _w(sys.stderr if stream is None else stream) > 0)


def _tax_date_basis(settings: Dict[str, Any]) -> str:
    """The date the project's gains files are year-scoped on: the
    explicit [settings] tax_date, else the country default (CRA:
    settlement, IRS: trade) — what stage_account feeds the engine."""
    return _tax_date(settings)


def _has_inputs(root: Path, name: str) -> bool:
    """inputs/<name>/ holds an activity file `tjs run` reads."""
    d = _PL.inputs_dir(root) / name
    return bool(input_files(d, ".csv") or input_files(d, ".tt"))


# _run_state_problems' entry for a run that died after writing work/:
# close-year refuses those books even with --force (backlog TJ-0015).
_RUN_UNFINISHED = ("the last `tjs run` did not finish: reports/ has "
                   "no .sum, but work/ holds the partial books it wrote")


def _run_state_problems(root: Path, cfg: Dict[str, Any]) -> List[str]:
    """What `tjs checklist`'s run-clean step finds wrong with the
    books the filing commands read: validation ERRORs in the last run,
    an account deferred on pending elections, inputs changed since the
    last full run (a failed run leaves them newer than the artifacts),
    an account with inputs but no report. [] when clean or when there
    is nothing to judge (no reports yet). The report commands used to
    serve these books with rc 0 and no word (R1-252, S049-11). A
    "blocked" step with work/ books but no reports/ (a run that died
    before writing them) is a problem too: close-year locked those with
    rc 0 (A2-0035, A2-0658)."""
    try:
        from datetime import date as _d
        from taxjson.lib.checklist import Ctx, d_run_clean
        year = int((cfg.get("settings") or {}).get("year") or 0)
        res = d_run_clean(Ctx(root, cfg, year, _d.today(),
                              lambda *a, **k: (0, "", "")))
    except Exception:                                   # noqa: BLE001
        return []
    if res.status == "blocked":
        # No .sum yet: nothing to judge — unless a run aborted after
        # writing work/ (a first run that died at a later stage). Those
        # partial books are what sum / t1135 / list read (A2-0658).
        cache = root / "work"
        try:
            partial = any(
                not p.name.startswith(".")
                for pat in ("*_gains.json", "*_gains_wash.json",
                            "*_base.json")
                for p in cache.glob(pat))
        except OSError:
            partial = False
        if partial:
            return [_RUN_UNFINISHED]
        return []
    if res.status != "attention":
        return []
    # Each problem whole: one may hold "; " itself ("inputs changed ...
    # (changed: X; added: Y)" was two problems, backlog TJ-0109).
    return [x.strip() for x in (res.problems or res.detail.split("; "))
            if x.strip()]


def _refuse_other_country_books(root: Path, cfg: Dict[str, Any]) -> None:
    """Die when work/ was built under the other country: its figures
    follow that country's law (a superficial-loss denial, an s.47 pool,
    CAD amounts) and every view would print them under this country's
    labels and citations at exit 0 (audit A2-0147). The country comes
    from the last full run's record."""
    from taxjson.lib.checklist import books_country
    from taxjson.lib.country import CountryError, settings_country
    built = books_country(root)
    try:
        now = settings_country(cfg.get("settings") or {})
    except CountryError:
        return
    if built and built != now:
        _die(f"the books in work/ were built by the last full run for country = \"{built}\", but "
             f"taxjson.toml now says \"{now}\" — their figures follow the "
             f"other country's law. Run `tjs run` to rebuild them "
             f"before using any report.")


def _warn_run_state(root: Path, cfg: Dict[str, Any]) -> List[str]:
    """Loud stderr banner for _run_state_problems; returns them. Books
    built under the other country are refused outright."""
    _refuse_other_country_books(root, cfg)
    probs = _run_state_problems(root, cfg)
    if probs and _brief(sys.stderr):
        _filed = ("; the filed year's inputs changed"
                  if _filed_year_stale_hint(root, cfg, probs) else "")
        _say("warning", f"these books are not the clean result of the "
             f"current inputs ({_count_noun(len(probs), 'problem')}"
             f"{_filed}): `tjs checklist --run`", prog=_cmd_prog())
    elif probs:
        _say("warning", "these books are not the clean result of the "
             "current inputs",
             *[f"- {p}" for p in probs],
             "The figures below may leave sales out or carry default FX; "
             "fix and re-run `tjs run` before using them."
             + _filed_year_stale_hint(root, cfg, probs),
             prog=_cmd_prog())
    return probs


def _filed_year_stale_hint(root: Path, cfg: Dict[str, Any],
                           probs: List[str]) -> str:
    """When the books' year is filed (filed/<year>.json) and one of
    `probs` (_run_state_problems) is that the inputs changed: the
    sentence saying they may have moved the filed figures — in a
    multi-year project a shared input or ticker.map edited while
    working on a later year (lib/project_layout). Any other problem (a
    run that did not finish) gets no such sentence."""
    year = (cfg.get("settings") or {}).get("year")
    if year is None or not (root / "filed" / f"{year}.json").is_file():
        return ""
    if not any(str(p).startswith("inputs changed since the last")
               for p in probs):
        return ""
    return (f" {year} is filed (filed/{year}.json) and its inputs changed "
            f"since the last run: `tjs run` here recomputes the year "
            f"and says whether the filed figures moved (DRIFTED).")


def _require_taxable_books(root: Path, cfg: Dict[str, Any],
                           have: Dict[str, Any], what: str) -> None:
    """Die when a configured taxable account that HAS inputs has no
    `what` artifact: a partial filing figure (form-export, t1135,
    close-year) was reported with rc 0 and a one-line warning
    (S045-21, S006-03, S006-07)."""
    missing = sorted(
        n for n, c in (cfg.get("accounts") or {}).items()
        if isinstance(c, dict) and c.get("type") == "taxable"
        and n not in have and _has_inputs(root, n))
    if missing:
        _die(f"no {what} for taxable account(s) {', '.join(missing)} — "
             f"the last `tjs run` did not build them (did it fail?). "
             f"Fix and re-run `tjs run`; figures without them would "
             f"leave those accounts out.")


def _filed_run_gains(cmd_tail, out_path):
    """taxjson-gains invocation for the filed-year recompute."""
    run_to_file(_cmd("taxjson-gains") + cmd_tail, Path(out_path),
                capture_diag=False)


def _close_year_attention(root: Path, cfg: Dict[str, Any],
                          year: int) -> List[Tuple[str, str]]:
    """(step id, what it found) for each checklist step before the lock
    (lib/checklist, the steps ahead of filed-lock) whose result, marks
    applied, needs attention — or is still to do where the lock needs
    it done: inputs committed, so the filed books can be rebuilt
    (_CLOSE_YEAR_TODO; backlog TJ-0090)."""
    from taxjson.lib import checklist as cl
    ids = cl.item_ids()
    only = ids[:ids.index("filed-lock")] if "filed-lock" in ids else ids
    ctx = cl.Ctx(root=root, cfg=cfg, year=year, today=date_cls.today(),
                 run_sub=cl.default_run_sub(root))
    try:
        results = cl.evaluate(ctx, only=only, progress=cl.stderr_progress)
    except cl.StateFileError as e:
        return [("checklist.json", str(e))]
    return [(r.id, " ".join(str(r.detail or "").split()))
            for r in results if r.effective == "attention"
            or (r.effective == "todo" and r.id in _CLOSE_YEAR_TODO)]


# Checklist steps before the lock whose "todo" stops close-year like an
# "attention" (docs/commands.md: uncommitted inputs stop the close).
_CLOSE_YEAR_TODO = frozenset({"inputs-committed"})


def _return_row_totals(cfg: Dict[str, Any], files: Dict[str, Path],
                       year: int) -> Optional[Dict[str, float]]:
    """`realized` and `disallowed` as `tjs sum`'s FOR THE RETURN row
    files them, for the taxable gains `files`: each disposition's cents
    summed per return line (Canada: Schedule 3's gain and denied; USA:
    Form 8949's (h) and (g), the §1256 net of Form 6781 added to the
    gain). The lock's `totals` round the engine's unrounded sum once,
    a cent or two apart on a large year: close-year and `tjs years`
    show these, check-filed compares the totals (backlog TJ-0192). None
    when the dispositions cannot be read."""
    import io
    from taxjson.bin.taxjson_form_export import (filing_6781, filing_lines,
                                                 filing_parts_8949,
                                                 load_dispositions,
                                                 mark_crypto)
    settings = cfg.get("settings") or {}
    date_key = ("date" if _tax_date_basis(settings) == "trade"
                else "date_settle")
    ents: List[Dict[str, Any]] = []
    try:
        with contextlib.redirect_stderr(io.StringIO()):
            for acct, p in sorted(files.items()):
                got, _ = load_dispositions([Path(p)], year, date_key)
                if ((cfg.get("accounts") or {}).get(acct) or {}).get(
                        "crypto"):
                    got = mark_crypto(got)
                ents += got
            if _country(settings) in ("us", "usa"):
                rows = filing_parts_8949(ents, year)
                gain = (sum(float(r["gain"]) for r in rows)
                        + float(filing_6781(ents).get("gain") or 0.0))
                denied = sum(float(r["adjustment"]) for r in rows)
            else:
                rows = filing_lines(ents, year, date_key)
                gain = sum(float(r["gain"]) for r in rows)
                denied = sum(float(r["denied"]) for r in rows)
    except (OSError, ValueError, KeyError, TypeError, SystemExit):
        return None
    return {"realized": round(gain, 2) + 0.0,
            "disallowed": round(denied, 2) + 0.0}


def _project_return_row(root: Path, cfg: Dict[str, Any],
                        taxable: List[str]) -> Optional[Dict[str, float]]:
    """The project year's RETURN row (`_return_row_totals`) over the
    taxable accounts' gains files in work/, for `tjs carryover`'s
    ledger (Canada: its net is one figure; backlog TJ-0208). None in a
    US project, with no year, or when a taxable account with books has
    no gains file of the year (a partial RETURN row is no figure)."""
    from taxjson.lib.report_model import resolve_gains_files
    settings = cfg.get("settings") or {}
    if _country(settings) in ("us", "usa") or settings.get("year") is None:
        return None
    cache = Path(root) / "work"
    files = {a: p for a, p in resolve_gains_files(cache).items()
             if a in taxable}
    books = {a for a in taxable if (cache / f"{a}_base.json").exists()}
    if not files or not books <= set(files) \
            or _artifact_year_mismatch(files, settings.get("year")):
        return None
    return _return_row_totals(cfg, files, int(settings["year"]))


def cmd_close_year(args: argparse.Namespace) -> None:
    """`tjs close-year`: snapshot the current tax year's per-account
    filing aggregates to filed/<year>.json (the filed-year lock)."""
    from taxjson.bin import taxjson_filed
    from taxjson.lib.report_model import (gains_basis_label,
                                          resolve_gains_files)
    from taxjson.lib import out as _out
    _prog = "tjs close-year"
    _nothing = "Nothing was written."
    root = Path(args.dir).resolve()
    cache = root / "work"
    cfg = load_config(root)
    settings = cfg["settings"]
    year = args.year or settings.get("year")
    if year != settings.get("year"):
        _die(f"the work/ gains artifacts are scoped to tax year "
             f"{settings.get('year')}",
             "Set [settings].year to the year you are closing, run "
             "`tjs run`, then close.")
    taxable = {n for n, c in cfg.get("accounts", {}).items()
               if c.get("type") == "taxable"}
    files = {a: p for a, p in resolve_gains_files(cache).items()
             if a in taxable}
    if not files:
        _die("no taxable gains files in work/", "Run `tjs run` first.")
    # The books, inputs and reports stay as they are until the lock is
    # written: no `tjs run` meanwhile (backlog TJ-0924).
    _acquire_run_lock(cache, closing=True)
    _bad_year = _artifact_year_mismatch(files, settings.get("year"))
    if _bad_year:
        _die(f"the work/ books were built for another tax year ("
             f"{', '.join(f'{a}: {y}' for a, y in sorted(_bad_year.items()))}"
             f") but [settings].year is {settings.get('year')}",
             f"Rebuild with `tjs run` first, then close. {_nothing}")
    # A taxable account with inputs but no gains file (its stage
    # failed) was left out of the lock without a word, and then never
    # drift-checked (S006-07).
    _require_taxable_books(root, cfg, files, "gains file")
    # The lock certifies the filing numbers: books from a run with
    # validation ERRORs, a pending-election deferral or inputs changed
    # since (a failed run) are not locked without --force (S048-23,
    # S049-11).
    _state = _run_state_problems(root, cfg)
    # Equity taxable accounts always get the blended cross-account pass
    # in a full run; a plain <acct>_gains.json means only `run --account`
    # ran (or an account is deferred) — per-account, unblended numbers
    # that check-filed's blended recompute then reports as DRIFT
    # (S046-01).
    _unblended = sorted(
        a for a, pth in files.items()
        if not (cfg.get("accounts", {}).get(a) or {}).get("crypto")
        and not Path(pth).name.endswith("_gains_wash.json"))
    # Staleness guard: after `run --account X` the wash file predates
    # the just-rebuilt plain gains (the blend pass was skipped).
    # `tjs sum` merely notes this; close-year WRITES the filing
    # lock, so snapshotting stale numbers is a hard stop.
    # A sheltered rebuild (`run --account <sheltered>`) refreshes
    # sheltered_base.json without the wash pass — the same stale lock
    # (2026-09 audit R1-251).
    from taxjson.lib.report_model import stale_wash_inputs
    stale = sorted(
        f"{a} (older than {', '.join(stale_wash_inputs(p))})"
        for a, p in files.items()
        if p.name.endswith("_gains_wash.json") and stale_wash_inputs(p))
    # A run deferred at a corp-action election skips the cross-account
    # pass too: the refusal names it, not an `--account` rerun that
    # never happened (backlog TJ-0148).
    _deferred = sorted(
        n for n in (cfg.get("accounts") or {})
        if (cache / f"{n}_pending_elections.json").exists())
    _why_unblended = (
        f"The last `tjs run` deferred {', '.join(_deferred)} at "
        f"pending elections (`tjs elect --pending`), so its "
        f"cross-account pass never ran: make the elections, run "
        f"`tjs run`, then close." if _deferred else None)
    # --force locks books with open problems, but never books it cannot:
    # a run that did not finish (the reports as filed would be empty,
    # backlog TJ-0015), or books the cross-account pass did not build
    # (refused below). The refusal offers --force only when it helps.
    _unfinished = _RUN_UNFINISHED in _state
    if _state and (not args.force or _unfinished):
        _forceable = not (_unfinished or _unblended or stale)
        _die("the books are not the clean result of the current inputs",
             *[f"- {_p}" for _p in _state],
             f"Fix and re-run `tjs run`, then close"
             + (" (or pass --force to lock them anyway)" if _forceable
                else "") + f". {_nothing}")
    if _unblended:
        _die(f"{', '.join(_unblended)} only has per-account (pre-wash, "
             f"unblended) gains",
             (_why_unblended or
              "The cross-account pass of a full `tjs run` never ran. "
              "Run `tjs run` with no --account first.")
             + f" {_nothing}")
    if stale:
        _die(f"wash-adjusted gains for {'; '.join(stale)} are STALE",
             (_why_unblended or
              "A --account rerun skipped the cross-account wash pass — "
              "run a full `tjs run` first.") + f" {_nothing}")
    if _state:
        _out.warn("locking books with open problems (--force)", prog=_prog,
                  details=[f"- {_p}" for _p in _state])
    accounts = {}
    raw_aggs = {}
    _ot_docs: Dict[str, Dict[str, Any]] = {}
    import json as _json
    for acct, pth in sorted(files.items()):
        _crypto = bool((cfg.get("accounts", {}).get(acct) or {})
                       .get("crypto"))
        try:
            doc = _read_work_doc(Path(pth))
            _ot_docs[acct] = doc
            accounts[acct] = taxjson_filed.aggregates_from_gains(
                doc, crypto=_crypto, year=int(year))
            raw_aggs[acct] = taxjson_filed.aggregates_from_gains(
                doc, rounded=False)
        except (OSError, ValueError, UnicodeDecodeError) as e:
            # Unreadable, not JSON, or JSON of the wrong shape (a list):
            # one line, never a traceback (S031-19).
            _die(f"could not read {_out.relpath(pth, root)}: {e}",
                 f"Re-run `tjs run` to rebuild it. {_nothing}")
    # A year with no disposition and no income in any taxable book is
    # almost always a typo'd [settings] year (2015, 2204): the lock
    # then guarded an all-zero "filed" year as OK (S045-24).
    if (not any(int(a.get("dispositions") or 0) for a in accounts.values())
            and not any(abs(float(a.get("income") or 0.0)) >= 0.005
                        for a in accounts.values())):
        if not args.force:
            _die(f"the taxable books hold no disposition and no income "
                 f"in {year}",
                 f"Check [settings] year (pass --force to lock an empty "
                 f"year). {_nothing}")
        _out.warn(f"locking {year} with no disposition and no income "
                  f"(--force)", prog=_prog)
    basis = gains_basis_label(files)
    from taxjson.lib.pipeline import option_timing_from_settings
    from taxjson.lib import handoff as _handoff
    # The lock's option timing describes its totals: it was stamped from
    # the CURRENT taxjson.toml, so a timing edited after the run locked
    # grant-timed totals as close timing and option-boundary advised a
    # T1-ADJ for a premium the lock already held (S046-02).
    _want_ot = option_timing_from_settings(settings) or {}
    _ot_bad = []
    for _a, _doc in sorted(_ot_docs.items()):
        _sm = _doc.get("summary") or {}
        if "option_premium_timing" not in _sm or not _want_ot:
            continue
        _got = (str(_sm.get("option_premium_timing") or "close"),
                _sm.get("option_grant_since"))
        _exp = (_want_ot.get("option_premium_timing"),
                _want_ot.get("option_grant_since"))
        if _got[0] != _exp[0] or (_exp[0] == "grant"
                                  and _got[1] != _exp[1]):
            _ot_bad.append(f"{_a}: built with {_got[0]} timing"
                           + (f" since {_got[1]}" if _got[0] == "grant"
                              else ""))
    if _ot_bad:
        _die("the gains files were built with another option timing than "
             "taxjson.toml now says",
             f"{'; '.join(_ot_bad)}; settings: {_exp[0]}"
             + (f" since {_exp[1]}" if _exp[0] == "grant" else "") + ".",
             f"Run `tjs run`, then close. {_nothing}")
    filed_csv = (Path(args.filed_dispositions).expanduser()
                 if getattr(args, "filed_dispositions", None) else None)
    if filed_csv is not None and not filed_csv.exists():
        _die_input(f"{filed_csv} not found.")
    if filed_csv is not None:
        # Read it up front, through the broker decode funnel: a UTF-16
        # save, a directory or a stray quote is one line naming the
        # file, exit 2, before anything is computed (A2-1136, A2-1138).
        # A row of another year is refused the same way: summed into
        # filed_totals it carried that year's loss into the next one
        # (backlog TJ-0298).
        try:
            _handoff.load_filed_dispositions(filed_csv, int(year))
        except ValueError as e:
            _die_input(str(e), _nothing)
    if taxjson_filed.snapshot_path(root, year).exists() and not args.force:
        _die(f"{_out.relpath(taxjson_filed.snapshot_path(root, year), root)}"
             f" already exists — the lock protects a filed year",
             "Re-run with --force to replace it (only if you "
             "re-filed/amended).")
    # Where the lock goes is checked before the inputs are frozen: a
    # file at filed/ failed the lock's write after taxjson.toml stopped
    # naming the shared exports (backlog TJ-0917).
    _lock_dir_bad = _lock_folder_problem(root)
    if _lock_dir_bad:
        _die(f"cannot write filed/{year}.json: {_lock_dir_bad}",
             f"Move it away (or make the folder writable), then close. "
             f"{_nothing}")
    _old_lock = None
    if taxjson_filed.snapshot_path(root, year).exists():
        try:
            _old_lock = _json.loads(taxjson_filed.snapshot_path(
                root, year).read_text(encoding="utf-8"))
            if not isinstance(_old_lock, dict):
                raise ValueError("not a close-year lock")
        except (OSError, ValueError) as e:
            _out.warn(f"the lock being replaced could not be read: {e}",
                      prog=_prog,
                      details=["Anything it recorded (the filed totals, "
                               "dispositions filed with another tool) is "
                               "not carried into the new lock."])
            _old_lock = None
    if (filed_csv is None and _old_lock is not None
            and isinstance(_old_lock.get("filed_dispositions"), list)):
        # The filed dispositions --force keeps (below) hold the same
        # invariant as a new CSV: the replaced lock's year only, checked
        # before anything is thawed or written (TJ-0298).
        _other = _handoff.filed_rows_outside(
            _old_lock["filed_dispositions"], int(year))
        if _other:
            _die_input(
                f"the lock being replaced records {len(_other)} filed "
                f"disposition(s) dated outside {year}: "
                f"{', '.join(_other[:5])}"
                + (f" and {len(_other) - 5} more" if len(_other) > 5
                   else ""),
                f"Its filed totals counted them in {year}. Pass "
                f"--filed-dispositions with the sales the {year} return "
                f"reported (that year's rows only). {_nothing}")
    # A partial lock an earlier release froze: thawed first, so this
    # close reads the whole year (workflow audit 2026-10-23).
    _thaw_partial_freeze(root, cfg, int(year), _old_lock,
                         nothing=_nothing)
    # The lock records a FILED return: a year that has not ended cannot
    # have been filed — the lock then drifted on every later run and
    # the checklist said "Return filed and the year locked" (S045-23).
    from datetime import date as _date_cy
    _partial_year = _date_cy.today() <= _date_cy(int(year), 12, 31)
    if _partial_year:
        if not args.force:
            _die(f"tax year {year} has not ended (today is "
                 f"{_date_cy.today().isoformat()})",
                 f"The lock records the FILED return; close the year "
                 f"after you file (or pass --force to snapshot it "
                 f"anyway). {_nothing}")
        _out.warn(f"tax year {year} has not ended — locking a partial "
                  f"year (--force)", prog=_prog,
                  details=[f"The inputs are not frozen: the year keeps "
                           f"reading its exports, so later trades in "
                           f"{year} show as drift. Close the year again "
                           f"after filing."])
    # Said under --yes too: this year's income moves if the short is
    # covered in time, and the lock would then drift (backlog TJ-1065).
    from taxjson.lib import readiness as _RD
    _open_comp = _RD.unsettled_compensation_lines(files.values())
    if _open_comp:
        _out.warn(f"{_count_noun(len(_open_comp), 'dividend compensation payment')}"
                  f" on a short still inside its 45 days: not settled",
                  prog=_prog, details=_open_comp)
    # The checklist's steps before the lock that need attention: listed
    # and confirmed on a terminal; without one, refused unless --yes
    # (new-user walkthrough: a year was locked with them open).
    if not getattr(args, "yes", False):
        _attn = _close_year_attention(root, cfg, int(year))
        if _attn:
            _head = (f"{len(_attn)} checklist item(s) before the lock need "
                     f"attention")
            _items = [f"- {sid}: {detail}" for sid, detail in _attn]
            if not sys.stdin.isatty():
                _die(_head, *_items,
                     f"Fix them (`{_PROG} checklist` says how), or pass "
                     f"--yes to lock {year} anyway. {_nothing}")
            # The question is about these items: listed in the default
            # view too, as the piped refusal lists them (backlog TJ-0035).
            _out.show(_out.message("warning", _head, prog=_prog,
                                   details=_items, stream=sys.stderr),
                      sys.stderr)
            try:
                _ans = input(f"Lock {year} anyway? [y/N] ")
            except EOFError:
                _ans = ""
            if not _ans.strip().lower().startswith("y"):
                _die(f"{year} not locked", _nothing)
    _step(f"Recording year-end positions and the {year} dispositions "
          f"for the {int(year) + 1} hand-off")
    try:
        extra = _handoff.record_fields(
            root, cfg, int(year), files, _filed_run_gains,
            _handoff_gains_flags(settings, root / "work"), filed_csv)
    except _handoff.BooksError as e:
        _die(f"{e}", _nothing)
    except ValueError as e:
        _die(str(e))
    if (filed_csv is None and _old_lock is not None
            and _old_lock.get("filed_dispositions") is not None):
        # --force (what check-filed's DRIFTED advice says) used to drop
        # the dispositions another tool actually filed, and handoff's
        # double-reporting check silently fell back to taxjson's own
        # (A2-0119). They describe the RETURN, not the books: keep them.
        extra["filed_dispositions"] = _old_lock["filed_dispositions"]
        if isinstance(_old_lock.get("filed_totals"), dict):
            extra["filed_totals"] = _old_lock["filed_totals"]
        print(_out.fill(
            f"Kept the {len(extra['filed_dispositions'])} filed "
            f"disposition(s) the replaced lock recorded"
            + (f" (from {_old_lock['filed_totals'].get('source')})"
               if isinstance(_old_lock.get("filed_totals"), dict)
               else "")
            + " — pass --filed-dispositions to replace them."))
    _cf = _carryforwards_for_lock(root, cfg, _details(args),
                                  extra.get("filed_totals"))
    if _cf is not None:
        extra["carryforwards"] = _cf
    if _fx_cash_ledger_choice(settings) == "v2":
        # The FX-on-cash ledger v2's close (each account's foreign cash
        # and its cost, each debt): the next year's opening pool
        # (CA-FX-07). Only a COMPUTED ledger is carried.
        try:
            _v2doc = _fx_cash_v2_doc(root, root / "work")[0]
        except SystemExit as e:
            _v2doc = {"status": "not_computed",
                      "problems": [{"text": str(e.code or "")}]}
        if _v2doc.get("status") == "computed":
            extra["fx_cash_v2"] = _v2doc["close"]
            print(_out.fill(f"Recorded the FX-on-cash ledger v2's close "
                            f"for the {int(year) + 1} opening pool."))
        else:
            _out.warn("the FX-on-cash ledger v2 did not compute — its "
                      "close is not recorded (the next year needs "
                      "CASHOPEN lines)", prog=_prog,
                      details=[str((_v2doc.get("problems") or [{}])[0]
                                   .get("text", ""))])
    # The exports the books were built from become this project's own
    # inputs/ (the lock records their hashes) before the lock is
    # written: the filed year stays reproducible while the shared
    # folder moves on with the next year.
    # A year that has not ended is hashed, not frozen: it keeps reading
    # the shared exports, so the rest of the year reaches the books
    # (and shows as drift against this snapshot) and the close after
    # filing freezes the whole year (workflow audit 2026-10-23).
    _undo_freeze: List[Callable[[], None]] = []
    _frozen = _freeze_inputs(root, cfg, settings, int(year),
                             nothing=_nothing,
                             previous=(_old_lock or {}).get("frozen"),
                             partial=_partial_year, undo=_undo_freeze)
    extra["frozen"] = _frozen
    # The freeze and the lock are one step: a lock that is not written
    # puts taxjson.toml and the copies back, so "Nothing was written"
    # is true and the year goes on reading the shared exports (backlog
    # TJ-0917).
    try:
        # The RETURN row's figures, as filed: what the CLOSED block and
        # `tjs years` show (display only; check-filed compares
        # `totals`).
        _ret = _return_row_totals(cfg, files, int(year))
        if _ret is not None:
            extra["return_row"] = _ret
        # The year's T5 box 18 capital-gains dividends
        # [[capital_gains_dividends]] names (Canada; a US project's
        # table is refused with its config): capital gains of the year
        # beside the RETURN row's, so the next year's carryover counts
        # them in the carry-back room this year offers (backlog
        # TJ-0898). The next project's inputs no longer hold them.
        _slip_cg = _box18_by_year(root, taxable).get(int(year), 0.0)
        if abs(_slip_cg) > 0.005:
            extra["slip_gains"] = round(_slip_cg, 2)
        path = taxjson_filed.write_snapshot(
            root, year, _normalize_country(settings["country"]), basis,
            accounts, force=args.force,
            option_timing=option_timing_from_settings(settings) or None,
            extra=extra, raw=raw_aggs)
    except BaseException:
        for _u in reversed(_undo_freeze):
            _u()
        raise
    _kept_reports = _keep_filed_reports(root, int(year), prog=_prog)
    tot = _json.loads(path.read_text())["totals"]
    _old_tot = (_old_lock or {}).get("totals")
    if isinstance(_old_tot, dict):
        # The replaced lock was the record of the filed return: say what
        # moved, so a re-close made only to record positions (handoff's
        # advice for a version-1 lock) does not overwrite the filed
        # totals in silence (A2-0345).
        _moved = []
        for _k in ("realized", "disallowed", "income", "dispositions"):
            try:
                _a, _b = float(_old_tot.get(_k) or 0), float(tot.get(_k) or 0)
            except (TypeError, ValueError):
                continue
            if abs(_a - _b) > 0.005:
                # A count reads as one, money as money (TJ-0189).
                _fmt = ",.0f" if _k == "dispositions" else ",.2f"
                _moved.append(f"{_k} {_a:{_fmt}} -> {_b:{_fmt}}")
        if _moved:
            _out.warn(f"the replaced {year} lock recorded other totals: "
                      f"{'; '.join(_moved)}", prog=_prog,
                      details=[f"The lock is the record of the FILED "
                               f"return: this is right only if you amended "
                               f"{year} to these figures — otherwise "
                               f"restore the old lock from your records "
                               f"(git) and resolve the drift `tjs "
                               f"check-filed` reports."])
    if _old_lock is not None:
        # A later year filed on the net capital loss the replaced lock
        # carried: the amendment reaches its return too (backlog
        # TJ-0430).
        for _ly, _lp, _ld, _cm in _later_locks_on(
                root, int(year), _json.loads(path.read_text())):
            _out.warn(f"{_ly} was filed on the {_cm[0]:,.2f} net capital "
                      f"loss the replaced {year} lock carried; {year} now "
                      f"carries {_cm[2]:,.2f}", prog=_prog,
                      details=[_carry_in_detail(
                          _ly, int(year), _cm,
                          _out.relpath(path, root),
                          ("`tjs check-filed` " if _ld == root else
                           f"`tjs -C {_year_dir_arg(_ld.parent, _ly)}"
                           f" check-filed` ")
                          + f"names it ({_lp}); amend {_ly} as {year}: "
                          f"`tjs run`, and after filing `tjs "
                          f"close-year --force` in {_ly}'s project.")])
    print()
    print(f"CLOSED {year} — {basis}, {len(accounts)} taxable account(s)")
    # Realized and disallowed as the return files them (`tjs sum`'s
    # RETURN row), not the engine total a cent or two apart (TJ-0192).
    _shown = {**tot, **(_ret or {})}
    # Income as `tjs sum`'s taxable SUBTOTAL adds it (each
    # account's cents), not the lock's total rounded once (TJ-0212).
    _inc = taxjson_filed.income_as_summed({"accounts": accounts})
    if _inc is not None:
        _shown["income"] = _inc
    _rows = [("Realized", f"{_shown['realized']:,.2f}"),
             ("Disallowed", f"{_shown['disallowed']:,.2f}"),
             ("Income", f"{_shown['income']:,.2f}")]
    _mw = max(len(v) for _, v in _rows)
    _kv = [(k, _out.Verbatim(f"{v:>{_mw}}")) for k, v in _rows]
    # Essentials first (docs/output-style.md): --details adds the why.
    _det = _details(args)
    _rnd = []
    if _det and _ret is not None and any(
            abs(float(tot[k]) - _ret[k]) > 0.005
            for k in ("realized", "disallowed")):
        _rnd.append(f"realized and disallowed are the RETURN "
                    f"row of `tjs sum` (each sale's cents); "
                    f"the engine totals the lock's drift check "
                    f"compares are {tot['realized']:,.2f} and "
                    f"{tot['disallowed']:,.2f}")
    if _det and abs(float(tot["income"]) - float(_shown["income"])) > 0.005:
        _rnd.append(f"income is the taxable SUBTOTAL of `tjs sum` "
                    f"(each account's cents); the lock's total the drift "
                    f"check compares is {tot['income']:,.2f}")
    if _rnd:
        _kv.append(("Rounding", "; ".join(_rnd)))
    _kv.append(("Lock", f"{_out.relpath(path, root)} — commit it with "
                        f"your records; `tjs check-filed` now guards "
                        f"it" if _det else
                        f"{_out.relpath(path, root)} — commit it with "
                        f"your records"))
    _ft = extra.get("filed_totals")
    if _ft:
        _kv.append(("As filed", f"{_ft['source']}: {_ft['dispositions']} "
                                f"dispositions, gain {_ft['gain']:,.2f}"
                                + (f" — the {int(year) + 1} project's "
                                   f"`tjs handoff` checks against "
                                   f"these" if _det else "")))
    _kv.append(("Frozen", _frozen_summary(_frozen, _kept_reports,
                                          int(year), _det)))
    _gi = _gitignore_hides_filed_reports(root)
    if _gi and _kept_reports:
        # An older scaffold's unanchored rule: the reports as filed
        # would be left out of every commit (2026-10 workflow audit).
        _kv.append(("Note", f".gitignore's `{_gi}` also ignores "
                            f"filed/{year}/reports/ — change the line to "
                            f"`/reports/` so the reports as filed are "
                            f"committed"))
    _ye = extra.get("year_end") or {}
    _kv.append(("Year-end positions",
                (", ".join(f"{g} {len(v)}" for g, v in _ye.items())
                 or "none")
                + f"; trades settling in {int(year) + 1}: "
                f"{len(extra.get('settle_next_year') or [])}"))
    for _ln in _out.kv_lines(_kv, indent="  "):
        print(_ln)
    if _cf is not None:
        for _ln in _carryforwards_summary(_cf, int(year), _det):
            print(_ln)
        _bl = _books_loss_not_carried(root, _cf, int(year))
        if _bl is not None:
            print()
            for _ln in _out.wrap(_out.labelled(
                    f"note: these books carry a net capital loss of "
                    f"{_bl:,.2f} into {year} (`tjs carryover`) that "
                    f"the lock does not take in: with no [estimate] "
                    f"other_losses and no earlier close-year record, "
                    f"{year} started from 0.00. If that loss is yours "
                    f"(your notice of assessment's balance), set "
                    f"[estimate] other_losses to it, `tjs run`, then "
                    f"`tjs close-year --force`."), None, "", ""):
                print(_ln)


def _lock_folder_problem(root: Path) -> Optional[str]:
    """Why close-year could not write filed/<year>.json, checked before
    anything is frozen: filed/ is not a folder, or it (or the project
    folder that would hold it) cannot be written. None when it can."""
    import os as _os
    d = root / "filed"
    if d.is_symlink() or d.exists():
        if not d.is_dir():
            return "filed exists and is not a folder"
        if not _os.access(d, _os.W_OK | _os.X_OK):
            return "filed/ cannot be written (Permission denied)"
        return None
    if not _os.access(root, _os.W_OK | _os.X_OK):
        return "the project folder cannot be written (Permission denied)"
    return None


def _config_rewrite_target(root: Path, nothing: str) -> Path:
    """The file close-year writes to rewrite taxjson.toml (its freeze
    and thaw), checked before anything is written, as every editor of a
    user file checks it (lib/safe_write.write_user_file; backlog
    TJ-0918): a link inside the project is followed (the link stays,
    its target is written), a link leaving it is refused, and so is a
    read-only file (made read-only to keep it as it is)."""
    from taxjson.lib.cli_diag import cannot_write
    from taxjson.lib.safe_write import (ReadOnlyFileError, link_outside,
                                        refuse_read_only)
    cfg_path = root / _PL.CONFIG
    tgt = link_outside(cfg_path, root)
    if tgt is not None:
        _die_input(f"{_config_shown(cfg_path)} is a symlink to {tgt}, "
                   f"outside the project — never written through: "
                   f"replace the link with a copy, then close", nothing)
    real = cfg_path.resolve() if cfg_path.is_symlink() else cfg_path
    try:
        refuse_read_only(real)
    except ReadOnlyFileError as e:
        _h, _fix = cannot_write(_config_shown(cfg_path), e, cfg_path)
        _die_input(_h, *([_fix] if _fix else []), nothing)
    return real


_FROZEN_NOTE = ("## frozen by `tjs close-year`: this year reads its "
                "own copy of the exports it was filed from")
# The note above the second key the freeze comments out (the first
# carries _FROZEN_NOTE; the keys need not be adjacent).
_FROZEN_NOTE_2 = "## frozen by `tjs close-year` too"
_FROZEN_NOTE_PREFIX = "## frozen by `tjs close-year`"


def _one_frozen_note(text: str) -> str:
    """The second note dropped when its key directly follows the first
    key: one note reads over both (workflow audit 2026-10)."""
    lines = text.split("\n")
    for i, ln in enumerate(lines[:-2]):
        if ln == _FROZEN_NOTE and lines[i + 2] == _FROZEN_NOTE_2 \
                and lines[i + 1].startswith("# "):
            del lines[i + 2]
            break
    return "\n".join(lines)


def _gitignore_hides_filed_reports(root: Path) -> Optional[str]:
    """The `.gitignore` line (an unanchored `reports/`, the scaffold
    before this release) that also ignores filed/<year>/reports/, else
    None: the reports as filed would never be committed. The project's
    own file, else the one in the folder holding the year folders."""
    for d in (root, root.parent):
        try:
            lines = (d / ".gitignore").read_text(
                encoding="utf-8").splitlines()
        except OSError:
            continue
        for ln in lines:
            if ln.strip() in ("reports/", "reports", "**/reports/"):
                return ln.strip()
        return None
    return None


def _frozen_record(root: Path, year) -> Optional[Dict[str, Any]]:
    """The `frozen` record of filed/<year>.json (what close-year froze:
    the shared settings it replaced and the inputs' hashes), or None
    when the year is not closed, was closed before freezing, or was
    locked before it ended (a `partial` record: hashed only, the year
    still reads the shared folders)."""
    import json as _json
    p = Path(root) / "filed" / f"{year}.json"
    try:
        doc = _json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    fz = doc.get("frozen") if isinstance(doc, dict) else None
    return fz if isinstance(fz, dict) and not fz.get("partial") else None


def _freeze_inputs(root: Path, cfg: Dict[str, Any],
                   settings: Dict[str, Any], year: int, *,
                   nothing: str,
                   previous: Optional[Dict[str, Any]] = None,
                   partial: bool = False,
                   undo: Optional[List[Callable[[], None]]] = None
                   ) -> Dict[str, Any]:
    """close-year's freeze. With exports shared by every year
    (`inputs_dir`), every file the run read (lib/checklist.input_files)
    is copied into this project's own inputs/<account>/, the shared
    tobase.map beside ticker.map, and taxjson.toml stops naming the
    shared ones (commented out under _FROZEN_NOTE; lib/project_layout:
    a project with no `inputs_dir` reads its own inputs/). A project
    that already reads its own files only records them. Returns the
    lock's `frozen` record: the settings replaced (None when none),
    how many files were copied, and the hashes of every input
    (lib/checklist.input_fingerprint) the frozen books come from.
    Refuses (nothing written) when inputs/<account>/ already holds
    files this project does not read, or taxjson.toml cannot be
    edited safely. `partial` (a year that has not ended, locked with
    --force): nothing is copied and taxjson.toml is left alone — the
    year goes on reading the shared exports, so its later trades show
    as drift against the hashes — and the record says `partial`
    (workflow audit 2026-10-23). `undo`: given a list, the freeze
    appends the step that takes it back (the copies removed,
    taxjson.toml as it was), run when the lock is not written (backlog
    TJ-0917)."""
    from taxjson.lib.checklist import (frozen_files, input_files,
                                       input_fingerprint)
    if partial:
        return {"partial": True, "inputs_dir": None, "tobase_map": None,
                "copied": 0,
                "inputs": frozen_files(input_fingerprint(root, cfg))}
    shared = _PL.shared_inputs(root)
    shared_tob = _PL.shared_tobase(root)
    # taxjson.toml is checked before the first copy (backlog TJ-0918).
    cfg_real = (_config_rewrite_target(root, nothing)
                if shared or shared_tob else None)
    # A year frozen before (re-closed with --force) keeps the record
    # of the shared folders it stopped naming: new-year reads it.
    previous = previous if isinstance(previous, dict) else {}
    rec: Dict[str, Any] = {
        "inputs_dir": previous.get("inputs_dir") if not shared else None,
        "tobase_map": previous.get("tobase_map") if not shared_tob
        else None,
        "copied": 0}
    copies: List[Tuple[Path, Path]] = []
    if shared:
        src_dir = _PL.inputs_dir(root)
        own = root / _PL.INPUTS
        busy = []
        for a in sorted(cfg.get("accounts") or {}):
            try:
                if any(p.is_file() for p in (own / a).iterdir()):
                    busy.append(a)
            except OSError:
                continue
        if busy:
            _die(f"inputs/{busy[0]}/ already holds files this project "
                 f"does not read"
                 + (f" (and {len(busy) - 1} more account folder(s))"
                    if len(busy) > 1 else ""),
                 f"close-year copies each account's exports from "
                 f"{_PL.shown(src_dir, root)}/ into this project's "
                 f"inputs/ — move those files away (into the shared "
                 f"folder if they belong to the books), then close. "
                 f"{nothing}")
        from taxjson.lib import crypto_sends as _CS

        def _generated(p: Path) -> bool:
            try:
                return (p.name.lower() == _CS.TT_NAME and (
                    _CS.read_tt(p) or "").startswith(_CS.GENERATED_MARK))
            except ValueError:
                return False

        for p in input_files(root, cfg):
            try:
                rel = p.relative_to(src_dir)
            except ValueError:
                continue            # the project's own files
            if _generated(p):
                # An older taxjson's crypto_sends.tt in the shared
                # folder: the books never read it (_account_tt_files),
                # the frozen year would.
                continue
            copies.append((p, own / rel))
        rec["inputs_dir"] = settings.get(_PL.INPUTS_KEY)
    rec["copied"] = len(copies)             # the exports; tobase.map apart
    if shared:
        # The crypto_sends.tt this year generated in work/ goes where the
        # frozen year reads and writes it, inputs/<account>/, so the lock
        # records it there: else the next run's copy was "a frozen input
        # changed — restore it" for good (backlog TJ-0089).
        for a in sorted(cfg.get("accounts") or {}):
            gen = _CS.tt_path(root, a)
            if gen.is_file():
                copies.append((gen, root / _PL.INPUTS / a / _CS.TT_NAME))
    if shared_tob:
        copies.append((_PL.tobase_map_path(root), root / _PL.TOBASE_MAP))
        rec["tobase_map"] = settings.get(_PL.TOBASE_KEY)
    done: List[Path] = []
    made_dirs: List[Path] = []

    def _undo() -> None:
        for d in done:
            try:
                d.unlink()
            except OSError:
                pass
        # The folders the copies made, deepest first, when empty.
        for d in reversed(made_dirs):
            with contextlib.suppress(OSError):
                d.rmdir()

    src = dst = None
    try:
        for src, dst in copies:
            for _d in reversed([dst.parent, *dst.parent.parents]):
                if root in _d.parents and not _d.exists() \
                        and _d not in made_dirs:
                    made_dirs.append(_d)
            dst.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            shutil.copy2(src, dst)
            done.append(dst)
    except OSError as e:
        _undo()
        _die(f"cannot copy {_PL.shown(src, root)} to "
             f"{_PL.shown(dst, root)}: {e.strerror or e}", nothing)
    cfg_before: Optional[bytes] = None
    if shared or shared_tob:
        cfg_path = root / _PL.CONFIG
        text = _read_config_text(cfg_path)
        bad: List[str] = []
        try:
            if shared:
                text = _PL.set_key_text(
                    text, ("settings", _PL.INPUTS_KEY), None,
                    note=_FROZEN_NOTE)
            if shared_tob:
                text = _PL.set_key_text(
                    text, ("settings", _PL.TOBASE_KEY), None,
                    note=_FROZEN_NOTE_2 if shared else _FROZEN_NOTE)
            if shared and shared_tob:
                text = _one_frozen_note(text)
            bad = _PL.setting_problems(
                root, _PL.parse_toml(text).get("settings") or {})
        except _PL.LayoutError as e:
            bad = [str(e)]
        if bad:
            _undo()
            _die(f"taxjson.toml cannot be pointed at the frozen copy: "
                 f"{bad[0]}", nothing)
        try:
            cfg_before = cfg_real.read_bytes()
            # A link inside the project stays a link: its target is
            # written, with its permission bits (backlog TJ-0918).
            _write_atomic(cfg_real, text, keep_mode=True)
        except OSError as e:
            _undo()
            _die(f"cannot rewrite taxjson.toml: {e.strerror or e}",
                 nothing)
    rec["inputs"] = frozen_files(input_fingerprint(root, cfg))
    if undo is not None:
        def _take_back() -> None:
            if cfg_before is not None and cfg_real is not None:
                try:
                    _write_atomic(cfg_real, cfg_before, keep_mode=True)
                except OSError as e:
                    _say("warning", f"taxjson.toml could not be put back "
                         f"as it was before close-year: "
                         f"{e.strerror or e}",
                         "It no longer names the shared exports: set "
                         "inputs_dir (and tobase_map) again by hand.",
                         prog=f"{_PROG} close-year")
            _undo()
        undo.append(_take_back)
    return rec


def _thaw_text(text: str, keys: Sequence[str]) -> str:
    """taxjson.toml's text with the `keys` (inputs_dir / tobase_map)
    close-year's freeze commented out under its note set again: the
    note dropped, the commented line restored as it was."""
    lines = text.split("\n")
    out: List[str] = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        if ln.strip().startswith(_FROZEN_NOTE_PREFIX):
            j = i + 1
            thawed: List[str] = []
            while j < len(lines):
                m = re.match(r"#\s*(inputs_dir|tobase_map)(\s*=.*)$",
                             lines[j].strip())
                if not m or m.group(1) not in keys:
                    break
                thawed.append(m.group(1) + m.group(2))
                j += 1
            if thawed:
                out += thawed
                i = j
                continue
        out.append(ln)
        i += 1
    return "\n".join(out)


def _thaw_partial_freeze(root: Path, cfg: Dict[str, Any], year: int,
                         old_lock: Any, *, nothing: str) -> None:
    """A lock taken before its year ended by a taxjson that froze it
    anyway (v0.31.0 / v0.31.1): the year reads a copy of the exports as
    they were then, so the rest of the year never reached its books and
    re-closing locked the partial figures (workflow audit 2026-10-23,
    item 7). close-year --force first thaws it — taxjson.toml names the
    shared folders the lock recorded again, the unchanged copies are
    removed, the lock's `frozen` record becomes a `partial` one (hashed
    only) — then stops, so the books are rebuilt from the shared
    exports before the year is closed. Returns when there is nothing to
    thaw; refuses, changing nothing, when a copy was edited or added
    since, or is not in the shared folder."""
    import json as _json
    from taxjson.bin import taxjson_filed
    fz = old_lock.get("frozen") if isinstance(old_lock, dict) else None
    if (not isinstance(fz, dict) or fz.get("partial")
            or not taxjson_filed.partial_year_note(old_lock, year)):
        return
    want: Dict[str, str] = {}
    for key, rk, shared in (
            (_PL.INPUTS_KEY, "inputs_dir", _PL.shared_inputs(root)),
            (_PL.TOBASE_KEY, "tobase_map", _PL.shared_tobase(root))):
        v = fz.get(rk)
        if isinstance(v, str) and v.strip() and not shared:
            want[key] = v
    if not want:
        return
    hashes = fz.get("inputs") if isinstance(fz.get("inputs"), dict) else {}

    def _shared_path(v: str) -> Path:
        q = Path(v).expanduser()
        return q if q.is_absolute() else root / q

    removes: List[Path] = []
    bad: List[str] = []
    if _PL.INPUTS_KEY in want:
        src_dir = _shared_path(want[_PL.INPUTS_KEY])
        own = root / _PL.INPUTS
        for a in sorted(cfg.get("accounts") or {}):
            try:
                files = sorted(p for p in (own / a).iterdir()
                               if p.is_file())
            except OSError:
                continue
            for p in files:
                key = f"{_PL.INPUTS}/{a}/{p.name}"
                try:
                    digest = hashlib.sha256(p.read_bytes()).hexdigest()
                except OSError as e:
                    bad.append(f"{key}: {e.strerror or e}")
                    continue
                if hashes.get(key) != digest:
                    bad.append(f"{key} ("
                               + ("changed since the freeze"
                                  if key in hashes
                                  else "added after the freeze") + ")")
                elif not (src_dir / a / p.name).is_file():
                    bad.append(f"{key} (not in "
                               f"{want[_PL.INPUTS_KEY]}/{a}/)")
                else:
                    removes.append(p)
    if _PL.TOBASE_KEY in want:
        own_tob = root / _PL.TOBASE_MAP
        if own_tob.is_file():
            try:
                digest = hashlib.sha256(own_tob.read_bytes()).hexdigest()
            except OSError as e:
                digest = ""
                bad.append(f"{_PL.TOBASE_MAP}: {e.strerror or e}")
            if digest and digest not in {v for k, v in hashes.items()
                                         if k.endswith(_PL.TOBASE_MAP)}:
                bad.append(f"{_PL.TOBASE_MAP} (changed since the freeze)")
            elif digest and not _shared_path(
                    want[_PL.TOBASE_KEY]).is_file():
                bad.append(f"{_PL.TOBASE_MAP} (no "
                           f"{want[_PL.TOBASE_KEY]})")
            elif digest:
                removes.append(own_tob)
    _at = str(old_lock.get("closed_at") or "")[:10]
    _what = (f"the {year} lock being replaced was taken on {_at}, before "
             f"the year ended, and froze a copy of the exports as they "
             f"were then: the books never got the rest of the year")
    if bad:
        _die(_what, *[f"- {b}" for b in bad[:6]],
             f"Move each into the shared folder (if it belongs to the "
             f"books) or out of the project; close-year then reads the "
             f"shared exports again. {nothing}")
    cfg_path = root / _PL.CONFIG
    text = _thaw_text(_read_config_text(cfg_path), list(want))
    try:
        for key, v in want.items():
            st = _PL.parse_toml(text).get("settings") or {}
            if st.get(key) != v:
                text = _PL.set_key_text(text, ("settings", key), v,
                                        after=_PL.EXPORTS_KEY)
        _st = _PL.parse_toml(text).get("settings") or {}
        # The frozen tobase.map beside the setting goes with the thaw.
        _both = (_PL.tobase_both_problem(root, _st)
                 if root / _PL.TOBASE_MAP in removes else None)
        bad_set = [b for b in _PL.setting_problems(root, _st)
                   if b != _both]
    except _PL.LayoutError as e:
        bad_set = [str(e)]
    if bad_set:
        _die(_what, f"taxjson.toml cannot name the shared folders again: "
             f"{bad_set[0]}", nothing)
    # Written through a link inside the project; a read-only one is
    # refused before anything changes (backlog TJ-0918).
    cfg_real = _config_rewrite_target(root, nothing)
    lock_path = taxjson_filed.snapshot_path(root, year)
    doc = dict(old_lock)
    doc["frozen"] = {"partial": True, "inputs_dir": None,
                     "tobase_map": None, "copied": 0, "inputs": hashes}
    try:
        _write_atomic(cfg_real, text, keep_mode=True)
        _write_atomic(lock_path, _json.dumps(doc, indent=2, sort_keys=True)
                      + "\n")
        for p in removes:
            p.unlink()
        for a in sorted(cfg.get("accounts") or {}):
            with contextlib.suppress(OSError):
                (root / _PL.INPUTS / a).rmdir()
        with contextlib.suppress(OSError):
            (root / _PL.INPUTS).rmdir()
    except OSError as e:
        _die(_what, f"the thaw did not finish: {e.strerror or e}",
             f"Check that taxjson.toml names "
             f"{' and '.join(want.values())} and remove the copies in "
             f"{_PL.INPUTS}/ by hand, then `tjs run` and close.")
    _die(_what,
         f"Thawed: taxjson.toml reads {' and '.join(want.values())} "
         f"again, the {len(removes)} unchanged copied file(s) are "
         f"removed, and the {year} lock is a partial snapshot (its "
         f"inputs hashed, not frozen).",
         f"Run `tjs run` (later trades in {year} now show as drift), "
         f"then close the year after filing. Nothing was locked.")


def _keep_filed_reports(root: Path, year: int, *, prog: str) -> int:
    """The reports as filed: reports/ copied to filed/<year>/reports/
    (replaced on --force), what `tjs compare filed` diffs against.
    Returns the number of files kept (0, with a warning, when the copy
    failed: the lock itself is written)."""
    from taxjson.lib import compare as _cmp
    from taxjson.lib import out as _out
    dest = _cmp.filed_reports_dir(root, year)
    files = _cmp.report_files(root / "reports")
    try:
        tmp = dest.with_name(dest.name + ".part")
        if tmp.exists():
            shutil.rmtree(tmp)
        tmp.mkdir(parents=True, mode=0o700)
        for name, data in files.items():
            _write_atomic(tmp / name, data)
        if dest.exists():
            shutil.rmtree(dest)
        tmp.rename(dest)
    except OSError as e:
        _out.warn(f"the reports as filed were not kept in "
                  f"{_PL.shown(dest, root)}/: {e.strerror or e}",
                  prog=prog, details=["The lock is written; `tjs "
                                      "compare filed` has nothing to "
                                      "diff against."])
        return 0
    return len(files)


def _frozen_summary(rec: Dict[str, Any], kept: int, year: int,
                    details: bool) -> str:
    """close-year's `Frozen:` line: what was copied and where the
    reports as filed are; --details adds what reads them."""
    if rec.get("partial"):
        what = (f"nothing — {year} has not ended: it keeps reading its "
                f"exports, so later trades show as drift; the close "
                f"after filing freezes them")
        if kept:
            what += f"; reports so far: filed/{year}/reports/"
        if details:
            what += (f"; {len(rec.get('inputs') or {})} input file(s) "
                     f"hashed in the lock — `tjs check-filed` names "
                     f"each one that changes")
        return what
    if rec.get("copied"):
        what = (f"inputs/ ({rec['copied']} file(s) copied from "
                f"{rec.get('inputs_dir') or 'the shared folder'}"
                + (f", tobase.map from {rec['tobase_map']}"
                   if rec.get("tobase_map") else "") + ")")
    elif rec.get("tobase_map") and not rec.get("inputs_dir"):
        what = (f"the project's own inputs/; tobase.map copied from "
                f"{rec['tobase_map']}")
    else:
        what = "the project's own inputs/" + (
            f" (frozen earlier from {rec['inputs_dir']})"
            if rec.get("inputs_dir") else "")
    if kept:
        what += f"; reports as filed: filed/{year}/reports/"
    if details:
        what += (f"; {len(rec.get('inputs') or {})} input file(s) hashed "
                 f"in the lock — taxjson.toml reads the copy from now on, "
                 f"`tjs check-filed` says when a frozen input "
                 f"changes, `tjs compare filed` diffs the reports")
    return what


def _carryforwards_for_lock(root: Path, cfg: Dict[str, Any],
                            details: bool = True,
                            filed_totals: Optional[Dict[str, Any]] = None
                            ) -> Optional[Dict[str, Any]]:
    """The `carryforwards` block close-year writes (lib/carryforward):
    the year's net capital loss (Canada) or ST/LT capital loss
    carryover (USA), and the Canadian minimum tax carryover — from the
    estimate itself (`tjs estimate --json`, the computation `amt`
    prints), with the inputs the project gives it. A Canada project
    with no supported province gets a federal-only estimate (no other
    province's tables stand in; every figure the block carries forward
    is federal), with a note. A failing estimate stops the close (its
    inputs are wrong), naming the reason. `filed_totals` (Canada; the
    dispositions filed with another tool, --filed-dispositions): the
    net capital loss is the filed return's — its gain stands in for
    the books' dispositions (CA-CARRY-01)."""
    import json as _json
    from taxjson.lib import carryforward as CF
    from taxjson.lib.dispatch import run_cmd as _run
    from taxjson.lib.tax_estimate import _VINTAGES
    settings = cfg.get("settings") or {}
    country = _country(settings)
    argv = _self_cmd(root, "estimate", "--json")
    prov = str(settings.get("province") or "").strip().upper()
    federal_only = False
    if country == "canada" and prov not in {
            k for v in _VINTAGES.values() for k in v["CA_PROVINCES"]}:
        argv += ["--federal-only"]
        federal_only = True
        from taxjson.lib.out import fill as _fill
        from taxjson.lib.out import label as _label
        from taxjson.lib.out import show as _show, width as _ow
        _show(_fill(_label("note", stream=sys.stdout)
                    + (f"province {prov} is not modelled" if prov else
                       "no [settings] province")
                    + (" — the carry-forwards are computed federal-only "
                       "(no provincial tax or minimum-tax recovery)."
                       if details else
                       " — the carry-forwards are federal-only."),
                    hang="  " if _ow(sys.stdout) <= 0 else "").split("\n"),
              sys.stdout)
    res = _run(argv, capture_output=True)
    if res.returncode != 0:
        _die("could not compute the carry-forwards the lock records (the "
             "estimate failed)", _child_error(res.stderr),
             "Fix the input, then close. Nothing was written.")
    _doc = _json.loads(res.stdout) or {}
    r = _doc.get("estimate") or {}
    est_cfg = cfg.get("estimate") if isinstance(cfg.get("estimate"),
                                                dict) else {}
    src = dict(r.get("carry_sources") or {})
    src["other_income_entered"] = "other_income" in (est_cfg or {})
    src["other_income_value"] = (est_cfg or {}).get("other_income") or 0.0
    block = CF.record_block(country, r, src)
    ncl = block.get("net_capital_loss")
    if (isinstance(ncl, dict) and isinstance(filed_totals, dict)
            and filed_totals.get("gain") is not None):
        _as_filed(ncl, _doc, float(filed_totals["gain"]))
    if isinstance(ncl, dict):
        # The estimate's own figure (`losses_carried_back`, from the one
        # ledger build): min(the carry-back, the books' loss). Only a
        # filed loss above the books' one, with the carry-back capped
        # there, needs the whole carry-back: the ledger is built again
        # just then (backlog TJ-0273), or for an estimate without the
        # figure.
        back = float(r.get("losses_carried_back") or 0.0)
        unused = float(r.get("losses_unused") or 0.0)
        if "losses_carried_back" not in r or (
                back >= unused - 0.005
                and float(ncl.get("closing") or 0.0) > unused + 0.005
                and _claims_back(cfg, settings.get("year"))):
            back = _carried_back(root, int(settings.get("year") or 0))
        if back > 0.005:
            # A T1A carry-back of this year's loss ([carryover] claimed
            # under an earlier year) leaves it with the next year: the
            # estimate never reads it, and the lock carried the whole
            # loss forward, so it was claimed twice. At most the loss
            # the lock holds (a filed loss below the books' one): the
            # rest of the claim stays for a later year's loss.
            back = min(back, float(ncl["closing"]))
            ncl["carried_back"] = round(back, 2)
            ncl["closing"] = round(max(0.0, ncl["closing"] - back), 2)
    mt = block.get("minimum_tax")
    if federal_only and isinstance(mt, dict):
        mt["province"] = None
        mt.pop("recovered_provincial", None)
        mt.pop("recovered_provincial_credit", None)
        mt.pop("recovered_provincial_surtax", None)
    return block


def _as_filed(ncl: Dict[str, Any], doc: Dict[str, Any],
              filed_gain: float) -> None:
    """Make the lock's net capital loss block `ncl` the filed return's:
    the dispositions filed with another tool (gain `filed_gain`) stand
    in for the books' (`doc`, the year's `estimate --json`); the T5 box
    18 capital gains the estimate adds stay. The next year's carryover
    reads the filed gain from the lock, so the balance the lock carries
    out comes from it too (workflow audit 2026-10-23 item 4)."""
    filing = (doc.get("filing") or {}).get("totals") or {}
    books = filing.get("gain")
    if books is None:
        books = (doc.get("totals") or {}).get("realized")
    if books is None:
        return
    books = float(books)
    if abs(books - filed_gain) <= 0.005:
        return
    est = doc.get("estimate") or {}
    realized = (filed_gain + float(est.get("capital_gains_dividends")
                                   or 0.0))
    opening = float(ncl.get("opening") or 0.0)
    ncl["created"] = round(max(0.0, -realized), 2)
    ncl["applied"] = round(min(max(0.0, realized), opening), 2)
    ncl["closing"] = round(max(0.0, opening - realized), 2)
    ncl["filed_gain"] = round(filed_gain, 2)
    ncl["books_gain"] = round(books, 2)


def _carried_back(root: Path, year: int) -> float:
    """How much of `year`'s net capital loss `tjs carryover` finds
    carried back by [carryover] claimed (lines under earlier years); 0.0
    when there is none or the ledger cannot be built."""
    return sum(float(x.get("carried_back") or 0.0)
               for x in _ledger_rows(root, year))


def _carried_back_to(root: Path, year: int) -> Dict[int, float]:
    """{earlier year: the part of `year`'s net capital loss `tjs
    carryover` carries back to it} ([carryover] claimed under that
    year, a T1A carry-back); {} when there is none or the ledger cannot
    be built."""
    out: Dict[int, float] = {}
    for x in _ledger_rows(root, year):
        for y, a in (x.get("carried_back_to") or {}).items():
            out[int(y)] = out.get(int(y), 0.0) + float(a)
    return out


def _ledger_rows(root: Path, year: int,
                 before: bool = False) -> List[Dict[str, Any]]:
    """`year`'s rows of `tjs carryover --json` ([] when the ledger
    cannot be built); `before`: the rows of the years before it."""
    import json as _json
    from taxjson.lib.dispatch import run_cmd as _run
    if not year:
        return []
    res = _run(_self_cmd(root, "carryover", "--json"), capture_output=True)
    if res.returncode != 0:
        return []
    try:
        rows = (_json.loads(res.stdout) or {}).get("rows") or []
    except ValueError:
        return []
    return [x for x in rows if isinstance(x, dict)
            and isinstance(x.get("year"), int)
            and (x["year"] < year if before else x["year"] == year)]


def _books_loss_not_carried(root: Path, cf: Dict[str, Any],
                            year: int) -> Optional[float]:
    """The net capital loss `tjs carryover` finds carried into
    `year` from the books' earlier years when the lock's block `cf`
    took none in (no [estimate] other_losses, no earlier close-year
    record: it starts from 0); None when it took one in, or the books
    show none. A first year with taxjson locked 0 carried forward in
    silence while the same project's ledger showed the loss (backlog
    TJ-0431)."""
    ncl = cf.get("net_capital_loss") if isinstance(cf, dict) else None
    if not isinstance(ncl, dict) or str(ncl.get("opening_source")
                                        or "none") != "none" \
            or abs(float(ncl.get("opening") or 0.0)) > 0.005:
        return None
    rows = _ledger_rows(root, year, before=True)
    bal = float((rows[-1] if rows else {}).get("carryforward_balance")
                or 0.0)
    return bal if bal > 0.005 else None


def _claims_back(cfg: Dict[str, Any], year: Any) -> bool:
    """True when [carryover] claimed has an entry under one of the 3
    years before `year`: a T1A carry-back of `year`'s loss may be
    recorded, which only the carryover ledger can tell."""
    from taxjson.lib.project_tables import claimed_losses
    try:
        y = int(year)
        claimed = claimed_losses(cfg)[0]
    except (TypeError, ValueError, SystemExit):
        return False
    return any(y - 3 <= int(c) < y and float(a) > 0.005
               for c, a in claimed.items())


def _losses_carried_back(root: Optional[Path], cfg: Dict[str, Any],
                         year: Any, losses_unused: float) -> float:
    """Of the estimate's unused capital losses (Canada), the part
    [carryover] claimed carries back (T1A), as `tjs carryover` folds
    it: what the estimate prints and its --json carries
    (`losses_carried_back`; backlog TJ-0084, TJ-0226). 0.0 with no
    claim under an earlier year (the ledger is not built then)."""
    if not losses_unused or root is None or not _claims_back(cfg, year):
        return 0.0
    return min(_carried_back(root, int(year)), losses_unused)


def _carryforwards_summary(cf: Dict[str, Any], year: int,
                           details: bool = True) -> List[str]:
    """close-year's lines on what the lock carries into year + 1
    (`details`: the notes in full and what reads them)."""
    from taxjson.lib.out import kv_lines, labelled, wrap
    kv: List[Tuple[str, str]] = []
    notes: List[str] = []
    ncl = cf.get("net_capital_loss")
    if isinstance(ncl, dict):
        kv.append(("Net capital loss",
                   f"applied {ncl['applied']:,.2f}, created "
                   f"{ncl['created']:,.2f}"
                   + (f" (as filed: gain {ncl['filed_gain']:,.2f}; the "
                      f"books {ncl['books_gain']:,.2f})"
                      if ncl.get("filed_gain") is not None else "")
                   + (f", carried back {ncl['carried_back']:,.2f}"
                      if ncl.get("carried_back") else "")
                   + f", carried into {year + 1}: "
                   f"{ncl['closing']:,.2f} (100% amounts)"))
    cl = cf.get("capital_loss")
    if isinstance(cl, dict):
        from taxjson.lib.carryforward import CLAIMED_KEY
        _claimed = cl.get("deduction_from") == CLAIMED_KEY
        kv.append((f"Capital loss carryover into {year + 1}",
                   f"short-term {cl['st_closing']:,.2f}, long-term "
                   f"{cl['lt_closing']:,.2f}"))
        if _claimed:
            kv.append((f"Deducted in {year}",
                       f"{cl['deduction_used']:,.2f} ({CLAIMED_KEY})"))
        _avail = float(cl.get("deduction_available") or 0.0)
        _used = float(cl.get("deduction_used") or 0.0)
        if not _claimed and not cl.get("other_income_entered") \
                and "deduction_used" in cl and _avail - _used > 0.005:
            # The lock counts the deduction as used only as far as the
            # estimate's taxable income absorbs it: with no other income
            # entered, none of it (backlog TJ-0464).
            notes.append(
                f"note: no [estimate] other_income and no {CLAIMED_KEY} "
                f"entry for {year}: {_used:,.2f} of the {_avail:,.2f} "
                f"deduction against ordinary income is counted as used"
                + (", so the carryover above is too high if your return "
                   "took more. Record the Schedule D line 21 deduction "
                   f"your return took under {CLAIMED_KEY} (or set "
                   f"[estimate] other_income), then close {year} again "
                   f"with --force." if details else
                   f" — record your return's under {CLAIMED_KEY} and "
                   f"close again with --force."))
        _s1256 = float(cl.get("section_1256_gain") or 0.0)
        if details and abs(_s1256) > 0.005 and (
                float(cl.get("st_closing") or 0.0)
                + float(cl.get("lt_closing") or 0.0) > 0.005):
            # The carryover took the §1256 net as Form 6781 splits it
            # (US-FUT-03; backlog TJ-0466); what is still by hand.
            notes.append(
                f"note: the carryover takes the {year} §1256 net, "
                f"{_s1256:,.2f}, as Form 6781 splits it: "
                f"{float(cl.get('section_1256_short_term') or 0.0):,.2f} "
                f"short-term (40%), "
                f"{float(cl.get('section_1256_long_term') or 0.0):,.2f} "
                f"long-term (60%). Not modelled: a contract still open "
                f"at Dec 31 is not marked to market, and a net §1256 loss "
                f"is not carried back (§1212(c)); check Form 6781 against "
                f"your 1099-B.")
    mt = cf.get("minimum_tax")
    if isinstance(mt, dict):
        kv.append(("Minimum tax",
                   f"recovered {mt['recovered_federal']:,.2f}, created "
                   f"{mt['created']:,.2f}, carried into {year + 1}: "
                   f"{mt['closing']:,.2f}"))
        if not mt.get("other_income_entered") and details:
            notes.append("note: the minimum tax was computed with no "
                         "[estimate] other_income — compare it with the "
                         "T691 you filed; the next project's [estimate] "
                         "amt_carryover (from your notice of assessment) "
                         "wins over this record.")
        elif not mt.get("other_income_entered"):
            notes.append("note: no [estimate] other_income — compare the "
                         "minimum tax with the T691 you filed.")
    if not kv:
        return []
    out = ["", f"CARRIED INTO {year + 1}"] + kv_lines(kv, indent="  ")
    if notes:
        # A message, not a row of the block: flush-left under it.
        out.append("")
    for i, n in enumerate(notes):
        block = wrap(labelled(n), None, "", "")
        out += block
        if len(block) > 1 and i + 1 < len(notes):
            out.append("")      # one blank line after a wrapped message
    if details:
        # `amt` reads the minimum tax block only (Canada): a US lock has
        # none, and `amt` refuses a US project (backlog TJ-0473).
        out += wrap(f"The {year + 1} project's estimate"
                    + (", carryover and amt" if isinstance(mt, dict)
                       else " and carryover")
                    + " read these; its handoff checks its inputs "
                    "against them.", None, "  ", "  ")
    return out


def _handoff_gains_flags(settings: Dict[str, Any],
                         cache: Optional[Path] = None) -> List[str]:
    """The taxjson-gains flags a full-history run of this project uses
    (no --year: the hand-off needs every year's pools); `cache`, the
    project's work/, adds its .tt ALLOWLOSS positions."""
    from taxjson.lib.pipeline import option_timing_flags
    country = _country(settings)
    flags = ["--country", country, "--tax-date", _tax_date(settings)]
    if country in ("us", "usa"):
        flags.append("--per-account-basis")
    return (flags + option_timing_flags(settings)
            + income_dating_flags(settings)
            + (_loss_override_flags(cache) if cache is not None else []))


def _prior_record_path(root: Path, settings: Dict[str, Any],
                       override: Optional[str]) -> Path:
    if override:
        return Path(override).expanduser()
    from taxjson.bin.taxjson_filed import (PriorRecordError,
                                           prior_record_setting)
    try:
        p = prior_record_setting(root, settings)
    except PriorRecordError as e:
        # The same refusal `tjs run` gives — not "no prior-year
        # record at <root>/5" (A2-1135).
        _die(str(e))
    if p is not None:
        return p
    year = settings.get("year")
    if not isinstance(year, int) or isinstance(year, bool):
        # It looked for filed/-1.json (A2-1162).
        _die("[settings] year is required in taxjson.toml",
             "The hand-off is from the year before it; or pass --prior.")
    return root / "filed" / f"{year - 1}.json"


def _handoff_positions(rep: Dict[str, Any], cache: Path, ry: int,
                       settings: Dict[str, Any]) -> None:
    """The .tt ALLOWLOSS filing positions on sales up to the closed
    year `ry` (CA-SL-18 / US-WASH-25): they shape the opening cost the
    hand-off compares (no ACB / basis raised for the replacement), so
    the report names them (`filing_positions` and a note; pre-release
    review). The closed year's project must take the same position."""
    from taxjson.lib import loss_overrides as _LO
    from taxjson.lib.report_model import resolve_gains_files
    if not _LO.read_state(cache):
        return
    key = "date" if _tax_date_basis(settings) == "trade" else "date_settle"
    fps = [fp for fp in _LO.positions(_LO.gather(resolve_gains_files(cache)))
           if str(fp.get(key) or fp.get("date"))[:4] <= str(ry)]
    if not fps:
        return
    rep["filing_positions"] = [
        {k: v for k, v in fp.items() if k != "in_year"} for fp in fps]
    us = _country(settings) in ("us", "usa")
    rep.setdefault("notes", []).append(
        f"{len(fps)} filing position(s) taken against the "
        + ("wash-sale rule (§1091)" if us else "superficial-loss rule (s.54)")
        + f" on sales up to {ry} (.tt ALLOWLOSS): "
        + "; ".join(f"{fp['date']} {fp['symbol']}, the rule would "
                    f"{'disallow' if us else 'deny'} "
                    f"{fp['would_disallow']:,.2f} ({fp['where']})"
                    for fp in fps)
        + f". The opening " + ("basis" if us else "ACB")
        + " here carries no denied loss for them; the " + str(ry)
        + " project must hold the same line, or its closing cost differs.")


def cmd_handoff(args: argparse.Namespace) -> None:
    """`tjs handoff`: check this project against the previous year's
    close-year record — opening positions and cost at Dec 31, trades
    that settle across Dec 31, and sales reported in both years
    (lib/handoff). Exit 1 on any problem."""
    from taxjson.lib import handoff as _handoff
    from taxjson.lib import out as _out
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    settings = cfg["settings"]
    rp = _prior_record_path(root, settings, args.prior)
    _rp_label = _out.relpath(rp, root)
    if not rp.exists():
        # A missing named input: exit 2, not handoff's "problems found"
        # code 1 (re-audit A2-0164). A filed year's deleted lock says so,
        # not to set prior_year_record (backlog TJ-0272).
        from taxjson.bin.taxjson_filed import missing_lock_problem
        _gone = missing_lock_problem(
            rp, _rp_label if args.prior else
            f"[settings] prior_year_record "
            f"({settings.get('prior_year_record')})")
        if _gone:
            _die_input(_gone)
        _die_input(f"no prior-year record at {_rp_label}",
                   "Run `tjs close-year` in the previous year's "
                   "project, then set [settings] prior_year_record to its "
                   "filed/<year>.json (or pass --prior).")
    # A truncated, non-UTF-8, unreadable or wrong-shape record, or a field
    # of the wrong type: one line naming it, exit 2 (re-audit A2-0162,
    # A2-0473, A2-0475, A2-0476, A2-0803; a BOM is accepted, A2-0776).
    try:
        record = _handoff.load_record(rp)
    except _handoff.RecordError as e:
        _die_input(str(e))
    _rprob = _handoff.record_problem(record)
    if _rprob:
        _die_input(f"{_rp_label}: not a usable close-year record: "
                   f"{_rprob}",
                   "Restore it (or re-close that year with `tjs "
                   "close-year --force` in its project).")
    from taxjson.bin.taxjson_filed import lock_country_problem
    _cp = lock_country_problem(record, settings, str(rp), prior=True)
    if _cp:
        # The other country's closing positions and cost are not this
        # project's opening (a different basis rule and wash rule):
        # "keep or amend" advice on them would be wrong (COMMANDS-08).
        _die(_cp)
    if int(record.get("schema_version") or 1) < 2 \
            or "year_end" not in record:
        _die(f"{_rp_label} is a version-1 lock (totals only)",
             "Re-close that year with the current taxjson (`tjs "
             "close-year --force` in its project) to record positions — "
             "run `tjs check-filed` there first: if it reports "
             "DRIFTED, the re-close would replace the filed totals, so "
             "resolve the drift (or amend) before re-closing.")
    ry = int(record["year"])
    # A record of another year than the one before this project's is a
    # problem of the record in the report (lib/handoff.check; backlog
    # TJ-0555), not a note beside a clean verdict.
    if not (root / "work").is_dir():
        _die("no work/", "Run `tjs run` first.")
    from taxjson.lib.income_dating import IncomeRulesError
    try:
        _hflags = _handoff_gains_flags(settings, root / "work")
    except IncomeRulesError as e:
        # A bad [settings] corporate_distributions & co.: one line, as
        # divs-sum gives it (re-audit A2-0802).
        _die(str(e))
    try:
        # A US project's lots at that Dec 31 too (backlog TJ-0554).
        _open_lots: Dict[str, Any] = {}
        opening = _handoff.snapshot(root / "work", cfg, f"{ry}-12-31",
                                    _filed_run_gains, _hflags,
                                    _missing_history_arg(root),
                                    lots_out=_open_lots)
        # A claim under the closed year that this project's own loss
        # carries back (T1A) is not a difference from its record: the
        # record was closed before the carry-back (backlog TJ-0078).
        _back_to = (_carried_back_to(root, int(settings.get("year") or 0))
                    if _country(settings) == "canada"
                    and _claims_back(cfg, settings.get("year")) else {})
        rep = _handoff.check(root, cfg, record, opening,
                             carried_back_to=_back_to,
                             opening_lots=_open_lots)
    except _handoff.BooksError as e:
        # Not a fabricated "a lot or a sale is missing" (A2-1137).
        _die(str(e))
    _handoff_positions(rep, root / "work", ry, settings)
    if getattr(args, "json", False):
        _json_out(dict(rep, record=str(rp)))
    else:
        for ln in _handoff.render(rep, _rp_label,
                                  int(settings.get("year") or 0) or None):
            print(ln)
    if rep["problems"]:
        raise SystemExit(1)


def _child_error_line(e: BaseException) -> str:
    """One line for a failed sub-tool: the child's own last error line,
    never the CalledProcessError repr with the full argv (A2-0676)."""
    if isinstance(e, subprocess.CalledProcessError):
        lines = [ln.strip() for ln in str(e.stderr or "").splitlines()
                 if ln.strip()]
        if lines:
            return lines[-1]
        return f"the gains engine exited {e.returncode}"
    return f"{type(e).__name__}: {e}"


def _frozen_inputs_changed(root: Path, frozen: Dict[str, str]
                           ) -> List[str]:
    """The frozen inputs (a lock's `frozen.inputs` hashes) that differ
    from the project's files now: changed, added or missing, by name.
    [] when the project cannot be fingerprinted."""
    from taxjson.lib.checklist import (fingerprint_changes,
                                       unrecorded_generated)
    try:
        now = _soft_fingerprint(root)
    except Exception:                                   # noqa: BLE001
        return []
    if now is None:
        return []
    return fingerprint_changes(frozen,
                               unrecorded_generated(root, frozen, now))


# A date on an export line, in each form a supported export writes
# (the parsers' date formats): the year is the group named `y`; `m`
# and `d`, when there, are checked as a month and a day (YYYYMMDD and
# YYYY/MM/DD are also a run of digits); a 2-digit year reads as
# strptime's %y does.
_LINE_MONTH = r"(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)"
_LINE_DATE_RES = tuple(re.compile(p, re.IGNORECASE) for p in (
    # ISO (Questrade, Kraken, Coinbase, IB, .tt lines)
    r"(?<!\d)(?P<y>(?:19|20)\d\d)-\d\d-\d\d(?!\d)",
    # YYYYMMDD (IB Flex)
    r"(?<!\d)(?P<y>(?:19|20)\d\d)(?P<m>\d\d)(?P<d>\d\d)(?!\d)",
    # YYYY/MM/DD (RBC Direct)
    r"(?<![\d/])(?P<y>(?:19|20)\d\d)/(?P<m>\d\d?)/(?P<d>\d\d?)(?!\d)",
    # M/D/YYYY or D/M/YYYY (RBC Direct, a generic mapping)
    r"(?<![\d/])\d{1,2}/\d{1,2}/(?P<y>(?:19|20)\d\d)(?!\d)",
    # DD-MM-YYYY (Webull; backlog TJ-0574) or MM-DD-YYYY
    r"(?<![\d-])\d{1,2}-\d{1,2}-(?P<y>(?:19|20)\d\d)(?!\d)",
    # D.M.YYYY (a generic mapping)
    r"(?<![\d.])\d{1,2}\.\d{1,2}\.(?P<y>(?:19|20)\d\d)(?!\d)",
    # January 30, 2025 / Jan 30, 2025 (RBC Direct)
    rf"(?<![a-z]){_LINE_MONTH}[a-z]*\.? \d{{1,2}}, "
    rf"(?P<y>(?:19|20)\d\d)(?!\d)",
    # 10-Jan-22 / 10-Jan-2022 (RBC Direct)
    rf"(?<!\d)\d{{1,2}}-{_LINE_MONTH}-(?P<y>(?:19|20)\d\d|\d\d)(?!\d)",
))


def _line_year(line: str) -> Optional[int]:
    """The earliest year an export line is dated in (a row's trade
    date, before its settlement date), None for a line with no date (a
    header, a total). Every date form a supported export writes counts
    (_LINE_DATE_RES): a Webull row's DD-MM-YYYY was no date, so a
    correction of it showed nowhere (backlog TJ-0574)."""
    years = []
    for rx in _LINE_DATE_RES:
        for m in rx.finditer(line):
            g = m.groupdict()
            if g.get("m") is not None and not (
                    1 <= int(g["m"]) <= 12 and 1 <= int(g["d"]) <= 31):
                continue
            y = int(g["y"])
            if len(g["y"]) == 2:
                y += 2000 if y < 69 else 1900
            years.append(y)
    return min(years) if years else None


def _frozen_year_accounts(root: Path, fz: Dict[str, Any]) -> List[str]:
    """The accounts of a year closed with its inputs frozen: those the
    freeze copied a file of (the lock's inputs/<account>/<file> keys)
    and those its taxjson.toml names (an account with no export at the
    close). Only the frozen ones when taxjson.toml cannot be read."""
    pre = f"{_PL.INPUTS}/"
    out = {k[len(pre):].split("/")[0] for k in (fz.get("inputs") or {})
           if k.startswith(pre) and k.count("/") == 2}
    try:
        doc = tomllib.loads((root / "taxjson.toml").read_text(
            encoding="utf-8-sig")) if tomllib is not None else {}
    except Exception:                                   # noqa: BLE001
        doc = {}
    accts = doc.get("accounts") if isinstance(doc, dict) else None
    if isinstance(accts, dict):
        out |= {str(a) for a in accts if str(a) and "/" not in str(a)}
    return sorted(out)


def _frozen_shared_src(root: Path, fz: Dict[str, Any]) -> Optional[Path]:
    """The shared folder a filed year's frozen inputs were copied from:
    the lock's `inputs_dir`; for a year frozen as a single folder and
    then moved by `migrate --to-years` (its lock names none), the
    inputs/ beside the year folders the later years read, as new-year
    and check-dates take it (lib/project_layout.migrated_shared_inputs;
    backlog TJ-0610). None for a partial lock or no shared folder."""
    if fz.get("partial"):
        return None
    v = fz.get("inputs_dir")
    if isinstance(v, str) and v.strip():
        src = Path(v.strip()).expanduser()
        return src if src.is_absolute() else root / src
    return _PL.migrated_shared_inputs(root, fz)


def _shared_exports_moved(root: Path, fz: Dict[str, Any], year: int
                          ) -> List[str]:
    """The shared exports whose rows of `year` or earlier differ from
    what the filed year was closed with (_shared_inputs_moved's
    `exports`)."""
    return _shared_inputs_moved(root, fz, year)["exports"]


def _shared_inputs_moved(root: Path, fz: Dict[str, Any], year: int
                         ) -> Dict[str, List[Any]]:
    """What changed for `year` in the shared folder a filed year's
    inputs were frozen from, each file shown from `root`:

    `exports` — the shared exports whose rows of `year` or earlier
    differ from what the filed year was closed with: each .csv / .tt
    of the lock's frozen inputs (inputs/<account>/<file>) against its
    namesake in the shared folder the freeze copied it from
    (`inputs_dir`), row by row and counting repeats — a row of the year
    changed, removed (one of two identical rows too, backlog TJ-0587)
    or added (the late-December trades a re-download has, backlog
    TJ-0421) — and each export put in an account's shared folder since
    the close that holds a row of the year no frozen copy of the
    account has (TJ-0421). A correction saved there (a sale's proceeds,
    the cost of a lot sold that year, a missing sale) reaches neither
    the filed year, which reads its copy, nor the next year's handoff,
    which compares Dec 31 positions and cost (backlog TJ-0091). Rows of
    later years are no difference, nor is a row added to one file that
    another frozen copy of the account has (a moved row); a namesake no
    longer there is not judged. Each file is read as the parsers read
    it (brokerages/base.decode_broker_text): a UTF-16 export was read
    as UTF-8, no row of it had a date, and its correction showed
    nowhere (backlog TJ-0707).

    `mappings` — the shared generic mappings (<csv>.toml, generic.toml)
    that now read a frozen CSV holding a row of `year` or earlier
    otherwise than the mapping the year was closed with (another
    column, action or format; a mapping new since the close): the CSV's
    bytes are the same, its figures are not (backlog TJ-0708). Which
    mapping reads a CSV: brokerages/detect.generic_mapping, on both
    sides; the mappings are compared as parsed TOML (a comment or the
    layout is no difference).

    `unread` — [(file, why)]: a file of the comparison that could not
    be read (not UTF-8 or UTF-16 text, not TOML, no permission): not
    judged, so named, never passed as unchanged (TJ-0707).

    The shared folder: _frozen_shared_src (a year frozen as a single
    folder, then migrated: ../inputs, backlog TJ-0610)."""
    from collections import Counter
    from taxjson.lib import crypto_sends as _CS
    from taxjson.lib.brokerages.base import (BrokerageParseError,
                                             decode_broker_text)
    from taxjson.lib.brokerages.detect import generic_mapping
    from taxjson.lib.checklist import _skipped_input_name
    res: Dict[str, List[Any]] = {"exports": [], "mappings": [],
                                 "unread": []}
    src = _frozen_shared_src(root, fz)
    if src is None:
        return res
    pre = f"{_PL.INPUTS}/"

    def _export(name: str) -> bool:
        return (Path(name).suffix.lower() in (".csv", ".tt")
                and name.lower() != _CS.TT_NAME
                and not _skipped_input_name(name))

    def _why(e: BaseException) -> str:
        if isinstance(e, BrokerageParseError):
            return "not UTF-8 or UTF-16 text"
        if isinstance(e, OSError):
            return str(e.strerror or e)
        return " ".join(str(e).split())

    def _rows(p: Path) -> "Counter[str]":
        """The rows of `year` or earlier, each with its count.
        OSError / BrokerageParseError when it cannot be read."""
        out: "Counter[str]" = Counter()
        for ln in decode_broker_text(p.read_bytes(), p.name).splitlines():
            ln = ln.rstrip()
            if not ln.strip() or (p.suffix.lower() == ".tt"
                                  and ln.lstrip().startswith("#")):
                continue
            if (_line_year(ln) or year + 1) <= year:
                out[ln] += 1
        return out

    def _mapping(p: Path) -> Any:
        """A generic mapping as the importer parses it (utf-8-sig)."""
        if tomllib is None:                     # pragma: no cover
            raise ValueError("TOML support unavailable")
        try:
            return tomllib.loads(p.read_text(encoding="utf-8-sig"))
        except UnicodeDecodeError:
            raise ValueError("not UTF-8 text") from None
        except tomllib.TOMLDecodeError as e:
            raise ValueError(f"not TOML ({e})") from None

    def _unread(p: Path, e: BaseException) -> None:
        item = (_PL.shown(p, root), _why(e))
        if item not in res["unread"]:
            res["unread"].append(item)

    frozen: Dict[str, List[str]] = {}
    for key in fz.get("inputs") or {}:
        if key.startswith(pre) and key.count("/") == 2:
            acct, name = key[len(pre):].split("/")
            frozen.setdefault(acct, []).append(name)
    for acct in _frozen_year_accounts(root, fz):
        names = sorted(n for n in frozen.get(acct, []) if _export(n))
        mine: Dict[str, "Counter[str]"] = {}
        for n in names:
            p = root / _PL.INPUTS / acct / n
            try:
                mine[n] = _rows(p)
            except FileNotFoundError:
                continue            # the frozen-input check names it
            except (OSError, BrokerageParseError) as e:
                _unread(p, e)
        folder = src / acct
        try:
            added_files = sorted(p.name for p in folder.iterdir()
                                 if p.is_file() and _export(p.name)
                                 and p.name not in frozen.get(acct, []))
        except (FileNotFoundError, NotADirectoryError):
            added_files = []
        except OSError as e:
            _unread(folder, e)
            added_files = []
        for n in [x for x in names if x in mine] + added_files:
            theirs = folder / n
            try:
                if not theirs.is_file():
                    continue
                if n in mine and (root / _PL.INPUTS / acct / n
                                  ).read_bytes() == theirs.read_bytes():
                    continue
                have = _rows(theirs)
            except (OSError, BrokerageParseError) as e:
                _unread(theirs, e)
                continue
            had = mine.get(n, Counter())
            # A row another frozen copy of the account has is not new
            # to the year (moved between files, an overlapping export).
            others = {ln for m, c in mine.items() if m != n for ln in c}
            if (had - have) or any(ln not in others
                                   for ln in (have - had)):
                res["exports"].append(_PL.shown(theirs, root))
        # The generic mapping each frozen CSV of the year is read with,
        # then and now (a CSV that could not be read counts as one of
        # the year: it is not known to hold none).
        for n in names:
            if Path(n).suffix.lower() != ".csv" or (
                    n in mine and not mine[n]):
                continue
            then = generic_mapping(root / _PL.INPUTS / acct / n)
            now = (generic_mapping(folder / n)
                   if (folder / n).is_file() else None)
            if now is None:
                continue            # no longer there: not judged
            shown = _PL.shown(now, root)
            if shown in res["mappings"]:
                continue
            try:
                if not now.is_file():
                    continue        # a dangling link: the run says so
                if (then is not None and then.is_file()
                        and then.read_bytes() == now.read_bytes()):
                    continue
                theirs_doc = _mapping(now)
            except (OSError, ValueError) as e:
                _unread(now, e)
                continue
            try:
                mine_doc = (_mapping(then) if then is not None
                            and then.is_file() else None)
            except (OSError, ValueError) as e:
                _unread(then, e)
                continue
            if mine_doc != theirs_doc:
                res["mappings"].append(shown)
    return res


# The decisions files a frozen year copied from the shared folder, and
# the table of entries each keeps (lib/corp_actions.Manifest,
# lib/crypto_sends.load_decisions).
_DECISION_FILES = {"manifest.json": "elections", "sends.json": "sends"}
_ENTRY_DATE_RE = re.compile(r"(?<!\d)((?:19|20)\d{2})-[01]\d-[0-3]\d(?!\d)")


def _decisions_moved(mine: Optional[Path], theirs: Path, table: str,
                     year: int) -> List[str]:
    """The entries (ids) of a shared decisions file that differ from
    the filed year's frozen copy `mine` (None: it had none) and concern
    `year` or earlier: a decision changed, removed or added since the
    close. Later years rewrite these files whole, so the comparison is
    per entry, never of the bytes (backlog TJ-0211): an entry dated
    after `year` (the date in its summary — an election's event, a
    send's — else in its id) is no difference, nor is an added one with
    no date. ValueError / OSError when a file cannot be read."""
    import json as _json

    def _entries(p: Optional[Path]) -> Dict[str, Any]:
        if p is None:
            return {}
        doc = _json.loads(p.read_text(encoding="utf-8-sig"))
        t = doc.get(table) if isinstance(doc, dict) else None
        return t if isinstance(t, dict) else {}
    a, b = _entries(mine), _entries(theirs)
    out = []
    for k in sorted(set(a) | set(b)):
        if a.get(k) == b.get(k):
            continue
        years = [int(m.group(1)) for v in (a.get(k), b.get(k))
                 if isinstance(v, dict)
                 for m in [_ENTRY_DATE_RE.search(str(v.get("summary")
                                                     or ""))] if m]
        if not years:
            m = _ENTRY_DATE_RE.search(str(k))
            years = [int(m.group(1))] if m else []
        if years and min(years) > year:
            continue
        if not years and k not in a:
            continue
        out.append(str(k))
    return out


def _shared_decisions_moved(root: Path, fz: Dict[str, Any], year: int
                            ) -> List[Tuple[str, int]]:
    """[(the shared file shown from `root`, how many entries)] — each
    decisions file of the lock's frozen inputs (inputs/<account>/
    manifest.json, sends.json) whose namesake in the shared folder the
    freeze copied it from holds a decision on `year` or earlier that
    differs from the copy (_decisions_moved). A late election or send
    decision saved there reaches neither the filed year, which reads
    its copy, nor its return; `elect` and `crypto-sends --set` name the
    frozen years when they write (_note_shared_decision), a hand edit
    showed nowhere (backlog TJ-0211). A file that cannot be read is not
    judged (the run that reads it says why). The shared folder:
    _frozen_shared_src (backlog TJ-0610)."""
    src = _frozen_shared_src(root, fz)
    if src is None:
        return []
    pre = f"{_PL.INPUTS}/"
    # Each account the freeze copied (a decisions file it had none of
    # is compared with an empty one: a first election saved later).
    accounts = sorted({k[len(pre):].split("/")[0]
                       for k in (fz.get("inputs") or {})
                       if k.startswith(pre) and k.count("/") == 2})
    out = []
    for acct in accounts:
        for name, table in sorted(_DECISION_FILES.items()):
            mine = root / _PL.INPUTS / acct / name
            theirs = src / acct / name
            try:
                if not theirs.is_file() or (
                        mine.is_file()
                        and mine.read_bytes() == theirs.read_bytes()):
                    continue
                moved = _decisions_moved(mine if mine.is_file() else None,
                                         theirs, table, year)
            except (OSError, ValueError):
                continue
            if moved:
                out.append((_PL.shown(theirs, root), len(moved)))
    return out


def _carry_in_moved(later: Any, record: Any, ry: int
                    ) -> Optional[Tuple[float, float, float]]:
    """(taken in, applied, carried now) when a later year's lock
    `later` took its net capital loss in from the `ry` close-year
    record (its opening_source names that record) and that record, as
    it is now (`record`), carries another balance into the next year:
    `ry` was closed again since (an amendment), so the later return
    applied, and its lock carried forward, a balance the record no
    longer has (backlog TJ-0430). None otherwise: another source ([estimate]
    other_losses), a lock without the block, the same balance."""
    import math as _math

    def _ncl(doc: Any) -> Optional[Dict[str, Any]]:
        cf = doc.get("carryforwards") if isinstance(doc, dict) else None
        b = cf.get("net_capital_loss") if isinstance(cf, dict) else None
        return b if isinstance(b, dict) else None
    a, b = _ncl(later), _ncl(record)
    if a is None or b is None or (f"(the {ry} close-year record)"
                                  not in str(a.get("opening_source") or "")):
        return None
    try:
        got = (float(a.get("opening") or 0.0), float(a.get("applied") or 0.0),
               float(b.get("closing") or 0.0))
    except (TypeError, ValueError):
        return None
    if not all(_math.isfinite(x) for x in got) \
            or abs(got[0] - got[2]) <= 0.005:
        return None
    return got


def _carry_in_detail(year: int, ry: int, got: Tuple[float, float, float],
                     record: str, then: str) -> str:
    """The detail of a _carry_in_moved message: what `year`'s return
    did with the balance `ry`'s record (`record`, shown) carried
    before, and `then` (what to run)."""
    taken, applied, now = got
    over = applied > now + 0.005
    return (f"{ry}'s close-year record ({record}) was closed again since "
            f"(an amendment). The {year} "
            f"return applied {applied:,.2f} of the {taken:,.2f}"
            + (f", more than the {now:,.2f} now carried in: no more "
               f"than the balance carried in can be applied (ITA "
               f"s.111(1)(b)), so {year} needs a T1-ADJ too"
               if over else
               f"; the balance its lock carried into {year + 1} is "
               f"built on the old {taken:,.2f}")
            + f" (its minimum tax carryover can move with it). {then}")


def _later_locks_on(root: Path, year: int, lock: Any
                    ) -> List[Tuple[int, str, Path,
                                    Tuple[float, float, float]]]:
    """[(later year, its lock shown from `root`, its folder, what
    _carry_in_moved found)] — each close-year lock of a later year,
    in this project's filed/ or a year folder beside it, that took
    its net capital loss in from `year`'s record as it was before
    `lock` replaced it (backlog TJ-0430)."""
    import os as _os
    from taxjson.bin import taxjson_filed
    cand: List[Tuple[int, Path, Path]] = [
        (y, p, root) for y, p in taxjson_filed.list_snapshots(root)
        if y > year]
    multi = _PL.multi_root(root)
    if multi is not None:
        for y, d in _PL.year_dirs(multi):
            p = d / "filed" / f"{y}.json"
            if y > year and d.resolve() != root.resolve() and p.is_file():
                cand.append((y, p, d))
    out = []
    for y, p, d in sorted(cand, key=lambda t: t[0]):
        try:
            doc = taxjson_filed.load_lock_json(p)
        except (OSError, ValueError):
            continue
        got = _carry_in_moved(doc, lock, year)
        if got is not None:
            out.append((y, _os.path.relpath(p, root), d, got))
    return out


def _frozen_settings_back(root: Path) -> List[str]:
    """The shared folders a frozen filed year names again in its
    [settings] (`inputs_dir = "../inputs"`, `tobase_map = ...`): the
    freeze commented them out, so a live one means the year reads the
    shared files, not its frozen copy. [] when it names none."""
    out = []
    if _PL.shared_inputs(root):
        out.append(f"{_PL.INPUTS_KEY} ({_PL.shown(_PL.inputs_dir(root), root)})")
    if _PL.shared_tobase(root):
        out.append(f"{_PL.TOBASE_KEY} "
                   f"({_PL.shown(_PL.tobase_map_path(root), root)})")
    return out


def _soft_fingerprint(root: Path) -> Optional[Dict[str, str]]:
    from taxjson.lib.checklist import input_fingerprint
    try:
        cfg = _soft_config(root)
    except Exception:                                   # noqa: BLE001
        return None
    return input_fingerprint(root, cfg)


def _lock_missing_year(root: Path, settings: Dict[str, Any]
                       ) -> Optional[int]:
    """The project's year when its filed/<year>.json was deleted while
    taxjson.toml still carries close-year's freeze note
    (lib/project_layout.lock_missing_frozen; backlog TJ-0263), else
    None."""
    year = settings.get("year")
    if not isinstance(year, int) or isinstance(year, bool):
        return None
    return year if _PL.lock_missing_frozen(root, year) else None


def _closed_with(lock: Dict[str, Any]) -> List[str]:
    """A drifted lock's detail line naming the taxjson that closed it
    and this one (backlog TJ-0341), or [] for a lock that records none
    (closed before the record was kept)."""
    from taxjson.lib import channels as _ch
    then = _ch.build_label(lock.get("taxjson"))
    if then is None:
        return []
    now_build = _ch.running_build()
    now = _ch.build_label(now_build) or "an unknown taxjson"
    same = _ch.same_build(lock.get("taxjson"), now_build)
    if same:
        return [f"It was closed with this taxjson ({then}): the change is "
                f"in the inputs or the settings, not the code."]
    return [f"It was closed with {then}; this is {now}: the releases "
            f"between them say what each moved (docs/upgrading.md)."]


def _check_filed_years(root: Path, cache: Path,
                       settings: Dict[str, Any], *,
                       strict: bool,
                       counts: Optional[Dict[str, int]] = None,
                       console: bool = False) -> int:
    """Drift check for every filed/<year>.json. Returns the number of
    years that drifted or could not be checked; prints per-year
    OK/DRIFT lines. `counts` (when given) receives them split:
    drifted, lock (unreadable, damaged or other-country locks) and
    input (the recompute itself failed on the books or an input)."""
    from taxjson.bin import taxjson_filed
    from taxjson.lib import out as _out
    _prog = _cmd_prog()

    def _line(text: str) -> None:
        # A per-year line: wrapped, its continuation indented under it
        # (a `note: ` line shown with its label, lib/out.labelled).
        # On the run's console (`console`), shown to a person: a message
        # of its own, the label at column 0 (`Info: Filed 2024: OK ...`),
        # continuations flush-left, a blank line after it when it wraps.
        if console and _out.width(sys.stdout) > 0:
            _t = _out.labelled(text)
            if not _t.startswith(("Info: ", "Warning: ", "Error: ")):
                _t = "Info: " + _t[:1].upper() + _t[1:]
            _out.show(_out.wrap(_t, None, "", ""), sys.stdout)
            return
        # Flush-left like the OK / DRIFT lines (docs/output-style.md).
        for _ln in _out.wrap(_out.labelled(text), None, "", ""):
            print(_ln)

    snaps = taxjson_filed.list_snapshots(root)
    # A bad [settings] value is the CONFIG's problem: refuse it in the
    # plain settings words before any lock is touched, not as "lock
    # could not be checked — fix or restore the lock" (A2-1134).
    if snaps:
        try:
            from taxjson.lib.pipeline import option_timing_from_settings
            _income_rules(settings)
            option_timing_from_settings(settings)
            taxjson_filed._tax_date(
                settings, taxjson_filed._canonical_country(settings))
        except ValueError as e:
            _die(f"{e}", "Fix taxjson.toml; the filed-year locks were not "
                 "checked.")
    drifting = 0
    # Which snapshot accounts are crypto (they blend only with each
    # other, and only in a Canadian project with two or more);
    # equity accounts recompute via ONE blended combined run — exactly
    # how close-year's numbers were produced — or the check would
    # falsely drift every multi-account book.
    try:
        _acct_cfg = load_config(root).get("accounts", {})
    except SystemExit:
        _acct_cfg = {}
        if snaps:
            _out.warn("taxjson.toml unreadable — the filed-year check "
                      "cannot tell crypto from equity accounts", prog=_prog,
                      details=["Crypto books would be blended into the "
                               "combined equity recompute and may report "
                               "false drift."])
    _taxable_cfg = {a for a, c in _acct_cfg.items()
                    if isinstance(c, dict) and c.get("type") == "taxable"}
    unreadable = 0
    input_failed = 0
    mismatched = 0
    settings_back = 0               # frozen years naming shared folders
    carry_moved = 0                 # built on an earlier record replaced
    # Each judged year's verdict, kept for `tjs years` (backlog
    # TJ-0159: a filed year whose run DRIFTED looked clean there).
    _verdicts: Dict[int, str] = {}
    _lost = _lock_missing_year(root, settings)
    if _lost is not None:
        # A frozen year whose lock was deleted: said and counted as a
        # damaged lock is (backlog TJ-0263).
        unreadable += 1
        _h, _d = _PL.lock_missing_parts(_lost)
        _out.warn(f"filed {_lost} could not be checked: {_h}", prog=_prog,
                  details=[f"{_d} The lock is the record of the filed "
                           f"return; the next year's estimate, amt, "
                           f"carryover and handoff need it too."])
    for year, path in snaps:
        _stage = "lock"
        # One lock at a time: an unreadable or hand-edited lock is
        # reported BY NAME and counted as a failure, and the other
        # locks are still checked. A KeyError/JSONDecodeError here used
        # to escape the loop, skip --strict's exit and every later lock
        # (R1-189).
        try:
            try:
                # The one check every reader of a lock applies: a lock
                # the next year's estimate, amt, carryover or handoff
                # refuses as damaged (its carryforwards block, a year
                # field naming another year) was called OK here
                # (2026-10-25 audit year-end#6).
                snap = taxjson_filed.read_lock(path,
                                               label=f"filed/{path.name}")
            except taxjson_filed.LockProblem as e:
                unreadable += 1
                _out.warn(f"filed {year} could not be checked: {e}",
                          prog=_prog,
                          details=["The lock is the record of the filed "
                                   "return; the next year's estimate, "
                                   "amt, carryover and handoff refuse it "
                                   "too."])
                continue
            # A lock closed under the other country is never recomputed
            # under this one's law (partition COMMANDS-08).
            _cp = taxjson_filed.lock_country_problem(
                snap, settings, f"filed/{path.name}")
            if _cp:
                mismatched += 1
                _out.warn(f"filed {year}: {_cp}", prog=_prog)
                continue
            _snap_accts = list(snap.get("accounts", {}))
            # A locked account that is no longer a configured taxable
            # account (renamed/removed) is NOT recomputed from its
            # orphan work/<label>_base.json — that blended stale books
            # into the check and said OK (S002-06).
            _gone = ({a for a in _snap_accts if a not in _taxable_cfg}
                     if _acct_cfg else set())
            _snap_accts = [a for a in _snap_accts if a not in _gone]
            # Taxable accounts the BOOKS have but the lock does not
            # (added or renamed after close-year) are recomputed too —
            # in the same blend — so diff_snapshot can report them
            # instead of saying OK.
            _snap_accts += sorted(
                a for a in _taxable_cfg
                if a not in _snap_accts
                and (cache / f"{a}_base.json").exists())
            # Merge in taxjson.toml order, as the run's blended pass
            # does (CA-DATE-14 / US-DATE-13: rows of different accounts
            # at one moment follow the accounts' order). The lock's
            # keys are alphabetical (sort_keys), so its order gave a
            # false DRIFT right after close-year (A2-0512).
            if _acct_cfg:
                _toml_order = {a: i for i, a in enumerate(_acct_cfg)}
                _snap_accts.sort(key=lambda a: _toml_order.get(
                    a, len(_toml_order)))
            _crypto = [a for a in _snap_accts
                       if (_acct_cfg.get(a) or {}).get("crypto")]
            _equity = [a for a in _snap_accts if a not in _crypto]
            _lock_timing = snap.get("option_timing")
            _stage = "recompute"
            recomputed = taxjson_filed.recompute_accounts(
                cache, _equity, _crypto, year,
                taxjson_filed.lock_settings(snap, settings),
                snap.get("basis", ""), _filed_run_gains,
                option_timing=_lock_timing)
            _stage = "lock"
            _diff_notes: List[str] = []
            lines = taxjson_filed.diff_snapshot(snap, recomputed,
                                                unconfigured=_gone,
                                                notes=_diff_notes)
            for _dn in _diff_notes:
                _line(f"note: filed {year}: {_dn}")
        except SystemExit:
            raise
        except Exception as e:          # this lock only
            if _stage == "recompute":
                # The books or an input failed, not the lock: say what
                # failed in the child's words and do not send the user
                # to edit the filed record (A2-0676).
                input_failed += 1
                _out.warn(f"filed {year}: {path.name} could not be "
                          f"checked: {_child_error_line(e)}", prog=_prog,
                          details=["Fix that input and re-run `tjs "
                                   "run` (the lock itself was not "
                                   "judged)."])
                continue
            unreadable += 1
            _out.warn(f"filed {year}: {path.name} could not be checked: "
                      f"{type(e).__name__}: {e}", prog=_prog,
                      details=["Fix or restore the lock (it is the record "
                               "of the filed return)."])
            continue
        if isinstance(_lock_timing, dict):
            from taxjson.lib.pipeline import option_timing_from_settings
            _cur = option_timing_from_settings(settings) or {}
            if _cur and (
                    _cur.get("option_premium_timing")
                    != _lock_timing.get("option_premium_timing")
                    or _cur.get("option_grant_since")
                    != _lock_timing.get("option_grant_since")):
                _line(f"note: filed {year} recomputed with the option "
                      f"timing its lock records "
                      f"({_lock_timing.get('option_premium_timing')}, "
                      f"since {_lock_timing.get('option_grant_since')}); "
                      f"this project uses "
                      f"{_cur.get('option_premium_timing')}, since "
                      f"{_cur.get('option_grant_since')} — set "
                      f"option_grant_timing_since to match or contracts "
                      f"written around {year} are taxed in the wrong "
                      f"year or twice")
            # The buy-back flag is recomputed from the lock too: an OK
            # line said nothing while the project's own .sum for that
            # year moved (A2-0348).
            if _cur and "option_buyback_loss_superficial" in _lock_timing \
                    and bool(_lock_timing.get(
                        "option_buyback_loss_superficial")) \
                    != bool(_cur.get("option_buyback_loss_superficial")):
                _line(f"note: filed {year} recomputed with "
                      f"option_buyback_loss_superficial = "
                      f"{str(bool(_lock_timing['option_buyback_loss_superficial'])).lower()}"
                      f" as its lock records; this project now says "
                      f"{str(bool(_cur.get('option_buyback_loss_superficial'))).lower()}"
                      f" — this project's reports for {year} no longer "
                      f"match what was filed")
        # Likewise the date basis (lock_settings): the lock is checked
        # on the basis it was filed on, so OK says nothing about this
        # project's own report for that year (A2-0672).
        _fz = snap.get("frozen")
        # A lock taken before the year ended (close-year --force): its
        # inputs were hashed, not frozen — the year reads the shared
        # exports, so its later trades are expected to move it
        # (workflow audit 2026-10-23).
        _partial = taxjson_filed.partial_year_note(snap, year)
        if isinstance(_fz, dict) and isinstance(_fz.get("inputs"), dict):
            # The lock hashed the inputs the filed books came from: one
            # edited or replaced since is named, so a DRIFT (or an OK
            # with other books) is not blamed on the code.
            _moved = _frozen_inputs_changed(root, _fz["inputs"])
            # taxjson.toml as `tjs migrate` left it, the edit its
            # lock records (frozen.migrated): migrate's own, explained
            # by check-filed, never a changed input; any later edit is
            # one (backlog TJ-0231).
            _mig = (_migrate_edit(root, _fz) if _PL.CONFIG in _moved
                    else None)
            if _mig is not None:
                _moved = [m for m in _moved if m != _PL.CONFIG]
                if not console:
                    _keys = ", ".join(str(k) for k in
                                      (_mig.get("keys") or [])) or "layout"
                    _line(f"note: filed {year}: taxjson.toml is as "
                          f"`{_mig.get('by') or 'tjs migrate'}` "
                          f"rewrote it on {_mig.get('on') or '?'} "
                          f"({_keys}), the edit its lock records — not "
                          f"a changed input")
            # The freeze is the project's own year's: a lock of an
            # earlier year kept in this year's filed/ (a single-folder
            # project gone on to the next year, then `migrate
            # --to-years`) is checked from the inputs this year reads,
            # rightly shared — never "delete inputs_dir" (backlog
            # TJ-0087).
            _cur_year = settings.get("year")
            _own = year == _cur_year
            _back = ([] if _partial or not _own
                     else _frozen_settings_back(root))
            if _partial and _moved:
                _line(f"note: filed {year}: {len(_moved)} input(s) "
                      f"changed since the partial lock was taken: "
                      f"{', '.join(_moved[:4])}"
                      + (" ..." if len(_moved) > 4 else "")
                      + " — not frozen while the year was open: "
                      "they reach the books")
            elif not _own:
                if _moved:
                    _line(f"note: filed {year} is checked from the inputs "
                          f"this {_cur_year} project reads "
                          f"({len(_moved)} changed since {year} was "
                          f"closed: {', '.join(_moved[:4])}"
                          + (" ..." if len(_moved) > 4 else "") + ")")
            elif _back:
                # taxjson.toml names the shared folders again (an older
                # `align`, or by hand): the books read them, not the
                # frozen copy — restoring files would change nothing
                # (workflow audit 2026-10-22). Something to act on: a
                # Warning, and `run --strict` stops (backlog TJ-0108).
                settings_back += 1
                _out.warn(f"filed {year} was closed with its inputs "
                          f"frozen, but taxjson.toml names the shared "
                          f"{' and '.join(_back)} again", prog=_prog,
                          details=[
                              f"The books no longer read the frozen "
                              f"copy: delete "
                              f"{'those lines' if len(_back) > 1 else 'that line'}"
                              f" from [settings], then `tjs run`."])
            elif _moved:
                _line(f"note: filed {year}: {len(_moved)} frozen input(s) "
                      f"changed since the year was closed: "
                      f"{', '.join(_moved[:4])}"
                      + (" ..." if len(_moved) > 4 else "")
                      + " — the books no longer come from the exports "
                      "as filed (restore them from your records; for "
                      "an amendment, re-close once it is filed)")
            _shared = ({"exports": [], "mappings": [], "unread": []}
                       if _partial or _back
                       else _shared_inputs_moved(root, _fz, year))
            _shared_moved = _shared["exports"]
            if _shared_moved:
                # A correction saved in the shared folder: the one place
                # it shows (backlog TJ-0091).
                _line(f"note: filed {year}: {len(_shared_moved)} shared "
                      f"export(s) gained, changed or lost a row of "
                      f"{year} or earlier since the year was closed: "
                      f"{', '.join(_shared_moved[:4])}"
                      + (" ..." if len(_shared_moved) > 4 else "")
                      + f" — the filed year reads its frozen copy and "
                      f"{year + 1}'s handoff checks only Dec 31 positions "
                      f"and cost, so a correction there shows nowhere "
                      f"else: compare each with its copy in inputs/ (a "
                      f"file new since the close has none); to "
                      f"amend, copy it in, `tjs run`, and after "
                      f"filing `tjs close-year --force`")
            _map_moved = _shared["mappings"]
            if _map_moved:
                # A generic mapping corrected in the shared folder: the
                # CSV's bytes are the same, its figures not (backlog
                # TJ-0708).
                _line(f"note: filed {year}: {len(_map_moved)} shared "
                      f"generic mapping(s) changed since the year was "
                      f"closed: {', '.join(_map_moved[:4])}"
                      + (" ..." if len(_map_moved) > 4 else "")
                      + f" — {'it reads' if len(_map_moved) == 1 else 'they read'}"
                      f" a CSV with rows of {year} or earlier otherwise "
                      f"than the copy {year} was closed with (a column, an "
                      f"action, a format), and the filed year reads its "
                      f"copy, so a correction there shows nowhere else: "
                      f"compare each with its copy in inputs/ (a mapping "
                      f"new since the close has none); to amend, copy it "
                      f"in, `tjs run`, and after filing `tjs "
                      f"close-year --force`")
            _dec_moved = ([] if _partial or _back
                          else _shared_decisions_moved(root, _fz, year))
            if _dec_moved:
                # A late election or send decision saved by hand in the
                # shared folder (backlog TJ-0211).
                _line(f"note: filed {year}: "
                      + ", ".join(f"{p} ({_count_noun(n, 'entry', 'entries')})"
                                  for p, n in _dec_moved[:4])
                      + (" ..." if len(_dec_moved) > 4 else "")
                      + f" in the shared folder "
                      f"{'holds' if len(_dec_moved) == 1 else 'hold'} "
                      f"a decision on {year} "
                      f"or earlier that differs from the copy {year} was "
                      f"closed with — the filed year reads its copy, so "
                      f"it reaches neither its books nor its return: to "
                      f"amend, make the same decision in {year}'s folder "
                      f"(`tjs elect` / `tjs crypto-sends --set` "
                      f"there), `tjs run`, and after filing `tjs "
                      f"close-year --force`; else undo it in the shared "
                      f"file")
            _unread = _shared["unread"]
            if _unread:
                # Not judged, so never passed as unchanged (backlog
                # TJ-0707).
                _line(f"note: filed {year}: "
                      f"{_count_noun(len(_unread), 'file')} could not be "
                      f"compared with the copy {year} was closed with: "
                      + ", ".join(f"{p} ({why})" for p, why in _unread[:4])
                      + (" ..." if len(_unread) > 4 else "")
                      + " — a correction there would show nowhere: "
                      "compare it with its copy in inputs/ yourself, or "
                      "save it readable (CSV UTF-8, a TOML mapping) and "
                      "check again")
        _rb = snap.get("date_basis")
        _now_basis = _tax_date(settings)
        if _rb in ("settle", "trade") and _rb != _now_basis:
            _line(f"note: filed {year} recomputed on the {_rb} date "
                  f"basis its lock records; this project uses "
                  f"tax_date = \"{_now_basis}\" — sales near Dec 31 "
                  f"fall in another year in this project's reports than "
                  f"on the filed return")
        _verdicts[year] = "drifted" if lines else "ok"
        if lines:
            drifting += 1
            _out.warn(f"filed {year} DRIFTED vs {path.name}", prog=_prog,
                      details=[f"- {ln}" for ln in lines]
                      + _closed_with(snap)
                      + ([f"The lock is a snapshot taken before {year} "
                          f"ended: trades and corrections since then "
                          f"move the year. Close it again after filing "
                          f"(`tjs close-year --force` with "
                          f"[settings].year = {year})."] if _partial else
                         [f"A code/data change moved an already-filed "
                          f"year. Review; then either amend the return or "
                          f"refresh the lock (`tjs close-year --force` "
                          f"with [settings].year = {year})."]))
        else:
            _line(f"filed {year}: OK (matches {path.name}; "
                  f"{taxjson_filed.NOT_LOCKED})")
        if _partial:
            _line(f"note: filed {year}: {_partial}")
        elif year == settings.get("year"):
            # The year's own lock took its net capital loss in from the
            # earlier year's record: that year amended and closed again
            # since leaves this return built on the old balance (backlog
            # TJ-0430).
            from taxjson.lib import carryforward as _CFw
            _pl = _CFw.prior_lock(root, settings)
            try:
                _rec = (taxjson_filed.load_lock_json(_pl[1])
                        if _pl is not None else None)
            except (OSError, ValueError):
                _rec = None                 # its readers name it
            _cm = (_carry_in_moved(snap, _rec, _pl[0])
                   if _pl is not None else None)
            if _cm is not None:
                carry_moved += 1
                _out.warn(f"filed {year} took in a {_cm[0]:,.2f} net "
                          f"capital loss from {_pl[0]}, whose record now "
                          f"carries {_cm[2]:,.2f} into {year}", prog=_prog,
                          details=[_carry_in_detail(
                              year, _pl[0], _cm, _pl[2],
                              f"`tjs run` here (the estimate reads "
                              f"the {_pl[0]} record as it is now), then "
                              f"after filing `tjs close-year "
                              f"--force`.")])
    _PL.record_filed_check(root, _verdicts)
    if counts is not None:
        counts.update(drifted=drifting, lock=unreadable + mismatched,
                      input=input_failed)
    unreadable += input_failed
    if (unreadable or mismatched) and strict:
        sys.exit(exit_text(f"tjs run --strict: {unreadable + mismatched} "
                           f"filed-year lock(s) could not be checked"
                           + (f" ({mismatched} closed under another country)"
                    if mismatched else "")
                           + (f" and {drifting} drifted" if drifting else "")
                           + " — aborting."))
    if drifting and strict:
        sys.exit(exit_text(f"tjs run --strict: {drifting} filed year(s) "
                           f"drifted — aborting."))
    if settings_back and strict:
        sys.exit(exit_text(f"tjs run --strict: {settings_back} filed "
                           f"year(s) no longer read their frozen inputs "
                           f"— aborting."))
    if carry_moved and strict:
        sys.exit(exit_text(f"tjs run --strict: the filed year took in "
                           f"a net capital loss its earlier year's record "
                           f"no longer carries — aborting."))
    return drifting + unreadable + mismatched


# What the newest year's run copies into [settings] exports_dir for other
# tools (lib/project_layout): reports/ files by pattern.
_EXPORT_PATTERNS = ("*_holdings.toml", "wash_radar_*.json",
                    "wash_radar_*.rpt")
_EXPORTS_README = """\
Written by `tjs run` of the {year} project ({folder}/), the newest
year folder here; every run of the newest year replaces these files.
Read them; do not edit them.

  <account>_holdings.toml   the account's positions at the end of the
                            books, with their cost for filing (as
                            reports/<account>_holdings.toml)
  wash_radar_<account>.json the superficial-loss / wash-sale radar: the
  wash_radar_<account>.rpt  sales and purchases whose window is open
                            (JSON for programs, the text report)
  wash_radar_COMBINED.*     the same across the taxable accounts
"""


_EXPORTS_README_NAME = "README.txt"
# The files the last export wrote: the next one removes only those it no
# longer writes (`_write_exports`).
_EXPORTS_MANIFEST = ".taxjson-exports.json"


def _exports_manifest(dst: Path) -> List[str]:
    """The plain file names the previous export recorded writing ([]
    without a readable manifest; a name with a path in it is never
    one)."""
    import json
    try:
        doc = json.loads((dst / _EXPORTS_MANIFEST).read_text(
            encoding="utf-8"))
    except (OSError, ValueError):
        return []
    files = doc.get("files") if isinstance(doc, dict) else None
    return [f for f in (files if isinstance(files, list) else [])
            if isinstance(f, str) and f and f == Path(f).name
            and f not in (".", "..") and not f.startswith(".")]


def _write_exports(root: Path, settings: Dict[str, Any],
                   reports_dir: Path) -> None:
    """The newest year's run: copy its positions and wash radar from
    reports/ into exports_dir with a README naming the year; an older
    year's run leaves them alone."""
    dst = _PL.exports_folder(root)
    if dst is None:
        return
    year = settings.get("year")
    newer = [y for y, _d in _PL.year_dirs(root.parent)
             if isinstance(year, int) and y > year]
    if newer:
        return
    from taxjson.lib.safe_write import write_atomic
    if dst.is_symlink():
        raise OSError(f"{dst} is a symlink")
    # (load_config refused an exports_dir overlapping another folder:
    # lib/project_layout.exports_overlap; said again here, never a
    # write into inputs, holdings or a year folder.)
    _ov = _PL.exports_overlap(root, settings)
    if _ov:
        raise OSError(_ov)
    dst.mkdir(parents=True, exist_ok=True, mode=0o700)
    srcs = [f for pat in _EXPORT_PATTERNS
            for f in sorted(reports_dir.glob(pat))
            if f.is_file() and not f.name.startswith(".")]
    names = sorted({f.name for f in srcs} | {_EXPORTS_README_NAME})
    # Only the files the previous export wrote (its manifest) and this
    # one no longer writes are removed: a file someone else put in the
    # folder is never touched.
    for old in sorted(set(_exports_manifest(dst)) - set(names)):
        p = dst / old
        if p.is_file() or p.is_symlink():
            p.unlink()
    for f in srcs:
        write_atomic(dst / f.name, f.read_bytes())
    n = len(srcs)
    write_atomic(dst / _EXPORTS_README_NAME, _EXPORTS_README.format(
        year=year, folder=root.name))
    import json
    write_atomic(dst / _EXPORTS_MANIFEST, json.dumps(
        {"schema_version": 1, "year": year, "files": names},
        indent=2) + "\n")
    _say("note", f"{n} file(s) for other tools -> "
         f"{_PL.shown(dst, root)}/ (the newest year's)", indent="  ",
         file=sys.stdout)


def _fx_cash_after_run(root: Path, cache: Path,
                       reports_dir: Path) -> None:
    """End-of-run FX-cash report, ONLY when [settings] fx_cash_gains
    is true — the ledger is advisory and many filers have never
    reported s.39(1.1), so it stays opt-in and touches no other
    output."""
    from taxjson.bin import taxjson_fx_cash as FX
    if not _soft_settings(root).get("fx_cash_gains"):
        return
    _step("Calculating FX gains on cash (fx_cash_gains = true)")
    from taxjson.lib.safe_write import write_atomic
    rpt = reports_dir / "fx_cash.rpt"
    try:
        if _fx_cash_ledger_choice(_soft_settings(root)) == "v2":
            from taxjson.lib import fx_cash_v2 as V2
            doc, verdict, _c, base, year, country = _fx_cash_v2_doc(root,
                                                                    cache)
            write_atomic(rpt, V2.render(doc, verdict, country, width_=0)
                         + "\n")
            _say("note", f"{V2.headline(doc, verdict)} -> "
                 f"{_out_relpath(rpt, root)}", indent="  ",
                 file=sys.stdout)
            return
        ledger, verdict, base, year, country = _fx_cash_doc(root, cache)
    except SystemExit as e:
        _say("warning", f"FX gains on cash skipped: {e}", indent="  ")
        return
    # A file, like the captured stage reports: never wrapped.
    text = FX.render_report(ledger, base, year, country, verdict,
                            width_=0)
    write_atomic(rpt, text + "\n")
    # Never a reportable figure from the default ledger (CA-FX-07).
    st = FX.unreliable_status(ledger, year, verdict)
    _say("note", f"{st['headline']} -> {_out_relpath(rpt, root)}",
         indent="  ", file=sys.stdout)


def cmd_check_filed(args: argparse.Namespace) -> None:
    """`tjs check-filed`: recompute every filed year from the
    current books and diff against the locks. Exit 1 on drift or a
    damaged lock, 2 when only the recompute failed on an input (nothing
    was judged)."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = load_config(root)["settings"]
    from taxjson.bin import taxjson_filed
    from taxjson.lib import out as _out
    # (A frozen year whose lock was deleted is checked as a damaged
    # one: said, exit 1; backlog TJ-0263.)
    if not taxjson_filed.list_snapshots(root) \
            and _lock_missing_year(root, settings) is None:
        # A year folder beside filed ones: its own lock is what is
        # missing, not every lock (backlog TJ-0092).
        _multi = _PL.multi_root(root)
        _others = (_filed_year_folders(_multi, skip=root)
                   if _multi is not None else [])
        if _others:
            import os as _os

            def _at(p: Path) -> str:
                # From here (`2024`, `../2024`), else the full path.
                rel = _os.path.relpath(p)
                return (str(p) if rel.startswith(_os.pardir + _os.sep
                                                 + _os.pardir) else rel)
            print(_out.fill(
                f"No filed/<year>.json lock in this project: "
                f"{settings.get('year')} is not closed (`tjs "
                f"close-year` locks it after you file). The filed years "
                f"are checked in their own folders: "
                + ", ".join(f"`tjs -C {_at(p)} check-filed`"
                            for p in _others) + "."))
            return
        print(_out.fill("No filed/<year>.json snapshots — `tjs "
                        "close-year` creates one after you file."))
        return
    print("FILED-YEAR LOCK CHECK", flush=True)
    # "OK" is only as good as the books it recomputes (S048-23).
    _state = _warn_run_state(root, load_config(root))
    _counts: Dict[str, int] = {}
    if _check_filed_years(root, cache, settings, strict=False,
                          counts=_counts):
        # 1: a year drifted or a lock is damaged / of another country;
        # 2: only the recompute failed on an input (A2-0676) — nothing
        # was judged, so it is not reported as drift.
        if _counts.get("drifted") or _counts.get("lock"):
            raise SystemExit(1)
        raise SystemExit(2)
    if _state:
        print(_out.fill("The books above are not clean — see the warning; "
                        "an OK here is not conclusive until `tjs run` "
                        "is clean."))


def cmd_reconcile_slips(args: argparse.Namespace) -> None:
    """`tjs reconcile-slips SLIP.csv`: diff broker T5008/1099-B slips
    against the computed dispositions of all taxable accounts."""
    from taxjson.bin import taxjson_reconcile_slips

    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = load_config(root).get("settings", {})
    year = settings.get("year")

    _slips = (args.slip_csv if isinstance(args.slip_csv, list)
              else [args.slip_csv])
    # IB's dividends report (T5/T3 data, `tjs slip-audit`) lives in
    # inputs/slips/ too: the documented `inputs/slips/*.csv` names it.
    from taxjson.lib.ib_dividends import is_dividends_report
    _ib = [f for f in _slips if is_dividends_report(Path(f))]
    if _ib:
        from taxjson.lib.brokerages.base import shown_name
        note("tjs reconcile-slips",
             f"skipped {', '.join(shown_name(f) for f in _ib)}: IB's "
             f"dividends report (T5/T3 income, read by `tjs "
             f"slip-audit`), not a T5008")
        _slips = [f for f in _slips if f not in _ib]
        if not _slips:
            _die_input("no T5008 slip CSV to reconcile",
                       "IB's dividends report is read by `tjs "
                       "slip-audit`.")
    gains_argv = _taxable_gains_argv(
        root, cache, exclude_crypto=True, prog="tjs reconcile-slips",
        required=True)
    # Books built for another tax year made every slip row read
    # MISSING_FROM_COMPUTED "dropped CSV rows or a missing statement?"
    # — the wrong cause (S047-24, S049-06).
    _stale = _artifact_year_mismatch(
        {Path(g).name: Path(g) for g in gains_argv[1::2]}, year)
    if _stale:
        got = ", ".join(f"{a} ({y})" for a, y in sorted(_stale.items()))
        _die(f"[settings].year is {year} but the work/ books were built "
             f"for another tax year: {got}",
             f"Rebuild with `tjs run` before reconciling the {year} "
             f"slips.")
    argv = list(_slips) + gains_argv
    tmap = _PL.ticker_map_path(root)
    if tmap.exists():
        # Slips print the broker's symbols; the books carry the
        # ticker.map consolidations (SAMPLK -> SAMPLJ, R1-19).
        argv += ["--ticker-map", str(tmap)]
    if year is not None:
        argv += ["--year", str(year)]
        # Same date convention stage_account feeds the gains engine:
        # IRS/1099-B scope by TRADE date, CRA/T5008 by SETTLEMENT; an
        # explicit tax_date config wins. Without this, a USA year-end
        # sale settling in January was on the 1099-B (and in
        # form-export) but missing from the computed side.
        tax_date = _tax_date(settings)
        argv += ["--date-basis", tax_date]
    argv += ["--country", _country(settings)]
    if args.tolerance is not None:
        # One token: '--tolerance -1' read the value as an option
        # (S036-00).
        argv.append(f"--tolerance={args.tolerance!r}")
    if args.json:
        argv.append("--json")
    if not _details(args) and not getattr(args, "json", False):
        # Essentials first (docs/output-style.md): the stage's default
        # view; --details prints its whole report.
        argv.append("--brief")
    raise SystemExit(taxjson_reconcile_slips.main(argv))


def _slip_audit_import_cra(root: Path, cfg: Dict[str, Any],
                           args: argparse.Namespace) -> None:
    """`tjs slip-audit [ACCOUNT] --import-cra PDF|DIR ... [--write]
    [--json]`: CRA-downloaded T5 / T3 slip PDFs as [[slip]] tables, each
    placed in a project account (and broker account, a T3 its fund) by
    the books (lib/cra_slips). A slip read twice is kept once; an
    amended slip replaces its original (in this import, or a table
    already in slips.toml — commented out, the file backed up). Shows
    what it would add; --write writes it to inputs/slips/slips.toml."""
    import contextlib
    import datetime as _dtm
    import io
    import tempfile
    from taxjson.lib import cra_slips as CS
    from taxjson.lib import out
    from taxjson.lib import slip_audit as SA
    from taxjson.lib.ib_dividends import IBReportError, read_report
    from taxjson.lib.safe_write import OutsideLinkError, write_user_file
    year = int((cfg.get("settings") or {}).get("year"))
    acct = getattr(args, "account", None)
    as_json = bool(getattr(args, "json", False))
    if acct and acct not in SA.slip_accounts(cfg):
        _die_input(f"account {acct!r} gets no T5 or T3",
                   "Name a taxable, non-crypto [accounts.*] account.")
    try:
        paths = CS.pdf_paths(args.import_cra)
    except CS.CraSlipError as e:
        _die_input(str(e))
    slips, skipped = [], []
    for p in paths:
        try:
            got = CS.read_pdf(p)
        except CS.CraSlipError as e:
            if "pdftotext is not installed" in str(e):
                _die_input(str(e))
            skipped.append(str(e))
            continue
        for sl in got:
            if sl.year != year:
                skipped.append(f"{sl.shown}: a {sl.year} slip; the "
                               f"project's year is {year}")
            elif sl.status == "cancelled":
                skipped.append(f"{sl.shown}: a cancelled slip — not "
                               f"imported (delete the table of the slip it "
                               f"cancels from slips.toml)")
            else:
                slips.append(sl)
    n_read = len(slips)
    slips, dup_notes = CS.drop_duplicates(slips)
    sf = SA.slips_dir(root) / SA.SLIPS_FILE
    old_text = ""
    have: List[Any] = []
    if sf.is_file():
        try:
            have = SA.load_slips_file(sf, cfg, year)[0]
            old_text = sf.read_text(encoding="utf-8-sig")
        except (SA.SlipsError, OSError, UnicodeDecodeError) as e:
            _die_input(str(e))
    reports, seen = [], set()
    for p in SA.find_ib_reports(root):
        try:
            rep = read_report(p)
        except IBReportError:
            continue
        if SA.report_identity(rep) not in seen:
            seen.add(SA.report_identity(rep))
            reports.append(rep)
    rate = {}
    for c in sorted({s.currency for s in slips} - {"CAD"}):
        a = SA.annual_average(c, year)
        rate[c] = a["rate"] if a else None
    try:
        # The market list's notes are the views' to print.
        with contextlib.redirect_stderr(io.StringIO()):
            groups = CS.book_groups(root, cfg, year)
    except ValueError as e:
        _die_input(str(e))
    # Originals and amended slips are placed apart, so an amended slip
    # lands where its original does and the pair is not shared out as
    # two slips.
    placed = []
    for part in ([s for s in slips if s.status != "amended"],
                 [s for s in slips if s.status == "amended"]):
        if part:
            try:
                placed += CS.place(part, groups, year, rate, reports,
                                   account=acct)
            except CS.CraSlipError as e:      # the shipped issuer file
                _die(str(e))
    order = {id(s): i for i, s in enumerate(slips)}
    placed.sort(key=lambda pl: order[id(pl.slip)])
    salt = SA.key_salt(root, create=True)
    keyed = [(pl, SA.broker_key(salt, pl.key) if pl.key else "")
             for pl in placed]
    hashes = {h for g in groups for h in g.hashes} | {
        r.account_hash for r in reports}
    existing = []
    for i, s0 in enumerate(have, 1):
        keys = {s0.broker_key} if s0.broker_key else set()
        keys |= {SA.broker_key(salt, h) for h in s0.broker_hashes
                 if h in hashes}
        existing.append(CS.Existing(
            index=i, type=s0.type, account=s0.account,
            security=s0.security, issuer=s0.issuer, status=s0.status,
            currency=s0.currency, boxes=dict(s0.boxes),
            keys=frozenset(k for k in keys if k),
            imported=s0.origin.startswith("cra:"), source=s0.origin))
    plan = CS.plan_import(keyed, existing)
    notes = [f"{pl.slip.shown}: {pl.how}" for pl in placed
             if not pl.account]
    notes += dup_notes + plan.notes
    notes += [f"skipped {m}" for m in skipped]
    in_import = list(plan.superseded)
    replaced_notes = in_import + [
        f"slips.toml [[slip]] #{e.index} ({e.status or 'original'}): "
        f"replaced by the amended slip {pl.slip.shown}"
        for e, pl, _k in plan.replace]
    tables = [CS.table(pl, k) for pl, k in plan.add] + [
        CS.table(pl, k) for _e, pl, k in plan.replace]
    text = ("\n\n".join(tables) + "\n") if tables else ""
    new_text = None
    if tables:
        today = _dtm.date.today().isoformat()
        base = old_text
        if plan.replace:
            try:
                base = SA.comment_out_tables(old_text, {
                    e.index: (f"Replaced by the amended slip "
                              f"{CS._comment(pl.slip.shown)} (tjs "
                              f"slip-audit --import-cra, {today}):")
                    for e, pl, _k in plan.replace})
            except SA.SlipsError as e:
                _die_input(str(e))
        if not base:
            base = f"year = {year}\n"
        sep = "" if base.endswith("\n\n") else (
            "\n" if base.endswith("\n") else "\n\n")
        new_text = base + sep + text
        # Never write a file slip-audit cannot read back.
        with tempfile.TemporaryDirectory() as td:
            tp = Path(td) / SA.SLIPS_FILE
            tp.write_text(new_text, encoding="utf-8")
            try:
                back = SA.load_slips_file(tp, cfg, year)[0]
            except SA.SlipsError as e:
                _die(f"the tables to write do not read back ({e}); "
                     f"slips.toml is unchanged")
        if len(back) != len(have) - len(plan.replace) + len(tables):
            _die("the tables to write do not read back as written; "
                 "slips.toml is unchanged")
    backup = None
    if args.write and new_text is not None:
        sf.parent.mkdir(parents=True, exist_ok=True)
        try:
            backup = write_user_file(sf, new_text, root)
        except OutsideLinkError as e:
            _die_input(str(e))
    if as_json:
        _json_out({
            "schema_version": 1, "year": year,
            "slips": [{"file": pl.slip.shown, "type": pl.slip.type,
                       "status": pl.slip.status, "issuer": pl.slip.issuer,
                       "currency": pl.slip.currency,
                       "boxes": {b: round(v, 2) for b, v in
                                 pl.slip.boxes.items()},
                       "account": pl.account,
                       "broker_account": (list(pl.group.sources)
                                          if pl.group else None),
                       "fund": pl.security or None, "how": pl.how}
                      for pl in placed],
            "add": [pl.slip.shown for pl, _k in plan.add],
            "replace": [{"table": e.index, "by": pl.slip.shown}
                        for e, pl, _k in plan.replace],
            "replaced_in_import": in_import,
            "not_imported": notes, "tables": text,
            "written": bool(args.write and new_text is not None),
            "backup": (f"inputs/slips/{backup.name}" if backup
                       else None)})
        return
    d = out.Doc(f"CRA SLIP IMPORT — tax year {year}: {n_read} slip(s) "
                f"read")
    body = [[pl.slip.shown, pl.slip.type, pl.slip.status, pl.slip.issuer,
             pl.slip.currency, pl.account or "-",
             ", ".join(pl.group.sources) if pl.group else "-",
             pl.security or ""] for pl in placed]
    if body:
        d.blank()
        d.table(["FILE", "TYPE", "STATUS", "ISSUER", "CUR", "ACCOUNT",
                 "BROKER ACCOUNT", "FUND"], body, drop=(3, 6, 2), key=0)
    if replaced_notes:
        d.section("Amended")
        d.items(replaced_notes)
    if notes:
        d.section("Not imported")
        d.items(notes)
    if text:
        d.section(f"{'Added to' if args.write else 'Would add to'} "
                  f"inputs/slips/{SA.SLIPS_FILE}")
        for ln in text.splitlines():
            d.line("  " + ln if ln else "")
    d.blank()
    if not text:
        d.para("Nothing to add.")
    elif args.write:
        d.para(f"Added {len(tables)} slip(s)"
               + (f", {len(plan.replace)} replacing an earlier slip (commented "
                  f"out" + (f"; the old file is {backup.name}" if backup
                            else "") + ")" if plan.replace else "")
               + "; `tjs slip-audit` compares them with the books.")
    else:
        d.para(f"Run again with --write to add {len(tables)} slip(s) to "
               f"inputs/slips/{SA.SLIPS_FILE}"
               + (f" ({len(plan.replace)} replacing an earlier slip, which is "
                  f"commented out)" if plan.replace else "") + ".")
    d.print()


def cmd_slip_audit(args: argparse.Namespace) -> None:
    """`tjs slip-audit [ACCOUNT]`: the T5 / T3 slips in inputs/slips/
    (slips.toml, IB's dividends reports) against the books' income, per
    account and box (lib/slip_audit; tax-logic CA-SLIP-01..04). Canada
    only (lib/country COMMAND_COUNTRY). Exit 1 on a finding or on
    something not compared (`not_compared`)."""
    from taxjson.lib import slip_audit as SA
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    settings = cfg.get("settings") or {}
    year = settings.get("year")
    if year is None:
        _die_input("taxjson.toml has no [settings] year",
                   "slip-audit compares one tax year's slips.")
    if not (root / "work").is_dir():
        _die("no work/ in the project", "Run `tjs run` first.")
    if getattr(args, "template", False):
        try:
            sys.stdout.write(SA.template(root, cfg))
        except (SA.SlipsError, ValueError) as e:
            _die_input(str(e))
        return
    if getattr(args, "import_cra", None):
        _slip_audit_import_cra(root, cfg, args)
        return
    if getattr(args, "write", False):
        _die_input("--write goes with --import-cra",
                   "It writes the imported slips into inputs/slips/"
                   "slips.toml.")
    tol = (SA.DEFAULT_TOLERANCE if args.tolerance is None
           else float(args.tolerance))
    # The books' income is what the slips are compared with: say when
    # they are not the clean result of the current inputs, as every
    # other review of the books does (backlog TJ-0557).
    _warn_run_state(root, cfg)
    try:
        rep = SA.audit(root, cfg, tolerance=tol,
                       account=getattr(args, "account", None))
    except SA.SlipsError as e:
        _die_input(str(e))
    if args.json:
        _json_out(rep)
    else:
        for ln in SA.render(rep, details=_details(args)):
            print(ln)
    # Something not compared (an account with no readable books, a
    # report or a slip matched to no account, an unknown IB component)
    # is never a pass either: exit 0 with "Every slip agrees" certified
    # an account it never read (backlog TJ-0305).
    if rep["issues"] or rep.get("not_compared"):
        raise SystemExit(1)


def _explain_wash_sales(root: Path, cache: Path,
                        account: Optional[str]) -> None:
    """`tjs wash-sales --explain`: print the full ACB / superficial-loss
    calculation trace for each wash sale, via `taxjson-explain --wash-sales`
    (plain text — `taxjson-explain` is color-off by default). Resolves the
    account base file(s) and the country / tax-date / sheltered context from the
    project. Raises SystemExit with the tool's return code."""
    if account:
        base = cache / f"{account}_base.json"
        if not base.exists():
            # (work/ named from the project: backlog TJ-0642)
            _die_input(f"no {base.name} in work/ — run `tjs run` "
                       f"first, or check the name.")
        if ((_soft_config(root).get("accounts") or {}).get(account)
                or {}).get("type") == "sheltered":
            # A registered account's own sale is no superficial loss
            # (CA-ACB-05; an IRA's, no wash sale): the table says none,
            # and the trace replayed the registered book as taxable,
            # each row twice (backlog TJ-0600).
            _usa = _country(_soft_settings(root)) in ("us", "usa")
            from taxjson.lib.out import Doc
            Doc(f"No {'wash sales' if _usa else 'superficial losses'} "
                f"for account {account!r} — it is a sheltered account."
                ).para("Its own sales are kept out of the filing totals, "
                       "so none is denied. Its purchases can deny a "
                       "taxable account's loss: `tjs wash-sales "
                       "--explain` traces those.").print()
            raise SystemExit(0)
        _refuse_us_crypto_account(root, account, "tjs wash-sales")
        bases = [base]
    else:
        names = _taxable_equity_account_names(root)
        if names is not None and not names:
            _no_wash_checkable("tjs wash-sales")
        if names is not None:
            bases = [cache / f"{n}_base.json" for n in names
                     if (cache / f"{n}_base.json").exists()]
        else:
            bases = [p for p in sorted(cache.glob("*_base.json"))
                     if not p.name.endswith("_raw_base.json")
                     and p.name != "sheltered_base.json"
                     and not p.name.startswith(".")]
        if not bases:
            # Exit 2, an input missing, work/ named from the project
            # (backlog TJ-0642).
            _die_input("no base files in work/ — run `tjs run` "
                       "first.")

    settings = _soft_settings(root)
    common: List[str] = ["--wash-sales", "--layout", "report"]
    common += ["--country", _country(settings)]
    if _country(settings) in ("us", "usa"):
        # The blended table keeps FIFO per account (US-BASIS-01): said
        # explicitly, as `tjs audit` does, so the trace of a merged
        # book never pools lots across accounts (re-audit A2-0155).
        common.append("--per-account-basis")
    if settings.get("tax_date"):
        common += ["--tax-date", settings["tax_date"]]
    # The table lists the tax year's wash sales; the trace printed every
    # year's under it (R1-284).
    if isinstance(settings.get("year"), int):
        common += ["--year", str(settings["year"])]
    # Sheltered history makes the ±30-day affiliated-balance window accurate
    # (a registered-account repurchase can trigger/permanently-deny a loss).
    sheltered_base = cache / "sheltered_base.json"
    if sheltered_base.exists():
        common += ["--sheltered", str(sheltered_base)]
    elif _sheltered_expected(root):
        # Without it the replay lost a registered account's denial the
        # table still lists (audit TJ-0394): refuse, as the wash checks
        # do (backlog TJ-0350).
        _die_input("no sheltered_base.json in work/: the registered "
                   "accounts' trades are missing from the replay",
                   "A registered account's buy can deny a loss for good, "
                   "so a trace without them can contradict the table. "
                   "Run `tjs run` first to rebuild it.")
    # Same missing-history openings as the pipeline, so traces match the
    # books.
    mh_file = _missing_history_arg(root)
    if mh_file is not None:
        common += ["--incomplete-history", str(mh_file)]
    common += option_timing_flags(settings)
    common += income_dating_flags(settings)
    common += _loss_override_flags(cache)
    if account:
        # The table lists this account's denials only; the merged book
        # below keeps the other accounts as context, so the trace shows
        # only this account's dispositions too (backlog TJ-0413).
        common += ["--account", account]

    # Trace the computation the table comes from: the pipeline BLENDS
    # the taxable equity books (s.47 ACB / cross-account §1091), and
    # Canadian crypto books when there are two or more. One explain
    # per account's own book gave each its own pool — "no matching
    # gains" for a real denial, or a denial the books do not have
    # (S046-09).
    _acfg = _soft_config(root).get("accounts") or {}
    _crypto_blend = _country(settings) \
        not in ("us", "usa")
    _by_name = {p.name[:-len("_base.json")]: p for p in bases}
    if account and account in _acfg:
        _is_c = bool((_acfg.get(account) or {}).get("crypto"))
        for n in _taxable_equity_account_names(root) or []:
            if (n != account and bool((_acfg.get(n) or {}).get("crypto"))
                    == _is_c and (cache / f"{n}_base.json").exists()):
                _by_name[n] = cache / f"{n}_base.json"
    # Merged in taxjson.toml order, as the pipeline's blend: rows of
    # different accounts at one moment follow that order (CA-DATE-14 /
    # US-DATE-13); an alphabetical merge traced another book (A2-1592).
    _toml_pos = {n: i for i, n in enumerate(_acfg)}
    _ordered = sorted(_by_name.items(), key=lambda kv: (
        _toml_pos.get(kv[0], len(_toml_pos)), kv[0]))
    equity = [p for n, p in _ordered
              if not (_acfg.get(n) or {}).get("crypto")]
    crypto = [p for n, p in _ordered
              if (_acfg.get(n) or {}).get("crypto")]
    groups = ([equity] if equity else []) + (
        [crypto] if crypto and _crypto_blend
        else [[c] for c in crypto])
    import os as _os
    import tempfile as _tf
    from taxjson.lib.dispatch import run_cmd as _run_cmd
    _usa = _country(settings) in ("us", "usa")
    print(f"{'WASH SALES' if _usa else 'SUPERFICIAL LOSSES'} — how each "
          f"denial was computed, {_base_currency(root)}"
          + (f", tax year {settings['year']}"
             if isinstance(settings.get("year"), int) else ""))
    print()
    sys.stdout.flush()
    rc = 0
    # Each book's explain exits _NO_MATCH (silently) when it has no
    # denial; the note is said once, only when no book had one — a
    # crypto book with none printed "no matching gains found" under
    # the equity book's real denial.
    _NO_MATCH = 3
    matched = False
    for grp in groups:
        target, tmp = grp[0], None
        if len(grp) > 1:
            _check_books_before_merge(grp)
            fd, name = _tf.mkstemp(prefix="taxjson_explain_",
                                   suffix=".json")
            _os.close(fd)
            tmp = Path(name)
            res = _run_cmd(_cmd("taxjson-merge") + [str(b) for b in grp],
                           capture_output=True)
            if res.returncode != 0:
                tmp.unlink(missing_ok=True)
                sys.exit(exit_text(f"tjs wash-sales: could not merge the "
                                   f"taxable base books: "
                                   f"{_child_error(res.stderr)}"))
            tmp.write_text(res.stdout, encoding="utf-8")
            target = tmp
        try:
            # Each trace block self-identifies its account, so no
            # per-file header is needed.
            proc = _run_cmd(_cmd("taxjson-explain") + common
                            + ["--no-match-status", str(_NO_MATCH),
                               str(target)])
            if proc.returncode == _NO_MATCH:
                continue
            matched = True
            rc = proc.returncode or rc
        finally:
            if tmp is not None:
                tmp.unlink(missing_ok=True)
    if not matched:
        emit_line("tjs wash-sales: note: no matching gains found",
                  file=sys.stderr)
    raise SystemExit(rc)


def _radar_config(root: Path, prog: str = "tjs") -> Dict[str, Any]:
    """taxjson.toml for the radar family (wash-radar, watch, buy-check,
    sell-check): {} when the project has none — a bare work/ directory
    still runs — but a file that EXISTS and does not parse stops the
    command. Soft-reading it as {} fell back to globbing every
    *_base.json, sheltered books included, as TAXABLE: registered
    accounts' sales became "losses" with rescue advice to sell RRSP
    shares (2026-09 audit S048-13)."""
    cfg_path = root / "taxjson.toml"
    if cfg_path.exists() and tomllib is not None:
        # Through _read_config_text, as every other command reads it:
        # a Notepad BOM is dropped, not 'Invalid statement (at line 1,
        # column 1)' (re-audit A2-0470, A2-1454, A2-1456, A2-1458,
        # A2-1459 — the S038-04 twin).
        text = _read_config_text(cfg_path)
        try:
            tomllib.loads(text)
        except Exception as e:
            from taxjson.lib.out import fail
            fail(f"taxjson.toml cannot be read ({e})", prog=prog,
                 details=["Fix it first; the radar will not guess which "
                          "accounts are taxable."])
    return _soft_config(root)


def _taxable_equity_account_names(root: Path,
                                  prog: str = "tjs"
                                  ) -> Optional[List[str]]:
    """Wash-checkable taxable account names from taxjson.toml (no hard
    exit when the config is absent; an unreadable one stops — see
    _radar_config). Crypto accounts are excluded only for US projects
    (§1091 does not reach digital assets); Canada's superficial-loss
    rule covers any identical property, so Canadian crypto accounts are
    included — matching _wash_flags and the run pipeline's second pass.
    None means 'no config', so the caller falls back to globbing base
    files; an EMPTY list is a real answer (a US crypto-only project has
    nothing wash-checkable) — treating it as 'unknown' globbed the
    crypto books back in and applied §1091 to them (S046-10)."""
    cfg = _radar_config(root, prog)
    if not cfg or not (cfg.get("accounts") or {}):
        return None                 # no accounts table: glob work/
    crypto_covered = _country((cfg.get("settings") or {})) \
        not in ("us", "usa")
    return [n for n, c in (cfg.get("accounts") or {}).items()
            if (c or {}).get("type") == "taxable"
            and (crypto_covered or not (c or {}).get("crypto"))]


def _refuse_us_crypto_account(root: Path, account: Optional[str],
                              prog: str, json_doc=None) -> None:
    """A US project's crypto account is outside the wash-sale rule
    (§1091 does not reach digital assets; the pipeline runs it with
    --no-wash): the explain and radar entry points said a loss the
    return allows in full was disallowed, and advised a trade to
    'rescue' it (S046-10). `json_doc`: as _no_wash_checkable's."""
    if not account:
        return
    cfg = _radar_config(root, prog)
    if (_country((cfg.get("settings") or {})) in ("us", "usa")
            and ((cfg.get("accounts") or {}).get(account) or {})
            .get("crypto")):
        _not_applicable(prog, f"{account} is a crypto account of a US "
                        f"project — the wash-sale rule (§1091) does not "
                        f"apply to it, so there is nothing to check.",
                        json_doc)


_NO_WASH_CHECKABLE = (
    "no wash-checkable taxable account in taxjson.toml (sheltered "
    "accounts are context only, and a US project's crypto accounts are "
    "outside the wash-sale rule, §1091) — nothing to check.")


def _not_applicable(prog: str, why: str, json_doc=None) -> None:
    """Stop with exit 0: the wash rule has nothing to check here. In
    text, `why` after the command's name; with `json_doc` (the
    command's --json: a callable returning its empty document), that
    document with `not_applicable` set to `why`. The prose broke every
    --json consumer of the planning commands (backlog TJ-0330)."""
    if json_doc is not None:
        doc = dict(json_doc())
        doc["not_applicable"] = why
        _json_out(doc)
    else:
        from taxjson.lib.out import fill
        print(fill(f"{prog}: {why}", hang="  "))
    raise SystemExit(0)


def _no_wash_checkable(prog: str, json_doc=None) -> None:
    """No wash-checkable taxable account (a US crypto-only project, or
    only sheltered accounts): _not_applicable."""
    _not_applicable(prog, _NO_WASH_CHECKABLE, json_doc)


def _empty_radar_json(root: Path, args: argparse.Namespace):
    """The callable _not_applicable takes for `wash-radar --json`: the
    radar's document with no rows (taxjson_wash_radar's payload keys)."""
    def doc() -> Dict[str, Any]:
        from datetime import date as _date, datetime as _dt
        from taxjson.lib.wash_scope import scope_note
        country = _normalize_country(_country(
            _radar_config(root, "tjs wash-radar").get("settings", {})))
        return {"schema_version": 1, "country": country,
                "generated_at": _dt.now().isoformat(timespec="seconds"),
                "as_of_date": args.date or _date.today().isoformat(),
                "account": args.account,
                "include_all": bool(args.all),
                "rows_scoped": bool(args.account),
                "scope_note": scope_note(country),
                "sections": [], "similar": []}
    return doc if getattr(args, "json", False) else None


def cmd_wash_radar(args: argparse.Namespace) -> None:
    """Convenience wrapper over `taxjson-wash-radar`: resolve the taxable equity
    account base file(s) and the combined sheltered base, then run the radar
    live (against `--date`, defaulting to today) to stdout. All taxable accounts
    go into ONE invocation so the report — and its Definitions legend — prints
    once, in the fixed advisory order. Recomputes cooling-down windows as of now
    (the per-account reports/wash_radar_<account>.rpt are written by `tjs
    run`). An ACCOUNT scopes the rows shown (--show), never the books
    read: every taxable account still decides each status, as the
    engine pools them (audit 2026-10-23 #6)."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    _na_json = _empty_radar_json(root, args)

    if args.account:
        base = cache / f"{args.account}_base.json"
        if not base.exists():
            _die_input(f"no {base.name} in work/",
                       "Run `tjs run` first, or check the account "
                       "name.")
        _acct_cfg = _radar_config(
            root, "tjs wash-radar").get("accounts") or {}
        if (_acct_cfg.get(args.account) or {}).get("type") == "sheltered":
            # A usage error (the wrong account for the radar): exit 2,
            # as an unknown account's (TJ-0157); 1 is a verdict's
            # status (backlog TJ-0601).
            _die_input(f"{args.account} is a sheltered account",
                       "The radar advises on TAXABLE loss sales (sheltered "
                       "books are its context, not its subject).")
        _refuse_us_crypto_account(root, args.account, "tjs wash-radar",
                                  _na_json)
        # Every taxable book decides the statuses (the superficial-loss
        # pool and §1091 look across all your accounts); the account
        # only scopes the rows shown. It used to read this book alone,
        # so a sibling account's rebuy or loss was invisible (audit
        # 2026-10-23 #6).
        bases = _radar_taxable_bases(root, cache, "tjs wash-radar",
                                     empty_ok=True)
        if base.resolve() not in {b.resolve() for b in bases}:
            bases.append(base)
        show = ["--show", str(base), "--account", args.account]
    else:
        bases = _radar_taxable_bases(root, cache, "tjs wash-radar",
                                     json_doc=_na_json)
        show = []
    # Its SIMILAR groups (lib/similar, below) and renames: the lenient
    # loader dropped a line it could not parse (backlog TJ-0352).
    _strict_ticker_map(
        root, "its rename and SIMILAR rules decide which listings the "
        "radar's caveats join, so a status without the rule can miss "
        "one (`tjs run` refuses this map too)")

    cmd = _cmd("taxjson-wash-radar") + ["--taxable", *[str(b) for b in bases]]
    cmd += show
    cmd += _radar_engine_args(
        bases, root,
        _country(_radar_config(root, "tjs wash-radar").get(
            "settings", {})))
    # Cross-account superficial-loss detection needs the pooled sheltered
    # history; pass it when the pipeline has built it.
    sheltered_base = cache / "sheltered_base.json"
    if sheltered_base.exists():
        cmd += ["--sheltered", str(sheltered_base)]
    elif _sheltered_expected(root):
        note("tjs wash-radar",
             "no sheltered_base.json in work/ — registered-account "
             "(permanent-denial) context disabled",
             details=["Run a full `tjs run` to build it."])
    if args.date:
        # Same shape+calendar validation as `list --date` — the
        # standalone fed the raw string straight into strptime, so a
        # typo'd date died with a traceback instead of a usage error.
        # A date whose 30-day window leaves the calendar Python can
        # hold (9999-12-31) is refused too (issue #54).
        from taxjson.lib.dates import as_of_date_problem
        _bad = as_of_date_problem(args.date)
        if _bad:
            _die_input(_bad)
        cmd += ["--date", args.date]
    # The SIMILAR groups of ticker.map (lib/similar): the radar lists
    # each group's statuses (a caveat; the funds stay two securities).
    from taxjson.lib import similar as _SIM
    for _g in _SIM.booked_groups(root):
        cmd += ["--similar", " ".join(_g)]
    if args.all:
        cmd += ["--all"]
    if getattr(args, "json", False):
        cmd += ["--json"]
    elif not (_details(args) or args.verbose):
        # Essentials first (docs/output-style.md): the stage's full
        # report (reports/wash_radar_*.rpt) is the --details view.
        # --verbose is that view too: the radar never read the flag,
        # so it changed nothing (backlog TJ-0156).
        cmd += ["--brief"]
    _exec_tool(cmd)


def _radar_taxable_bases(root: Path, cache: Path,
                         prog: str, empty_ok: bool = False,
                         json_doc=None,
                         warn_missing: bool = True) -> List[Path]:
    """Taxable base files for a radar-style run. Prefer the config's
    wash-checkable taxable accounts (sheltered accounts are never
    radar'd; crypto is included only where the jurisdiction's wash
    rule covers it — see _taxable_equity_account_names). Fall back to
    globbing base files when there's no readable config. None of them
    stops the command (exit 0, _no_wash_checkable; `json_doc` its
    --json document). `warn_missing=False`: the caller says itself that
    a configured account has no books (watch: _radar_missing_context)."""
    names = _taxable_equity_account_names(root, prog)
    if names is not None and not names:
        if empty_ok:
            return []
        _no_wash_checkable(prog, json_doc)
    if names is not None:
        bases = [cache / f"{n}_base.json" for n in names
                 if (cache / f"{n}_base.json").exists()]
        # A configured taxable account without books used to vanish
        # from the checks in silence — a sibling's recent buy then read
        # as "SAFE — no tracked position" (S046-11).
        _skipped = _accounts_skipped_for_no_inputs(root)
        _missing = [n for n in sorted(names)
                    if not (cache / f"{n}_base.json").exists()
                    and n not in _skipped]
        if _missing and bases and warn_missing:
            from taxjson.lib.out import warn as _warn
            _warn(f"no books for taxable account(s) "
                  f"{', '.join(_missing)} (work/<account>_base.json "
                  f"missing)", prog=prog,
                  details=["Their trades are INVISIBLE to these window "
                           "checks, so a SAFE/CLEAR verdict here can be "
                           "wrong. Run `tjs run` to build them."])
    else:
        bases = [p for p in sorted(cache.glob("*_base.json"))
                 if not p.name.endswith("_raw_base.json")
                 and p.name != "sheltered_base.json"
                 and not p.name.startswith(".")]
    if not bases:
        from taxjson.lib.out import fail
        fail("no taxable base files in work/", prog=prog,
             details=["Run `tjs run` first."])
    return bases


def _has_tt_openings(root: Path) -> bool:
    from taxjson.lib.missing_history import has_tt_openings
    return has_tt_openings(root)


def _radar_engine_args(bases: List[Path],
                       project: Optional[Path],
                       country: str,
                       ticker_map: Optional[Path] = None) -> List[str]:
    """The radar's engine context, shared by every radar run (wash-radar,
    watch, buy-check, sell-check and the run's reports/wash_radar_*):
    the taxable accounts' gains files (wash-adjusted, s.47-blended — the
    engine decides which sales were losses), the project's .tt OPENING
    cost=unknown lines (the same openings the gains pass applies; the
    project folder `project` is passed when it has any), its
    country (Canada's per-holder s.54 test vs the US s.1091 rules), its
    transfer policy (--transfers-as-acquisitions) and its ticker.map
    (`ticker_map`, else the project's: the listings a TOBASE pair books
    as one security, whose calendars the radar's dates follow —
    backlog TJ-0446, TJ-0447)."""
    from taxjson.lib.report_model import resolve_gains_files
    # --country is required by the radar (lib/country): never omitted.
    out: List[str] = ["--country", _normalize_country(str(country))]
    if ticker_map is None and project is not None:
        ticker_map = _PL.ticker_map_path(Path(project))
    if ticker_map is not None and Path(ticker_map).is_file():
        out += ["--ticker-map", str(ticker_map)]
    by_dir: Dict[Path, Dict[str, Path]] = {}
    for b in bases:
        b = Path(b)
        if not b.name.endswith("_base.json"):
            continue
        name = b.name[:-len("_base.json")]
        found = by_dir.setdefault(b.parent, resolve_gains_files(b.parent))
        g = found.get(name)
        if g is not None:
            out += ["--gains", str(g)]
    if project is not None and _has_tt_openings(Path(project)):
        out += ["--incomplete-history", str(project)]
    if project is not None:
        # The project's transfer policy, as the engine passes read it
        # (CA-SL-16/17, US-WASH-23/24; pre-release review L5).
        try:
            from taxjson.lib.pipeline import transfers_as_acquisitions
            if transfers_as_acquisitions(_soft_settings(
                    Path(project))):
                out.append("--transfers-as-acquisitions")
        except Exception:                                  # noqa: BLE001
            pass
    # The project's .tt ALLOWLOSS filing positions (US-WASH-25): the US
    # radar's engine applies them as the gains pass does (pre-release
    # review; a claimed loss read WASHED).
    _work = {Path(b).parent for b in bases}
    if len(_work) == 1:
        out += _loss_override_flags(next(iter(_work)))
    if project is not None and out[1] == "canada":
        # The project's corporate_distributions list: the radar's own
        # pool moves a Canadian TRUST's return of capital to its record
        # date as the engine does, and leaves a listed corporation's on
        # its pay date (CA-INC-DATE-ROC-TRUST; audit A2-1174/A2-1178).
        try:
            _s = _soft_settings(Path(project))
            _corp = (_s.get("corporate_distributions") or [])
            # CA-SL-11 / CA-SL-12 in the radar's own pool too (a loss
            # outside the gains files' year — audit A2-0442).
            if _s.get("option_buyback_loss_superficial") is True:
                out.append("--option-buyback-wash")
        except Exception:                                  # noqa: BLE001
            _corp = []
        if isinstance(_corp, (list, tuple)):
            for _c in _corp:
                if isinstance(_c, str) and _c.strip():
                    out += ["--corporate-distribution", _c.strip()]
    return out


def _radar_missing_context(root: Path, cache: Path) -> List[str]:
    """The work/ books a radar run should read and cannot, as
    `work/<file>` names: each wash-checkable taxable account's
    <account>_base.json, and the combined sheltered_base.json when the
    project has a sheltered account (an account `tjs run` skipped
    for having no inputs has no books to miss). [] with no readable
    accounts table (the radar then globs work/)."""
    names = _taxable_equity_account_names(root) or []
    skipped = _accounts_skipped_for_no_inputs(root)
    out = [f"work/{n}_base.json" for n in sorted(names)
           if n not in skipped and not (cache / f"{n}_base.json").exists()]
    if (_sheltered_expected(root)
            and not (cache / "sheltered_base.json").exists()):
        out.append("work/sheltered_base.json")
    return out


def _watch_threshold(args: argparse.Namespace) -> float:
    """--threshold for the harvest dimension; an explicit 0 means "any
    move" (`or 100.0` turned it into 100, R1-242)."""
    v = getattr(args, "threshold", None)
    return 100.0 if v is None else float(v)


def cmd_watch(args: argparse.Namespace) -> None:
    """`tjs watch`: report only what CHANGED since the last watch
    run — new/changed/cleared radar advisories, moved clear dates, and
    (with --harvest) the harvestable-now loss total. Quiet (no output,
    exit 0) when nothing changed, so a cron line mails only on news.
    State lives in work/.watch_state.json; the first run records a
    baseline. `--exit-code` exits 1 on changes for scripting (the
    default stays 0 so chains like `tjs run watch` never fail on
    a mere report)."""
    import json as _json
    from datetime import date as _date
    from taxjson.bin import taxjson_watch as _watch
    from taxjson.lib.dispatch import run_cmd as _run
    root = Path(args.dir).resolve()
    cache = root / "work"

    def _na_doc() -> Dict[str, Any]:
        # No wash-checkable account: watch's document, nothing tracked
        # and no state written (backlog TJ-0330).
        from taxjson.lib.wash_scope import scope_note
        return {"baseline": False, "changes": [], "tracked": 0,
                "actionable": 0, "as_of": _date.today().isoformat(),
                "scope_note": scope_note(_country(_radar_config(
                    root, "tjs watch").get("settings", {})))}
    bases = _radar_taxable_bases(
        root, cache, "tjs watch",
        json_doc=_na_doc if getattr(args, "json", False) else None,
        warn_missing=False)
    cmd = _cmd("taxjson-wash-radar") + [
        "--taxable", *[str(b) for b in bases], "--all", "--json"]
    _wcountry = _country(_radar_config(root, "tjs watch").get(
        "settings", {}))
    cmd += _radar_engine_args(bases, root, _wcountry)
    # A CLEAR is "safe as far as this project's accounts show"
    # (CA-PLAN-04 / US-PLAN-04, re-audit A2-0909).
    from taxjson.lib.wash_scope import scope_note as _scope_note
    _scope = _scope_note(_wcountry)
    if getattr(args, "state", None):
        state_path = Path(args.state)
        if not state_path.is_absolute():
            state_path = root / state_path
        # A directory, a path under a file or an unwritable place gave
        # an 11-line traceback (S046-12) — one line, like
        # --write-missing-history.
        if state_path.is_dir():
            _die_input(f"--state {args.state} is a directory",
                       f"Pass a FILE path, e.g. "
                       f"{state_path / 'watch_state.json'}")
        try:
            state_path.parent.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            _die_input(f"cannot create the folder for --state "
                       f"{args.state}: {e}",
                       "Pass a FILE path in a writable folder.")
    else:
        state_path = cache / ".watch_state.json"

    # The books the radar's verdicts need. Without the registered
    # accounts' combined books a LOCKED name read CLEAR, "safe to sell
    # at a loss", and that state replaced the baseline (backlog
    # TJ-0303); a taxable account's missing books hide its buys the
    # same way. Nothing is compared or saved until they are back.
    missing = _radar_missing_context(root, cache)
    if missing:
        since = _watch.baseline_date(state_path)
        kept = (f"the baseline of {since} is kept" if since
                else "no baseline is recorded")
        from taxjson.lib.out import warn as _warn
        _one = len(missing) == 1
        _warn(f"nothing compared: {', '.join(missing)} "
              f"{'is' if _one else 'are'} missing, and without "
              f"{'it' if _one else 'them'} the radar misses those "
              f"accounts' buys (a LOCKED name reads CLEAR); {kept}",
              prog="tjs watch",
              details=["Run a full `tjs run` to rebuild "
                       f"{'it' if _one else 'them'}, then `tjs "
                       "watch` again."])
        if getattr(args, "json", False):
            _json_out({"baseline": False, "changes": [],
                       "incomplete": missing, "tracked": None,
                       "actionable": None,
                       "as_of": _date.today().isoformat(),
                       "since": since, "scope_note": _scope})
        return
    sheltered_base = cache / "sheltered_base.json"
    if sheltered_base.exists():
        cmd += ["--sheltered", str(sheltered_base)]
    res = _run(cmd, capture_output=True)
    if res.returncode != 0:
        _die("the wash radar failed", _child_error(res.stderr))
    try:
        radar_doc = _json.loads(res.stdout)
    except ValueError as e:
        _die(f"the wash radar emitted unparseable JSON: {e}")
    cur_radar = _watch.flatten_radar(radar_doc)
    as_of = radar_doc.get("as_of_date") or _date.today().isoformat()

    harvest_now = None
    # The positions this run's harvest total leaves out (backlog
    # TJ-0912): compared with the baseline's before the totals are.
    harvest_left: List[Dict[str, str]] = []
    harvest_valued: List[str] = []
    if (getattr(args, "threshold", None) not in (None, 100.0)
            and not getattr(args, "harvest", False)):
        note("tjs watch", "--threshold only applies with --harvest "
             "(ignored this run).")
    if getattr(args, "harvest", False):
        hcmd = _self_cmd(root, "harvest", "--json")
        if getattr(args, "no_ibkr", False):
            hcmd.append("--no-ibkr")
        hres = _run(hcmd, capture_output=True)
        if hres.returncode != 0:
            from taxjson.lib.out import warn as _warn
            _warn("harvest failed — the harvest dimension is skipped "
                  "this run", prog="tjs watch",
                  details=[_child_error(hres.stderr)])
        else:
            try:
                hdoc = _json.loads(hres.stdout)
                harvest_now = float(
                    ((hdoc.get("totals") or {}).get("harvestable")
                     or {}).get("now") or 0.0)
                harvest_left = _watch.harvest_left_out(hdoc)
                harvest_valued = _watch.harvest_valued(hdoc)
            except (ValueError, TypeError, AttributeError) as e:
                harvest_now = None
                from taxjson.lib.out import warn as _warn
                _warn(f"harvest JSON unreadable ({e}) — skipped this "
                      f"run.", prog="tjs watch")

    def _save(harvest_value, harvest_omitted=None,
              valued=None) -> None:
        try:
            _watch.save_state(state_path, cur_radar, harvest_value, as_of,
                              harvest_omitted, valued)
        except OSError as e:
            _die_input(f"cannot write the watch state {state_path}: {e}",
                       "Pass a writable FILE path with --state.")

    _left_keys = [x["key"] for x in harvest_left]
    state = _watch.load_state(state_path)
    if state is None:
        _save(harvest_now, _left_keys if harvest_now is not None else None,
              harvest_valued if harvest_now is not None else None)
        actionable = sum(1 for r in cur_radar.values()
                         if r.get("category") in _watch._ACTIONABLE)
        if getattr(args, "json", False):
            _json_out({"baseline": True, "changes": [], "incomplete": [],
                       "tracked": len(cur_radar),
                       "actionable": actionable, "as_of": as_of,
                       "scope_note": _scope})
        else:
            from taxjson.lib.out import fill
            print(f"WATCH — baseline recorded (as of {as_of})")
            print(fill(f"{len(cur_radar)} ticker(s) tracked, {actionable} "
                       f"actionable advisories. Future runs report only "
                       f"changes."))
        return

    changes = _watch.diff_radar(state.get("radar") or {}, cur_radar)
    harvest_incomplete: List[str] = []
    saved_left = state.get("harvest_omitted")
    saved_valued = state.get("harvest_valued")
    _cover = (_watch.harvest_coverage(saved_left, _left_keys, saved_valued)
              if harvest_now is not None
              and state.get("harvest_now") is not None else "same")
    if harvest_now is not None and _cover == "worse":
        # The total leaves out a position the baseline valued (its FX
        # rate or price is missing this run): the move is the coverage,
        # not the market. A "fell from 200 to 100" alert, then a "rose"
        # one when the rate came back, and the partial total replaced
        # the baseline (backlog TJ-0912). Nothing compared; the
        # baseline is kept.
        _was = set(saved_left or [])
        _new = [x["shown"] for x in harvest_left if x["key"] not in _was
                and (saved_valued is None or x["key"] in saved_valued)]
        harvest_incomplete = [f"harvest: {t}" for t in _new]
        from taxjson.lib.out import warn as _warn
        _warn(f"harvestable losses not compared: {len(_new)} "
              f"position(s) the baseline valued are left out this run "
              f"({', '.join(_new)}); the baseline of "
              f"{state.get('as_of') or '?'} is kept",
              prog="tjs watch",
              details=["`tjs harvest` names what is missing (a rate: "
                       "`tjs run`; a price: run it online)."])
        saved_harvest = state.get("harvest_now")
        _save(saved_harvest, saved_left, saved_valued)
    elif harvest_now is not None:
        # A position left out that the baseline never valued is in
        # neither total: the totals still compare (backlog TJ-1040).
        _unvalued = [x["shown"] for x in harvest_left
                     if saved_left is not None
                     and x["key"] not in saved_left]
        if _unvalued:
            note("tjs watch", f"not in the harvestable total: "
                                  f"{', '.join(_unvalued)} (`tjs "
                                  f"harvest` names what is missing).")
        if _cover == "same":
            hch = _watch.diff_harvest(state.get("harvest_now"),
                                      harvest_now, _watch_threshold(args))
            if hch:
                changes.append(hch)
        # "better": it values positions the baseline left out — not
        # comparable either, but the fuller total becomes the baseline.
        saved_harvest = harvest_now
        _save(saved_harvest, _left_keys, harvest_valued)
    else:
        # This run didn't compute a harvest total (no --harvest, or a
        # transient harvest failure) — CARRY the previous baseline
        # forward. Dropping it meant alternating `watch` /
        # `watch --harvest` cron lines re-baselined every time and a
        # harvest change was never reported.
        saved_harvest = state.get("harvest_now")
        _save(saved_harvest, saved_left, saved_valued)

    actionable = sum(1 for r in cur_radar.values()
                     if r.get("category") in _watch._ACTIONABLE)
    if getattr(args, "json", False):
        _json_out({"baseline": False, "changes": changes,
                   "incomplete": harvest_incomplete,
                   "tracked": len(cur_radar),
                   "actionable": actionable,
                   "as_of": as_of, "since": state.get("as_of"),
                   "scope_note": _scope})
    elif changes:
        print(_watch.render_report(changes, as_of,
                                   since=state.get("as_of"),
                                   scope=_scope))
    if changes and getattr(args, "exit_code", False):
        raise SystemExit(1)


def _no_fetcher_exit() -> None:
    """`tjs fetch` with no fetcher plugin installed: one line, exit 2
    (the core ships no broker client; lib/fetchers)."""
    from taxjson.lib.fetchers import INSTALL_HINT
    # One message (one line when captured): the checklist and scripts
    # read a failed command's last line.
    _die_input(f"no fetcher is installed — {INSTALL_HINT}.")


def cmd_fetch(args: argparse.Namespace) -> None:
    """`tjs fetch [ACCOUNT ...]`: the thin dispatcher over the
    installed fetcher plugins (entry-point group `taxjson.fetchers`;
    lib/fetchers). Each [accounts.<name>] with a `brokerage` goes to the
    fetcher that serves that brokerage; the core itself holds no broker
    client and reads no credential. `--list` names the installed
    fetchers. Run `tjs run` afterwards (or chain: `tjs fetch
    run`)."""
    from taxjson.lib import fetchers as FP
    found, problems = FP.discover()
    for msg in problems:
        _say("warning", msg, prog=f"{_PROG} fetch")
    if getattr(args, "list", False):
        rows = FP.listing()
        if getattr(args, "json", False):
            _json_out({"fetchers": rows})
        elif not rows:
            _no_fetcher_exit()
        else:
            for r in rows:
                print(f"{r['name']}"
                      + (f" ({r['distribution']})" if r["distribution"]
                         else "")
                      + f": {', '.join(r['brokerages']) or '-'}")
                if r["description"]:
                    for _ln in _out_wrap(r["description"], indent="  "):
                        print(_ln)
        return
    if not found:
        _no_fetcher_exit()
    chosen = found
    if getattr(args, "fetcher", None):
        chosen = [f for f in found if f.name == args.fetcher]
        if not chosen:
            _die(f"no installed fetcher named {args.fetcher!r}",
                 f"Installed: {', '.join(f.name for f in found)}; see "
                 f"`tjs fetch --list`.")
    serves = FP.served_brokerages(chosen)
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    declared = FP.declared_brokerages(cfg)
    if not declared:
        hints = [f.setup_hint for f in chosen if f.setup_hint]
        _die("no account declares a fetch source",
             *(hints or ["Add `brokerage = \"...\"` under "
                         f"[accounts.<name>] in taxjson.toml "
                         f"({', '.join(sorted(serves))})."]))
    accounts_cfg = cfg.get("accounts", {})
    wanted = list(args.account) if args.account else list(declared)
    for a in wanted:
        if a not in declared:
            _die(f"[accounts.{a}] declares no `brokerage`"
                 if a in accounts_cfg else
                 f"no [accounts.{a}] in taxjson.toml")
    if not args.account:
        wanted = sorted(wanted)
    by_fetcher: Dict[str, List[str]] = {}
    for a in wanted:
        f = serves.get(declared[a])
        if f is None:
            _die(f"[accounts.{a}] brokerage {declared[a]!r} has no "
                 f"installed fetcher",
                 f"Served: {', '.join(sorted(serves)) or 'none'}; see "
                 f"`tjs fetch --list`.")
        by_fetcher.setdefault(f.name, []).append(a)
    json_mode = bool(getattr(args, "json", False))
    dry_run = bool(getattr(args, "dry_run", False))
    # TAXJSON_OFFLINE forbids taxjson's network egress, and a fetch IS
    # egress (a dry run too: it still downloads to preview). Refused here,
    # before any plugin runs (security review L6); --list stays allowed.
    from taxjson.lib.offline import ENV_VAR as _OFF_VAR, offline_enabled
    if offline_enabled():
        # One message (one line when captured).
        _die(f"{_OFF_VAR} is set — a fetch downloads from the broker, so "
             f"nothing was fetched; unset it (or set {_OFF_VAR}=0) to "
             f"fetch.")

    def say(msg: str) -> None:
        # Progress lines move to stderr under --json so stdout stays
        # a single machine-readable document. A plugin's `note:` line is
        # shown with its label first (`Info:`, lib/out.labelled).
        from taxjson.lib.out import labelled
        stream = sys.stderr if json_mode else sys.stdout
        print(labelled(msg, stream), file=stream)

    results: Dict[str, Any] = {}
    for f in chosen:
        accts = by_fetcher.get(f.name)
        if not accts:
            continue
        # Where the downloads and the positions go (lib/project_layout):
        # the shared inputs folder of a multi-year project, the year's
        # holdings folder.
        req = FP.FetchRequest(root=root, work=root / "work", config=cfg,
                              accounts=accts, args=args, say=say,
                              dry_run=dry_run, json=json_mode,
                              inputs=_PL.inputs_dir(root),
                              holdings=_PL.holdings_folder(root),
                              shared_inputs=_PL.shared_inputs(root))
        out = f.impl.fetch(req) or {}
        for a, r in out.items():
            results.setdefault(a, {}).update(r or {})
    if json_mode:
        _json_out({"accounts": results, "dry_run": dry_run})
    elif not dry_run:
        print("fetch complete: run `tjs run` to rebuild (or chain: "
              "`tjs fetch run`).")


FX_CASH_LEDGERS = ("v1", "v2")


def _fx_cash_ledger_choice(settings: Dict[str, Any],
                           flag: Optional[str] = None) -> str:
    """Which FX-on-cash ledger: `--ledger` when given, else [settings]
    fx_cash_ledger, else "v1" — the default, flagged NOT RELIABLE
    (CA-FX-07 / US-FX-03). v2 stays opt-in until it has been audited."""
    v = flag or (settings or {}).get("fx_cash_ledger") or "v1"
    v = str(v).strip().lower()
    if v not in FX_CASH_LEDGERS:
        sys.exit(exit_text(f"tjs fx-cash: fx_cash_ledger must be "
                           f"\"v1\" or \"v2\" (got {v!r})"))
    return v


def _fx_cash_status(root: Path, cache: Path,
                    ledger: Optional[str] = None) -> Dict[str, Any]:
    """The FX-on-cash result every output shares (sum, fx-cash --json,
    checklist, the end-of-run note): `reliable`, `headline` (the one
    line shown in place of a reportable figure), `reasons`, and the
    figures only where they may be quoted. v1 (default): NOT RELIABLE,
    the raw numbers under `unreliable_raw`. v2 (opt-in): `computed`
    (labelled under audit) or `not_computed` with its problems."""
    from taxjson.bin import taxjson_fx_cash as FX
    settings = (_soft_config(root).get("settings") or {})
    which = _fx_cash_ledger_choice(settings, ledger)
    if which == "v2":
        return _fx_cash_v2_status(root, cache)
    doc, verdict, base, year, country = _fx_cash_doc(root, cache)
    st = FX.unreliable_status(doc, year, verdict)
    st.update(year=year, currency=base, rule=verdict.get("rule"))
    return st


def _fx_sum_item(st: Dict[str, Any], money) -> str:
    """`tjs sum` FOR THE RETURN's FX-on-cash line."""
    if st.get("ledger") == "v2" and st.get("status") == "computed":
        return (f"FX on foreign cash, ledger {st.get('label')}, "
                f"s.39(1.1): net {money(st['net_gain'])}, reportable "
                f"{money(st['reportable'])} after the $200 exemption — not "
                f"in the rows above; T4037 puts it on line 15300. Review "
                f"`tjs fx-cash` and mark the checklist's fx-cash step "
                f"reviewed before using it.")
    if st.get("ledger") == "v2":
        return (st["headline"] + " (`tjs fx-cash` lists each "
                "problem).")
    return (st["headline"] + " (line 15300; `tjs fx-cash` shows the "
            "raw ledger, and the opt-in ledger v2 reads the missing "
            "cash events).")


def _fx_cash_native(root: Path, cache: Path, prog: str = "tjs fx-cash"):
    """(rows, base, year, country, fx history) for the FX-on-cash
    ledgers (and `tjs cash`, `prog` naming it in the errors): every
    TAXABLE account's native rows (each with `account`) — s.39(1.1) /
    §988 reach the person's taxable holdings; registered accounts are
    exempt."""
    from taxjson.lib.price_chain import load_fx_history
    cfg = _soft_config(root)
    settings = cfg.get("settings", {}) or {}
    base = str(_base(settings)).upper()
    year = settings.get("year")
    if not year:
        sys.exit(exit_text(f"{prog}: needs [settings] year in "
                           "taxjson.toml."))
    country = _country(settings)
    txs: List[Dict[str, Any]] = []
    found = False
    for name, acfg in sorted((cfg.get("accounts") or {}).items()):
        if (acfg or {}).get("type") != "taxable":
            continue
        f = _native_tx_file(cache, name)
        if f is None:
            if _has_inputs(root, name):
                # A partial ledger flipped the line-15300 figure's sign
                # with rc 0 (S005-04, S046-19).
                sys.exit(exit_text(f"{prog}: no native transaction file "
                                   f"for taxable account {name!r} — run `tjs "
                                   f"run` first; a ledger without it would be "
                                   f"partial."))
            continue
        try:
            doc = _read_work_doc(f)
        except (OSError, ValueError) as e:
            _m = str(e)                 # (named once: A2-1413)
            sys.exit(exit_text(f"{prog}: "
                               f"{_m if str(f) in _m else f'could not read {f}: {_m}'}"
                               + ("" if "tjs run" in _m else
                        " — re-run `tjs run` to rebuild it")
                               + f"; a ledger without account {name!r} would be "
                       f"partial."))
        found = True
        for t in doc.get("transactions", []):
            t.setdefault("account", name)
            txs.append(t)
    if not found:
        sys.exit(exit_text(f"{prog}: no native transaction files in "
                           f"{cache} (run `tjs run` first)."))
    try:
        fx = load_fx_history(cache / "to_base.csv", base)
    except (OSError, ValueError) as e:
        sys.exit(exit_text(f"{prog}: error: {e}"))
    return txs, base, int(year), country, fx


def cmd_cash(args: argparse.Namespace) -> None:
    """`tjs cash`: the cash events of the taxable accounts over a
    window — the conversions, deposits and withdrawals the exports carry
    and the project's .tt cash lines, the rows the FX-on-cash ledger v2
    reads — each as the .tt line that declares it (lib/cash_events
    tt_line: FXCONV, CASHMOVE, CASHOPEN; a fee as a `#FEE` comment
    line), oldest to latest, with per-currency totals. A broker's move
    that no .tt line declares shows `?` where its own / kept / spot /
    cost= / proceeds= goes; one in the base currency needs none (a
    `#CASHMOVE` comment line). Statement balances are not listed (`tjs
    fx-cash --ledger v2` reconciles them). `[PERIOD] [ACCOUNT]` as
    `tjs events`."""
    from taxjson.lib import cash_events as CE
    root = Path(args.dir).resolve()
    cache = root / "work"
    keep, scope, account = _view_window(args, root)
    cfg = _soft_config(root)
    accounts = cfg.get("accounts") or {}
    taxable = sorted(n for n, c in accounts.items()
                     if isinstance(c, dict) and c.get("type") == "taxable")
    if account:
        if account not in accounts:
            _die(f"no account {account!r} in taxjson.toml",
                 f"Accounts: {', '.join(sorted(accounts)) or 'none'}.")
        if account not in taxable:
            _die(f"account {account!r} is not a taxable account",
                 "Cash events are read for the taxable accounts "
                 "(s.39(1.1) / §988 reach those alone): "
                 f"{', '.join(taxable) or 'none'}.")
    txs, _base, _year, country, _fx = _fx_cash_native(root, cache,
                                                       prog="tjs cash")
    by_label: Dict[str, List[Dict[str, Any]]] = {}
    for t in txs:
        by_label.setdefault(str(t.get("account")), []).append(t)
    try:
        cash = CE.collect(root, cfg, country, by_label)
    except (OSError, ValueError) as e:
        _die(str(e))
    CE.apply_declarations(cash["events"], cash["lines"])
    for p in list(cash["problems"]) + list(cash.get("warnings") or []):
        _view_msg("warning", p)
    evs = [e for e in list(cash["events"])
           + [x for x in cash["lines"] if not x.get("matched")]
           if e.get("date") and keep(e["date"])
           and (not account or e.get("label") == account)]
    evs.sort(key=lambda e: (e["date"], e.get("label") or "", e["kind"]))
    # Each line with the at= its copy needs to stay in its book (backlog
    # TJ-0889).
    rows = [(e, ln) for e, ln in
            ((e, CE.tt_line(e, _base, at=CE.at_token(e, cash["books"])))
             for e in evs)
            if ln]

    # Per-currency totals: deposits (+) and withdrawals (-), the
    # conversions per currency pair, the fees paid, and the other cash
    # a cash event brought in (a stock-lending receipt, a rebate: a
    # FLOW received, never a fee; backlog TJ-0693).
    dep: Dict[str, float] = {}
    wd: Dict[str, float] = {}
    conv: Dict[str, float] = {}
    fees: Dict[str, float] = {}
    credits: Dict[str, float] = {}
    for e, _ln in rows:
        k = e["kind"]
        if k == "CASHMOVE":
            d = dep if e["amount"] > 0 else wd
            d[e["currency"]] = d.get(e["currency"], 0.0) + abs(e["amount"])
        elif k == "FXCONV":
            pair = f"{e['from_ccy']}->{e['to_ccy']}"
            conv[pair] = conv.get(pair, 0.0) + float(e["from_amt"])
        elif k == "FLOW" and e.get("leg") != "trade":
            d = credits if float(e["amount"]) > 0 else fees
            d[e["currency"]] = d.get(e["currency"], 0.0) + abs(e["amount"])
    if getattr(args, "json", False):
        _json_out({"scope": scope, "account": account,
                   "rows": [dict({k: v for k, v in e.items()
                                  if not k.startswith("_")}, tt=ln)
                            for e, ln in rows],
                   "totals": {"deposits": dep, "withdrawals": wd,
                              "converted": conv, "fees": fees,
                              "credits": credits},
                   "problems": list(cash["problems"])})
        return
    if not rows:
        print("(no cash events in this window)")
        return
    # One account prints the lines as they are; the merged view prefixes
    # each with its account, as `tjs events` does. The keyword, date,
    # currency and amount line up in columns (the amounts on their
    # decimal points); what follows (a conversion's other side, a move's
    # declaration) is as written, and the comments line up after the
    # longest line.
    prefix = not account and len(taxable) != 1
    head_n = 5 if prefix else 4
    heads, tails = [], []
    for e, ln in rows:
        parts = (f"{e['label']} {ln}" if prefix else ln).split()
        heads.append(" ".join(parts[:head_n]))
        tails.append(" ".join(parts[head_n:]))
    bodies = [f"{h} {t}" if t else h for h, t in
              zip(_align_columns(heads, numeric_right=True, header=False),
                  tails)]
    comments = [CE.tt_comment(e) for e, _ln in rows]
    width = max(len(b) for b in bodies)
    for body, c in zip(bodies, comments):
        print(f"{body:<{width}}  # {c}" if c else body)

    def _fmt(d: Dict[str, float]) -> str:
        return ", ".join(f"{v:,.2f} {c}" for c, v in sorted(d.items()))
    footer = [(lbl, d) for lbl, d in
              (("TOTAL DEPOSITS:", dep), ("TOTAL WITHDRAWALS:", wd),
               ("TOTAL CONVERTED:", conv), ("TOTAL FEES:", fees),
               ("TOTAL OTHER CREDITS:", credits)) if d]
    if footer:
        print()
        _w = max(len(lbl) for lbl, _d in footer)
        for lbl, d in footer:
            if prefix:
                _vprint(f"{lbl:<{_w}} {_fmt(d)}", hang=" " * (_w + 1))
            else:
                print(f"{lbl:<{_w}} {_fmt(d)}")


def _fx_cash_doc(root: Path, cache: Path):
    """(doc, verdict, base, year, country) for the default (v1) FX-cash
    report — shared by the fx-cash command and the end-of-run hook."""
    from taxjson.bin import taxjson_fx_cash as FX
    txs, base, year, country, fx = _fx_cash_native(root, cache)
    try:      # a futures refusal (A2-1424/1434)
        ledger = FX.build_ledger(txs, base, fx, int(year), country=country)
    except (OSError, ValueError) as e:
        sys.exit(exit_text(f"tjs fx-cash: error: {e}"))
    verdict = FX.apply_jurisdiction(ledger["net_gain"], country)
    return ledger, verdict, base, int(year), country


def _fx_cash_carry(root: Path, settings: Dict[str, Any], year: int,
                   country: Optional[str] = None
                   ) -> Optional[Dict[str, Any]]:
    """The prior year's v2 close (close-year's `fx_cash_v2` in the
    prior-year record: filed/<year-1>.json, or the record [settings]
    prior_year_record names). None when there is no record, or it
    carries no close (closed under the default ledger). A record that
    EXISTS but cannot be read, is not a close-year record, carries
    another year's close, or was closed under the other country
    (`country`: this project's) is {"year", "books": {}, "problem":
    text}: lib/fx_cash_v2.build lists the problem and computes nothing.
    It used to read as no record, and an empty year was certified on it
    (2026-10 audit C02, C04)."""
    import json as _json
    from taxjson.bin.taxjson_filed import (PriorRecordError,
                                           prior_record_setting)
    from taxjson.lib.country import (CountryError, canonical_country,
                                     display_name, home_currency)

    def bad(text: str) -> Dict[str, Any]:
        return {"year": year - 1, "books": {}, "problem": text}
    try:
        p = prior_record_setting(root, settings)
    except PriorRecordError as e:
        return bad(str(e))
    label = (f"[settings] prior_year_record ({p})" if p is not None
             else f"filed/{year - 1}.json")
    if p is None:
        p = root / "filed" / f"{year - 1}.json"
    p = Path(p)
    if not p.exists():
        # A filed year's deleted lock is a problem, not "no record"
        # (backlog TJ-0272); a year never closed has none to miss.
        from taxjson.bin.taxjson_filed import missing_lock_problem
        _gone = missing_lock_problem(p, label)
        return bad(_gone) if _gone else None
    try:
        rec = _json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return bad(f"{label}: the prior-year record cannot be read ({e}) "
                   f"— restore it from git or re-close {year - 1}; until "
                   f"then this year's opening pool is unknown")
    if not isinstance(rec, dict):
        return bad(f"{label}: not a close-year record (not a JSON "
                   f"object) — restore it from git or re-close {year - 1}")
    # A record closed under the default ledger carries no pool, whatever
    # its country: no carry (backlog TJ-0022: the country check came
    # first and refused a year that had nothing to carry).
    close = rec.get("fx_cash_v2")
    if close is None:
        return None
    rc = rec.get("country")
    if country is not None and rc not in (None, ""):
        here = canonical_country(country)
        try:
            rcc = canonical_country(rc, what=f"{label} country")
        except CountryError as e:
            return bad(f"{e} — the record cannot be checked against this "
                       f"project; restore it from git or re-close "
                       f"{year - 1}")
        if rcc != here:
            # `foreign`: CASHOPEN lines open the year instead, and the
            # record is then only noted (lib/fx_cash_v2._carry_openings).
            return dict(bad(
                f"{label} was closed under country = \"{rcc}\" "
                f"({display_name(rcc)} law) but this project is "
                f"country = \"{here}\" ({display_name(here)}): its "
                f"foreign-cash pool (costs in {home_currency(rcc)}) "
                f"cannot open a {display_name(here)} year — set "
                f"[settings] country = \"{rcc}\" if that is wrong, "
                f"else open the year with CASHOPEN lines "
                f"(docs/settings.md)"), foreign=(
                f"{label} was closed under country = \"{rcc}\" "
                f"({display_name(rcc)} law): its foreign-cash pool is not "
                f"carried into this {display_name(here)} year, which opens "
                f"from its CASHOPEN lines"))
    if not isinstance(close, dict) or not isinstance(close.get("books"),
                                                     dict):
        return bad(f"{label}: its fx_cash_v2 close is not a table of books "
                   f"— the record is damaged; restore it from git or "
                   f"re-close {year - 1} with this ledger")
    if close.get("year") != year - 1:
        return bad(f"{label}: its fx_cash_v2 close is {close.get('year')!r}'s, "
                   f"not {year - 1}'s — the record is damaged or names the "
                   f"wrong year; restore it from git or re-close {year - 1}")
    return close


def _fx_cash_carry_record(settings: Dict[str, Any], year: int) -> str:
    """The prior-year record a carry's repair names
    (lib/fx_cash_v2._carry_openings): [settings] prior_year_record as
    written, else filed/<year-1>.json. A repair used to name
    filed/<year-1>.json whatever file was read (backlog TJ-0068)."""
    rec = str(settings.get("prior_year_record") or "").strip()
    return rec or f"filed/{year - 1}.json"


def _fx_cash_v2_doc(root: Path, cache: Path, holdings: bool = False,
                    holdings_basis: str = "settle"):
    """(doc, verdict or None, cash, base, year, country) of the opt-in
    ledger v2 (lib/fx_cash_v2): the native rows attributed to their
    broker account's book, the cash events (lib/cash_events), the prior
    year's close. `holdings`: the doc carries each book's cash day by
    day (lib/fx_cash_v2.build; `tjs t1135`), on the date basis
    `holdings_basis` (the project's tax_date: backlog TJ-0627)."""
    import re as _re
    from taxjson.lib import cash_events as CE
    from taxjson.lib import fx_cash_v2 as V2
    from taxjson.bin import taxjson_fx_cash as FX
    from taxjson.lib.price_chain import latest_rate
    txs, base, year, country, fx = _fx_cash_native(root, cache)
    cfg = _soft_config(root)
    settings = cfg.get("settings", {}) or {}
    by_label: Dict[str, List[Dict[str, Any]]] = {}
    for t in txs:
        by_label.setdefault(str(t.get("account")), []).append(t)
    try:
        cash = CE.collect(root, cfg, country, by_label)
    except (OSError, ValueError) as e:
        sys.exit(exit_text(f"tjs fx-cash: error: {e}"))
    books = cash["books"]
    for t in txs:
        src = _re.sub(r"#\d+$", "", str(t.get("source") or ""))
        t["_book"] = books.for_file(str(t.get("account")), src,
                                    str(t.get("source_account") or ""))

    def rate_of(cur: str, d: str):
        r, _d = latest_rate(fx, cur, d,
                            max_age_days=FX.FX_MAX_RATE_AGE_DAYS)
        return r
    carry = _fx_cash_carry(root, settings, year, country=country)
    if carry:
        carry = dict(carry, record=_fx_cash_carry_record(settings, year))
    try:
        doc = V2.build(txs, cash, base, year, rate_of, country=country,
                       carry=carry,
                       inflow_spot=str(settings.get("fx_cash_inflow_cost")
                                       or "").strip().lower() == "spot",
                       holdings=holdings, holdings_basis=holdings_basis)
    except ValueError as e:
        sys.exit(exit_text(f"tjs fx-cash: error: {e}"))
    verdict = FX.v2_verdict(doc, country)
    return doc, verdict, cash, base, year, country


def _fx_cash_v2_status(root: Path, cache: Path) -> Dict[str, Any]:
    from taxjson.lib import fx_cash_v2 as V2
    doc, verdict, _cash, base, year, _country = _fx_cash_v2_doc(root, cache)
    st = {"ledger": "v2", "label": V2.LABEL, "status": doc["status"],
          "reliable": doc["status"] == "computed", "under_audit": True,
          "headline": V2.headline(doc, verdict),
          "reasons": [p["text"] for p in doc["problems"]],
          "problems": doc["problems"], "year": year, "currency": base}
    if verdict is not None:
        st.update(net_gain=doc["net_gain"],
                  reportable=verdict["reportable"], rule=verdict["rule"],
                  review_key=f"v2|{year}|{verdict['reportable']:.2f}")
    return st


def _cmd_fx_cash_v2(root: Path, cache: Path, args) -> None:
    from taxjson.lib import fx_cash_v2 as V2
    doc, verdict, cash, base, year, country = _fx_cash_v2_doc(root, cache)
    evs = None
    if getattr(args, "cash_events", False):
        evs = sorted(list(cash["events"]) + list(cash["lines"]),
                     key=lambda e: (e.get("date", ""), e.get("book") or ""))
    if getattr(args, "json", False):
        out = dict(doc)
        out["headline"] = V2.headline(doc, verdict)
        if verdict is not None:
            out.update(reportable=verdict["reportable"],
                       rule=verdict["rule"],
                       review_key=f"v2|{year}|{verdict['reportable']:.2f}")
        if not getattr(args, "events", False):
            out["events"] = None
        if evs is not None:
            out["cash_events"] = [{k: v for k, v in e.items()
                                   if not k.startswith("_")} for e in evs]
        _json_out(out)
        return
    print(V2.render(doc, verdict, country, cash_events=evs))
    if getattr(args, "events", False) and doc["events"]:
        from taxjson.lib import out as _o
        print()
        print("EVENTS")
        print("\n".join(_o.fit_table(
            ["DATE", "BOOK", "CUR", "UNITS", "RATE", "GAIN", "WHAT"],
            [[e["date"], e["book"], e["currency"], f"{e['units']:,.2f}",
              f"{e['rate']:g}" if e["rate"] is not None else "-",
              f"{e['gain']:+,.2f}", e["what"] or "-"]
             for e in doc["events"]],
            aligns=["<", "<", "<", ">", ">", ">", "<"], key=0)))


def cmd_fx_cash(args: argparse.Namespace) -> None:
    """`tjs fx-cash`: FX gains on foreign-currency cash (ITA
    s.39(1.1) with the $200 de minimis; the §988 ordinary-income figure
    for US projects). A standalone REPORT — nothing here changes the
    engine's gains, sum, or the filing exports. The default ledger (v1)
    is NOT RELIABLE and says so first; `--ledger v2` (or [settings]
    fx_cash_ledger = "v2") runs the opt-in ledger that reads the cash
    events and refuses instead of guessing (lib/fx_cash_v2)."""
    from taxjson.bin import taxjson_fx_cash as FX
    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = (_soft_config(root).get("settings") or {})
    which = _fx_cash_ledger_choice(settings, getattr(args, "ledger", None))
    if which == "v2":
        _cmd_fx_cash_v2(root, cache, args)
        return
    ledger, verdict, base, year, country = _fx_cash_doc(root, cache)
    st = FX.unreliable_status(ledger, year, verdict)
    if getattr(args, "json", False):
        _json_out({"ledger": "v1", "status": st["status"],
                   "reliable": False, "active": st["active"],
                   "headline": st["headline"],
                   "reasons": st["reasons"],
                   "overdrafts_in_year": st["overdrafts_in_year"],
                   "unreliable_raw": st["unreliable_raw"],
                   "per_currency": ledger["per_currency"],
                   "events": (ledger["events"]
                              if getattr(args, "events", False)
                              else None),
                   "rule": verdict["rule"],
                   "overdrafts": ledger["overdrafts"],
                   "unrated": ledger["unrated"],
                   "open_pools": ledger["pools"],
                   "pools_year_end": ledger.get("pools_year_end") or {},
                   "currency": base, "year": year})
        return
    print((FX.render_report if _details(args) else FX.render_brief)(
        ledger, base, year, country, verdict))
    if getattr(args, "events", False) and ledger["events"]:
        print()
        print("EVENTS")
        print("\n".join(FX.render_events(ledger["events"])))


def _radar_country_is_usa(root: Path) -> bool:
    """Wording only, AFTER _wash_class_context: the radar it ran was
    given the project's country through the one resolver (a missing or
    unknown country already stopped it), so this only picks the rule's
    name for the text."""
    from taxjson.lib.country import CountryError, canonical_country
    try:
        return canonical_country(_soft_settings(root).get("country")) \
            == "usa"
    except CountryError:
        return False


def _us_crypto_coins(root: Path, cache: Path, prog: str
                     ) -> Dict[str, List[str]]:
    """{SYMBOL: [account, ...]} for the coins in a US project's crypto
    accounts' books ({} in Canada, where crypto accounts are radar'd
    like any other: CA-SL-13)."""
    import json as _json
    from taxjson.lib.core import is_option_symbol
    cfg = _radar_config(root, prog) or {}
    if _country(cfg.get("settings") or {}) != "usa":
        return {}
    out: Dict[str, List[str]] = {}
    for n, c in sorted((cfg.get("accounts") or {}).items()):
        if not ((c or {}).get("type") == "taxable"
                and (c or {}).get("crypto")):
            continue
        try:
            doc = _json.loads((cache / f"{n}_base.json").read_text(
                encoding="utf-8"))
        except (OSError, ValueError):
            continue
        rows = (doc if isinstance(doc, list)
                else (doc.get("transactions") or [])
                if isinstance(doc, dict) else [])
        for t in rows:
            if not isinstance(t, dict):
                continue
            sy = str(t.get("symbol") or "").strip().upper()
            if sy and "." not in sy and not is_option_symbol(sy):
                if n not in out.setdefault(sy, []):
                    out[sy].append(n)
    return out


def _us_coin_answer(canon, radar: Dict[str, Dict[str, Any]],
                    q: str) -> Optional[List[str]]:
    """buy-check / sell-check lines for a bare coin query in a US
    project's crypto account, or None: the coin is outside the
    wash-sale rule (US-WASH-13; US-PLAN-05); an equity sharing its root
    (SAMPLT.US) keeps its own verdict under its own name."""
    coins = getattr(canon, "us_crypto_coins", None) or {}
    q = q.strip().upper()
    if q not in coins:
        return None
    lines = [f"{q}: a coin in crypto account(s) "
             f"{', '.join(coins[q])} — crypto is not subject to the "
             f"wash-sale rule (US-WASH-13): no wash-sale exposure."]
    others = sorted({t for t in radar
                     if t.strip().upper().rpartition(".")[0] == q})
    if others:
        lines.append(f"{', '.join(others)} "
                     f"{'is a separate listing' if len(others) == 1 else 'are separate listings'}"
                     f" — query {'it' if len(others) == 1 else 'them'} "
                     f"by name.")
    return lines


def _refuse_map_problems(ticker_map: Path, problems: Sequence[str],
                         effect: str, code: int = 1) -> None:
    """Stop on ticker.map / tobase.map lines map_file_problems found
    (`effect`: what a dropped or contradictory rule changes), naming
    each line, exit `code`. `tjs run` and the wash checks refuse
    the same map with the same words."""
    # The files the problems are in (tobase.map is read with
    # ticker.map): a tobase.map line was headed "ticker.map
    # problem(s)" (backlog TJ-0125).
    files: List[str] = []
    for p in problems:
        m = re.match(r"(.+?):\d+: ", p)
        n = Path(m.group(1)).name if m else ticker_map.name
        if n not in files:
            files.append(n)
    files.sort(key=lambda n: n != ticker_map.name)
    (_die_input if code == 2 else _die)(
        f"{len(problems)} {' and '.join(files)} problem(s)",
        *[f"- {p}" for p in problems],
        f"A malformed line's rule would be silently dropped, and "
        f"contradictory rules (a cycle, two targets for one symbol, a "
        f"DISTINCT pair the renames pool) have no single meaning; "
        f"{effect}. Fix the line (its keyword's fields separated by "
        f"spaces, as the ticker.map header and docs/settings.md give "
        f"them; notes after `#`) or delete it.")


def _strict_ticker_map(root: Path, effect: str):
    """The project's ticker.map (tobase.map's pairs included) as a
    TickerMap, None when it has none — read strictly: the loader DROPS
    a line it cannot parse (a warning), and the verdict read without a
    dropped `GLOBAL OLD NEW` turned UNSAFE into SAFE (backlog TJ-0304),
    harvest quoted another option contract (TJ-0352) and lib/similar
    lost a SIMILAR group. A problem line stops the command as `tjs
    run` stops (`effect`: what a dropped rule changes here), and so
    does a map that cannot be read (audit A2-0683): both exit 2, an
    input to fix, never a verdict's 1 (backlog TJ-0351)."""
    _map_path = _PL.ticker_map_path(root)
    if not _map_path.exists():
        return None
    from taxjson.bin.taxjson_ticker_map import (load_map_file,
                                                map_file_problems)
    try:
        _map_problems = map_file_problems(_map_path)
        if not _map_problems:
            return load_map_file(_map_path)
    except Exception as e:                                 # noqa: BLE001
        _die_input(f"ticker.map cannot be read ({e})",
                   "`tjs run` refuses it too; fix it first (its "
                   "cross-listing and rename rules decide which listings "
                   "are the same security).")
    _refuse_map_problems(_map_path, _map_problems, effect, code=2)
    return None


def _wash_class_context(root: Path, cache: Path, prog: str,
                        radar_args: Sequence[str] = (), json_doc=None):
    """(radar, canon, last_loss) shared by buy-check and sell-check:
    the combined radar document flattened per ticker, a symbol-class
    canonicalizer (known-exchange-suffix roots union-folded with the
    project's ticker.map pairs), and each class's most recent LOSING
    disposition from the taxable gains files (economic raw_gain, so a
    wash-denied loss still shows). `radar_args`: more radar options
    (rebuy's --date and --cleared-days). `json_doc`: the command's
    --json document when the project has no wash-checkable account
    (_no_wash_checkable)."""
    import json as _json
    from taxjson.bin.taxjson_watch import flatten_radar
    from taxjson.lib.dispatch import run_cmd as _run
    from taxjson.lib.report_model import resolve_gains_files
    bases = _radar_taxable_bases(root, cache, prog, json_doc=json_doc)
    # The map decides which listings are one security: refused, as
    # `tjs run` refuses it, before any verdict (backlog TJ-0304).
    _tm = _strict_ticker_map(
        root, "the map decides which listings are one security, so a "
        "verdict without the rule can miss a cross-listed loss and read "
        "SAFE (`tjs run` refuses this map too)")
    cmd = _cmd("taxjson-wash-radar") + [
        "--taxable", *[str(b) for b in bases], "--all", "--json"]
    _proj_country = _country(_radar_config(root, prog).get("settings", {}))
    cmd += _radar_engine_args(
        bases, root, _proj_country)
    cmd += list(radar_args)
    sheltered_base = cache / "sheltered_base.json"
    if sheltered_base.exists():
        cmd += ["--sheltered", str(sheltered_base)]
    elif _sheltered_expected(root):
        # Without the registered accounts' books their recent buys are
        # invisible, and a LOCKED loss sale read SAFE, exit 0, after an
        # Info line (backlog TJ-0350, audit TJ-0394): refuse, as `watch`
        # compares nothing (TJ-0303). Exit 2: an input to rebuild.
        _die_input("no sheltered_base.json in work/: the registered "
                   "accounts' trades are missing from this check",
                   "A registered account's recent buy can deny a loss "
                   "for good, so a verdict without them can read SAFE. "
                   "Run `tjs run` first to rebuild it.")
    res = _run(cmd, capture_output=True)
    if res.returncode != 0:
        _die("the wash radar failed", _child_error(res.stderr))
    radar = flatten_radar(_json.loads(res.stdout))

    # Identity comes ONLY from ticker.map (GLOBAL/TOBASE/JOURNAL), SPLIT
    # renames in the books, and an option's own underlying. Two listings
    # that merely share a root (SAMPLE.TO / SAMPLE.US) are NOT assumed to be the
    # same security: a CDR, a different issuer (SAMPLF.US an NYSE issuer vs
    # SAMPLF.TO a TSX ETF) or a share class would all be merged
    # wrongly by suffix stripping. The engine pools by exact mapped symbol,
    # and this matcher must agree with it.
    # (_tm: the map, read strictly above.)
    _distinct_pairs: set = (
        {frozenset(s.strip().upper() for s in p) for p in _tm.distinct}
        if _tm is not None else set())

    def _root(t: str) -> str:
        t = t.strip().upper()
        # An option is a right to acquire ITS underlying — identical
        # property for s.40(2)(g)/§1091 purposes — so it folds to the
        # underlying symbol exactly as parsed (suffix kept).
        from taxjson.lib.core import parse_option_underlying
        _u = parse_option_underlying(t)
        return _u.upper() if _u else t

    _parent: Dict[str, str] = {}

    def _find(x: str) -> str:
        while _parent.get(x, x) != x:
            x = _parent[x]
        return x

    def _union(a: str, b: str, why: str) -> None:
        ra, rb = _find(_root(a)), _find(_root(b))
        if ra == rb:
            return
        _parent[ra] = rb
        # A DISTINCT pair must never end up in one class — not even
        # transitively through a third symbol. Undo and say so.
        if any(_find(x) == _find(y) for x, y in
               (tuple(p) for p in _distinct_pairs if len(p) == 2)):
            del _parent[ra]
            from taxjson.lib.out import warn as _warn
            _warn(f"{why} would merge a DISTINCT pair from ticker.map "
                  f"({a} ~ {b}); the pair stays separate.", prog=prog)

    if _tm is not None:
        for _src, _dst in list(_tm.glob.items()) \
                + list(_tm.tobase.items()) \
                + list(_tm.journal.items()):
            _union(_src, _dst, "ticker.map")

    # SPLIT-renames are identical property too (the engine and the
    # radar match on the rename class): a loss on OLD.TO followed by
    # a NEW.TO rebuy is a violation that `sell-check OLD.TO` must
    # find under NEW.TO's radar row. Same union condition as
    # SplitTimeline.from_transactions (non-empty, non-self symbol_new).
    # Renames are DATED (A2-0197): a ticker that trades again after
    # its rename date names a different security NOW, so it is not
    # joined to the renamed holding (lib/renames).
    from taxjson.lib.renames import late_rows as _late_rows
    from taxjson.lib.renames import rename_events as _rename_events
    _all_rows: List[Dict[str, Any]] = []
    for _bp in bases + ([sheltered_base] if sheltered_base.exists()
                        else []):
        try:
            _bdoc = _json.loads(_bp.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        # A bare-array book is a book (the radar's own read_json_doc
        # contract — audit A2-1180).
        _brows = (_bdoc if isinstance(_bdoc, list)
                  else (_bdoc.get("transactions", []) or [])
                  if isinstance(_bdoc, dict) else [])
        _all_rows += [_t for _t in _brows if isinstance(_t, dict)]
    _late_old = {e["old"] for _r, e in _late_rows(
        _all_rows, _rename_events(_all_rows), _proj_country)}
    for _t in _all_rows:
        if (_t.get("action") or "").upper() != "SPLIT":
            continue
        _new = (_t.get("symbol_new") or "").strip()
        _old = (_t.get("symbol") or "").strip()
        if _new and _old and _new.upper() != _old.upper():
            if _old in _late_old:
                continue
            _union(_old, _new, "SPLIT-rename in the books")

    # An option root that names no share listing in the books but
    # matches exactly ONE class share of that root on the same exchange
    # is that class: RBC books Rogers' Montreal options under the root
    # SAMPLD (SAMPLD271217C00030000.TO) while the shares are SAMPLD.B.TO, and the
    # call — a right to acquire those shares — fell into an empty
    # SAMPLD.TO class, so buy-check said SAFE (S047-01).
    from taxjson.lib.core import is_option_symbol as _is_opt
    _shares = {t.strip().upper() for t in radar if not _is_opt(t)}
    for _bp in bases:
        try:
            _bdoc = _json.loads(_bp.read_text(encoding="utf-8"))
            _brows = (_bdoc if isinstance(_bdoc, list)
                      else _bdoc.get("transactions", []) or [])
            for _t in _brows:
                _sy = str(_t.get("symbol") or "").strip().upper()
                if _sy and not _is_opt(_sy):
                    _shares.add(_sy)
        except (OSError, ValueError, AttributeError):
            continue
    _by_root: Dict[str, set] = {}
    for _sy in _shares:
        _m = re.fullmatch(r"(.+)\.([A-Z]{1,2})\.([A-Z]{1,3})", _sy)
        if _m:
            _by_root.setdefault(f"{_m.group(1)}.{_m.group(3)}",
                                set()).add(_find(_sy))
    _class_alias = {r: next(iter(cs)) for r, cs in _by_root.items()
                    if len(cs) == 1 and r not in _shares
                    and _find(r) == r}

    def canon(t: str) -> str:
        r = _find(_root(t))
        if _is_opt(t.strip().upper()) and r in _class_alias:
            return _class_alias[r]
        return r

    # Suffix-less listings in the books — crypto coins (ETH): a bare
    # query that names one of them means that listing, never also the
    # equity sharing its root (SAMPLT.US) (S047-06).
    canon.bare_listings = {_sy for _sy in _shares if "." not in _sy}
    # One option contract, two spellings: a ticker.map line pairing two
    # option symbols (GLOBAL SYN<series>.TO ALT<series>.TO) makes them
    # the SAME contract, as the engine books it. The class fold above
    # joins only their underlyings, so the exact-series filters
    # dropped the booked spelling's loss and `buy-check SYN<series>.TO`
    # answered SAFE (backlog TJ-1000). {option: its one spelling}.
    _opt_parent: Dict[str, str] = {}
    # A share line on one market (GLOBAL SYN.TO ALT.TO) books the
    # options too (ticker_map.map_symbol): a spelling the books do not
    # hold is the contract the line rewrites it to (backlog TJ-1172). A
    # spelling the books hold is its own contract (the engine keeps a
    # collision apart). Between markets a code can name two contracts
    # (guard_option_listing_collisions): left as it is.
    _share_rules: Dict[str, str] = {}

    def _opt_find(x: str) -> str:
        while _opt_parent.get(x, x) != x:
            x = _opt_parent[x]
        return x
    if _tm is not None:
        for _src, _dst in list(_tm.glob.items()) \
                + list(_tm.tobase.items()) \
                + list(_tm.journal.items()):
            _s, _d = str(_src).strip().upper(), str(_dst).strip().upper()
            if _s != _d and _is_opt(_s) and _is_opt(_d):
                _rs, _rd = _opt_find(_s), _opt_find(_d)
                if _rs != _rd:
                    _opt_parent[_rs] = _rd
            elif (_s != _d and not _is_opt(_s) and not _is_opt(_d)
                  and _s.rpartition(".")[2] == _d.rpartition(".")[2]):
                _share_rules[_s] = _d
    _booked = {str(_t.get("symbol") or "").strip().upper()
               for _t in _all_rows}

    def _option_spelling(x: str) -> str:
        from taxjson.bin.taxjson_ticker_map import map_symbol
        if x in _booked or x in _opt_parent or not _is_opt(x):
            return x
        return map_symbol(x, _share_rules)
    canon.option_id = lambda t: _opt_find(
        _option_spelling(str(t).strip().upper()))
    # The share listings each class joins (ticker.map / tobase.map
    # pairs, renames, the books' own listings): `rebuy` names the other
    # listings a buy of which counts too (XYZ.US for XYZ.TO).
    _members: Dict[str, set] = {}
    for _sy in set(_parent) | _shares:
        if _sy and not _is_opt(_sy):
            _members.setdefault(canon(_sy), set()).add(_sy)
    canon.members = {k: sorted(v) for k, v in _members.items()}
    # A US project leaves its crypto accounts out of the radar (§1091
    # does not reach digital assets, US-WASH-13), so a coin there is
    # in no radar row: `buy-check SAMPLT` took SAMPLT.US's verdict and
    # `sell-check BTC` said "no tracked taxable position" (audit
    # A2-0749, A2-0750, A2-1340). {coin: [crypto accounts]}.
    canon.us_crypto_coins = _us_crypto_coins(root, cache, prog)
    # The classes ticker.map SIMILAR lines put beside each class
    # (lib/similar): a caveat in buy-check / sell-check, the listings
    # `rebuy` names as flagged — never one class (the engine keeps them
    # apart, and so must this matcher).
    from taxjson.lib import similar as _SIM
    _sim: Dict[str, set] = {}
    for _g in _SIM.groups(root):
        _roots = {canon(_s) for _s in _g}
        for _r in _roots:
            _sim.setdefault(_r, set()).update(_roots - {_r})
    canon.similar = {k: sorted(v) for k, v in _sim.items() if v}

    _acct_cfg = _soft_config(root).get("accounts") or {}
    _taxable = {a for a, c in _acct_cfg.items()
                if (c or {}).get("type") == "taxable"}
    last_loss = _last_loss_by_class(
        resolve_gains_files(cache), canon, _taxable,
        usa=_radar_country_is_usa(root))
    return radar, canon, last_loss


_OPTION_LOSS_KEY = "option:"


def _option_id(canon, symbol: str) -> str:
    """`symbol` (upper-cased) as the one spelling of its contract: an
    option paired with another option symbol by ticker.map is the same
    contract under either name (canon.option_id, backlog TJ-1000); any
    other symbol is itself."""
    s = str(symbol).strip().upper()
    f = getattr(canon, "option_id", None)
    return f(s) if f is not None else s


def _last_loss_for(last_loss: Dict[str, Dict[str, Any]], want: str,
                   wroot: str, mode: str, closes_short: bool = False,
                   canon=None):
    """The last loss a trade in `want` can affect: a share query sees
    the class's share losses; an option query sees its own contract's
    (either spelling ticker.map pairs, `canon`), plus (a call BUY that
    opens a position) the underlying's share losses (one-way option
    rule, audit A2-1172)."""
    from taxjson.lib.core import is_option_symbol, parse_option_right
    q = want.strip().upper()
    if not is_option_symbol(q):
        return last_loss.get(wroot)
    cands = [last_loss.get(_OPTION_LOSS_KEY + _option_id(canon, q))]
    if mode == "buy" and parse_option_right(q) == "C" and not closes_short:
        cands.append(last_loss.get(wroot))
    cands = [c for c in cands if c]
    return max(cands, key=lambda c: c["date"]) if cands else None


def _last_loss_by_class(gains_files, canon, taxable, *, usa: bool
                        ) -> Dict[str, Dict[str, Any]]:
    """Each symbol class's most recent LOSING disposition in the taxable
    gains files (economic raw_gain, so a denied loss still shows), dated
    on the country's window basis — the SETTLE date under s.54, the
    TRADE date under §1091 — so the "N days ago / INSIDE the window"
    line agrees with the radar's verdict at the day-30 edge (audit
    S050-00; it used settle dates in US projects too)."""
    last_loss: Dict[str, Dict[str, Any]] = {}
    for _a, _p in gains_files.items():
        if taxable and _a not in taxable:
            continue
        try:
            _doc = _read_work_doc(Path(_p))
        except (OSError, ValueError) as e:
            # The context line vanished in silence (S047-03).
            from taxjson.lib.out import warn as _warn
            _warn(f"could not read {Path(_p).name} ({e})",
                  prog="tjs",
                  details=[f"The 'last loss sale' line leaves out account "
                           f"{_a}; re-run `tjs run`."])
            continue
        # A sale routed to manual reporting (unknown cost) is still a
        # loss sale for the window: its row has no 'gain', only the
        # engine's raw_gain (S047-02).
        _rows = [(t, False) for t in _doc.get("transactions", [])] + [
            (t, True) for t in _doc.get("manual_reporting_required") or []]
        for _t, _routed in _rows:
            if not _t.get("qty"):
                continue
            if _routed:
                if _t.get("raw_gain") is None:
                    continue
                _g = float(_t.get("raw_gain") or 0.0)
            else:
                if "gain" not in _t:
                    continue
                _g = float(_t.get("raw_gain", _t.get("gain")) or 0.0)
            if _g >= 0:
                continue
            # An option's loss is keyed by its own contract, never by the
            # underlying's class: shares never replace an option, so a
            # share query's context line must not show a written call's
            # buy-back loss as INSIDE its window (audit A2-1172).
            _sym = str(_t.get("symbol") or "")
            from taxjson.lib.core import is_option_symbol as _is_o
            _c = (_OPTION_LOSS_KEY + _option_id(canon, _sym)
                  if _is_o(_sym.strip().upper()) else canon(_sym))
            _d = str((_t.get("date") or _t.get("date_settle")) if usa
                     else (_t.get("date_settle") or _t.get("date")) or "")
            _prev = last_loss.get(_c)
            if _prev is None or _d > _prev["date"]:
                last_loss[_c] = {"date": _d,
                                 # The window date's kind, printed with
                                 # it: the radar labels the same sale by
                                 # its trade date (S047-05).
                                 "date_kind": "traded" if usa else "settled",
                                 "symbol": _t.get("symbol"),
                                 "gain": round(_g, 2),
                                 # SHORT: the loss was on covering a
                                 # short, not a sale (backlog TJ-0122).
                                 "direction": _t.get("direction") or "LONG",
                                 "unknown_cost": _routed,
                                 "account": _t.get("account") or _a}
    return last_loss


def _fold_class_separator(symbol: str) -> str:
    """A share-class ticker typed the broker/Yahoo way (SAMPLD-B, 'SAMPLD B',
    SAMPLD/B, SAMPLD-B.TO) in the books' dotted spelling (SAMPLD.B, SAMPLD.B.TO).
    Unfolded, the query matched nothing and buy-check answered SAFE
    while a loss on SAMPLD.B.TO sat inside the window (S007-02). Option
    symbols pass through unchanged."""
    from taxjson.lib.core import is_option_symbol
    s = " ".join(str(symbol).split()).upper()
    if is_option_symbol(s):
        return s
    m = re.fullmatch(r"([A-Z0-9]+)[-/ ]([A-Z]{1,2})((?:\.[A-Z]{1,3})?)", s)
    return f"{m.group(1)}.{m.group(2)}{m.group(3)}" if m else s


def _bare_listings(radar: Dict[str, Dict[str, Any]], canon,
                   q: str) -> List[str]:
    """The listings a BARE ticker (no exchange suffix) names: those in
    the books that carry it, q.<exchange> joined to the books by a
    ticker.map rule, and q.<exchange> a ticker.map SIMILAR line names
    (never held: the look-alike a tax-loss swap is about to buy, whose
    caveat `buy-check ZZH` dropped while `buy-check ZZH.TO` gave it;
    workflow audit 2026-10-22 #8). Each listing keeps its own class."""
    from taxjson.lib.brokerages.schema import KNOWN_SUFFIXES
    q = q.strip().upper()
    booked = {canon(t) for t in radar}
    similar = set(getattr(canon, "similar", None) or ())
    listings = [t for t in radar
                if t.strip().upper().rpartition(".")[0] == q
                or t.strip().upper() == q]
    for sx in sorted(KNOWN_SUFFIXES):
        t = f"{q}.{sx}"
        if t in listings:
            continue
        c = canon(t)
        if (c != t and c in booked) or c in similar:
            listings.append(t)
    return listings


def _class_matches(radar: Dict[str, Dict[str, Any]], canon, want: str):
    """(class root, {ticker: row}, note) for one queried symbol.

    A query WITH an exchange suffix (SAMPLE.TO) names one listing and sees
    exactly that listing's class — the listings ticker.map joins to it,
    its split renames and its options. A BARE query (SAMPLE, SAMPLC.B) names
    no listing: it is resolved to every listing that carries that
    ticker, and each of those keeps its own class. Nothing is ever
    merged by stripping a suffix — only ticker.map makes two listings
    one security. When the bare ticker resolves to more than one class
    the worst verdict is shown with a note asking for an explicit
    spelling."""
    from taxjson.lib.brokerages.schema import KNOWN_SUFFIXES
    q = want.strip().upper()
    base, _, ext = q.rpartition(".")
    if base and ext in KNOWN_SUFFIXES:
        wroot = canon(q)
        return wroot, {t: r for t, r in radar.items()
                       if canon(t) == wroot}, None
    _bare = set(getattr(canon, "bare_listings", None) or ())
    if q in _bare or any(t.strip().upper() == q for t in radar):
        # The books hold a suffix-less listing of exactly this name (a
        # coin): that IS the security asked about. `buy-check ETH` gave
        # SAMPLT.US's verdict too, and nothing could ask about the coin
        # alone (S047-06); the equity keeps its own spelling.
        wroot = canon(q)
        others = sorted({t for t in radar
                         if t.strip().upper().rpartition(".")[0] == q
                         and canon(t) != wroot})
        note = (f"{q}: this is the {q} listing in the books (a coin or "
                f"other suffix-less symbol); {', '.join(others)} "
                f"{'is a separate listing' if len(others) == 1 else 'are separate listings'}"
                f" — query {'it' if len(others) == 1 else 'them'} by "
                f"name." if others else None)
        return wroot, {t: r for t, r in radar.items()
                       if canon(t) == wroot}, note
    listings = _bare_listings(radar, canon, q)
    classes = sorted({canon(t) for t in listings}) or [canon(q)]
    matches = {t: r for t, r in radar.items() if canon(t) in classes}
    note = None
    if len(classes) > 1:
        note = (f"{q}: ambiguous — {', '.join(sorted(listings))} are "
                f"separate listings (only ticker.map makes two listings "
                f"one security); this is the worst verdict across them. "
                f"Query one explicitly.")
    return classes[0], matches, note


def _replacement_rows(want: str, matches: Dict[str, Dict[str, Any]],
                      mode: str, closes_short: bool = False, canon=None
                      ) -> Dict[str, Dict[str, Any]]:
    """Keep the radar rows a trade in `want` can actually affect (ITA
    s.54, one-way option rule): buying SHARES touches share losses only
    (shares never replace an option); buying a CALL also touches the
    underlying's share losses (a right to acquire them) and its own
    contract; any other option — and SELLING an option — touches only
    the identical contract (a different series never replaces it) —
    under either spelling a ticker.map line pairs (`canon`, backlog
    TJ-1000)."""
    from taxjson.lib.core import is_option_symbol, parse_option_right
    q = want.strip().upper()
    if not is_option_symbol(q):
        return {t: r for t, r in matches.items()
                if not is_option_symbol(t)}
    # A buy that closes a written call acquires nothing (CA-SL-05,
    # US-WASH-12; audit A2-0370): it touches only its own contract.
    from taxjson.lib.core import _FUTURES_PREFIX_RE, parse_option_underlying
    # A futures option is never sized as a replacement of the futures
    # loss (CA-SL-15 / US-WASH-15): buy-check flags it instead.
    call_buy = (mode == "buy" and parse_option_right(q) == "C"
                and not closes_short
                and not _FUTURES_PREFIX_RE.match(
                    parse_option_underlying(q) or ""))
    qid = _option_id(canon, q)
    return {t: r for t, r in matches.items()
            if _option_id(canon, t) == qid
            or (call_buy and not is_option_symbol(t))}


def _similar_lines(radar: Dict[str, Dict[str, Any]], canon, wroot: str,
                   q: str, mode: str, usa: bool) -> List[str]:
    """buy-check's / sell-check's caveat lines for the share rows of the
    classes ticker.map declares SIMILAR to the queried class (lib/
    similar, CA-SL-20 / US-WASH-26): on a buy, a similar fund sold at a
    loss inside the window; on a sale, one bought inside it. A caveat
    (SAFE*), never a verdict: the books keep the funds apart."""
    from taxjson.lib import similar as _SIM
    from taxjson.lib.brokerages.schema import KNOWN_SUFFIXES
    from taxjson.lib.core import is_option_symbol
    q = q.strip().upper()
    simmap = getattr(canon, "similar", None) or {}
    roots = {wroot}
    base, _, ext = q.rpartition(".")
    if not (base and ext in KNOWN_SUFFIXES) and q not in set(
            getattr(canon, "bare_listings", None) or ()):
        # A bare query may name several classes (the worst verdict is
        # shown): each one's look-alikes are a caveat, none dropped.
        roots |= {canon(t) for t in _bare_listings(radar, canon, q)}
    sim = set()
    for _r in roots:
        sim.update(simmap.get(_r) or [])
    sim -= roots
    if not sim or is_option_symbol(q):
        return []
    want = _SIM.LOSS_CATEGORIES if mode == "buy" else _SIM.BUY_CATEGORIES
    out = []
    for t, r in sorted(radar.items()):
        tu = t.strip().upper()
        if is_option_symbol(tu) or canon(tu) not in sim:
            continue
        cat = r.get("category") or ""
        if cat in want:
            out.append(_SIM.caveat(tu, cat, q, mode,
                                   "usa" if usa else "canada"))
        elif mode == "sell" and isinstance(r.get("sheltered_buy"), dict):
            # Held only in a registered account / IRA that bought it in
            # the window: the radar files it CLEAR (nothing taxable to
            # sell), but the buy is "in any of your accounts" (CA-SL-20
            # / US-WASH-26; workflow audit 2026-10-22 #13).
            out.append(_SIM.caveat(tu, cat, q, mode,
                                   "usa" if usa else "canada",
                                   sheltered_buy=r["sheltered_buy"]))
        elif mode == "sell" and isinstance(r.get("recent_buy"), dict):
            # Bought inside the window under another status — a
            # VIOLATION's own replacement: the category says nothing of
            # the buy, and sell-check said plain SAFE while the run
            # warns after the sale (backlog TJ-0449).
            out.append(_SIM.caveat(tu, cat, q, mode,
                                   "usa" if usa else "canada",
                                   bought=r["recent_buy"]))
    return out


_FLAG_WORDS = {
    "right_vs_share_loss": "a warrant/right on",
    "adjusted_option_vs_loss": "a call on an adjusted option series of",
    "futures_option_vs_loss": "a call on the futures contract of",
}


def _flagged_share_rows(radar: Dict[str, Dict[str, Any]], q: str):
    """[(ticker, row, rule)] for the share rows a purchase of `q` would
    be flagged against (never sized): `q` a warrant/right on them, a call
    on an adjusted series of them (root + digit), or a call on their
    futures contract — the engines' warn-only rules (core.
    detect_right_replacement_matches / detect_unresolved_option_
    replacement_matches)."""
    from taxjson.lib.core import (_FUTURES_PREFIX_RE, _root_matches_stock,
                                  _split_underlying, is_option_symbol,
                                  parse_option_right,
                                  parse_option_underlying, right_underlying)
    q = q.strip().upper()
    if is_option_symbol(q):
        if parse_option_right(q) != "C":
            return []
        und = parse_option_underlying(q) or ""
        b, ext = _split_underlying(und)
        b = _FUTURES_PREFIX_RE.sub("F:", b)
        if b.startswith("F:"):
            kind = "futures_option_vs_loss"
        elif b[-1:].isdigit():
            kind = "adjusted_option_vs_loss"
        else:
            return []
    else:
        und = right_underlying(q)
        if not und:
            return []
        b, ext = _split_underlying(und)
        kind = "right_vs_share_loss"
    out = []
    for t, r in radar.items():
        tu = t.strip().upper()
        if is_option_symbol(tu) or tu == q:
            continue
        sb, sext = _split_underlying(tu)
        sb = _FUTURES_PREFIX_RE.sub("F:", sb)
        if sext != ext:
            continue
        if kind == "right_vs_share_loss":
            if sb != b:
                continue
        elif not _root_matches_stock(b, sb):
            continue
        out.append((t, r, kind))
    return sorted(out, key=lambda x: x[0])


def _short_cover_loss_date(r: Dict[str, Any]) -> Optional[str]:
    """The date of a radar row's recent loss when every loss still in
    its window was on covering a short (direction SHORT), else None:
    buy-check / sell-check word it as a cover, never as a sale (backlog
    TJ-0122)."""
    live = [l for l in r.get("losses") or [] if not l.get("cleared")]
    if live and all(l.get("direction") == "SHORT" for l in live):
        return max(str(l.get("trade_date") or "") for l in live) or None
    return None


def _passed_violation_text(r: Dict[str, Any]) -> str:
    """A settled VIOLATION's advisory (its rescue date has passed)
    without the forward view the radar appends to it ("For a loss sale
    today: …"), which sell-check / buy-check state as its own line
    (backlog TJ-0775)."""
    adv = str(r.get("advisory") or "")
    fwd = r.get("forward")
    if isinstance(fwd, dict) and fwd.get("advisory"):
        adv = adv.replace(f" For a loss sale today: {fwd['advisory']}", "")
    return adv


def _with_forward_rows(matches: Dict[str, Dict[str, Any]]):
    """(ticker, row) of `matches` in ticker order; after a VIOLATION
    whose rescue date has passed, its `forward` view (what a loss sale
    or a buy TODAY meets: a registered account's recent buy still held
    is LOCKED) as a row of its own, marked `after_passed`. The settled
    loss masked it: sell-check said SAFE* before a sale the rule denies
    (backlog TJ-0775)."""
    for t, r in sorted(matches.items()):
        yield t, r
        fwd = r.get("forward")
        if ((r.get("category") or "") == "VIOLATION"
                and r.get("deadline_passed") and isinstance(fwd, dict)
                and fwd.get("category")):
            yield t, {**r, "category": fwd.get("category"),
                      "advisory": fwd.get("advisory") or "",
                      "clears_at": fwd.get("clears_at"),
                      "at_risk_qty": fwd.get("at_risk_qty"),
                      "deadline_passed": False, "forward": None,
                      "notes": [], "after_passed": True}


def _window_over(r: Dict[str, Any]) -> bool:
    """A VIOLATION whose rescue date has passed and none of whose
    losses a buy today can still replace (each one's re-entry date has
    come, the radar's `losses`): its window is over for a buyer, as
    `rebuy` lists it (backlog TJ-0775). An older radar without the
    losses is not judged."""
    losses = r.get("losses")
    return ((r.get("category") or "") == "VIOLATION"
            and bool(r.get("deadline_passed"))
            and isinstance(losses, list) and bool(losses)
            and not any(not x.get("cleared") and x.get("buy_replaces")
                        for x in losses if isinstance(x, dict)))


def _loss_within_30(r: Dict[str, Any]) -> str:
    """'a loss sold within the past 30 days', or its short-cover form."""
    d = _short_cover_loss_date(r)
    return (f"a loss on covering a short ({d}) within the past 30 days"
            if d else "a loss sold within the past 30 days")


def _last_loss_line(ll) -> Optional[str]:
    if not ll:
        return None
    from datetime import date as _date
    try:
        _ago = (_date.today() - _date.fromisoformat(ll["date"])).days
        # `date` is the country's window date (settle for Canada): a
        # sale made today settles later (T+1), so a negative age means
        # "not settled yet", not "-1 days ago".
        _ago_s = (f"{_ago} days ago" if _ago >= 0 else
                  f"traded, settles in {-_ago} day"
                  f"{'s' if _ago < -1 else ''}")
        _inout = ("INSIDE the 30-day window" if _ago <= 30
                  else "outside the 30-day window")
    except ValueError:
        _ago_s, _inout = "?", "window position unknown"
    _kind = ll.get("date_kind")
    _head = ("last loss this tax year (covering a short)"
             if ll.get("direction") == "SHORT"
             else "last loss sale this tax year")
    return (f"{_head}: {ll['symbol']} "
            + (f"{_kind} " if _kind else "")
            + f"{ll['date']} ({_ago_s}, {ll['gain']:,.2f}"
            + (", unknown cost (no purchase in your files) — routed to "
               "manual reporting"
               if ll.get("unknown_cost") else "")
            + f") — {_inout}.")


# A buy-check line's trailing caveat on the window a buy starts: the
# --details view (docs/output-style.md, Essentials first).
_FUTURE_CAVEAT = " (Any buy starts a 30-day window: "


def _print_check_results(results: List[Dict[str, Any]],
                         country: str, details: bool = True,
                         cmd: str = "") -> None:
    """buy-check / sell-check text: per symbol a `SYMBOL: VERDICT` line
    and its detail lines as `- ` items (a radar note quoted in one as
    its own `Info:` item), a blank line between symbols, then the scope
    paragraph (lib/wash_scope). The --json document carries the same
    results."""
    from taxjson.lib import out
    from taxjson.lib.wash_scope import advisory_lines, scope_lines
    w = out.width()
    lines: List[str] = []
    for r in results:
        if lines:
            lines.append("")
        lines.append(f"{r['symbol']}: {r['verdict']}")
        for ln in r["detail"]:
            if not details:
                ln = ln.split(_FUTURE_CAVEAT, 1)[0]
            lines += advisory_lines(ln, w, "- ", "  ")
    if details:
        lines.append("")
        lines += scope_lines(country, w)
    else:
        from taxjson.lib.wash_scope import scope_more
        lines += out.wrap(scope_more(f"tjs {cmd} --details", country), w)
    print("\n".join(lines))


def _check_na_json(root: Path, args: argparse.Namespace):
    """buy-check / sell-check --json when the project has no
    wash-checkable account (_no_wash_checkable): their document with
    no result (backlog TJ-0330)."""
    if not getattr(args, "json", False):
        return None

    def doc() -> Dict[str, Any]:
        from taxjson.lib.wash_scope import scope_note
        return {"results": [], "scope_note": scope_note(
            "usa" if _radar_country_is_usa(root) else "canada")}
    return doc


def cmd_buy_check(args: argparse.Namespace) -> None:
    """`tjs buy-check SYMBOL...`: is buying this ticker TODAY safe
    from the wash-sale / superficial-loss rules? Unsafe when a loss
    was sold within the past 30 days (the rebuy cancels it — deferred
    if bought taxable, PERMANENTLY denied if bought sheltered);
    safe-with-a-caveat when a wash window is merely open (buying
    extends it for future loss sales). Root-matched with ticker.map
    equivalences folded in. Exit 1 when any queried symbol is
    unsafe."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    radar, _canon, _last_loss = _wash_class_context(
        root, cache, "tjs buy-check",
        json_doc=_check_na_json(root, args))
    _usa = _radar_country_is_usa(root)

    def _money_cur(x: float) -> str:
        """Money as the radar's advisories print it: fmt_money and the
        books' base currency, the country's own (base_currency refuses
        any other; backlog TJ-0244)."""
        from taxjson.lib.report_model import fmt_money
        return f"{fmt_money(x)} {'USD' if _usa else 'CAD'}"
    # The rule's name in the project's law (never "superficial" in a
    # US project, never "wash sale" in a Canadian one).
    _sl_adj = "a wash sale" if _usa else "superficial"
    # s.54 'superficial loss' (b): the substituted property must still
    # be held at the END of the 30 days after the sale — a full exit,
    # or a rebuy sold again before day 30, leaves the loss standing.
    # §1091 has no such test. The texts below said every in-window
    # loss sale "would be superficial" and every rebuy "cancels" the
    # loss (S048-19, S049-15).
    _future_rule = (
        f"a PARTIAL loss sale of this name within 30 days of a buy "
        f"would be {_sl_adj}; selling the full position is not"
        if _usa else
        f"a loss sale of this name within 30 days of a buy would be "
        f"{_sl_adj} if you still hold the bought shares 30 days after "
        f"the sale — a full exit is not")
    unsafe = 0
    results = []
    from taxjson.lib.core import is_option_symbol as _is_opt_sym
    from taxjson.lib.core import parse_option_right as _opt_right
    for want in args.symbol:
        want = _fold_class_separator(want)
        _coin = _us_coin_answer(_canon, radar, want)
        if _coin is not None:
            results.append({"symbol": want.strip().upper(),
                            "verdict": "SAFE", "clears_at": None,
                            "detail": _coin, "last_loss": None})
            continue
        wroot, matches, _note = _class_matches(radar, _canon, want)
        _q = want.strip().upper()
        # Short this very contract: the buy closes it and acquires
        # nothing (CA-SL-05 / US-WASH-12; audit A2-0370).
        _own = radar.get(_q) or (next(
            (r for t, r in radar.items()
             if _option_id(_canon, t) == _option_id(_canon, _q)), None)
            if _is_opt_sym(_q) else None) or {}
        _short_n = -(float(_own.get("taxable_qty") or 0.0)
                     + float(_own.get("sheltered_qty") or 0.0))
        _closes = (_is_opt_sym(_q) and _opt_right(_q) == "C"
                   and _short_n > 1e-9)
        matches = _replacement_rows(want, matches, "buy", _closes,
                                    canon=_canon)
        # Worst verdict across the class (cross-listings included).
        verdict, lines = "SAFE", ([_note] if _note else [])
        if _closes:
            verdict = "SAFE*"
            lines.append(
                f"{_q}: you are short {_short_n:g} contract(s) — a buy "
                f"that closes them acquires nothing, so it never "
                f"replaces a loss on the shares; buying MORE than "
                f"{_short_n:g} opens a long call, a right to acquire "
                f"them.")
        # A US long call is a note only (US-WASH-12 / US-PLAN-02): the
        # engine never denies a share loss on it, so buying one is not
        # UNSAFE for the shares (it was, against the engine's verdict).
        _us_call_note = (_usa and _is_opt_sym(_q) and _opt_right(_q) == "C"
                         and not _closes)
        clears = None
        # A VIOLATION anywhere in the class poisons every leg's date:
        # cross-listings are identical property, so a BLOCKED leg's
        # own "safe from" date can be WEEKS before the violation
        # leg's loss becomes safely rebuyable — printing it (or
        # exporting it as the class clears_at) invited a rebuy that
        # cancels the newer loss (2026-09 audit).
        # A settled one whose window is over for a buyer (backlog
        # TJ-0775) poisons nothing.
        _class_has_violation = any(
            (r.get("category") or "") == "VIOLATION"
            and not _window_over(r)
            for r in matches.values())
        # Such a class's safe-from date is the radar's re-entry date
        # (rebuy_at: the first trading day a buy no longer replaces any
        # of its losses, the date `rebuy` prints), the latest across the
        # class — never a VIOLATION's sell-by CLEARS date, which the
        # radar's table shows and buy-check used to send the reader to
        # (backlog TJ-0137). None when a loss row lacks it.
        _loss_rows = [r for r in matches.values()
                      if (r.get("category") or "") in ("BLOCKED", "COOLING",
                                                       "VIOLATION")
                      and not _window_over(r)]
        _class_rebuy = (max(str(r["rebuy_at"]) for r in _loss_rows)
                        if _loss_rows and all(r.get("rebuy_at")
                                              for r in _loss_rows)
                        else None)
        for t, r in _with_forward_rows(matches):
            cat = r.get("category") or ""
            # A loss whose window is over (a settled VIOLATION) is no
            # reason to wait: "no recent loss sale" is a buy's view.
            _no_loss = ("no loss sale a buy can still replace"
                        if r.get("after_passed") else "no recent loss sale")
            if _usa and r.get("outside_wash_rule"):
                # A futures contract / futures option: outside §1091
                # (US-WASH-18) — a re-purchase never disallows its loss
                # (audit A2-0435: UNSAFE, exit 1).
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(f"{t}: {r.get('advisory')}")
                continue
            _sc = r.get("short_cover_loss") if _usa else None
            if _sc and not _is_opt_sym(_q):
                # §1091(e) / US-WASH-05: only a new SHORT sale replaces a
                # short-cover loss; a buy never does (audit A2-0436).
                # Beside a long loss a buy can replace (the row's
                # recent_loss), that one still decides the verdict
                # below (backlog TJ-0559).
                # A WASHED row's other losses are washed ones (its
                # advisory says which), never the short cover alone.
                _long_too = bool(r.get("recent_loss")) or cat == "WASHED"
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(
                    f"{t}: "
                    + ("a loss within the past 30 days was also on"
                       if _long_too else
                       "the loss sold within the past 30 days was on")
                    + f" covering a short ({_sc.get('date')}) — a buy does "
                    f"not replace it (§1091(e)); only a new short sale "
                    f"before {_sc.get('reshort_ok_from')} would disallow "
                    f"it.")
                if cat in ("BLOCKED", "COOLING") and not _long_too:
                    continue
            if (_us_call_note and not _is_opt_sym(t.strip().upper())
                    and cat in ("BLOCKED", "COOLING", "VIOLATION",
                                "WASHED")):
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(
                    f"{t}: {cat} — {_loss_within_30(r)}; "
                    f"{_q} is a long call on these shares: §1091 may "
                    f"treat it as an option to acquire them, so buying it "
                    f"now may make that loss a wash sale — the US engine "
                    f"only flags it (a warning, call_vs_share_loss), so "
                    f"check it by hand.")
                continue
            if _window_over(r):
                # Its rescue date has passed and every loss's re-entry
                # date has come: a buy traded today settles after the
                # window — it replaces nothing (`rebuy` lists the loss
                # as cleared; backlog TJ-0775).
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(f"{t}: {_passed_violation_text(r)} Its 30-day "
                             f"window has ended: a buy now does not "
                             f"replace that loss.")
            elif cat in ("BLOCKED", "COOLING", "VIOLATION"):
                verdict = "UNSAFE"
                # VIOLATION's clears_at is the radar's SELL-BY
                # deadline (loss + 30 — the last day to rescue), NOT
                # a re-entry date: printing it as "safe to buy from"
                # invited a rebuy up to four weeks early, killing the
                # loss permanently. Only the re-entry categories
                # carry a usable date (a class with a VIOLATION: the
                # rows' rebuy_at); take the LATEST across the
                # class, not the first alphabetically.
                _cd = (_class_rebuy if _class_has_violation
                       else r.get("clears_at"))
                if _cd:
                    clears = max(clears, _cd) if clears else _cd
                # Only the rebought units' share of the loss is denied
                # (audit S054-07): state it per unit when the radar
                # carries the loss and the units sold at it — money as
                # the advisories print it, fmt_money and the base
                # currency, never '$' (backlog TJ-0244, TJ-0121).
                _rl, _rq = r.get("recent_loss"), r.get("recent_loss_qty")
                # One unit's share (the radar's _per_unit_denial): two
                # Canadian sales in the window are each replaced by the
                # same unit, and a US short-cover loss is no buy's —
                # the total over the units sold halved or inflated it
                # (backlog TJ-0559, TJ-0560). An older radar: the ratio.
                _ps = r.get("recent_loss_per_unit")
                if _ps is None and _rl and _rq and float(_rq) > 1e-9:
                    _ps = float(_rl) / float(_rq)
                _upto = r.get("recent_loss_per_unit_qty")
                _first = (f" for the first {float(_upto):g} units"
                          if _upto else "")
                _per = (f" on as many units as you buy (about "
                        f"{_money_cur(float(_ps))} of it per unit"
                        f"{_first})" if _ps else "")
                if (_per and _is_opt_sym(_q)
                        and not _is_opt_sym(t.strip().upper())):
                    # A call replaces the shares it is a right to: one
                    # standard contract is 100 of them (CA-SL-05; the
                    # per-unit figure read as per contract, audit
                    # A2-0752).
                    from taxjson.lib.core import OPTION_CONTRACT_SHARES
                    _ps = float(_ps)
                    _per = (f" on as many shares as the calls cover "
                            f"(about {_money_cur(_ps)} of it per share, "
                            f"{_money_cur(_ps * OPTION_CONTRACT_SHARES)} "
                            f"per standard {OPTION_CONTRACT_SHARES:g}-share "
                            f"contract{_first.replace('units', 'shares')})")
                lines.append(
                    f"{t}: {cat} — {_loss_within_30(r)}; buying now "
                    f"cancels it{_per}"
                    + ("" if _usa else
                       " if you still hold the shares 30 days after "
                       + ("that cover" if _short_cover_loss_date(r)
                          else "that sale"))
                    + f" (DEFERRED if bought taxable, PERMANENT if bought "
                    f"{'in an IRA' if _usa else 'sheltered'})."
                    + (f" Safe to buy from {_cd}." if _cd else
                       " Wait until 31 days after the LATEST in-window "
                       "loss sale (its REBUY ON date: `tjs rebuy`)."))
            elif cat == "WASHED":
                # US §1091: the loss is already disallowed (nothing a
                # buy can make worse) unless part of an in-window loss
                # is still allowed — then a buy before clears_at
                # disallows that part too.
                _cd = r.get("clears_at")
                if _cd:
                    verdict = "UNSAFE"
                    clears = max(clears, _cd) if clears else _cd
                    lines.append(f"{t}: {r.get('advisory')} Safe to buy "
                                 f"from {_cd}.")
                else:
                    if verdict == "SAFE":
                        verdict = "SAFE*"
                    _wadv = str(r.get("advisory") or "")
                    if _sc and not _is_opt_sym(_q):
                        # The short cover has its line above: "that
                        # loss" is the washed one (backlog TJ-0681).
                        for _n in r.get("notes") or []:
                            if "covering a short" in str(_n):
                                _wadv = _wadv.replace(" " + str(_n), "")
                    lines.append(
                        f"{t}: {_wadv} Buying now changes "
                        f"nothing for that loss, but it starts a new "
                        f"30-day window for a later loss sale.")
            elif cat == "LOCKED":
                # A registered account's / IRA's in-window buy denies a
                # taxable loss sale even as a full exit: the generic
                # "a full exit is not" contradicted sell-check's LOCKED
                # verdict (audit A2-0408). The radar's advisory states
                # the case in the project's law.
                if verdict == "SAFE":
                    verdict = "SAFE*"
                _adv = str(r.get("advisory") or "")
                _adv = _adv.split(":", 1)[1].strip() if \
                    _adv.startswith("LOCKED:") else _adv
                lines.append(
                    f"{t}: LOCKED — {_no_loss}, buying is safe "
                    f"TODAY, but selling even the full taxable position "
                    f"at a loss does not escape the rule: {_adv} Buying "
                    f"more extends the wash window.")
            elif cat in ("EXITABLE", "CAUTION"):
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(
                    f"{t}: {cat} — {_no_loss}"
                    + (" a buy can disallow" if _sc and not
                       r.get("after_passed") else "")
                    + f", buying is safe TODAY, but it extends the wash "
                    f"window: {_future_rule}.")
        # A warrant/right, a call on an adjusted series or a futures
        # option on the shares of a recent loss: the engines flag it for
        # a manual check (CA-SL-14/15, US-WASH-14/15); buy-check said
        # SAFE, 'no wash exposure on record' (audit A2-0129).
        for t, r, kind in _flagged_share_rows(radar, _q):
            cat = r.get("category") or ""
            if cat not in ("BLOCKED", "COOLING", "VIOLATION", "WASHED"):
                continue
            if verdict == "SAFE":
                verdict = "SAFE*"
            lines.append(
                f"{t}: {cat} — {_loss_within_30(r)}; {_q} "
                f"is {_FLAG_WORDS[kind]} these shares: a right to acquire "
                f"them bought now may make that loss "
                + ("a wash sale (§1091 \"contract or option to "
                   "acquire\")" if _usa
                   else "superficial (s.54 para (i))")
                + f" — the engine only flags it [{kind}], so check it by "
                  f"hand.")
        matches = {t: r for t, r in matches.items()
                   if (r.get("category") or "")}
        if len(lines) == bool(_note) and matches:
            cats = ", ".join(f"{t} ({r.get('category')})"
                             for t, r in sorted(matches.items()))
            lines.append(f"{cats}: no loss sale in the past 30 days — "
                         f"safe to buy. (Any buy starts a 30-day "
                         f"window: {_future_rule}.)")
        elif not lines:
            lines.append(f"{wroot}: no wash exposure on record — safe "
                         f"to buy. (Any buy starts a 30-day window: "
                         f"{_future_rule}.)")
        for _sl in _similar_lines(radar, _canon, wroot, want, "buy", _usa):
            if verdict == "SAFE":
                verdict = "SAFE*"
            lines.append(_sl)
        _ll = _last_loss_for(_last_loss, want, wroot, "buy", _closes,
                             canon=_canon)
        _lll = _last_loss_line(_ll)
        if _lll:
            lines.append(_lll)
        if verdict == "UNSAFE":
            unsafe += 1
        results.append({"symbol": want.strip().upper(),
                        "verdict": verdict,
                        "clears_at": clears, "detail": lines,
                        "last_loss": _ll})

    # SAFE is "as far as this project's accounts show" (CA-PLAN-04 /
    # US-PLAN-04, audit S054-22).
    from taxjson.lib.wash_scope import scope_note as _scope_note
    _scope = _scope_note("usa" if _usa else "canada")
    if getattr(args, "json", False):
        _json_out({"results": results, "scope_note": _scope})
    else:
        _print_check_results(results, "usa" if _usa else "canada",
                             _details(args), "buy-check")
    if unsafe:
        raise SystemExit(1)


def cmd_sell_check(args: argparse.Namespace) -> None:
    """`tjs sell-check SYMBOL...`: is selling this ticker AT A
    LOSS today safe from the superficial-loss / wash-sale rules?
    UNSAFE when a registered account's recent buy it still holds
    would deny the loss on the WHOLE taxable position (LOCKED), or when
    an open violation is backed by a registered account's in-window
    buy; ACTION when a violation can be rescued by selling the taxable
    replacement; SAFE* for conditional cases (full-exit-only,
    sheltered-holds forward caveat); PARTIAL when only some units of a
    LOCKED position are at risk; SAFE otherwise
    — with the standard rule: no rebuy on EITHER side for 30 days
    after. Root-matched with ticker.map equivalences. Exit 1 when any
    queried symbol is UNSAFE or PARTIAL. Whether the sale would BE a
    loss at today's price is `tjs harvest`'s job."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    radar, _canon, _last_loss = _wash_class_context(
        root, cache, "tjs sell-check",
        json_doc=_check_na_json(root, args))
    _usa = _radar_country_is_usa(root)
    unsafe = 0
    results = []
    for want in args.symbol:
        want = _fold_class_separator(want)
        _coin = _us_coin_answer(_canon, radar, want)
        if _coin is not None:
            results.append({"symbol": want.strip().upper(),
                            "verdict": "SAFE", "clears_at": None,
                            "act_by": None, "detail": _coin,
                            "last_loss": None})
            continue
        wroot, matches, _note = _class_matches(radar, _canon, want)
        matches = _replacement_rows(want, matches, "sell", canon=_canon)
        verdict, lines = "SAFE", ([_note] if _note else [])
        clears = None        # safe-to-sell-from date (worst = LATEST)
        act_by = None        # rescue deadline: last TRADE date (EARLIEST)
        for t, r in _with_forward_rows(matches):
            cat = r.get("category") or ""
            adv = r.get("advisory") or ""
            if _usa and r.get("outside_wash_rule"):
                # A futures contract / futures option: outside §1091
                # (US-WASH-18) — the radar's own line, not 'do not rebuy'.
                lines.append(f"{t}: {adv}")
            elif cat == "LOCKED":
                # A registered account's in-window buy it still holds
                # denies the loss on up to that many units — the rest of
                # a sale stands (s.54, per holder). UNSAFE only when the
                # whole taxable position is at risk; a fraction is
                # PARTIAL, its line stating the units (still exit 1: a
                # part of the loss would be lost for good). An older
                # radar without at_risk_qty stays UNSAFE.
                _risk = r.get("at_risk_qty")
                _tq = abs(float(r.get("taxable_qty") or 0.0))
                if (_risk is not None and _tq > 1e-9
                        and float(_risk) < _tq - 1e-6):
                    if verdict != "UNSAFE":
                        verdict = "PARTIAL"
                else:
                    verdict = "UNSAFE"
                _cd = r.get("clears_at")
                if _cd:                     # worst case across the class
                    clears = max(clears, _cd) if clears else _cd
                lines.append(f"{t}: {adv}")
            elif cat == "VIOLATION" and r.get("deadline_passed"):
                # The last rescue trade date has passed: the loss is
                # denied and no sale undoes it — never an ACTION with a
                # sell-by date in the past (audit A2-0368). A loss sale
                # today of the shares still held is judged on its own:
                # the row's `forward` view follows it (backlog TJ-0775).
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(f"{t}: {_passed_violation_text(r)}")
            elif cat == "VIOLATION":
                _cd = r.get("clears_at")
                if _cd:
                    # A VIOLATION's date is a SELL-BY deadline — the
                    # radar's last TRADE date that settles inside the
                    # engine's loss_settle+30 bound (never the settle
                    # date itself: trading ON that settles a day late
                    # and the loss is denied). The binding one across
                    # a class of identical property is the EARLIEST,
                    # not the latest — max() exported a date that
                    # missed the tighter leg's rescue by days
                    # (2026-09 audit).
                    act_by = min(act_by, _cd) if act_by else _cd
                _rescue = r.get("rescue")
                if _rescue is None:
                    # A radar from before the per-holder rule: any
                    # sheltered holding was treated as backing.
                    _shl_accts = (["a sheltered account"]
                                  if abs(float(r.get("sheltered_qty")
                                               or 0.0)) > 0.01 else [])
                else:
                    # Only a registered account that bought inside the
                    # window and still holds backs the denial (s.54,
                    # per holder); shares it held before the window
                    # never do.
                    _shl_accts = sorted({
                        f"'{x.get('account') or 'unknown'}'"
                        for x in _rescue
                        if x.get("holder") == "sheltered"})
                if _shl_accts:
                    # The registered-matched portion is denied for good
                    # ONLY if that account still holds at the window's
                    # end — selling there too before the deadline
                    # defeats it.
                    verdict = "UNSAFE"
                    lines.append(
                        f"{t}: {adv} Registered holder(s) "
                        f"{', '.join(_shl_accts)} bought inside the "
                        f"window: unless they also sell by that trade "
                        f"date" + (f" ({_cd})" if _cd else "")
                        + f", the registered-matched portion is "
                        f"permanently denied.")
                else:
                    if verdict not in ("UNSAFE", "PARTIAL"):
                        verdict = "ACTION"
                    lines.append(f"{t}: {adv}")
            elif cat == "WASHED":
                # US §1091: an earlier loss is already disallowed and no
                # sale undoes it — there is nothing to rescue (never
                # ACTION). Selling the replacement realizes the deferred
                # loss that sits in its basis.
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(
                    f"{t}: {adv} A sale now cannot restore that loss; "
                    f"selling the replacement lot realizes the loss added "
                    f"to its basis, but a PARTIAL loss sale with other "
                    f"buys in the last 30 days is a wash sale again.")
            elif cat in ("EXITABLE", "CAUTION", "RISK"):
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(f"{t}: {adv}")
            elif cat in ("BLOCKED", "COOLING"):
                _scd = _short_cover_loss_date(r)
                lines.append(f"{t}: {cat} — "
                             + (f"a recent loss on covering a short "
                                f"({_scd}) is" if _scd else
                                "a recent loss sale is")
                             + f" already in its cooling window; if any "
                             f"position remains, a further loss sale "
                             f"is fine only with no buys within ±30 "
                             f"days.")
            elif cat == "CLEAR":
                if abs(float(r.get("taxable_qty") or 0.0)) <= 0.01:
                    # Sheltered-only holding: nothing to sell at a
                    # loss, and a registered disposition has no tax
                    # effect at all.
                    lines.append(
                        f"{t}: held only in "
                        f"{'IRA(s)' if _usa else 'sheltered account(s)'}"
                        f" — nothing to sell at a loss (a "
                        f"{'tax-deferred' if _usa else 'registered'} "
                        f"disposition has no tax effect).")
                elif float(r.get("taxable_qty") or 0.0) < 0:
                    lines.append(f"{t}: {adv}")
                else:
                    lines.append(f"{t}: CLEAR — safe to sell at a loss "
                                 f"now; do not rebuy on EITHER side "
                                 f"(taxable or "
                                 f"{'IRA' if _usa else 'sheltered'}) for "
                                 f"30 days.")
            # Warn-only flags (a US long call, a warrant, an adjusted
            # series, a futures option bought in the window; a US
            # short-cover loss's re-short rule), whatever the row's
            # category — a BLOCKED row dropped them (audit A2-0687 /
            # A2-0434 / A2-0445); skipped when the line already quotes
            # the advisory that carries them.
            for _n in r.get("notes") or []:
                if any(_n in ln for ln in lines):
                    continue
                if verdict == "SAFE":
                    verdict = "SAFE*"
                lines.append(f"{t}: {_n}")
        if len(lines) == bool(_note):
            lines.append(f"{wroot}: no tracked taxable position — "
                         f"nothing to sell (or run `tjs run` to "
                         f"refresh the books).")
        for _sl in _similar_lines(radar, _canon, wroot, want, "sell", _usa):
            if verdict == "SAFE":
                verdict = "SAFE*"
            lines.append(_sl)
        _ll = _last_loss_for(_last_loss, want, wroot, "sell",
                             canon=_canon)
        _lll = _last_loss_line(_ll)
        if _lll:
            lines.append(_lll)
        if verdict in ("UNSAFE", "PARTIAL"):
            unsafe += 1
        results.append({"symbol": want.strip().upper(),
                        "verdict": verdict,
                        "clears_at": clears,
                        "act_by": act_by, "detail": lines,
                        "last_loss": _ll})
    # SAFE is "as far as this project's accounts show" (CA-PLAN-04 /
    # US-PLAN-04, audit S054-22).
    from taxjson.lib.wash_scope import scope_note as _scope_note
    _scope = _scope_note("usa" if _usa else "canada")
    if getattr(args, "json", False):
        _json_out({"results": results, "scope_note": _scope})
    else:
        _print_check_results(results, "usa" if _usa else "canada",
                             _details(args), "sell-check")
    if unsafe:
        raise SystemExit(1)


def cmd_rebuy(args: argparse.Namespace) -> None:
    """`tjs rebuy [SYMBOL ...] [--date D]`: every ticker sold at a
    loss whose repurchase window is still open, with the first day it
    can be bought back without the loss being denied (CA-PLAN-05 /
    US-PLAN-06). The rows are the wash radar's own (its `losses` and
    `rebuy_at`, run as of the date with --all), matched to the query
    the way buy-check matches (ticker.map / tobase.map, renames, an
    option's underlying); lib/rebuy groups and renders them."""
    from taxjson.lib import rebuy as RB
    from taxjson.lib.ticker_map import class_share_aliases, underlying_of
    root = Path(args.dir).resolve()
    cache = root / "work"
    if args.date:
        from taxjson.lib.dates import as_of_date_problem
        _bad = as_of_date_problem(args.date)
        if _bad:
            _die_input(_bad)
    as_of = args.date or RB.as_of_default()

    def _na_doc() -> Dict[str, Any]:
        # No wash-checkable account: rebuy's document with no row
        # (backlog TJ-0330).
        from taxjson.lib.wash_scope import scope_note as _sn
        c = "usa" if _radar_country_is_usa(root) else "canada"
        d = RB.build({}, as_of, c)
        d.update(currency=_base_currency(root), scope_note=_sn(c),
                 any_account=RB.any_account_line(c))
        return d
    radar, canon, _ll = _wash_class_context(
        root, cache, "tjs rebuy",
        ["--date", as_of, "--cleared-days", str(RB.CLEARED_DAYS)],
        json_doc=_na_doc if getattr(args, "json", False) else None)
    country = "usa" if _radar_country_is_usa(root) else "canada"
    want = None
    asked = []
    if args.symbol:
        want = set()
        for s in args.symbol:
            _w, _m, _n = _class_matches(radar, canon,
                                        _fold_class_separator(s))
            _ws = {_w} | {canon(t) for t in _m}
            want |= _ws
            asked.append((s.strip().upper(), _ws, bool(_m)))
    _aliases = class_share_aliases(radar)
    doc = RB.build(radar, as_of, country, canon=canon,
                   underlying=lambda s: underlying_of(s, _aliases),
                   want=want)
    if asked:
        # A SYMBOL with no row is said so, with the count of the other
        # tickers that have an open window: "No ticker sold at a loss
        # has an open repurchase window" was false then, and a mistyped
        # symbol read as nothing to wait for (backlog TJ-0104).
        full = RB.build(radar, as_of, country, canon=canon,
                        underlying=lambda s: underlying_of(s, _aliases))
        doc["asked"] = [a for a, _ws, _b in asked]
        doc["unmatched"] = [
            {"symbol": a, "in_books": in_books}
            for a, _ws, in_books in asked
            if not any(canon(x["ticker"]) in _ws
                       for x in doc["rows"] + doc["cleared"])]
        doc["others_open"] = len({r["ticker"] for r in full["rows"]}
                                 - {r["ticker"] for r in doc["rows"]})
    from taxjson.lib.wash_scope import scope_note as _scope_note
    doc["currency"] = _base_currency(root)
    doc["scope_note"] = _scope_note(country)
    doc["any_account"] = RB.any_account_line(country)
    if getattr(args, "json", False):
        _json_out(doc)
        return
    RB.render(doc, doc["currency"], _details(args)).print()


# Pipeline artifacts in work/ that are NOT parsed-source files — the
# audit's source join must never read a derived book as provenance.
_AUDIT_DERIVED_SUFFIXES = (
    "_base.json", "_gains.json", "_gains_wash.json", _GAINS_ALL_SUFFIX,
    "_raw.json",
    "_raw_base.json", "_raw_gains.json", "_raw_base_gains.json",
    "_merged.json", "_sorted.json", "_filled.json", "_report.json",
    # The crypto ticker.map stage's output: a renamed copy of the
    # parse, read as a second source it claimed a false 2-file dedup
    # and hid the rename (S047-12).
    "_mapped.json", "_manifest.json",
    "_pending_elections.json", "_validate.diag",
    # The engine's cost timelines (timeline_beside): pools, not rows.
    ".timeline.json",
)


def _audit_source_files(cache: Path, name: str,
                        accounts=None) -> List[Path]:
    """The parsed-source JSONs for one account: everything the pipeline
    wrote as `{name}_*.json` that is not a derived book. These are the
    per-brokerage parses, converted .tt files, and corp-action rows —
    the nominal-currency provenance the audit joins dispositions to.
    `accounts` (the configured names) keeps a longer-named sibling's
    files out: `margin_*.json` also matches margin_us's parses, which
    the audit then listed twice (S047-13)."""
    siblings = [a for a in (accounts or [])
                if a != name and str(a).startswith(f"{name}_")]
    out = []
    for p in sorted(cache.glob(f"{name}_*.json")):
        if any(p.name.endswith(sfx) for sfx in _AUDIT_DERIVED_SUFFIXES):
            continue
        if any(p.name.startswith(f"{sib}_") for sib in siblings):
            continue
        out.append(p)
    return out


def _check_books_before_merge(paths: List[Path]) -> None:
    """Load each base book a command is about to merge into a temp file,
    and die naming the damaged one. taxjson-merge passes a well-formed
    JSON file with a bad row straight through, so the engine's error
    named the deleted /tmp merge file instead of work/<acct>_base.json
    (A2-1143)."""
    from taxjson.lib.core import load_transactions
    for b in paths:
        try:
            load_transactions(Path(b))
        except Exception as e:                      # noqa: BLE001
            msg = str(e).strip().splitlines()[0] if str(e).strip() \
                else type(e).__name__
            msg = msg.replace(f"load_transactions({b}): ", "")
            _die(f"cannot read {b}: {msg} — re-run `tjs run` to "
                 f"rebuild it.")


def _audit_diag(kind: str, text: str) -> None:
    """`tjs audit: <kind>: ...` on stderr, wrapped (lib/out)."""
    from taxjson.lib.out import emit
    emit(kind, text, prog="tjs audit")


def cmd_audit(args: argparse.Namespace) -> None:
    """`tjs audit`: the authoritative justification of every
    capital-gain figure. One block per taxable disposition: the parsed
    broker row (nominal currency, original ticker, source file), the
    ticker.map rename, the exact FX rate applied (with provenance and
    a to-the-cent recomputation against the base books), the engine's
    disposition math, the wash-sale / superficial-loss determination
    with replacement lots resolved, a tie-out against the pipeline's
    saved gains files, and the full ACB/FIFO pool trace. Runs the same
    blended computation the pipeline runs (ITA s.47 cross-account ACB
    / US cross-account §1091), so the numbers ARE the filed numbers —
    and exits 1 if any cross-check disagrees."""
    import json as _json
    import os as _os
    import tempfile
    from taxjson.lib.dispatch import run_cmd as _run

    root = Path(args.dir).resolve()
    cache = root / "work"
    settings = _soft_settings(root)
    if not settings:
        _die("no taxjson.toml here — audit is a project command "
             "(run it from the project root, or pass -C).")
    # The recomputation reads the market lines (SECFUT, INDEXOPT, MULT)
    # the run read: it soft-reads the config, which does not point
    # lib/markets at the project (backlog TJ-1029).
    _use_project_ticker_map(root)
    country = _country(settings)
    tax_date = _tax_date(settings)
    base_currency = str(settings.get("base_currency")
                        or _home_currency(settings)).upper()
    year = None if getattr(args, "all_years", False) else (
        getattr(args, "year", None) or settings.get("year"))

    acfgs = _soft_config(root).get("accounts") or {}
    taxable = {n: (c or {}) for n, c in acfgs.items()
               if (c or {}).get("type") == "taxable"}
    if not taxable:
        _die("no taxable accounts in taxjson.toml — nothing to audit.")
    # taxjson.toml order, as the pipeline's blended pass merges them
    # (CA-DATE-14 / US-DATE-13); alphabetical failed the tie-out on a
    # book with same-moment rows in two accounts (A2-1592 sibling).
    equity = [n for n, c in taxable.items() if not c.get("crypto")]
    crypto = [n for n, c in taxable.items() if c.get("crypto")]
    # The crypto accounts the run computes in ONE blended pass (cmd_run's
    # _crypto_blend / _us_crypto_blend), decided on the configuration as
    # the run decides it: every crypto account of a Canadian project
    # with two or more (s.47 pooled ACB, the superficial-loss rule
    # across exchanges), or a US project's crypto accounts without
    # `transfers` once a move between two of them was paired (their
    # work/<account>_own_moves.json): FIFO per account, no wash-sale
    # rule, the move carrying the sender's lots (US-CRYPTO-05). Each
    # account on its own used to lose the moved coins' basis: a correct
    # gain failed the tie-out (backlog TJ-0311).
    if country not in ("us", "usa"):
        crypto_group = list(crypto) if len(crypto) >= 2 else []
    elif any(not taxable[n].get("transfers")
             and (cache / f"{n}{OWN_MOVES_SUFFIX}").is_file()
             for n in crypto):
        crypto_group = [n for n in crypto if not taxable[n].get("transfers")]
    else:
        crypto_group = []
    _acct = getattr(args, "account", None)
    if _acct:
        if _acct not in taxable:
            _die(f"--account {_acct!r} is not a taxable account in "
                 f"taxjson.toml (audit covers: "
                 f"{', '.join(sorted(taxable))}).")
        # Only the computation that holds the account: the blended
        # equity pass (still over ALL equity books — display filter
        # only) or the crypto pass that holds it — the crypto blend over
        # all its books (narrowing it to one book re-ran that book's own
        # cost and failed the tie-out, #79), else that account's own
        # books. The others would print empty 0/0 blocks.
        if _acct in crypto:
            equity = []
            crypto = (list(crypto_group) if _acct in crypto_group
                      else [_acct])
        else:
            crypto = []

    sheltered_base = cache / "sheltered_base.json"
    mh_file = _missing_history_arg(root)
    rates = cache / "to_base.csv"
    tmap = _PL.ticker_map_path(root)

    # A LOCKED year is recomputed with the option timing its lock
    # recorded, as check-filed does: `audit --year 2025` from a 2026
    # project without since = 2025 printed -1,000 for a year filed at
    # -601, with no word (S048-18).
    # The lock may live in the previous year's project (per-year
    # layout, [settings] prior_year_record) — it counts the same as a
    # local filed/<year>.json (A2-0335, A2-0664). Its recorded DATE
    # BASIS applies too, as check-filed's lock_settings does: a year
    # filed on settlement dates is audited on settlement dates
    # (A2-0334, A2-1129).
    _timing_flags = option_timing_flags(settings)
    if year and str(year) != str(settings.get("year")):
        from taxjson.bin import taxjson_filed as _tf
        try:
            _hit = _tf.lock_for_year(root, settings, int(year))
        except _tf.PriorRecordError as e:
            _die(str(e))
        if _hit is not None:
            _lp, _where = _hit
            _lname = _tf.lock_label(root, _lp)
            _lock = None
            # The one reader every lock consumer uses (read_lock: the
            # JSON, no key written twice, the shape and year field). A
            # damaged lock's settings are not applied, and said.
            try:
                _lock = _tf.read_lock(_lp, label=_lname)
                _lot = (_lock.get("option_timing")
                        if isinstance(_lock, dict) else None)
            except _tf.LockProblem as e:
                _lock = _lot = None
                _audit_diag("warning",
                            f"{e} — {year} is recomputed with this "
                            f"project's option timing and date basis, "
                            f"which may not be the ones it was filed "
                            f"on.")
            # A lock closed under the other country is refused before
            # any of its settings apply, as check-filed and handoff
            # refuse it: a US lock's trade date basis moved a Canadian
            # sale into the audited year and the audit passed (backlog
            # TJ-0550).
            _cp = (_tf.lock_country_problem(
                _lock, settings, _lname,
                prior=_where == "prior_year_record")
                if isinstance(_lock, dict) else None)
            if _cp:
                _die(f"audit --year {year}: {_lname} is another "
                     f"country's lock", _cp)
            _lb = _tf.lock_settings(_lock, settings).get("tax_date") \
                if isinstance(_lock, dict) else None
            if _lb in ("settle", "trade") and _lb != tax_date:
                _audit_diag("note",
                            f"{year} is locked ({_lname}) — recomputed on "
                            f"the {_lb} date basis its lock recorded, not "
                            f"this project's {tax_date} basis.")
                tax_date = _lb
            if isinstance(_lot, dict):
                _lf = _tf._lock_timing_flags(settings, int(year), _lot)
                if _lf != _timing_flags:
                    _audit_diag("note",
                                f"{year} is locked ({_lname}) — "
                                f"recomputed with the option timing its "
                                f"lock recorded ({' '.join(_lf)}), not "
                                f"this project's "
                                f"({' '.join(_timing_flags) or 'none'}).")
                _timing_flags = _lf

    def common_flags() -> List[str]:
        fl = ["--country", country, "--tax-date", tax_date,
              "--base-currency", base_currency]
        if year:
            fl += ["--year", str(year)]
        if settings.get("year"):
            # The saved gains files are year-scoped (R1-191).
            fl += ["--check-year", str(settings.get("year"))]
        if rates.exists():
            fl += ["--rates", str(rates)]
        if tmap.exists():
            fl += ["--map", str(tmap)]
        # The listings the run joined by their transfer journal (its
        # effective map): `audit QZD.U.TO` finds the sale the run booked
        # as QZD.TO (backlog TJ-0773).
        from taxjson.lib.cross_listings import EFFECTIVE_MAP as _EFF_MAP
        if (cache / _EFF_MAP).is_file():
            fl += ["--effective-map", str(cache / _EFF_MAP)]
        from taxjson.lib.dated_events import STATE as _DE_STATE
        if (cache / _DE_STATE).is_file():
            # The .tt RENAME line a ticker change's row came from
            # (backlog TJ-0359).
            fl += ["--dated-events", str(cache / _DE_STATE)]
        if mh_file is not None:
            fl += ["--incomplete-history", str(mh_file)]
        fl += _timing_flags
        # The project's income-dating overrides, as the run applied
        # them (re-audit A2-0033: the trust ROC record date).
        fl += income_dating_flags(settings)
        # ...and its filing positions against the loss rule (ALLOWLOSS).
        fl += _loss_override_flags(root / "work")
        # ...and its filed years: a US wash-sale basis add to a
        # replacement sold in one is booked in the loss's year
        # (US-WASH-22), as every gains pass of the run books it
        # (backlog TJ-0313). Canada: none.
        fl += _locked_year_flags(root, settings)
        for sym in getattr(args, "symbol", None) or []:
            fl += ["--symbol", sym]
        if getattr(args, "gain_id", None):
            fl += ["--id", args.gain_id]
        if getattr(args, "date", None):
            fl += ["--date", args.date]
        if getattr(args, "account", None):
            fl += ["--account", args.account]
        if getattr(args, "summary", False):
            fl.append("--summary")
        if getattr(args, "no_trace", False):
            fl.append("--no-trace")
        if getattr(args, "no_color", False):
            fl.append("--no-color")
        if not _details(args):
            # Essentials first (docs/output-style.md): the rounding
            # note is the --details view.
            fl.append("--brief")
        # "Nothing matched" is decided across ALL invocations below.
        fl += ["--no-match-rc", "3"]
        return fl

    # (flags, cleanup_path|None) per engine computation, mirroring the
    # pipeline: ONE blended pass over the equity taxable accounts, then
    # the crypto accounts — ONE blended pass too for a Canadian project
    # with two or more of them (the pipeline's crypto blend), else each
    # on its own books.
    invocations: List[Tuple[List[str], Optional[Path]]] = []
    crypto_blend = [n for n in crypto if n in crypto_group]

    _no_input = _accounts_skipped_for_no_inputs(root)
    # Configured accounts (with inputs) the audit could not cover: the
    # tie-out printed "✓" over the rest and exited 0, and the checklist
    # marked every disposition traced (S047-16).
    _uncovered: List[str] = []

    # An account the last run deferred at a corp-action election (its
    # work/<acct>_pending_elections.json): its book is incomplete and
    # the cross-account pass never ran, so its dispositions cannot tie
    # (2026-10 workflow audit: 3 MISMATCHED and FAILED over a pending
    # election). Left out, and said.
    _pending = sorted(n for n in acfgs
                      if (cache / f"{n}_pending_elections.json").exists())
    # The accounts blended with a deferred one: the run's cross-account
    # pass never ran, so their saved gains are per-account figures that
    # the audit's blended recomputation cannot tie (3 MISMATCHED and a
    # "stale work/" FAILED over a pending election: backlog TJ-0196).
    # Not audited either, and said.
    _held_back: List[str] = []

    def _blended_invocation(names: List[str], *, is_crypto: bool) -> None:
        if _pending:
            # The run runs no cross-account pass while ANY account
            # (sheltered too) waits on an election (cmd_run: `not
            # pending_accounts`), the crypto blend included: an equity
            # election left the crypto accounts' per-account gains,
            # which the audit's blend could not tie (backlog TJ-0314).
            _held_back.extend(n for n in names if n not in _pending)
            return
        bases = [cache / f"{n}_base.json" for n in names
                 if (cache / f"{n}_base.json").exists()]
        missing = [n for n in names
                   if not (cache / f"{n}_base.json").exists()
                   and n not in _no_input]
        _uncovered.extend(missing)
        if missing:
            _audit_diag("note", f"no books yet for {', '.join(missing)} "
                                f"— run `tjs run` to include them.")
        if not bases:
            return
        cleanup: Optional[Path] = None
        if len(bases) == 1:
            base_arg = bases[0]
        else:
            # Merge the CURRENT per-account base books — the same
            # inputs the pipeline's blended pass merged, rebuilt fresh
            # so a stale .blend artifact can't smuggle old numbers
            # past the tie-out.
            _check_books_before_merge(bases)
            fd, tmp = tempfile.mkstemp(prefix="taxjson_audit_",
                                       suffix=".json")
            _os.close(fd)
            cleanup = Path(tmp)
            res = _run(_cmd("taxjson-merge")
                       + [str(b) for b in bases],
                       capture_output=True)
            if res.returncode != 0:
                cleanup.unlink(missing_ok=True)
                _die(f"could not merge the taxable base books: "
                     f"{_child_error(res.stderr)}")
            cleanup.write_text(res.stdout, encoding="utf-8")
            base_arg = cleanup
        fl = common_flags() + ["--base", str(base_arg)]
        _us = country in ("us", "usa")
        if _us and is_crypto:
            # A US crypto blend carries lots only: §1091 does not reach
            # digital assets (stage_blended_wash_pass no_wash).
            fl.append("--no-wash")
        elif sheltered_base.exists():
            fl += ["--sheltered", str(sheltered_base)]
        if _us:
            fl.append("--per-account-basis")
        for n in names:
            for src in _audit_source_files(cache, n, list(acfgs)):
                fl += ["--source", str(src)]
            if (cache / f"{n}_filled.json").exists():
                fl += ["--filled", str(cache / f"{n}_filled.json")]
            chk = cache / f"{n}_gains_wash.json"
            if not chk.exists():
                chk = cache / f"{n}_gains.json"
            if chk.exists():
                fl += ["--check", str(chk)]
        invocations.append((fl, cleanup))

    if equity:
        _blended_invocation(equity, is_crypto=False)
    if crypto_blend:
        _blended_invocation(crypto_blend, is_crypto=True)

    for n in crypto:
        if n in crypto_blend:
            continue
        if n in _pending:
            continue                    # its book is incomplete: named below
        base = cache / f"{n}_base.json"
        if not base.exists():
            if n not in _no_input:
                _uncovered.append(n)
                _audit_diag("note", f"no books yet for {n} — run "
                                    f"`tjs run` to include it.")
            continue
        fl = common_flags() + ["--base", str(base)]
        if country in ("us", "usa"):
            # §1091 does not reach digital assets — mirror the
            # pipeline's --no-wash on US crypto books.
            fl.append("--no-wash")
        elif sheltered_base.exists():
            fl += ["--sheltered", str(sheltered_base)]
        for src in _audit_source_files(cache, n, list(acfgs)):
            fl += ["--source", str(src)]
        if (cache / f"{n}_filled.json").exists():
            # Crypto rows priced by fill-crypto-prices (R1-271).
            fl += ["--filled", str(cache / f"{n}_filled.json")]
        chk = cache / f"{n}_gains_wash.json"
        if not chk.exists():
            chk = cache / f"{n}_gains.json"
        if chk.exists():
            fl += ["--check", str(chk)]
        invocations.append((fl, None))

    _also = sorted(set(_held_back))
    _pending_head = (f"not audited — corp-action elections pending for "
                     f"{', '.join(_pending)}"
                     + (f" (so {', '.join(_also)} too: no cross-account "
                        f"pass)" if _also else ""))
    if not invocations and _pending:
        _die(_pending_head,
             "Decide them (`tjs elect --pending`), then `tjs run`.")
    if not invocations:
        _die("no computed books in work/ — run `tjs run` first.")

    rc = 0
    no_match = 0
    _printed_groups = 0
    json_docs: List[Dict[str, Any]] = []
    try:
        for fl, _cl in invocations:
            cmd = _cmd("taxjson-audit") + fl
            if getattr(args, "json", False):
                res = _run(cmd + ["--json"], capture_output=True)
                if res.stderr:
                    sys.stderr.write(res.stderr)
                if res.returncode == 3:
                    no_match += 1
                    continue
                if res.returncode == 2:
                    # An input the audit cannot read: its own one line
                    # above says which; the same exit code as the text
                    # mode, and the next book would only repeat it
                    # (re-audit A2-0796).
                    rc = 2
                    break
                try:
                    json_docs.append(_json.loads(res.stdout))
                except ValueError:
                    _die(f"taxjson-audit produced no JSON "
                         f"(rc={res.returncode}).")
                rc = max(rc, res.returncode or 0)
            else:
                if _printed_groups:
                    print()                 # one blank line between groups
                    sys.stdout.flush()
                _printed_groups += 1
                res = _run(cmd)
                if res.returncode == 3:
                    no_match += 1
                    continue
                rc = max(rc, res.returncode or 0)
                if res.returncode == 2:
                    break               # (A2-0796: printed once)
    finally:
        for _fl, _cl in invocations:
            if _cl is not None:
                _cl.unlink(missing_ok=True)
    if no_match and no_match == len(invocations) and _also:
        # The filter's dispositions may be in an account held back.
        _die(_pending_head,
             "Decide them (`tjs elect --pending`), then `tjs run`.")
    if no_match and no_match == len(invocations):
        _filt = [f"{k} {v}" for k, v in (
            ("symbol", " ".join(getattr(args, "symbol", None) or [])),
            ("--id", getattr(args, "gain_id", None)),
            ("--date", getattr(args, "date", None)),
            ("--account", _acct)) if v]
        _die(f"no disposition matches {', '.join(_filt)}"
             + (f" in {year}" if year else "")
             + " — check the filter (`tjs audit --summary` lists "
               "every event; --date matches the trade or settlement "
               "date).")

    if rc == 2:
        raise SystemExit(2)
    # What the audit could not cover, decided BEFORE anything is shown:
    # the --json document's `failed` and the exit status say the same
    # (it said failed=false over an account with no books while the
    # command exited 1: backlog TJ-0315). One line each (the checklist
    # shows a failed command's last line).
    not_audited: List[Dict[str, str]] = []
    coverage_failures: List[str] = []
    if _uncovered and not _acct:
        _nb = sorted(set(_uncovered))
        not_audited += [{"account": n, "reason": "no_books"} for n in _nb]
        coverage_failures.append(
            f"not audited — no books for {', '.join(_nb)}; their "
            f"dispositions are not in the tie-out above. Run `tjs "
            f"run`.")
    if _pending and not _acct:
        not_audited += [{"account": n, "reason": "elections_pending"}
                        for n in _pending]
        not_audited += [{"account": n, "reason": "no_cross_account_pass"}
                        for n in _also]
        coverage_failures.append(
            f"{_pending_head}; decide them (`tjs elect --pending`), "
            f"then `tjs run`.")
    if coverage_failures:
        rc = max(rc, 1)
    if getattr(args, "json", False):
        doc = _merge_audit_json(json_docs, base_currency, country)
        doc["not_audited"] = not_audited
        doc["coverage_failures"] = coverage_failures
        doc["failed"] = bool(doc.get("failed")) or bool(coverage_failures)
        _json_out(doc)
    elif not _details(args) and rc != 1:
        from taxjson.lib.out import details_hint as _dh
        print(_dh("tjs audit --details",
                  "what the tie-out compares, and why the totals can "
                  "differ from the return's rows by cents"))
    if coverage_failures:
        from taxjson.lib.out import warn as _warn
        for _cf in coverage_failures:
            _warn(_cf, prog="tjs audit")
    if rc:
        raise SystemExit(rc)


def _merge_audit_json(docs: List[Dict[str, Any]], base_currency: str,
                      country: str) -> Dict[str, Any]:
    """One `tjs audit --json` document from the per-book
    taxjson-audit runs: events concatenated, totals summed over EVERY
    book (S026-11 pins it), reconciliation failures kept (they were
    dropped when two books were merged). The gain total is the computed
    dispositions', as one book's is: an unknown-cost disposition
    (`manual_reporting`) is reported by hand and counted in
    `manual_reporting` only (backlog TJ-0302)."""
    if len(docs) == 1:
        return docs[0]
    from taxjson.bin.taxjson_audit import manual_reporting_totals, totals_note
    events = [e for d in docs for e in d.get("events") or []]

    def _total(ev_key: str, doc_key: str, computed_only: bool) -> float:
        # Over the events, rounded ONCE: adding each book's already-
        # rounded total put the audit a cent off wash-sales (S047-17).
        # Books whose events carry no amount keep their own totals.
        if events and all(ev_key in e for e in events):
            return round(sum(float(e.get(ev_key) or 0.0) for e in events
                             if not (computed_only
                                     and e.get("manual_reporting"))), 2)
        return round(sum(float(d.get(doc_key) or 0.0) for d in docs), 2)
    out = {"base_currency": base_currency, "country": country,
           "events": events,
           "total_gain": _total("gain", "total_gain", True),
           "total_disallowed": _total("disallowed_amount",
                                      "total_disallowed", False),
           "manual_reporting": manual_reporting_totals(events),
           "totals_note": totals_note(country),
           # Each book's pool-trade check summed, and what the audit
           # compares (backlog TJ-0332, TJ-0333).
           "pool_trades": {
               **{k: sum(int((d.get("pool_trades") or {}).get(k) or 0)
                         for d in docs)
                  for k in ("checked", "tied", "untraced")},
               **{k: [m for d in docs for m in
                      (d.get("pool_trades") or {}).get(k) or []]
                  for k in ("mismatched", "untraced_rows")}},
           # The rows that are not trades, the same way (TJ-0359).
           "pool_other_rows": {
               **{k: sum(int((d.get("pool_other_rows") or {}).get(k) or 0)
                         for d in docs)
                  for k in ("checked", "tied", "untraced")},
               **{k: [m for d in docs for m in
                      (d.get("pool_other_rows") or {}).get(k) or []]
                  for k in ("mismatched", "rows")}},
           "scope": next((d["scope"] for d in docs if d.get("scope")),
                         None),
           "reconciliation_failures": [
               f for d in docs
               for f in d.get("reconciliation_failures") or []],
           "failed": any(d.get("failed") for d in docs)}
    return out


def _project_base_files(cache: Path) -> List[Path]:
    """work/<account>_base.json of every account (not the raw/native
    books, not the combined sheltered book, not a dot-prefixed pass)."""
    return sorted(p for p in cache.glob("*_base.json")
                  if not p.name.endswith("_raw_base.json")
                  and p.name != "sheltered_base.json"
                  and not p.name.startswith("."))


def _year_short_rows(root: Path, files: List[Path], year: Any):
    """{(symbol, account): MissingHistoryRow} of every pair that goes
    short in the project's books, judged against `year`
    (lib/missing_history.classify_year_shorts) — the one test the run's
    console and `find-missing-history --outside-year` share."""
    from taxjson.lib.core import load_transactions
    from taxjson.lib.missing_history import (account_types_near,
                                              classify_year_shorts,
                                              walk_journal_symbols)
    txs = []
    for f in files:
        try:
            txs.extend(load_transactions(f))
        except (OSError, ValueError):
            continue
    settings = _soft_settings(root)
    tm = _PL.ticker_map_path(root)
    journal = walk_journal_symbols(root / "work",
                                   tm if tm.is_file() else None)
    types = (account_types_near(files[0]) if files else {})
    return classify_year_shorts(
        txs, year, country=_country(settings), registered=types,
        date_basis=_tax_date_basis(settings), journal_symbols=journal)


def _missing_history_suspects(root: Path, cache: Path
                              ) -> Set[Tuple[str, str]]:
    """{(symbol, account)} of the positions that go short in the
    project's books because a sale had nothing to close
    (lib/missing_history.missing_history_suspect) — read like
    find-missing-history reads them. Empty when the books cannot be
    read (advisory)."""
    try:
        from taxjson.lib.core import load_transactions
        from taxjson.lib.missing_history import (account_types_near,
                                                  missing_history_suspects,
                                                  walk_journal_symbols)
        files = _project_base_files(cache)
        txs = []
        for f in files:
            try:
                txs.extend(load_transactions(f))
            except (OSError, ValueError):
                continue
        tm = _PL.ticker_map_path(root)
        journal = walk_journal_symbols(cache, tm if tm.is_file() else None)
        return missing_history_suspects(
            txs, registered=(account_types_near(files[0]) if files
                             else {}),
            country=_country(_soft_settings(root)), journal_symbols=journal)
    except Exception:                               # noqa: BLE001
        return set()


def _late_rename_trades(root: Path) -> Dict[Tuple[str, str],
                                              Tuple[str, str]]:
    """(SYMBOL, account) -> (rename date, new symbol): the trades in an
    old ticker after its dated rename that no declaration resolves
    (lib/renames.unresolved_late, as the run warns): a short they make
    is no purchase missing from the files (backlog TJ-0442)."""
    from taxjson.lib.renames import unresolved_late
    try:
        rows = unresolved_late(root, load_config(root))
    except (ValueError, OSError, SystemExit):
        return {}
    out: Dict[Tuple[str, str], Tuple[str, str]] = {}
    for x in rows:
        k = (str(x.get("symbol") or "").upper(), str(x.get("account")))
        v = (str(x.get("rename_date") or "")[:10],
             str(x.get("renamed_to") or ""))
        if k not in out or v < out[k]:
            out[k] = v
    return out


def _write_missing_history_tt(root: Path, cache: Path,
                              rows: List[Dict[str, Any]], year: Any,
                              outside: bool, files: List[Path],
                              flag: str) -> None:
    """`find-missing-history --write-missing-history` (no FILE): one
    `OPENING <date> <SYMBOL> <qty> cost=unknown` line per suggested pair
    in inputs/<account>/missing_history.tt, dated the day before the
    account's first row, its quantity the units the run opens for it
    (the deepest shortage of the rows through the tax year's end; for a
    pair short only after it, of every row). Merged with the lines the
    account's .tt files have: never written twice; a symbol opened with
    another quantity is listed and left as it is."""
    from taxjson.lib import missing_history as MH
    prog = f"{_PROG} find-missing-history"
    if outside:
        rows_by = _year_short_rows(root, files, year)
        rows = [e for e in rows
                if (r := rows_by.get((e.get("symbol"), e.get("account"))))
                is not None and not r.year_listed]
    lines: List[Any] = []
    unsized: List[str] = []
    nodate: List[str] = []
    # Short, but not sized: two holdings renamed into one symbol (the
    # rows cannot tell which the missing units were; backlog TJ-0959).
    ambiguous: List[str] = []
    # A short a trade in an old ticker after its rename makes: its
    # purchase is in the files, so an OPENING line is never its fix
    # (backlog TJ-0442: "the rows never go short" said of it).
    _late = _late_rename_trades(root)
    late: List[str] = []
    for e in sorted(rows, key=lambda e: (str(e.get("account")),
                                         str(e.get("symbol")))):
        sym = str(e.get("symbol") or "").upper()
        acct = str(e.get("account") or "")
        if (sym, acct) in _late:
            d, new = _late[(sym, acct)]
            late.append(f"`RENAME {d} {sym} {new} late=fold` ({acct})")
            continue
        q = e.get(MH.QUANTITY_KEY)
        how = (f"the shortage of the rows through {e.get('_sized_through')}"
               if q and e.get("_sized_through") else "")
        if not q and e.get("_not_sized"):
            ambiguous.append(f"{sym} / {acct}: {e.get('_not_sized')}")
            continue
        if not q:
            q = e.get("_quantity_all_rows")
            how = "the shortage of every row"
        if not q or not sym or not acct:
            unsized.append(f"{sym} / {acct}")
            continue
        d = MH.default_opening_date(cache, acct)
        if d is None:
            nodate.append(f"{sym} / {acct}")
            continue
        lines.append(MH.TtLine(acct, sym, float(q), d,
                               f"find-missing-history: {how}"))
    try:
        plan = MH.plan_tt_write(root, lines)
    except MH.TtOpeningError as e:
        _die_input(f"{flag}: the accounts' OPENING cost=unknown lines "
                   f"cannot be read — fix them first; nothing was written:",
                   *str(e).splitlines())
    for ln in MH.tt_differ_lines(plan):
        _say("warning", f"{flag}: {ln}", prog=prog)
    if late:
        _say("warning", f"{flag}: not written: {len(late)} short(s) a "
             f"trade in an old ticker after its rename makes",
             "The purchase is in your files under the old ticker: "
             "declare the late trades with a .tt line, not an opening — "
             + "; ".join(late) + " (`late=separate` when it is another "
             "security; `tjs renames` prints the lines).", prog=prog)
    if ambiguous:
        _say("warning", f"{flag}: not written: {len(ambiguous)} sale(s) "
             f"with no purchase of a symbol two holdings were renamed "
             f"into", *ambiguous, prog=prog)
    if unsized or nodate:
        _say("note", f"{flag}: not written: "
             + ", ".join(unsized + nodate),
             "No shortage to size (the rows never go short), or no books "
             "for the account (run `tjs run`).", prog=prog)
    if not plan.n_add:
        _say("note", f"nothing to add: "
             + (f"{len(plan.same)} line(s) already there"
                if plan.same else "no line to write for the pair(s) above"
                if late or unsized or nodate or ambiguous or plan.differ
                else "no sale with no purchase in your files"),
             prog=prog)
        return
    from taxjson.lib.safe_write import OutsideLinkError
    try:
        written = MH.apply_tt_plan(plan)
    except OutsideLinkError as e:
        _die_input(f"{flag}: {e}")
    except OSError as e:
        _die_input(f"{flag}: cannot write: {e}")
    # OPENING cost=unknown lines: read from v0.27.0 (lib/requires); with
    # shared exports by every year.
    _raise_requirements(root, ("missing_history_tt",),
                        all_years=_PL.shared_inputs(root), quiet=True)
    # Wrapped at the house width, as the --write-purchases note is
    # (docs/output-style.md, Width; backlog TJ-0175).
    _notes = [f"Wrote {len(plan.add[p.parent.name])} OPENING cost=unknown "
              f"line(s) to {_PL.shown(p, root)} (sales with no purchase in "
              f"your files)" for p in written]
    _notes.append(("These inputs are shared by every year's project: the "
                   "lines apply to every year. "
                   if _PL.shared_inputs(root) else "")
                  + "Review each line: remove any that is a real short "
                  "position, and give the units held before your data and "
                  "the date (before the first sale they cover). `tjs "
                  "run` reads them.")
    for _note in _notes:
        for _ln in _out_wrap(_note, file=sys.stderr):
            print(_ln, file=sys.stderr)


def _refuse_stale_books_write(root: Path, flag: str) -> None:
    """Exit 1 before find-missing-history writes lines from books older
    than the inputs (the last full run's record of what it read, as
    run-clean compares it): a purchase just added to a .tt file is not
    in them, so the line written for its sale opened a phantom position
    (backlog TJ-0077). The files the write flags change themselves do
    not count: missing_history.tt (merged by the write, which reads it)
    and taxjson.toml (the write pins requires_taxjson there), so a
    second write before a run still merges. The banner says the rest,
    and every run-state problem."""
    try:
        from taxjson.lib.checklist import (FINGERPRINT_VERSION,
                                           _load_fingerprint_doc,
                                           fingerprint_changes,
                                           input_fingerprint)
        cfg = _soft_config(root)
        doc = _load_fingerprint_doc(root)
        if not doc or doc.get("version") != FINGERPRINT_VERSION:
            return
        changed = fingerprint_changes(doc["files"],
                                      input_fingerprint(root, cfg))
    except Exception:                                   # noqa: BLE001
        return
    stale = [k for k in changed
             if k.rsplit("/", 1)[-1] not in ("missing_history.tt",
                                             "taxjson.toml")]
    if stale:
        _die(f"{flag}: the books in work/ are older than the inputs "
             f"(changed since the last full run: {', '.join(stale[:3])}"
             f"{' ...' if len(stale) > 3 else ''})",
             "Lines written from them could open a position the inputs "
             "already fix (a purchase just added to a .tt file). Run "
             "`tjs run` first; nothing was written.")


def _is_configured_account(root: Path, name: str) -> bool:
    """`name` is an account of the project's taxjson.toml."""
    try:
        accts = _PL.read_config_soft(root).get("accounts") or {}
    except Exception:                               # noqa: BLE001
        return False
    return isinstance(accts, dict) and name in accts


def _refuse_missing_history_file(name: str) -> None:
    """Exit 2: `--write-missing-history FILE` (the JSON candidates
    before v0.27.0) — the flag writes .tt lines and takes no FILE."""
    _die_input(f"--write-missing-history takes no FILE ({name}): it writes "
               f"dated .tt lines (OPENING <date> <SYMBOL> <qty> "
               f"cost=unknown) into inputs/<account>/missing_history.tt, "
               f"merged with the lines there — missing_history.json is no "
               f"longer read.")


def cmd_find_missing_history(args: argparse.Namespace) -> None:
    """Convenience wrapper over `taxjson-missing-history`: resolve the account
    base file(s) from the project and default the year from taxjson.toml."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    # --gen-phantoms: the old spelling of --write-missing-history (hidden,
    # still accepted with a note).
    if getattr(args, "write_missing_history", None) is None:
        args.write_missing_history = None
    # A FILE after the flag (the JSON candidates before v0.27.0; the old
    # --gen-phantoms FILE) reads as the account: refused with a word.
    # A configured account is never a FILE: an account name may hold a
    # period (`[accounts."margin.old"]`), which read as a suffix
    # (backlog TJ-0816).
    _file = getattr(args, "gen_phantoms", None) or (
        args.account if args.write_missing_history and args.account
        and (Path(args.account).suffix or "/" in args.account)
        and not _is_configured_account(root, args.account) else None)
    if _file:
        _refuse_missing_history_file(_file)
    if (getattr(args, "write_purchases", None) is not None
            and args.write_missing_history is not None):
        _die_input("--write-purchases and --write-missing-history write "
                   "different files: run them one at a time.")
    # Per-account full-history base files only — skip the raw/native
    # derivatives and the combined sheltered file (its accounts are
    # already covered individually).
    all_files = _project_base_files(cache)
    if args.account:
        f = cache / f"{args.account}_base.json"
        if not f.exists():
            _die_input(f"no {f.name} in {cache} (run `tjs run` first, "
                       f"or check the name).")
        files = [f]
    else:
        files = all_files
        if not files:
            sys.exit(exit_text(f"tjs find-missing-history: no base files in {cache} "
                               f"(run `tjs run` first)."))
    outside = bool(getattr(args, "outside_year", False))
    if outside and args.write_missing_history is None:
        _die_input("--outside-year goes with --write-missing-history (it "
                   "writes the pairs that do not bear on the tax year).")
    if outside and args.all_history:
        _die_input("--outside-year and --all-history choose different "
                   "pairs: give one.")

    year = args.year
    if year is None:
        year = _soft_settings(root).get("year")
    if (args.write_missing_history is not None
            or getattr(args, "write_purchases", None) is not None):
        _refuse_stale_books_write(
            root, "--write-missing-history"
            if args.write_missing_history is not None
            else "--write-purchases")

    # --write-missing-history: instead of the diagnostic report, write
    # the sales with no purchase in the files (the truncated-history rows
    # — positions that go negative, the subset an opening balance
    # actually fixes) as dated .tt lines (inputs/<account>/
    # missing_history.tt: OPENING <date> <SYMBOL> <qty> cost=unknown —
    # lib/missing_history). $0-cost corp-action rows are intentionally
    # NOT emitted; those need a merger/spinoff basis, not a synthetic
    # opening balance. The candidates (incl. year-scoping and each one's
    # size) come from `taxjson-gains --suggest-missing-history`, which
    # takes one base file, so we run it per account and merge them
    # (keyed by symbol+account).
    if args.write_missing_history is not None:
        import json
        import tempfile
        _flag = ("--write-missing-history --outside-year" if outside
                 else "--write-missing-history")
        if outside and not year:
            _die_input(f"{_flag}: no tax year — set [settings] year in "
                       f"taxjson.toml or pass --year.")

        merged: Dict[Tuple[str, str], dict] = {}
        for f in files:
            with tempfile.NamedTemporaryFile(
                    "r", suffix=".json", delete=False) as tmp:
                tmp_path = tmp.name
            cmd = _cmd("taxjson-gains") + ["--suggest-missing-history",
                                           tmp_path]
            # The project's jurisdiction, as the pipeline passes it
            # (taxjson-gains requires it). (Sheltered books
            # stay in: a short in a registered account is the MOST
            # certain missing purchase, and `run` applies the file to every
            # account's gains stage.)
            cmd += ["--country", _country(_soft_settings(root))]
            # The project's date basis, as the report and the gains
            # stage year-scope a sale: without it the helper fell back
            # to the country default, so a trade-dated Canadian
            # project's Dec 31 sale settling in January was filtered
            # out as another year's though the report said AFFECTS
            # (backlog TJ-0316).
            cmd += ["--tax-date", _tax_date(_soft_settings(root))]
            # The project's written-option timing and income dating,
            # as the gains stage runs (re-audit A2-1361: the standalone
            # close-timing default and its note leaked in here).
            cmd += option_timing_flags(_soft_settings(root))
            cmd += income_dating_flags(_soft_settings(root))
            if year:
                cmd += ["--year", str(year)]
            if args.include_options:
                cmd += ["--include-options-in-suggestions"]
            if args.all_history or outside:
                cmd += ["--all-history"]
            cmd += [str(f)]
            # Capture the inner tool's stderr and re-emit everything except
            # the lines referencing the temp file (deleted below; our merged
            # summary replaces them). Devnulling ALL of it swallowed the
            # "Filtered N candidate(s)... Use --all-history" warning — the
            # only signal that a year-scoped run dropped a pair.
            from taxjson.lib.dispatch import run_cmd as _run_cmd
            proc = _run_cmd(cmd, capture_output=True)
            if proc.stdout:
                sys.stdout.write(proc.stdout)
            for line in (proc.stderr or "").splitlines():
                if tmp_path in line:
                    continue
                if line.strip():
                    print(f"  [{f.name}] {line}", file=sys.stderr)
            if proc.returncode != 0:
                sys.exit(exit_text(f"tjs find-missing-history {_flag}: "
                                   f"taxjson-gains failed on {f.name} "
                                   f"(exit {proc.returncode})."))
            try:
                entries = json.loads(Path(tmp_path).read_text(encoding="utf-8"))
            except (OSError, ValueError):
                entries = []
            finally:
                Path(tmp_path).unlink(missing_ok=True)
            for e in entries:
                merged[(e.get("symbol"), e.get("account"))] = e

        # A short that a same-day journal leg covers (Norbert's gambit,
        # RBC's ordinal times put the sale first) is not missing
        # history: an entry for it pulled the sale off Schedule 3 and
        # invented the shares (audit A2-0309). taxjson-gains knows no
        # journal, so the journal symbols (a JOURNAL line, a join of the
        # run, a broker journal of the exports — lib/missing_history.
        # walk_journal_symbols) are re-checked here with the walk that
        # knows them.
        _tm_path = _PL.ticker_map_path(root)
        if merged:
            from taxjson.lib.missing_history import (account_types_near,
                                                      detect_missing_history,
                                                      walk_journal_symbols)
            from taxjson.lib.core import load_transactions
            _journal = walk_journal_symbols(
                cache, _tm_path if _tm_path.is_file() else None)
            _js = {k for k in merged
                   if str(k[0] or "").upper() in _journal}
            if _js:
                _txs = []
                for f in files:
                    try:
                        _txs.extend(load_transactions(f))
                    except (OSError, ValueError):
                        pass
                _still = {(c.symbol, c.account) for c in detect_missing_history(
                    _txs, include_options=True, include_broker_shorts=True,
                    registered_accounts=(account_types_near(files[0])
                                         or None) if files else None,
                    journal_symbols=_journal)}
                for k in sorted(_js - _still):
                    del merged[k]
                    print(f"  left out {k[0]} / {k[1]}: its short is the "
                          f"same-day leg of a journal between the "
                          f"security's lines (Norbert's gambit), not "
                          f"missing history.",
                          file=sys.stderr)

        rows = list(merged.values())
        _write_missing_history_tt(root, cache, rows, year, outside,
                                  all_files or files, _flag)
        return

    # Every book is read (a Canadian ACB pool spans the taxable
    # accounts: lib/missing_history.year_pool); ACCOUNT narrows the
    # report with --account.
    cmd = _cmd("taxjson-missing-history") + [
        str(f) for f in (all_files if args.account and files[0] in all_files
                         else files)]
    if (args.account and files[0] in all_files and len(all_files) > 1
            and getattr(args, "write_purchases", None) is None):
        cmd += ["--account", args.account]
    if getattr(args, "write_purchases", None) is not None:
        # Drafts of purchase lines from the broker's cost evidence
        # (tax-logic CA-ACB-15 / US-BASIS-08): the tool writes them
        # beside the account's inputs, as .tt.txt the run never reads.
        cmd += ["--write-purchases", args.write_purchases]
        if args.force:
            cmd += ["--force"]
        if args.all_history:
            cmd += ["--all-history"]
        if args.account:
            cmd += ["--account", args.account]
    if not args.account:
        # The glob above sees only books that exist: a CONFIGURED
        # account whose book was never built (a failed parse, deferred
        # elections) was skipped silently and the checklist marked the
        # step done (2026-09 audit S047-18). Accounts `run` skipped for
        # having no inputs at all are expected to have none.
        _have = {f.name[: -len("_base.json")] for f in files}
        _quiet = _accounts_skipped_for_no_inputs(root)
        for _n in sorted((_soft_config(root).get("accounts") or {})):
            if _n not in _have and _n not in _quiet:
                emit_line(f"tjs find-missing-history: note: account {_n} "
                          f"has no work/{_n}_base.json — not checked (run "
                          f"`tjs run`).", file=sys.stderr)
                cmd += ["--unchecked-account", _n]
    if year:
        cmd += ["--year", str(year)]
    if args.include_options:
        cmd += ["--include-options"]
    _mh_arg = _missing_history_arg(root)
    if _mh_arg is not None:
        cmd += ["--missing-history", str(_mh_arg)]
    if (_PL.ticker_map_path(root)).exists():
        # Name the broker's ticker of a renamed symbol (S049-01).
        cmd += ["--ticker-map", str(_PL.ticker_map_path(root))]
    if _details(args) and getattr(args, "write_purchases", None) is None:
        cmd += ["--details"]
    if getattr(args, "write_purchases", None) is None:
        for (_s, _a), (_d, _n) in sorted(_late_rename_trades(root).items()):
            # A short a late trade in a renamed ticker makes is that
            # rename's .tt line to add, not a purchase (TJ-0442).
            cmd += ["--late-rename", _a, _s, _d, _n]
    if (cache / IN_KIND_FILE).is_file() and getattr(
            args, "write_purchases", None) is None:
        # A short an in-kind withdrawal NOT booked explains is that
        # move's INKIND line to add, not a purchase (backlog TJ-0439).
        cmd += ["--in-kind", str(cache / IN_KIND_FILE)]
    _exec_tool(cmd)


def cmd_fees_sum(args: argparse.Namespace) -> None:
    """Convenience wrapper over `taxjson-fees-sum`: trading-fee report by brokerage
    (converted to the base currency), reading the parsed per-broker JSONs in
    work/. Resolves cache / base currency / rates from the project. Like the
    other roll-ups it takes an optional PERIOD window (30d/6w/…, wired to
    `taxjson-fees-sum --since`), defaulting to the tax year; a lone non-period
    positional is read as an account (its per-broker files only)."""
    root = Path(args.dir).resolve()
    cache = root / "work"
    if not cache.exists():
        _die("no work/ — run `tjs run` first")
    _require_books(root, also=("*_*.json",))
    settings = _soft_settings(root)

    period, account = _lone_positional(root, args.period, args.account)

    cmd = _cmd("taxjson-fees")
    if account:
        # Scope to one account by feeding only its parsed per-broker files;
        # non-broker JSONs (…_base.json etc.) are skipped by taxjson-fees-sum.
        # Exclude files that actually belong to a LONGER-named sibling
        # account sharing this prefix (accounts `margin` and `margin_us`:
        # the glob "margin_*.json" also matches margin_us_ib.json, leaking
        # the sibling's fees into this account's total).
        accounts_cfg = _soft_config(root).get("accounts") or {}
        siblings = [a for a in accounts_cfg
                    if a != account and a.startswith(f"{account}_")]
        files = sorted(
            f for f in cache.glob(f"{account}_*.json")
            if not any(f.name.startswith(f"{sib}_") for sib in siblings))
        if not files:
            _die_input(f"no files for account {account!r} in work/ — run "
                       f"`tjs run` first, or check the name")
        cmd += [str(f) for f in files]
    else:
        cmd += ["--cache", str(cache)]
        _warn_accounts_without_books(root, _discover_tx_accounts(cache),
                                     "fees-sum", "transaction file")

    tok = (period or "").strip().lower()
    if period and _YEAR_TOKEN_RE.fullmatch(tok):         # literal year window
        cmd += ["--year", tok]
    elif period and tok in _TAX_YEAR_TOKENS:             # explicit tax_year
        year = settings.get("year")
        if year:
            cmd += ["--year", str(year)]
    elif period and tok not in ("all", "max"):           # look-back window
        # Through today, as every period view (backlog TJ-0329).
        cmd += ["--since", _tx_period_cutoff(period).isoformat(),
                "--until", _period_end(period)]
    elif not period:                                     # default: tax year
        year = settings.get("year")
        if year:
            cmd += ["--year", str(year)]

    # taxjson-fees-sum needs --rates alongside --to; pass both only when the rate
    # file exists, else report native per-brokerage amounts (no conversion).
    rates = cache / "to_base.csv"
    if rates.exists():
        cmd += ["--to", _base(settings),
                "--rates", str(rates)]
    if args.by_account:
        cmd += ["--by-account"]
    if (_PL.ticker_map_path(root)).exists():
        # DELETE'd symbols' fees, like the books (S038-11).
        cmd += ["--ticker-map", str(_PL.ticker_map_path(root))]
    if args.json:
        cmd += ["--json"]
    elif not _details(args):
        # Essentials first (docs/output-style.md).
        cmd += ["--brief"]
    _exec_tool(cmd)


def _backup_config(cfg: Path) -> str:
    """Copy taxjson.toml to taxjson.toml.bak before it is rewritten
    (init --force, format --write) and return the backup's name. Never
    overwrite an earlier backup: a second --force (fixing the --country)
    replaced the only copy of the user's config with the first template
    (R1-255) — the next free taxjson.toml.bakN is used instead, the same
    numbering as fetch's .bak files; an identical existing backup is
    reused; a symlink at a .bak name is never written through
    (lib/safe_write.backup_copy, security review M1)."""
    from taxjson.lib.safe_write import backup_copy
    return backup_copy(cfg).name


def cmd_format(args: argparse.Namespace) -> None:
    """`tjs format [--write [--no-backup] | --check]`: re-render
    taxjson.toml into the country's template (lib/config_template):
    every key in its place, set ones active, the rest commented with
    their description and default; the user's values, unknown keys and
    comments kept. The parsed configuration before and after must be
    identical or nothing is written. Default: print a unified diff."""
    import difflib
    from taxjson.lib.config_template import FormatError, format_config
    if args.no_backup and not args.write:
        _die_input("--no-backup applies only with --write")
    root = Path(args.dir).resolve()
    cfg = root / "taxjson.toml"
    if not cfg.exists() and not cfg.is_symlink():
        _die_input(f"no taxjson.toml in {root}",
                   "Run `tjs init` first.")
    text = _read_config_text(cfg)
    try:
        res = format_config(text)
    except FormatError as e:
        _die_input(f"taxjson.toml: {e}")
    if res.unrecognised:
        _say("note", f"kept {len(res.unrecognised)} key(s) the template "
             f"does not know, flagged in the file: "
             f"{', '.join(res.unrecognised)}", prog=f"{_PROG} format")
    if res.notes_lines:
        _say("note", f"{res.notes_lines} comment line(s) could not be "
             f"attached to a setting"
             + ("" if _details(args) else
                ": kept in the \"Your notes\" block at the end"),
             *(["They are kept in the \"Your notes\" block at the end of "
                "the file."] if _details(args) else []),
             prog=f"{_PROG} format")
    if not res.changed:
        print("taxjson.toml is already formatted.")
        return
    if args.check:
        _say("warning", "taxjson.toml is not formatted",
             "`tjs format` shows the changes, `tjs format "
             "--write` applies them.", prog=f"{_PROG} format")
        sys.exit(1)
    if not args.write:
        sys.stdout.writelines(difflib.unified_diff(
            text.splitlines(keepends=True),
            res.text.splitlines(keepends=True),
            fromfile="taxjson.toml", tofile="taxjson.toml (formatted)"))
        if _details(args):
            _say("note", "dry run: nothing written",
                 "`tjs format --write` applies this; your "
                 "configuration loads the same either way.",
                 prog=f"{_PROG} format")
        else:
            _say("note", "dry run: nothing written — `tjs format "
                 "--write` applies it (your settings load the same)",
                 prog=f"{_PROG} format")
        return
    from taxjson.lib.safe_write import link_outside, write_atomic
    target = link_outside(cfg, root)
    if target is not None:
        _die_input(f"taxjson.toml is a symlink to {target}, outside the "
                   f"project",
                   "Format the file it points at in its own project, or "
                   "replace the link with the file.")
    from taxjson.lib.cli_diag import cannot_write
    from taxjson.lib.safe_write import refuse_read_only
    try:
        # A taxjson.toml made read-only is refused before the backup is
        # taken (TJ-0107); a folder that cannot be written names
        # taxjson.toml and the folder, not the backup file (TJ-0056).
        # A taxjson.toml that is a link inside the project stays a
        # link: its target is written (backlog TJ-0937; replacing the
        # link left the target, which the user edits, unformatted and
        # no longer read).
        real = cfg.resolve() if cfg.is_symlink() else cfg
        refuse_read_only(real)
        bak = None if args.no_backup else _backup_config(cfg)
        write_atomic(real, res.text, suffix=".format.part", keep_mode=True)
    except OSError as e:
        _head, _fix = cannot_write(_config_shown(cfg), e, cfg)
        _die_input(_head, " ".join(x for x in (_fix, "Nothing was changed.")
                                   if x))
    print("formatted taxjson.toml"
          + (f" (previous version: {bak})" if bak else ""))


def cmd_format_map(args: argparse.Namespace) -> None:
    """`tjs format-map [--write [--no-backup] | --check]`: lay
    ticker.map out in keyword groups (lib/ticker_map_format): a short
    header, then Spellings, Listings of one security, Clean-up and
    Lookups, each under its heading, the user's order kept in a group, a
    comment directly above a line moved with it, spacing normalised,
    exact duplicates dropped, a line taxjson cannot use kept as written
    in an Unrecognized group. Dated events leave the map (v0.24): a
    `JOURNAL A B` line becomes `TOBASE A B`, and each dated `RENAME OLD
    NEW YYYY-MM-DD [late=...]` moves, with its comments, to a .tt line
    `RENAME YYYY-MM-DD OLD NEW [late=...]` in inputs/<account>/renames.tt
    (lib/dated_events.home_accounts: one per account kind whose books
    hold the symbols). The parsed map before and after (plus the moved
    lines) must mean the same, every comment be kept, and the run book
    the same rename events in every account after the move as before it
    — the project's .tt lines included (lib/dated_events.plan_migration)
    — or nothing is written (exit 2, naming the lines). Every target is
    checked before the first write (a link to outside the project — of
    ticker.map, a .tt file or its inputs/<account> folder — is refused);
    the .tt files are written first, a block they already hold is not
    added again, and a failed write says what was already written.
    Default: print a unified diff, the .tt additions and the lines per
    group; --check fails while the map is not formatted, a migration is
    pending, or `tjs run` refuses the map."""
    import difflib
    from taxjson.lib.cli_diag import read_text_utf8
    from taxjson.lib.ticker_map_format import FormatError, format_map
    prog = f"{_PROG} format-map"
    if args.no_backup and not args.write:
        _die_input("--no-backup applies only with --write")
    root = Path(args.dir).resolve()
    # The .tt files it moves lines to may be in the shared inputs folder
    # (lib/project_layout): their links are judged against the folder
    # holding the year folders.
    _data = _PL.write_boundary(root)
    tm = _PL.ticker_map_path(root)
    if not tm.exists() and not tm.is_symlink():
        _die_input(f"no ticker.map in {root}",
                   "`tjs init` writes one; the run needs none.")
    if tm.is_dir():
        _die_input(f"{tm} is a directory, not a file")
    try:
        text = read_text_utf8(tm)
    except OSError as e:
        _die_input(f"cannot read {tm}: {e.strerror or e}")
    try:
        res = format_map(text, migrate=True)
    except FormatError as e:
        _die_input(f"ticker.map: {e}", "Nothing was written.")
    if res.problems:
        _n_bad = res.counts.get("Unrecognized", 0)
        _say("warning", f"{len(res.problems)} ticker.map problem(s): "
             f"`tjs run` refuses the map until each is fixed",
             *[f"- {m}" for m in res.problems],
             *([f"The {_n_bad} line(s) taxjson cannot use are kept as "
                f"written in the \"Unrecognized\" group."] if _n_bad
               else []),
             *(["Its dated events are moved out once the map has no "
                "problem."] if res.problems else []), prog=prog)
    if res.duplicates:
        _say("note", f"dropped {len(res.duplicates)} exact duplicate "
             f"line(s)",
             *[f"line {n}: {ln}" for n, ln in res.duplicates], prog=prog)
    if res.retired:
        _say("note", f"{res.retired} line(s) of a removed feature are in "
             f"the \"Retired\" group", "taxjson ignores them; delete "
             "them.", prog=prog)
    _format_map_header_notes(res, prog)
    # Where each moved RENAME goes (a .tt RENAME applies to every account
    # of its kind holding the old symbol), and whether the run would book
    # the same events after the move (lib/dated_events.plan_migration).
    from taxjson.lib import dated_events as DE
    plan = DE.MigrationPlan()
    pending = res.migration_pending
    if args.check:
        # --check reports; it plans nothing (a project without accounts
        # can still be checked). It fails while the map is not formatted,
        # a migration is pending, or `tjs run` refuses the map.
        if pending:
            _say("warning", f"ticker.map holds dated events to migrate: "
                 f"{len(res.journals)} JOURNAL line(s) (to TOBASE), "
                 f"{len([m for m in res.moved if not m.commented])} dated "
                 f"RENAME line(s) (to a .tt file)",
                 "`tjs format-map` shows the changes, `tjs "
                 "format-map --write` applies them.", prog=prog)
        elif res.changed:
            _say("warning", "ticker.map is not formatted",
                 "`tjs format-map` shows the changes, `tjs "
                 "format-map --write` applies them.", prog=prog)
        else:
            print("ticker.map is already formatted.")
        if res.problems:
            _say("warning", f"`tjs run` refuses this ticker.map: "
                 f"{len(res.problems)} problem(s), listed above",
                 "Fix each line, then check again.", prog=prog)
        if pending or res.changed or res.problems:
            sys.exit(1)
        return
    if res.moved:
        cfg = load_config(root)
        accounts = cfg.get("accounts") or {}
        if not accounts:
            _die_input("ticker.map's dated RENAME lines move to an "
                       "account's .tt file, and taxjson.toml has no "
                       "account", "Nothing was written.")
        plan = DE.plan_migration(root, accounts, text, res.moved)
        if plan.refused:
            _die_input("moving ticker.map's dated RENAME lines to .tt "
                       "files would change the books — nothing was "
                       "written",
                       *[f"- {m}" for m in plan.refused],
                       *[f"- {m}" for m in plan.twins],
                       "Make the map line and the .tt line(s) of each "
                       "change say the same (or delete one), run "
                       "`tjs run`, then format the map again. An "
                       "account without books yet (no work/<account>_"
                       "base.json) is compared on every change of its "
                       "kind: run `tjs run` first.")
    if not res.changed and not pending:
        print("ticker.map is already formatted.")
        return
    counts = ", ".join(f"{g} {n}" for g, n in res.counts.items()
                       if n or g not in ("Retired", "Unrecognized",
                                         "Dated events"))
    # What each .tt file gets: a block already in the file (an earlier
    # --write, a restored backup) is not added again.
    from taxjson.lib.safe_write import (OutsideLinkError, link_outside,
                                        write_user_file)
    texts: Dict[str, Tuple[str, str, int]] = {}
    for rel, blocks in sorted(plan.adds.items()):
        p = _PL.project_path(root, rel)
        try:
            cur = read_text_utf8(p) if p.is_file() else ""
        except OSError as e:
            _die_input(f"cannot read {rel}: {e.strerror or e}",
                       "Nothing was written.")
        from taxjson.bin.taxjson_convert_tt import tt_lines
        have = [ln.strip() for ln in tt_lines(cur)]
        lines: List[str] = []
        n_rules = 0
        for block in blocks:
            body = [ln.strip() for ln in block]
            if _block_in(body, have):
                continue
            last = body[-1] if body else ""
            if last.startswith(("RENAME", "# RENAME")) and last in have:
                # The line is there (its comments edited since): only the
                # comments that are not.
                block = [ln for ln in block[:-1] if ln.strip() not in have]
            lines.extend(block)
            n_rules += sum(1 for ln in block if ln.startswith("RENAME"))
        if not lines:
            continue
        new_txt = (cur + ("" if not cur or cur.endswith("\n") else "\n")
                   + ("\n" if cur.strip() else "")
                   + ("" if cur.strip() else DE.RENAMES_TT_HEAD)
                   + "\n".join(lines) + "\n")
        texts[rel] = (cur, new_txt, n_rules)
    if not args.write:
        sys.stdout.writelines(difflib.unified_diff(
            text.splitlines(keepends=True),
            res.text.splitlines(keepends=True),
            fromfile="ticker.map", tofile="ticker.map (formatted)"))
        for rel, (cur, new_txt, _n) in sorted(texts.items()):
            print(f"--- {rel}{'' if cur else ' (new file)'}")
            print(f"+++ {rel} (with the dated events from ticker.map)")
            for ln in new_txt[len(cur):].lstrip("\n").splitlines():
                print(f"+{ln}")
        _migration_notes(res, plan.homes, plan.skipped, prog,
                         plan.twins, root, text)
        _say("note", f"lines per group: {counts}", prog=prog)
        _say("note", "dry run: nothing written",
             "`tjs format-map --write` applies this; the books are "
             "the same either way.", prog=prog)
        return
    # Every target is checked before anything is written: ticker.map and
    # each .tt file inside the project (a link — of the file or of its
    # inputs/<account> folder — pointing outside is refused).
    targets = [("ticker.map", tm)] + [(rel, _PL.project_path(root, rel))
                                      for rel in texts]
    for rel, p in targets:
        _out = link_outside(p, root if rel == "ticker.map" else _data)
        if _out is None and rel != "ticker.map":
            _par = p.parent
            while not _par.exists() and _par != _data:
                _par = _par.parent
            try:
                _par.resolve().relative_to(_data.resolve())
            except ValueError:
                _out = _par.resolve()
        if _out is not None:
            _die_input(f"{rel} would be written through a link to "
                       f"{_out}, outside the project — nothing was "
                       f"written",
                       "Replace the link with the folder or file it "
                       "points at, or migrate the lines by hand.")
    # Two accounts' .tt files that are one file (links to the same
    # target inside the project): each text was made from the file as
    # it is, so the second write dropped the first one's lines (backlog
    # TJ-0938). Refused before anything is written.
    _by_real: Dict[Path, List[str]] = {}
    for rel in texts:
        _by_real.setdefault(_PL.project_path(root, rel).resolve(),
                            []).append(rel)
    _alias = [rels for rels in _by_real.values() if len(rels) > 1]
    if _alias:
        _die_input(f"{' and '.join(sorted(_alias[0]))} are one file (a link "
                   f"to the same target) — nothing was written",
                   "Each account's dated RENAME lines go in its own .tt "
                   "file: replace the links with files of their own, "
                   "then format the map again.")
    # The .tt files first: a map without its moved lines must never be
    # left behind without them.
    written: List[str] = []

    def _fail(what: str, e: BaseException, path: Path) -> None:
        # The file named from where the command was run, and the fix
        # (`chmod u+w` it or its folder): the read-only reason named
        # the bare file name, wrong with -C from elsewhere (backlog
        # TJ-0219).
        from taxjson.lib.cli_diag import cannot_write
        if isinstance(e, OSError):
            head, fix = cannot_write(_config_shown(path), e, path)
        else:
            head, fix = f"cannot write {what}: {e}", ""
        _die_input(head, *([fix] if fix else []),
                   ("Already written: " + ", ".join(written)
                    + " — ticker.map is unchanged; re-running "
                    "`tjs format-map --write` does not add those "
                    "lines twice.") if written else "Nothing was written.")
    for rel, (cur, new_txt, n_rules) in sorted(texts.items()):
        p = _PL.project_path(root, rel)
        try:
            p.parent.mkdir(parents=True, exist_ok=True)
            write_user_file(p, new_txt, _data,
                            suffix=".format.part",
                            backup=bool(cur) and not args.no_backup)
        except (OutsideLinkError, OSError) as e:
            _fail(rel, e, p)
        written.append(rel)
        print(f"wrote {_PL.shown(p, root)} ({n_rules} ticker change(s) "
              f"from ticker.map)")
        _shared_inputs_note(root, p, prog)
    try:
        bak = write_user_file(tm, res.text, root,
                              suffix=".format.part",
                              backup=not args.no_backup)
    except (OutsideLinkError, OSError) as e:
        _fail("ticker.map", e, tm)
    print("formatted ticker.map"
          + (f" (previous version: {bak.name})" if bak else ""))
    _migration_notes(res, plan.homes, plan.skipped, prog, plan.twins, root,
                     text)
    _say("note", f"lines per group: {counts}", prog=prog)


def _format_map_header_notes(res, prog: str) -> None:
    """format-map's Info lines on the map's comments
    (lib/ticker_map_format.FormatResult): an earlier taxjson header
    replaced by the current one, one kept because the user edited it, and
    the user's comments that still describe the legacy dated events as map
    rules (kept: they are the user's)."""
    if res.regenerated:
        _say("note", f"{res.regenerated} comment line(s) of an earlier "
             f"taxjson header are replaced by the current header",
             prog=prog)
    n = len(res.edited_headers)
    if n:
        _say("note", ("a comment block looks" if n == 1 else
                      f"{n} comment blocks look")
             + " like an old taxjson header you edited — kept; delete "
             + ("it if it no longer applies" if n == 1
                else "them if they no longer apply"),
             *[f"- {ln}" for ln in res.edited_headers], prog=prog)
    n = len(res.dated_comments)
    if n:
        _say("note", f"{n} comment block(s) still describe JOURNAL or a "
             f"dated RENAME as a ticker.map rule",
             *[f"- {ln}" for ln in res.dated_comments],
             "A journal or a ticker change on a date is a .tt line of an "
             "account now (docs/settings.md, \".tt files\"); your comments "
             "are kept: edit them if they no longer apply.", prog=prog)


def _journal_gaps(root: Path, map_text: str,
                  res) -> List[Tuple[str, str, str, float]]:
    """(account, FROM, TO, qty) for each legacy JOURNAL pair a format-map
    migration rewrites whose listings the last run's holdings
    (reports/<acct>_holdings.toml) show with opposite signs: the long one
    is FROM, the quantity the smaller of the two."""
    if not res.journals:
        return []
    from taxjson.bin.taxjson_ticker_map import _parse_map_text
    try:
        pairs = dict(_parse_map_text(map_text, "ticker.map")[0].journal)
    except ValueError:
        return []
    from taxjson.lib.tomlcompat import tomllib
    out = []
    for hp in sorted((root / "reports").glob("*_holdings.toml")):
        try:
            doc = tomllib.loads(hp.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        qty: Dict[str, float] = {}
        for h in doc.get("holding") or []:
            if isinstance(h, dict):
                try:
                    qty[str(h.get("symbol") or "").upper()] = \
                        qty.get(str(h.get("symbol") or "").upper(), 0.0) \
                        + float(h.get("quantity") or 0.0)
                except (TypeError, ValueError):
                    continue
        acct = hp.name[:-len("_holdings.toml")]
        for a, b in sorted(pairs.items()):
            qa, qb = qty.get(a, 0.0), qty.get(b, 0.0)
            if qa * qb < 0:
                frm, to = (a, b) if qa > 0 else (b, a)
                out.append((acct, frm, to, min(abs(qa), abs(qb))))
    return out


def _block_in(block: List[str], have: List[str]) -> bool:
    """`block` (stripped lines) appears, in order and contiguous, in
    `have`."""
    n = len(block)
    if not n:
        return True
    return any(have[i:i + n] == block for i in range(len(have) - n + 1))


def _migration_notes(res, homes: List[str], skipped: List[str],
                     prog: str, twins: List[str] = (),
                     root: Optional[Path] = None,
                     map_text: str = "") -> None:
    """The migration's Info lines (format-map): what moved where, the
    .tt lines that declare a moved change differently (to reconcile),
    and a `.tt JOURNAL` line for each migrated JOURNAL whose two
    listings the holdings show long and short (M7)."""
    if res.journals:
        _say("note", f"{len(res.journals)} JOURNAL line(s) rewritten as "
             f"TOBASE (what they mean now)",
             "A journal on a date is a .tt line of the account: `JOURNAL "
             "<date> <FROM> <TO> <qty>` (only needed when the broker's "
             "export lacks the journal's rows).", prog=prog)
        for acct, frm, to, qty in (_journal_gaps(root, map_text, res)
                                   if root else ()):
            _say("warning", f"{acct}: the holdings show {frm} long and "
                 f"{to} short by {qty:g} — a journal the export lacks",
                 "The tax books join the two listings (TOBASE); the "
                 "holdings view moves units only by a journal's rows. "
                 "Add to a .tt file of the account (the journal's date):",
                 f"  JOURNAL <date> {frm} {to} {qty:g}", prog=prog)
    if twins:
        _say("note", f"{len(twins)} moved line(s) repeat a .tt line of the "
             f"same change written differently (booked as one event)",
             *twins, prog=prog)
    if homes:
        _say("note", f"{len(homes)} dated RENAME line(s) moved to a .tt "
             f"file (a .tt RENAME applies to every account of its kind — "
             f"securities or crypto — holding the old symbol)", *homes,
             prog=prog)
    if skipped:
        _say("note", f"{len(skipped)} dated RENAME line(s) already "
             f"declared in a .tt file: removed from ticker.map", *skipped,
             prog=prog)
    if res.dropped_examples:
        _say("note", f"dropped {len(res.dropped_examples)} switched-off "
             f"example(s) an earlier `tjs init` wrote",
             *res.dropped_examples, prog=prog)


def _year_accounts(d: Path) -> List[str]:
    """The [accounts.*] names of the year project `d` ([] when its
    taxjson.toml cannot be read: it is not judged here)."""
    try:
        doc = _PL.parse_toml((d / _PL.CONFIG).read_text(
            encoding="utf-8-sig"))
    except (OSError, ValueError, _PL.LayoutError):
        return []
    acc = doc.get("accounts")
    return sorted(acc) if isinstance(acc, dict) else []


def cmd_init(args: argparse.Namespace) -> None:
    """`tjs init`: one folder of exports for every year — inputs/
    shared by the year projects, and the year's folder (YYYY/), a
    complete project whose taxjson.toml names the shared folders
    (lib/project_layout); `--single`: one folder for one year."""
    if getattr(args, "demo", False):
        _init_demo(args)
        return
    if not args.country:
        _die_input("--country is required (canada | ca | usa | us)",
                   f"`{_PROG} init --demo` makes a project of made-up "
                   f"data to try first.")
    country = _normalize_country(args.country)
    if country not in ("canada", "usa"):
        _die(f"unknown country {args.country!r} (expected canada | ca | "
             f"usa | us)")

    _year = getattr(args, "year", None)
    _max_year = date_cls.today().year + 1
    if _year is not None and not (1900 <= _year <= _max_year):
        # 0/-5/20255 scaffolded projects whose every report was
        # silently all-zero (REVIEW #28); 2099 fetched no FX rates
        # and built empty books (2026-09 CLI audit).
        _die(f"--year {_year} is not a plausible tax year (expected "
             f"1900 to {_max_year})")
    years = not bool(getattr(args, "single", False))
    first_year = int(_year or date_cls.today().year)

    # The positional `path` (if given) overrides the global -C/--dir flag.
    target = getattr(args, "path", None) or args.dir
    top = Path(target).resolve()
    if years:
        _refuse_init_in_year_folder(top, country, _year)
    if years and (top / "taxjson.toml").is_file():
        _die(f"{top} is a single-folder project (it has a taxjson.toml)",
             "`tjs migrate --to-years` there turns it into one folder "
             "of exports for every year; `tjs init --single --force` "
             "re-templates it.")
    root = top / str(first_year) if years else top
    cfg = root / "taxjson.toml"
    if cfg.exists() and not args.force:
        _die(f"{cfg} already exists (use --force to overwrite)")
    # A taxjson.toml made read-only is refused before anything is
    # written, as every other writer refuses it (lib/safe_write; backlog
    # TJ-0107, TJ-0220). `init --force` replaces no other file: the
    # rest are written only when absent.
    from taxjson.lib.safe_write import refuse_read_only
    try:
        refuse_read_only(cfg)
    except OSError as e:
        from taxjson.lib.cli_diag import cannot_write
        _head, _fix = cannot_write(_config_shown(cfg), e, cfg)
        _die_input(_head, " ".join(x for x in (_fix, "Nothing was changed.")
                                   if x))

    # The config is (re)written — the guard above already enforces --force.
    _layout = ({_PL.INPUTS_KEY: f"../{_PL.INPUTS}",
                _PL.EXPORTS_KEY: f"../{_PL.EXPORTS}",
                # Canada: the interlisted pairs, one file every year reads.
                **({_PL.TOBASE_KEY: _PL.SHARED_TOBASE}
                   if country == "canada" else {})} if years else {})
    config_text, account_names = _render_init_config(
        country, getattr(args, "year", None),
        {**_layout, _REQ_KEY: _init_requires(cfg, country, _layout,
                                             own_tobase=not years)},
        grant_since=(_sibling_grant_since(top, first_year)
                     if years and country == "canada" else None))
    # The write boundary BEFORE anything is created (#45): a folder the
    # scaffold writes into that is a link leaving the project (inputs/
    # -> a sibling folder) put the account folders and READMEs there,
    # as _refuse_outside_dir_links refuses for every other command.
    _yd = f"{first_year}/" if years else ""
    _init_refuse_outside_links(top, [
        f"{_yd}{_PL.HOLDINGS}" if years else "", _PL.INPUTS,
        *(f"{_PL.INPUTS}/{a}" for a in account_names)])
    import os as _os
    # Every folder the scaffold writes into is checked BEFORE anything
    # is created or written: inputs/ existing as a file was a
    # NotADirectoryError traceback after taxjson.toml and ticker.map
    # were in place (re-audit A2-0781), and 2025/holdings as a file
    # stopped the init after taxjson.toml, ticker.map, tobase.map and
    # .gitignore were written — the retry then refused, "taxjson.toml
    # already exists" (backlog TJ-0568).
    for rel in ([_PL.INPUTS] + [f"{_PL.INPUTS}/{a}" for a in account_names]
                + ([f"{_yd}{_PL.HOLDINGS}"] if years else [])):
        q = top / rel
        if _os.path.lexists(q) and not q.is_dir():
            _die(f"cannot create {rel}/: it exists and is not a "
                 f"directory", "Move it away, then re-run init. Nothing "
                 "was written.")
    _own = [d for d in ({top, root}) if not d.exists()
            or (d.is_dir() and not any(d.iterdir()))]
    # What this init creates, removed again when a later write fails on
    # a NEW project, so the retry is not refused (TJ-0568).
    _made: List[Path] = [d for d in (top, root) if not _os.path.lexists(d)]
    try:
        root.mkdir(parents=True, exist_ok=True)
        # A folder made for the project (`mkdir -p ~/taxes` before the
        # init, or here) is owner-only like the scaffold's own folders,
        # so no later run warns that it is readable by other users.
        for d in _own:
            if _os.name != "nt":
                _os.chmod(d, 0o700)
    except OSError as e:
        # An existing FILE, a path under a file, or an unwritable
        # parent tracebacked (R1-263).
        _die(f"cannot create the project directory {root}: "
             + ("a file of that name exists"
                if isinstance(e, FileExistsError) or root.is_file()
                else (e.strerror or str(e))))

    written: List[str] = []
    _yrel = f"{first_year}/" if years else ""
    # An earlier year added beside existing year folders (new-year only
    # goes forward): the shared inputs/ holds their accounts. A folder
    # the template names that inputs/ lacks is not made there (the
    # user's accounts are other, or were removed), and the note says
    # where the accounts' tables are (backlog TJ-0475).
    _beside = ([(y, d) for y, d in _PL.year_dirs(top) if y != first_year]
               if years else [])
    _shared_dirs = sorted(
        d.name for d in (top / _PL.INPUTS).iterdir()
        if d.is_dir() and d.name != "slips") if (
            _beside and (top / _PL.INPUTS).is_dir()) else []
    _accts_made = [a for a in account_names
                   if not _shared_dirs or a in _shared_dirs]
    bak_name = "taxjson.toml.bak"
    _fresh = not _os.path.lexists(cfg)
    _new_files: List[Path] = []

    def _failed(rel: str, path: Path, e: OSError) -> None:
        """A write failed part-way: a NEW project's files and folders
        made so far are removed (the retry is not refused for a
        taxjson.toml left behind — TJ-0568); a re-template keeps its
        backup."""
        from taxjson.lib.cli_diag import cannot_write
        if _fresh:
            for f in reversed(_new_files):
                try:
                    f.unlink()
                except OSError:
                    pass
            for d in reversed(_made):
                try:
                    d.rmdir()               # only when left empty
                except OSError:
                    pass
        _head, _fix = cannot_write(rel, e, path)
        _die_input(_head, " ".join(x for x in (
            _fix, "Nothing was kept: re-run init once it is fixed."
            if _fresh else f"Your previous config is {_yrel}{bak_name}.")
            if x))

    if cfg.exists():
        # --force re-templates: keep the user's previous config (their
        # accounts, holdings, instalments) recoverable.
        bak_name = _backup_config(cfg)
        written.append(f"{_yrel}{bak_name} (your previous config)")
    # UTF-8 whatever the locale, through tmp + replace: under LC_ALL=C
    # the template's em dash was a UnicodeEncodeError that left a 0-byte
    # taxjson.toml blocking the retry (re-audit A2-0477).
    try:
        write_text_atomic(cfg, config_text)
    except OSError as e:
        _failed(f"{_yrel}taxjson.toml", cfg, e)
    if _fresh:
        _new_files.append(cfg)
    written.append(f"{_yrel}taxjson.toml")

    # Everything else is written ONLY when absent, so re-running `init
    # --force` re-templates the config without clobbering a ticker.map or
    # README the user has already populated.
    def _stub(rel: str, content: str) -> None:
        import os
        p = top / rel
        try:
            _made.extend(reversed([
                d for d in (p.parent, *p.parent.parents)
                if d.is_relative_to(top) and not os.path.lexists(d)]))
            p.parent.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            # Name the folder that could not be made (its parent is the
            # one to make writable), not the file meant for it.
            _d = next((d for d in reversed([p.parent, *p.parent.parents])
                       if d.is_relative_to(top) and not d.is_dir()),
                      p.parent)
            _failed(_d.relative_to(top).as_posix() + "/", _d, e)
        if os.path.lexists(p):
            if p.is_symlink() and not p.exists():
                # A dangling symlink: writing the stub would create its
                # target, wherever it points (security review I3).
                _say("note", f"{rel} is a symlink to a missing file "
                     f"({os.readlink(p)}) — left as is",
                     "It is not written through; remove it and re-run "
                     "init for the template.", prog=f"{_PROG} init")
            return
        from taxjson.lib.safe_write import write_atomic
        try:
            write_atomic(p, content)
        except OSError as e:
            _failed(rel, p, e)
        _new_files.append(p)
        written.append(rel)

    from taxjson.lib.ticker_map_format import init_template
    _stub(f"{_yrel}ticker.map", init_template())
    if country == "canada":
        # The interlisted master's pairs (lib/tobase_map, CA-XLIST-06):
        # every US and OTC listing of a Canadian share, one security —
        # with a year folder, one file at the top every year reads
        # (`[settings] tobase_map`).
        from taxjson.lib import tobase_map as _TB
        _stub(_TB.TOBASE_MAP, _TB.render(_TB.load_master(), shared=years))
    _stub(".gitignore", _TEMPLATE_GITIGNORE + (
        "# The newest year's positions and wash radar, for other tools "
        "(`tjs run`).\n/exports/\n" if years else ""))
    if years:
        from taxjson.lib.holdings_dir import README as _HREADME
        _stub(f"{_yrel}{_PL.HOLDINGS}/README.txt", _HREADME)
    from taxjson.lib.config_template import input_readme as _readme
    for acct in _accts_made:
        # The README also keeps the empty input dir present under git.
        # It says what to download from each broker (new-user study).
        _stub(f"inputs/{acct}/README.txt", _readme(
            country, acct, "YYYY/inputs/slips/"
            if years else "inputs/slips/"))

    # Essentials first (docs/output-style.md): the project made and the
    # next steps, one line each; the files written, the layout and the
    # next-year hint with --details.
    _det = _details(args)
    print(f"Initialized taxjson project at {root}"
          + (f" (the {first_year} folder of {top}: one folder of exports "
             f"for every year)" if years and _det else ""))
    _bak = any(w.endswith("(your previous config)") for w in written)
    if _det:
        for rel in written:
            print(f"  wrote {rel}")
    elif _bak and cfg.with_name(bak_name).exists():
        print(f"  wrote {_yrel}{bak_name} (your previous config)")
    from taxjson.lib.out import labelled as _labelled

    def _few(names: List[str]) -> str:
        return ", ".join(names[:3]) + (
            f" +{len(names) - 3} more" if len(names) > 3 else "")
    # Folders a previous scaffold (e.g. --force from canada to usa)
    # left under inputs/ that the new config has no section for; beside
    # other year folders, theirs (backlog TJ-0475). The .bak is named
    # only when this init wrote one.
    _inputs = top / "inputs"
    _orphans = sorted(d.name for d in _inputs.iterdir()
                      if d.is_dir() and d.name not in account_names
                      and d.name != "slips") if _inputs.is_dir() else []
    _theirs = {a for _y, d in _beside for a in _year_accounts(d)}
    _near = min((y for y, _d in _beside),
                key=lambda y: (abs(y - first_year), -y), default=None)
    _used = [o for o in _orphans if o in _theirs]
    _stray = [o for o in _orphans if o not in _theirs]
    if _near is not None and (_used or len(_accts_made) < len(account_names)):
        _not_made = [a for a in account_names if a not in _accts_made]
        _head = (f"note: {_yrel}taxjson.toml has the template's accounts, "
                 f"inputs/ "
                 + (f"{_near}'s" if len(_beside) == 1 else "the other years'")
                 + (f" ({_few(_used)})" if _used else ""))
        _rest = (f"Copy from {_near}/taxjson.toml the [accounts.*] tables "
                 f"of the accounts {first_year} had, and remove the "
                 f"template's others."
                 + (f" No folder was made in inputs/ for the template's "
                    f"{', '.join(_not_made)}." if _not_made else ""))
        if _det:
            for _ln in _out_wrap(_labelled(_head), indent="  ",
                                 hang="    "):
                print(_ln)
            for _ln in _out_wrap(_rest, indent="    "):
                print(_ln)
        else:
            print(_labelled(_head + f" — copy their tables from "
                            f"{_near}/taxjson.toml"))
    if _stray:
        _how = f"re-add (see {bak_name})" if _bak else "add one"
        if _det:
            for _ln in _out_wrap(_labelled(
                    f"note: inputs/ has folder(s) with no [accounts.*] "
                    f"section in the new config: {', '.join(_stray)}"),
                    indent="  ", hang="    "):
                print(_ln)
            for _ln in _out_wrap(
                    (f"Re-add their sections (see {bak_name})" if _bak
                     else "Add their sections") + " or remove the "
                    "folders.", indent="    "):
                print(_ln)
        else:
            print(_labelled(f"note: inputs/ {_few(_stray)}: no "
                            f"[accounts.*] section — {_how} or remove "
                            f"them"))
    import shlex as _shlex
    from taxjson.lib.config_template import system_timezone as _systz
    if not _det:
        print("\nNEXT STEPS")
        print(f"  1. Edit {_yrel}taxjson.toml: "
              + ("your accounts" if years else "the year, your accounts")
              + " and currencies"
              + (", and [settings] local_timezone" if _systz() is None
                 else "") + ".")
        print("  2. Save the broker exports in inputs/<account>/"
              + (f" (every year), positions snapshots in {_yrel}holdings/."
                 if years else "."))
        # Commands to copy: their own lines, never wrapped.
        print(f"  3. tjs -C {_shlex.quote(str(root))} run")
        print(f"  4. tjs -C {_shlex.quote(str(root))} checklist --run")
        _init_filing_hint(_year, first_year, country, years, top)
        if country == "usa":
            _say("note", f"{_US_EXPERIMENTAL_NOTE[0]}: treat the output "
                 f"as a draft", prog=f"{_PROG} init")
        return
    print("\nNext:")
    _step1 = (f"1. Edit {_yrel}taxjson.toml: set the accounts and source "
              f"currencies" if years else
              "1. Edit taxjson.toml: set the year, accounts, and source "
              "currencies")
    if _systz() is None:
        # Left commented (UTC or unreadable here): there is no default,
        # and a crypto account stops the run until it is set.
        _step1 += (", and [settings] local_timezone (your IANA zone, e.g. "
                   "\"America/Vancouver\": crypto rows are dated in it; "
                   "this machine's zone could not be read or is UTC)")
    for _ln in _out_wrap(_step1 + ".", indent="  ", hang="     "):
        print(_ln)
    if years:
        for _ln in _out_wrap(
                "2. Drop every year's broker CSV exports into "
                "inputs/<account>/ (one folder per account, all years "
                f"together) and the broker's positions snapshots into "
                f"{_yrel}holdings/.", indent="  ", hang="     "):
            print(_ln)
    else:
        print("  2. Drop broker CSV exports into inputs/<account>/.")
    print("  3. Run:")
    # A command to copy: its own line, never wrapped.
    print(f"       tjs -C {_shlex.quote(str(root))} run")
    print("  4. Every step after that, checked, and which one is next:")
    print(f"       tjs -C {_shlex.quote(str(root))} checklist --run")
    if years:
        for _ln in _out_wrap(f"Next year: `tjs -C "
                             f"{_shlex.quote(str(top))} new-year "
                             f"{first_year + 1}` copies this year's "
                             f"taxjson.toml and ticker.map into "
                             f"{first_year + 1}/"
                             + (" (tobase.map is one file every year "
                                "reads)" if country == "canada" else "")
                             + ".", indent="  ", hang="  "):
            print(_ln)
    _init_filing_hint(_year, first_year, country, years, top)
    if country == "usa":
        _say("note", *_US_EXPERIMENTAL_NOTE, prog=f"{_PROG} init")


def _init_refuse_outside_links(top: Path, rels: List[str]) -> None:
    """Die (exit 2, nothing written) when a folder `tjs init` would
    write into — each of `rels` and every folder above it, under `top` —
    is a symlink leaving `top` (#45). A link inside `top` is kept."""
    from taxjson.lib.safe_write import link_outside
    bad: List[str] = []
    for rel in rels:
        p = top
        for part in Path(rel).parts:
            p = p / part
            target = link_outside(p, top)
            shown = f"{p.relative_to(top).as_posix()}/ -> {target}"
            if target is not None and shown not in bad:
                bad.append(shown)
    if bad:
        _die_input("folder(s) that are symlinks to outside the project — "
                   "init writes there; nothing was written:\n    "
                   + "\n    ".join(bad),
                   "Replace each link with a real folder (move its "
                   "contents in), or run init in the folder the link "
                   "points into.")


def _init_filing_hint(year_given: Optional[int], first_year: int,
                      country: str, years: bool, top: Path) -> None:
    """January to April, with no --year: one line naming the init
    command for last year's folder — most people file the year that just
    ended (owner: the default stays the calendar year). Printed in the
    default view and with --details."""
    import shlex as _shlex
    if year_given is None and date_cls.today().month <= 4:
        print(f"  Filing {first_year - 1} now? Run `{_PROG} init --country "
              f"{country} --year {first_year - 1}`"
              + (f" in {_shlex.quote(str(top))}" if years else "")
              + " for its folder.")


_REQ_KEY = "requires_taxjson"         # lib/requires.KEY


def _init_requires(cfg: Path, country: str, layout: Dict[str, Any],
                   own_tobase: bool) -> str:
    """The requires_taxjson `tjs init` writes: the release that
    reads the layout it makes (lib/requires.FEATURES) — the previous
    config's value when `--force` re-templates one that asks for more
    (never lowered)."""
    from taxjson.lib import requires as _REQ
    old = None
    if cfg.is_file():
        try:
            old = (tomllib.loads(_read_config_text(cfg)).get("settings")
                   or {}).get(_REQ.KEY)
            _REQ.parse_spec(old)
        except Exception:                               # noqa: BLE001
            old = None
    feats = (_REQ.features_of({"country": country, **layout},
                              own_tobase=own_tobase)
             | set(_REQ.INIT_FEATURES))
    return _REQ.raised(old, feats) or old


def _init_demo(args: argparse.Namespace) -> None:
    """`tjs init --demo [DIR]`: the demo project (lib/demo) — DIR
    (new or empty) holding inputs/ with the made-up exports, tobase.map
    and 2024/, a ready taxjson.toml — and the commands to try."""
    import shlex as _shlex
    import shutil
    from taxjson.lib import config_template as CT
    from taxjson.lib import demo as DM
    from taxjson.lib import tobase_map as _TB
    from taxjson.lib.safe_write import write_atomic
    from taxjson.lib.ticker_map_format import init_template
    if args.country and _normalize_country(args.country) != DM.COUNTRY:
        _die_input("the demo is a Canadian project: leave out --country "
                   "(or pass --country canada)")
    if getattr(args, "year", None) not in (None, DM.YEAR):
        _die_input(f"the demo's tax year is {DM.YEAR}: leave out --year")
    if getattr(args, "single", False):
        _die_input("the demo is one folder of exports for every year: "
                   "leave out --single")
    top = Path(getattr(args, "path", None) or args.dir).resolve()
    _refuse_init_in_year_folder(top, DM.COUNTRY, DM.YEAR)
    try:
        busy = top.exists() and (not top.is_dir() or any(top.iterdir()))
    except OSError as e:
        _die_input(f"cannot read {top}: {e.strerror or e}")
    if busy:
        _die_input(f"{top} is not empty: the demo goes in a new folder",
                   f"`{_PROG} init --demo ~/taxjson-demo` makes one. "
                   f"Nothing was written.")
    try:
        top.mkdir(parents=True, exist_ok=True, mode=0o700)
    except OSError as e:
        _die_input(f"cannot create {top}: {e.strerror or e}")
    root = top / str(DM.YEAR)
    doc = CT.scaffold_document(DM.COUNTRY, DM.YEAR)
    doc["settings"].update(DM.settings())
    doc["settings"]["province"] = DM.PROVINCE
    doc["settings"].update({_PL.INPUTS_KEY: f"../{_PL.INPUTS}",
                            _PL.EXPORTS_KEY: f"../{_PL.EXPORTS}",
                            _PL.TOBASE_KEY: _PL.SHARED_TOBASE})
    doc["settings"][_REQ_KEY] = _init_requires(
        root / _PL.CONFIG, DM.COUNTRY, doc["settings"], own_tobase=False)
    doc["accounts"] = {n: dict(c) for n, c in DM.ACCOUNTS}
    (root / _PL.HOLDINGS).mkdir(parents=True, exist_ok=True, mode=0o700)
    write_atomic(root / "taxjson.toml",
                 CT.render_document(doc, DM.COUNTRY, DM.YEAR))
    write_atomic(root / "ticker.map", init_template())
    from taxjson.lib.holdings_dir import README as _HREADME
    write_atomic(root / _PL.HOLDINGS / "README.txt", _HREADME)
    write_atomic(top / _TB.TOBASE_MAP,
                 _TB.render(_TB.load_master(), shared=True))
    write_atomic(top / ".gitignore", _TEMPLATE_GITIGNORE
                 + "# The newest year's positions and wash radar, for "
                   "other tools (`tjs run`).\n/exports/\n")
    for name, cfg in DM.ACCOUNTS:
        d = top / _PL.INPUTS / name
        d.mkdir(parents=True, exist_ok=True, mode=0o700)
        kind = ("crypto" if cfg.get("crypto") else str(cfg["type"]))
        write_atomic(d / "README.txt", CT.input_readme(
            DM.COUNTRY, name, "YYYY/inputs/slips/", kind=kind))
    for name, src in DM.files():
        dst = top / _PL.INPUTS / name / src.name
        shutil.copyfile(src, dst)
        dst.chmod(0o600)
    from taxjson.lib import out as _out
    yd = _shlex.quote(str(root))
    print(_out.fill(f"Made the taxjson demo in {top}: tax year {DM.YEAR}, "
                    f"made-up exports of eight accounts in inputs/ (two "
                    f"taxable at IB, Questrade, Webull, crypto at Kraken "
                    f"and Coinbase; a TFSA at RBC, a LIRA at Questrade "
                    f"and an RRSP at IB) and the year's project in "
                    f"{DM.YEAR}/."))
    print("\nTry:")
    print(f"  cd {yd}")
    print(f"  {_PROG} run              # build the books")
    print(f"  {_PROG} sum              # the year's gains, as on the return")
    print(f"  {_PROG} checklist --run  # every step to filing, checked")
    print("\nIt holds, to explore:")
    for what, cmd in DM.SCENARIOS:
        print(f"  {what}: `{_PROG} {cmd}`")


def _refuse_init_in_year_folder(top: Path, country: str,
                                year: Optional[int]) -> None:
    """`tjs init` makes the year's folder (YYYY/) inside the folder
    it runs in: run inside an empty folder named like a year
    (~/taxes/2026) it built ~/taxes/2026/2026/ without a word. Refuse,
    with the command for the folder above it."""
    import shlex as _shlex
    if not re.fullmatch(r"(?:19|20)\d\d", top.name):
        return
    try:
        empty = not any(top.iterdir()) if top.is_dir() else not top.exists()
    except OSError:
        return
    if not empty:
        return
    y = year or int(top.name)
    _die_input(
        f"{top} is named like a tax year and is empty: `init` makes the "
        f"year's folder itself, so this would build {top.name}/{y}/ in it",
        f"Run it in the folder above: cd {_shlex.quote(str(top.parent))} "
        f"&& {_PROG} init --country {country}"
        + (f" --year {y}" if y != date_cls.today().year else "")
        + f" && cd {y} (or `{_PROG} init --single --country {country}` for "
        f"one folder for one year here). Nothing was written.")


def _sibling_grant_since(top: Path, year: int) -> Optional[int]:
    """option_grant_timing_since as another year folder of `top` sets
    it (the nearest year's), so a new year keeps the first year filed
    under grant timing; None when no year sets it."""
    best: Optional[Tuple[int, int]] = None
    for y, d in _PL.year_dirs(top):
        if y == year:
            continue
        try:
            doc = tomllib.loads((d / "taxjson.toml").read_bytes()
                                .decode("utf-8-sig"))
        except (OSError, ValueError, UnicodeError):
            continue
        v = (doc.get("settings") or {}).get("option_grant_timing_since")
        if isinstance(v, int) and not isinstance(v, bool):
            dist = abs(y - year)
            if best is None or dist < best[0]:
                best = (dist, v)
    return best[1] if best else None


def _years_folder(root: Path) -> Path:
    """The folder holding the year projects for `years` / `new-year`
    (lib/project_layout.multi_root); dies outside one."""
    top = _PL.multi_root(root)
    if top is not None:
        return top
    if not _PL.has_config(root):
        _die_input(f"{root} holds no year folder (YYYY/ with a "
                   f"taxjson.toml)",
                   "`tjs init` creates one folder of exports for every "
                   "year; docs/getting-started.md, \"One folder of exports "
                   "for every year\".")
    return root.parent


def _single_folder_project(root: Path, top: Path) -> bool:
    """`root` is a project folder that is not a year folder: it has a
    taxjson.toml and the folder `years` / `new-year` would read holds no
    year folder at all (2026-10 workflow audit: `years` there offered
    `new-year`, which refused and offered an `init` that refused too;
    the move is `tjs migrate --to-years`)."""
    return (_PL.has_config(root) and _PL.multi_root(root) is None
            and not _PL.year_dirs(top))


def _single_folder_hint(root: Path) -> str:
    return (f"{root} is a single-folder project, not a year folder: "
            f"`tjs migrate --to-years` makes it the first year folder "
            f"(its exports shared by every year), then `tjs new-year "
            f"YYYY` adds the next.")


def cmd_years(args: argparse.Namespace) -> None:
    """`tjs years [--json] [--diff A B]`: the year projects of a
    multi-year folder and the state of each (lib/project_layout
    .years_report); --diff: what differs between two years' ticker.map
    and taxjson.toml."""
    root = Path(args.dir).resolve()
    top = _years_folder(root)
    if args.diff:
        a, b = (top / str(y) for y in args.diff)
        for d in (a, b):
            if not _PL.has_config(d):
                _die_input(f"no project in {d}")
        try:
            c = _PL.compare(a, b)
        except _PL.LayoutError as e:
            _die_input(str(e), "Nothing was compared: fix the file first.")
        _align_show(c, a.name, b.name, args.json)
        return
    rep = _PL.years_report(top)
    _years_shared_moved(top, rep)
    if args.json:
        _json_out(rep)
        return
    from taxjson.lib import out as _out
    if not _details(args):
        _years_table(top, rep, root)
        return
    single = not rep["years"] and _single_folder_project(root, top)
    # A single-folder project: its own folder, not its parent's (backlog
    # TJ-0116).
    print(f"Year projects in {root if single else top}")
    if not rep["years"]:
        print(_out.fill(_single_folder_hint(root) if single else
                        "No year folder yet — `tjs new-year YYYY` "
                        "creates one."))
        return
    for r in rep["years"]:
        state = ("filed" + (f" {r['closed_at'][:10]}" if r["closed_at"]
                            else "")
                 + (" (lock taken before the year ended)"
                    if r["partial_lock"] else "")) if r["filed"] else "open"
        if r["totals"]:
            t = r["totals"]
            state += (f" (realized {float(t.get('realized') or 0):,.2f}, "
                      f"denied {float(t.get('disallowed') or 0):,.2f})")
        if r.get("drifted"):
            state += (f", DRIFTED from filed/{r['year']}.json at its last "
                      f"run (`tjs -C {_year_dir_arg(top, r['year'])} "
                      f"check-filed`)")
        run = (f"last run {r['last_run'][:16].replace('T', ' ')}"
               if r["last_run"] else "not run yet")
        if r["stale"]:
            run += f" — inputs changed since ({r['changed']})"
            if r["filed"]:
                run += ("; `tjs run` there rechecks the filed figures "
                        "against the lock")
        diff = r["differs_from_newest"]
        extra = ""
        if diff and (diff["map_rules"] or diff["keys"]
                     or diff.get("tobase_rules") or diff.get("accounts")):
            extra = (f"; differs from {rep['newest']}: {diff['map_rules']} "
                     f"ticker.map rule(s), "
                     + (f"{diff['tobase_rules']} tobase.map line(s), "
                        if diff.get("tobase_rules") else "")
                     + (f"{diff['accounts']} account(s) only one has, "
                        if diff.get("accounts") else "")
                     + f"{diff['keys']} setting(s) ("
                     + ("a filed year's own: `align` there would change "
                        "what its lock recorded; " if _years_as_filed(r)
                        else "")
                     + f"`tjs years --diff {r['year']} "
                     f"{rep['newest']}`)")
        _sm = r.get("shared_exports_changed") or []
        if _sm:
            extra += (f"; {len(_sm)} shared file(s) gained, changed or "
                      f"lost a row of {r['year']} (or a decision on it, or "
                      f"a generic mapping that reads it) since the close "
                      f"({', '.join(_sm[:4])}"
                      + (" ..." if len(_sm) > 4 else "")
                      + f"): the year reads its frozen copy — `tjs -C "
                      f"{_year_dir_arg(top, r['year'])} check-filed` says "
                      f"what to do")
        _nc = r.get("shared_not_compared") or []
        if _nc:
            extra += (f"; {len(_nc)} file(s) could not be compared with "
                      f"the copy {r['year']} was closed with ("
                      + ", ".join(f"{x['file']}: {x['why']}"
                                  for x in _nc[:4])
                      + (" ..." if len(_nc) > 4 else "")
                      + ")")
        marks = r["marks"]
        if marks["done"] or marks["forced"]:
            extra += (f"; checklist: {marks['done']} done, "
                      f"{marks['forced']} forced")
        line = f"{r['year']}  {state}; {run}{extra}"
        if r["problem"]:
            line += f"; {r['problem']}"
        for _ln in _out.wrap(line, None, "  ", "        "):
            print(_ln)
    # tobase.map (Canada): one file every year reads, per-year copies,
    # or a filed year's frozen copy (said as the default view says it).
    shared, own, frozen = _years_tobase(rep)
    for p, ys in sorted(shared.items()):
        for _ln in _out.wrap(f"tobase.map: {p}, shared by "
                             f"{', '.join(str(y) for y in ys)} ([settings] "
                             f"{_PL.TOBASE_KEY})", None, "", "  "):
            print(_ln)
    if frozen:
        for _ln in _out.wrap(
                f"tobase.map: frozen copy of its own in "
                f"{', '.join(str(y) for y in frozen)} (filed: close-year "
                f"froze it, the year reads it)", None, "", "  "):
            print(_ln)
    if own:
        for _ln in _out.wrap(
                f"tobase.map: a copy in each of "
                f"{', '.join(str(y) for y in own)} — `tjs migrate` "
                f"here makes them one file every year reads", None, "",
                "  "):
            print(_ln)


def _years_tobase(rep: Dict[str, Any]
                  ) -> Tuple[Dict[str, List[int]], List[int], List[int]]:
    """The years report's tobase.map files: ({shared file: the years
    naming it}, the years with a copy of their own to merge, the filed
    years with the copy close-year froze — their own by design, never a
    copy to merge)."""
    shared: Dict[str, List[int]] = {}
    for r in rep["years"]:
        if r.get("tobase_shared"):
            shared.setdefault(r["tobase_map"], []).append(r["year"])
    own = [r["year"] for r in rep["years"]
           if r.get("tobase_map") and not r.get("tobase_shared")
           and not r.get("tobase_frozen")]
    frozen = [r["year"] for r in rep["years"] if r.get("tobase_frozen")]
    return shared, own, frozen


def _years_as_filed(r: Dict[str, Any]) -> bool:
    """A years-report year that is filed: locked after its year ended.
    What differs from the newest year is its own, never a step to take
    (`align` there would change what the lock recorded; backlog
    TJ-0103)."""
    return bool(r["filed"] and not r["partial_lock"])


def _years_shared_moved(top: Path, rep: Dict[str, Any]) -> None:
    """Each year's `shared_exports_changed`: for a year closed with its
    inputs frozen, the shared exports that gained, changed or lost a row
    of the year since the close, the generic mappings that read one of
    its CSVs otherwise (_shared_inputs_moved, backlog TJ-0708) and the
    decisions files
    holding a decision on it that differs (_shared_decisions_moved,
    backlog TJ-0211), from the folder
    holding the years. The run's check-filed note was the one place it
    showed: `years` gave the filed year no mark (backlog TJ-0210). []
    for an open year, a damaged lock, a lock that froze nothing, and a
    year that names the shared folders again (it reads them: its drift
    check covers it). `shared_not_compared`: [{"file", "why"}] the
    files that comparison could not read (backlog TJ-0707)."""
    import os as _os
    from taxjson.bin.taxjson_filed import load_lock_json

    def _from_top(d: Path, shown: str) -> str:
        q = Path(shown)
        q = _os.path.normpath(q if q.is_absolute() else d / q)
        rel = _os.path.relpath(q, top)
        return q if rel.startswith("..") else rel

    for r in rep.get("years") or []:
        r["shared_exports_changed"] = []
        r["shared_not_compared"] = []
        if not r.get("filed") or r.get("problem") or r.get("partial_lock"):
            continue
        d = top / str(r["folder"])
        try:
            doc = load_lock_json(d / "filed" / f"{r['year']}.json")
        except (OSError, ValueError):
            continue
        fz = doc.get("frozen") if isinstance(doc, dict) else None
        if not isinstance(fz, dict) or _frozen_settings_back(d):
            continue
        got = _shared_inputs_moved(d, fz, int(r["year"]))
        r["shared_exports_changed"] = [
            _from_top(d, shown) for shown in (
                got["exports"] + got["mappings"]
                + [x for x, _n in _shared_decisions_moved(
                    d, fz, int(r["year"]))])]
        r["shared_not_compared"] = [{"file": _from_top(d, p), "why": why}
                                    for p, why in got["unread"]]


def _years_act(text: str, cmd: str, width_: int = 100) -> str:
    """An act-on line (out.act) within `width_` columns: a longer
    `text` cut at its last clause (`, ` / `; ` / ` — `) or else at a
    word, ` ...` marking the cut; --details has it whole (backlog
    TJ-0051: cut mid-word at 80 characters)."""
    from taxjson.lib import out as _out
    text = " ".join(str(text).split())
    room = width_ - len(_out.act("", cmd))
    if len(text) <= room:
        return _out.act(text, cmd)
    cut = text[:room - 4]                  # room for " ..."
    at = max(cut.rfind(s) for s in (", ", "; ", " — "))
    if at <= room // 2:
        at = cut.rfind(" ")
    cut = cut[:at] if at > 0 else cut
    return _out.act(cut.rstrip(" ,;:—-") + " ...", cmd)


def _year_dir_arg(top: Path, year: Any) -> str:
    """The `-C` argument that names year folder `year` (in `top`) from
    the folder the command was run in: `2024` in the folder holding the
    years, `../2024` in a year folder (a bare `2024` there names
    2025/2024; backlog TJ-0262); the full path when it is further away.
    Quoted for the shell."""
    import os as _os
    import shlex as _shlex
    p = Path(top) / str(year)
    try:
        rel = _os.path.relpath(p)
    except ValueError:                      # another drive (Windows)
        rel = str(p)
    if rel.startswith(_os.pardir + _os.sep + _os.pardir):
        rel = str(p)
    return _shlex.quote(rel)


def _years_table(top: Path, rep: Dict[str, Any], root: Path) -> None:
    """`tjs years`, the default view (docs/output-style.md,
    Essentials first): one table row per year, then one line per thing
    to do; --details prints each year's state in words."""
    from taxjson.lib import out as _out
    single = not rep["years"] and _single_folder_project(root, top)
    # A single-folder project: its own folder, not its parent's (backlog
    # TJ-0116).
    print(f"YEAR PROJECTS — {root if single else top}")
    if not rep["years"]:
        print()
        if single:
            print(_out.act("This is a single-folder project, not a year "
                           "folder", "tjs migrate --to-years"))
        else:
            print(_out.act("No year folder yet", "tjs new-year YYYY"))
        return
    newest = rep["newest"]
    body = []
    for r in rep["years"]:
        state = (("filed " + (r["closed_at"][:10] if r["closed_at"] else "")
                  ).strip() + ("*" if r["partial_lock"] else "")
                 if r["filed"] else "open")
        if r["filed"] and str(r["problem"] or "").startswith(
                f"filed/{r['year']}.json"):
            state = "lock damaged"          # issue #49
            if " was closed under country = " in str(r["problem"]):
                state = "other country"     # backlog TJ-0069
            elif str(r["problem"]).startswith(
                    f"filed/{r['year']}.json is missing"):
                state = "lock missing"      # backlog TJ-0263
        elif r.get("drifted"):
            state += " DRIFTED"             # its last run (TJ-0159)
        t = r["totals"] or {}
        diff = r["differs_from_newest"] or {}
        vs = ", ".join(x for x in (
            f"{diff['map_rules']} rule(s)" if diff.get("map_rules") else "",
            f"{diff['tobase_rules']} tobase line(s)"
            if diff.get("tobase_rules") else "",
            f"{diff['accounts']} account(s)" if diff.get("accounts") else "",
            f"{diff['keys']} setting(s)" if diff.get("keys") else "") if x)
        if vs and _years_as_filed(r):
            vs += " (filed)"
        marks = r["marks"]
        body.append([str(r["year"]), state,
                     f"{float(t.get('realized') or 0):,.2f}" if t else "",
                     f"{float(t.get('disallowed') or 0):,.2f}" if t else "",
                     r["last_run"][:16].replace("T", " ")
                     if r["last_run"] else "not run",
                     "changed" if r["stale"] else
                     "shared changed" if r.get("shared_exports_changed")
                     else "shared unchecked"
                     if r.get("shared_not_compared") else "",
                     vs or ("" if r["year"] == newest else "same"),
                     f"{marks['done']} done" if marks["done"] else ""])
    print()
    if len(rep["years"]) > 1 or any(r["partial_lock"] for r in rep["years"]):
        print(f"INPUTS: changed since that year's last run"
              + (" (shared changed: a shared export changed a filed "
                 "year's row, or a decision or a generic mapping on it, "
                 "since its close)" if any(
                     r.get("shared_exports_changed")
                     for r in rep["years"]) else "")
              + (" (shared unchecked: a shared file a filed year's copy "
                 "could not be compared with)" if any(
                     r.get("shared_not_compared")
                     and not r.get("shared_exports_changed")
                     for r in rep["years"]) else "")
              + f"; VS {newest}: what differs from the newest year."
              + (" *: locked before the year ended." if any(
                  r["partial_lock"] for r in rep["years"]) else ""))
    for _ln in _out.fit_table(
            ["YEAR", "STATE", "REALIZED", "DENIED", "LAST RUN", "INPUTS",
             f"VS {newest}", "CHECKLIST"], body,
            aligns=["<", "<", ">", ">", "<", "<", "<", "<"],
            drop=(7, 3), key=0):
        print(_ln)
    acts = []
    stale = [r for r in rep["years"] if r["stale"]]
    if stale:
        acts.append(_out.act(
            f"Inputs changed since the last run of "
            f"{', '.join(str(r['year']) for r in stale[:3])}"
            + (f" +{len(stale) - 3}" if len(stale) > 3 else ""),
            f"tjs -C {_year_dir_arg(top, stale[0]['year'])} run"))
    for r in rep["years"]:
        if r["problem"]:
            acts.append(_years_act(f"{r['year']}: {r['problem']}",
                                   "tjs years --details"))
        elif r.get("drifted"):
            acts.append(_years_act(
                f"{r['year']}: its last run DRIFTED from "
                f"filed/{r['year']}.json",
                f"tjs -C {_year_dir_arg(top, r['year'])} check-filed"))
        if r.get("shared_exports_changed") and not r["problem"]:
            _sm = r["shared_exports_changed"]
            # Which files: --details, --json and check-filed.
            acts.append(_years_act(
                f"{r['year']}: {_count_noun(len(_sm), 'shared file')} "
                f"changed for {r['year']} since the close",
                f"tjs -C {_year_dir_arg(top, r['year'])} check-filed"))
        if r.get("shared_not_compared") and not r["problem"]:
            # Not judged: never passed as unchanged (backlog TJ-0707).
            _nc = r["shared_not_compared"]
            acts.append(_years_act(
                f"{r['year']}: {_count_noun(len(_nc), 'shared file')} "
                f"could not be compared with its copy",
                f"tjs -C {_year_dir_arg(top, r['year'])} check-filed"))
    # A filed year's differences are the settings it was filed with:
    # never offered as a step (TJ-0103).
    differ = [r for r in rep["years"] if r["year"] != newest
              and not _years_as_filed(r) and any(
                  (r["differs_from_newest"] or {}).get(k)
                  for k in ("map_rules", "keys", "tobase_rules",
                            "accounts"))]
    if differ:
        acts.append(f"What differs: tjs years --diff {differ[0]['year']} "
                    f"{newest}")
    # A filed year's frozen copy (close-year) is its own by design:
    # never a copy to merge.
    shared, own, frozen = _years_tobase(rep)
    for p, ys in sorted(shared.items()):
        acts.append(f"tobase.map: {p}, shared by "
                    f"{', '.join(str(y) for y in ys)}")
    if frozen:
        acts.append(f"tobase.map: frozen copy of its own in "
                    f"{', '.join(str(y) for y in frozen[:4])} (filed)")
    if own:
        acts.append(_out.act(
            (f"tobase.map: a copy of its own in {own[0]}; make it the "
             f"shared file" if len(own) == 1 else
             f"tobase.map: copies of their own in "
             f"{', '.join(str(y) for y in own[:4])}; make them one file"),
            "tjs migrate"))
    if acts:
        print()
        for a in acts:
            print(a)


def _os_path_lexists(p: Path) -> bool:
    import os
    return os.path.lexists(p)


def _implicit_grant_since(doc: Dict[str, Any]) -> Optional[int]:
    """The option grant-timing cutoff a Canadian project applies by
    default — its own `year`, when option_premium_timing is "grant"
    (the default) and option_grant_timing_since is not set — or None
    (the key set, close timing, a US project: lib/country)."""
    from taxjson.lib.country import CANADA, CountryError, settings_country
    st = doc.get("settings")
    if not isinstance(st, dict):
        return None
    try:
        if settings_country(st) != CANADA:
            return None
    except CountryError:
        return None
    if str(st.get("option_premium_timing") or "grant").strip().lower() \
            != "grant":
        return None
    if st.get("option_grant_timing_since") not in (None, ""):
        return None
    yr = st.get("year")
    return yr if isinstance(yr, int) and not isinstance(yr, bool) else None


def _new_year_publish(top: Path, folder: Path, config_text: str,
                      files: Dict[str, bytes],
                      holdings: Optional[str]) -> None:
    """`tjs new-year`: the new year's files made in a staging folder
    beside the years, then moved into place — the whole folder in one
    rename when it does not exist yet, else file by file with
    taxjson.toml last and every one moved before it taken back when one
    fails. A failure leaves no taxjson.toml behind, so the command can
    simply be run again (GitHub #40). `holdings`: the empty folder to
    make, relative to the year (holdings/, or what holdings_dir names),
    or None. OSError when it cannot be done."""
    import os
    import shutil
    import tempfile
    from taxjson.lib.safe_write import write_atomic
    stage = Path(tempfile.mkdtemp(prefix=f".{folder.name}.new-",
                                  dir=str(top)))
    try:
        for n, data in files.items():
            write_atomic(stage / n, data)
        # (each level private: mkdir(parents=True) gives the parents the
        # default mode)
        hold_first = None   # its first level the year folder does not have
        at, there = stage, folder
        for part in Path(holdings).parts if holdings else ():
            at, there = at / part, there / part
            at.mkdir(mode=0o700)
            if hold_first is None and not os.path.lexists(there):
                hold_first = there.relative_to(folder)
        write_atomic(stage / _PL.CONFIG, config_text)
        if not os.path.lexists(folder):
            os.rename(stage, folder)
            return
        names = list(files) + ([hold_first] if hold_first else []) \
            + [_PL.CONFIG]
        for n in names:
            if os.path.lexists(folder / n):
                raise FileExistsError(17, "already exists",
                                      str(folder / n))
        moved: List[Path] = []
        try:
            for n in names:
                os.rename(stage / n, folder / n)
                moved.append(folder / n)
        except OSError:
            for m in reversed(moved):
                try:
                    if m.is_dir() and not m.is_symlink():
                        shutil.rmtree(m)
                    else:
                        m.unlink()
                except OSError:
                    pass
            raise
    finally:
        if stage.exists():
            shutil.rmtree(stage, ignore_errors=True)


def _unfreeze_text(text: str) -> str:
    """taxjson.toml's text without the lines close-year's freeze
    wrote: its note (_FROZEN_NOTE) and the commented-out `inputs_dir` /
    `tobase_map` under it (new-year sets them again)."""
    out: List[str] = []
    skip = False
    for ln in text.splitlines(keepends=True):
        if ln.strip().startswith(_FROZEN_NOTE_PREFIX):
            skip = True
            continue
        if skip and re.match(r"#\s*(inputs_dir|tobase_map)\s*=", ln.strip()):
            continue
        skip = False
        out.append(ln)
    return "".join(out)


def _templated(text: str) -> str:
    """`text` (a taxjson.toml) in the template layout when it can be
    laid out losslessly, else as it is: a new year's file read as "not
    in the template layout" by its own checklist (workflow audit
    2026-10)."""
    from taxjson.lib.config_template import FormatError, format_config
    try:
        res = format_config(text)
    except FormatError:
        return text
    return res.text if res.changed else text


def cmd_new_year(args: argparse.Namespace) -> None:
    """`tjs new-year YYYY`: the year's folder beside the others,
    with the previous year's taxjson.toml and ticker.map copied in
    (year bumped, prior_year_record set, the year's own tables commented
    out — lib/project_layout.new_year_text; a Canadian project's
    default option grant-timing cutoff kept) and an empty holdings/,
    made in a staging folder and moved into place only when complete
    (_new_year_publish)."""
    import shlex as _shlex
    root = Path(args.dir).resolve()
    top = _years_folder(root)
    year = args.year
    _max_year = date_cls.today().year + 1
    if not 1900 <= year <= _max_year:
        _die_input(f"{year} is not a plausible tax year (expected 1900 to "
                   f"{_max_year})")
    folder = top / str(year)
    if folder.is_symlink() or (folder.exists() and not folder.is_dir()):
        _die_input(f"{folder} exists and is not a folder — move it away "
                   f"first.")
    if (folder / "taxjson.toml").exists() \
            or (folder / "taxjson.toml").is_symlink():
        _die_input(f"{year}/taxjson.toml already exists — the year folder "
                   f"is there (`tjs years` lists them).")
    earlier = [(y, d) for y, d in _PL.year_dirs(top) if y < year]
    if not earlier:
        if _single_folder_project(root, top):
            _die_input(f"{root} is a single-folder project, not a year "
                       f"folder", "`tjs migrate --to-years` makes it "
                       f"the first year folder (its exports shared by "
                       f"every year); then `tjs new-year {year}`.")
        _die_input(f"no earlier year folder in {top} to start {year} from",
                   f"`tjs init --year {year} --country ...` creates a "
                   f"first one.")
    prev_year, prev = earlier[-1]
    if prev_year != year - 1:
        # The year before has no folder: starting from an older year
        # would carry its lock's balances past whatever the missing
        # year used (prior_year_record, handoff, estimate — backlog
        # TJ-0036).
        _die_input(f"{year - 1} has no year folder: start it first",
                   f"{year} would start from {prev_year}/, and the "
                   f"carryforwards it reads from {prev_year}'s lock would "
                   f"skip whatever {year - 1} used. `tjs new-year "
                   f"{year - 1}` makes {year - 1}/ from {prev_year}/; then "
                   f"`tjs new-year {year}`. Nothing was created.")
    text = _read_config_text(prev / "taxjson.toml")
    kept_since = None
    # A frozen previous year (close-year copied its exports into its
    # own inputs/ and stopped naming the shared folders): the new year
    # reads the shared folders its lock recorded.
    _fz = _frozen_record(prev, prev_year)
    if _fz is None and _PL.frozen_year(prev, prev_year):
        # Frozen by its freeze note, its lock damaged or deleted
        # (backlog TJ-0158, TJ-0263): the shared folders beside the
        # year folders, as for a lock that recorded none — never the
        # note copied into a year that was not closed.
        _fz = {}
    _share_inputs = _share_tobase = None
    if _fz is not None:
        # The folders its lock recorded; a year frozen as a single
        # folder (then moved by `migrate --to-years`) recorded none:
        # the shared folders beside the year folders, when they exist.
        _share_inputs = _fz.get("inputs_dir") or (
            f"../{_PL.INPUTS}" if (top / _PL.INPUTS).is_dir() else None)
        _share_tobase = _fz.get("tobase_map") or (
            _PL.SHARED_TOBASE if (top / _PL.TOBASE_MAP).is_file()
            else None)
    try:
        new_text = _PL.new_year_text(text, prev_year, year)
        kept_since = _implicit_grant_since(_PL.parse_toml(text))
        if kept_since is not None:
            # The cutoff the previous year applied by default (its own
            # year) is kept: the new year's default would be the new
            # year, taxing again a premium written last year and closed
            # this year (GitHub #57; tax-logic CA-OPT-01).
            new_text = _PL.set_key_text(
                new_text, ("settings", "option_grant_timing_since"),
                kept_since, after="year")
        if _share_inputs or _share_tobase:
            new_text = _unfreeze_text(new_text)
            if _share_inputs:
                new_text = _PL.set_key_text(
                    new_text, ("settings", _PL.INPUTS_KEY),
                    _share_inputs, after="prior_year_record")
            if _share_tobase:
                new_text = _PL.set_key_after(
                    new_text, f"settings.{_PL.TOBASE_KEY}",
                    _share_tobase, _PL.INPUTS_KEY
                    if _share_inputs else "prior_year_record")
        new_settings = _PL.parse_toml(new_text).get("settings")
    except _PL.LayoutError as e:
        _die_input(f"{prev_year}/taxjson.toml cannot be copied: {e}",
                   "Nothing was created.")
    if not isinstance(new_settings, dict):
        new_settings = {}
    # A holdings_dir naming the previous year's own folder by way of its
    # year folder (`"../2025/snapshots"`) is the new year's own folder of
    # that name: 2025's would be a folder inside another year's project,
    # which the new year's run refuses (backlog TJ-0798).
    _hd_was = new_settings.get(_PL.HOLDINGS_KEY)
    _hd_own = _PL.own_folder_value(prev, _hd_was)
    if _hd_own != _hd_was:
        try:
            new_text = _PL.set_key_text(
                new_text, ("settings", _PL.HOLDINGS_KEY), _hd_own)
            new_settings = _PL.parse_toml(new_text).get("settings") or {}
        except _PL.LayoutError as e:
            _die_input(f"{prev_year}/taxjson.toml cannot be copied: {e}",
                       "Nothing was created.")
    # tobase.map: the interlisted pairs, one file every year reads
    # (`[settings] tobase_map`, kept by the taxjson.toml copy): no
    # per-year copy. A year from before v0.27.1 with its own copy passes
    # it on (`tjs migrate` makes the copies one file).
    # (A frozen year's own tobase.map is the shared one's copy: not a
    # legacy per-year file to pass on.)
    _legacy_tobase = (not _PL.shared_tobase(prev)
                      and (prev / _PL.TOBASE_MAP).is_file()
                      and not _share_tobase)
    # (The positions bought before the data are .tt lines of the shared
    # inputs: the same every year.)
    copied = [n for n in ("ticker.map",) + ((_PL.TOBASE_MAP,)
                                             if _legacy_tobase else ())
              if (prev / n).is_file()
              and not _os_path_lexists(folder / n)]
    try:
        # The oldest taxjson the copy runs on: last year's, raised for
        # its own layout (lib/requires) — computed here, so the copy is
        # published complete (_new_year_publish).
        from taxjson.lib.requires import raised_text as _req_raised
        new_text = _req_raised(
            new_text, own_tobase=(_legacy_tobase or (
                folder / _PL.TOBASE_MAP).is_file()))
    except (_PL.LayoutError, ValueError) as e:
        _die_input(f"{prev_year}/taxjson.toml cannot be copied: {e}",
                   "Nothing was created.")
    # Laid out last, the raised requires_taxjson in its place too.
    new_text = _templated(new_text)
    # The folder the new year reads its snapshots from: inside the year
    # (holdings/, or what holdings_dir names) it is made here and named;
    # a shared one beside the years is named, its own business (backlog
    # TJ-1083, TJ-1114).
    try:
        hold = _PL.folder_setting(folder, _PL.HOLDINGS_KEY, new_settings)
    except _PL.LayoutError:
        hold = None                 # said by the new year's run
    hold_rel: Optional[str] = _PL.HOLDINGS
    if hold is not None:
        try:
            hold_rel = hold.relative_to(folder.resolve()).as_posix()
        except ValueError:
            hold_rel = None
    make_hold = False
    if hold_rel is not None:
        _at = folder
        for _part in Path(hold_rel).parts:
            _at = _at / _part
            if _os_path_lexists(_at) and not _at.is_dir():
                _die_input(f"{_PL.shown(_at, top)} exists and is not a "
                           f"folder — move it away first.",
                           "Nothing was created.")
        make_hold = not (folder / hold_rel).is_dir()
    try:
        _new_year_publish(top, folder, new_text,
                          {n: (prev / n).read_bytes() for n in copied},
                          hold_rel if make_hold else None)
    except OSError as e:
        _die_input(f"cannot create {year}/: {e.strerror or e}",
                   "Nothing was created.")
    _yd = _shlex.quote(str(folder))
    shared = _PL.shared_inputs(folder)
    _hold_made = [f"{hold_rel}/"] if make_hold else []
    _hold_where = (f"{year}/{hold_rel}/" if hold_rel is not None
                   else f"{_PL.shown(hold, top)}/ (shared)")
    if not _details(args):
        # Essentials first (docs/output-style.md): what was made and the
        # next steps, one line each; the long form with --details.
        # (Wrapped at the width, later lines flush-left or under the
        # step's text — backlog TJ-0190.)
        for _ln in _out_wrap(
                f"Created {year}/ from {prev_year}/: "
                + ", ".join(["taxjson.toml", *copied, *_hold_made])
                + (f"; option_grant_timing_since = {kept_since} kept"
                   if kept_since is not None else ""),
                indent="", hang=""):
            print(_ln)
        if _legacy_tobase:
            _say("note", f"{year}/ got its own copy of {prev_year}'s "
                 f"tobase.map — `tjs migrate` makes it one file",
                 prog=_PROG)
        print("\nNEXT STEPS")
        for _ln in _out_wrap(
                f"1. Save the {year} exports in "
                + (f"{_PL.shown(_PL.inputs_dir(folder), top)}/<account>/ "
                   f"(shared)" if shared else f"{year}/inputs/<account>/")
                + f", positions snapshots in {_hold_where}.",
                indent="  ", hang="     "):
            print(_ln)
        print(f"  2. tjs -C {_yd} run")
        print(f"  3. tjs -C {_yd} checklist --run")
        print(f"  4. Later, in {year}/: tjs align --from {prev_year}")
        if _PL.lock_missing_frozen(prev, prev_year):
            # Closed and frozen, its lock deleted: never "not locked
            # yet" (backlog TJ-0263).
            _h, _d = _PL.lock_missing_parts(prev_year)
            _say("warning", f"{prev_year}: {_h}", _d)
        elif not (prev / "filed" / f"{prev_year}.json").is_file():
            _say("note", f"{prev_year} is not locked yet: `tjs "
                 f"close-year` in {prev_year}/ after filing it")
        return
    for _ln in _out_wrap(
            f"Created {year}/ from {prev_year}/: taxjson.toml (year {year}, "
            f"prior_year_record ../{prev_year}/filed/{prev_year}.json, the "
            f"{prev_year} [estimate] / [instalments] and accounts' "
            f"holdings commented out"
            + (f", option_grant_timing_since = {kept_since}: the cutoff "
               f"{prev_year} used by default, kept so a premium written "
               f"before {year} is not taxed again"
               if kept_since is not None else "") + ")"
            + "".join(f", {n}" for n in (*copied, *_hold_made))
            + (f"; it reads {_PL.tobase_shown(folder)} "
               f"([settings] {_PL.TOBASE_KEY})"
               if _PL.shared_tobase(folder) else "") + ".",
            indent="", hang=""):
        print(_ln)
    if _legacy_tobase:
        _say("note", f"{year}/ got its own copy of {prev_year}'s "
             f"tobase.map: the years keep one copy each",
             f"`tjs -C {_shlex.quote(str(top))} migrate` makes "
             f"them one tobase.map every year reads ([settings] "
             f"{_PL.TOBASE_KEY} = \"{_PL.SHARED_TOBASE}\").", prog=_PROG)
    _yd = _shlex.quote(str(folder))
    shared = _PL.shared_inputs(folder)
    print("\nNext:")
    for _ln in _out_wrap(
            (f"1. Save the {year} broker exports in "
             f"{_PL.shown(_PL.inputs_dir(folder), top)}/<account>/ beside "
             f"the earlier years' (keep those: the books are built from "
             f"all of them)" if shared else
             f"1. Copy the broker exports into {year}/inputs/<account>/")
            + f", and the broker's positions snapshots in {_hold_where}.",
            indent="  ", hang="     "):
        print(_ln)
    print(f"  2. Build the {year} books and see what is next:")
    print(f"       tjs -C {_yd} run")
    print(f"       tjs -C {_yd} checklist --run")
    for _ln in _out_wrap(
            f"3. Later, `tjs align --from {prev_year}` in {year}/ shows "
            f"the ticker.map lines and settings that differ from "
            f"{prev_year} and brings chosen ones over.",
            indent="  ", hang="     "):
        print(_ln)
    if _PL.lock_missing_frozen(prev, prev_year):
        # Closed and frozen, its lock deleted (backlog TJ-0263).
        _h, _d = _PL.lock_missing_parts(prev_year)
        _say("warning", f"{prev_year}: {_h}", _d)
    elif not (prev / "filed" / f"{prev_year}.json").is_file():
        _say("note", f"{prev_year} is not locked yet: after filing it, "
             f"`tjs close-year` in {prev_year}/ (keep a positions "
             f"snapshot taken at or just after the year end in "
             f"{_PL.shown(_PL.holdings_folder(prev), top)}/).")


def cmd_update_tobase_map(args: argparse.Namespace) -> None:
    """`tjs update-tobase-map [--write] [--json]`: bring the
    project's tobase.map in step with the installed interlisted master
    (lib/tobase_map, tax-logic CA-XLIST-06). Dry run by default; --write
    applies it (the previous file kept as tobase.map.bak). Canada only
    (lib/country COMMAND_COUNTRY)."""
    from taxjson.lib import tobase_map as TB
    from taxjson.lib.safe_write import write_user_file
    from taxjson.lib.ticker_map_suggest import books_symbols
    root = Path(args.dir).resolve()
    if not _PL.has_config(root):
        root = _tobase_root_year(root, args.json)
    both = _PL.tobase_both_problem(root, _soft_settings(root))
    if both:
        _die_input(both, "Nothing was written.")
    shared = _PL.shared_tobase(root)
    # Every year that reads the file this one does (its own: this year).
    readers = [root]
    if shared:
        _lay = _PL.tobase_layout(root.parent)
        readers = [root.parent / str(y) for y in
                   _lay["shared"].get(_PL.tobase_map_path(root), [])] \
            or [root]
    _yrs_text = ", ".join(p.name for p in readers)
    boundary = root.parent if shared else root
    master = TB.load_master()
    books: Set[str] = set()
    for _r in readers:
        books |= books_symbols(_r)
    tm = _PL.ticker_map_path(root)
    from taxjson.lib.cli_diag import read_text_utf8
    ticker_text = read_text_utf8(tm) if tm.is_file() else ""
    tob = TB.read_tobase(root)
    # Essentials first (docs/output-style.md): --details adds the
    # master's figures, each line's reason and the long headings.
    _det = _details(args)
    from taxjson.lib.out import act as _act
    if shared and not args.json and not _det:
        print(f"{_PL.tobase_shown(root)}: read by {_yrs_text}.")
    elif shared and not args.json:
        for _ln in _out_wrap(
                f"{_PL.tobase_shown(root)}: read by {_yrs_text} — a "
                f"change applies to each (a filed year closed with its "
                f"inputs frozen reads its own copy instead; each "
                f"year's ticker.map still wins)."):
            print(_ln)
    nsec = len(master.security)
    exch = sum(1 for e in master.security.values() if e.get("us"))
    otc = sum(1 for e in master.security.values()
              if e.get("us_otc") and not e.get("us"))
    head = (f"The installed interlisted master (generated "
            f"{master.generated}): {nsec} Canadian securities, {exch} with "
            f"a US exchange listing, {otc} with OTC listings only.")
    no_run = not books
    if tob is None:
        text = TB.render(master, shared=shared)
        n_lines = sum(1 for ln in text.splitlines()
                      if ln.split("#", 1)[0].strip())
        changes = TB.books_changes(master, books, ticker_text)
        ov = TB.compute_overlay(ticker_text, TB.parse_tobase(text), True)
        if args.json:
            _json_out({"schema_version": 1, "exists": False,
                       "master_generated": master.generated,
                       "lines": n_lines,
                       "changes_books": [{"line": g.rule, "how": how}
                                         for g, how in changes],
                       "ticker_map_decides": [{"line": r, "why": w}
                                              for r, w in ov.overridden],
                       "written": bool(args.write)})
        else:
            if _det:
                for _ln in _out_wrap(head):
                    print(_ln)
            for _ln in _out_wrap(
                    f"This project has no tobase.map yet: one would hold "
                    f"{n_lines} pair line(s)."):
                print(_ln)
            if no_run:
                for _ln in _out_wrap(
                        "The books are not built yet (`tjs run`): "
                        "what the pairs change in them cannot be shown."):
                    print(_ln)
            elif changes:
                print(f"{len(changes)} of them change these books (read "
                      f"over their full history, every year the exports "
                      f"hold):")
                for g, how in changes:
                    for _ln in _out_wrap(f"- {g.rule}: {how}", "  ",
                                         "    "):
                        print(_ln)
            elif not _det:
                print("None of them changes these books.")
            else:
                for _ln in _out_wrap(
                        "None of them changes these books (ticker.map "
                        "already pools every pair they hold, or they hold "
                        "none): they apply when you trade such a "
                        "security."):
                    print(_ln)
            if ov.overridden:
                print(f"ticker.map decides {len(ov.overridden)} pair(s) "
                      f"otherwise (ticker.map wins; reported only):")
                for r, w in ov.overridden:
                    for _ln in _out_wrap(f"- {r}" + (f" ({w})" if _det
                                                     else ""),
                                         "  ", "    "):
                        print(_ln)
        if not args.write:
            if not args.json and not _det:
                print(_act("Nothing written: create tobase.map, then "
                           "`tjs run`", "tjs update-tobase-map --write"))
            elif not args.json:
                for _ln in _out_wrap(
                        "Nothing written: `tjs update-tobase-map "
                        "--write` creates tobase.map; then `tjs run`."):
                    print(_ln)
            return
        if not tm.is_file():
            from taxjson.lib.ticker_map_format import init_template
            write_user_file(tm, init_template(), root, backup=False)
        write_user_file(TB.tobase_path(root), text, boundary, backup=False)
        if not args.json:
            print(f"Wrote {_PL.tobase_shown(root)} ({n_lines} lines). Run "
                  f"`tjs run` "
                  + (f"in each year that reads it ({_yrs_text}) "
                     if shared else "")
                  + "to rebuild the books with it.")
        _raise_requirements(root, dirs=readers, quiet=args.json)
        return
    plan = TB.plan_update(master, tob, books, ticker_text, shared=shared)
    in_books = [g for g in plan.added
                if g.keyword == "TOBASE" and ({g.a, TB.venue_alias(g.a)}
                                              & books)]
    made_map = False
    if args.write and not tm.is_file():
        # tobase.map is read beside a ticker.map only (_say_tobase_map).
        from taxjson.lib.ticker_map_format import init_template
        write_user_file(tm, init_template(), root, backup=False)
        made_map = True
    if args.json:
        _json_out({
            "schema_version": 1, "exists": True,
            "master_generated": master.generated,
            "file_master_generated": plan.old_stamp or None,
            "added": [{"line": g.rule, "figi": g.figi,
                       "section": g.section.strip("#- ")} for g in plan.added],
            "added_in_books": [g.rule for g in in_books],
            "ended": [{"line": ln.rule, "until": g.until} for ln, g in
                      plan.ended],
            "retracted": [{"line": ln.rule, "why": w}
                          for ln, w in plan.retracted],
            "retracted_but_edited": [{"line": ln.rule, "why": w}
                                     for ln, w in plan.retracted_edited],
            "edited": [ln.rule for ln in plan.edited],
            "edited_replaces": [{"master": g.rule, "yours": ln.rule}
                                for g, ln in plan.suppressed],
            "unknown_figi": [ln.rule for ln in plan.unknown],
            "opted_out": [g.rule for g in plan.opted_out],
            "removed_by_you": [g.rule for g in plan.removed_now],
            "not_tobase_lines": plan.others,
            "made_ticker_map": made_map,
            "ticker_changed": [{"old": o.rule, "new": n.rule,
                                "until": o.until, "pooled": pooled}
                               for o, n, pooled in plan.renamed],
            "ticker_map_decides": [{"line": r, "why": w}
                                   for r, w in plan.conflicts],
            "written": bool(args.write and (plan.changes or
                                            plan.old_stamp !=
                                            plan.new_stamp))})
    else:
        if _det:
            for _ln in _out_wrap(head):
                print(_ln)
        print(f"tobase.map was made from the master of "
              f"{plan.old_stamp or 'an unknown date'}"
              + ("." if _det else f"; installed: {master.generated}."))
        if plan.added:
            print(f"Added: {len(plan.added)} line(s)"
                  + (" (new interlistings or listings)" if _det else "")
                  + (f"; {len(in_books)} name a symbol of "
                                  f"these books:" if in_books else "."))
            for g in in_books:
                print(f"  + {g.rule}")
            if len(plan.added) <= 30:
                for g in plan.added:
                    if g not in in_books:
                        print(f"  + {g.rule}")
        if plan.ended:
            print(f"Ended: {len(plan.ended)} interlisting(s)"
                  + (" (annotated with `until`, kept for the years they "
                     "traded):" if _det else ":"))
            for ln, g in plan.ended:
                print(f"  ~ {ln.rule} until {g.until}")
        if plan.retracted:
            print(f"Retracted: {len(plan.retracted)} line(s)"
                  + (" the master no longer gives or no longer needs "
                     "(removed; never a line you edited):" if _det
                     else " (removed):"))
            for ln, why in plan.retracted:
                for _ln in _out_wrap(f"- {ln.rule}"
                                     + (f": {why}" if _det else ""),
                                     "  ", "    "):
                    print(_ln)
        if plan.retracted_edited and not _det:
            print(_act(f"{len(plan.retracted_edited)} line(s) you edited "
                       f"were retracted by the master: check each",
                       "tjs update-tobase-map --details"))
            for ln, why in plan.retracted_edited:
                print(f"  ? {ln.rule} ({TB.TOBASE_MAP}:{ln.lineno})")
        elif plan.retracted_edited:
            print(f"ATTENTION: {len(plan.retracted_edited)} line(s) you "
                  f"edited are lines the master RETRACTED (kept as you "
                  f"wrote them; check each):")
            for ln, why in plan.retracted_edited:
                for _ln in _out_wrap(f"! {ln.rule} ({TB.TOBASE_MAP}:"
                                     f"{ln.lineno}): {why}", "  ", "    "):
                    print(_ln)
        if plan.edited:
            print(f"Left as written: {len(plan.edited)} marked line(s) you "
                  f"edited" + (" (yours now; the master's line for the "
                               "same listing is not added beside it):"
                               if _det else ":"))
            for ln in plan.edited:
                print(f"  = {ln.rule} ({TB.TOBASE_MAP}:{ln.lineno})")
        if plan.unknown:
            print(f"Kept: {len(plan.unknown)} marked line(s) whose FIGI "
                  f"this master does not know:")
            for ln in plan.unknown:
                print(f"  ? {ln.rule} ({TB.TOBASE_MAP}:{ln.lineno})")
        if plan.removed_now:
            print(f"Removed by you: {len(plan.removed_now)} master line(s) "
                  f"you deleted" + (" (recorded as `# removed:` lines and "
                                    "never added again; delete such a "
                                    "line to have it back):" if _det
                                    else ":"))
            for g in plan.removed_now:
                print(f"  x {g.rule}")
        if plan.opted_out:
            print(f"Kept out: {len(plan.opted_out)} master line(s) you "
                  f"opted out of (`# removed:` or commented out).")
        if plan.others:
            print(f"Kept as written: {len(plan.others)} line(s) that are "
                  f"not TOBASE / DISTINCT lines" + (" (the run refuses "
                                                    "them: move them to "
                                                    "ticker.map):" if _det
                                                    else " (move them to "
                                                    "ticker.map):"))
            for r in plan.others:
                print(f"  ! {r.strip()}")
        for o, n, pooled in plan.renamed:
            old_sym, new_sym = o.a, n.a
            when = o.until if o.until and o.until != "unknown" else \
                "YYYY-MM-DD"
            if pooled:
                msg = (f"Ticker change: {old_sym} is now {new_sym} (the "
                       f"old line is kept for the years it traded). Both "
                       f"are booked as {n.b} already: nothing more to "
                       f"write.")
            else:
                msg = (f"Ticker change: {old_sym} is now {new_sym} (the "
                       f"old line is kept for the years it traded). Book "
                       f"the change as a dated event: a .tt line `RENAME "
                       f"{when} {old_sym} {new_sym}` (the first day it "
                       f"traded as {new_sym}).")
            for _ln in _out_wrap(msg, "", "  "):
                print(_ln)
        if plan.conflicts:
            print(f"ticker.map decides {len(plan.conflicts)} pair(s) "
                  f"otherwise (ticker.map wins; reported only):")
            for r, w in plan.conflicts:
                for _ln in _out_wrap(f"- {r}" + (f" ({w})" if _det else ""),
                                     "  ", "    "):
                    print(_ln)
        if not plan.changes:
            print(f"tobase.map is up to date with the installed master.")
    stale = plan.old_stamp != plan.new_stamp
    if not args.write:
        if (plan.changes or stale) and not args.json and not _det:
            print(_act("Nothing written", "tjs update-tobase-map --write"))
        elif (plan.changes or stale) and not args.json:
            print("Nothing written: `tjs update-tobase-map --write` "
                  "applies it.")
        if not tm.is_file() and not args.json:
            print("There is no ticker.map beside tobase.map (it is not "
                  "read without one): `tjs update-tobase-map --write` "
                  "makes one.")
        return
    if made_map and not args.json:
        print("Wrote an empty ticker.map (tobase.map is read beside one).")
    if not plan.changes and not stale:
        return
    bak = write_user_file(TB.tobase_path(root), plan.new_text, boundary,
                          backup=not args.no_backup)
    if not args.json:
        print(f"Wrote {_PL.tobase_shown(root)}"
              + (f" (the previous file kept as {bak.name})" if bak else "")
              + ". Run `tjs run` "
              + (f"in each year that reads it ({_yrs_text}) "
                 if shared else "")
              + "to rebuild the books with it.")
    _raise_requirements(root, dirs=readers, quiet=args.json)


def _tobase_root_year(top: Path, as_json: bool) -> Path:
    """`update-tobase-map` in the folder holding the year folders: the
    newest year that reads the tobase.map every year shares (the file is
    updated as from there). Dies when there is no such file or it is
    ambiguous: a year keeps a copy of its own, or the years name
    different files."""
    yrs = _PL.year_dirs(top)
    if not yrs:
        _die_input(f"no taxjson.toml in {top}: run it in a project's "
                   f"(year) folder")
    lay = _PL.tobase_layout(top)
    if lay["own"]:
        _die_input(f"the year folders {', '.join(str(y) for y in sorted(lay['own']))} "
                   f"keep a tobase.map of their own — which file to "
                   f"update is ambiguous here",
                   "`tjs migrate` here makes the copies one file every "
                   "year reads; or run update-tobase-map in a year folder.")
    if len(lay["shared"]) != 1:
        if not lay["shared"]:
            _die_input("no year folder reads a shared tobase.map "
                       f"([settings] {_PL.TOBASE_KEY}) — run "
                       f"update-tobase-map in a year folder")
        _die_input("the year folders read different tobase.map files: "
                   + "; ".join(f"{_PL.shown(p, top)} ({', '.join(map(str, ys))})"
                               for p, ys in sorted(lay["shared"].items())),
                   "Point each year's [settings] tobase_map at one file, "
                   "or run update-tobase-map in a year folder.")
    (_p, ys), = lay["shared"].items()
    year = max(ys)
    if not as_json:
        for _ln in _out_wrap(f"(In the folder holding the years: the shared "
                             f"{_PL.shown(_p, top)}, updated as from "
                             f"{year}/, the newest year that reads it; "
                             f"ticker.map conflicts are {year}'s.)"):
            print(_ln)
    return top / str(year)


def _align_show(c: Dict[str, Any], here: str, there: str,
                as_json: bool) -> None:
    if as_json:
        _json_out({"schema_version": 1, "here": here, "there": there,
                   "map_only_here": c["map_only_here"],
                   "map_only_there": c["map_only_there"],
                   "tobase_only_here": c.get("tobase_only_here", []),
                   "tobase_only_there": c.get("tobase_only_there", []),
                   "accounts_only_here": c.get("accounts_only_here", []),
                   "accounts_only_there": c.get("accounts_only_there", []),
                   "keys": c["keys"]})
        return
    _tob = [(f"tobase.map lines only in {there}",
             c.get("tobase_only_there") or []),
            (f"tobase.map lines only in {here}",
             c.get("tobase_only_here") or [])]
    if any(rows for _t, rows in _tob):
        for title, rows in _tob:
            if rows:
                print(f"{title}:")
                for r in rows:
                    print(f"  {r}")
        print("(tobase.map: the interlisted pairs, a copy in each year; "
              "`tjs migrate` in the folder holding the years makes "
              "them one file every year reads.)")
    _accts = _align_lone_accounts(c, here, there)
    if _accts:
        print(_accts)
    if not (c["map_only_here"] or c["map_only_there"] or c["keys"]):
        if _accts or any(rows for _t, rows in _tob):
            return
        print(f"{here} and {there}: the same ticker.map rules and "
              f"settings (the year's own keys aside).")
        return
    for title, rows in ((f"ticker.map rules only in {there}",
                         c["map_only_there"]),
                        (f"ticker.map rules only in {here}",
                         c["map_only_here"])):
        if rows:
            print(f"{title}:")
            for r in rows:
                print(f"  {r}")
    if c["keys"]:
        print(f"taxjson.toml keys set differently ({here} | {there}):")
        for k in c["keys"]:
            print(f"  {k['key']} = {_setting_text(k['here'])} | "
                  f"{_setting_text(k['there'])}")


def _align_new_config_problems(before: str, after: str,
                               root: Optional[Path] = None) -> List[str]:
    """The config-check problems (lib/config_check: settings, account
    types; with `root`, the project's folder settings as load_config
    checks them there: project_layout.setting_problems, backlog TJ-0798)
    of taxjson.toml as `after` that it does not have as `before`: a
    problem the file already has is not align's to refuse."""
    import copy
    from taxjson.lib.config_check import (account_type_problems,
                                          settings_problems)

    def _probs(text: str) -> List[str]:
        try:
            doc = _PL.parse_toml(text)
        except (_PL.LayoutError, ValueError) as e:
            return [str(e)]
        st = doc.get("settings")
        return (settings_problems(copy.deepcopy(doc))
                + account_type_problems(copy.deepcopy(doc))
                + (_PL.setting_problems(root, st) if root is not None
                   and isinstance(st, dict) else []))
    old = _probs(before)
    return [p for p in _probs(after) if p not in old]


def _align_lone_accounts(c: Dict[str, Any], here: str, there: str) -> str:
    """The accounts only one year has, one line each side (empty when
    both have the same): listed, never brought over or removed by
    `align` (backlog TJ-0349)."""
    parts = [f"[accounts] only in {yr}: {', '.join(names)}"
             for yr, names in ((there, c.get("accounts_only_there") or []),
                               (here, c.get("accounts_only_here") or []))
             if names]
    if not parts:
        return ""
    return "\n".join(parts) + ("\n(align never adds or removes an account: "
                               "copy or delete its [accounts.NAME] table "
                               "by hand.)")


def _setting_text(v: Any) -> str:
    if v is None:
        return "(not set)"
    try:
        return _PL.toml_value(v)
    except _PL.LayoutError:
        return repr(v)


def _align_filed_year(root: Path) -> Optional[int]:
    """The project's year when it is filed: its filed/<year>.json lock
    is there and was not taken before the year ended (a damaged lock
    counts: the year was closed; so does a deleted one while
    taxjson.toml still carries the freeze note, backlog TJ-0263). None
    otherwise."""
    import json as _json
    from taxjson.bin.taxjson_filed import partial_year_note
    try:
        year = int((_PL.read_config_soft(root).get("settings") or {})
                   .get("year"))
    except (TypeError, ValueError):
        return None
    lock = root / "filed" / f"{year}.json"
    if not lock.is_file():
        return year if _PL.lock_missing_frozen(root, year) else None
    try:
        doc = _json.loads(lock.read_text(encoding="utf-8"))
        if isinstance(doc, dict) and partial_year_note(doc, year):
            return None
    except (OSError, ValueError):
        pass
    return year


def cmd_align(args: argparse.Namespace) -> None:
    """`tjs align --from YEAR [--write [--all]] [--json]`: the
    ticker.map rules and taxjson.toml keys of another year's project
    that differ from this one's; --write brings chosen ones into THIS
    project (asked one by one on a terminal, or --all), backing up each
    file it changes. The other year is never written."""
    from taxjson.lib.safe_write import write_user_file
    root = Path(args.dir).resolve()
    top = _years_folder(root)
    other = top / str(args.from_year)
    if other.resolve() == root:
        _die_input(f"--from {args.from_year} is this project")
    if not _PL.has_config(other):
        _die_input(f"no project in {other}")
    try:
        c = _PL.compare(root, other)
    except _PL.LayoutError as e:
        _die_input(str(e), "Nothing was compared: fix the file, then run "
                   "`tjs align` again.")
    if not args.write:
        _align_show(c, root.name, other.name, args.json)
        return
    if args.json and not args.all:
        # Asked one by one, the questions would go to stdout with the
        # JSON (backlog TJ-0318).
        _die_input("--write --json needs --all: one by one, the "
                   "questions would mix with the JSON",
                   "Nothing was written. `tjs align --from "
                   f"{args.from_year} --json` lists the differences; "
                   f"`--write --all --json` brings them all over.")
    interactive = sys.stdin.isatty() and not args.all
    if not interactive and not args.all:
        _die_input("--write needs a terminal to ask, or --all to bring "
                   "every difference over")
    # A filed year's taxjson.toml and ticker.map are the ones its lock
    # was closed with: said before anything is asked or written (backlog
    # TJ-0103: the change left a permanent "frozen input changed" note).
    _filed = _align_filed_year(root)
    warnings: List[str] = []
    if _filed is not None and (c["map_only_there"] or any(
            not k.get("order") for k in c["keys"])):
        warnings.append(f"{_filed} is filed: --write changes the "
                        f"taxjson.toml and ticker.map filed/{_filed}.json "
                        f"was closed with")
        _say("warning", f"{_filed} is filed: --write changes the "
             f"taxjson.toml and ticker.map filed/{_filed}.json was "
             f"closed with",
             "`tjs run` here then says a frozen input changed since "
             "the close, and DRIFTED if a filed figure moves. To keep the "
             "year as filed, put the .bak copy back; for an amendment, "
             "`tjs close-year --force` once it is filed.",
             prog=_cmd_prog())

    def _ask(what: str) -> bool:
        if not interactive:
            return True
        ans = input(f"{what}? [y/N/q] ").strip().lower()
        if ans.startswith("q"):
            raise SystemExit(0)
        return ans.startswith("y")
    lines = [r for r in c["map_only_there"]
             if _ask(f"add to ticker.map: {r}")]
    # The accounts' order (GitHub #42) is shown, never rewritten;
    # requires_taxjson is never lowered or removed (lib/requires).
    from taxjson.lib import requires as _REQ
    order = next((k for k in c["keys"] if k.get("order")), None)
    keys = [k for k in c["keys"] if not k.get("order")
            and not _REQ.lowers(k["key"], k["here"], k["there"])
            and _ask(f"set {k['key']} = {_setting_text(k['there'])}")]
    done = []
    skipped: List[Tuple[str, List[str]]] = []
    # Every chosen change is made and checked in memory first; the
    # files are written only when all of them can be (GitHub #35: a
    # taxjson.toml edit that failed after ticker.map was written said
    # "nothing was written").
    tm = _PL.ticker_map_path(root)
    map_text: Optional[str] = None
    if lines:
        cur = tm.read_text(encoding="utf-8-sig") if tm.is_file() else ""
        head = (cur.rstrip("\n") + ("\n\n" if cur.strip() else "")
                + f"# from {other.name}/ticker.map (`tjs align`, "
                  f"{date_cls.today().isoformat()})\n")
        from taxjson.bin.taxjson_ticker_map import map_file_problems
        import tempfile as _tf

        def _problems_of(text: str) -> List[str]:
            with _tf.TemporaryDirectory() as _d:
                _probe = Path(_d) / "ticker.map"
                _probe.write_text(text, encoding="utf-8")
                return list(map_file_problems(_probe))
        # A line that would make the map contradict itself (with this
        # map's lines, or one brought over before it) is skipped and
        # listed; the others are brought over.
        before = set(_problems_of(cur))
        kept: List[str] = []
        for ln in lines:
            new = [p for p in _problems_of(head + "\n".join(kept + [ln])
                                           + "\n") if p not in before]
            if new:
                skipped.append((ln, new))
            else:
                kept.append(ln)
        lines = kept
        if lines:
            map_text = head + "\n".join(lines) + "\n"
    cfg = root / "taxjson.toml"
    cfg_text: Optional[str] = None
    if keys:
        text = _before = _read_config_text(cfg)
        try:
            for k in keys:
                # (set_key_text reads the result back: it must be this
                # file with exactly that key changed.)
                text = _PL.set_key_text(text, tuple(k["path"]), k["there"])
            # A setting brought over may need a newer taxjson: raised
            # for the layout features the keys added (never lowered).
            text = _REQ.raised_text(text, since=_before, own_tobase=(
                root / _PL.TOBASE_MAP).is_file())
        except (_PL.LayoutError, ValueError) as e:
            _die_input(f"{cfg.name}: {e}", "Nothing was written (neither "
                       "ticker.map nor taxjson.toml).")
        # The configuration as it would be written passes the config
        # check every command applies, or nothing is written (backlog
        # TJ-0349: align wrote a taxjson.toml the next run refused).
        new_probs = _align_new_config_problems(_before, text, root)
        if new_probs:
            _die_input(f"{cfg.name} with {other.name}'s keys would not "
                       f"pass the config check: {new_probs[0]}",
                       *[f"- {p}" for p in new_probs[1:]],
                       "Nothing was written (neither ticker.map nor "
                       "taxjson.toml): bring the keys over by hand, or "
                       "fix the setting in one year first.")
        cfg_text = text
    from taxjson.lib.safe_write import (OutsideLinkError, link_outside,
                                        write_atomic)
    for p, t in ((tm, map_text), (cfg, cfg_text)):
        tgt = link_outside(p, root) if t is not None else None
        if tgt is not None:
            _die_input(f"{p.name} is a symlink to {tgt}, outside the "
                       f"project — never written through: replace the "
                       f"link with a copy", "Nothing was written.")
    written: List[Tuple[Path, Optional[bytes]]] = []
    files: List[Dict[str, Any]] = []
    failed = cfg
    try:
        for p, t, what in ((tm, map_text, f"ticker.map: {len(lines)} "
                            f"line(s) added"),
                           (cfg, cfg_text, f"taxjson.toml: {len(keys)} "
                            f"key(s) set")):
            if t is None:
                continue
            failed = p
            real = p.resolve() if p.is_symlink() else p
            old = real.read_bytes() if real.is_file() else None
            bak = write_user_file(p, t, root)
            written.append((real, old))
            files.append({"file": p.name,
                          "backup": bak.name if bak else None})
            done.append(what + (f" (the previous file kept as {bak.name})"
                                if bak else ""))
    except (OSError, OutsideLinkError) as e:
        # Put back what was already written: all or nothing.
        for real, old in written:
            try:
                if old is None:
                    real.unlink()
                else:
                    write_atomic(real, old, keep_mode=True)
            except OSError:
                pass
        # Named from where the command was run (`tjs -C 2025 align`
        # from the folder holding the years: 2025/ticker.map), with the
        # fix, as format and format-map name it (backlog TJ-0604).
        if isinstance(e, OSError):
            from taxjson.lib.cli_diag import cannot_write
            _h, _fix = cannot_write(_config_shown(failed), e, failed)
            _die_input(_h, *([_fix] if _fix else []), "Nothing was changed.")
        _die_input(f"could not write {_config_shown(failed)}: {e}",
                   "Nothing was changed.")
    if not args.json:
        print("\n".join(done) if done else "Nothing brought over.")
        _accts = _align_lone_accounts(c, root.name, other.name)
        if _accts:
            print(_accts)
    if skipped:
        warnings.append(f"{len(skipped)} ticker.map line(s) of "
                        f"{other.name} not brought over: each contradicts "
                        f"this map's lines")
        _say("warning", f"{len(skipped)} ticker.map line(s) of "
             f"{other.name} not brought over: each contradicts this "
             f"map's lines",
             *[f"- {ln}: {'; '.join(why)}" for ln, why in skipped],
             "Decide which line is right for this year and edit "
             "ticker.map by hand.", prog=_cmd_prog())
    if order:
        # A note, not a warning: the tables' order changes no figure.
        # Trades at the same moment in two accounts book in the
        # accounts' NAME order (lib/corporate_timeline, account_tie),
        # whatever order the tables are written in (backlog TJ-0922:
        # the advice to move the tables by hand changed nothing).
        _say("note", f"the accounts are in another order in "
             f"{other.name} ({', '.join(order['there'])}) than here "
             f"({', '.join(order['here'])}) — not changed by align",
             "The order of the [accounts.NAME] tables changes no figure: "
             "trades at the same moment in two accounts book in the "
             "accounts' name order, however the tables are written.",
             prog=_cmd_prog())
    if args.json:
        # One result, after the writes: the comparison's keys (as
        # without --write) and what was done (backlog TJ-0318: prose
        # after changing the files, which json.loads refused). The
        # warnings stay on stderr too.
        _json_out(_align_write_result(
            c, root.name, other.name, files=files,
            added=lines if map_text is not None else [],
            skipped=skipped, keys=keys, order=order, filed=_filed,
            warnings=warnings))
        return
    if done:
        print("Run `tjs run` to rebuild the books with them.")


def _align_write_result(c: Dict[str, Any], here: str, there: str, *,
                        files: List[Dict[str, Any]], added: List[str],
                        skipped: List[Tuple[str, List[str]]],
                        keys: List[Dict[str, Any]],
                        order: Optional[Dict[str, Any]],
                        filed: Optional[int],
                        warnings: List[str]) -> Dict[str, Any]:
    """`tjs align --write --all --json`: the comparison
    (_align_show's keys) and the outcome — the files written (with
    their backups), the ticker.map lines added and skipped (with why),
    the keys set, the differences align never changes, the warnings."""
    from taxjson.lib import requires as _REQ
    kept = [{"key": k["key"], "path": k["path"],
             "reason": "requires_taxjson is never lowered"}
            for k in c["keys"] if not k.get("order")
            and _REQ.lowers(k["key"], k["here"], k["there"])]
    if order:
        kept.append({"key": order["key"], "path": order["path"],
                     "reason": "the accounts' order is never rewritten"})
    return {"schema_version": 1, "here": here, "there": there,
            "map_only_here": c["map_only_here"],
            "map_only_there": c["map_only_there"],
            "tobase_only_here": c.get("tobase_only_here", []),
            "tobase_only_there": c.get("tobase_only_there", []),
            "accounts_only_here": c.get("accounts_only_here", []),
            "accounts_only_there": c.get("accounts_only_there", []),
            "keys": c["keys"],
            "written": bool(files), "files": files,
            "map_lines_added": list(added),
            "map_lines_skipped": [{"line": ln, "problems": list(why)}
                                  for ln, why in skipped],
            "keys_set": [{"key": k["key"], "path": k["path"],
                          "value": k["there"]} for k in keys],
            "keys_not_changed": kept,
            "filed_year": filed,
            "warnings": list(warnings)}


# The carryover flag means what each country's return does with it
# (re-audit A2-0481: the help cited the Canadian 50% inclusion in a US
# project).
_OTHER_LOSSES_HELP = ("Prior-year capital loss carryover applied, in "
                      "FULL dollars (Canada: net capital losses, netted "
                      "against the gains before the 50%% inclusion; US: "
                      "the SHORT-term carryover — give the long-term one "
                      "with --long-term-losses)")


def _add_deduction_flags(p: argparse.ArgumentParser) -> None:
    """--deductions / --carrying-charges for the Canada estimate
    (`sum` and `estimate`); [estimate] deductions / carrying_charges
    are the config equivalents."""
    p.add_argument("--deductions", type=float, default=None,
                   metavar="AMT",
                   help="Canada: deductions from total income that the "
                        "AMT allows in full — RRSP (line 20800), FHSA, "
                        "RPP ... (default: [estimate] deductions, else 0)")
    p.add_argument("--carrying-charges", type=float, default=None,
                   metavar="AMT",
                   help="Canada: interest and carrying charges (line "
                        "22100), deducted in full from regular income "
                        "and at 50%% in the AMT base (default: "
                        "[estimate] carrying_charges, else 0)")
    p.add_argument("--long-term-losses", type=float, default=None,
                   metavar="AMT",
                   help="US: the LONG-term capital loss carryover "
                        "(Schedule D line 14), netted against long-term "
                        "gains first; --other-losses is then the "
                        "short-term one (default: [estimate] "
                        "long_term_losses, else 0)")


def _interrupt_note() -> str:
    if _CURRENT_CMD == "run":
        return ("work/ is incomplete — re-run `tjs run` before "
                "trusting any report")
    return ""


def main() -> None:
    """The `taxjson` entry point: Ctrl-C is one `interrupted` line with
    exit 130 and a closed stdout pipe a quiet exit 141, never a
    traceback (re-audit A2-0782, A2-0785); report text the terminal
    cannot encode degrades to '?' (A2-0786)."""
    from taxjson.lib.cli_diag import run_top_level
    run_top_level(lambda: (f"{_PROG} {_CURRENT_CMD}" if _CURRENT_CMD
                           else _PROG),
                  _main, interrupt_note=_interrupt_note)


def _build_parser(prog: str = "tjs"
                  ) -> Tuple[argparse.ArgumentParser, Any]:
    """The `taxjson` / `tjs` argument parser and its subparsers action.
    `prog` is the name the program was invoked as (usage lines and the
    help page show it)."""
    p = _GroupedHelpParser(
        prog=prog, description=_TOP_DESCRIPTION,
        formatter_class=_CappedHelpFormatter)
    p.add_argument("-C", "--dir", default=".", help="Project root (default: cwd)")
    try:
        from importlib.metadata import version as _pkg_version
        _ver = _pkg_version("taxjson")
    except Exception:
        _ver = "unknown"
    p.add_argument("--version", action="version",
                   version=f"taxjson {_ver}")
    sub = p.add_subparsers(dest="cmd", required=True, metavar="COMMAND")

    p_run = sub.add_parser(
        "run",
        help="Build the books and every report from inputs/",
        description="Run the full pipeline: parse every broker file in "
                    "the accounts' folders (inputs/, or [settings] "
                    "inputs_dir), convert to the base currency, apply "
                    "ticker.map, corporate actions and your elections, "
                    "compute the gains with the superficial-loss / "
                    "wash-sale pass across all your accounts, and write "
                    "reports/. Every stage is rebuilt by default; --fast "
                    "skips the stages whose inputs, config and code are "
                    "unchanged. The run ends with the broker positions "
                    "cross-check when there are positions snapshots "
                    "(holdings/, found without a setting). "
                    "Commands chain: `tjs run sum`.")
    p_run.add_argument("--account", help="Process only one account")
    p_run.add_argument("--fast", action="store_true",
                       help="Incremental run: reuse cached stage "
                            "outputs; stages whose inputs, config and "
                            "code are unchanged are skipped")
    p_run.add_argument("--no-input", action="store_true",
                       help="Never prompt (scripts/CI): unresolved corp-action "
                            "elections write work/pending_elections.json "
                            "and exit 3 — resolve with `tjs elect "
                            "... --set`, then re-run")
    p_run.add_argument("--strict", action="store_true",
                       help="Promote per-account validation ERRORs "
                            "(oversold positions, malformed rows) to "
                            "fatal — the run stops instead of "
                            "publishing reports with a DIAGNOSTICS "
                            "banner. Recommended for CI/cron")
    p_run.set_defaults(func=cmd_run)

    p_elect = sub.add_parser(
        "elect", help="Review or set corporate-action tax elections",
        description="List the corporate-action events in the books "
                    "(mergers, spin-offs, reorganisations) with the tax "
                    "election recorded for each; redo or reset one, show "
                    "what a --no-input run left pending, or write one "
                    "non-interactively with --set EVENT_ID=ELECTION.")
    p_elect.add_argument("account", nargs="?",
                         help="Account to act on (omit to list all accounts)")
    p_elect.add_argument("--redo", action="store_true",
                         help="Clear the election(s) and re-prompt now")
    p_elect.add_argument("--reset", action="store_true",
                         help="Clear the election(s) without re-prompting "
                              "(next `tjs run` asks again)")
    p_elect.add_argument("--event", metavar="ID",
                         help="Scope --redo/--reset to one event id "
                              "(from the list); default is all")
    p_elect.add_argument("--set", metavar="EVENT_ID=ELECTION",
                         action="append",
                         help="Write one election non-interactively "
                              "(headless/CI bootstrap), e.g. --set "
                              "20250317-abg-abh-1a2b=rollover_s_85_1_5 "
                              "(Canada) or =reorg_368 (USA); the "
                              "event's own choices are listed by "
                              "`tjs elect ACCOUNT`")
    p_elect.add_argument("--hint", action="append", metavar="KEY=VALUE",
                         help="Hint for --set (repeatable), e.g. "
                              "--hint fmv_per_share=12.5")
    p_elect.add_argument("--pending", action="store_true",
                         help="Show elections a --no-input/headless run "
                              "left unresolved (work/pending_elections"
                              ".json), with ready-to-copy --set lines")
    p_elect.add_argument("--json", action="store_true",
                         help="With --pending: emit the raw pending "
                              "document")
    p_elect.set_defaults(func=cmd_elect)

    p_mig = sub.add_parser(
        "migrate",
        help="Move an older project's files into the new layout",
        description="Move an old project's yf_ticker.map, "
             "crypto_ticker.map, ticker_extraction_overrides.txt, "
             "t1135.map, amt_carryover.txt, claimed_losses.txt, "
             "capital_gains_dividends.map and distributions.map into "
             "ticker.map / taxjson.toml (appended; each old file is "
             "renamed <name>.migrated). Every other command stops while "
             "one of those files is present. A leftover tv_exchange.map "
             "(the removed TradingView export) is only renamed. In a "
             "multi-year project (the folder holding the years, or a "
             "year folder) the years' tobase.map copies become one "
             "tobase.map beside the year folders that every year reads "
             "([settings] tobase_map = \"../tobase.map\"; each copy kept "
             "as tobase.map.bak).")
    p_mig.add_argument("--dry-run", action="store_true",
                       help="Show what would be appended and moved; "
                            "write nothing")
    p_mig.add_argument("--write", action="store_true",
                       help="missing_history.json of year folders that "
                            "disagree: write anyway, each entry as the "
                            "newest year listing it sizes it; tobase.map "
                            "copies that differ: keep the newest year's "
                            "as the one file")
    p_mig.add_argument("--to-years", action="store_true",
                       help="Turn this single-folder project into one "
                            "folder of exports for every year: inputs/ "
                            "stays here, shared, and the project moves "
                            "into the YYYY/ folder of its year "
                            "(docs/getting-started.md)")
    p_mig.set_defaults(func=cmd_migrate)

